        "https://raw.githubusercontent.com/Jimmyzxk/DNS-Alice-Unlock/refs/heads/main/dns-unlock.sh"|\
        "https://raw.githubusercontent.com/hotyue/IP-Sentinel/main/core/install.sh")
            echo "$(localized_text "项目内置硬编码外部脚本源" "Project built-in hardcoded external script source" "Встроенный в проект жестко закодированный внешний источник сценария")"
            return 0
            ;;
    esac
    return 1
}

run_remote_script() {
    local desc="$1"
    local url="$2"
    shift 2
    local tmp_file rc trusted_source
    echo -e "${CYAN}▶ ${desc}${PLAIN}"
    echo -e "$(localized_text "${YELLOW}脚本来源：${url}${PLAIN}" "${YELLOW}Script source: ${url}${PLAIN}" "${YELLOW}Источник сценария : ${url}${PLAIN}")"
    if trusted_source=$(is_trusted_remote_script_url "$url"); then
        echo -e "$(localized_text "${GREEN}内置已知来源：${trusted_source}${PLAIN}" "${GREEN}Built-in Known source: ${trusted_source}${PLAIN}" "${GREEN}встроенный Известный источник: ${trusted_source}${PLAIN}")"
    else
        trusted_source=""
        echo -e "$(localized_text "${RED}⚠️ 非内置已知来源：该 URL 不在 VPS-Optimize 内置远程脚本白名单内。${PLAIN}" "${RED}⚠️ Non-built-in known sources: The URL is not in the VPS-Optimize built-in remote script whitelist.${PLAIN}" "${RED}⚠️ Невстроенные известные источники: URL-адрес отсутствует в белом списке встроенных удаленных сценариев VPS-Optimize.${PLAIN}")"
    fi
    if [[ "$url" != https://* && "$url" != file://* ]]; then
        echo -e "$(localized_text "${RED}❌ 该来源不是 HTTPS，已拒绝下载和执行。${PLAIN}" "${RED}❌ The source is not HTTPS and downloading and execution have been refused.${PLAIN}" "${RED}❌ Источник не HTTPS, загрузка и выполнение отклонены.${PLAIN}")"
        return 1
    fi

    tmp_file=$(mktemp /tmp/vps-remote.XXXXXX.sh) || {
        echo -e "$(localized_text "${RED}❌ 临时文件创建失败，已取消执行。${PLAIN}" "${RED}❌ Temporary file creation failed and execution has been cancelled.${PLAIN}" "${RED}❌ Не удалось создать временный файл, и выполнение было отменено.${PLAIN}")"
        return 1
    }
    if ! download_remote_script "$url" "$tmp_file"; then
        rm -f "$tmp_file"
        echo -e "$(localized_text "${RED}❌ 下载失败，请检查网络或脚本来源。${PLAIN}" "${RED}❌ Download failed, please check the network or script source.${PLAIN}" "${RED}❌ Не удалось загрузить, проверьте сеть или источник сценария.${PLAIN}")"
        return 1
    fi
    if ! bash -n "$tmp_file" >/dev/null 2>&1; then
        echo -e "$(localized_text "${RED}❌ 远程脚本未通过 Bash 语法检查，已中止执行。${PLAIN}" "${RED}❌ The remote script failed the Bash syntax check and execution was aborted.${PLAIN}" "${RED}❌ Удаленный сценарий не прошел проверку синтаксиса Bash, и выполнение было прервано.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}已保留下载文件用于排查：${tmp_file}${PLAIN}" "${YELLOW}Has reserved the download file for troubleshooting: ${tmp_file}${PLAIN}" "${YELLOW}зарезервировал файл загрузки для устранения неполадок: ${tmp_file}.${PLAIN}")"
        return 1
    fi

    chmod +x "$tmp_file"
    bash "$tmp_file" "$@"
    rc=$?
    rm -f "$tmp_file"
    return "$rc"
}

pause_after_external_script() {
    local prompt="$(localized_text "${1:-按回车键继续...}" "${1:-按回车键继续...}" "${1:-按回车键继续...}")"
    local junk

    if [[ -r /dev/tty ]]; then
        while IFS= read -r -s -n 1 -t 0.05 junk < /dev/tty; do :; done
        read -r -p "$prompt" junk < /dev/tty
    else
        read -r -p "$prompt" junk
    fi
}

install_acme_sh() {
    local acme_email="$1"
    local tmp_file rc
    tmp_file=$(mktemp /tmp/vps-acme.XXXXXX.sh)
    echo -e "$(localized_text "${CYAN}▶ 正在安装 acme.sh...${PLAIN}" "${CYAN}▶ Installing acme.sh...${PLAIN}" "${CYAN}▶ Установка acme.sh...${PLAIN}")"
    if ! download_remote_script "https://get.acme.sh" "$tmp_file"; then
        rm -f "$tmp_file"
        echo -e "$(localized_text "${RED}❌ acme.sh 安装脚本下载失败。${PLAIN}" "${RED}❌ acme.sh The installation script download failed.${PLAIN}" "${RED}❌ acme.sh Не удалось загрузить сценарий установки.${PLAIN}")"
        return 1
    fi
    if ! sh -n "$tmp_file" >/dev/null 2>&1; then
        echo -e "$(localized_text "${RED}❌ acme.sh 安装脚本未通过 sh 语法检查，已中止。${PLAIN}" "${RED}❌ acme.sh The installation script failed the sh syntax check and was aborted.${PLAIN}" "${RED}❌ acme.sh Сценарий установки не прошел проверку синтаксиса sh и был прерван.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}已保留下载文件用于排查：${tmp_file}${PLAIN}" "${YELLOW}Has reserved the download file for troubleshooting: ${tmp_file}${PLAIN}" "${YELLOW}зарезервировал файл загрузки для устранения неполадок: ${tmp_file}.${PLAIN}")"
        return 1
    fi
    sh "$tmp_file" "email=${acme_email}" >/dev/null 2>&1
    rc=$?
    rm -f "$tmp_file"
    return "$rc"
}

# ---------------------------------------------------------
# Module: language.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Persistent language selection and localized text helpers.

VPSO_LANGUAGE_CONFIG="${VPSO_LANGUAGE_CONFIG:-/etc/vps-optimize/language.conf}"
VPSO_LANGUAGE="zh"
VPSO_LANGUAGE_CONFIGURED=0

normalize_ui_language() {
    case "${1,,}" in
        en|en_us|en-us|english) printf 'en' ;;
        ru|ru_ru|ru-ru|russian|русский) printf 'ru' ;;
        zh|zh_cn|zh-cn|chinese|中文|简体中文) printf 'zh' ;;
        *) return 1 ;;
    esac
}

load_ui_language() {
    local configured="${VPSO_LANG:-}"
    VPSO_LANGUAGE_CONFIGURED=0
    if [[ -z "$configured" && -r "$VPSO_LANGUAGE_CONFIG" ]]; then
        configured=$(sed -n 's/^[[:space:]]*LANGUAGE[[:space:]]*=[[:space:]]*//p' "$VPSO_LANGUAGE_CONFIG" | tail -n 1)
        configured="${configured%\"}"
        configured="${configured#\"}"
        configured="${configured%\'}"
        configured="${configured#\'}"
    fi
    if VPSO_LANGUAGE=$(normalize_ui_language "$configured"); then
        VPSO_LANGUAGE_CONFIGURED=1
    else
        VPSO_LANGUAGE="zh"
    fi
}

save_ui_language() {
    local language config_dir tmp_file
    language=$(normalize_ui_language "$1") || return 1
    config_dir=$(dirname "$VPSO_LANGUAGE_CONFIG")
    mkdir -p "$config_dir" || return 1
    tmp_file=$(mktemp "${config_dir}/.language.conf.XXXXXX") || return 1
    if ! printf 'LANGUAGE=%s\n' "$language" > "$tmp_file"; then
        rm -f "$tmp_file"
        return 1
    fi
    chmod 600 "$tmp_file" 2>/dev/null || true
    if ! mv -f "$tmp_file" "$VPSO_LANGUAGE_CONFIG"; then
        rm -f "$tmp_file"
        return 1
    fi
    VPSO_LANGUAGE="$language"
    VPSO_LANGUAGE_CONFIGURED=1
}

localized_text() {
    local zh="$1"
    local en="$2"
    local ru="${3:-$en}"
    case "$VPSO_LANGUAGE" in
        en) printf '%s' "$en" ;;
        ru) printf '%s' "$ru" ;;
        *) printf '%s' "$zh" ;;
    esac
}

localized_echo() {
    echo -e "$(localized_text "$@")"
}

select_ui_language() {
    local mode="${1:-menu}"
    local choice target prompt

    while true; do
        echo -e "${CYAN}Select interface language:${PLAIN}"
        echo "  1. English"
        echo "  2. 简体中文 (Simplified Chinese)"
        echo "  3. Русский (Russian)"
        [[ "$mode" == "initial" ]] || echo "  0. Cancel"
        if [[ "$mode" == "initial" ]]; then
            prompt="Enter 1-3 [default: 1]: "
        else
            prompt="Enter 0-3: "
        fi
        if ! read -r -p "$prompt" choice; then
            return 1
        fi
        choice="${choice:-1}"
        case "${choice,,}" in
            1|en|english) target="en" ;;
            2|zh|chinese|中文|简体中文) target="zh" ;;
            3|ru|russian|русский) target="ru" ;;
            0|q|quit|cancel)
                [[ "$mode" == "initial" ]] || return 0
                echo -e "${RED}Please select a language before continuing.${PLAIN}"
                continue
                ;;
            *)
                echo -e "${RED}Invalid selection. Enter a number from 1 to 3.${PLAIN}"
                continue
                ;;
        esac

        if ! save_ui_language "$target"; then
            echo -e "${RED}Unable to save the language setting: ${VPSO_LANGUAGE_CONFIG}${PLAIN}"
            return 1
        fi
        case "$target" in
            zh) echo -e "${GREEN}界面语言已切换为简体中文。${PLAIN}" ;;
            en) echo -e "${GREEN}Interface language changed to English.${PLAIN}" ;;
            ru) echo -e "${GREEN}Язык интерфейса изменён на русский.${PLAIN}" ;;
        esac
        return 0
    done
}

prompt_initial_ui_language() {
    [[ "$VPSO_LANGUAGE_CONFIGURED" == "1" ]] && return 0
    [[ -t 0 ]] || return 0
    select_ui_language initial
}

toggle_ui_language() {
    select_ui_language menu
}

# ---------------------------------------------------------
# Module: ui.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# UI output and confirmation helpers.

print_breadcrumb() {
    echo -e "${CYAN}VPS-Optimize > $*${PLAIN}"
}

pause_return() {
    local default_prompt
    if declare -F localized_text >/dev/null 2>&1; then
        default_prompt="$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    else
        default_prompt="$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    fi
    local prompt="${1:-$default_prompt}"
    read -n 1 -s -r -p "$prompt"
    echo ""
}

print_action_summary() {
    local level="$1"
    local title="$2"
    local impact="$3"
    local rollback="$4"
    local advice="${5:-}"
    local snapshot_advice="${6:-}"

    if [[ -z "$snapshot_advice" ]]; then
        if [[ "$level" == "danger" ]]; then
            snapshot_advice="$(localized_text \
                "建议先创建 VPS 快照，或确认云厂商快照/救援控制台可用。" \
                "Create a VPS snapshot first, or confirm that snapshot or rescue-console access is available." \
                "Сначала создайте снимок VPS или убедитесь, что доступны снимок либо аварийная консоль.")"
        else
            snapshot_advice="$(localized_text \
                "确认上方参数无误。" \
                "Verify the values above." \
                "Проверьте указанные выше значения.")"
        fi
    fi

    if [[ "$level" == "danger" ]]; then
        echo -e "$(localized_text "${RED}⚠️ 高风险操作：${title}${PLAIN}" "${RED}⚠️ High-risk operation: ${title}${PLAIN}" "${RED}⚠️ Операция высокого риска: ${title}${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 操作确认：${title}${PLAIN}" "${YELLOW}⚠️ Confirm operation: ${title}${PLAIN}" "${YELLOW}⚠️ Подтвердите операцию: ${title}${PLAIN}")"
    fi
    echo -e "$(localized_text "${YELLOW}将修改：${PLAIN}${impact}" "${YELLOW}Changes:${PLAIN} ${impact}" "${YELLOW}Изменения:${PLAIN} ${impact}")"
    echo -e "$(localized_text "${BLUE}恢复方式：${PLAIN}${rollback}" "${BLUE}Recovery:${PLAIN} ${rollback}" "${BLUE}Восстановление:${PLAIN} ${rollback}")"
    echo -e "$(localized_text "${CYAN}操作前：${PLAIN}${snapshot_advice}" "${CYAN}Before continuing:${PLAIN} ${snapshot_advice}" "${CYAN}Перед продолжением:${PLAIN} ${snapshot_advice}")"
    [[ -n "$advice" ]] && echo -e "$(localized_text "${CYAN}注意：${PLAIN}${advice}" "${CYAN}Note:${PLAIN} ${advice}" "${CYAN}Важно:${PLAIN} ${advice}")"
}

confirm_default_yes() {
    local confirm
    while true; do
        read_trimmed confirm "$(localized_text "确认执行？(Y/n，默认 Y): " "Proceed? (Y/n, default Y): " "Продолжить? (Y/n, по умолчанию Y): ")" || return 1
        case "$(trim_input "$confirm" | tr '[:upper:]' '[:lower:]')" in
            y|yes) return 0 ;;
            n|no) return 1 ;;
            *)
                echo -e "$(localized_text "${YELLOW}请输入 Y 或 n。${PLAIN}" "${YELLOW}Enter Y or n.${PLAIN}" "${YELLOW}Введите Y или n.${PLAIN}")"
                ;;
        esac
    done
}

confirm_default_no() {
    local prompt="${1:-$(localized_text "确认继续？(y/N): " "Continue? (y/N): " "Продолжить? (y/N): ")}"
    local confirm
    while true; do
        read_trimmed confirm "$prompt" || return 1
        case "$(trim_input "$confirm" | tr '[:upper:]' '[:lower:]')" in
            y|yes) return 0 ;;
            n|no) return 1 ;;
            "")
                echo -e "$(localized_text "${GREEN}尚未执行；已填写参数仍保留。输入 y 继续，输入 n 取消。${PLAIN}" "${GREEN}Not executed; entered values are preserved. Enter y to continue or n to cancel.${PLAIN}" "${GREEN}Операция не запущена; введённые значения сохранены. Введите y для продолжения или n для отмены.${PLAIN}")"
                ;;
            *)
                echo -e "$(localized_text "${YELLOW}请输入 y 或 N。${PLAIN}" "${YELLOW}Enter y or N.${PLAIN}" "${YELLOW}Введите y или N.${PLAIN}")"
                ;;
        esac
    done
}

confirm_danger() {
    local title="$1"
    local impact="$2"
    local rollback="$3"
    local advice="${4:-}"
    local snapshot_advice="${5:-}"
    local confirm confirm_word

    print_action_summary "danger" "$title" "$impact" "$rollback" "$advice" "$snapshot_advice"
    echo -e "$(localized_text \
        "${BOLD}${GREEN}默认 N：${PLAIN}直接回车仅停留在本页，已填写参数不会丢失。" \
        "${BOLD}${GREEN}Default N:${PLAIN} Enter keeps this page open and preserves the values you entered." \
        "${BOLD}${GREEN}По умолчанию N:${PLAIN} Enter оставляет эту страницу открытой и сохраняет введённые значения.")"

    while true; do
        read_trimmed confirm "$(localized_text "继续执行？(y/N): " "Continue? (y/N): " "Продолжить? (y/N): ")" || return 1
        case "$(trim_input "$confirm" | tr '[:upper:]' '[:lower:]')" in
            "")
                echo -e "$(localized_text "${GREEN}尚未执行；参数已保留。输入 y 继续，输入 n 取消。${PLAIN}" "${GREEN}Not executed; values are preserved. Enter y to continue or n to cancel.${PLAIN}" "${GREEN}Операция не запущена; значения сохранены. Введите y для продолжения или n для отмены.${PLAIN}")"
                ;;
            n|no) return 1 ;;
            y|yes)
                while true; do
                    read_trimmed confirm_word "$(localized_text "再次确认：输入 YES 执行，直接回车返回上一步: " "Final confirmation: enter YES to proceed, or press Enter to go back: " "Повторное подтверждение: введите YES для запуска или нажмите Enter, чтобы вернуться: ")" || return 1
                    case "$(trim_input "$confirm_word" | tr '[:lower:]' '[:upper:]')" in
                        YES) return 0 ;;
                        "")
                            echo -e "$(localized_text "${GREEN}已返回上一步；参数仍保留。${PLAIN}" "${GREEN}Back to the previous confirmation; values are still preserved.${PLAIN}" "${GREEN}Возврат к предыдущему подтверждению; значения сохранены.${PLAIN}")"
                            break
                            ;;
                        *)
                            echo -e "$(localized_text "${YELLOW}确认词不匹配，操作尚未执行。请输入 YES，或直接回车返回上一步。${PLAIN}" "${YELLOW}Confirmation did not match; nothing was executed. Enter YES, or press Enter to go back.${PLAIN}" "${YELLOW}Подтверждение не совпало; операция не запущена. Введите YES или нажмите Enter, чтобы вернуться.${PLAIN}")"
                            ;;
                    esac
                done
                ;;
            *)
                echo -e "$(localized_text "${YELLOW}请输入 y 或 N。${PLAIN}" "${YELLOW}Enter y or N.${PLAIN}" "${YELLOW}Введите y или N.${PLAIN}")"
                ;;
        esac
    done

}

action_needs_safe_default() {
    local title
    local impact
    title=$(printf '%s' "${1:-}" | tr '[:upper:]' '[:lower:]')
    impact=$(printf '%s' "${2:-}" | tr '[:upper:]' '[:lower:]')

    case "$title $impact" in
        *安装*|*部署*|*install*|*deploy*|*установ*|*развер*)
            return 0
            ;;
    esac
    case "$title" in
        *删除*|*清理*|*清空*|*隔离*|*卸载*|*重装*|*重启*|*关机*|*停机*|*恢复*|*回滚*|*停止*|*停用*|*关闭*|*覆盖*|*白名单*|*防火墙*|*监听公网*|*重置*|*切换*|*迁移*|*应用*|*重签*|*公网\ 443*|*delete*|*remove*|*prune*|*clean*|*clear*|*quarantine*|*isolate*|*uninstall*|*reinstall*|*restart*|*reboot*|*shutdown*|*poweroff*|*restore*|*rollback*|*stop*|*disable*|*overwrite*|*whitelist*|*allowlist*|*firewall*|*publicly*|*public\ port\ 443*|*reset*|*switch*|*migrate*|*apply*|*re-sign*|*удал*|*Удал*|*очист*|*Очист*|*карантин*|*Карантин*|*изолир*|*Изолир*|*переустанов*|*Переустанов*|*перезап*|*Перезап*|*перезагруз*|*Перезагруз*|*выключ*|*Выключ*|*восстанов*|*Восстанов*|*откат*|*Откат*|*останов*|*Останов*|*отключ*|*Отключ*|*сброс*|*Сброс*|*переключ*|*Переключ*|*мигр*|*Мигр*|*примен*|*Примен*|*переподп*|*Переподп*|*белый\ список*|*Белый\ список*|*список\ разреш*|*Список\ разреш*|*брандмауэр*|*Брандмауэр*|*публичн*443*|*Публичн*443*)
            return 0
            ;;
    esac
    case "$impact" in
        *删除*|*清空*|*关机*|*重启*|*覆盖*|*公网\ 443*|*erase*|*delete*|*shutdown*|*poweroff*|*restart*|*overwrite*|*public\ port\ 443*|*удал*|*Удал*|*очист*|*Очист*|*перезагруз*|*Перезагруз*|*выключ*|*Выключ*|*перезапис*|*Перезапис*|*публичн*443*|*Публичн*443*)
            return 0
            ;;
    esac
    return 1
}

confirm_risk_action() {
    if action_needs_safe_default "$1" "$2"; then
        confirm_danger "$@"
        return $?
    fi
    print_action_summary "risk" "$1" "$2" "$3" "${4:-}" "${5:-}"
    confirm_default_yes
}

terminal_text_width() {
    local text="$1"
    local width

    width=$(printf '%s\n' "$text" | LC_ALL=C.UTF-8 wc -L 2>/dev/null) \
        || width=$(printf '%s\n' "$text" | LC_ALL=C.utf8 wc -L 2>/dev/null) \
        || width=$(printf '%s\n' "$text" | wc -L 2>/dev/null) \
        || width=${#text}
    [[ "$width" =~ ^[[:space:]]*[0-9]+[[:space:]]*$ ]] || width=${#text}
    printf '%d' "$width"
}

print_menu_item() {
    local number="$1"
    local title="$2"
    local description="$3"
    local title_column="${4:-28}"
    local number_color="${5:-$GREEN}"
    local description_color="${6:-$YELLOW}"
    local title_color="${7:-}"
    local title_width padding

    title_width=$(terminal_text_width "$title")
    padding=$((title_column - title_width + 2))
    (( padding < 2 )) && padding=2
    printf ' %b%2s.%b %b%s%b%*s%b(%s)%b\n' \
        "$number_color" "$number" "$PLAIN" "$title_color" "$title" "$PLAIN" \
        "$padding" '' "$description_color" "$description" "$PLAIN"
}

render_menu() {
    local items_name="$1"
    local -n menu_items="$items_name"
    local item number title description handler risk title_width
    local title_column=0

    for item in "${menu_items[@]}"; do
        IFS='|' read -r number title description handler risk <<< "$item"
        title_width=$(terminal_text_width "$title")
        (( title_width > title_column )) && title_column=$title_width
    done
    for item in "${menu_items[@]}"; do
        IFS='|' read -r number title description handler risk <<< "$item"
        print_menu_item "$number" "$title" "$description" "$title_column" "$GREEN" "$YELLOW" "$GREEN"
    done
}

dispatch_menu_choice() {
    local choice="$1"
    local items_name="$2"
    local -n menu_items="$items_name"
    local item number title description handler risk

    for item in "${menu_items[@]}"; do
        IFS='|' read -r number title description handler risk <<< "$item"
        if [[ "$choice" == "$number" ]]; then
            if [[ -n "$risk" ]] && declare -F confirm_menu_risk >/dev/null; then
                confirm_menu_risk "$risk" || return 0
            fi
            "$handler"
            return 0
        fi
    done
    return 1
}

# ---------------------------------------------------------
# Module: input.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Input normalization and prompt helpers.

trim_input() {
    local value="$*"
    value="${value//$'\r'/}"
    value="${value//$'\xc2\xa0'/ }"
    value="${value//$'\xe3\x80\x80'/ }"
    value="${value#"${value%%[![:space:]]*}"}"
    value="${value%"${value##*[![:space:]]}"}"
    printf '%s' "$value"
}

normalize_ascii_digits() {
    local value="$1"
    value="${value//０/0}"
    value="${value//１/1}"
    value="${value//２/2}"
    value="${value//３/3}"
    value="${value//４/4}"
    value="${value//５/5}"
    value="${value//６/6}"
    value="${value//７/7}"
    value="${value//８/8}"
    value="${value//９/9}"
    printf '%s' "$value"
}

normalize_menu_choice_input() {
    local value lower
    value="$(normalize_ascii_digits "$(trim_input "$1")")"
    case "$value" in
        [0-9].|[0-9][0-9].) value="${value%.}" ;;
        [0-9]\)|[0-9][0-9]\)) value="${value%)}" ;;
        [0-9]、|[0-9][0-9]、) value="${value%、}" ;;
        [0-9]．|[0-9][0-9]．) value="${value%．}" ;;
        [0-9]）|[0-9][0-9]）) value="${value%）}" ;;
    esac
    lower=$(echo "$value" | tr '[:upper:]' '[:lower:]')
    case "$lower" in
        q) printf '0' ;;
        *) printf '%s' "$value" ;;
    esac
}

colorize_confirmation_prompt() {
    local prompt="$1"
    local bold="${BOLD:-}"
    local green="${GREEN:-}"
    local red="${RED:-}"
    local plain="${PLAIN:-}"
    prompt="${prompt//Y\/n/${bold}${green}Y${plain}\/${red}n${plain}}"
    prompt="${prompt//y\/N/${red}y${plain}\/${bold}${green}N${plain}}"
    prompt="${prompt//Да\/Нет/${bold}${green}Y${plain}\/${red}n${plain}}"
    prompt="${prompt//Да\/нет/${bold}${green}Y${plain}\/${red}n${plain}}"
    printf '%b' "$prompt"
}

read_trimmed() {
    local __target="$1"
    local prompt="${2:-}"
    local display_prompt
    local __raw_input=""
    local read_rc=0
    display_prompt=$(colorize_confirmation_prompt "$prompt")
    read -r -p "$display_prompt" __raw_input || read_rc=$?
    if (( read_rc == 0 )) && [[ -z "$(trim_input "$__raw_input")" ]]; then
        case "$prompt" in
            *"(Y/n"*|*"[Y/n]"*|*"(Да/Нет"*|*"(Да/нет"*|*"直接回车继续"*) __raw_input="y" ;;
        esac
    fi
    case "$__target" in
        mode_choice|action_choice)
            printf -v "$__target" '%s' "$(trim_input "$__raw_input")"
            ;;
        p_choice|final_p|*port*)
            if declare -F normalize_port_input >/dev/null 2>&1; then
                printf -v "$__target" '%s' "$(normalize_port_input "$__raw_input")"
            else
                printf -v "$__target" '%s' "$(trim_input "$__raw_input")"
            fi
            ;;
        *choice*|action|c|t)
            printf -v "$__target" '%s' "$(normalize_menu_choice_input "$__raw_input")"
            ;;
        ip|*_ip|*addr*)
            if declare -F normalize_ip_input >/dev/null 2>&1; then
                printf -v "$__target" '%s' "$(normalize_ip_input "$__raw_input")"
            else
                printf -v "$__target" '%s' "$(trim_input "$__raw_input")"
            fi
            ;;
        *)
            printf -v "$__target" '%s' "$(trim_input "$__raw_input")"
            ;;
    esac
    return "$read_rc"
}

read_secret_trimmed() {
    local __target="$1"
    local prompt="${2:-}"
    local __raw_input
    read -r -s -p "$prompt" __raw_input
    echo ""
    printf -v "$__target" '%s' "$(trim_input "$__raw_input")"
}

ask_with_default() {
    local prompt="$1"
    local default_value="$2"
    local input
    local value
    read_trimmed input "$(localized_text "${prompt} (默认: ${default_value}): " "${prompt} (default: ${default_value}):" "${prompt} (по умолчанию: ${default_value}):")"
    value="${input:-$default_value}"
    case "$prompt" in
        *路径*|*[Pp]ath*|*путь*|*Путь*)
            ;;
        *端口*|*[Pp][Oo][Rr][Tt]*|*порт*|*Порт*)
            if declare -F normalize_port_input >/dev/null 2>&1; then
                value="$(normalize_port_input "$value")"
            fi
            ;;
        *监听地址*|*[Ll]isten*address*|*адрес*прослуш*|*Адрес*прослуш*)
            if declare -F normalize_ip_input >/dev/null 2>&1; then
                value="$(normalize_ip_input "$value")"
            fi
            ;;
    esac
    echo "$value"
}

split_csv_to_array() {
    local input="$1"
    local -n out_array=$2
    local idx cleaned
    input="${input//，/,}"
    input="${input//、/,}"
    input="${input//；/,}"
    input="${input//;/,}"
    input="${input//$'\r'/,}"
    input="${input//$'\n'/,}"
    input="${input//$'\t'/,}"
    input="${input// /,}"
    out_array=()
    local raw_array=()
    IFS=',' read -ra raw_array <<< "$input"
    for idx in "${!raw_array[@]}"; do
        cleaned=$(echo "${raw_array[$idx]}" | tr '[:upper:]' '[:lower:]' | tr -d '[:space:]')
        [[ -n "$cleaned" ]] && out_array+=("$cleaned")
    done
}

split_pipe_to_array() {
    local input="$1"
    local -n out_array=$2
    local item cleaned
    local raw_array=()
    out_array=()
    IFS='|' read -ra raw_array <<< "$input"
    for item in "${raw_array[@]}"; do
        cleaned=$(trim_input "$item")
        [[ -n "$cleaned" ]] && out_array+=("$cleaned")
    done
}

# ---------------------------------------------------------
# Module: validate.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Validation and normalization helpers.

normalize_domain_input() {
    local domain
    domain="$(trim_input "$1")"
    if declare -F normalize_ascii_digits >/dev/null 2>&1; then
        domain="$(normalize_ascii_digits "$domain")"
    fi
    domain="${domain//。/.}"
    domain="${domain//．/.}"
    domain="${domain//｡/.}"
    domain="${domain//：/:}"
    domain=$(printf '%s' "$domain" | sed 's#／#/#g')
    domain=$(echo "$domain" | tr '[:upper:]' '[:lower:]')
    domain="${domain#http://}"
    domain="${domain#https://}"
    domain="${domain%%\?*}"
    domain="${domain%%？*}"
    domain="${domain%%#*}"
    domain="${domain%%＃*}"
    domain="${domain%%/*}"
    domain="${domain%%:*}"
    domain=$(echo "$domain" | tr -d '[:space:]')
    while [[ "$domain" == *. ]]; do
        domain="${domain%.}"
    done
    printf '%s' "$domain"
}

is_valid_hostname() {
    local name="$1"
    local label
    [[ -n "$name" && ${#name} -le 253 ]] || return 1
    [[ "$name" != .* && "$name" != *. ]] || return 1
    [[ "$name" =~ ^[A-Za-z0-9.-]+$ ]] || return 1
    IFS='.' read -ra labels <<< "$name"
    for label in "${labels[@]}"; do
        [[ -n "$label" && ${#label} -le 63 ]] || return 1
        [[ "$label" =~ ^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$ ]] || return 1
    done
    return 0
}

is_valid_domain() {
    local domain="$1"
    echo "$domain" | grep -Eq '^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$'
}

print_domain_validation_error() {
    local label="$(localized_text "${1:-域名}" "${1:-域名}" "${1:-域名}")"
    local raw="${2:-}"
    local normalized="${3:-}"
    local trimmed display_value

    [[ -z "$normalized" && -n "$raw" ]] && normalized=$(normalize_domain_input "$raw")
    display_value="$(localized_text "${normalized:-（空）}" "${normalized:-（空）}" "${normalized:-（空）}")"
    echo -e "$(localized_text "${RED}❌ ${label}格式无效：${display_value}${PLAIN}" "${RED}❌ ${label} Invalid format: ${display_value}${PLAIN}" "${RED}❌ ${label} Неверный формат: ${display_value}${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}提示：请只粘贴纯域名，例如 panel.example.com；不要带协议、路径、端口或中文/全角标点。${PLAIN}" "${YELLOW}Tip: Please paste only the pure domain, such as panel.example.com; do not include the protocol, path, port or Chinese/full-width punctuation.${PLAIN}" "${YELLOW}Совет. Вставьте только чистое доменное имя, например Panel.example.com; не включайте протокол, путь, порт или знаки препинания на китайском языке или во всю ширину.${PLAIN}")"

    if [[ -z "$raw" ]]; then
        echo -e "$(localized_text "${YELLOW}脚本规范化后用于校验的值：${display_value}${PLAIN}" "${YELLOW}The value used for verification after the script is normalized: ${display_value}${PLAIN}" "${YELLOW}Значение, используемое для проверки после нормализации сценария : ${display_value}.${PLAIN}")"
        return 0
    fi

    trimmed=$(trim_input "$raw")
    if [[ "$trimmed" != "$raw" || "$raw" =~ [[:space:]] ]]; then
        echo -e "$(localized_text "${YELLOW}检测到空白字符：请确认没有复制到换行、制表符、不可见空格或多余空格。${PLAIN}" "${YELLOW}Whitespace characters detected: Please confirm that no newlines, tabs, invisible spaces, or extra spaces are copied.${PLAIN}" "${YELLOW}Обнаружены пробельные символы: убедитесь, что не копируются символы новой строки, табуляции, невидимые пробелы или дополнительные пробелы.${PLAIN}")"
    fi
    if [[ "$trimmed" =~ ^[Hh][Tt][Tt][Pp][Ss]?:// || "$trimmed" == *"://"* || "$trimmed" == */* || "$trimmed" == *\?* || "$trimmed" == *#* || "$trimmed" == *:* ]]; then
        echo -e "$(localized_text "${YELLOW}检测到类似 URL 的内容：请去掉 http(s)://、路径、查询参数、#片段或 :端口。${PLAIN}" "${YELLOW}Detected URL-like content: Please remove http(s)://, path, query parameters, # fragment or :port.${PLAIN}" "${YELLOW}обнаружил содержимое, похожее на URL-адрес: удалите http(s)://, путь, параметры запроса, # фрагмент или :port.${PLAIN}")"
    fi
    if printf '%s' "$trimmed" | grep -q '[：，。／、；？＃＠　]'; then
        echo -e "$(localized_text "${YELLOW}检测到中文/全角标点：请改成英文半角的 . , / : 等字符；域名里的点必须是英文句点。${PLAIN}" "${YELLOW}Detected Chinese/full-width punctuation: please change it to English half-width . , / : and other characters; the dots in the domain must be English periods.${PLAIN}" "${YELLOW}обнаружил китайскую/полноширинную пунктуацию: измените ее на английскую половинную ширину. , / : и другие символы; точки в доменном имени должны быть английскими точками.${PLAIN}")"
    fi
    if printf '%s' "$trimmed" | LC_ALL=C grep -q '[^ -~]'; then
        echo -e "$(localized_text "${YELLOW}检测到非 ASCII 字符：可能包含零宽空格、全角字符或复制来源带入的隐藏字符。${PLAIN}" "${YELLOW}Non-ASCII characters detected: may contain zero-width spaces, full-width characters, or hidden characters brought in from the copy source.${PLAIN}" "${YELLOW}Обнаружены символы, отличные от ASCII: могут содержать пробелы нулевой ширины, символы полной ширины или скрытые символы, полученные из источника копирования.${PLAIN}")"
    fi
    echo -e "$(localized_text "${YELLOW}脚本规范化后用于校验的值：${display_value}${PLAIN}" "${YELLOW}The value used for verification after the script is normalized: ${display_value}${PLAIN}" "${YELLOW}Значение, используемое для проверки после нормализации сценария : ${display_value}.${PLAIN}")"
}

normalize_path_prefix() {
    local path
    path="$(trim_input "$1")"
    if [[ "$path" =~ ^https?://[^/]+(/.*)?$ ]]; then
        path="${BASH_REMATCH[1]:-/}"
    fi
    path="${path%%\?*}"
    path="${path%%#*}"
    [[ -z "$path" ]] && path="/sub/"
    [[ "$path" != /* ]] && path="/${path}"
    [[ "$path" != */ ]] && path="${path}/"
    printf '%s' "$path"
}

is_valid_path_prefix() {
    local path="$1"
    [[ "$path" != "/" && "$path" != *".."* ]] && echo "$path" | grep -Eq '^/[A-Za-z0-9._~/-]+/$'
}

caddy_path_match_tokens() {
    local path
    local exact
    local seen=" "
    local tokens=""
    for path in "$@"; do
        path=$(normalize_path_prefix "$path")
        exact="${path%/}"
        if [[ "$seen" == *" ${exact} "* ]]; then
            continue
        fi
        tokens+="${exact} ${exact}/* "
        seen+=" ${exact} "
    done
    printf '%s' "${tokens% }"
}

is_yes() {
    local value
    value="$(trim_input "$1")"
    [[ "$value" =~ ^[Yy]([Ee][Ss])?$ ]]
}

is_no() {
    local value
    value="$(trim_input "$1")"
    [[ "$value" =~ ^[Nn]([Oo])?$ ]]
}

is_suspicious_public_ipv4() {
    local ip="$1"
    local a b c d

    [[ "$ip" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
    IFS='.' read -r a b c d <<< "$ip"
    for octet in "$a" "$b" "$c" "$d"; do
        [[ "$octet" =~ ^[0-9]+$ ]] && ((10#$octet <= 255)) || return 1
    done

    # Public panel domains should not resolve to private, loopback, test, multicast,
    # or benchmark/fake-ip ranges. Run this on the VPS side; local proxy fake-ip
    # mode may intentionally return 198.18.0.0/15 on the user's own computer.
    ((10#$a == 0 || 10#$a == 10 || 10#$a == 127 || 10#$a >= 224)) && return 0
    ((10#$a == 100 && 10#$b >= 64 && 10#$b <= 127)) && return 0
    ((10#$a == 169 && 10#$b == 254)) && return 0
    ((10#$a == 172 && 10#$b >= 16 && 10#$b <= 31)) && return 0
    ((10#$a == 192 && 10#$b == 168)) && return 0
    ((10#$a == 198 && (10#$b == 18 || 10#$b == 19))) && return 0
    ((10#$a == 192 && 10#$b == 0 && 10#$c == 2)) && return 0
    ((10#$a == 198 && 10#$b == 51 && 10#$c == 100)) && return 0
    ((10#$a == 203 && 10#$b == 0 && 10#$c == 113)) && return 0
    return 1
}

resolve_domain_a_records() {
    local domain="$1"
    if command -v dig >/dev/null 2>&1; then
        dig +short A "$domain" @1.1.1.1 2>/dev/null | grep -E '^([0-9]{1,3}\.){3}[0-9]{1,3}$' | sort -u
    elif command -v nslookup >/dev/null 2>&1; then
        nslookup -type=A "$domain" 1.1.1.1 2>/dev/null | awk '/^Address: / {print $2}' | grep -Ev '^1\.1\.1\.1$' | grep -E '^([0-9]{1,3}\.){3}[0-9]{1,3}$' | sort -u
    elif command -v getent >/dev/null 2>&1; then
        getent ahostsv4 "$domain" 2>/dev/null | awk '{print $1}' | grep -E '^([0-9]{1,3}\.){3}[0-9]{1,3}$' | sort -u
    fi
}

check_domain_dns_sanity() {
    local domain="$1"
    local label="$(localized_text "${2:-域名}" "${2:-域名}" "${2:-域名}")"
    local mode="${3:-warn}"
    local ips ip suspect=0

    ips=$(resolve_domain_a_records "$domain")
    if [[ -z "$ips" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ ${label} ${domain} 未解析到 A 记录；如果只配置了 IPv6/AAAA，请确认客户端和 VPS 都支持 IPv6。${PLAIN}" "${YELLOW}⚠️ ${label} ${domain} is not resolved to the A record; if only IPv6/AAAA is configured, please confirm that both the client and VPS support IPv6.${PLAIN}" "${YELLOW}⚠️ ${label} ${domain} не разрешается в запись A; если настроен только IPv6/AAAA, убедитесь, что и клиент, и VPS поддерживают IPv6.${PLAIN}")"
        return 1
    fi

    echo -e "$(localized_text "${CYAN}▶ ${label} ${domain} 当前 A 记录: $(echo "$ips" | tr '\n' ' ')${PLAIN}" "${CYAN}▶ ${label} ${domain} Current A record: $(echo \"$ips\" | tr '\n' ' ')${PLAIN}" "${CYAN}▶ ${label} ${domain} Текущая запись A: $(echo \"$ips\" | tr '\n' ' ')${PLAIN}")"
    while IFS= read -r ip; do
        [[ -z "$ip" ]] && continue
        if is_suspicious_public_ipv4 "$ip"; then
            echo -e "$(localized_text "${RED}❌ ${label} ${domain} 解析到可疑地址 ${ip}，这不是正常公网 VPS 地址。${PLAIN}" "${RED}❌ ${label} ${domain} resolves to the suspicious address ${ip}, which is not a normal public VPS address.${PLAIN}" "${RED}❌ ${label} ${domain} разрешается в подозрительный адрес ${ip}, который не является обычным VPS-адресом публичной сети.${PLAIN}")"
            suspect=1
        fi
    done <<< "$ips"

    if [[ "$suspect" -eq 1 ]]; then
        echo -e "$(localized_text "${YELLOW}请在 VPS 上复查 DNS。若只在本地电脑开启了 fake-ip，198.18.x.x 可能只是本地代理映射；若 VPS/公共 DNS 也看到此地址，请把 A 记录改成真实 VPS 公网 IP。${PLAIN}" "${YELLOW}Please review DNS on VPS. If fake-ip is only enabled on the local computer, 198.18.x.x may only be local proxy mapping; if VPS/public DNS also sees this address, please change the A record to the real VPS public IP.${PLAIN}" "${YELLOW}Пожалуйста, просмотрите DNS на VPS. Если поддельный IP-адрес включен только на локальном компьютере, 198.18.x.x может быть сопоставлением только локального прокси-сервера; если VPS/public DNS также видит этот адрес, измените запись A на реальный IP-адрес VPS в Интернете.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}如果使用 Cloudflare 小云朵，公共 DNS 应看到 Cloudflare 边缘 IP，而不是 198.18/10/127/192.168 等地址。${PLAIN}" "${YELLOW}If using the Cloudflare cloudlet, the public DNS should see the Cloudflare edge IP instead of 198.18/10/127/192.168 etc. addresses.${PLAIN}" "${YELLOW}При использовании облака Cloudflare общедоступный DNS должен видеть граничный IP-адрес Cloudflare вместо адресов 198.18/10/127/192.168 и т. д.${PLAIN}")"
        if [[ "$mode" == "prompt" ]]; then
            confirm_default_no "$(localized_text "仍要继续？(y/N，不推荐): " "Continue anyway? (y/N, not recommended): " "Всё равно продолжить? (y/N, не рекомендуется): ")" || return 1
        else
            return 1
        fi
    fi

    return 0
}

is_valid_ipv4_cidr() {
    local value="$1"
    local ip prefix a b c d octet
    ip="${value%%/*}"
    prefix=""
    if [[ "$value" == */* ]]; then
        prefix="${value##*/}"
        [[ -n "$prefix" ]] || return 1
    fi

    [[ "$ip" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
    IFS='.' read -r a b c d <<< "$ip"
    for octet in "$a" "$b" "$c" "$d"; do
        [[ "$octet" =~ ^[0-9]+$ ]] || return 1
        (( 10#$octet >= 0 && 10#$octet <= 255 )) || return 1
    done
    if [[ -n "$prefix" ]]; then
        [[ "$prefix" =~ ^[0-9]+$ ]] || return 1
        (( 10#$prefix >= 0 && 10#$prefix <= 32 )) || return 1
    fi
}

is_valid_ipv6_cidr() {
    local value="$1"
    local ip prefix remainder double_colon_count segment_count segment
    local -a ipv6_segments
    [[ -n "$value" ]] || return 1
    ip="${value%%/*}"
    prefix=""
    if [[ "$value" == */* ]]; then
        prefix="${value##*/}"
        [[ -n "$prefix" ]] || return 1
    fi

    [[ -n "$ip" ]] || return 1
    [[ "$ip" == *:* ]] || return 1
    [[ "$ip" =~ ^[0-9a-fA-F:]+$ ]] || return 1
    [[ "$ip" != *:::* ]] || return 1
    remainder="$ip"
    double_colon_count=0
    while [[ "$remainder" == *"::"* ]]; do
        ((double_colon_count += 1))
        remainder="${remainder#*::}"
    done
    (( double_colon_count <= 1 )) || return 1

    segment_count=0
    IFS=':' read -ra ipv6_segments <<< "$ip"
    for segment in "${ipv6_segments[@]}"; do
        [[ -z "$segment" ]] && continue
        ((segment_count += 1))
        ((${#segment} <= 4)) || return 1
    done
    if (( double_colon_count == 0 )); then
        (( segment_count == 8 )) || return 1
    else
        (( segment_count < 8 )) || return 1
    fi
    if [[ -n "$prefix" ]]; then
        [[ "$prefix" =~ ^[0-9]+$ ]] || return 1
        (( 10#$prefix >= 0 && 10#$prefix <= 128 )) || return 1
    fi
}

validate_ip_cidr_python() {
    local value="$1"
    python3 - "$value" <<'PY'
import ipaddress
import sys

try:
    ipaddress.ip_network(sys.argv[1], strict=False)
except ValueError:
    sys.exit(1)
PY
}

is_valid_ip_cidr() {
    local value="$1"
    [[ -n "$value" && "$value" != *";"* && "$value" != *"{"* && "$value" != *"}"* ]] || return 1
    if command -v python3 >/dev/null 2>&1; then
        validate_ip_cidr_python "$value" && return 0
    fi
    is_valid_ipv4_cidr "$value" || is_valid_ipv6_cidr "$value"
}

normalize_ip_input() {
    local value
    value="$(trim_input "$1")"
    if declare -F normalize_ascii_digits >/dev/null 2>&1; then
        value="$(normalize_ascii_digits "$value")"
    fi
    value="${value//。/.}"
    value="${value//．/.}"
    value="${value//｡/.}"
    value="${value//：/:}"
    value=$(printf '%s' "$value" | sed 's#／#/#g')
    value=$(echo "$value" | tr '[:upper:]' '[:lower:]')
    value="${value#http://}"
    value="${value#https://}"
    value="${value%%\?*}"
    value="${value%%？*}"
    value="${value%%#*}"
    value="${value%%＃*}"
    value="${value%%/*}"
    value=$(echo "$value" | tr -d '[:space:]')
    if [[ "$value" =~ ^\[(.+)\](:[0-9]+)?$ ]]; then
        value="${BASH_REMATCH[1]}"
    elif [[ "$value" =~ ^(([0-9]{1,3}\.){3}[0-9]{1,3}):[0-9]+$ ]]; then
        value="${BASH_REMATCH[1]}"
    fi
    printf '%s' "$value"
}

normalize_backend_addr_input() {
    local value
    value="$(normalize_ip_input "$1")"
    value="$(normalize_loopback_addr "$value")"
    if [[ "$value" =~ ^([^:]+):[0-9]+$ ]]; then
        value="${BASH_REMATCH[1]}"
    fi
    printf '%s' "$value"
}

normalize_ip_whitelist_input() {
    local input="$1"
    local -n out_array=$2
    local item normalized seen
    if declare -F normalize_ascii_digits >/dev/null 2>&1; then
        input="$(normalize_ascii_digits "$input")"
    fi
    input="${input//。/.}"
    input="${input//．/.}"
    input="${input//｡/.}"
    input="${input//：/:}"
    input=$(printf '%s' "$input" | sed 's#／#/#g')
    input="${input//，/ }"
    input="${input//、/ }"
    input="${input//；/ }"
    input="${input//;/ }"
    input="${input//|/ }"
    input="${input//,/ }"
    input="${input//$'\r'/ }"
    input="${input//$'\n'/ }"
    input="${input//$'\t'/ }"
    out_array=()
    seen=" "
    for item in $input; do
        normalized=$(echo "$(trim_input "$item")" | tr '[:upper:]' '[:lower:]')
        if [[ "$normalized" =~ ^\[(.+)\](/.+)?$ ]]; then
            normalized="${BASH_REMATCH[1]}${BASH_REMATCH[2]}"
        fi
        [[ -z "$normalized" ]] && continue
        if ! is_valid_ip_cidr "$normalized"; then
            echo -e "$(localized_text "${RED}❌ IP/CIDR 格式无效：${normalized}${PLAIN}" "${RED}❌ Invalid IP/CIDR format: ${normalized}${PLAIN}" "${RED}❌ Неверный формат IP/CIDR: ${normalized}.${PLAIN}")"
            return 1
        fi
        if [[ "$seen" != *" ${normalized} "* ]]; then
            out_array+=("$normalized")
            seen+=" ${normalized} "
        fi
    done
    [[ ${#out_array[@]} -gt 0 ]]
}

normalize_port_input() {
    local value port_candidate
    value="$(trim_input "$1")"
    if declare -F normalize_ascii_digits >/dev/null 2>&1; then
        value="$(normalize_ascii_digits "$value")"
    fi
    value="${value//：/:}"
    value=$(echo "$value" | tr '[:upper:]' '[:lower:]')
    value="${value#http://}"
    value="${value#https://}"
    value="${value%%\?*}"
    value="${value%%？*}"
    value="${value%%#*}"
    value="${value%%＃*}"
    value="${value%%/*}"
    value=$(echo "$value" | tr -d '[:space:]')
    value="${value%)}"
    value="${value%）}"
    value="${value%.}"
    value="${value%．}"
    value="${value%,}"
    value="${value%，}"
    value="${value%;}"
    value="${value%；}"
    if [[ "$value" == *:* ]]; then
        port_candidate="${value##*:}"
        [[ "$port_candidate" =~ ^[0-9]+$ ]] && value="$port_candidate"
    fi
    printf '%s' "$value"
}

is_valid_port() {
    local port
    port="$(normalize_port_input "$1")"
    [[ "$port" =~ ^[0-9]+$ ]] && (( 10#$port >= 1 && 10#$port <= 65535 ))
}

is_valid_listen_addr() {
    local addr="$1"
    if [[ "$addr" == "127.0.0.1" || "$addr" == "localhost" || "$addr" == "0.0.0.0" || "$addr" == "::1" || "$addr" == "::" ]]; then
        return 0
    fi
    if [[ "$addr" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
        local IFS=.
        local -a octets=($addr)
        local octet
        for octet in "${octets[@]}"; do
            [[ "$octet" =~ ^[0-9]+$ ]] || return 1
            (( 10#$octet >= 0 && 10#$octet <= 255 )) || return 1
        done
        return 0
    fi
    return 1
}

is_valid_backend_addr() {
    local addr="$1"
    [[ -n "$addr" ]] || return 1
    is_valid_listen_addr "$addr" || is_valid_hostname "$addr"
}

backend_addr_resolution_status() {
    local addr="$1"

    addr="${addr#[}"
    addr="${addr%]}"
    if is_valid_listen_addr "$addr"; then
        return 0
    fi
    if command -v getent >/dev/null 2>&1; then
        getent ahosts "$addr" >/dev/null 2>&1
        return $?
    fi
    return 2
}

tcp_target_reachable() {
    local host="$1"
    local port="$2"
    local attempted=0

    is_valid_port "$port" || return 1
    if command -v nc >/dev/null 2>&1; then
        attempted=1
        nc -z -w 3 "$host" "$port" >/dev/null 2>&1 && return 0
    fi
    if command -v timeout >/dev/null 2>&1; then
        attempted=1
        timeout 5 bash -c 'cat < /dev/null > /dev/tcp/$1/$2' _ "$host" "$port" 2>/dev/null && return 0
    fi
    if command -v curl >/dev/null 2>&1; then
        attempted=1
        curl -fsS --connect-timeout 3 --max-time 5 "telnet://$(format_hostport "$host" "$port")" </dev/null >/dev/null 2>&1 && return 0
    fi
    [[ "$attempted" -eq 1 ]] && return 1
    return 2
}

probe_backend_target() {
    local label="$1"
    local addr="$2"
    local port="$3"
    local probe_rc

    if ! is_valid_backend_addr "$addr" || ! is_valid_port "$port"; then
        echo -e "$(localized_text "${RED}❌ ${label}：后端地址或端口无效（$(format_hostport "$addr" "$port")）${PLAIN}" "${RED}❌ ${label}: Invalid backend address or port ($(format_hostport \"$addr\" \"$port\"))${PLAIN}" "${RED}❌ ${label}: Неверный внутренний адрес или порт ($(format_hostport \"$addr\" \"$port\"))${PLAIN}")"
        return 1
    fi

    if backend_addr_resolution_status "$addr"; then
        :
    else
        probe_rc=$?
        if [[ "$probe_rc" -eq 2 ]]; then
            echo -e "$(localized_text "${YELLOW}⚠️ ${label}：缺少地址解析工具，未检查 $(format_hostport "$addr" "$port")${PLAIN}" "${YELLOW}⚠️ ${label}: Missing address resolution tool, not checked $(format_hostport \"$addr\" \"$port\")${PLAIN}" "${YELLOW}⚠️ ${label}: Отсутствует инструмент разрешения адресов, не отмечен $(format_hostport \"$addr\" \"$port\")${PLAIN}")"
            return 2
        fi
        echo -e "$(localized_text "${RED}❌ ${label}：无法解析后端地址 ${addr}${PLAIN}" "${RED}❌ ${label}: Unable to resolve backend address ${addr}${PLAIN}" "${RED}❌ ${label}: невозможно разрешить внутренний адрес ${addr}${PLAIN}")"
        return 1
    fi

    if tcp_target_reachable "$addr" "$port"; then
        echo -e "$(localized_text "${GREEN}✅ ${label}：$(format_hostport "$addr" "$port") 可连接${PLAIN}" "${GREEN}✅ ${label}: $(format_hostport \"$addr\" \"$port\") is reachable${PLAIN}" "${GREEN}✅ ${label}: $(format_hostport \"$addr\" \"$port\") доступен${PLAIN}")"
        return 0
    fi
    probe_rc=$?
    if [[ "$probe_rc" -eq 2 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ ${label}：缺少 nc、timeout 或 curl，未检查 $(format_hostport "$addr" "$port")${PLAIN}" "${YELLOW}⚠️ ${label}: missing nc, timeout or curl, not checked $(format_hostport \"$addr\" \"$port\")${PLAIN}" "${YELLOW}⚠️ ${label}: отсутствует NC, тайм-аут или curl, не проверено $(format_hostport \"$addr\" \"$port\")${PLAIN}")"
        return 2
    fi
    echo -e "$(localized_text "${RED}❌ ${label}：$(format_hostport "$addr" "$port") 当前不可连接${PLAIN}" "${RED}❌ ${label}: $(format_hostport \"$addr\" \"$port\") is unreachable${PLAIN}" "${RED}❌ ${label}: $(format_hostport \"$addr\" \"$port\") недоступен${PLAIN}")"
    return 1
}

confirm_backend_target_or_continue() {
    local label="$1"
    local addr="$2"
    local port="$3"
    local probe_rc

    if probe_backend_target "$label" "$addr" "$port"; then
        return 0
    fi
    probe_rc=$?
    [[ "$probe_rc" -eq 2 ]] && return 0

    if confirm_default_no "$(localized_text "后端当前不可连接，仍要继续保存吗？(y/N，默认 N): " "The backend is unreachable. Save anyway? (y/N, default N): " "Бэкенд недоступен. Всё равно сохранить? (y/N, по умолчанию N): ")"; then
        echo -e "$(localized_text "${YELLOW}⚠️ 已选择继续；保存后请检查后端服务、地址和端口。${PLAIN}" "${YELLOW}⚠️ Selected to continue; please check the backend service, address and port after saving.${PLAIN}" "${YELLOW}⚠️ Выбрано для продолжения; пожалуйста, проверьте серверную службу, адрес и порт после сохранения.${PLAIN}")"
        return 0
    fi
    echo -e "$(localized_text "${BLUE}已取消保存。${PLAIN}" "${BLUE}Save canceled.${PLAIN}" "${BLUE}Сохранение отменено.${PLAIN}")"
    return 1
}

is_loopback_listen_addr() {
    local addr="$1"
    [[ "$addr" == "127.0.0.1" || "$addr" == "localhost" || "$addr" == "::1" ]]
}

normalize_loopback_addr() {
    local addr="$1"
    [[ "$addr" == "localhost" ]] && addr="127.0.0.1"
    printf '%s' "$addr"
}

normalize_port_rule_input() {
    local value="$1"
    if declare -F normalize_ascii_digits >/dev/null 2>&1; then
        value="$(normalize_ascii_digits "$value")"
    fi
    value="${value//，/,}"
    value="${value//、/,}"
    value="${value//；/,}"
    value="${value//;/,}"
    value="${value//：/:}"
    value="${value//－/-}"
    value="${value//—/-}"
    value=$(echo "$value" | tr -d '[:space:]')

    local item start end extra
    local items=()
    local normalized=()
    IFS=',' read -ra items <<< "$value"
    for item in "${items[@]}"; do
        item="${item//:/-}"
        if [[ "$item" == *-* ]]; then
            IFS='-' read -r start end extra <<< "$item"
            if [[ -z "$extra" && "$start" =~ ^[0-9]+$ && "$end" =~ ^[0-9]+$ ]]; then
                normalized+=("$((10#$start))-$((10#$end))")
            else
                normalized+=("$item")
            fi
        elif [[ "$item" =~ ^[0-9]+$ ]]; then
            normalized+=("$((10#$item))")
        else
            normalized+=("$item")
        fi
    done

    (IFS=','; printf '%s' "${normalized[*]}")
}

is_valid_port_rule_input() {
    local input
    input=$(normalize_port_rule_input "$1")
    [[ -n "$input" ]] || return 1

    local item range_start range_end extra
    local items=()
    IFS=',' read -ra items <<< "$input"
    for item in "${items[@]}"; do
        [[ -n "$item" ]] || return 1
        item="${item//:/-}"
        if [[ "$item" == *-* ]]; then
            IFS='-' read -r range_start range_end extra <<< "$item"
            [[ -z "$extra" ]] || return 1
            is_valid_port "$range_start" && is_valid_port "$range_end" || return 1
            (( 10#$range_start <= 10#$range_end )) || return 1
        else
            is_valid_port "$item" || return 1
        fi
    done
    return 0
}

warn_if_public_bind() {
    local service_name="$1"
    local listen_addr="$2"
    local listen_port="$3"
    local confirm
    if [[ "$listen_addr" == "0.0.0.0" || "$listen_addr" == "::" ]]; then
        confirm_risk_action "$(localized_text "${service_name} 监听公网 ${listen_addr}:${listen_port}" "${service_name} listens on the public ${listen_addr}:${listen_port}" "${service_name} прослушивает публичную сеть ${listen_addr}:${listen_port}")" \
            "$(localized_text "${service_name} 监听地址将从本地模型改为公网可访问" "${service_name} listening address will be changed from local model to public accessible" "Адрес прослушивания ${service_name} будет изменен с локальной модели на доступную публичную сеть.")" \
            "$(localized_text "改回 127.0.0.1 后重新应用配置并重启相关服务" "Change back to 127.0.0.1 and then reapply the configuration and restart related services." "Вернитесь к 127.0.0.1, затем повторно примените конфигурацию и перезапустите соответствующие службы.")" \
            "$(localized_text "仅在你明确需要公网直连该服务时继续。" "Only continue if you clearly need a direct public connection to the service." "Продолжайте только в том случае, если вам явно необходимо прямое подключение к службе через публичную сеть.")" || return 1
    fi
    return 0
}

format_hostport() {
    local addr="$1"
    local port="$2"
    if [[ "$addr" == *:* && "$addr" != \[*\] ]]; then
        echo "[${addr}]:${port}"
    else
        echo "${addr}:${port}"
    fi
}

nginx_stream_listen_directives() {
    local addr="$1"
    local port="$2"

    if [[ "$addr" == *:* && "$addr" != \[*\] ]]; then
        printf '    listen [%s]:%s;\n' "$addr" "$port"
        return 0
    fi

    printf '    listen %s:%s;\n' "$addr" "$port"
    if [[ "$addr" == "0.0.0.0" ]]; then
        printf '    listen [::]:%s;\n' "$port"
    fi
}

xui_cert_setting_key_sql_list() {
    printf '%s' "'webcertfile','webkeyfile','webcert','webcertkey','webcertkeyfile','certfile','keyfile','cert','key','subcertfile','subkeyfile','subcert','subkey','subcertkey','subcertkeyfile'"
}

dns_is_valid_ipv4() {
    local ip="$1"
    local octet
    [[ "$ip" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
    local IFS=.
    local -a octets=($ip)
    for octet in "${octets[@]}"; do
        [[ "$octet" =~ ^[0-9]+$ ]] || return 1
        (( 10#$octet >= 0 && 10#$octet <= 255 )) || return 1
    done
    return 0
}

dns_is_valid_ipv6() {
    local ip="$1"
    [[ "$ip" == *:* ]] || return 1
    [[ "$ip" =~ ^[0-9A-Fa-f:]+$ ]] || return 1
    [[ "$ip" != *:::* ]]
}

dns_normalize_servers() {
    local family="$1"
    local raw="$2"
    local item
    local items=()
    local result=()

    if declare -F normalize_ascii_digits >/dev/null 2>&1; then
        raw="$(normalize_ascii_digits "$raw")"
    fi
    raw="${raw//。/.}"
    raw="${raw//．/.}"
    raw="${raw//｡/.}"
    raw="${raw//：/:}"
    raw=$(printf '%s' "$raw" | sed 's#／#/#g')
    raw="${raw//，/,}"
    raw="${raw//、/,}"
    raw="${raw//；/,}"
    raw="${raw//;/,}"
    raw="${raw//$'\r'/,}"
    raw="${raw//$'\n'/,}"
    raw="${raw// /,}"
    raw="${raw//$'\t'/,}"
    IFS=',' read -ra items <<< "$raw"

    for item in "${items[@]}"; do
        item="$(trim_input "$item")"
        if [[ "$item" =~ ^\[(.+)\]$ ]]; then
            item="${BASH_REMATCH[1]}"
        fi
        [[ -z "$item" ]] && continue
        if [[ "$family" == "4" ]]; then
            dns_is_valid_ipv4 "$item" || return 1
        else
            dns_is_valid_ipv6 "$item" || return 1
        fi
        result+=("$item")
    done

    [[ ${#result[@]} -gt 0 ]] || return 1
    (IFS=' '; printf '%s' "${result[*]}")
}

# ---------------------------------------------------------
# Module: rollback.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Rollback and quarantine helpers.

quarantine_path() {
    local target="$1"
    local quarantine_root="${2:-/root/vps-optimize-quarantine}"
    local resolved base dest

    if [[ -z "$target" || "$target" == *"*"* || "$target" == *"?"* ]]; then
        echo -e "$(localized_text "${RED}❌ 拒绝隔离空路径或通配符路径：${target}${PLAIN}" "${RED}❌ Deny quarantine of empty or wildcard paths: ${target}${PLAIN}" "${RED}❌ Запретить карантин пустых путей или путей с подстановочными знаками: ${target}.${PLAIN}")"
        return 1
    fi

    [[ -e "$target" || -L "$target" ]] || return 0

    resolved=$(readlink -f -- "$target" 2>/dev/null || realpath -m -- "$target" 2>/dev/null || printf '%s' "$target")
    case "$resolved" in
        /|/bin|/boot|/dev|/etc|/home|/lib|/lib64|/opt|/proc|/root|/run|/sbin|/sys|/tmp|/usr|/var)
            echo -e "$(localized_text "${RED}❌ 拒绝隔离系统根级目录：${resolved}${PLAIN}" "${RED}❌ Refuse to isolate the system root directory: ${resolved}${PLAIN}" "${RED}❌ Отказаться от изоляции корневого каталога системы: ${resolved}${PLAIN}")"
            return 1
            ;;
    esac

    mkdir -p "$quarantine_root" || return 1
    chmod 700 "$quarantine_root" 2>/dev/null || true
    base=$(basename "$resolved")
    dest="${quarantine_root%/}/$(date +%Y%m%d_%H%M%S)_${base}"
    while [[ -e "$dest" ]]; do
        dest="${dest}_$RANDOM"
    done

    mv -- "$target" "$dest"
    echo -e "$(localized_text "${YELLOW}已隔离：${resolved} -> ${dest}${PLAIN}" "${YELLOW}Has been isolated: ${resolved} -> ${dest}${PLAIN}" "${YELLOW}изолирован: ${resolved} -> ${dest}${PLAIN}")"
}

restore_sni_stack_backup_files() {
    local backup_dir="$1"
    local domain conf_file
    [[ -n "$backup_dir" && -d "$backup_dir" ]] || return 1

    mkdir -p /etc/nginx/stream.d /etc/nginx/conf.d /etc/caddy/conf.d /etc/vps-optimize /etc/systemd/system /usr/local/bin
    [[ -f "$backup_dir/nginx.conf" ]] && cp -a "$backup_dir/nginx.conf" /etc/nginx/nginx.conf
    [[ -f "$backup_dir/Caddyfile" ]] && cp -a "$backup_dir/Caddyfile" /etc/caddy/Caddyfile
    [[ -f "$backup_dir/vps-optimize/sni-stack.env" ]] && cp -a "$backup_dir/vps-optimize/sni-stack.env" /etc/vps-optimize/sni-stack.env
    [[ -f "$backup_dir/vps-optimize/xray-sni-routes.conf" ]] && cp -a "$backup_dir/vps-optimize/xray-sni-routes.conf" /etc/vps-optimize/xray-sni-routes.conf
    [[ -f "$backup_dir/vps-optimize/443-engine.conf" ]] && cp -a "$backup_dir/vps-optimize/443-engine.conf" /etc/vps-optimize/443-engine.conf
    [[ -f "$backup_dir/vps-optimize/vpso-mux.yaml" ]] && cp -a "$backup_dir/vps-optimize/vpso-mux.yaml" /etc/vps-optimize/vpso-mux.yaml
    [[ -f "$backup_dir/systemd/vpso-mux.service" ]] && cp -a "$backup_dir/systemd/vpso-mux.service" /etc/systemd/system/vpso-mux.service
    [[ -f "$backup_dir/usr-local-bin/vpso-mux" ]] && cp -a "$backup_dir/usr-local-bin/vpso-mux" /usr/local/bin/vpso-mux

    while IFS= read -r conf_file; do
        quarantine_path "$conf_file" "/etc/vps-optimize/quarantine/nginx-sni" >/dev/null 2>&1 || true
    done < <(find /etc/nginx/stream.d -maxdepth 1 -type f -name 'vps_sni_*.conf' 2>/dev/null | sort)
    cp -a "$backup_dir/nginx_stream.d/"*.conf /etc/nginx/stream.d/ 2>/dev/null || true

    while IFS= read -r conf_file; do
        quarantine_path "$conf_file" "/etc/vps-optimize/quarantine/nginx-conf-d" >/dev/null 2>&1 || true
    done < <(find /etc/nginx/conf.d -maxdepth 1 \( -name 'vps_sni_web_*.conf' -o -name 'vps_proxy_*.conf' \) 2>/dev/null | sort)
    cp -a "$backup_dir/nginx_conf.d/"*.conf /etc/nginx/conf.d/ 2>/dev/null || true

    for domain in "$PANEL_DOMAIN" "${SITE_DOMAINS[@]}"; do
        [[ -n "$domain" ]] || continue
        conf_file="/etc/caddy/conf.d/${domain}.caddy"
        [[ -e "$conf_file" ]] && quarantine_path "$conf_file" "/etc/vps-optimize/quarantine/caddy-sni" >/dev/null 2>&1 || true
    done
    cp -a "$backup_dir/caddy_conf.d/"*.caddy /etc/caddy/conf.d/ 2>/dev/null || true
}

rollback_sni_stack_after_failure() {
    local backup_dir="$1"
    local reason="$(localized_text "${2:-配置应用失败}" "${2:-配置应用失败}" "${2:-配置应用失败}")"
    echo -e "${RED}❌ ${reason}${PLAIN}"
    echo -e "$(localized_text "${YELLOW}▶ 正在从本次操作前备份回滚 Nginx/Caddy 配置...${PLAIN}" "${YELLOW}▶ Rolling back from the backup before this operation Nginx/Caddy configuration...${PLAIN}" "${YELLOW}▶ Откат из резервной копии перед этой операцией. Конфигурация Nginx/Caddy...${PLAIN}")"
    if restore_sni_stack_backup_files "$backup_dir"; then
        nginx -t >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}⚠️ Nginx 回滚后语法检查仍未通过，请手动检查 /etc/nginx/nginx.conf。${PLAIN}" "${YELLOW}⚠️ Nginx The syntax check still fails after rollback. Please check /etc/nginx/nginx.conf manually.${PLAIN}" "${YELLOW}⚠️ Nginx Проверка синтаксиса по-прежнему не выполняется после отката. Пожалуйста, проверьте /etc/nginx/nginx.conf вручную.${PLAIN}")"
        caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}⚠️ Caddy 回滚后配置检查仍未通过，请手动检查 /etc/caddy/Caddyfile。${PLAIN}" "${YELLOW}⚠️ Caddy The configuration check still fails after rollback. Please check /etc/caddy/Caddyfile manually.${PLAIN}" "${YELLOW}⚠️ Caddy Проверка конфигурации после отката по-прежнему не выполняется. Пожалуйста, проверьте /etc/caddy/Caddyfile вручную.${PLAIN}")"
        restart_service_if_available nginx >/dev/null 2>&1 || true
        restart_service_if_available caddy >/dev/null 2>&1 || true
        systemctl daemon-reload >/dev/null 2>&1 || true
        echo -e "$(localized_text "${YELLOW}已回滚到：${backup_dir}${PLAIN}" "${YELLOW}Has been rolled back to: ${backup_dir}${PLAIN}" "${YELLOW}откатился до: ${backup_dir}.${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ 自动回滚失败，请手动使用备份目录恢复：${backup_dir}${PLAIN}" "${RED}❌ Automatic rollback failed, please manually use the backup directory to restore: ${backup_dir}${PLAIN}" "${RED}❌ Не удалось выполнить автоматический откат. Для восстановления вручную используйте каталог резервной копии: ${backup_dir}.${PLAIN}")"
    fi
    return 1
}

rollback_sni_stack_config() {
    local backup_dir
    backup_dir=$(cat /etc/vps-optimize/sni-stack.last-backup 2>/dev/null)
    if [[ -z "$backup_dir" || ! -d "$backup_dir" ]]; then
        backup_dir=$(find /etc/vps-optimize/backups -maxdepth 1 -type d -name 'sni-stack_*' 2>/dev/null | sort | tail -n1)
    fi
    if [[ -z "$backup_dir" || ! -d "$backup_dir" ]]; then
        echo -e "$(localized_text "${RED}❌ 未找到可回滚的 SNI stack 备份。${PLAIN}" "${RED}❌ No rollbackable SNI stack backup found.${PLAIN}" "${RED}❌ Не найдена резервная копия стека SNI, допускающая откат.${PLAIN}")"
        return 1
    fi
    echo -e "$(localized_text "${YELLOW}即将回滚到备份：${backup_dir}${PLAIN}" "${YELLOW}Is about to be rolled back to backup: ${backup_dir}${PLAIN}" "${YELLOW}собирается вернуться к резервной копии: ${backup_dir}${PLAIN}")"
    confirm_risk_action "$(localized_text "回滚覆盖 Nginx/Caddy 443 配置" "Rollback coverage Nginx/Caddy 443 configuration" "Покрытие отката конфигурации Nginx/Caddy 443")" \
        "$(localized_text "当前 Nginx/Caddy/443端口复用相关配置" "Current Nginx/Caddy/Port 443 Reuse related configuration" "Текущая конфигурация, связанная повторного использования порта 443 Nginx/Caddy/443")" \
        "$(localized_text "如回滚后仍异常，请用云厂商控制台或手动恢复备份目录" "If the exception persists after rollback, please use the cloud provider console or manually restore the backup directory." "Если исключение сохраняется после отката, воспользуйтесь консолью облачного провайдера или вручную восстановите каталог резервной копии.")" \
        "$(localized_text "回滚会覆盖当前配置，请确认已选中正确备份。" "Rolling back will overwrite the current configuration, please confirm that correct backup is selected." "При откате текущая конфигурация будет перезаписана. Убедитесь, что выбрана правильная резервная копия.")" || return 1

    restore_sni_stack_backup_files "$backup_dir" || { echo -e "$(localized_text "${RED}❌ 回滚文件恢复失败。${PLAIN}" "${RED}❌ Rollback file recovery failed.${PLAIN}" "${RED}❌ Не удалось выполнить откат восстановления файла.${PLAIN}")"; return 1; }

    if nginx -t && caddy validate --config /etc/caddy/Caddyfile; then
        restart_service_if_available nginx >/dev/null 2>&1 || true
        restart_service_if_available caddy >/dev/null 2>&1 || true
        echo -e "$(localized_text "${GREEN}✅ 回滚完成。${PLAIN}" "${GREEN}✅ Rollback completed.${PLAIN}" "${GREEN}✅ Откат завершен.${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ 回滚文件已恢复，但配置校验失败，请手动检查备份：${backup_dir}${PLAIN}" "${RED}❌ The rollback file has been restored, but the configuration validation failed. Please check the backup manually: ${backup_dir}${PLAIN}" "${RED}❌ Файл отката восстановлен, но проверка конфигурации не удалась. Пожалуйста, проверьте резервную копию вручную: ${backup_dir}.${PLAIN}")"
        return 1
    fi
}

restore_backup_file() {
    local snapshot="$1"
    local target="$2"

    [[ -f "$snapshot" || -L "$snapshot" ]] || return 0
    mkdir -p "$(dirname "$target")" || return 1
    cp -af -- "$snapshot" "$target"
}

restore_backup_dir() {
    local snapshot="$1"
    local target="$2"
    local quarantine_root="$3"

    [[ -d "$snapshot" ]] || return 0
    mkdir -p "$(dirname "$target")" || return 1
    if [[ -e "$target" || -L "$target" ]]; then
        quarantine_path "$target" "$quarantine_root" >/dev/null 2>&1 || return 1
    fi
    cp -a -- "$snapshot" "$target"
}

dns_restore_latest_backup() {
    local backup_dir
    backup_dir=$(cat "${DNS_OPTIMIZE_BACKUP_DIR}/last" 2>/dev/null || true)
    if [[ -z "$backup_dir" || ! -d "$backup_dir" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未找到最近一次 DNS 备份。${PLAIN}" "${YELLOW}⚠️ The most recent DNS backup was not found.${PLAIN}" "${YELLOW}⚠️ Самая последняя резервная копия DNS не найдена.${PLAIN}")"
        return 1
    fi

    confirm_risk_action "$(localized_text "恢复最近一次 DNS 备份" "Restore the most recent DNS backup" "Восстановите самую последнюю резервную копию DNS.")" \
        "$(localized_text "/etc/resolv.conf 和 VPS-Optimize 写入的 systemd-resolved DNS 配置" "systemd-resolved DNS configuration written by /etc/resolv.conf and VPS-Optimize" "Конфигурация DNS с разрешением systemd, написанная /etc/resolv.conf и VPS-Optimize")" \
        "$(localized_text "重新进入 DNS 优化菜单选择国内/国外/自定义 DNS" "Re-enter DNS optimization menu and select domestic/foreign/customized DNS" "Снова войдите в меню оптимизации DNS и выберите отечественный/иностранный/индивидуальный DNS.")" \
        "$(localized_text "恢复后如果解析异常，请重新选择一个 DNS 配置。" "If the parsing is abnormal after recovery, please select a DNS configuration again." "Если после восстановления анализ происходит ненормально, выберите конфигурацию DNS еще раз.")" || return 1

    if [[ -e "$backup_dir/resolv.conf" || -L "$backup_dir/resolv.conf" ]]; then
        [[ -e /etc/resolv.conf || -L /etc/resolv.conf ]] && quarantine_path /etc/resolv.conf "/etc/vps-optimize/quarantine/dns" >/dev/null 2>&1 || true
        cp -a "$backup_dir/resolv.conf" /etc/resolv.conf
    fi

    if [[ -f "$DNS_OPTIMIZE_RESOLVED_DROPIN" ]]; then
        quarantine_path "$DNS_OPTIMIZE_RESOLVED_DROPIN" "/etc/vps-optimize/quarantine/dns" >/dev/null 2>&1 || true
    fi
    if [[ -f "$backup_dir/99-vps-optimize-dns.conf" ]]; then
        mkdir -p /etc/systemd/resolved.conf.d
        cp -a "$backup_dir/99-vps-optimize-dns.conf" "$DNS_OPTIMIZE_RESOLVED_DROPIN"
    fi

    systemctl restart systemd-resolved >/dev/null 2>&1 || true
    echo -e "$(localized_text "${GREEN}✅ 已恢复 DNS 备份：${backup_dir}${PLAIN}" "${GREEN}✅ Restored DNS Backup: ${backup_dir}${PLAIN}" "${GREEN}✅ Восстановлена резервная копия DNS: ${backup_dir}${PLAIN}")"
}

# ---------------------------------------------------------
# Module: backup.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Backup helpers and backup center entrypoint.

sni_stack_backup_dir() {
    echo "/etc/vps-optimize/backups/sni-stack_$(date +%Y%m%d_%H%M%S)"
}

create_sni_stack_backup() {
    local backup_dir
    backup_dir="${1:-$(sni_stack_backup_dir)}"
    mkdir -p "$backup_dir/nginx_stream.d" "$backup_dir/nginx_conf.d" "$backup_dir/caddy_conf.d" "$backup_dir/vps-optimize" "$backup_dir/systemd" "$backup_dir/usr-local-bin" "$backup_dir/x-ui"
    [[ -f /etc/nginx/nginx.conf ]] && cp -a /etc/nginx/nginx.conf "$backup_dir/nginx.conf" 2>/dev/null || true
    [[ -d /etc/nginx/stream.d ]] && cp -a /etc/nginx/stream.d/vps_sni_*.conf "$backup_dir/nginx_stream.d/" 2>/dev/null || true
    [[ -d /etc/nginx/conf.d ]] && cp -a /etc/nginx/conf.d/vps_sni_web_*.conf "$backup_dir/nginx_conf.d/" 2>/dev/null || true
    [[ -d /etc/nginx/conf.d ]] && cp -a /etc/nginx/conf.d/vps_proxy_*.conf "$backup_dir/nginx_conf.d/" 2>/dev/null || true
    [[ -f /etc/nginx/conf.d/00-vps-proxy-map.conf ]] && cp -a /etc/nginx/conf.d/00-vps-proxy-map.conf "$backup_dir/nginx_conf.d/" 2>/dev/null || true
    [[ -f /etc/caddy/Caddyfile ]] && cp -a /etc/caddy/Caddyfile "$backup_dir/Caddyfile" 2>/dev/null || true
    [[ -d /etc/caddy/conf.d ]] && cp -a /etc/caddy/conf.d/*.caddy "$backup_dir/caddy_conf.d/" 2>/dev/null || true
    [[ -f /etc/vps-optimize/sni-stack.env ]] && cp -a /etc/vps-optimize/sni-stack.env "$backup_dir/vps-optimize/sni-stack.env" 2>/dev/null || true
    [[ -f /etc/vps-optimize/xray-sni-routes.conf ]] && cp -a /etc/vps-optimize/xray-sni-routes.conf "$backup_dir/vps-optimize/xray-sni-routes.conf" 2>/dev/null || true
    [[ -f /etc/vps-optimize/443-engine.conf ]] && cp -a /etc/vps-optimize/443-engine.conf "$backup_dir/vps-optimize/443-engine.conf" 2>/dev/null || true
    [[ -f /etc/vps-optimize/vpso-mux.yaml ]] && cp -a /etc/vps-optimize/vpso-mux.yaml "$backup_dir/vps-optimize/vpso-mux.yaml" 2>/dev/null || true
    [[ -f /etc/systemd/system/vpso-mux.service ]] && cp -a /etc/systemd/system/vpso-mux.service "$backup_dir/systemd/vpso-mux.service" 2>/dev/null || true
    [[ -f /usr/local/bin/vpso-mux ]] && cp -a /usr/local/bin/vpso-mux "$backup_dir/usr-local-bin/vpso-mux" 2>/dev/null || true
    [[ -d /etc/x-ui ]] && cp -a /etc/x-ui "$backup_dir/x-ui/etc-x-ui" 2>/dev/null || true
    [[ -f /usr/local/x-ui/bin/config.json ]] && cp -a /usr/local/x-ui/bin/config.json "$backup_dir/x-ui/config.json" 2>/dev/null || true
    echo "$backup_dir" > /etc/vps-optimize/sni-stack.last-backup 2>/dev/null || true
    echo -e "$(localized_text "${GREEN}✅ 已创建配置备份：${backup_dir}${PLAIN}" "${GREEN}✅ Configuration backup created: ${backup_dir}${PLAIN}" "${GREEN}✅ Создана резервная копия конфигурации: ${backup_dir}.${PLAIN}")"
}

make_secure_temp_dir() {
    local prefix="$1"
    local tmp_dir
    tmp_dir=$(mktemp -d "/tmp/${prefix}.XXXXXX") || return 1
    chmod 700 "$tmp_dir" 2>/dev/null || true
    printf '%s' "$tmp_dir"
}

backup_cleanup_temp_dir() {
    local target="$1"
    local temp_root resolved_target target_parent target_name

    [[ -n "$target" && -d "$target" && ! -L "$target" ]] || return 0
    temp_root=$(readlink -f -- "${TMPDIR:-/tmp}") || return 1
    resolved_target=$(readlink -f -- "$target") || return 1
    target_parent=$(dirname -- "$resolved_target")
    target_name=$(basename -- "$resolved_target")
    [[ "$target_parent" == "$temp_root" ]] || return 1
    case "$target_name" in
        vps_backup_*.??????|vps_restore.??????) ;;
        *) return 1 ;;
    esac
    find "$resolved_target" -xdev -depth -delete
}

backup_copy_path() {
    local src="$1"
    local dest_rel="$2"
    local manifest_file="$3"
    local work_dir="$4"
    local dest_dir

    [[ -e "$src" || -L "$src" ]] || return 1
    dest_dir=$(dirname "$dest_rel")
    mkdir -p "$work_dir/$dest_dir" || return 1

    if cp -a -- "$src" "$work_dir/$dest_rel" 2>/dev/null; then
        echo " - $src" >> "$manifest_file"
        return 0
    fi
    BACKUP_COPY_FAILURES+=("$src")
    return 1
}

backup_path_size_bytes() {
    local target="$1"
    local size_kib
    size_kib=$(du -sk -- "$target" 2>/dev/null | awk 'NR == 1 {print $1}')
    [[ "$size_kib" =~ ^[0-9]+$ ]] || return 1
    printf '%s' "$((size_kib * 1024))"
}

backup_archive_unpacked_size_bytes() {
    local archive_file="$1"
    local size
    size=$(LC_ALL=C tar -tvzf "$archive_file" 2>/dev/null | awk '$3 ~ /^[0-9]+$/ {total += $3} END {printf "%.0f", total + 0}')
    [[ "$size" =~ ^[0-9]+$ ]] || return 1
    printf '%s' "$size"
}

backup_available_bytes() {
    local target="$1"
    local available_kib
    available_kib=$(df -Pk -- "$target" 2>/dev/null | awk 'NR == 2 {print $4}')
    [[ "$available_kib" =~ ^[0-9]+$ ]] || return 1
    printf '%s' "$((available_kib * 1024))"
}

backup_human_size() {
    local bytes="$1"
    awk -v bytes="$bytes" 'BEGIN {
        split("B KiB MiB GiB TiB", units, " ")
        unit_index = 1
        while (bytes >= 1024 && unit_index < 5) { bytes /= 1024; unit_index++ }
        if (unit_index == 1) printf "%d %s", bytes, units[unit_index]
        else printf "%.1f %s", bytes, units[unit_index]
    }'
}

backup_require_free_space() {
    local target="$1"
    local payload_bytes="$2"
    local operation="$3"
    local reserve_bytes=$((64 * 1024 * 1024))
    local required_bytes available_bytes

    required_bytes=$((payload_bytes + payload_bytes / 10 + reserve_bytes))
    if ! available_bytes=$(backup_available_bytes "$target"); then
        echo -e "$(localized_text "${YELLOW}⚠️ 无法读取 ${target} 的可用空间，继续前请自行确认磁盘容量。${PLAIN}" "${YELLOW}⚠️ Available space for ${target} could not be read. Verify disk capacity before continuing.${PLAIN}" "${YELLOW}⚠️ Не удалось определить свободное место для ${target}. Перед продолжением проверьте объём диска.${PLAIN}")"
        return 0
    fi
    if (( available_bytes < required_bytes )); then
        echo -e "$(localized_text "${RED}❌ ${operation}需要约 $(backup_human_size "$required_bytes")，${target} 仅剩 $(backup_human_size "$available_bytes")。操作已停止。${PLAIN}" "${RED}❌ ${operation} needs about $(backup_human_size "$required_bytes"), but ${target} has only $(backup_human_size "$available_bytes") free. Operation stopped.${PLAIN}" "${RED}❌ Для операции «${operation}» требуется около $(backup_human_size "$required_bytes"), а в ${target} свободно только $(backup_human_size "$available_bytes"). Операция остановлена.${PLAIN}")"
        return 1
    fi
    echo -e "$(localized_text "${GREEN}空间预检通过：需要约 $(backup_human_size "$required_bytes")，可用 $(backup_human_size "$available_bytes")。${PLAIN}" "${GREEN}Space check passed: about $(backup_human_size "$required_bytes") required, $(backup_human_size "$available_bytes") available.${PLAIN}" "${GREEN}Проверка места пройдена: требуется около $(backup_human_size "$required_bytes"), доступно $(backup_human_size "$available_bytes").${PLAIN}")"
}

backup_copy_xui_databases() {
    local manifest_file="$1"
    local work_dir="$2"
    local copied=1
    local db suffix src
    local db_paths=(
        "/etc/x-ui/x-ui.db"
        "/usr/local/x-ui/x-ui.db"
        "/usr/local/x-ui/bin/x-ui.db"
    )

    for db in "${db_paths[@]}"; do
        for suffix in "" "-wal" "-shm"; do
            src="${db}${suffix}"
            if backup_copy_path "$src" "${src#/}" "$manifest_file" "$work_dir"; then
                copied=0
            fi
        done
    done
    return "$copied"
}

backup_copy_managed_configuration() {
    local manifest_file="$1"
    local work_dir="$2"
    local copied=1

    backup_copy_path /etc/ssh/sshd_config etc/ssh/sshd_config "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/hostname etc/hostname "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/hosts etc/hosts "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/nginx/nginx.conf etc/nginx/nginx.conf "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/nginx/stream.d etc/nginx/stream.d "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/nginx/conf.d etc/nginx/conf.d "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/nginx/sites-available etc/nginx/sites-available "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/nginx/sites-enabled etc/nginx/sites-enabled "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/caddy/Caddyfile etc/caddy/Caddyfile "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/caddy/conf.d etc/caddy/conf.d "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/caddy/certs etc/caddy/certs "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /root/cert root/cert "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /root/.acme.sh root/.acme.sh "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /root/.config/vps-panel/cloudflare.env root/.config/vps-panel/cloudflare.env "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/vps-optimize/sni-stack.env etc/vps-optimize/sni-stack.env "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/vps-optimize/sni-stack.last-backup etc/vps-optimize/sni-stack.last-backup "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/vps-optimize/443-engine.conf etc/vps-optimize/443-engine.conf "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/vps-optimize/vpso-mux.yaml etc/vps-optimize/vpso-mux.yaml "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/systemd/system/vpso-mux.service etc/systemd/system/vpso-mux.service "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /usr/local/bin/vpso-mux usr/local/bin/vpso-mux "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/vps-optimize/traffic-guard.conf etc/vps-optimize/traffic-guard.conf "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /var/lib/vps-optimize/traffic-guard var/lib/vps-optimize/traffic-guard "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /usr/local/bin/vps-traffic-guard-check usr/local/bin/vps-traffic-guard-check "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/systemd/system/vps-traffic-guard.service etc/systemd/system/vps-traffic-guard.service "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/systemd/system/vps-traffic-guard.timer etc/systemd/system/vps-traffic-guard.timer "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/resolv.conf etc/resolv.conf "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/systemd/resolved.conf.d/99-vps-optimize-dns.conf etc/systemd/resolved.conf.d/99-vps-optimize-dns.conf "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/docker/daemon.json etc/docker/daemon.json "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/fail2ban/jail.local etc/fail2ban/jail.local "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/sysctl.d etc/sysctl.d "$manifest_file" "$work_dir" && copied=0
    backup_copy_path /etc/x-ui etc/x-ui "$manifest_file" "$work_dir" && copied=0
    backup_copy_xui_databases "$manifest_file" "$work_dir" && copied=0
    return "$copied"
}

backup_resolve_custom_directory() {
    local input_path="$1"
    local resolved_path

    [[ "$input_path" == /* && "$input_path" != "/" ]] || return 1
    resolved_path=$(cd -- "$input_path" 2>/dev/null && pwd -P) || return 1
    case "$resolved_path" in
        /proc|/proc/*|/sys|/sys/*|/dev|/dev/*|/run|/run/*|/tmp|/tmp/*) return 1 ;;
    esac
    printf '%s' "$resolved_path"
}

backup_collect_custom_directories() {
    local array_name="$1"
    local -n directory_list="$array_name"
    local input_path resolved_path existing duplicate

    directory_list=()
    echo -e "$(localized_text "${CYAN}每行填写一个要备份的绝对目录，留空结束。${PLAIN}" "${CYAN}Enter one absolute directory per line; leave blank to finish.${PLAIN}" "${CYAN}Введите один абсолютный каталог в строке; пустая строка завершает ввод.${PLAIN}")"
    echo -e "$(localized_text "示例：/etc、/usr、/home 或 /var/lib/myapp；不支持 /、/proc、/sys、/dev、/run、/tmp。" "Example: /etc, /usr, /home, or /var/lib/myapp. /, /proc, /sys, /dev, /run, and /tmp are not supported." "Пример: /etc, /usr, /home или /var/lib/myapp. /, /proc, /sys, /dev, /run и /tmp не поддерживаются.")"
    while true; do
        IFS= read -r -p "$(localized_text "目录: " "Directory: " "Каталог: ")" input_path || return 1
        input_path=$(trim_input "$input_path")
        [[ -n "$input_path" ]] || break
        if ! resolved_path=$(backup_resolve_custom_directory "$input_path"); then
            echo -e "$(localized_text "${RED}❌ 目录无效或不允许备份。${PLAIN}" "${RED}❌ Directory is invalid or cannot be backed up.${PLAIN}" "${RED}❌ Каталог недопустим или его нельзя резервировать.${PLAIN}")"
            continue
        fi
        duplicate=0
        for existing in "${directory_list[@]}"; do
            if [[ "$existing" == "$resolved_path" ]]; then
                duplicate=1
                break
            fi
        done
        [[ "$duplicate" -eq 1 ]] && continue
        directory_list+=("$resolved_path")
        echo -e "$(localized_text "${GREEN}已加入：${resolved_path}${PLAIN}" "${GREEN}Added: ${resolved_path}${PLAIN}" "${GREEN}Добавлено: ${resolved_path}${PLAIN}")"
    done
    [[ ${#directory_list[@]} -gt 0 ]]
}

backup_select_archive_directory() {
    local default_dir="$1"
    local input_path

    while true; do
        IFS= read -r -p "$(localized_text "备份存放目录 [${default_dir}]: " "Backup storage directory [${default_dir}]: " "Каталог хранения резервной копии [${default_dir}]: ")" input_path || return 1
        input_path=$(trim_input "$input_path")
        input_path=${input_path:-$default_dir}
        if [[ "$input_path" != /* || "$input_path" == "/" ]]; then
            echo -e "$(localized_text "${RED}❌ 请填写非根目录的绝对路径。${PLAIN}" "${RED}❌ Enter an absolute path other than /.${PLAIN}" "${RED}❌ Укажите абсолютный путь, отличный от /.${PLAIN}")"
            continue
        fi
        if mkdir -p -- "$input_path" 2>/dev/null; then
            BACKUP_ARCHIVE_ROOT="$input_path"
            return 0
        fi
        echo -e "$(localized_text "${RED}❌ 无法创建或写入该目录。${PLAIN}" "${RED}❌ Cannot create or write to this directory.${PLAIN}" "${RED}❌ Не удалось создать каталог или записать в него.${PLAIN}")"
    done
}

backup_archive_is_readable() {
    local archive_file="$1"
    [[ -f "$archive_file" && -r "$archive_file" ]] || return 1
    [[ "$archive_file" == *.tar.gz || "$archive_file" == *.tar.gz.enc ]]
}

backup_archive_is_encrypted() {
    [[ "${1:-}" == *.tar.gz.enc ]]
}

backup_read_new_password() {
    local output_name="$1"
    local -n output_password="$output_name"
    local first second

    while true; do
        read_secret_trimmed first "$(localized_text "备份加密密码: " "Backup encryption password: " "Пароль шифрования резервной копии: ")"
        if [[ ${#first} -lt 10 ]]; then
            echo -e "$(localized_text "${YELLOW}密码至少需要 10 个字符。${PLAIN}" "${YELLOW}The password must contain at least 10 characters.${PLAIN}" "${YELLOW}Пароль должен содержать не менее 10 символов.${PLAIN}")"
            continue
        fi
        read_secret_trimmed second "$(localized_text "再次输入密码: " "Enter the password again: " "Введите пароль ещё раз: ")"
        if [[ "$first" == "$second" ]]; then
            output_password="$first"
            first=""
            second=""
            return 0
        fi
        first=""
        second=""
        echo -e "$(localized_text "${YELLOW}两次密码不一致，请重新输入。${PLAIN}" "${YELLOW}The passwords do not match. Try again.${PLAIN}" "${YELLOW}Пароли не совпадают. Повторите ввод.${PLAIN}")"
    done
}

backup_create_archive() {
    local work_dir="$1"
    local archive_file="$2"
    local password="${3:-}"

    if backup_archive_is_encrypted "$archive_file"; then
        (
            set -o pipefail
            umask 077
            exec 3<<<"$password"
            tar -czf - -C "$work_dir" . | openssl enc -aes-256-cbc -salt -pbkdf2 -iter 200000 -pass fd:3 -out "$archive_file"
        ) >/dev/null 2>&1 || return 1
        (
            set -o pipefail
            exec 3<<<"$password"
            openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -pass fd:3 -in "$archive_file" | tar -tzf - >/dev/null
        ) 2>/dev/null
    else
        ( umask 077 && tar -czf "$archive_file" -C "$work_dir" . ) >/dev/null 2>&1 || return 1
        tar -tzf "$archive_file" >/dev/null 2>&1
    fi
}

backup_decrypt_archive() {
    local archive_file="$1"
    local output_file="$2"
    local password="$3"

    (
        umask 077
        exec 3<<<"$password"
        openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -pass fd:3 -in "$archive_file" -out "$output_file"
    ) >/dev/null 2>&1
}

backup_register_archive_root() {
    local archive_root="$1"
    local roots_file="/etc/vps-optimize/backup-archive-roots.conf"

    [[ "$archive_root" == /* && "$archive_root" != "/" ]] || return 1
    mkdir -p /etc/vps-optimize || return 1
    touch "$roots_file" || return 1
    chmod 600 "$roots_file" 2>/dev/null || true
    grep -Fqx -- "$archive_root" "$roots_file" 2>/dev/null || printf '%s\n' "$archive_root" >> "$roots_file"
}

backup_collect_archive_roots() {
    local array_name="$1"
    local -n root_list="$array_name"
    local roots_file="/etc/vps-optimize/backup-archive-roots.conf"
    local root existing duplicate

    root_list=()
    while IFS= read -r root; do
        [[ "$root" == /* && "$root" != "/" && -d "$root" ]] || continue
        duplicate=0
        for existing in "${root_list[@]}"; do
            [[ "$existing" == "$root" ]] && duplicate=1 && break
        done
        [[ "$duplicate" -eq 1 ]] || root_list+=("$root")
    done < <(
        printf '%s\n' "/etc/vps-optimize/backups/manual" "/backups" "/root/backups"
        [[ -f "$roots_file" ]] && sed -n '/^\//p' "$roots_file"
    )
}

backup_collect_available_archives() {
    local array_name="$1"
    local -n archive_list="$array_name"
    local -a roots=()
    local root archive existing duplicate

    archive_list=()
    backup_collect_archive_roots roots
    for root in "${roots[@]}"; do
        while IFS= read -r archive; do
            backup_archive_is_readable "$archive" || continue
            duplicate=0
            for existing in "${archive_list[@]}"; do
                [[ "$existing" == "$archive" ]] && duplicate=1 && break
            done
            [[ "$duplicate" -eq 1 ]] || archive_list+=("$archive")
        done < <(ls -1t "$root"/*.tar.gz "$root"/*.tar.gz.enc 2>/dev/null)
    done
}

backup_select_available_archive() {
    local output_name="$1"
    local -n selected_archive="$output_name"
    local -a archives=()
    local choice i

    backup_collect_available_archives archives
    if [[ ${#archives[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未自动读取到可用的 .tar.gz 或 .tar.gz.enc 备份包。${PLAIN}" "${YELLOW}⚠️ No usable .tar.gz or .tar.gz.enc backup archive was found automatically.${PLAIN}" "${YELLOW}⚠️ Не найден доступный архив .tar.gz или .tar.gz.enc.${PLAIN}")"
        return 1
    fi

    echo -e "$(localized_text "${CYAN}可加载备份：${PLAIN}" "${CYAN}Loadable backups:${PLAIN}" "${CYAN}Доступные для загрузки копии:${PLAIN}")"
    for i in "${!archives[@]}"; do
        echo -e "  ${GREEN}$((i + 1)).${PLAIN} $(basename "${archives[$i]}") ${YELLOW}($(dirname "${archives[$i]}"))${PLAIN}"
    done
    read_trimmed choice "$(localized_text "输入备份序号: " "Enter backup number: " "Введите номер резервной копии: ")"
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#archives[@]} )); then
        echo -e "$(localized_text "${RED}❌ 无效序号。${PLAIN}" "${RED}❌ Invalid number.${PLAIN}" "${RED}❌ Неверный номер.${PLAIN}")"
        return 1
    fi
    selected_archive="${archives[$((choice - 1))]}"
}

backup_copy_custom_directories() {
    local manifest_file="$1"
    local work_dir="$2"
    local array_name="$3"
    local -n directory_list="$array_name"
    local mapping_file="${work_dir}/custom-paths.txt"
    local directory dest_rel
    local copied=1

    for directory in "${directory_list[@]}"; do
        dest_rel="custom${directory}"
        if backup_copy_path "$directory" "$dest_rel" "$manifest_file" "$work_dir"; then
            printf '%s|%s\n' "$dest_rel" "$directory" >> "$mapping_file"
            copied=0
        fi
    done
    [[ "$copied" -eq 0 ]] || rm -f "$mapping_file"
    return "$copied"
}

backup_restore_preflight() {
    local restore_dir="$1"
    local missing=0

    echo -e "$(localized_text "${CYAN}恢复环境预检：${PLAIN}" "${CYAN}Restore environment preflight:${PLAIN}" "${CYAN}Предварительная проверка среды восстановления:${PLAIN}")"
    if [[ -e "$restore_dir/etc/nginx/nginx.conf" || -d "$restore_dir/etc/nginx" ]] && ! command -v nginx >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}- Nginx 配置在备份中，但新系统未安装 Nginx。${PLAIN}" "${YELLOW}- Nginx configuration is in the backup, but Nginx is not installed on this system.${PLAIN}" "${YELLOW}- Конфигурация Nginx есть в резервной копии, но Nginx не установлен в системе.${PLAIN}")"
        missing=1
    fi
    if [[ -e "$restore_dir/etc/caddy/Caddyfile" || -d "$restore_dir/etc/caddy" ]] && ! command -v caddy >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}- Caddy 配置在备份中，但新系统未安装 Caddy。${PLAIN}" "${YELLOW}- Caddy configuration is in the backup, but Caddy is not installed on this system.${PLAIN}" "${YELLOW}- Конфигурация Caddy есть в резервной копии, но Caddy не установлен в системе.${PLAIN}")"
        missing=1
    fi
    if [[ -e "$restore_dir/etc/docker/daemon.json" ]] && ! command -v docker >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}- Docker 配置在备份中，但新系统未安装 Docker。${PLAIN}" "${YELLOW}- Docker configuration is in the backup, but Docker is not installed on this system.${PLAIN}" "${YELLOW}- Конфигурация Docker есть в резервной копии, но Docker не установлен в системе.${PLAIN}")"
        missing=1
    fi
    if [[ -d "$restore_dir/etc/x-ui" ]] && [[ ! -d /etc/x-ui && ! -d /usr/local/x-ui ]]; then
        echo -e "$(localized_text "${YELLOW}- 3x-ui 配置在备份中，但新系统未检测到 3x-ui。${PLAIN}" "${YELLOW}- 3x-ui configuration is in the backup, but 3x-ui was not detected on this system.${PLAIN}" "${YELLOW}- Конфигурация 3x-ui есть в резервной копии, но 3x-ui не обнаружен в системе.${PLAIN}")"
        missing=1
    fi
    if [[ -f "$restore_dir/custom-paths.txt" ]]; then
        echo -e "$(localized_text "${YELLOW}- 备份包含自定义系统目录，恢复会覆盖这些目录。${PLAIN}" "${YELLOW}- The backup contains custom system directories; restoring will overwrite them.${PLAIN}" "${YELLOW}- Резервная копия содержит пользовательские системные каталоги; восстановление перезапишет их.${PLAIN}")"
    fi
    [[ "$missing" -eq 0 ]] || echo -e "$(localized_text "${YELLOW}缺少的服务不会自动安装；恢复文件后请安装并启动对应服务。${PLAIN}" "${YELLOW}Missing services are not installed automatically. Install and start them after restoring the files.${PLAIN}" "${YELLOW}Отсутствующие службы не устанавливаются автоматически. После восстановления файлов установите и запустите их.${PLAIN}")"
}

backup_restore_custom_directories() {
    local restore_dir="$1"
    local quarantine_root="$2"
    local mapping_file="${restore_dir}/custom-paths.txt"
    local dest_rel target_path
    local failed=0

    [[ -f "$mapping_file" ]] || return 0
    while IFS='|' read -r dest_rel target_path; do
        [[ "$dest_rel" == "custom${target_path}" && "$target_path" == /* && "$target_path" != "/" ]] || return 1
        case "$target_path" in
            /proc|/proc/*|/sys|/sys/*|/dev|/dev/*|/run|/run/*|/tmp|/tmp/*) return 1 ;;
        esac
        [[ -d "$restore_dir/$dest_rel" ]] || return 1
        if [[ "${target_path#/}" == */* ]]; then
            restore_backup_dir "$restore_dir/$dest_rel" "$target_path" "$quarantine_root" || failed=1
        else
            mkdir -p "$target_path" && cp -a -- "$restore_dir/$dest_rel/." "$target_path/" || failed=1
        fi
    done < "$mapping_file"
    return "$failed"
}

redact_sensitive_output() {
    sed -E \
        -e 's/(authorization:[[:space:]]*(bearer|basic)[[:space:]]+)[^[:space:]]+/\1***REDACTED***/gI' \
        -e 's/((^|[^[:alnum:]_])(token|password|passwd|secret|api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret|CF_Token|CF_Key)[[:space:]]*[=:][[:space:]]*)[^[:space:],;"'\''}]+/\1***REDACTED***/gI' \
        -e 's/("(token|password|passwd|secret|api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret|CF_Token|CF_Key)"[[:space:]]*:[[:space:]]*")[^"]+/\1***REDACTED***/gI' \
        -e 's/([?&](token|password|passwd|secret|api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret)=)[^&[:space:]]+/\1***REDACTED***/gI' \
        -e 's#(https?://)[^/@[:space:]]+@#\1***REDACTED***@#g'
}

dns_backup_current_config() {
    local ts backup_dir
    ts=$(date +%Y%m%d_%H%M%S)
    backup_dir="${DNS_OPTIMIZE_BACKUP_DIR}/${ts}"
    mkdir -p "$backup_dir"
    chmod 700 "$DNS_OPTIMIZE_BACKUP_DIR" "$backup_dir" 2>/dev/null || true
    [[ -e /etc/resolv.conf || -L /etc/resolv.conf ]] && cp -a /etc/resolv.conf "$backup_dir/resolv.conf" 2>/dev/null || true
    [[ -f "$DNS_OPTIMIZE_RESOLVED_DROPIN" ]] && cp -a "$DNS_OPTIMIZE_RESOLVED_DROPIN" "$backup_dir/99-vps-optimize-dns.conf" 2>/dev/null || true
    echo "$backup_dir" > "${DNS_OPTIMIZE_BACKUP_DIR}/last" 2>/dev/null || true
    echo "$backup_dir"
}

applied_config_editor_command() {
    local editor="${EDITOR:-}"
    if [[ -n "$editor" && "$editor" != *" "* ]] && command -v "$editor" >/dev/null 2>&1; then
        printf '%s' "$editor"
        return 0
    fi

    local candidate
    for candidate in nano vim vi; do
        if command -v "$candidate" >/dev/null 2>&1; then
            printf '%s' "$candidate"
            return 0
        fi
    done
    return 1
}

append_applied_config_file() {
    local label="$1"
    local path="$2"
    local kind="$3"
    local existing

    [[ -e "$path" || -L "$path" ]] || return 0
    for existing in "${applied_config_paths[@]}"; do
        [[ "$existing" == "$path" ]] && return 0
    done

    applied_config_labels+=("$label")
    applied_config_paths+=("$path")
    applied_config_kinds+=("$kind")
}

collect_applied_config_files() {
    local scope="${1:-all}"
    local conf_file

    applied_config_labels=()
    applied_config_paths=()
    applied_config_kinds=()

    append_applied_config_file "$(localized_text "Caddy 主配置" "Caddy main configuration" "Основная конфигурация Caddy")" "/etc/caddy/Caddyfile" "caddy"
    for conf_file in /etc/caddy/conf.d/*.caddy; do
        [[ -f "$conf_file" ]] && append_applied_config_file "$(localized_text "Caddy 站点 $(basename "$conf_file")" "Caddy site $(basename \"$conf_file\")" "Caddy сайт $(basename \"$conf_file\")")" "$conf_file" "caddy"
    done
    append_applied_config_file "$(localized_text "Nginx 主配置" "Nginx main configuration" "Основная конфигурация Nginx")" "/etc/nginx/nginx.conf" "nginx"
    for conf_file in /etc/nginx/conf.d/*.conf; do
        [[ -f "$conf_file" ]] && append_applied_config_file "Nginx conf.d $(basename "$conf_file")" "$conf_file" "nginx"
    done
    for conf_file in /etc/nginx/sites-enabled/*; do
        [[ -f "$conf_file" ]] && append_applied_config_file "Nginx sites-enabled $(basename "$conf_file")" "$conf_file" "nginx"
    done

    [[ "$scope" == "proxy" ]] && return 0

    for conf_file in /etc/nginx/stream.d/*.conf; do
        [[ -f "$conf_file" ]] && append_applied_config_file "Nginx stream.d $(basename "$conf_file")" "$conf_file" "nginx"
    done
    append_applied_config_file "$(localized_text "443端口复用参数" "Port 443 Reuse Parameters" "Параметры повторного использования порта 443")" "/etc/vps-optimize/sni-stack.env" "entry-mode"
    append_applied_config_file "$(localized_text "443 引擎状态" "443 Engine status" "443 Статус двигателя")" "/etc/vps-optimize/443-engine.conf" "entry-mode"
    append_applied_config_file "$(localized_text "Xray SNI 分流记录" "Xray SNI routing record" "Xray SNI маршрутизирующая пластинка")" "/etc/vps-optimize/xray-sni-routes.conf" "xray-routes"
    append_applied_config_file "$(localized_text "TCP Peek vpso-mux 配置" "TCP Peek vpso-mux configuration" "Конфигурация TCP Peek vpso-mux")" "/etc/vps-optimize/vpso-mux.yaml" "vpso-mux"
    append_applied_config_file "vpso-mux systemd" "/etc/systemd/system/vpso-mux.service" "systemd"
    append_applied_config_file "$(localized_text "vpso-mux 8444 预检 systemd" "vpso-mux 8444 preflight check systemd" "vpso-mux 8444 Предварительная проверка systemd")" "/etc/systemd/system/vpso-mux-preflight.service" "systemd"
    append_applied_config_file "$(localized_text "Traffic Guard 配置" "Traffic Guard configuration" "Конфигурация Traffic Guard")" "$TRAFFIC_GUARD_CONFIG" "traffic-guard"
    append_applied_config_file "Traffic Guard service" "/etc/systemd/system/vps-traffic-guard.service" "systemd"
    append_applied_config_file "Traffic Guard timer" "/etc/systemd/system/vps-traffic-guard.timer" "systemd"
    append_applied_config_file "$(localized_text "Cloudflare DNS API 配置" "Cloudflare DNS API configuration" "Cloudflare DNS Конфигурация API")" "/root/.config/vps-panel/cloudflare.env" "env"
    append_applied_config_file "Docker daemon.json" "/etc/docker/daemon.json" "docker-json"
    append_applied_config_file "$(localized_text "SSH 主配置" "SSH main configuration" "Основная конфигурация SSH")" "/etc/ssh/sshd_config" "ssh"
    for conf_file in /etc/ssh/sshd_config.d/*.conf; do
        [[ -f "$conf_file" ]] && append_applied_config_file "SSH drop-in $(basename "$conf_file")" "$conf_file" "ssh"
    done
    append_applied_config_file "$(localized_text "Hosts 文件" "Hosts file" "Файл хостов")" "/etc/hosts" "hosts"
    append_applied_config_file "$(localized_text "Hostname 文件" "Hostname file" "Файл имени хоста")" "/etc/hostname" "hostname"
    append_applied_config_file "DNS resolv.conf" "/etc/resolv.conf" "dns"
    append_applied_config_file "systemd-resolved DNS drop-in" "$DNS_OPTIMIZE_RESOLVED_DROPIN" "dns"
    append_applied_config_file "Fail2ban jail.local" "/etc/fail2ban/jail.local" "fail2ban"
    append_applied_config_file "x-ui config.json" "/usr/local/x-ui/bin/config.json" "xui-json"
    for conf_file in /etc/sysctl.d/*.conf; do
        [[ -f "$conf_file" ]] && append_applied_config_file "sysctl.d $(basename "$conf_file")" "$conf_file" "sysctl"
    done
    for conf_file in /opt/sublinkpro/docker-compose.yml /opt/miaomiaowu/docker-compose.yml /opt/sub-store/docker-compose.yml /opt/dockge/docker-compose.yml /opt/komari/docker-compose.yml /opt/*/compose.yaml /opt/*/compose.yml /opt/*/docker-compose.yml /opt/*/docker-compose.yaml; do
        [[ -f "$conf_file" ]] && append_applied_config_file "Compose $(basename "$(dirname "$conf_file")")/$(basename "$conf_file")" "$conf_file" "compose"
    done
}

validate_xray_routes_file() {
    local target_file="$1"
    awk -F'|' '
        /^[[:space:]]*($|#)/ { next }
        { for (i = 1; i <= NF; i++) gsub(/^[[:space:]]+|[[:space:]]+$/, "", $i) }
        NF != 3 { exit 1 }
        $1 == "" || $2 == "" || $3 !~ /^[0-9]+$/ || $3 < 1 || $3 > 65535 { exit 1 }
    ' "$target_file"
}

validate_hosts_file() {
    local target_file="$1"
    awk '
        /^[[:space:]]*($|#)/ { next }
        NF < 2 { exit 1 }
    ' "$target_file"
}

validate_hostname_file() {
    local target_file="$1"
    local hostname_value
    hostname_value=$(head -n1 "$target_file" 2>/dev/null | tr -d '[:space:]')
    [[ -n "$hostname_value" && "$hostname_value" != *"/"* ]]
}

validate_json_file() {
    local target_file="$1"
    if command -v jq >/dev/null 2>&1; then
        jq empty "$target_file"
    elif command -v python3 >/dev/null 2>&1; then
        python3 -m json.tool "$target_file" >/dev/null
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 jq/python3，已跳过 JSON 语法校验。${PLAIN}" "${YELLOW}⚠️ jq/python3 not detected, JSON syntax check skipped.${PLAIN}" "${YELLOW}⚠️ jq/python3 не обнаружен, проверка синтаксиса JSON пропущена.${PLAIN}")"
        return 0
    fi
}

load_docker_compose_runtime_helper() {
    local helper_path
    local -a helper_paths=()

    declare -F ensure_docker_compose_ready >/dev/null 2>&1 && return 0

    if [[ -n "${SCRIPT_DIR:-}" ]]; then
        helper_paths+=("${SCRIPT_DIR}/src/compose_runtime.sh")
    fi
    helper_paths+=("$(dirname "${BASH_SOURCE[0]}")/compose_runtime.sh")

    for helper_path in "${helper_paths[@]}"; do
        [[ -f "$helper_path" ]] || continue
        # shellcheck source=/dev/null
        . "$helper_path"
        declare -F ensure_docker_compose_ready >/dev/null 2>&1 && return 0
    done

    return 1
}

run_applied_config_compose() {
    local target_file="$1"
    local project_dir
    shift

    if ! load_docker_compose_runtime_helper; then
        echo -e "$(localized_text "${RED}❌ 未加载 Docker Compose 自动安装/检测逻辑，无法应用 Compose 操作。${PLAIN}" "${RED}❌ The Docker Compose automatic installation/detection logic is not loaded and the Compose operation cannot be applied.${PLAIN}" "${RED}❌ Логика автоматической установки/обнаружения Docker Compose не загружена, и операцию Compose невозможно применить.${PLAIN}")"
        return 1
    fi

    ensure_docker_compose_ready || return 1
    project_dir=$(dirname "$target_file")
    (cd "$project_dir" && $DOCKER_COMPOSE_CMD -f "$target_file" "$@")
}

validate_applied_config_kind() {
    local kind="$1"
    local target_file="$2"

    case "$kind" in
        caddy)
            command -v caddy >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ 未检测到 caddy 命令，无法校验配置。${PLAIN}" "${RED}❌ The caddy command is not detected and the configuration cannot be verified.${PLAIN}" "${RED}❌ Команда caddy не обнаружена, и конфигурация не может быть проверена.${PLAIN}")"; return 1; }
            caddy validate --config /etc/caddy/Caddyfile
            ;;
        nginx)
            command -v nginx >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ 未检测到 nginx 命令，无法校验配置。${PLAIN}" "${RED}❌ The nginx command is not detected and the configuration cannot be verified.${PLAIN}" "${RED}❌ Команда nginx не обнаружена, и конфигурация не может быть проверена.${PLAIN}")"; return 1; }
            nginx -t
            ;;
        systemd)
            if command -v systemd-analyze >/dev/null 2>&1; then
                systemd-analyze verify "$target_file"
            else
                echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 systemd-analyze，已跳过 systemd unit 静态校验。${PLAIN}" "${YELLOW}⚠️ systemd-analyze is not detected and systemd unit static verification has been skipped.${PLAIN}" "${YELLOW}⚠️ systemd-анализ не обнаружен, а статическая проверка блока systemd пропущена.${PLAIN}")"
            fi
            ;;
        docker-json|xui-json)
            validate_json_file "$target_file"
            ;;
        compose)
            run_applied_config_compose "$target_file" config >/dev/null
            ;;
        ssh)
            command -v sshd >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ 未检测到 sshd 命令，无法校验 SSH 配置。${PLAIN}" "${RED}❌ The sshd command was not detected and the SSH configuration could not be verified.${PLAIN}" "${RED}❌ Команда sshd не обнаружена, и конфигурацию SSH проверить не удалось.${PLAIN}")"; return 1; }
            sshd -t
            ;;
        vpso-mux)
            if declare -F run_vpso_mux_config_check >/dev/null 2>&1; then
                run_vpso_mux_config_check "$target_file"
            elif [[ -x /usr/local/bin/vpso-mux ]]; then
                /usr/local/bin/vpso-mux -config "$target_file" -check
            else
                echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 vpso-mux 二进制，已跳过运行时配置校验。${PLAIN}" "${YELLOW}⚠️ vpso-mux binary not detected, runtime configuration validation skipped.${PLAIN}" "${YELLOW}⚠️ Двоичный файл vpso-mux не обнаружен, проверка конфигурации во время выполнения пропущена.${PLAIN}")"
            fi
            ;;
        entry-mode|traffic-guard|env)
            bash -n "$target_file"
            ;;
        xray-routes)
            validate_xray_routes_file "$target_file"
            ;;
        hosts)
            validate_hosts_file "$target_file"
            ;;
        hostname)
            validate_hostname_file "$target_file"
            ;;
        dns|sysctl)
            return 0
            ;;
        fail2ban)
            if command -v fail2ban-client >/dev/null 2>&1; then
                fail2ban-client -t
            else
                echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 fail2ban-client，已跳过 Fail2ban 配置校验。${PLAIN}" "${YELLOW}⚠️ fail2ban-client is not detected and Fail2ban configuration validation has been skipped.${PLAIN}" "${YELLOW}⚠️ fail2ban-клиент не обнаружен и проверка конфигурации Fail2ban пропущена.${PLAIN}")"
            fi
            ;;
        *)
            echo -e "$(localized_text "${YELLOW}⚠️ 未知配置类型 ${kind}，仅保存备份，不执行额外校验。${PLAIN}" "${YELLOW}⚠️ Unknown configuration type ${kind}, only save backup and do not perform additional verification.${PLAIN}" "${YELLOW}⚠️ Неизвестный тип конфигурации ${kind}, сохраняйте только резервную копию и не выполняйте дополнительную проверку.${PLAIN}")"
            ;;
    esac
}

restart_named_service_if_available() {
    local service_name="$1"
    local rc
    restart_service_if_available "$service_name"
    rc=$?
    [[ "$rc" -eq 0 || "$rc" -eq 2 ]]
}

reload_applied_config_kind() {
    local kind="$1"
    local target_file="$2"
    local previous_file="${3:-${target_file}.bak}"
    local unit_name

    case "$kind" in
        caddy)
            systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1
            ;;
        nginx)
            systemctl reload nginx >/dev/null 2>&1 || systemctl restart nginx >/dev/null 2>&1
            ;;
        systemd)
            systemctl daemon-reload >/dev/null 2>&1 || return 1
            unit_name=$(basename "$target_file")
            if confirm_danger \
                "$(localized_text "重启或重新加载 ${unit_name}" "Restart or reload ${unit_name}" "Перезапустить или перезагрузить ${unit_name}")" \
                "$(localized_text "立即让已编辑的 systemd 单元配置生效。" "Apply the edited systemd unit configuration immediately." "Немедленно применить изменённую конфигурацию systemd.")" \
                "$(localized_text "恢复 ${previous_file} 后执行 systemctl daemon-reload，并重新启动该单元。" "Restore ${previous_file}, run systemctl daemon-reload, and start the unit again." "Восстановите ${previous_file}, выполните systemctl daemon-reload и снова запустите службу.")"; then
                systemctl try-reload-or-restart "$unit_name" >/dev/null 2>&1 || systemctl restart "$unit_name" >/dev/null 2>&1
            else
                echo -e "$(localized_text "${BLUE}unit 修改已保存，${unit_name} 尚未重启。${PLAIN}" "${BLUE}The unit change is saved; ${unit_name} has not been restarted.${PLAIN}" "${BLUE}Изменения unit сохранены; ${unit_name} не перезапущен.${PLAIN}")"
            fi
            ;;
        docker-json)
            if confirm_danger \
                "$(localized_text "重启 Docker" "Restart Docker" "Перезапустить Docker")" \
                "$(localized_text "应用已校验的 daemon.json；运行中容器的网络可能短暂中断。" "Apply the validated daemon.json; networking for running containers may be interrupted briefly." "Применить проверенный daemon.json; сеть запущенных контейнеров может кратковременно прерваться.")" \
                "$(localized_text "恢复 ${previous_file} 后再次重启 Docker。" "Restore ${previous_file} and restart Docker again." "Восстановите ${previous_file} и снова перезапустите Docker.")"; then
                restart_named_service_if_available docker
            else
                echo -e "$(localized_text "${YELLOW}⚠️ Docker 未重启，daemon.json 修改尚未生效。${PLAIN}" "${YELLOW}⚠️ Docker has not restarted, and the modification of daemon.json has not yet taken effect.${PLAIN}" "${YELLOW}⚠️ Docker не перезапустился, а модификация daemon.json еще не вступила в силу.${PLAIN}")"
            fi
            ;;
        compose)
            if confirm_danger \
                "$(localized_text "应用 Compose 配置" "Apply the Compose configuration" "Применить конфигурацию Compose")" \
                "$(localized_text "执行 up -d；相关容器可能被创建、重建或重启。" "Run up -d; related containers may be created, recreated, or restarted." "Выполнить up -d; связанные контейнеры могут быть созданы, пересозданы или перезапущены.")" \
                "$(localized_text "恢复 ${previous_file} 后再次执行 Compose up -d。" "Restore ${previous_file} and run Compose up -d again." "Восстановите ${previous_file} и снова выполните Compose up -d.")"; then
                run_applied_config_compose "$target_file" up -d
            else
                echo -e "$(localized_text "${YELLOW}⚠️ Compose 修改已保存，但尚未应用到容器。${PLAIN}" "${YELLOW}⚠️ The Compose change is saved but has not been applied to the containers.${PLAIN}" "${YELLOW}⚠️ Изменения Compose сохранены, но ещё не применены к контейнерам.${PLAIN}")"
            fi
            ;;
        ssh)
            if confirm_risk_action "$(localized_text "重启 SSH 服务" "Restart SSH service" "Перезапустите службу SSH.")" \
                "$(localized_text "当前 SSH 服务运行状态" "Current SSH service running status" "Текущее состояние работы службы SSH")" \
                "$(localized_text "使用当前未断开的 SSH 会话恢复 ${target_file}.bak_*，或通过云厂商控制台恢复 SSH 配置" "Use the currently undisconnected SSH session to restore ${target_file}.bak_*, or restore the SSH configuration through the cloud vendor console" "Используйте текущий неотключенный сеанс SSH для восстановления ${target_file}.bak_* или восстановите конфигурацию SSH через консоль облачного поставщика.")" \
                "$(localized_text "确认新 SSH 配置已经通过 sshd -t 校验。" "Confirm that the new SSH configuration has passed sshd -t verification." "Убедитесь, что новая конфигурация SSH прошла проверку sshd -t.")"; then
                restart_service_if_available sshd >/dev/null 2>&1 || restart_service_if_available ssh >/dev/null 2>&1
            else
                echo -e "$(localized_text "${YELLOW}⚠️ SSH 未重启，修改可能尚未生效。${PLAIN}" "${YELLOW}⚠️ SSH has not been restarted, and the modification may not yet take effect.${PLAIN}" "${YELLOW}⚠️ SSH не был перезапущен, и модификация может еще не вступить в силу.${PLAIN}")"
            fi
            ;;
        vpso-mux)
            if confirm_risk_action "$(localized_text "重启 vpso-mux" "Restart vpso-mux" "Перезагрузите vpso-mux.")" \
                "$(localized_text "TCP Peek/vpso-mux 分流器运行进程" "TCP Peek/vpso-mux routing running process" "Процесс работы маршрутизации TCP Peek/vpso-mux")" \
                "$(localized_text "使用当前未断开的 SSH 会话恢复 ${target_file}.bak_*，或回到 443端口复用菜单重新应用/回滚入口模式" "Restore ${target_file}.bak_* using the currently undisconnected SSH session, or return to the Port 443 Reuse menu to reapply/rollback entry mode" "Восстановите ${target_file}.bak_*, используя текущий неотключенный сеанс SSH, или вернитесь в меню повторное использование порта 443, чтобы повторно применить/откатить режим входа.")" \
                "$(localized_text "确认公网 443 当前入口模式和本机后端端口都正常。" "Confirm that the current entry mode of public port 443 and the local backend port are normal." "Убедитесь, что текущий режим входа в публичный порт 443 и локальный внутренний порт являются нормальными.")"; then
                restart_named_service_if_available vpso-mux
            else
                echo -e "$(localized_text "${YELLOW}⚠️ vpso-mux 未重启，修改尚未生效。${PLAIN}" "${YELLOW}⚠️ vpso-mux has not been restarted and the modification has not yet taken effect.${PLAIN}" "${YELLOW}⚠️ vpso-mux не был перезапущен и модификация еще не вступила в силу.${PLAIN}")"
            fi
            ;;
        entry-mode|xray-routes)
            if declare -F reapply_current_entry_mode >/dev/null 2>&1; then
                if confirm_risk_action "$(localized_text "重新应用当前 443 入口模式" "Reapply current 443 entry pattern" "Повторно применить текущий шаблон входа 443")" \
                    "$(localized_text "公网 443 入口配置、Caddy/Nginx/vpso-mux/Xray 相关路由" "public port 443 entry configuration, Caddy/Nginx/vpso-mux/Xray related routes" "Конфигурация входа в публичную сеть 443, маршруты, связанные с Caddy/Nginx/vpso-mux/Xray")" \
                    "$(localized_text "脚本会创建入口模式备份并在失败时回滚；也可从备份与回滚中心恢复" "Script creates entry mode backup and rolls back on failure; can also be restored from the Backup and Rollback Center" "Скрипт создает резервную копию в режим входа и выполняет откат в случае сбоя; также можно восстановить из Центра резервного копирования и отката.")" \
                    "$(localized_text "确认配置文件中的域名、端口和 ENTRY_MODE 值已经匹配。" "Confirm that the domain, port, and ENTRY_MODE value in the configuration file match." "Убедитесь, что имя домена, порт и значение ENTRY_MODE в файле конфигурации совпадают.")"; then
                    reapply_current_entry_mode
                else
                    echo -e "$(localized_text "${YELLOW}⚠️ 已保存配置，但未重新应用 443 入口模式。${PLAIN}" "${YELLOW}⚠️ Configuration saved, but 443 entry mode was not reapplied.${PLAIN}" "${YELLOW}⚠️ Конфигурация сохранена, но режим входа 443 не был применен повторно.${PLAIN}")"
                fi
            else
                echo -e "$(localized_text "${YELLOW}⚠️ 已保存配置；请回到 443端口复用菜单重新应用当前入口模式。${PLAIN}" "${YELLOW}⚠️ The configuration has been saved; please return to the Port 443 Reuse menu to reapply the current entry mode.${PLAIN}" "${YELLOW}⚠️ Конфигурация сохранена; вернитесь в меню повторного использования порта 443, чтобы повторно применить текущий режим ввода.${PLAIN}")"
            fi
            ;;
        traffic-guard)
            if [[ -n "$previous_file" ]] && declare -F traffic_guard_restore_ssh_only_firewall_from_config >/dev/null 2>&1; then
                traffic_guard_restore_ssh_only_firewall_from_config "$previous_file" || {
                    echo -e "$(localized_text "${RED}❌ 无法解除编辑前配置的仅保留 SSH 封锁规则，已取消应用。${PLAIN}" "${RED}❌ The keep-only SSH blocking rule configured before editing cannot be released and the application has been cancelled.${PLAIN}" "${RED}❌ Правило блокировки SSH «только сохранение», настроенное до редактирования, не может быть отменено, и приложение было отменено.${PLAIN}")"
                    return 1
                }
            fi
            if confirm_risk_action "$(localized_text "重启 Traffic Guard timer" "Restart Traffic Guard timer" "Перезапустить таймер Traffic Guard")" \
                "$(localized_text "vps-traffic-guard.timer 和流量阈值检查周期" "vps-traffic-guard.timer and traffic threshold check period" "vps-traffic-guard.timer и период проверки порога трафика")" \
                "$(localized_text "重新编辑 ${target_file} 或从 ${target_file}.bak_* 恢复；必要时停用 vps-traffic-guard.timer" "Re-edit ${target_file} or restore from ${target_file}.bak_*; disable vps-traffic-guard.timer if necessary" "Отредактируйте ${target_file} повторно или восстановите из ${target_file}.bak_*; при необходимости отключите vps-traffic-guard.timer")" \
                "$(localized_text "如果 ACTION=poweroff，请确认阈值、账单周期和云厂商救援方式。" "If ACTION=poweroff, confirm the threshold, billing cycle, and cloud vendor rescue method." "Если ACTION=poweroff, подтвердите пороговое значение, цикл выставления счетов и метод восстановления поставщика облачных услуг.")"; then
                systemctl daemon-reload >/dev/null 2>&1 || true
                systemctl restart vps-traffic-guard.timer >/dev/null 2>&1
            else
                echo -e "$(localized_text "${YELLOW}⚠️ Traffic Guard timer 未重启，下一次运行前请确认配置已生效。${PLAIN}" "${YELLOW}⚠️ Traffic Guard timer has not been restarted. Please confirm that the configuration has taken effect before running it next time.${PLAIN}" "${YELLOW}⚠️ Таймер Traffic Guard не был перезапущен. Пожалуйста, подтвердите, что конфигурация вступила в силу, прежде чем запускать ее в следующий раз.${PLAIN}")"
            fi
            ;;
        hostname)
            local hostname_value
            hostname_value=$(head -n1 "$target_file" 2>/dev/null | tr -d '[:space:]')
            if [[ -n "$hostname_value" ]]; then
                hostnamectl set-hostname "$hostname_value" >/dev/null 2>&1 || hostname "$hostname_value" 2>/dev/null || true
            fi
            ;;
        dns)
            if confirm_risk_action "$(localized_text "重启 systemd-resolved" "Restart systemd-resolved" "Перезапуск systemd-решено")" \
                "$(localized_text "系统 DNS 解析服务和 resolved drop-in 配置" "System DNS resolution service and resolved drop-in configuration" "Служба разрешения проблем системы DNS и решенная прямая конфигурация")" \
                "$(localized_text "恢复 ${target_file}.bak_*，或重新进入 DNS 更改优化菜单切换回原配置" "Restore ${target_file}.bak_*, or re-enter DNS and change the optimization menu to switch back to the original configuration." "Восстановите ${target_file}.bak_* или повторно введите DNS и измените меню оптимизации, чтобы вернуться к исходной конфигурации.")" \
                "$(localized_text "确认当前 SSH 会话保持连接，必要时可用 IP 直连排障。" "Confirm that the current SSH session remains connected, and use IP direct connection to troubleshoot if necessary." "Убедитесь, что текущий сеанс SSH остается подключенным, и при необходимости используйте прямое IP-соединение для устранения неполадок.")"; then
                restart_named_service_if_available systemd-resolved
            else
                echo -e "$(localized_text "${BLUE}DNS 配置已保存，未重启 systemd-resolved。${PLAIN}" "${BLUE}DNS configuration saved, no restart systemd-resolved.${PLAIN}" "${BLUE}Конфигурация DNS сохранена, проблема с systemd решена без перезагрузки.${PLAIN}")"
            fi
            ;;
        sysctl)
            if confirm_risk_action "$(localized_text "应用 sysctl 配置" "Apply sysctl configuration" "Применить конфигурацию sysctl")" \
                "$(localized_text "当前内核运行中的 sysctl 参数" "sysctl parameters currently running in the kernel" "Параметры sysctl, работающие в настоящее время в ядре")" \
                "$(localized_text "恢复 ${target_file}.bak_* 后重新执行 sysctl --system，或手动回退异常参数" "Restore ${target_file}.bak_* and re-execute sysctl --system, or manually roll back the abnormal parameters" "Восстановите ${target_file}.bak_* и повторно выполните sysctl --system или вручную откатите ненормальные параметры.")" \
                "$(localized_text "确认参数来源可信；错误网络参数可能影响远程连接。" "Confirm that the source of the parameters is trustworthy; incorrect network parameters may affect remote connections." "Подтвердите, что источник параметров заслуживает доверия; неправильные параметры сети могут повлиять на удаленные подключения.")"; then
                sysctl --system >/dev/null
            else
                echo -e "$(localized_text "${YELLOW}⚠️ sysctl 修改尚未应用到当前内核。${PLAIN}" "${YELLOW}⚠️ The sysctl modification has not yet been applied to the current kernel.${PLAIN}" "${YELLOW}⚠️ Модификация sysctl пока не применена к текущему ядру.${PLAIN}")"
            fi
            ;;
        fail2ban)
            if confirm_risk_action "$(localized_text "重启 fail2ban" "Restart fail2ban" "Перезагрузите fail2ban.")" \
                "$(localized_text "Fail2ban 服务和登录防护规则" "Fail2ban Service and Login Protection Rules" "Fail2ban Правила защиты и защиты входа в систему")" \
                "$(localized_text "恢复 ${target_file}.bak_* 后重启 fail2ban，或临时停用异常 jail" "Restore ${target_file}.bak_* and then restart fail2ban, or temporarily disable the abnormal jail" "Восстановите ${target_file}.bak_*, а затем перезапустите fail2ban или временно отключите аварийный джейл.")" \
                "$(localized_text "确认当前 SSH 来源不会被新规则误封。" "Confirm that the current SSH source will not be accidentally blocked by the new rules." "Убедитесь, что текущий источник SSH не будет случайно заблокирован новыми правилами.")"; then
                restart_named_service_if_available fail2ban
            else
                echo -e "$(localized_text "${YELLOW}⚠️ Fail2ban 未重启，修改尚未生效。${PLAIN}" "${YELLOW}⚠️ Fail2ban has not been restarted and the modification has not yet taken effect.${PLAIN}" "${YELLOW}⚠️ Fail2ban не был перезапущен и модификация еще не вступила в силу.${PLAIN}")"
            fi
            ;;
        xui-json)
            if confirm_risk_action "$(localized_text "重启 x-ui/3x-ui" "Restart x-ui/3x-ui" "Перезагрузите x-ui/3x-ui.")" \
                "$(localized_text "x-ui/3x-ui 面板进程和 config.json 运行配置" "x-ui/3x-ui panel process and config.json running configuration" "Процесс и конфигурация панели x-ui/3x-ui. Текущая конфигурация json")" \
                "$(localized_text "恢复 ${target_file}.bak_* 后重启面板，或用官方 x-ui/3x-ui 命令进入管理菜单修复" "Restore ${target_file}.bak_* and then restart the panel, or use the official x-ui/3x-ui command to enter the management menu to repair" "Восстановите ${target_file}.bak_*, а затем перезапустите панель или используйте официальную команду x-ui/3x-ui, чтобы войти в меню управления для восстановления.")" \
                "$(localized_text "确认面板端口、证书路径和 443端口复用设置匹配。" "Verify that the panel port, certificate path, and Port 443 Reuse settings match." "Убедитесь, что порт панели, путь к сертификату и настройки записи общего ресурса 443 совпадают.")"; then
                restart_named_service_if_available x-ui
                restart_named_service_if_available 3x-ui
            else
                echo -e "$(localized_text "${YELLOW}⚠️ x-ui/3x-ui 未重启，修改可能尚未生效。${PLAIN}" "${YELLOW}⚠️ x-ui/3x-ui has not been restarted, and the modification may not yet take effect.${PLAIN}" "${YELLOW}⚠️ x-ui/3x-ui не был перезапущен, и модификация может еще не вступить в силу.${PLAIN}")"
            fi
            ;;
        env|hosts)
            echo -e "$(localized_text "${BLUE}配置已保存；该文件通常由系统或脚本后续读取，无需立即 reload。${PLAIN}" "${BLUE}Configuration has been saved; this file is usually read later by the system or script and does not need to be reloaded immediately.${PLAIN}" "${BLUE}Конфигурация сохранена; этот файл обычно читается позже системой или сценарием, и его не нужно перезагружать немедленно.${PLAIN}")"
            ;;
        *)
            echo -e "$(localized_text "${BLUE}配置已保存；未为 ${kind} 定义自动 reload。${PLAIN}" "${BLUE}Configuration saved; no automatic reload is defined for ${kind}.${PLAIN}" "${BLUE}Конфигурация сохранена; для ${kind} автоматическая перезагрузка не определена.${PLAIN}")"
            ;;
    esac
}

edit_applied_config_file() {
    local target_file="$1"
    local target_kind="$2"
    local target_label="${3:-$1}"
    local backup_file editor confirm rollback_confirm

    [[ -e "$target_file" || -L "$target_file" ]] || { echo -e "$(localized_text "${RED}❌ 文件不存在：${target_file}${PLAIN}" "${RED}❌ File does not exist: ${target_file}${PLAIN}" "${RED}❌ Файл не существует: ${target_file}${PLAIN}")"; return 1; }
    [[ -f "$target_file" || -L "$target_file" ]] || { echo -e "$(localized_text "${RED}❌ 不是普通配置文件：${target_file}${PLAIN}" "${RED}❌ is not an ordinary configuration file: ${target_file}${PLAIN}" "${RED}❌ — это не обычный файл конфигурации: ${target_file}.${PLAIN}")"; return 1; }

    echo -e "${CYAN}------------------------------------------------${PLAIN}"
    echo -e "$(localized_text "${BOLD}当前文件：${target_label}${PLAIN}" "${BOLD}Current file: ${target_label}${PLAIN}" "${BOLD}Текущий файл: ${target_label}${PLAIN}")"
    echo -e "${CYAN}${target_file}${PLAIN}"
    echo -e "${CYAN}------------------------------------------------${PLAIN}"
    nl -ba "$target_file"
    echo -e "${CYAN}------------------------------------------------${PLAIN}"
    read_trimmed confirm "$(localized_text "是否打开编辑器修改该文件？(Y/n，默认 y): " "Do you want to open an editor to modify the file? (Y/n, default y):" "Хотите открыть редактор и изменить файл? (Да/нет, по умолчанию y):")"
    is_yes "$confirm" || return 0

    editor=$(applied_config_editor_command) || {
        echo -e "$(localized_text "${RED}❌ 未找到可用编辑器。请先安装 nano/vim/vi，或设置 EDITOR。${PLAIN}" "${RED}❌ No available editor found. Please install nano/vim/vi first, or set up EDITOR.${PLAIN}" "${RED}❌ Доступный редактор не найден. Пожалуйста, сначала установите nano/vim/vi или настройте РЕДАКТОР.${PLAIN}")"
        return 1
    }
    backup_file="${target_file}.bak_$(date +%s)"
    cp -p "$target_file" "$backup_file" || { echo -e "$(localized_text "${RED}❌ 备份失败，已取消编辑。${PLAIN}" "${RED}❌ Backup failed, editing canceled.${PLAIN}" "${RED}❌ Не удалось выполнить резервное копирование, редактирование отменено.${PLAIN}")"; return 1; }
    echo -e "$(localized_text "${CYAN}编辑前备份：${backup_file}${PLAIN}" "${CYAN}Backup before editing: ${backup_file}${PLAIN}" "${CYAN}Резервная копия перед редактированием: ${backup_file}${PLAIN}")"

    "$editor" "$target_file" || {
        echo -e "$(localized_text "${RED}❌ 编辑器异常退出，配置未重新加载。${PLAIN}" "${RED}❌ The editor exited abnormally and the configuration was not reloaded.${PLAIN}" "${RED}❌ Редактор завершился аварийно, и конфигурация не была перезагружена.${PLAIN}")"
        return 1
    }

    if cmp -s "$target_file" "$backup_file"; then
        echo -e "$(localized_text "${BLUE}配置未变化。${PLAIN}" "${BLUE}The configuration has not changed.${PLAIN}" "${BLUE}Конфигурация не изменилась.${PLAIN}")"
        return 0
    fi

    echo -e "$(localized_text "${CYAN}▶ 正在校验配置...${PLAIN}" "${CYAN}▶ Verifying configuration...${PLAIN}" "${CYAN}▶ Проверка конфигурации...${PLAIN}")"
    if ! validate_applied_config_kind "$target_kind" "$target_file"; then
        echo -e "$(localized_text "${RED}❌ 校验失败，服务不会 reload。${PLAIN}" "${RED}❌ The verification failed and the service will not reload.${PLAIN}" "${RED}❌ Проверка не удалась, и служба не перезагрузится.${PLAIN}")"
        read_trimmed rollback_confirm "$(localized_text "是否恢复编辑前备份？(Y/n，默认 yes): " "Restore pre-edit backup? (Y/n, default yes):" "Восстановить предварительно отредактированную резервную копию? (Да/нет, по умолчанию да):")"
        if ! is_no "$rollback_confirm"; then
            cp -p "$backup_file" "$target_file" && echo -e "$(localized_text "${GREEN}✅ 已恢复：${target_file}${PLAIN}" "${GREEN}✅ Restored: ${target_file}${PLAIN}" "${GREEN}✅ Восстановлено: ${target_file}${PLAIN}")"
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 已保留未通过校验的修改，请手动修正后再应用。${PLAIN}" "${YELLOW}⚠️ The modifications that failed the verification have been retained. Please correct them manually before applying them.${PLAIN}" "${YELLOW}⚠️ Модификации, не прошедшие проверку, сохранены. Пожалуйста, исправьте их вручную перед применением.${PLAIN}")"
        fi
        return 1
    fi

    if reload_applied_config_kind "$target_kind" "$target_file" "$backup_file"; then
        echo -e "$(localized_text "${GREEN}✅ 配置已保存并完成可执行的校验/应用步骤。${PLAIN}" "${GREEN}✅ Configuration saved and executable verification/application steps completed.${PLAIN}" "${GREEN}✅ Конфигурация сохранена, исполняемые этапы проверки/приложения выполнены.${PLAIN}")"
        echo -e "$(localized_text "${CYAN}备份文件：${backup_file}${PLAIN}" "${CYAN}Backup file: ${backup_file}${PLAIN}" "${CYAN}Файл резервной копии : ${backup_file}${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ 配置校验通过，但应用/reload 失败。${PLAIN}" "${RED}❌ configuration validation passed, but application/reload failed.${PLAIN}" "${RED}❌ Проверка конфигурации пройдена, но приложение/перезагрузка не удалась.${PLAIN}")"
        read_trimmed rollback_confirm "$(localized_text "是否恢复编辑前备份？(Y/n，默认 yes): " "Restore pre-edit backup? (Y/n, default yes):" "Восстановить предварительно отредактированную резервную копию? (Да/нет, по умолчанию да):")"
        if ! is_no "$rollback_confirm"; then
            cp -p "$backup_file" "$target_file" && reload_applied_config_kind "$target_kind" "$target_file" >/dev/null 2>&1 || true
            echo -e "$(localized_text "${GREEN}✅ 已尝试恢复编辑前配置。${PLAIN}" "${GREEN}✅ An attempt has been made to restore the pre-edit configuration.${PLAIN}" "${GREEN}✅ Предпринята попытка восстановить предредактированную конфигурацию.${PLAIN}")"
        fi
        return 1
    fi
}

func_edit_applied_config_center() {
    local scope="${1:-all}"
    local -a applied_config_labels=()
    local -a applied_config_paths=()
    local -a applied_config_kinds=()
    collect_applied_config_files "$scope"

    clear
    echo -e "${CYAN}================================================${PLAIN}"
    if [[ "$scope" == "proxy" ]]; then
        echo -e "$(localized_text "${BOLD}📝 查看/编辑已应用反代配置${PLAIN}" "${BOLD}📝 View/edit applied reverse proxy configuration${PLAIN}" "${BOLD}📝 Просмотр/редактирование примененной конфигурации обратного прокси-сервера${PLAIN}")"
    else
        echo -e "$(localized_text "${BOLD}📝 查看/编辑脚本已应用配置${PLAIN}" "${BOLD}📝 View/edit script has applied configuration${PLAIN}" "${BOLD}📝 Скрипт просмотра/редактирования применил конфигурацию${PLAIN}")"
    fi
    echo -e "${CYAN}================================================${PLAIN}"
    if [[ ${#applied_config_paths[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}未检测到可编辑的已应用配置文件。${PLAIN}" "${YELLOW}No editable applied profile detected.${PLAIN}" "${YELLOW}Не обнаружен редактируемый прикладной профиль.${PLAIN}")"
        return 0
    fi

    local i
    for i in "${!applied_config_paths[@]}"; do
        printf '%b%3d. %s%b\n' "$GREEN" "$((i + 1))" "${applied_config_labels[$i]} -> ${applied_config_paths[$i]}" "$PLAIN"
    done
    echo -e "$(localized_text "${RED}  0. 取消${PLAIN}" "${RED}0. Cancel${PLAIN}" "${RED}0. Отмена${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"

    local choice idx
    read_trimmed choice "$(localized_text "请选择要查看/编辑的配置文件: " "Please select a profile to view/edit:" "Пожалуйста, выберите профиль для просмотра/редактирования:")"
    [[ "$choice" == "0" || "$choice" == "q" || "$choice" == "Q" ]] && return 0
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#applied_config_paths[@]} )); then
        echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"
        return 1
    fi

    idx=$((choice - 1))
    edit_applied_config_file "${applied_config_paths[$idx]}" "${applied_config_kinds[$idx]}" "${applied_config_labels[$idx]}"
}

func_backup_center() {
    local backup_root="/etc/vps-optimize/backups/manual"
    local loaded_archive=""
    mkdir -p "$backup_root"
    chmod 700 "$backup_root" 2>/dev/null || true

    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        print_breadcrumb "$(localized_text "备份与回滚" "Backup and rollback" "Резервное копирование и откат")"
        echo -e "$(localized_text "${BOLD}🗂️ 配置备份与回滚中心${PLAIN}" "${BOLD}🗂️ Configure backup and rollback center${PLAIN}" "${BOLD}🗂️ Настройка центра резервного копирования и отката${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "当前备份目录: ${YELLOW}${backup_root}${PLAIN}" "Current backup directory: ${YELLOW}${backup_root}${PLAIN}" "Текущий каталог резервной копии: ${YELLOW}${backup_root}${PLAIN}.")"
        [[ -n "$loaded_archive" && ! -r "$loaded_archive" ]] && loaded_archive=""
        [[ -n "$loaded_archive" ]] && echo -e "$(localized_text "已加载备份包: ${YELLOW}$(basename "$loaded_archive")${PLAIN}" "Loaded backup archive: ${YELLOW}$(basename "$loaded_archive")${PLAIN}" "Загруженный архив резервной копии: ${YELLOW}$(basename "$loaded_archive")${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 创建备份${PLAIN}               ${YELLOW}(配置 / 自定义目录 / 两者)${PLAIN}" "${GREEN}1. Create backup${PLAIN} (configuration / custom directories / both)" "${GREEN}1. Создать резервную копию${PLAIN} (конфигурация / пользовательские каталоги / оба)")"
        echo -e "$(localized_text "${GREEN}  2. 加载备份包${PLAIN}               ${YELLOW}(.tar.gz / 加密 .tar.gz.enc)${PLAIN}" "${GREEN}2. Load backup archive${PLAIN} (.tar.gz / encrypted .tar.gz.enc)" "${GREEN}2. Загрузить архив${PLAIN} (.tar.gz / зашифрованный .tar.gz.enc)")"
        echo -e "$(localized_text "${GREEN}  3. 从备份恢复${PLAIN}             ${YELLOW}(已加载 / 自动列表 / 指定路径)${PLAIN}" "${GREEN}3. Restore from backup${PLAIN} (loaded / automatic list / specified path)" "${GREEN}3. Восстановить из копии${PLAIN} (загруженный / автоматический список / указанный путь)")"
        echo -e "$(localized_text "${GREEN}  4. 隔离旧备份${PLAIN}             ${YELLOW}(仅保留最近 5 份，旧文件移入隔离区)${PLAIN}" "${GREEN}4. Isolate old backups (only the latest 5 copies are kept, and old files are moved to the quarantine area)${PLAIN}" "${GREEN}4. Изолировать старые резервные копии (сохраняются только последние 5 копий, а старые файлы перемещаются в зону карантина)${PLAIN}")"
        echo -e "$(localized_text "${CYAN}  5. 查看/编辑脚本已应用配置${PLAIN} ${YELLOW}(备份、校验，可选择 reload/restart)${PLAIN}" "${CYAN}5. View/edit script applied configuration (backup, verification, optional reload/restart)${PLAIN}" "${CYAN}5. Просмотр/редактирование примененной конфигурации сценария (резервное копирование, проверка, дополнительная перезагрузка/перезапуск)${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${BLUE}  ?. 查看帮助${PLAIN}" "${BLUE}?. View help${PLAIN}" "${BLUE}?. Посмотреть справку${PLAIN}")"
        echo -e "$(localized_text "${RED}  0. 返回主菜单 / q 返回上一级${PLAIN}" "${RED}0. Return to the main menu / q Return to the previous level${PLAIN}" "${RED}0. Возврат в главное меню / q Возврат на предыдущий уровень${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local b_choice
        read_trimmed b_choice "$(localized_text "👉 请选择操作: " "👉 Please select an operation:" "👉 Пожалуйста, выберите операцию:")"

        case $b_choice in
            1)
                local backup_scope scope_choice ts
                ts=$(date +%Y%m%d_%H%M%S)
                local work_dir
                local tar_file
                local manifest_file
                local copied=0
                local encrypt_choice=""
                local backup_password=""
                local -a custom_directories=()
                local -a BACKUP_COPY_FAILURES=()

                echo -e "$(localized_text "${BOLD}备份范围${PLAIN}" "${BOLD}Backup scope${PLAIN}" "${BOLD}Область резервного копирования${PLAIN}")"
                echo -e "  1. $(localized_text "脚本与服务配置（默认）" "Script and service configuration (default)" "Конфигурация скрипта и служб (по умолчанию)")"
                echo -e "  2. $(localized_text "自定义系统目录" "Custom system directories" "Пользовательские системные каталоги")"
                echo -e "  3. $(localized_text "配置 + 自定义系统目录" "Configuration + custom system directories" "Конфигурация + пользовательские системные каталоги")"
                echo -e "  0. $(localized_text "取消" "Cancel" "Отмена")"
                read_trimmed scope_choice "$(localized_text "选择备份范围: " "Select backup scope: " "Выберите область резервного копирования: ")"
                case "$scope_choice" in
                    1) backup_scope="managed" ;;
                    2) backup_scope="custom" ;;
                    3) backup_scope="both" ;;
                    0|q|Q) continue ;;
                    *)
                        echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"
                        continue
                        ;;
                esac
                if [[ "$backup_scope" == "custom" || "$backup_scope" == "both" ]]; then
                    echo -e "$(localized_text "${YELLOW}数据库或 Docker 数据目录请先停止相关服务，文件复制不保证运行中数据一致。${PLAIN}" "${YELLOW}Stop related services before backing up database or Docker data directories; file copying does not guarantee consistency for active data.${PLAIN}" "${YELLOW}Перед резервным копированием каталогов баз данных или Docker остановите связанные службы: копирование файлов не гарантирует согласованность активных данных.${PLAIN}")"
                    if ! backup_collect_custom_directories custom_directories; then
                        echo -e "$(localized_text "${YELLOW}未填写可备份目录，已取消。${PLAIN}" "${YELLOW}No backupable directory entered; canceled.${PLAIN}" "${YELLOW}Не указан каталог для резервного копирования; операция отменена.${PLAIN}")"
                        continue
                    fi
                    confirm_risk_action \
                        "$(localized_text "备份自定义系统目录" "Back up custom system directories" "Создать резервную копию пользовательских системных каталогов")" \
                        "$(localized_text "复制所选目录到权限为 600 的压缩包；运行中的数据库或 Docker 数据可能处于不一致状态。" "Copy the selected directories into a mode-600 archive. Active databases or Docker data may be inconsistent." "Скопировать выбранные каталоги в архив с правами 600. Активные базы данных и данные Docker могут оказаться несогласованными.")" \
                        "$(localized_text "备份不会修改源目录；若需一致快照，请先停止相关服务后重新创建备份。" "The source directories are not modified. Stop related services and recreate the backup if a consistent snapshot is required." "Исходные каталоги не изменяются. Для согласованной копии остановите связанные службы и создайте архив заново.")" || continue
                fi
                backup_select_archive_directory "$backup_root" || continue
                read_trimmed encrypt_choice "$(localized_text "是否使用 AES-256 加密备份？(y/N，默认 N): " "Encrypt the backup with AES-256? (y/N, default N): " "Зашифровать резервную копию с помощью AES-256? (y/N, по умолчанию N): ")"
                if is_yes "$encrypt_choice"; then
                    if ! command -v openssl >/dev/null 2>&1; then
                        echo -e "$(localized_text "${RED}❌ 缺少 openssl，无法创建加密备份。${PLAIN}" "${RED}❌ openssl is required to create an encrypted backup.${PLAIN}" "${RED}❌ Для создания зашифрованной копии требуется openssl.${PLAIN}")"
                        continue
                    fi
                    backup_read_new_password backup_password
                    tar_file="${BACKUP_ARCHIVE_ROOT}/backup_${ts}.tar.gz.enc"
                else
                    tar_file="${BACKUP_ARCHIVE_ROOT}/backup_${ts}.tar.gz"
                fi

                work_dir=$(make_secure_temp_dir "vps_backup_${ts}") || {
                    echo -e "$(localized_text "${RED}❌ 无法创建安全临时目录，备份已取消。${PLAIN}" "${RED}❌ Unable to create secure temporary directory, backup canceled.${PLAIN}" "${RED}❌ Невозможно создать безопасный временный каталог, резервное копирование отменено.${PLAIN}")"
                    sleep 2
                    continue
                }
                manifest_file="${work_dir}/manifest.txt"
                {
                    echo "VPS-Optimize backup manifest"
                    echo "Created: $(date -Is 2>/dev/null || date)"
                    echo "Backup file: ${tar_file}"
                    echo "Scope: ${backup_scope}"
                    echo "Included paths:"
                } > "$manifest_file"

                if [[ "$backup_scope" == "managed" || "$backup_scope" == "both" ]]; then
                    backup_copy_managed_configuration "$manifest_file" "$work_dir" && copied=1
                fi
                if [[ "$backup_scope" == "custom" || "$backup_scope" == "both" ]]; then
                    backup_copy_custom_directories "$manifest_file" "$work_dir" custom_directories && copied=1
                fi

                if (( ${#BACKUP_COPY_FAILURES[@]} > 0 )); then
                    backup_cleanup_temp_dir "$work_dir" || true
                    echo -e "$(localized_text "${RED}❌ 以下路径复制失败，未创建不完整备份：${BACKUP_COPY_FAILURES[*]}${PLAIN}" "${RED}❌ These paths could not be copied; an incomplete backup was not created: ${BACKUP_COPY_FAILURES[*]}${PLAIN}" "${RED}❌ Не удалось скопировать следующие пути; неполная резервная копия не создана: ${BACKUP_COPY_FAILURES[*]}${PLAIN}")"
                elif [[ "$copied" -eq 0 ]]; then
                    backup_cleanup_temp_dir "$work_dir" || true
                    echo -e "$(localized_text "${YELLOW}⚠️ 未检测到可备份配置文件，已取消创建。${PLAIN}" "${YELLOW}⚠️ The backupable configuration file was not detected and the creation has been cancelled.${PLAIN}" "${YELLOW}⚠️ Резервный файл конфигурации не обнаружен, и его создание отменено.${PLAIN}")"
                else
                    local backup_payload_bytes
                    backup_payload_bytes=$(backup_path_size_bytes "$work_dir") || backup_payload_bytes=0
                    if ! backup_require_free_space "$BACKUP_ARCHIVE_ROOT" "$backup_payload_bytes" "$(localized_text "创建备份" "Backup creation" "Создание резервной копии")"; then
                        backup_cleanup_temp_dir "$work_dir" || true
                        continue
                    fi
                    if backup_create_archive "$work_dir" "$tar_file" "$backup_password"; then
                        backup_password=""
                        chmod 600 "$tar_file" 2>/dev/null || true
                        backup_register_archive_root "$BACKUP_ARCHIVE_ROOT" || true
                        loaded_archive="$tar_file"
                        echo -e "$(localized_text "${GREEN}✅ 备份创建成功: ${tar_file}${PLAIN}" "${GREEN}✅ Backup created successfully: ${tar_file}${PLAIN}" "${GREEN}. Резервная копия успешно создана: ${tar_file}.${PLAIN}")"
                        echo -e "$(localized_text "已加载备份包: $(basename "$tar_file")，可在 [3] -> [1] 恢复。" "Loaded backup archive: $(basename "$tar_file"). Restore it with [3] -> [1]." "Загружен архив: $(basename "$tar_file"). Восстановление: [3] -> [1].")"
                        if backup_archive_is_encrypted "$tar_file"; then
                            echo -e "$(localized_text "${YELLOW}⚠️ 加密密码不会保存；丢失后无法恢复该备份。${PLAIN}" "${YELLOW}⚠️ The encryption password is not stored. The backup cannot be restored if the password is lost.${PLAIN}" "${YELLOW}⚠️ Пароль шифрования не сохраняется. Без него восстановить копию невозможно.${PLAIN}")"
                        else
                            echo -e "$(localized_text "${YELLOW}⚠️ 备份包含证书私钥、面板数据库和 API Token；文件权限已设为 600，请勿公开传输。${PLAIN}" "${YELLOW}⚠️ This archive contains certificate keys, panel databases, and API tokens. Its mode is 600; do not transfer it publicly.${PLAIN}" "${YELLOW}⚠️ Архив содержит закрытые ключи, базы данных панели и API-токены. Права установлены в 600; не передавайте его публично.${PLAIN}")"
                        fi
                    else
                        backup_password=""
                        rm -f -- "$tar_file"
                        echo -e "$(localized_text "${RED}❌ 备份打包失败，请检查磁盘空间与权限。${PLAIN}" "${RED}❌ Backup packaging failed, please check the disk space and permissions.${PLAIN}" "${RED}❌ Не удалось создать резервную копию, проверьте место на диске и разрешения.${PLAIN}")"
                    fi
                    backup_cleanup_temp_dir "$work_dir" || true
                fi
                ;;

            2)
                backup_select_available_archive loaded_archive || true
                [[ -n "$loaded_archive" ]] && echo -e "$(localized_text "${GREEN}✅ 已加载: ${loaded_archive}${PLAIN}" "${GREEN}✅ Loaded: ${loaded_archive}${PLAIN}" "${GREEN}✅ Загружено: ${loaded_archive}${PLAIN}")"
                ;;

            3)
                local restore_source target_file
                echo -e "  1. $(localized_text "已加载备份包" "Loaded backup archive" "Загруженный архив резервной копии")"
                echo -e "  2. $(localized_text "自动读取的备份列表" "Automatically detected backup list" "Автоматически найденный список копий")"
                echo -e "  3. $(localized_text "指定备份包路径" "Specify backup archive path" "Указать путь к архиву резервной копии")"
                echo -e "  0. $(localized_text "取消" "Cancel" "Отмена")"
                read_trimmed restore_source "$(localized_text "选择恢复来源: " "Select restore source: " "Выберите источник восстановления: ")"
                case "$restore_source" in
                    1)
                        if ! backup_archive_is_readable "$loaded_archive"; then
                            echo -e "$(localized_text "${YELLOW}⚠️ 尚未加载可用备份包。${PLAIN}" "${YELLOW}⚠️ No usable backup archive is loaded.${PLAIN}" "${YELLOW}⚠️ Доступный архив резервной копии не загружен.${PLAIN}")"
                            read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                            continue
                        fi
                        target_file="$loaded_archive"
                        ;;
                    2)
                        backup_select_available_archive target_file || continue
                        loaded_archive="$target_file"
                        ;;
                    3)
                        IFS= read -r -p "$(localized_text "备份包绝对路径（.tar.gz 或 .tar.gz.enc）: " "Absolute backup archive path (.tar.gz or .tar.gz.enc): " "Абсолютный путь к архиву (.tar.gz или .tar.gz.enc): ")" target_file || continue
                        target_file=$(trim_input "$target_file")
                        if ! backup_archive_is_readable "$target_file"; then
                            echo -e "$(localized_text "${RED}❌ 未找到可读取的 .tar.gz 或 .tar.gz.enc 备份包。${PLAIN}" "${RED}❌ A readable .tar.gz or .tar.gz.enc backup archive was not found.${PLAIN}" "${RED}❌ Не найден доступный для чтения архив .tar.gz или .tar.gz.enc.${PLAIN}")"
                            continue
                        fi
                        loaded_archive="$target_file"
                        ;;
                    0|q|Q) continue ;;
                    *)
                        echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"
                        continue
                        ;;
                esac

                local restore_dir restore_archive restore_password
                local restore_failed=0
                local restore_quarantine="/etc/vps-optimize/quarantine/manual-restore"
                restore_dir=$(make_secure_temp_dir "vps_restore") || {
                    echo -e "$(localized_text "${RED}❌ 无法创建安全临时目录，回滚中止。${PLAIN}" "${RED}❌ Unable to create secure temporary directory, rollback aborted.${PLAIN}" "${RED}❌ Невозможно создать безопасный временный каталог, откат прерван.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                }
                restore_archive="$target_file"
                restore_password=""
                if backup_archive_is_encrypted "$target_file"; then
                    if ! command -v openssl >/dev/null 2>&1; then
                        backup_cleanup_temp_dir "$restore_dir" || true
                        echo -e "$(localized_text "${RED}❌ 缺少 openssl，无法解密该备份。${PLAIN}" "${RED}❌ openssl is required to decrypt this backup.${PLAIN}" "${RED}❌ Для расшифровки этой копии требуется openssl.${PLAIN}")"
                        continue
                    fi
                    read_secret_trimmed restore_password "$(localized_text "备份解密密码: " "Backup decryption password: " "Пароль для расшифровки: ")"
                    if [[ -z "$restore_password" ]]; then
                        backup_cleanup_temp_dir "$restore_dir" || true
                        echo -e "$(localized_text "${YELLOW}未输入密码，恢复已取消。${PLAIN}" "${YELLOW}No password was entered; restore canceled.${PLAIN}" "${YELLOW}Пароль не введён; восстановление отменено.${PLAIN}")"
                        continue
                    fi
                    local encrypted_archive_bytes
                    encrypted_archive_bytes=$(backup_path_size_bytes "$target_file") || encrypted_archive_bytes=0
                    if ! backup_require_free_space "$restore_dir" "$encrypted_archive_bytes" "$(localized_text "解密备份" "Backup decryption" "Расшифровка резервной копии")"; then
                        restore_password=""
                        backup_cleanup_temp_dir "$restore_dir" || true
                        continue
                    fi
                    restore_archive="${restore_dir}/.decrypted-backup.tar.gz"
                    if ! backup_decrypt_archive "$target_file" "$restore_archive" "$restore_password"; then
                        restore_password=""
                        rm -f -- "$restore_archive"
                        backup_cleanup_temp_dir "$restore_dir" || true
                        echo -e "$(localized_text "${RED}❌ 解密失败：密码错误或文件已损坏。${PLAIN}" "${RED}❌ Decryption failed: the password is incorrect or the file is damaged.${PLAIN}" "${RED}❌ Ошибка расшифровки: неверный пароль или повреждённый файл.${PLAIN}")"
                        continue
                    fi
                    restore_password=""
                fi

                if ! tar -tzf "$restore_archive" >/dev/null 2>&1; then
                    [[ "$restore_archive" == "$target_file" ]] || rm -f -- "$restore_archive"
                    backup_cleanup_temp_dir "$restore_dir" || true
                    echo -e "$(localized_text "${RED}❌ 备份文件无法读取，回滚中止。${PLAIN}" "${RED}❌ The backup file cannot be read and the rollback is aborted.${PLAIN}" "${RED}❌ Файл резервной копии не может быть прочитан, и откат прерывается.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi
                if tar -tzf "$restore_archive" 2>/dev/null | grep -Eq '(^/|(^|/)\.\.(/|$))'; then
                    [[ "$restore_archive" == "$target_file" ]] || rm -f -- "$restore_archive"
                    backup_cleanup_temp_dir "$restore_dir" || true
                    echo -e "$(localized_text "${RED}❌ 备份文件包含不安全路径，回滚中止。${PLAIN}" "${RED}❌ The backup file contains an unsafe path and the rollback is aborted.${PLAIN}" "${RED}❌ Файл резервной копии содержит небезопасный путь, и откат прерывается.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi

                local unpacked_bytes
                unpacked_bytes=$(backup_archive_unpacked_size_bytes "$restore_archive") || unpacked_bytes=0
                if ! backup_require_free_space "$restore_dir" "$unpacked_bytes" "$(localized_text "解压备份" "Backup extraction" "Распаковка резервной копии")"; then
                    [[ "$restore_archive" == "$target_file" ]] || rm -f -- "$restore_archive"
                    backup_cleanup_temp_dir "$restore_dir" || true
                    continue
                fi

                if ! tar -xzf "$restore_archive" -C "$restore_dir" >/dev/null 2>&1; then
                    [[ "$restore_archive" == "$target_file" ]] || rm -f -- "$restore_archive"
                    backup_cleanup_temp_dir "$restore_dir" || true
                    echo -e "$(localized_text "${RED}❌ 备份解压失败，回滚中止。${PLAIN}" "${RED}❌ Backup decompression failed and rollback aborted.${PLAIN}" "${RED}❌ Не удалось распаковать резервную копию, и откат прерван.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi
                [[ "$restore_archive" == "$target_file" ]] || rm -f -- "$restore_archive"

                backup_restore_preflight "$restore_dir"
                confirm_danger "$(localized_text "确认从备份恢复" "Confirm backup restore" "Подтвердите восстановление из резервной копии")" "$(localized_text "会覆盖 SSH、Caddy、Docker、Fail2ban、sysctl 及备份中的自定义系统目录。" "It will overwrite SSH, Caddy, Docker, Fail2ban, sysctl, and custom system directories in the backup." "Будут перезаписаны SSH, Caddy, Docker, Fail2ban, sysctl и пользовательские системные каталоги из резервной копии.")" "$(localized_text "恢复后脚本会尝试重启已安装服务；请保持当前 SSH 会话并准备好云厂商救援控制台。" "After restoring, the script will try to restart installed services. Keep the current SSH session and prepare the cloud rescue console." "После восстановления скрипт попытается перезапустить установленные службы. Сохраните текущий сеанс SSH и подготовьте облачную консоль восстановления.")" || {
                    backup_cleanup_temp_dir "$restore_dir" || true
                    echo -e "$(localized_text "${BLUE}已取消恢复操作。${PLAIN}" "${BLUE}Restore operation canceled.${PLAIN}" "${BLUE}Операция восстановления отменена.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                }

                if [[ -f "$restore_dir/etc/vps-optimize/traffic-guard.conf" || -f "$restore_dir/usr/local/bin/vps-traffic-guard-check" ]]; then
                    if declare -F traffic_guard_restore_ssh_only_firewall >/dev/null 2>&1 && ! traffic_guard_restore_ssh_only_firewall; then
                        backup_cleanup_temp_dir "$restore_dir" || true
                        echo -e "$(localized_text "${RED}❌ 无法解除当前仅保留 SSH 封锁规则，回滚中止。${PLAIN}" "${RED}❌ Unable to unblock the current blocking rule of SSH, the rollback is aborted.${PLAIN}" "${RED}❌ Невозможно разблокировать текущее правило блокировки SSH, откат прерывается.${PLAIN}")"
                        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                        continue
                    fi
                fi

                restore_backup_file "$restore_dir/etc/ssh/sshd_config" /etc/ssh/sshd_config || restore_failed=1
                restore_backup_file "$restore_dir/etc/hostname" /etc/hostname || restore_failed=1
                restore_backup_file "$restore_dir/etc/hosts" /etc/hosts || restore_failed=1
                restore_backup_file "$restore_dir/etc/nginx/nginx.conf" /etc/nginx/nginx.conf || restore_failed=1
                restore_backup_dir "$restore_dir/etc/nginx/stream.d" /etc/nginx/stream.d "$restore_quarantine" || restore_failed=1
                restore_backup_dir "$restore_dir/etc/nginx/conf.d" /etc/nginx/conf.d "$restore_quarantine" || restore_failed=1
                restore_backup_dir "$restore_dir/etc/nginx/sites-available" /etc/nginx/sites-available "$restore_quarantine" || restore_failed=1
                restore_backup_dir "$restore_dir/etc/nginx/sites-enabled" /etc/nginx/sites-enabled "$restore_quarantine" || restore_failed=1
                restore_backup_file "$restore_dir/etc/caddy/Caddyfile" /etc/caddy/Caddyfile || restore_failed=1
                restore_backup_dir "$restore_dir/etc/caddy/conf.d" /etc/caddy/conf.d "$restore_quarantine" || restore_failed=1
                restore_backup_dir "$restore_dir/etc/caddy/certs" /etc/caddy/certs "$restore_quarantine" || restore_failed=1
                restore_backup_dir "$restore_dir/root/cert" /root/cert "$restore_quarantine" || restore_failed=1
                restore_backup_dir "$restore_dir/root/.acme.sh" /root/.acme.sh "$restore_quarantine" || restore_failed=1
                restore_backup_file "$restore_dir/root/.config/vps-panel/cloudflare.env" /root/.config/vps-panel/cloudflare.env || restore_failed=1
                restore_backup_file "$restore_dir/etc/vps-optimize/sni-stack.env" /etc/vps-optimize/sni-stack.env || restore_failed=1
                restore_backup_file "$restore_dir/etc/vps-optimize/sni-stack.last-backup" /etc/vps-optimize/sni-stack.last-backup || restore_failed=1
                restore_backup_file "$restore_dir/etc/vps-optimize/443-engine.conf" /etc/vps-optimize/443-engine.conf || restore_failed=1
                restore_backup_file "$restore_dir/etc/vps-optimize/vpso-mux.yaml" /etc/vps-optimize/vpso-mux.yaml || restore_failed=1
                restore_backup_file "$restore_dir/etc/systemd/system/vpso-mux.service" /etc/systemd/system/vpso-mux.service || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/bin/vpso-mux" /usr/local/bin/vpso-mux || restore_failed=1
                restore_backup_file "$restore_dir/etc/vps-optimize/traffic-guard.conf" /etc/vps-optimize/traffic-guard.conf || restore_failed=1
                restore_backup_dir "$restore_dir/var/lib/vps-optimize/traffic-guard" /var/lib/vps-optimize/traffic-guard "$restore_quarantine" || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/bin/vps-traffic-guard-check" /usr/local/bin/vps-traffic-guard-check || restore_failed=1
                restore_backup_file "$restore_dir/etc/systemd/system/vps-traffic-guard.service" /etc/systemd/system/vps-traffic-guard.service || restore_failed=1
                restore_backup_file "$restore_dir/etc/systemd/system/vps-traffic-guard.timer" /etc/systemd/system/vps-traffic-guard.timer || restore_failed=1
                restore_backup_file "$restore_dir/etc/resolv.conf" /etc/resolv.conf || restore_failed=1
                restore_backup_file "$restore_dir/etc/systemd/resolved.conf.d/99-vps-optimize-dns.conf" /etc/systemd/resolved.conf.d/99-vps-optimize-dns.conf || restore_failed=1
                restore_backup_file "$restore_dir/etc/docker/daemon.json" /etc/docker/daemon.json || restore_failed=1
                restore_backup_file "$restore_dir/etc/fail2ban/jail.local" /etc/fail2ban/jail.local || restore_failed=1
                restore_backup_dir "$restore_dir/etc/sysctl.d" /etc/sysctl.d "$restore_quarantine" || restore_failed=1
                restore_backup_dir "$restore_dir/etc/x-ui" /etc/x-ui "$restore_quarantine" || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/x-ui/x-ui.db" /usr/local/x-ui/x-ui.db || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/x-ui/x-ui.db-wal" /usr/local/x-ui/x-ui.db-wal || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/x-ui/x-ui.db-shm" /usr/local/x-ui/x-ui.db-shm || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/x-ui/bin/x-ui.db" /usr/local/x-ui/bin/x-ui.db || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/x-ui/bin/x-ui.db-wal" /usr/local/x-ui/bin/x-ui.db-wal || restore_failed=1
                restore_backup_file "$restore_dir/usr/local/x-ui/bin/x-ui.db-shm" /usr/local/x-ui/bin/x-ui.db-shm || restore_failed=1
                backup_restore_custom_directories "$restore_dir" "$restore_quarantine" || restore_failed=1

                if [[ -d "$restore_dir/etc/sysctl.d" ]]; then
                    sysctl --system >/dev/null 2>&1
                fi
                if [[ -f "$restore_dir/etc/hostname" ]]; then
                    local restored_hostname
                    restored_hostname=$(cat /etc/hostname 2>/dev/null | head -n1)
                    restored_hostname="$(trim_input "$restored_hostname")"
                    if [[ -n "$restored_hostname" ]]; then
                        hostnamectl set-hostname "$restored_hostname" >/dev/null 2>&1 || hostname "$restored_hostname" 2>/dev/null || true
                    fi
                fi
                if [[ -f "$restore_dir/etc/systemd/system/vps-traffic-guard.timer" || -f "$restore_dir/etc/systemd/system/vps-traffic-guard.service" || -f "$restore_dir/etc/systemd/system/vpso-mux.service" ]]; then
                    systemctl daemon-reload >/dev/null 2>&1 || true
                fi

                local restart_failed=0
                local restart_rc=0
                restart_service_if_available sshd
                restart_rc=$?
                if [[ "$restart_rc" -eq 2 ]]; then
                    restart_service_if_available ssh
                    restart_rc=$?
                fi
                [[ "$restart_rc" -eq 1 ]] && restart_failed=1

                for svc in nginx caddy docker fail2ban systemd-resolved x-ui 3x-ui xray sing-box vpso-mux; do
                    restart_service_if_available "$svc"
                    restart_rc=$?
                    [[ "$restart_rc" -eq 1 ]] && restart_failed=1
                done

                backup_cleanup_temp_dir "$restore_dir" || true
                if [[ "$restore_failed" -eq 0 && "$restart_failed" -eq 0 ]]; then
                    echo -e "$(localized_text "${GREEN}✅ 回滚完成！建议立即验证 SSH、反代和容器服务状态。${PLAIN}" "${GREEN}✅ Rollback completed! It is recommended to verify SSH, reverse proxy and container service status immediately.${PLAIN}" "${GREEN}✅ Откат завершен! Рекомендуется немедленно проверить статус SSH, обратный прокси и контейнерной службы.${PLAIN}")"
                elif [[ "$restore_failed" -ne 0 ]]; then
                    echo -e "$(localized_text "${YELLOW}⚠️ 部分备份文件恢复失败，请检查权限、磁盘空间和 ${restore_quarantine}。${PLAIN}" "${YELLOW}⚠️ Partial backup file recovery failed, please check permissions, disk space and ${restore_quarantine}.${PLAIN}" "${YELLOW}⚠️ Не удалось частично восстановить файл резервной копии. Проверьте разрешения, место на диске и ${restore_quarantine}.${PLAIN}")"
                else
                    echo -e "$(localized_text "${YELLOW}⚠️ 回滚文件已写入，但至少一个服务重启失败，请立即查看 systemctl status。${PLAIN}" "${YELLOW}⚠️ The rollback file has been written, but at least one service failed to restart. Please check systemctl status immediately.${PLAIN}" "${YELLOW}⚠️ Файл отката записан, но как минимум одну службу не удалось перезапустить. Пожалуйста, немедленно проверьте статус systemctl.${PLAIN}")"
                fi
                ;;

            4)
                mapfile -t backups < <(ls -1t "$backup_root"/backup_*.tar.gz "$backup_root"/backup_*.tar.gz.enc 2>/dev/null)
                if [[ ${#backups[@]} -le 5 ]]; then
                    echo -e "$(localized_text "${BLUE}当前备份不超过 5 份，无需清理。${PLAIN}" "${BLUE}There are no more than five backups; no cleanup is needed.${PLAIN}" "${BLUE}Резервных копий не больше пяти; очистка не требуется.${PLAIN}")"
                else
                    confirm_danger "$(localized_text "隔离旧备份" "Quarantine old backups" "Поместить старые резервные копии в карантин")" "$(localized_text "会把第 6 份及更早的备份移入隔离目录，不会直接删除。" "The 6th and earlier backups will be moved to the quarantine directory and will not be deleted directly." "Шестая и более ранние резервные копии будут перемещены в каталог карантина и не будут удалены напрямую.")" "$(localized_text "如需恢复，可到 /etc/vps-optimize/quarantine/manual-backups 手动查看。保留最近 5 份不动。" "If you need to restore, you can go to /etc/vps-optimize/quarantine/manual-backups to check manually. Leave the last 5 copies unchanged." "Если вам нужно восстановить, вы можете перейти к /etc/vps-optimize/quarantine/manual-backups и проверить вручную. Последние 5 копий оставьте без изменений.")" || {
                        echo -e "$(localized_text "${BLUE}已取消旧备份隔离。${PLAIN}" "${BLUE}The old backup has been dequarantined.${PLAIN}" "${BLUE}Старая резервная копия выведена из карантина.${PLAIN}")"
                        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                        continue
                    }
                    for i in "${!backups[@]}"; do
                        if [[ "$i" -ge 5 ]]; then
                            quarantine_path "${backups[$i]}" "/etc/vps-optimize/quarantine/manual-backups" >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}⚠️ 隔离失败: ${backups[$i]}${PLAIN}" "${YELLOW}⚠️ Isolation failed: ${backups[$i]}${PLAIN}" "${YELLOW}⚠️ Сбой изоляции: ${backups[$i]}${PLAIN}")"
                        fi
                    done
                    echo -e "$(localized_text "${GREEN}✅ 旧备份隔离完成，最近 5 份备份已保留。${PLAIN}" "${GREEN}✅ Old backup isolation completed, the last 5 backups have been retained.${PLAIN}" "${GREEN}✅ Изоляция старых резервных копий завершена, последние 5 резервных копий сохранены.${PLAIN}")"
                fi
                ;;

            5)
                func_edit_applied_config_center
                ;;

            "?") show_backup_help ;;
            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择！${PLAIN}" "${RED}❌ Invalid selection!${PLAIN}" "${RED}❌ Неверный выбор!${PLAIN}")" ;;
        esac

        echo ""
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    done
}

# ---------------------------------------------------------
# Module: runtime.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Runtime privilege guard used before starting the menu.

# --- Runtime guard ---
ensure_runtime_root() {
    if [[ $EUID -ne 0 ]]; then
        localized_echo \
            "${RED}❌ 错误：请以 root 用户身份运行本脚本！${PLAIN}" \
            "${RED}❌ Error: run this script as root.${PLAIN}" \
            "${RED}❌ Ошибка: запустите этот скрипт от имени пользователя root.${PLAIN}"
        exit 1
    fi
}

acquire_vpso_session_lock() {
    local lock_dir="/run/lock"
    local lock_file="${lock_dir}/vps-optimize.lock"
    local owner=""

    command -v flock >/dev/null 2>&1 || {
        localized_echo \
            "${RED}❌ 缺少 flock，无法防止多个会话同时修改配置。${PLAIN}" \
            "${RED}❌ flock is required to prevent concurrent configuration changes.${PLAIN}" \
            "${RED}❌ Для защиты от одновременного изменения конфигурации требуется flock.${PLAIN}"
        exit 1
    }
    mkdir -p "$lock_dir" || exit 1
    exec {VPSO_SESSION_LOCK_FD}>>"$lock_file" || exit 1
    if ! flock -n "$VPSO_SESSION_LOCK_FD"; then
        owner=$(head -n 1 "$lock_file" 2>/dev/null || true)
        localized_echo \
            "${YELLOW}⚠️ 另一个 VPS-Optimize 会话正在运行：${owner:-状态未知}${PLAIN}" \
            "${YELLOW}⚠️ Another VPS-Optimize session is running: ${owner:-unknown}${PLAIN}" \
            "${YELLOW}⚠️ Уже запущен другой сеанс VPS-Optimize: ${owner:-неизвестно}${PLAIN}"
        exit 1
    fi
    : > "$lock_file"
    printf 'pid=%s started=%s\n' "$$" "$(date -Is 2>/dev/null || date)" >&"$VPSO_SESSION_LOCK_FD"
    trap release_vpso_session_lock EXIT
}

release_vpso_session_lock() {
    if [[ -n "${VPSO_SESSION_LOCK_FD:-}" ]]; then
        flock -u "$VPSO_SESSION_LOCK_FD" 2>/dev/null || true
        exec {VPSO_SESSION_LOCK_FD}>&-
        VPSO_SESSION_LOCK_FD=""
    fi
}

# ---------------------------------------------------------
# Module: system_core.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Base system initialization, hostname, hosts, and system toggles.

configure_system_timezone_for_init() {
    local current_tz choice custom_tz target_tz

    if ! command -v timedatectl >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 timedatectl，已保持当前系统时区。${PLAIN}" "${YELLOW}⚠️ timedatectl not detected, current system time zone has been maintained.${PLAIN}" "${YELLOW}⚠️ timedatectl не обнаружен, текущий часовой пояс системы сохранен.${PLAIN}")"
        return 0
    fi

    current_tz=$(timedatectl show -p Timezone --value 2>/dev/null || true)
    [[ -z "$current_tz" ]] && current_tz="$(localized_text "未设置/未知" "Not set/unknown" "Не установлено/неизвестно")"

    echo -e "$(localized_text "${CYAN}当前系统时区：${current_tz}${PLAIN}" "${CYAN}Current system time zone: ${current_tz}${PLAIN}" "${CYAN}Текущий часовой пояс системы: ${current_tz}${PLAIN}")"
    echo -e "$(localized_text "${GREEN}  1. 保持当前时区${PLAIN} ${YELLOW}(默认)${PLAIN}" "${GREEN}1. Keep the current time zone (default)${PLAIN}" "${GREEN}1. Сохранить текущий часовой пояс (по умолчанию)${PLAIN}")"
    echo -e "${GREEN}  2. Asia/Shanghai${PLAIN}"
    echo -e "${GREEN}  3. Asia/Tokyo${PLAIN}"
    echo -e "${GREEN}  4. UTC${PLAIN}"
    echo -e "$(localized_text "${GREEN}  5. 自定义时区${PLAIN}" "${GREEN}5. Custom time zone${PLAIN}" "${GREEN}5. Пользовательский часовой пояс${PLAIN}")"
    read_trimmed choice "$(localized_text "请选择基础初始化时区处理方式（默认 1）: " "Please select the basic initialization time zone processing method (default 1):" "Пожалуйста, выберите основной метод обработки часового пояса при инициализации (по умолчанию 1):")"

    case "${choice:-1}" in
        1)
            echo -e "$(localized_text "${BLUE}已保持当前时区：${current_tz}${PLAIN}" "${BLUE}Has maintained the current time zone: ${current_tz}${PLAIN}" "${BLUE}сохранил текущий часовой пояс: ${current_tz}.${PLAIN}")"
            return 0
            ;;
        2) target_tz="Asia/Shanghai" ;;
        3) target_tz="Asia/Tokyo" ;;
        4) target_tz="UTC" ;;
        5)
            read_trimmed custom_tz "$(localized_text "请输入 IANA 时区名称（例如 Europe/London）: " "Please enter the IANA time zone name (e.g. Europe/London):" "Введите название часового пояса IANA (например, Европа/Лондон):")"
            target_tz="$custom_tz"
            ;;
        *)
            echo -e "$(localized_text "${YELLOW}⚠️ 未选择有效选项，已保持当前时区：${current_tz}${PLAIN}" "${YELLOW}⚠️ No valid option selected, current time zone has been maintained: ${current_tz}${PLAIN}" "${YELLOW}⚠️ Не выбран правильный вариант, текущий часовой пояс сохранен: ${current_tz}${PLAIN}")"
            return 0
            ;;
    esac

    if [[ -z "$target_tz" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 自定义时区为空，已保持当前时区：${current_tz}${PLAIN}" "${YELLOW}⚠️ The custom time zone is empty, the current time zone has been maintained: ${current_tz}${PLAIN}" "${YELLOW}⚠️ Пользовательский часовой пояс пуст, текущий часовой пояс сохранен: ${current_tz}${PLAIN}")"
        return 0
    fi

    if timedatectl set-timezone "$target_tz" >/dev/null 2>&1; then
        echo -e "$(localized_text "${GREEN}✅ 系统时区已设置为：${target_tz}${PLAIN}" "${GREEN}✅ The system time zone has been set to: ${target_tz}${PLAIN}" "${GREEN}. Часовой пояс системы установлен на: ${target_tz}.${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 时区设置失败，已保持当前时区：${current_tz}${PLAIN}" "${YELLOW}⚠️ Time zone setting failed, current time zone has been maintained: ${current_tz}${PLAIN}" "${YELLOW}⚠️ Не удалось настроить часовой пояс, текущий часовой пояс сохранен: ${current_tz}${PLAIN}")"
        return 1
    fi
}

func_base_init() {
    local failed_steps=()
    local current_cc current_qdisc

    clear
    echo -e "$(localized_text "${CYAN}👉 正在更新系统软件包、安装基础工具、限制日志并开启基础 BBR...${PLAIN}" "${CYAN}👉 Updating system software packages, installing basic tools, limiting logs and enabling basics BBR...${PLAIN}" "${CYAN}👉 Обновление пакетов системного ПО, установка базовых инструментов, ограничение журналов и включение базовых функций BBR...${PLAIN}")"

    if is_debian; then
        export DEBIAN_FRONTEND=noninteractive
        if apt-get update -y && apt-get upgrade -y; then
            APT_UPDATED=1
        else
            failed_steps+=("$(localized_text "系统软件包更新" "System package update" "Обновление системных пакетов")")
        fi
        unset DEBIAN_FRONTEND
        install_pkg sudo curl wget git nano unzip htop lsof net-tools iputils-ping dnsutils iptables iproute2 sqlite3 jq \
            || failed_steps+=("$(localized_text "基础工具安装" "Base tool installation" "Установка базовых инструментов")")
    elif is_redhat; then
        if command -v dnf >/dev/null 2>&1; then
            dnf update -y || failed_steps+=("$(localized_text "系统软件包更新" "System package update" "Обновление системных пакетов")")
        else
            yum update -y || failed_steps+=("$(localized_text "系统软件包更新" "System package update" "Обновление системных пакетов")")
        fi
        install_pkg sudo curl wget git nano unzip htop lsof net-tools iputils bind-utils iptables iproute epel-release sqlite jq \
            || failed_steps+=("$(localized_text "基础工具安装" "Base tool installation" "Установка базовых инструментов")")
    else
        failed_steps+=("$(localized_text "当前发行版不受支持" "Unsupported distribution" "Дистрибутив не поддерживается")")
    fi

    ensure_minimal_system_compat || failed_steps+=("$(localized_text "精简系统兼容组件" "Minimal-system compatibility components" "Компоненты совместимости минимальной системы")")

    if ! mkdir -p /etc/systemd/journald.conf.d/ || ! cat > /etc/systemd/journald.conf.d/99-limit.conf <<EOF
[Journal]
SystemMaxUse=100M
RuntimeMaxUse=100M
EOF
    then
        failed_steps+=("$(localized_text "journald 日志限制" "journald log limit" "Ограничение журнала journald")")
    elif ! systemctl restart systemd-journald >/dev/null 2>&1; then
        failed_steps+=("$(localized_text "journald 重启" "journald restart" "Перезапуск journald")")
    fi

    configure_system_timezone_for_init || failed_steps+=("$(localized_text "时区设置" "Timezone configuration" "Настройка часового пояса")")

    modprobe tcp_bbr >/dev/null 2>&1 || true
    if ! {
        printf '%s\n' \
            "net.core.default_qdisc = fq" \
            "net.ipv4.tcp_congestion_control = bbr" \
            > /etc/sysctl.d/99-bbr-init.conf
    }; then
        failed_steps+=("$(localized_text "BBR 配置写入" "Write BBR configuration" "Запись конфигурации BBR")")
    elif ! sysctl -p /etc/sysctl.d/99-bbr-init.conf >/dev/null 2>&1; then
        failed_steps+=("$(localized_text "BBR 参数加载" "Load BBR parameters" "Загрузка параметров BBR")")
    else
        current_cc=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || true)
        current_qdisc=$(sysctl -n net.core.default_qdisc 2>/dev/null || true)
        if [[ "$current_cc" != "bbr" || "$current_qdisc" != "fq" ]]; then
            failed_steps+=("$(localized_text "BBR 状态验证" "Validate BBR status" "Проверка состояния BBR")")
        fi
    fi

    if [[ ${#failed_steps[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${GREEN}✅ 基础初始化完成，已验证 BBR 与 fq 生效。${PLAIN}" "${GREEN}✅ Basic initialization is completed, and BBR and fq have been verified to be effective.${PLAIN}" "${GREEN}✅ Базовая инициализация завершена, эффективность BBR и fq подтверждена.${PLAIN}")"
        if [[ "${VPSO_BEGINNER_FLOW:-0}" != "1" ]]; then
            read -n 1 -s -r -p "$(localized_text "按任意键返回主菜单..." "Press any key to return to the main menu..." "Нажмите любую клавишу, чтобы вернуться в главное меню...")"
        fi
        return 0
    fi

    echo -e "$(localized_text "${RED}❌ 基础初始化未完整完成，失败步骤：${PLAIN}" "${RED}❌ Basic initialization is not completely completed, failed step:${PLAIN}" "${RED}❌ Базовая инициализация не полностью завершена, не удалось выполнить шаг:${PLAIN}")"
    printf '  - %s\n' "${failed_steps[@]}"
    echo -e "$(localized_text "${YELLOW}已保留成功完成的步骤；请修复上述问题后重新运行基础初始化。${PLAIN}" "${YELLOW}Has retained successfully completed steps; please fix the above issue and rerun the basic initialization.${PLAIN}" "${YELLOW}сохранил успешно выполненные шаги; пожалуйста, исправьте вышеуказанную проблему и повторите базовую инициализацию.${PLAIN}")"
    if [[ "${VPSO_BEGINNER_FLOW:-0}" != "1" ]]; then
        read -n 1 -s -r -p "$(localized_text "按任意键返回主菜单..." "Press any key to return to the main menu..." "Нажмите любую клавишу, чтобы вернуться в главное меню...")"
    fi
    return 1
}

update_hosts_hostname_entry() {
    local old_name="$1"
    local new_name="$2"
    local tmp_file

    tmp_file=$(mktemp /tmp/vps-hosts.XXXXXX) || return 1
    awk -v old="$old_name" -v new="$new_name" '
        BEGIN { updated = 0 }
        $1 == "127.0.1.1" {
            print "127.0.1.1\t" new
            updated = 1
            next
        }
        {
            for (i = 2; i <= NF; i++) {
                if ($i == old) {
                    $i = new
                    updated = 1
                }
            }
            print
        }
        END {
            if (!updated) {
                print "127.0.1.1\t" new
            }
        }
    ' /etc/hosts > "$tmp_file" || {
        rm -f "$tmp_file"
        return 1
    }
    cp "$tmp_file" /etc/hosts
    rm -f "$tmp_file"
}

func_change_hostname() {
    local current_name new_name ts
    current_name=$(hostnamectl --static 2>/dev/null || hostname 2>/dev/null || cat /etc/hostname 2>/dev/null)
    current_name="$(trim_input "$current_name")"
    current_name="${current_name:-localhost}"

    echo -e "$(localized_text "当前主机名: ${CYAN}${current_name}${PLAIN}" "Current host name: ${CYAN}${current_name}${PLAIN}" "Текущее имя хоста: ${CYAN}${current_name}${PLAIN}.")"
    echo -e "$(localized_text "${YELLOW}主机名建议只使用字母、数字、连字符和点号；每段不能以连字符开头或结尾。${PLAIN}" "${YELLOW}It is recommended to use only letters, numbers, hyphens and periods for the host name; each paragraph cannot begin or end with a hyphen.${PLAIN}" "${YELLOW}В имени хоста рекомендуется использовать только буквы, цифры, дефисы и точки; каждый абзац не может начинаться или заканчиваться дефисом.${PLAIN}")"
    read_trimmed new_name "$(localized_text "请输入新的主机名（回车取消）: " "Please enter a new hostname (press enter to cancel):" "Пожалуйста, введите новое имя хоста (нажмите Enter, чтобы отменить):")"
    [[ -z "$new_name" || "$new_name" == "0" ]] && { echo -e "$(localized_text "${BLUE}已取消修改主机名。${PLAIN}" "${BLUE}The modification of the host name has been cancelled.${PLAIN}" "${BLUE}Изменение имени хоста отменено.${PLAIN}")"; return 0; }

    if ! is_valid_hostname "$new_name"; then
        echo -e "$(localized_text "${RED}❌ 主机名格式无效。示例：vps01 或 node-1.example.com${PLAIN}" "${RED}❌ The hostname format is invalid. Example: vps01 or node-1.example.com${PLAIN}" "${RED}❌ Неверный формат имени хоста. Пример: vps01 или node-1.example.com.${PLAIN}")"
        return 1
    fi

    if [[ "$new_name" == "$current_name" ]]; then
        echo -e "$(localized_text "${BLUE}主机名未变化。${PLAIN}" "${BLUE}The host name has not changed.${PLAIN}" "${BLUE}Имя хоста не изменилось.${PLAIN}")"
        return 0
    fi

    confirm_risk_action "$(localized_text "修改主机名为 ${new_name}" "Modify the host name to ${new_name}" "Измените имя хоста на ${new_name}.")" \
        "$(localized_text "/etc/hostname、/etc/hosts 和当前运行时 hostname" "/etc/hostname、/etc/hosts and current runtime hostname" "/etc/hostname、/etc/hosts и текущее имя хоста среды выполнения.")" \
        "$(localized_text "使用本功能改回 ${current_name}，或从 /etc/*.bak_时间戳 恢复" "Use this function to change back to ${current_name} or restore from /etc/*.bak_时间戳" "Используйте эту функцию для возврата к ${current_name} или восстановления с /etc/*.bak_时间戳.")" \
        "$(localized_text "少数服务会在重启后才读取新主机名。" "A few services will not read the new hostname until they are restarted." "Некоторые службы не будут считывать новое имя хоста до тех пор, пока не будут перезапущены.")" || return 1

    ts=$(date +%s)
    [[ -f /etc/hostname ]] && cp -p /etc/hostname "/etc/hostname.bak_${ts}" 2>/dev/null || true
    [[ -f /etc/hosts ]] && cp -p /etc/hosts "/etc/hosts.bak_${ts}" 2>/dev/null || true

    echo "$new_name" > /etc/hostname || {
        echo -e "$(localized_text "${RED}❌ 写入 /etc/hostname 失败。${PLAIN}" "${RED}❌ Failed to write /etc/hostname.${PLAIN}" "${RED}❌ Не удалось записать /etc/hostname.${PLAIN}")"
        return 1
    }

    if [[ -f /etc/hosts ]]; then
        update_hosts_hostname_entry "$current_name" "$new_name" || echo -e "$(localized_text "${YELLOW}⚠️ /etc/hosts 更新失败，请稍后手动检查。${PLAIN}" "${YELLOW}⚠️ /etc/hosts update failed, please check manually later.${PLAIN}" "${YELLOW}⚠️ Обновление /etc/hosts не удалось, проверьте вручную позже.${PLAIN}")"
    else
        {
            echo "127.0.0.1	localhost"
            echo "127.0.1.1	$new_name"
        } > /etc/hosts
    fi

    if command -v hostnamectl >/dev/null 2>&1; then
        hostnamectl set-hostname "$new_name" >/dev/null 2>&1 || hostname "$new_name" 2>/dev/null || true
    else
        hostname "$new_name" 2>/dev/null || true
    fi

    echo -e "$(localized_text "${GREEN}✅ 主机名已修改为：${new_name}${PLAIN}" "${GREEN}✅ The host name has been changed to: ${new_name}${PLAIN}" "${GREEN}. Имя хоста изменено на: ${new_name}.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}如部分服务仍显示旧名称，重启对应服务或下次重启系统后会完全生效。${PLAIN}" "${YELLOW}If some services still display the old names, restart the corresponding services or the next time the system is restarted, it will take full effect.${PLAIN}" "${YELLOW}Если некоторые службы по-прежнему отображают старые имена, перезапустите соответствующие службы или при следующем перезапуске системы это вступит в полную силу.${PLAIN}")"
}

hosts_managed_marker() {
    printf '%s' '# VPS-Optimize local-hosts'
}

hosts_is_valid_ip() {
    local ip="$1"
    [[ "$ip" != */* ]] || return 1
    dns_is_valid_ipv4 "$ip" || dns_is_valid_ipv6 "$ip"
}

hosts_normalize_names() {
    local raw="$1"
    local -n out_array=$2
    local item normalized seen=" "
    raw="${raw//，/,}"
    raw="${raw//、/,}"
    raw="${raw//；/,}"
    raw="${raw//;/,}"
    raw="${raw//,/ }"
    out_array=()
    for item in $raw; do
        normalized=$(normalize_domain_input "$item")
        [[ -z "$normalized" ]] && continue
        if ! is_valid_hostname "$normalized"; then
            echo -e "$(localized_text "${RED}❌ 主机名/域名格式无效：${normalized}${PLAIN}" "${RED}❌ Invalid host name/domain format: ${normalized}${PLAIN}" "${RED}❌ Неверный формат имени хоста/доменного имени: ${normalized}.${PLAIN}")"
            return 1
        fi
        case "$normalized" in
            localhost|localhost.localdomain|ip6-localhost|ip6-loopback)
                echo -e "$(localized_text "${RED}❌ 为避免破坏系统解析，不能管理保留名称：${normalized}${PLAIN}" "${RED}❌ To avoid damaging system resolution, the reserved name cannot be managed: ${normalized}${PLAIN}" "${RED}❌ Чтобы не повредить разрешение системы, нельзя управлять зарезервированным именем: ${normalized}.${PLAIN}")"
                return 1
                ;;
        esac
        if [[ "$seen" != *" ${normalized} "* ]]; then
            out_array+=("$normalized")
            seen+=" ${normalized} "
        fi
    done
    [[ ${#out_array[@]} -gt 0 ]]
}

hosts_backup_current() {
    local backup_dir="/etc/vps-optimize/backups/hosts"
    local backup_file
    mkdir -p "$backup_dir" || return 1
    backup_file="${backup_dir}/hosts.$(date +%Y%m%d_%H%M%S).bak"
    if [[ -f /etc/hosts ]]; then
        cp -p /etc/hosts "$backup_file" || return 1
    else
        : > "$backup_file" || return 1
    fi
    printf '%s' "$backup_file"
}

hosts_remove_names_to_tmp() {
    local names_csv="$1"
    local tmp_file="$2"
    local hosts_file="/etc/hosts"
    [[ -f "$hosts_file" ]] || : > "$hosts_file"
    awk -v names_csv="$names_csv" '
        BEGIN {
            split(names_csv, names, ",")
            for (i in names) target[names[i]] = 1
        }
        /^[[:space:]]*#/ || NF == 0 { print; next }
        {
            keep = 0
            line = $1
            for (i = 2; i <= NF; i++) {
                if ($i == "#") break
                if (!($i in target)) {
                    line = line "\t" $i
                    keep = 1
                }
            }
            if (keep) print line
        }
    ' "$hosts_file" > "$tmp_file"
}

hosts_add_or_update_entry() {
    local ip names_input names_csv names_joined backup_file tmp_file
    local -a names=()
    read_trimmed ip "$(localized_text "请输入解析 IP（IPv4/IPv6）: " "Please enter the resolution IP (IPv4/IPv6):" "Пожалуйста, введите IP-адрес разрешения (IPv4/IPv6):")"
    if ! hosts_is_valid_ip "$ip"; then
        echo -e "$(localized_text "${RED}❌ IP 格式无效。${PLAIN}" "${RED}❌ IP format is invalid.${PLAIN}" "${RED}❌ Неверный формат IP.${PLAIN}")"
        return 1
    fi
    read_trimmed names_input "$(localized_text "请输入要绑定的域名/主机名（多个用空格或逗号分隔）: " "Please enter the domain/host name to be bound (separate multiple names with spaces or commas):" "Пожалуйста, введите имя домена/имя хоста, к которому будет привязываться (разделяйте несколько имен пробелами или запятыми):")"
    if ! hosts_normalize_names "$names_input" names; then
        return 1
    fi
    names_csv=$(IFS=','; printf '%s' "${names[*]}")
    names_joined=$(IFS=' '; printf '%s' "${names[*]}")
    confirm_risk_action "$(localized_text "写入本机 hosts 解析" "Write to local hosts parsing" "Запись на локальные хосты, парсинг")" \
        "$(localized_text "/etc/hosts 本机解析表" "/etc/hosts local parsing table" "/etc/hosts локальная таблица синтаксического анализа")" \
        "$(localized_text "从 /etc/vps-optimize/backups/hosts 恢复最近备份，或在本菜单删除对应条目" "Restore the latest backup from /etc/vps-optimize/backups/hosts, or delete the corresponding entry in this menu" "Восстановите последнюю резервную копию из /etc/vps-optimize/backups/hosts или удалите соответствующую запись в этом меню.")" \
        "$(localized_text "本功能只影响当前 VPS 本机解析，不会修改公网 DNS。" "This function only affects the local resolution of the current VPS and will not modify the public DNS." "Эта функция влияет только на локальное разрешение текущего VPS и не изменяет публичную сеть DNS.")" || return 1

    backup_file=$(hosts_backup_current) || {
        echo -e "$(localized_text "${RED}❌ /etc/hosts 备份失败，已取消。${PLAIN}" "${RED}❌ /etc/hosts Backup failed and has been cancelled.${PLAIN}" "${RED}❌ /etc/hosts Резервное копирование не выполнено и было отменено.${PLAIN}")"
        return 1
    }
    tmp_file=$(mktemp /tmp/vps-hosts.XXXXXX) || return 1
    if hosts_remove_names_to_tmp "$names_csv" "$tmp_file"; then
        printf '%s\t%s\t%s\n' "$ip" "$names_joined" "$(hosts_managed_marker)" >> "$tmp_file"
        cp "$tmp_file" /etc/hosts
        echo -e "$(localized_text "${GREEN}✅ 已写入本机 hosts：${ip} -> ${names_joined}${PLAIN}" "${GREEN}✅ has been written to this machine hosts: ${ip} -> ${names_joined}${PLAIN}" "${GREEN}✅ был записан на хосты этой машины: ${ip} -> ${names_joined}${PLAIN}")"
        echo -e "$(localized_text "${CYAN}备份已保留：${backup_file}${PLAIN}" "${CYAN}Backup has been retained: ${backup_file}${PLAIN}" "${CYAN}Резервная копия сохранена: ${backup_file}.${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ 生成 hosts 临时文件失败，已取消。${PLAIN}" "${RED}❌ Failed to generate hosts temporary file and has been cancelled.${PLAIN}" "${RED}❌ Не удалось создать временный файл хостов, работа была отменена.${PLAIN}")"
        rm -f "$tmp_file"
        return 1
    fi
    rm -f "$tmp_file"
}

hosts_remove_entry() {
    local names_input names_csv names_joined backup_file tmp_file
    local -a names=()
    read_trimmed names_input "$(localized_text "请输入要删除解析的域名/主机名（多个用空格或逗号分隔）: " "Please enter the domain/host name to be deleted (separate multiple by spaces or commas):" "Пожалуйста, введите имя домена/хоста, которое необходимо удалить (разделяйте кратные пробелами или запятыми):")"
    if ! hosts_normalize_names "$names_input" names; then
        return 1
    fi
    names_csv=$(IFS=','; printf '%s' "${names[*]}")
    names_joined=$(IFS=' '; printf '%s' "${names[*]}")
    confirm_risk_action "$(localized_text "删除本机 hosts 解析" "Delete local hosts resolution" "Удалить разрешение локальных хостов")" \
        "$(localized_text "/etc/hosts 中与 ${names_joined} 匹配的解析项" "Parse items in /etc/hosts that match ${names_joined}" "Разобрать элементы в /etc/hosts, соответствующие ${names_joined}.")" \
        "$(localized_text "从 /etc/vps-optimize/backups/hosts 恢复最近备份" "Restore recent backup from /etc/vps-optimize/backups/hosts" "Восстановите последнюю резервную копию из /etc/vps-optimize/backups/hosts.")" \
        "$(localized_text "只删除匹配主机名，保留同一行其他别名。" "Remove only matching hostnames, leaving other aliases on the same line." "Удалите только совпадающие имена хостов, оставив другие псевдонимы в одной строке.")" || return 1

    backup_file=$(hosts_backup_current) || {
        echo -e "$(localized_text "${RED}❌ /etc/hosts 备份失败，已取消。${PLAIN}" "${RED}❌ /etc/hosts Backup failed and has been cancelled.${PLAIN}" "${RED}❌ /etc/hosts Резервное копирование не выполнено и было отменено.${PLAIN}")"
        return 1
    }
    tmp_file=$(mktemp /tmp/vps-hosts.XXXXXX) || return 1
    if hosts_remove_names_to_tmp "$names_csv" "$tmp_file"; then
        cp "$tmp_file" /etc/hosts
        echo -e "$(localized_text "${GREEN}✅ 已删除匹配的本机 hosts 解析：${names_joined}${PLAIN}" "${GREEN}✅ The matching local hosts have been deleted. Resolution: ${names_joined}${PLAIN}" "${GREEN}✅ Соответствующие локальные хосты были удалены. Разрешение: ${names_joined}${PLAIN}")"
        echo -e "$(localized_text "${CYAN}备份已保留：${backup_file}${PLAIN}" "${CYAN}Backup has been retained: ${backup_file}${PLAIN}" "${CYAN}Резервная копия сохранена: ${backup_file}.${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ 生成 hosts 临时文件失败，已取消。${PLAIN}" "${RED}❌ Failed to generate hosts temporary file and has been cancelled.${PLAIN}" "${RED}❌ Не удалось создать временный файл хостов, работа была отменена.${PLAIN}")"
        rm -f "$tmp_file"
        return 1
    fi
    rm -f "$tmp_file"
}

hosts_restore_latest_backup() {
    local latest
    latest=$(find /etc/vps-optimize/backups/hosts -maxdepth 1 -type f -name 'hosts.*.bak' 2>/dev/null | sort -r | head -n1)
    if [[ -z "$latest" ]]; then
        echo -e "$(localized_text "${YELLOW}未找到 hosts 备份。${PLAIN}" "${YELLOW}Hosts backup not found.${PLAIN}" "${YELLOW}Резервная копия хостов не найдена.${PLAIN}")"
        return 1
    fi
    confirm_risk_action "$(localized_text "恢复最近 hosts 备份" "Restore recent hosts backup" "Восстановить резервную копию последних хостов")" \
        "$(localized_text "/etc/hosts 将恢复为 ${latest}" "/etc/hosts will revert to ${latest}" "/etc/hosts вернется к ${latest}.")" \
        "$(localized_text "重新进入本菜单添加/删除解析，或手动恢复更新前备份" "Re-enter this menu to add/delete parses, or manually restore the backup before the update" "Повторно войдите в это меню, чтобы добавить/удалить анализы или вручную восстановить резервную копию перед обновлением.")" \
        "$(localized_text "恢复会覆盖当前本机 hosts 解析。" "Restoring overwrites the current native hosts resolution." "При восстановлении перезаписывается текущее собственное разрешение хостов.")" || return 1
    cp -p "$latest" /etc/hosts || {
        echo -e "$(localized_text "${RED}❌ 恢复失败。${PLAIN}" "${RED}❌ Recovery failed.${PLAIN}" "${RED}❌ Восстановление не удалось.${PLAIN}")"
        return 1
    }
    echo -e "$(localized_text "${GREEN}✅ 已恢复：${latest}${PLAIN}" "${GREEN}✅ Restored: ${latest}${PLAIN}" "${GREEN}✅ Восстановлено: ${latest}${PLAIN}")"
}

func_hosts_manage() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        print_breadcrumb "$(localized_text "系统开关与清理 > 本机 hosts 解析" "System switch and cleanup > Local hosts resolution" "Переключение и очистка системы > Разрешение локальных хостов")"
        echo -e "$(localized_text "${BOLD}🧭 本机 hosts 解析管理${PLAIN}" "${BOLD}🧭 Local hosts resolution management${PLAIN}" "${BOLD}🧭 Управление разрешением локальных хостов${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}用途：修改当前 VPS 的 /etc/hosts，本地指定域名解析到某个 IP。不会影响公网 DNS。${PLAIN}" "${YELLOW}Purpose: Modify the /etc/hosts of the current VPS and resolve the local specified domain to a certain IP. It will not affect the public DNS.${PLAIN}" "${YELLOW}Назначение: изменить /etc/hosts текущего VPS и разрешить указанное локальное доменное имя в определенный IP-адрес. Это не повлияет на публичную сеть DNS.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 查看当前 hosts${PLAIN}" "${GREEN}1. View current hosts${PLAIN}" "${GREEN}1. Просмотр текущих хостов${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 添加 / 更新本机解析${PLAIN}" "${GREEN}2. Add/update local resolution${PLAIN}" "${GREEN}2. Добавить/обновить локальное разрешение.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}  3. 删除本机解析${PLAIN}" "${YELLOW}3. Delete local resolution${PLAIN}" "${YELLOW}3. Удалить локальное разрешение.${PLAIN}")"
        echo -e "$(localized_text "${CYAN}  4. 恢复最近一次 hosts 备份${PLAIN}" "${CYAN}4. Restore the latest hosts backup${PLAIN}" "${CYAN}4. Восстановите последнюю резервную копию хостов.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}  0. 返回上一级 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        local choice
        read_trimmed choice "$(localized_text "👉 请选择操作: " "👉 Please select an operation:" "👉 Пожалуйста, выберите операцию:")"
        case "$choice" in
            1)
                echo -e "${CYAN}--- /etc/hosts ---${PLAIN}"
                sed -n '1,120p' /etc/hosts 2>/dev/null || echo "$(localized_text "未检测到 /etc/hosts" "/etc/hosts not detected" "/etc/hosts не обнаружен")"
                pause_return
                ;;
            2) hosts_add_or_update_entry; pause_return ;;
            3) hosts_remove_entry; pause_return ;;
            4) hosts_restore_latest_backup; pause_return ;;
            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择！${PLAIN}" "${RED}❌ Invalid selection!${PLAIN}" "${RED}❌ Неверный выбор!${PLAIN}")"; sleep 1 ;;
        esac
    done
}

# ---------------------------------------------------------
# 2. 系统高级开关 (已修复显示丢失问题)
# ---------------------------------------------------------
func_system_tweaks() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}⚙️ 系统开关与清理${PLAIN}" "${BOLD}⚙️ System switch and cleaning${PLAIN}" "${BOLD}⚙️ Системный переключатель и очистка${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        # 状态获取
        local ipv6_status
        local str_ipv6
        ipv6_status=$(cat /proc/sys/net/ipv6/conf/all/disable_ipv6 2>/dev/null)
        if [[ "$ipv6_status" == "0" ]]; then str_ipv6="$(localized_text "${GREEN}开启中${PLAIN}" "${GREEN}Is opening${PLAIN}" "${GREEN}открывает${PLAIN}")"; else str_ipv6="$(localized_text "${RED}已禁用${PLAIN}" "${RED}Disabled${PLAIN}" "${RED}отключен${PLAIN}")"; fi

        local str_ipv4_first
        if grep -q "^precedence ::ffff:0:0/96  100" /etc/gai.conf 2>/dev/null; then
            str_ipv4_first="$(localized_text "${GREEN}已优先${PLAIN}" "${GREEN}Has given priority to${PLAIN}" "${GREEN}отдал приоритет${PLAIN}")"
        else
            str_ipv4_first="$(localized_text "${RED}默认(IPv6优先)${PLAIN}" "${RED}Default (IPv6 takes priority)${PLAIN}" "${RED}по умолчанию (IPv6 имеет приоритет)${PLAIN}")"
        fi

        local ping_status
        local str_ping
        ping_status=$(cat /proc/sys/net/ipv4/icmp_echo_ignore_all 2>/dev/null)
        if [[ "$ping_status" == "0" ]]; then str_ping="$(localized_text "${GREEN}允许被Ping${PLAIN}" "${GREEN}Is allowed to be Ping${PLAIN}" "${GREEN}может быть Ping${PLAIN}")"; else str_ping="$(localized_text "${RED}禁Ping中${PLAIN}" "${RED}Ping banned${PLAIN}" "${RED}Пинг запрещен${PLAIN}")"; fi

        local update_status
        local str_update
        if [[ "$OS" =~ debian|ubuntu ]]; then
            update_status=$(systemctl is-active unattended-upgrades 2>/dev/null)
        else
            update_status=$(systemctl is-active dnf-automatic.timer 2>/dev/null)
        fi
        if [[ "$update_status" == "active" ]]; then str_update="$(localized_text "${GREEN}开启中${PLAIN}" "${GREEN}Is opening${PLAIN}" "${GREEN}открывает${PLAIN}")"; else str_update="$(localized_text "${RED}已关闭${PLAIN}" "${RED}Has closed${PLAIN}" "${RED}закрылся${PLAIN}")"; fi

        local current_hostname
        current_hostname=$(hostnamectl --static 2>/dev/null || hostname 2>/dev/null || cat /etc/hostname 2>/dev/null)
        current_hostname="$(trim_input "$current_hostname")"
        current_hostname="$(localized_text "${current_hostname:-未知}" "${current_hostname:-未知}" "${current_hostname:-未知}")"

        # 完美修复：一字不落的菜单显示
        echo -e "$(localized_text "${GREEN}  1. IPv6 开关${PLAIN}              当前: [ $str_ipv6 ]" "${GREEN}1. IPv6 switch${PLAIN} Current: [ $str_ipv6 ]" "${GREEN}1. Переключатель IPv6${PLAIN} Ток: [ $str_ipv6 ]")"
        echo -e "$(localized_text "${GREEN}  2. IPv4 出站优先${PLAIN}          当前: [ $str_ipv4_first ]" "${GREEN}2. IPv4 Outbound priority${PLAIN} Current: [ $str_ipv4_first ]" "${GREEN}2. IPv4 Приоритет исходящего вызова${PLAIN} Текущий: [ $str_ipv4_first ]")"
        echo -e "$(localized_text "${GREEN}  3. Ping 响应开关${PLAIN}          当前: [ $str_ping ]" "${GREEN}3. Ping response switch${PLAIN} Current: [ $str_ping ]" "${GREEN}3. Переключатель ответа на запрос Ping${PLAIN} Ток: [ $str_ping ]")"
        echo -e "$(localized_text "${GREEN}  4. 本机 hosts 解析管理${PLAIN}    (/etc/hosts 本机域名解析)" "${GREEN}4. Local hosts resolution management${PLAIN} (/etc/hosts local domain resolution)" "${GREEN}4. Управление разрешением локальных хостов${PLAIN} (разрешение локального доменного имени /etc/hosts)")"
        echo -e "$(localized_text "${GREEN}  5. 修改主机名${PLAIN}             当前: [ ${CYAN}${current_hostname}${PLAIN} ]" "${GREEN}5. Modify the host name${PLAIN} Current: [ ${CYAN}${current_hostname}${PLAIN} ]" "${GREEN}5. Измените имя хоста${PLAIN} Текущее: [ ${CYAN}${current_hostname}${PLAIN} ]")"
        echo -e "$(localized_text "${GREEN}  6. 自动安全更新开关${PLAIN}       当前: [ $str_update ]" "${GREEN}6. Automatic security update switch${PLAIN} Current: [ $str_update ]" "${GREEN}6. Переключатель автоматического обновления безопасности${PLAIN} Текущая версия: [ $str_update ]")"
        echo -e "$(localized_text "${GREEN}  7. 清理系统垃圾${PLAIN}           (日志/缓存/无用包)" "${GREEN}7. Clean up system garbage${PLAIN} (log/cache/useless packages)" "${GREEN}7. Очистка системного мусора${PLAIN} (журнал/кеш/бесполезные пакеты)")"
        echo -e "$(localized_text "${RED}  8. 系统重装${PLAIN}               (重启后清空主硬盘；高风险)" "${RED}8. System reinstallation${PLAIN} (erases the main disk after reboot; high risk)" "${RED}8. Переустановка системы${PLAIN} (очистит основной диск после перезагрузки; высокий риск)")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}  0. 返回主菜单 / q 返回${PLAIN}" "${RED}0. Main menu / q Back${PLAIN}" "${RED}0. Главное меню / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local tweak_choice
        read_trimmed tweak_choice "$(localized_text "👉 请选择操作: " "👉 Please select an operation:" "👉 Пожалуйста, выберите операцию:")"

        case $tweak_choice in
            1)
                read_trimmed yn "$(localized_text "❓ 开启 IPv6？(y 开启 / n 关闭): " "❓ Turn on IPv6? (y on / n off):" "❓ Включить IPv6? (да вкл./нет выкл.):")"
                if is_yes "$yn"; then
                    quarantine_path /etc/sysctl.d/99-disable-ipv6.conf "/etc/vps-optimize/quarantine/sysctl" >/dev/null 2>&1 || true
                    sysctl -w net.ipv6.conf.all.disable_ipv6=0 >/dev/null 2>&1
                    echo -e "$(localized_text "${GREEN}✅ IPv6 已开启${PLAIN}" "${GREEN}✅ IPv6 has opened${PLAIN}" "${GREEN}✅ IPv6 открылся${PLAIN}")"
                elif is_no "$yn"; then
                    [[ -f /etc/sysctl.d/99-disable-ipv6.conf ]] && cp -p /etc/sysctl.d/99-disable-ipv6.conf "/etc/sysctl.d/99-disable-ipv6.conf.bak_$(date +%s)" 2>/dev/null || true
                    echo "net.ipv6.conf.all.disable_ipv6 = 1" > /etc/sysctl.d/99-disable-ipv6.conf
                    sysctl -p /etc/sysctl.d/99-disable-ipv6.conf >/dev/null 2>&1
                    echo -e "$(localized_text "${RED}✅ IPv6 已禁用${PLAIN}" "${RED}✅ IPv6 has disabled${PLAIN}" "${RED}✅ IPv6 отключил${PLAIN}")"
                fi; sleep 1 ;;
            2)
                read_trimmed yn "$(localized_text "❓ 设置 IPv4 为最高出站优先级？(y 开启 / n 恢复默认): " "❓ Set IPv4 as the highest outbound priority? (y turns on / n returns to default):" "❓ Установить IPv4 как наивысший исходящий приоритет? (y включается/n возвращается к настройкам по умолчанию):")"
                if is_yes "$yn"; then
                    [[ -f /etc/gai.conf ]] || touch /etc/gai.conf
                    cp -p /etc/gai.conf "/etc/gai.conf.bak_$(date +%s)" 2>/dev/null || true
                    sed -Ei '/^[[:space:]]*#?[[:space:]]*precedence[[:space:]]+::ffff:0:0\/96[[:space:]]+100\b.*?$/ {s/.+100\b([[:space:]]*#.*)?$/precedence ::ffff:0:0\/96  100\1/; :a;n;b a}; /^[[:space:]]*precedence[[:space:]]+::ffff:0:0\/96[[:space:]]+[0-9]+.*$/ {s/^.*precedence.+::ffff:0:0\/96[^0-9]+([0-9]+).*$/precedence ::ffff:0:0\/96  100\t#原值为 \1/; :a;n;ba;}; $aprecedence ::ffff:0:0\/96  100' /etc/gai.conf
                    echo -e "$(localized_text "${GREEN}✅ 已设为 IPv4 优先${PLAIN}" "${GREEN}✅ has been set to IPv4, giving priority to${PLAIN}" "${GREEN}Для вещества установлено значение IPv4, что дает приоритет.${PLAIN}")"
                elif is_no "$yn"; then
                    [[ -f /etc/gai.conf ]] || touch /etc/gai.conf
                    cp -p /etc/gai.conf "/etc/gai.conf.bak_$(date +%s)" 2>/dev/null || true
                    sed -i '/precedence ::ffff:0:0\/96  100/d' /etc/gai.conf
                    echo -e "$(localized_text "${BLUE}已恢复系统默认${PLAIN}" "${BLUE}Has restored the system default${PLAIN}" "${BLUE}восстановил системные настройки по умолчанию${PLAIN}")"
                fi; sleep 1 ;;
            3)
                read_trimmed yn "$(localized_text "❓ 允许被 Ping？(y 允许 / n 禁止): " "❓ Allow to be pinged? (y allowed / n forbidden):" "❓ Разрешить пинговать? (y разрешено/n запрещено):")"
                if is_yes "$yn"; then
                    quarantine_path /etc/sysctl.d/99-disable-ping.conf "/etc/vps-optimize/quarantine/sysctl" >/dev/null 2>&1 || true
                    sysctl -w net.ipv4.icmp_echo_ignore_all=0 >/dev/null 2>&1
                    echo -e "$(localized_text "${GREEN}✅ 已允许被 Ping${PLAIN}" "${GREEN}✅ has been allowed to be Ping${PLAIN}" "${GREEN}веществу разрешено быть Ping${PLAIN}")"
                elif is_no "$yn"; then
                    [[ -f /etc/sysctl.d/99-disable-ping.conf ]] && cp -p /etc/sysctl.d/99-disable-ping.conf "/etc/sysctl.d/99-disable-ping.conf.bak_$(date +%s)" 2>/dev/null || true
                    echo "net.ipv4.icmp_echo_ignore_all = 1" > /etc/sysctl.d/99-disable-ping.conf
                    sysctl -p /etc/sysctl.d/99-disable-ping.conf >/dev/null 2>&1
                    echo -e "$(localized_text "${RED}✅ 已开启禁 Ping 保护${PLAIN}" "${RED}✅ Ping ban protection has been enabled${PLAIN}" "${RED}✅ Защита от блокировки Ping включена${PLAIN}")"
                fi; sleep 1 ;;
            4) func_hosts_manage ;;
            5) func_change_hostname; sleep 1 ;;
            6)
                read_trimmed yn "$(localized_text "❓ 开启系统自动更新？(y 开启 / n 关闭): " "❓ Turn on automatic system updates? (y on / n off):" "❓ Включить автоматическое обновление системы? (да вкл./нет выкл.):")"
                if is_yes "$yn"; then
                    if [[ "$OS" =~ debian|ubuntu ]]; then
                        install_pkg unattended-upgrades || { echo -e "$(localized_text "${RED}❌ unattended-upgrades 安装失败。${PLAIN}" "${RED}❌ unattended-upgrades Installation failed.${PLAIN}" "${RED}❌ автоматические обновления Установка не удалась.${PLAIN}")"; sleep 1; continue; }
                        systemctl enable --now unattended-upgrades >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}⚠️ unattended-upgrades 服务启用失败，请手动检查。${PLAIN}" "${YELLOW}⚠️ unattended-upgrades Service activation failed, please check manually.${PLAIN}" "${YELLOW}⚠️ unattended-upgrades Не удалось активировать службу, проверьте вручную.${PLAIN}")"
                    else
                        install_pkg dnf-automatic || { echo -e "$(localized_text "${RED}❌ dnf-automatic 安装失败。${PLAIN}" "${RED}❌ dnf-automatic installation failed.${PLAIN}" "${RED}❌ dnf-автоматическая установка не удалась.${PLAIN}")"; sleep 1; continue; }
                        systemctl enable --now dnf-automatic.timer >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}⚠️ dnf-automatic.timer 启用失败，请手动检查。${PLAIN}" "${YELLOW}⚠️ dnf-automatic.timer failed to be enabled, please check manually.${PLAIN}" "${YELLOW}⚠️ Не удалось включить dnf-automatic.timer, проверьте вручную.${PLAIN}")"
                    fi
                    echo -e "$(localized_text "${GREEN}✅ 自动更新已开启${PLAIN}" "${GREEN}✅ Automatic update is turned on${PLAIN}" "${GREEN}✅ Автоматическое обновление включено${PLAIN}")"
                elif is_no "$yn"; then
                    if [[ "$OS" =~ debian|ubuntu ]]; then systemctl disable --now unattended-upgrades >/dev/null 2>&1
                    else systemctl disable --now dnf-automatic.timer >/dev/null 2>&1; fi
                    echo -e "$(localized_text "${GREEN}✅ 自动更新已关闭${PLAIN}" "${GREEN}✅ Automatic updates are turned off${PLAIN}" "${GREEN}✅ Автоматические обновления отключены${PLAIN}")"
                fi; sleep 1 ;;
            7)
                echo -e "$(localized_text "${CYAN}👉 正在深度清理系统垃圾...${PLAIN}" "${CYAN}👉 Deep cleaning of system junk...${PLAIN}" "${CYAN}👉 Глубокая очистка системного мусора...${PLAIN}")"
                if [[ "$OS" =~ debian|ubuntu ]]; then
                    apt autoremove --purge -y >/dev/null 2>&1
                    apt clean >/dev/null 2>&1
                else
                    yum autoremove -y >/dev/null 2>&1
                    yum clean all >/dev/null 2>&1
                fi
                journalctl --vacuum-time=1d > /dev/null 2>&1
                echo -e "$(localized_text "${GREEN}✅ 清理完成！${PLAIN}" "${GREEN}✅ Cleanup completed!${PLAIN}" "${GREEN}✅ Очистка завершена!${PLAIN}")"
                sleep 1 ;;
            8) func_system_reinstall ;;
            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择！${PLAIN}" "${RED}❌ Invalid selection!${PLAIN}" "${RED}❌ Неверный выбор!${PLAIN}")"; sleep 1 ;;
        esac
    done
}

# ---------------------------------------------------------
# 统一包管理与执行守卫 (新增：请放在 func_env_install 函数上方)
# ---------------------------------------------------------

# ---------------------------------------------------------
# Module: system_reinstall.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# System reinstallation workflow backed by bin456789/reinstall.

SYSTEM_REINSTALL_UPSTREAM_URL="https://raw.githubusercontent.com/bin456789/reinstall/main/reinstall.sh"
SYSTEM_REINSTALL_SCRIPT="/usr/local/lib/vps-optimize/reinstall.sh"

system_reinstall_windows_language() {
    case "$VPSO_LANGUAGE" in
        en) printf 'en-us' ;;
        ru) printf 'ru-ru' ;;
        *) printf 'zh-cn' ;;
    esac
}

system_reinstall_set_target() {
    local choice="$1"
    local windows_language
    SYSTEM_REINSTALL_TARGET=()
    SYSTEM_REINSTALL_LABEL=""
    windows_language=$(system_reinstall_windows_language)

    case "$choice" in
        1) SYSTEM_REINSTALL_TARGET=(debian 13); SYSTEM_REINSTALL_LABEL="Debian 13" ;;
        2) SYSTEM_REINSTALL_TARGET=(debian 12); SYSTEM_REINSTALL_LABEL="Debian 12" ;;
        3) SYSTEM_REINSTALL_TARGET=(debian 11); SYSTEM_REINSTALL_LABEL="Debian 11" ;;
        4) SYSTEM_REINSTALL_TARGET=(debian 10); SYSTEM_REINSTALL_LABEL="Debian 10" ;;
        11) SYSTEM_REINSTALL_TARGET=(ubuntu 26.04); SYSTEM_REINSTALL_LABEL="Ubuntu 26.04" ;;
        12) SYSTEM_REINSTALL_TARGET=(ubuntu 24.04); SYSTEM_REINSTALL_LABEL="Ubuntu 24.04" ;;
        13) SYSTEM_REINSTALL_TARGET=(ubuntu 22.04); SYSTEM_REINSTALL_LABEL="Ubuntu 22.04" ;;
        14) SYSTEM_REINSTALL_TARGET=(ubuntu 20.04); SYSTEM_REINSTALL_LABEL="Ubuntu 20.04" ;;
        21) SYSTEM_REINSTALL_TARGET=(rocky 10); SYSTEM_REINSTALL_LABEL="Rocky Linux 10" ;;
        22) SYSTEM_REINSTALL_TARGET=(rocky 9); SYSTEM_REINSTALL_LABEL="Rocky Linux 9" ;;
        23) SYSTEM_REINSTALL_TARGET=(almalinux 10); SYSTEM_REINSTALL_LABEL="AlmaLinux 10" ;;
        24) SYSTEM_REINSTALL_TARGET=(almalinux 9); SYSTEM_REINSTALL_LABEL="AlmaLinux 9" ;;
        25) SYSTEM_REINSTALL_TARGET=(oracle 10); SYSTEM_REINSTALL_LABEL="Oracle Linux 10" ;;
        26) SYSTEM_REINSTALL_TARGET=(oracle 9); SYSTEM_REINSTALL_LABEL="Oracle Linux 9" ;;
        27) SYSTEM_REINSTALL_TARGET=(fedora 44); SYSTEM_REINSTALL_LABEL="Fedora Linux 44" ;;
        28) SYSTEM_REINSTALL_TARGET=(fedora 43); SYSTEM_REINSTALL_LABEL="Fedora Linux 43" ;;
        29) SYSTEM_REINSTALL_TARGET=(centos 10); SYSTEM_REINSTALL_LABEL="CentOS Stream 10" ;;
        30) SYSTEM_REINSTALL_TARGET=(centos 9); SYSTEM_REINSTALL_LABEL="CentOS Stream 9" ;;
        31) SYSTEM_REINSTALL_TARGET=(alpine 3.24); SYSTEM_REINSTALL_LABEL="Alpine Linux 3.24" ;;
        32) SYSTEM_REINSTALL_TARGET=(arch); SYSTEM_REINSTALL_LABEL="Arch Linux" ;;
        33) SYSTEM_REINSTALL_TARGET=(kali); SYSTEM_REINSTALL_LABEL="Kali Linux" ;;
        34) SYSTEM_REINSTALL_TARGET=(openeuler 24.03); SYSTEM_REINSTALL_LABEL="openEuler 24.03" ;;
        35) SYSTEM_REINSTALL_TARGET=(opensuse tumbleweed); SYSTEM_REINSTALL_LABEL="openSUSE Tumbleweed" ;;
        36) SYSTEM_REINSTALL_TARGET=(fnos 1); SYSTEM_REINSTALL_LABEL="fnOS 1" ;;
        41) SYSTEM_REINSTALL_TARGET=(windows --image-name "Windows 11 Pro" --lang "$windows_language"); SYSTEM_REINSTALL_LABEL="Windows 11 Pro" ;;
        42) SYSTEM_REINSTALL_TARGET=(windows --image-name "Windows 10 Pro" --lang "$windows_language"); SYSTEM_REINSTALL_LABEL="Windows 10 Pro" ;;
        44) SYSTEM_REINSTALL_TARGET=(windows --image-name "Windows Server 2025 Standard" --lang "$windows_language"); SYSTEM_REINSTALL_LABEL="Windows Server 2025 Standard" ;;
        45) SYSTEM_REINSTALL_TARGET=(windows --image-name "Windows Server 2022 Standard" --lang "$windows_language"); SYSTEM_REINSTALL_LABEL="Windows Server 2022 Standard" ;;
        46) SYSTEM_REINSTALL_TARGET=(windows --image-name "Windows Server 2019 Standard" --lang "$windows_language"); SYSTEM_REINSTALL_LABEL="Windows Server 2019 Standard" ;;
        47) SYSTEM_REINSTALL_TARGET=(windows --image-name "Windows 11 Pro" --lang "$windows_language"); SYSTEM_REINSTALL_LABEL="Windows 11 Pro ARM" ;;
        *) return 1 ;;
    esac
}

system_reinstall_set_windows7_target() {
    local iso_url="$1"
    local windows_language

    case "$iso_url" in
        http://*|https://*|magnet:*) ;;
        *) return 1 ;;
    esac

    windows_language=$(system_reinstall_windows_language)
    SYSTEM_REINSTALL_TARGET=(windows --image-name "Windows 7 Ultimate" --lang "$windows_language" --iso "$iso_url")
    SYSTEM_REINSTALL_LABEL="Windows 7 Ultimate"
}

system_reinstall_is_windows_target() {
    [[ "${SYSTEM_REINSTALL_TARGET[0]:-}" == "windows" ]]
}

system_reinstall_is_valid_ssh_public_key() {
    local ssh_key="$1"
    local key_type key_data

    [[ "$ssh_key" != *$'\n'* && "$ssh_key" != *$'\r'* ]] || return 1
    read -r key_type key_data _ <<<"$ssh_key"
    case "$key_type" in
        ssh-rsa|ssh-ed25519|ecdsa-sha2-nistp256|ecdsa-sha2-nistp384|ecdsa-sha2-nistp521) ;;
        *) return 1 ;;
    esac
    [[ "$key_data" =~ ^[A-Za-z0-9+/]+={0,2}$ ]]
}

system_reinstall_set_password() {
    local password="$1"

    [[ -n "$password" ]] || return 1
    SYSTEM_REINSTALL_AUTH_MODE="password"
    SYSTEM_REINSTALL_ACCESS_ARGS=(--password "$password")
}

system_reinstall_set_ssh_key() {
    local ssh_key="$1"

    system_reinstall_is_valid_ssh_public_key "$ssh_key" || return 1
    SYSTEM_REINSTALL_AUTH_MODE="ssh_key"
    SYSTEM_REINSTALL_ACCESS_ARGS=(--ssh-key "$ssh_key")
}

system_reinstall_set_ssh_port() {
    local ssh_port

    ssh_port=$(normalize_port_input "$1")
    is_valid_port "$ssh_port" || return 1
    SYSTEM_REINSTALL_SSH_PORT="$ssh_port"
}

system_reinstall_read_password() {
    local password password_confirm

    while true; do
        IFS= read -r -p "$(localized_text "设置登录密码（输入会明文显示）: " "Set login password (input is visible): " "Введите пароль для входа (ввод отображается): ")" password || return 1
        if ! system_reinstall_set_password "$password"; then
            echo -e "$(localized_text "${RED}❌ 密码不能为空。${PLAIN}" "${RED}❌ Password cannot be empty.${PLAIN}" "${RED}❌ Пароль не может быть пустым.${PLAIN}")"
            continue
        fi

        printf '%b%s%b%s\n' "$YELLOW" "$(localized_text "将写入的密码：" "Password to be set: " "Устанавливаемый пароль: ")" "$PLAIN" "$password"
        IFS= read -r -p "$(localized_text "再次输入密码确认（输入会明文显示）: " "Retype password to confirm (input is visible): " "Повторите пароль для подтверждения (ввод отображается): ")" password_confirm || return 1
        if [[ "$password" == "$password_confirm" ]]; then
            printf '%b%s%b%s\n' "$GREEN" "$(localized_text "密码已确认：" "Password confirmed: " "Пароль подтверждён: ")" "$PLAIN" "$password"
            return 0
        fi

        echo -e "$(localized_text "${RED}❌ 两次密码不一致，请重新输入。${PLAIN}" "${RED}❌ Passwords do not match. Try again.${PLAIN}" "${RED}❌ Пароли не совпадают. Повторите ввод.${PLAIN}")"
    done
}

system_reinstall_read_ssh_key() {
    local ssh_key

    while true; do
        IFS= read -r -p "$(localized_text "SSH 公钥（单行）: " "SSH public key (one line): " "Открытый ключ SSH (одна строка): ")" ssh_key || return 1
        if system_reinstall_set_ssh_key "$ssh_key"; then
            echo -e "$(localized_text "${GREEN}✅ SSH 公钥格式检查通过。${PLAIN}" "${GREEN}✅ SSH public-key format accepted.${PLAIN}" "${GREEN}✅ Формат открытого ключа SSH принят.${PLAIN}")"
            return 0
        fi

        echo -e "$(localized_text "${RED}❌ SSH 公钥格式无效，仅支持单行 ssh-rsa、ssh-ed25519 或 ecdsa-sha2-nistp* 公钥。${PLAIN}" "${RED}❌ Invalid SSH public-key format. Use a one-line ssh-rsa, ssh-ed25519, or ecdsa-sha2-nistp* public key.${PLAIN}" "${RED}❌ Недопустимый формат открытого ключа SSH. Используйте однострочный ключ ssh-rsa, ssh-ed25519 или ecdsa-sha2-nistp*.${PLAIN}")"
    done
}

system_reinstall_read_ssh_port() {
    local ssh_port

    while true; do
        IFS= read -r -p "$(localized_text "SSH 登录端口 [22]: " "SSH login port [22]: " "Порт входа SSH [22]: ")" ssh_port || return 1
        ssh_port=${ssh_port:-22}
        if system_reinstall_set_ssh_port "$ssh_port"; then
            echo -e "$(localized_text "${YELLOW}请确认云厂商安全组和防火墙允许 TCP ${SYSTEM_REINSTALL_SSH_PORT}。${PLAIN}" "${YELLOW}Ensure the cloud security group and firewall allow TCP ${SYSTEM_REINSTALL_SSH_PORT}.${PLAIN}" "${YELLOW}Убедитесь, что облачная группа безопасности и межсетевой экран разрешают TCP ${SYSTEM_REINSTALL_SSH_PORT}.${PLAIN}")"
            return 0
        fi

        echo -e "$(localized_text "${RED}❌ SSH 端口必须在 1-65535。${PLAIN}" "${RED}❌ SSH port must be between 1 and 65535.${PLAIN}" "${RED}❌ Порт SSH должен быть от 1 до 65535.${PLAIN}")"
    done
}

system_reinstall_collect_access_options() {
    local access_choice

    SYSTEM_REINSTALL_AUTH_MODE=""
    SYSTEM_REINSTALL_ACCESS_ARGS=()
    SYSTEM_REINSTALL_SSH_PORT=""
    while true; do
        echo -e "$(localized_text "${BOLD}登录方式${PLAIN}" "${BOLD}Login method${PLAIN}" "${BOLD}Способ входа${PLAIN}")"
        echo -e "  1. $(localized_text "密码登录" "Password" "Пароль")"
        echo -e "  2. $(localized_text "SSH 公钥登录" "SSH public key" "Открытый ключ SSH")"
        echo -e "  0. $(localized_text "返回系统选择" "Back to system selection" "Назад к выбору системы")"
        if system_reinstall_is_windows_target; then
            echo -e "$(localized_text "${YELLOW}Windows 重装不支持 SSH 公钥，选择 [1] 设置密码。${PLAIN}" "${YELLOW}Windows reinstallation does not support SSH public keys; select [1] to set a password.${PLAIN}" "${YELLOW}Переустановка Windows не поддерживает открытые ключи SSH; выберите [1], чтобы задать пароль.${PLAIN}")"
        fi

        read_trimmed access_choice "$(localized_text "选择登录方式: " "Select login method: " "Выберите способ входа: ")"
        case "$access_choice" in
            0|q|Q) return 1 ;;
            1)
                system_reinstall_read_password || return 1
                break
                ;;
            2)
                if system_reinstall_is_windows_target; then
                    echo -e "$(localized_text "${RED}❌ Windows 不支持 SSH 公钥登录。${PLAIN}" "${RED}❌ Windows does not support SSH public-key login.${PLAIN}" "${RED}❌ Windows не поддерживает вход по открытому ключу SSH.${PLAIN}")"
                    continue
                fi
                system_reinstall_read_ssh_key || return 1
                break
                ;;
            *)
                echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"
                ;;
        esac
    done

    system_reinstall_read_ssh_port || return 1
    if [[ "$SYSTEM_REINSTALL_AUTH_MODE" == "password" ]]; then
        printf '%b%s%b%s\n' "$YELLOW" "$(localized_text "确认使用密码登录，密码：" "Password login confirmed, password: " "Подтверждён вход по паролю, пароль: ")" "$PLAIN" "${SYSTEM_REINSTALL_ACCESS_ARGS[1]}"
    else
        echo -e "$(localized_text "${GREEN}确认使用 SSH 公钥登录。${PLAIN}" "${GREEN}SSH public-key login confirmed.${PLAIN}" "${GREEN}Подтверждён вход по открытому ключу SSH.${PLAIN}")"
    fi
    echo -e "$(localized_text "${GREEN}SSH 登录端口：${SYSTEM_REINSTALL_SSH_PORT}${PLAIN}" "${GREEN}SSH login port: ${SYSTEM_REINSTALL_SSH_PORT}${PLAIN}" "${GREEN}Порт входа SSH: ${SYSTEM_REINSTALL_SSH_PORT}${PLAIN}")"
}

system_reinstall_fetch_upstream() {
    local script_dir temp_script

    script_dir=$(dirname "$SYSTEM_REINSTALL_SCRIPT")
    mkdir -p "$script_dir" || return 1
    temp_script=$(mktemp "${script_dir}/.reinstall.sh.XXXXXX") || return 1

    if command -v curl >/dev/null 2>&1; then
        curl -fL --connect-timeout 10 --retry 3 --retry-delay 1 -o "$temp_script" "$SYSTEM_REINSTALL_UPSTREAM_URL" || {
            rm -f "$temp_script"
            return 1
        }
    elif command -v wget >/dev/null 2>&1; then
        wget -q -O "$temp_script" "$SYSTEM_REINSTALL_UPSTREAM_URL" || {
            rm -f "$temp_script"
            return 1
        }
    else
        echo -e "$(localized_text "${RED}❌ 缺少 curl 或 wget，无法下载重装脚本。${PLAIN}" "${RED}❌ curl or wget is required to download the reinstallation script.${PLAIN}" "${RED}❌ Для загрузки сценария переустановки требуется curl или wget.${PLAIN}")"
        rm -f "$temp_script"
        return 1
    fi

    if [[ ! -s "$temp_script" ]] || ! bash -n "$temp_script"; then
        echo -e "$(localized_text "${RED}❌ 上游重装脚本下载或语法校验失败，未执行。${PLAIN}" "${RED}❌ The upstream reinstallation script download or syntax check failed; it was not run.${PLAIN}" "${RED}❌ Загрузка или проверка синтаксиса сценария переустановки не удалась; запуск отменён.${PLAIN}")"
        rm -f "$temp_script"
        return 1
    fi

    chmod 700 "$temp_script" 2>/dev/null || true
    mv -f "$temp_script" "$SYSTEM_REINSTALL_SCRIPT" || {
        rm -f "$temp_script"
        return 1
    }
}

system_reinstall_cancel_pending() {
    [[ -x "$SYSTEM_REINSTALL_SCRIPT" ]] || {
        echo -e "$(localized_text "${YELLOW}未找到已下载的重装脚本，无法取消。${PLAIN}" "${YELLOW}No downloaded reinstallation script was found to cancel.${PLAIN}" "${YELLOW}Загруженный сценарий переустановки не найден; отмена невозможна.${PLAIN}")"
        return 1
    }

    confirm_risk_action \
        "$(localized_text "取消已安排的系统重装" "Cancel scheduled system reinstallation" "Отменить запланированную переустановку системы")" \
        "$(localized_text "删除上游脚本写入的临时引导项" "Remove the temporary boot entry written by the upstream script" "Удалить временную загрузочную запись, созданную исходным сценарием")" \
        "$(localized_text "如取消失败，请使用云厂商控制台或救援模式恢复" "If cancellation fails, recover through the cloud console or rescue mode" "Если отмена не удалась, используйте облачную консоль или режим восстановления")" \
        "$(localized_text "仅在尚未重启进入安装环境时使用" "Use only before rebooting into the installer" "Используйте только до перезагрузки в установщик")" || return

    bash "$SYSTEM_REINSTALL_SCRIPT" reset
}

func_system_reinstall() {
    local reinstall_choice windows7_iso result

    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        print_breadcrumb "$(localized_text "系统重装" "System reinstallation" "Переустановка системы")"
        echo -e "$(localized_text "${BOLD}⚠️ 系统重装${PLAIN}" "${BOLD}⚠️ System reinstallation${PLAIN}" "${BOLD}⚠️ Переустановка системы${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${RED}重装会在重启后清空主硬盘数据，可能导致 SSH 失联。请先备份并确认云厂商控制台或救援模式可用。${PLAIN}" "${RED}Reinstallation erases the main disk after reboot and may disconnect SSH. Back up data and confirm cloud-console or rescue access first.${PLAIN}" "${RED}После перезагрузки переустановка очистит основной диск и может отключить SSH. Сначала создайте резервную копию и проверьте доступ к облачной консоли или режиму восстановления.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}后端：bin456789/reinstall；参考：leitbogioro/Tools。选择系统后设置登录方式和 SSH 端口。${PLAIN}" "${YELLOW}Backend: bin456789/reinstall; reference: leitbogioro/Tools. After selecting a system, set the login method and SSH port.${PLAIN}" "${YELLOW}Основа: bin456789/reinstall; справочный проект: leitbogioro/Tools. После выбора системы задайте способ входа и порт SSH.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "  1. Debian 13                 2. Debian 12"
        echo -e "  3. Debian 11                 4. Debian 10"
        echo -e "------------------------------------------------"
        echo -e " 11. Ubuntu 26.04             12. Ubuntu 24.04"
        echo -e " 13. Ubuntu 22.04             14. Ubuntu 20.04"
        echo -e "------------------------------------------------"
        echo -e " 21. Rocky Linux 10           22. Rocky Linux 9"
        echo -e " 23. AlmaLinux 10             24. AlmaLinux 9"
        echo -e " 25. Oracle Linux 10          26. Oracle Linux 9"
        echo -e " 27. Fedora Linux 44          28. Fedora Linux 43"
        echo -e " 29. CentOS Stream 10         30. CentOS Stream 9"
        echo -e "------------------------------------------------"
        echo -e " 31. Alpine Linux 3.24        32. Arch Linux"
        echo -e " 33. Kali Linux               34. openEuler 24.03"
        echo -e " 35. openSUSE Tumbleweed      36. fnOS 1"
        echo -e "------------------------------------------------"
        echo -e " 41. Windows 11               42. Windows 10"
        echo -e "$(localized_text " 43. Windows 7（需自备 ISO） 44. Windows Server 2025" " 43. Windows 7 (custom ISO)  44. Windows Server 2025" " 43. Windows 7 (свой ISO)    44. Windows Server 2025")"
        echo -e " 45. Windows Server 2022      46. Windows Server 2019"
        echo -e " 47. Windows 11 ARM"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text " ${YELLOW}50. 取消已安排的重装${PLAIN}" " ${YELLOW}50. Cancel scheduled reinstallation${PLAIN}" " ${YELLOW}50. Отменить запланированную переустановку${PLAIN}")"
        echo -e "${RED}  0. $(localized_text "返回上一级菜单" "Back to the previous menu" "Назад в предыдущее меню")${PLAIN}"
        echo -e "${CYAN}================================================${PLAIN}"

        read_trimmed reinstall_choice "$(localized_text "请选择要重装的系统: " "Select a system to reinstall: " "Выберите систему для переустановки: ")"
        case "$reinstall_choice" in
            0|q|Q) return ;;
            50|cancel)
                system_reinstall_cancel_pending
                pause_return
                continue
                ;;
            43)
                read_trimmed windows7_iso "$(localized_text "Windows 7 ISO 地址（HTTP(S) 或磁力链接，留空取消）: " "Windows 7 ISO URL (HTTP(S) or magnet link; leave blank to cancel): " "URL ISO Windows 7 (HTTP(S) или magnet; пусто — отмена): ")"
                [[ -n "$windows7_iso" ]] || continue
                if ! system_reinstall_set_windows7_target "$windows7_iso"; then
                    echo -e "$(localized_text "${RED}❌ ISO 地址无效。${PLAIN}" "${RED}❌ Invalid ISO URL.${PLAIN}" "${RED}❌ Недопустимый URL ISO.${PLAIN}")"
                    pause_return
                    continue
                fi
                ;;
            47)
                case "$(uname -m)" in
                    aarch64|arm64) ;;
                    *)
                        echo -e "$(localized_text "${RED}❌ Windows 11 ARM 仅适用于 ARM64 服务器。${PLAIN}" "${RED}❌ Windows 11 ARM is available only on ARM64 servers.${PLAIN}" "${RED}❌ Windows 11 ARM доступна только на серверах ARM64.${PLAIN}")"
                        pause_return
                        continue
                        ;;
                esac
                system_reinstall_set_target "$reinstall_choice"
                ;;
            *)
                if ! system_reinstall_set_target "$reinstall_choice"; then
                    echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"
                    sleep 1
                    continue
                fi
                ;;
        esac

        if ! system_reinstall_collect_access_options; then
            continue
        fi

        confirm_risk_action \
            "$(localized_text "重装为 ${SYSTEM_REINSTALL_LABEL}" "Reinstall as ${SYSTEM_REINSTALL_LABEL}" "Переустановить как ${SYSTEM_REINSTALL_LABEL}")" \
            "$(localized_text "下载并执行第三方上游脚本，写入一次性安装引导项；重启后会清空主硬盘及全部分区数据" "Download and run a third-party upstream script that writes a one-time installer boot entry; rebooting will erase the main disk and all its partitions" "Загрузить и запустить сторонний исходный сценарий, который создаст одноразовую загрузочную запись; после перезагрузки основной диск и все его разделы будут очищены")" \
            "$(localized_text "重启前可用本菜单 [50] 取消已安排的重装；重启后只能用快照、云控制台或救援模式恢复" "Before rebooting, use [50] in this menu to cancel the scheduled reinstallation; after rebooting, recovery requires a snapshot, cloud console, or rescue mode" "До перезагрузки отмените запланированную переустановку через [50]; после перезагрузки восстановление возможно только из снимка, через облачную консоль или режим восстановления")" \
            "$(localized_text "确认已完成备份，且能使用云厂商控制台或救援模式" "Confirm that backups are complete and cloud-console or rescue access is available" "Подтвердите наличие резервной копии и доступа к облачной консоли или режиму восстановления")" || continue

        if ! system_reinstall_fetch_upstream; then
            echo -e "$(localized_text "${RED}❌ 无法准备上游重装脚本，未写入引导项。${PLAIN}" "${RED}❌ Unable to prepare the upstream reinstallation script; no boot entry was written.${PLAIN}" "${RED}❌ Не удалось подготовить исходный сценарий; загрузочная запись не создана.${PLAIN}")"
            pause_return
            continue
        fi

        bash "$SYSTEM_REINSTALL_SCRIPT" "${SYSTEM_REINSTALL_TARGET[@]}" "${SYSTEM_REINSTALL_ACCESS_ARGS[@]}" --ssh-port "$SYSTEM_REINSTALL_SSH_PORT"
        result=$?
        if [[ "$result" -eq 0 ]]; then
            echo -e "$(localized_text "${YELLOW}重装已安排，重启后开始执行；如需取消，请在重启前选择 [50]。${PLAIN}" "${YELLOW}Reinstallation is scheduled and starts after reboot. To cancel, select [50] before rebooting.${PLAIN}" "${YELLOW}Переустановка запланирована и начнётся после перезагрузки. Для отмены выберите [50] до перезагрузки.${PLAIN}")"
        else
            echo -e "$(localized_text "${RED}❌ 上游重装脚本退出失败，未自动重启。请检查上方输出。${PLAIN}" "${RED}❌ The upstream reinstallation script failed and did not reboot automatically. Check the output above.${PLAIN}" "${RED}❌ Исходный сценарий переустановки завершился с ошибкой и не перезагрузил сервер. Проверьте вывод выше.${PLAIN}")"
        fi
        pause_return
    done
}

# ---------------------------------------------------------
# Module: firewall.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Firewall rule management workflows.

PORT_CONNLIMIT_NFT_TABLE="${PORT_CONNLIMIT_NFT_TABLE:-vps_optimize_connlimit}"
PORT_CONNLIMIT_NFT_CONFIG="${PORT_CONNLIMIT_NFT_CONFIG:-/etc/vps-optimize/port-connlimit.nft}"
PORT_CONNLIMIT_NFT_SERVICE="${PORT_CONNLIMIT_NFT_SERVICE:-vps-optimize-connlimit.service}"
PORT_CONNLIMIT_NFT_UNIT="${PORT_CONNLIMIT_NFT_UNIT:-/etc/systemd/system/${PORT_CONNLIMIT_NFT_SERVICE}}"

port_connlimit_comment() {
    local port="$1"
    printf 'VPSO_CONN_LIMIT_PORT_%s' "$port"
}

is_valid_connlimit_value() {
    local value="$1"
    [[ "$value" =~ ^[0-9]+$ ]] || return 1
    value="${value#"${value%%[!0]*}"}"
    [[ -n "$value" && ${#value} -le 10 ]] || return 1
    (( 10#$value <= 4294967295 ))
}

ensure_connlimit_tool() {
    local cmd="$1"
    local family_label="$2"

    if command -v "$cmd" >/dev/null 2>&1; then
        return 0
    fi

    echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 ${cmd}，正在尝试安装 iptables 兼容工具...${PLAIN}" "${YELLOW}⚠️ ${cmd} not detected, trying to install iptables compatible tool...${PLAIN}" "${YELLOW}⚠️ ${cmd} не обнаружен, пытаюсь установить iptables-совместимый инструмент...${PLAIN}")"
    install_pkg iptables || true

    if command -v "$cmd" >/dev/null 2>&1; then
        return 0
    fi

    echo -e "$(localized_text "${RED}❌ 未检测到 ${cmd}，无法写入 ${family_label} connlimit 规则。${PLAIN}" "${RED}❌ ${cmd} is not detected and the ${family_label} connlimit rule cannot be written.${PLAIN}" "${RED}❌ ${cmd} не обнаружен, и правило connlimit ${family_label} не может быть записано.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}请先安装 iptables/ip6tables 兼容工具，再重新进入本菜单。${PLAIN}" "${YELLOW}Please install the iptables/ip6tables compatible tool first, and then re-enter this menu.${PLAIN}" "${YELLOW}Сначала установите инструмент, совместимый с iptables/ip6tables, а затем повторно войдите в это меню.${PLAIN}")"
    return 1
}

try_load_connlimit_module() {
    if command -v modprobe >/dev/null 2>&1; then
        modprobe xt_connlimit >/dev/null 2>&1 || true
    fi
}

port_connlimit_kernel_release() {
    if [[ -n "${PORT_CONNLIMIT_KERNEL_RELEASE:-}" ]]; then
        printf '%s\n' "$PORT_CONNLIMIT_KERNEL_RELEASE"
    else
        uname -r 2>/dev/null
    fi
}

port_connlimit_kernel_supports_ct_count() {
    local release major minor patch
    release=$(port_connlimit_kernel_release)
    if [[ ! "$release" =~ ^([0-9]+)\.([0-9]+)(\.([0-9]+))? ]]; then
        return 1
    fi
    major=$((10#${BASH_REMATCH[1]}))
    minor=$((10#${BASH_REMATCH[2]}))
    patch=$((10#${BASH_REMATCH[4]:-0}))

    (( major > 4 )) && return 0
    (( major == 4 && minor > 19 )) && return 0
    (( major == 4 && minor == 19 && patch >= 10 ))
}

port_connlimit_nft_is_managed() {
    command -v nft >/dev/null 2>&1 || return 1
    [[ -f "$PORT_CONNLIMIT_NFT_CONFIG" ]] && return 0
    nft list table inet "$PORT_CONNLIMIT_NFT_TABLE" >/dev/null 2>&1
}

port_connlimit_nft_supported() {
    local probe_table="vpso_connlimit_probe_$$"

    command -v nft >/dev/null 2>&1 || return 1
    port_connlimit_kernel_supports_ct_count || return 1
    if command -v modprobe >/dev/null 2>&1; then
        modprobe nf_tables >/dev/null 2>&1 || true
        modprobe nf_conntrack >/dev/null 2>&1 || true
    fi

    nft -c -f - >/dev/null 2>&1 <<EOF
add table inet ${probe_table}
add set inet ${probe_table} v4_sources { type ipv4_addr; flags dynamic; }
add set inet ${probe_table} v6_sources { type ipv6_addr; flags dynamic; }
add chain inet ${probe_table} input { type filter hook input priority -1; policy accept; }
add rule inet ${probe_table} input tcp dport 1 ct state new add @v4_sources { ip saddr ct count over 1 } reject with tcp reset
add rule inet ${probe_table} input tcp dport 1 ct state new add @v6_sources { ip6 saddr ct count over 1 } reject with tcp reset
delete table inet ${probe_table}
EOF
}

ensure_nft_connlimit_support() {
    local release
    release=$(port_connlimit_kernel_release)

    if ! command -v nft >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}未检测到 nft，正在尝试安装 nftables...${PLAIN}" "${YELLOW}nft not found; attempting to install nftables...${PLAIN}" "${YELLOW}nft не найден; выполняется попытка установить nftables...${PLAIN}")"
        install_pkg nftables || true
    fi
    if port_connlimit_nft_supported; then
        echo -e "$(localized_text "${GREEN}已检测到 nftables ct count 支持（内核 ${release}），优先使用原生 nftables。${PLAIN}" "${GREEN}nftables ct count is supported (kernel ${release}); using native nftables.${PLAIN}" "${GREEN}Обнаружена поддержка nftables ct count (ядро ${release}); используется нативный nftables.${PLAIN}")"
        return 0
    fi

    echo -e "$(localized_text "${YELLOW}当前 nftables/内核不支持可用的 ct count，回退到 iptables/ip6tables connlimit。内核：${release:-unknown}。${PLAIN}" "${YELLOW}Usable nftables ct count support is unavailable; falling back to iptables/ip6tables connlimit. Kernel: ${release:-unknown}.${PLAIN}" "${YELLOW}Поддержка nftables ct count недоступна; выполняется переход на iptables/ip6tables connlimit. Ядро: ${release:-unknown}.${PLAIN}")"
    return 1
}

port_connlimit_nft_rule_entries() {
    command -v nft >/dev/null 2>&1 || return 0
    nft -nn list table inet "$PORT_CONNLIMIT_NFT_TABLE" 2>/dev/null | awk '
        /comment "VPSO_CONN_LIMIT_PORT_[0-9]+"/ {
            family = ""
            port = ""
            limit = ""
            for (i = 1; i <= NF; i++) {
                if ($i == "dport" && i < NF) port = $(i + 1)
                if ($i == "over" && i < NF) limit = $(i + 1)
                if ($i == "ip" && $(i + 1) == "saddr") family = "4"
                if ($i == "ip6" && $(i + 1) == "saddr") family = "6"
            }
            if (family != "" && port ~ /^[0-9]+$/ && limit ~ /^[0-9]+$/) {
                print family "|" port "|" limit
            }
        }
    ' | sort -t '|' -k1,1n -k2,2n -k3,3n -u
}

port_connlimit_legacy_rule_entries_for_family() {
    local cmd="$1"
    local family="$2"

    command -v "$cmd" >/dev/null 2>&1 || return 0
    "$cmd" -S INPUT 2>/dev/null | awk -v family="$family" '
        $1 == "-A" && $2 == "INPUT" {
            port = ""
            limit = ""
            comment = ""
            for (i = 3; i <= NF; i++) {
                if ($i == "--dport" && i < NF) port = $(i + 1)
                if ($i == "--connlimit-above" && i < NF) limit = $(i + 1)
                if ($i == "--comment" && i < NF) {
                    comment = $(i + 1)
                    gsub(/^["\047]|["\047]$/, "", comment)
                }
            }
            if (port ~ /^[0-9]+$/ && limit ~ /^[0-9]+$/ && comment == "VPSO_CONN_LIMIT_PORT_" port) {
                print family "|" port "|" limit
            }
        }
    '
}

port_connlimit_legacy_rule_entries() {
    {
        port_connlimit_legacy_rule_entries_for_family iptables 4
        port_connlimit_legacy_rule_entries_for_family ip6tables 6
    }
}

port_connlimit_merge_rule_entries() {
    awk -F '|' '
        $1 ~ /^[46]$/ && $2 ~ /^[0-9]+$/ && $3 ~ /^[0-9]+$/ {
            key = $1 FS $2
            if (!(key in minimum) || $3 + 0 < minimum[key] + 0) minimum[key] = $3
        }
        END {
            for (key in minimum) print key FS minimum[key]
        }
    ' | sort -t '|' -k1,1n -k2,2n
}

port_connlimit_update_rule_entries() {
    local entries="$1"
    local action="$2"
    local port="$3"
    local limit="$4"
    shift 4
    local families=("$@")
    local family line_family line_port line_limit selected

    while IFS='|' read -r line_family line_port line_limit; do
        [[ -n "$line_family" && -n "$line_port" && -n "$line_limit" ]] || continue
        selected=0
        for family in "${families[@]}"; do
            [[ "$line_family" == "$family" ]] && selected=1
        done
        if [[ "$action" == "add" && "$selected" -eq 1 && "$line_port" == "$port" ]]; then
            continue
        fi
        if [[ "$action" == "delete" && "$selected" -eq 1 && "$line_port" == "$port" && "$line_limit" == "$limit" ]]; then
            continue
        fi
        printf '%s|%s|%s\n' "$line_family" "$line_port" "$line_limit"
    done <<<"$entries"

    if [[ "$action" == "add" ]]; then
        for family in "${families[@]}"; do
            printf '%s|%s|%s\n' "$family" "$port" "$limit"
        done
    fi
}

render_port_connlimit_nft_config() {
    local entries="$1"
    local family port limit set_name

    printf 'flush table inet %s\n' "$PORT_CONNLIMIT_NFT_TABLE"
    printf 'table inet %s {\n' "$PORT_CONNLIMIT_NFT_TABLE"
    while IFS='|' read -r family port limit; do
        [[ -n "$family" && -n "$port" && -n "$limit" ]] || continue
        set_name="v${family}_p${port}"
        if [[ "$family" == "4" ]]; then
            printf '    set %s { type ipv4_addr; size 65535; flags dynamic; }\n' "$set_name"
        else
            printf '    set %s { type ipv6_addr; size 65535; flags dynamic; }\n' "$set_name"
        fi
    done <<<"$entries"

    if [[ -n "$entries" ]]; then
        printf '    chain input {\n'
        printf '        type filter hook input priority -1; policy accept;\n'
        while IFS='|' read -r family port limit; do
            [[ -n "$family" && -n "$port" && -n "$limit" ]] || continue
            set_name="v${family}_p${port}"
            if [[ "$family" == "4" ]]; then
                printf '        tcp dport %s ct state new add @%s { ip saddr ct count over %s } reject with tcp reset comment "%s"\n' "$port" "$set_name" "$limit" "$(port_connlimit_comment "$port")"
            else
                printf '        tcp dport %s ct state new add @%s { ip6 saddr ct count over %s } reject with tcp reset comment "%s"\n' "$port" "$set_name" "$limit" "$(port_connlimit_comment "$port")"
            fi
        done <<<"$entries"
        printf '    }\n'
    fi
    printf '}\n'
}

port_connlimit_nft_ensure_table() {
    nft list table inet "$PORT_CONNLIMIT_NFT_TABLE" >/dev/null 2>&1 && return 0
    nft add table inet "$PORT_CONNLIMIT_NFT_TABLE" >/dev/null 2>&1 || \
        nft list table inet "$PORT_CONNLIMIT_NFT_TABLE" >/dev/null 2>&1
}

enable_nft_port_connlimit_persistence() {
    local nft_path unit_dir unit_tmp
    nft_path=$(port_connlimit_command_path nft 2>/dev/null) || return 1
    command -v systemctl >/dev/null 2>&1 || return 1

    unit_dir=$(dirname "$PORT_CONNLIMIT_NFT_UNIT")
    mkdir -p "$unit_dir" || return 1
    unit_tmp=$(mktemp "${unit_dir}/.${PORT_CONNLIMIT_NFT_SERVICE}.XXXXXX") || return 1
    if ! render_nft_port_connlimit_service "$nft_path" >"$unit_tmp"; then
        rm -f "$unit_tmp"
        return 1
    fi
    chmod 0644 "$unit_tmp" 2>/dev/null || true
    if ! mv -f "$unit_tmp" "$PORT_CONNLIMIT_NFT_UNIT"; then
        rm -f "$unit_tmp"
        return 1
    fi
    systemctl daemon-reload >/dev/null 2>&1 || return 1
    systemctl enable "$PORT_CONNLIMIT_NFT_SERVICE" >/dev/null 2>&1
}

render_nft_port_connlimit_service() {
    local nft_path="$1"
    cat <<EOF
[Unit]
Description=VPS-Optimize port connection limits
After=nftables.service firewalld.service ufw.service

[Service]
Type=oneshot
ExecStartPre=-${nft_path} add table inet ${PORT_CONNLIMIT_NFT_TABLE}
ExecStart=${nft_path} -f ${PORT_CONNLIMIT_NFT_CONFIG}
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF
}

write_port_connlimit_nft_config() {
    local entries="$1"
    local apply_runtime="${2:-0}"
    local config_dir tmp_file output

    config_dir=$(dirname "$PORT_CONNLIMIT_NFT_CONFIG")
    mkdir -p "$config_dir" || return 1
    port_connlimit_nft_ensure_table || return 1
    tmp_file=$(mktemp "${config_dir}/.port-connlimit.nft.XXXXXX") || return 1
    render_port_connlimit_nft_config "$entries" >"$tmp_file"

    if ! output=$(nft -c -f "$tmp_file" 2>&1); then
        rm -f "$tmp_file"
        echo -e "$(localized_text "${RED}nftables 配置校验失败：${output}${PLAIN}" "${RED}nftables configuration validation failed: ${output}${PLAIN}" "${RED}Ошибка проверки конфигурации nftables: ${output}${PLAIN}")"
        return 1
    fi
    if [[ "$apply_runtime" -eq 1 ]] && ! output=$(nft -f "$tmp_file" 2>&1); then
        rm -f "$tmp_file"
        echo -e "$(localized_text "${RED}nftables 原子更新失败：${output}${PLAIN}" "${RED}Atomic nftables update failed: ${output}${PLAIN}" "${RED}Не удалось атомарно обновить nftables: ${output}${PLAIN}")"
        return 1
    fi
    chmod 0600 "$tmp_file" 2>/dev/null || true
    if ! mv -f "$tmp_file" "$PORT_CONNLIMIT_NFT_CONFIG"; then
        rm -f "$tmp_file"
        return 1
    fi
    if ! enable_nft_port_connlimit_persistence; then
        echo -e "$(localized_text "${YELLOW}nftables 运行时规则已更新，但未能启用 ${PORT_CONNLIMIT_NFT_SERVICE}，重启恢复状态需手动确认。${PLAIN}" "${YELLOW}The nftables runtime rules were updated, but ${PORT_CONNLIMIT_NFT_SERVICE} could not be enabled; boot restoration must be checked manually.${PLAIN}" "${YELLOW}Правила nftables обновлены, но не удалось включить ${PORT_CONNLIMIT_NFT_SERVICE}; восстановление после загрузки необходимо проверить вручную.${PLAIN}")"
        return 1
    fi
    return 0
}

remove_saved_port_connlimit_legacy_rules() {
    local file dir tmp_file rc=0
    local files=(
        /etc/iptables/rules.v4
        /etc/iptables/rules.v6
        /etc/sysconfig/iptables
        /etc/sysconfig/ip6tables
    )

    for file in "${files[@]}"; do
        [[ -f "$file" ]] || continue
        grep -Fq 'VPSO_CONN_LIMIT_PORT_' "$file" 2>/dev/null || continue
        dir=$(dirname "$file")
        tmp_file=$(mktemp "${dir}/.vpso-connlimit-clean.XXXXXX") || {
            rc=1
            continue
        }
        if awk 'index($0, "VPSO_CONN_LIMIT_PORT_") == 0 { print }' "$file" >"$tmp_file" && \
            chmod --reference="$file" "$tmp_file" 2>/dev/null && \
            chown --reference="$file" "$tmp_file" 2>/dev/null && \
            mv -f "$tmp_file" "$file"; then
            :
        else
            rm -f "$tmp_file"
            rc=1
        fi
    done
    return "$rc"
}

delete_port_connlimit_legacy_entry() {
    local family="$1"
    local port="$2"
    local limit="$3"
    local cmd mask comment

    if [[ "$family" == "4" ]]; then
        cmd=iptables
        mask=32
    else
        cmd=ip6tables
        mask=128
    fi
    command -v "$cmd" >/dev/null 2>&1 || return 1
    comment=$(port_connlimit_comment "$port")
    "$cmd" -D INPUT \
        -p tcp --dport "$port" --syn \
        -m connlimit --connlimit-above "$limit" --connlimit-mask "$mask" --connlimit-saddr \
        -m comment --comment "$comment" \
        -j REJECT --reject-with tcp-reset >/dev/null 2>&1
}

cleanup_port_connlimit_legacy_rules() {
    local legacy_entries="$1"
    local family port limit remaining removed=0 rc=0

    while IFS='|' read -r family port limit; do
        [[ -n "$family" && -n "$port" && -n "$limit" ]] || continue
        if delete_port_connlimit_legacy_entry "$family" "$port" "$limit"; then
            removed=$((removed + 1))
        else
            rc=1
        fi
    done <<<"$legacy_entries"
    remove_saved_port_connlimit_legacy_rules || rc=1
    remaining=$(( $(port_connlimit_runtime_rule_count iptables) + $(port_connlimit_runtime_rule_count ip6tables) ))
    (( remaining == 0 )) || rc=1

    if (( removed > 0 )); then
        echo -e "$(localized_text "${GREEN}已迁移并清理 ${removed} 条旧 iptables/ip6tables connlimit 规则。${PLAIN}" "${GREEN}Migrated and removed ${removed} legacy iptables/ip6tables connlimit rule(s).${PLAIN}" "${GREEN}Перенесено и удалено старых правил iptables/ip6tables connlimit: ${removed}.${PLAIN}")"
    fi
    if (( rc != 0 )); then
        echo -e "$(localized_text "${YELLOW}部分旧 connlimit 规则或保存快照清理失败；剩余运行时规则 ${remaining} 条，可能与 nftables 限制叠加。${PLAIN}" "${YELLOW}Some legacy connlimit rules or saved snapshots could not be removed; ${remaining} runtime rule(s) remain and may overlap the nftables limits.${PLAIN}" "${YELLOW}Не удалось удалить часть старых правил connlimit или сохранённых снимков; осталось правил во время выполнения: ${remaining}. Они могут применяться вместе с ограничениями nftables.${PLAIN}")"
    fi
    return "$rc"
}

run_nft_port_connlimit_action() {
    local action="$1"
    local port="$2"
    local limit="$3"
    local apply_ipv6="$4"
    local nft_entries legacy_entries merged_entries current_entries updated_entries match_count
    local families=(4)

    [[ "$apply_ipv6" -eq 1 ]] && families+=(6)
    nft_entries=$(port_connlimit_nft_rule_entries)
    legacy_entries=$(port_connlimit_legacy_rule_entries)
    merged_entries=$(printf '%s\n%s\n' "$nft_entries" "$legacy_entries" | port_connlimit_merge_rule_entries)
    current_entries=$(printf '%s\n' "$nft_entries" | port_connlimit_merge_rule_entries)

    if [[ "$action" == "delete" ]]; then
        match_count=$(printf '%s\n' "$merged_entries" | awk -F '|' -v port="$port" -v limit="$limit" -v ipv6="$apply_ipv6" '
            $2 == port && $3 == limit && ($1 == 4 || (ipv6 == 1 && $1 == 6)) { count++ }
            END { print count + 0 }
        ')
        if (( match_count == 0 )); then
            echo -e "$(localized_text "${YELLOW}未找到 nftables 或旧 iptables 匹配规则：端口 ${port}，连接数 ${limit}。${PLAIN}" "${YELLOW}No matching nftables or legacy iptables rule found for port ${port}, connection limit ${limit}.${PLAIN}" "${YELLOW}Не найдено подходящее правило nftables или старое правило iptables для порта ${port} с лимитом ${limit}.${PLAIN}")"
            return 1
        fi
    fi

    updated_entries=$(port_connlimit_update_rule_entries "$merged_entries" "$action" "$port" "$limit" "${families[@]}" | port_connlimit_merge_rule_entries)
    if [[ "$action" == "add" && -z "$legacy_entries" && "$updated_entries" == "$current_entries" ]]; then
        if write_port_connlimit_nft_config "$current_entries" 0; then
            echo -e "$(localized_text "${BLUE}nftables 已存在相同限制：端口 ${port}，每来源 IP 最大并发 ${limit}。${PLAIN}" "${BLUE}The same nftables limit already exists for port ${port}: ${limit} concurrent connections per source IP.${PLAIN}" "${BLUE}Такое ограничение nftables уже существует для порта ${port}: ${limit} подключений на исходный IP-адрес.${PLAIN}")"
            return 0
        fi
        return 1
    fi
    if ! write_port_connlimit_nft_config "$updated_entries" 1; then
        return 1
    fi

    cleanup_port_connlimit_legacy_rules "$legacy_entries" || return 1
    if [[ "$action" == "add" ]]; then
        echo -e "$(localized_text "${GREEN}nftables 规则已应用：端口 ${port}，每来源 IP 最大并发 ${limit}。${PLAIN}" "${GREEN}nftables rule applied: port ${port}, maximum ${limit} concurrent connections per source IP.${PLAIN}" "${GREEN}Правило nftables применено: порт ${port}, не более ${limit} одновременных подключений на исходный IP-адрес.${PLAIN}")"
    else
        echo -e "$(localized_text "${GREEN}nftables 规则已删除：端口 ${port}，连接数 ${limit}。${PLAIN}" "${GREEN}nftables rule removed: port ${port}, connection limit ${limit}.${PLAIN}" "${GREEN}Правило nftables удалено: порт ${port}, лимит подключений ${limit}.${PLAIN}")"
    fi
}

port_connlimit_runtime_rule_count() {
    local cmd="$1"
    local count

    if ! command -v "$cmd" >/dev/null 2>&1; then
        printf '0'
        return 0
    fi

    count=$("$cmd" -S INPUT 2>/dev/null | grep -Fc 'VPSO_CONN_LIMIT_PORT_' || true)
    printf '%s' "${count:-0}"
}

port_connlimit_persisted_rule_count() {
    local file="$1"
    local count

    if [[ ! -f "$file" ]]; then
        printf '0'
        return 0
    fi

    count=$(grep -Fc 'VPSO_CONN_LIMIT_PORT_' "$file" 2>/dev/null || true)
    printf '%s' "${count:-0}"
}

port_connlimit_command_path() {
    local cmd="$1"
    local candidate

    if command -v "$cmd" >/dev/null 2>&1; then
        command -v "$cmd"
        return 0
    fi

    for candidate in "/usr/sbin/${cmd}" "/sbin/${cmd}" "/usr/bin/${cmd}" "/bin/${cmd}"; do
        if [[ -x "$candidate" ]]; then
            printf '%s\n' "$candidate"
            return 0
        fi
    done

    return 1
}

port_connlimit_systemd_unit_exists() {
    local unit="$1"

    command -v systemctl >/dev/null 2>&1 || return 1
    systemctl list-unit-files "${unit}.service" --no-legend 2>/dev/null | grep -q . && return 0
    systemctl list-units "${unit}.service" --all --no-legend 2>/dev/null | grep -q . && return 0
    return 1
}

port_connlimit_rhel_ipv4_persistence_available() {
    is_redhat || return 1
    port_connlimit_command_path iptables-save >/dev/null 2>&1 || return 1

    [[ -f /etc/sysconfig/iptables ]] && return 0
    port_connlimit_systemd_unit_exists iptables
}

port_connlimit_rhel_ipv6_persistence_available() {
    is_redhat || return 1
    port_connlimit_command_path ip6tables-save >/dev/null 2>&1 || return 1

    [[ -f /etc/sysconfig/ip6tables ]] && return 0
    port_connlimit_systemd_unit_exists ip6tables
}

port_connlimit_persistence_backend() {
    if port_connlimit_command_path netfilter-persistent >/dev/null 2>&1; then
        printf '%s\n' "netfilter-persistent"
        return 0
    fi

    if port_connlimit_rhel_ipv4_persistence_available; then
        printf '%s\n' "rhel-iptables-services"
        return 0
    fi

    printf '%s\n' "none"
}

port_connlimit_saved_file_for_family() {
    local family="$1"
    local backend="${2:-$(port_connlimit_persistence_backend)}"

    case "$backend:$family" in
        netfilter-persistent:4) printf '%s\n' "/etc/iptables/rules.v4" ;;
        netfilter-persistent:6) printf '%s\n' "/etc/iptables/rules.v6" ;;
        rhel-iptables-services:4) printf '%s\n' "/etc/sysconfig/iptables" ;;
        rhel-iptables-services:6) printf '%s\n' "/etc/sysconfig/ip6tables" ;;
        *) return 1 ;;
    esac
}

port_connlimit_saved_rule_count_for_family() {
    local family="$1"
    local backend="${2:-$(port_connlimit_persistence_backend)}"
    local file

    file=$(port_connlimit_saved_file_for_family "$family" "$backend" 2>/dev/null) || {
        printf '0'
        return 0
    }
    port_connlimit_persisted_rule_count "$file"
}

port_connlimit_runtime_rule_fingerprints_for_family() {
    local family="$1"
    local cmd="$2"

    if ! command -v "$cmd" >/dev/null 2>&1; then
        return 0
    fi

    "$cmd" -S INPUT 2>/dev/null | grep -F 'VPSO_CONN_LIMIT_PORT_' | sed "s/^/${family}:/" || true
}

port_connlimit_saved_rule_fingerprints_for_file() {
    local family="$1"
    local file="$2"

    [[ -f "$file" ]] || return 0
    grep -F 'VPSO_CONN_LIMIT_PORT_' "$file" 2>/dev/null | sed "s/^/${family}:/" || true
}

port_connlimit_runtime_rule_fingerprints() {
    {
        while IFS='|' read -r family port limit; do
            [[ -n "$family" && -n "$port" && -n "$limit" ]] || continue
            printf 'nftables:%s|%s|%s|%s\n' "$family" "$port" "$limit" "$(port_connlimit_comment "$port")"
        done < <(port_connlimit_nft_rule_entries)
        port_connlimit_runtime_rule_fingerprints_for_family "IPv4" iptables
        port_connlimit_runtime_rule_fingerprints_for_family "IPv6" ip6tables
    } | sort -u
}

port_connlimit_nft_saved_rule_fingerprints() {
    [[ -f "$PORT_CONNLIMIT_NFT_CONFIG" ]] || return 0
    awk '
        /comment "VPSO_CONN_LIMIT_PORT_[0-9]+"/ {
            family = ""
            port = ""
            limit = ""
            for (i = 1; i <= NF; i++) {
                if ($i == "dport" && i < NF) port = $(i + 1)
                if ($i == "over" && i < NF) limit = $(i + 1)
                if ($i == "ip" && $(i + 1) == "saddr") family = "4"
                if ($i == "ip6" && $(i + 1) == "saddr") family = "6"
            }
            if (family != "" && port ~ /^[0-9]+$/ && limit ~ /^[0-9]+$/) {
                print "nftables:" family "|" port "|" limit "|VPSO_CONN_LIMIT_PORT_" port
            }
        }
    ' "$PORT_CONNLIMIT_NFT_CONFIG" | sort -u
}

port_connlimit_saved_rule_fingerprints_for_backend() {
    local backend="$1"
    local v4_file v6_file

    v4_file=$(port_connlimit_saved_file_for_family 4 "$backend" 2>/dev/null || true)
    v6_file=$(port_connlimit_saved_file_for_family 6 "$backend" 2>/dev/null || true)
    {
        [[ -n "$v4_file" ]] && port_connlimit_saved_rule_fingerprints_for_file "IPv4" "$v4_file"
        [[ -n "$v6_file" ]] && port_connlimit_saved_rule_fingerprints_for_file "IPv6" "$v6_file"
    } | sort -u
}

port_connlimit_known_saved_rule_fingerprints() {
    {
        port_connlimit_nft_saved_rule_fingerprints
        port_connlimit_saved_rule_fingerprints_for_file "IPv4" /etc/iptables/rules.v4
        port_connlimit_saved_rule_fingerprints_for_file "IPv6" /etc/iptables/rules.v6
        port_connlimit_saved_rule_fingerprints_for_file "IPv4" /etc/sysconfig/iptables
        port_connlimit_saved_rule_fingerprints_for_file "IPv6" /etc/sysconfig/ip6tables
    } | sort -u
}

port_connlimit_fingerprint_count() {
    local data="$1"

    if [[ -z "$data" ]]; then
        printf '0'
    else
        printf '%s\n' "$data" | grep -c .
    fi
}

print_port_connlimit_health_summary() {
    local backend runtime_rules saved_rules known_saved_rules
    local runtime_count saved_count known_saved_count backend_label consistency risk

    if port_connlimit_nft_is_managed; then
        backend="nftables"
    else
        backend=$(port_connlimit_persistence_backend)
    fi
    runtime_rules=$(port_connlimit_runtime_rule_fingerprints)
    if [[ "$backend" == "nftables" ]]; then
        saved_rules=$(port_connlimit_nft_saved_rule_fingerprints)
    else
        saved_rules=$(port_connlimit_saved_rule_fingerprints_for_backend "$backend")
    fi
    known_saved_rules=$(port_connlimit_known_saved_rule_fingerprints)
    runtime_count=$(port_connlimit_fingerprint_count "$runtime_rules")
    saved_count=$(port_connlimit_fingerprint_count "$saved_rules")
    known_saved_count=$(port_connlimit_fingerprint_count "$known_saved_rules")

    case "$backend" in
        nftables) backend_label="${GREEN}nftables (${PORT_CONNLIMIT_NFT_SERVICE})${PLAIN}" ;;
        netfilter-persistent) backend_label="${GREEN}netfilter-persistent${PLAIN}" ;;
        rhel-iptables-services) backend_label="${GREEN}rhel-iptables-services${PLAIN}" ;;
        *) backend_label="$(localized_text "${YELLOW}未检测到可用后端${PLAIN}" "${YELLOW}No available backend detected${PLAIN}" "${YELLOW}Доступная бэкенд не обнаружена${PLAIN}")" ;;
    esac

    if [[ "$backend" == "none" ]]; then
        consistency="$(localized_text "${YELLOW}未检测（无可用持久化后端）${PLAIN}" "${YELLOW}Not detected (no persistence backend available)${PLAIN}" "${YELLOW}Не обнаружен (бэкенд сохраняемости недоступна)${PLAIN}")"
    elif [[ "$runtime_rules" == "$saved_rules" ]]; then
        consistency="$(localized_text "${GREEN}一致${PLAIN}" "${GREEN}Is consistent with${PLAIN}" "${GREEN}соответствует .${PLAIN}")"
    else
        consistency="$(localized_text "${YELLOW}不一致${PLAIN}" "${YELLOW}Is inconsistent with${PLAIN}" "${YELLOW}несовместим с .${PLAIN}")"
    fi

    if [[ "$backend" == "none" && "$runtime_count" -gt 0 ]]; then
        risk="$(localized_text "${YELLOW}存在：运行时规则未接入可用持久化后端，重启后可能丢失或恢复旧快照。${PLAIN}" "${YELLOW}Exists: The runtime rule is not connected to the available persistence backend, and old snapshots may be lost or restored after restarting.${PLAIN}" "${YELLOW}существует: правило времени выполнения не подключено к доступной серверной части хранилища, и старые снимки могут быть потеряны или восстановлены после перезапуска.${PLAIN}")"
    elif [[ "$backend" == "none" && "$known_saved_count" -gt 0 ]]; then
        risk="$(localized_text "${YELLOW}存在：发现保存文件里仍有脚本规则标记，但当前无可用后端，重启恢复行为需手动确认。${PLAIN}" "${YELLOW}Exists: It is found that there are still script rule tags in the saved file, but there is currently no available backend. The restart recovery behavior needs to be confirmed manually.${PLAIN}" "${YELLOW}существует: обнаружено, что в сохраненном файле все еще есть теги правил сценария, но в настоящее время доступной серверной части нет. Поведение перезапуска и восстановления необходимо подтвердить вручную.${PLAIN}")"
    elif [[ "$backend" != "none" && "$runtime_count" -gt 0 && "$saved_count" -eq 0 ]]; then
        risk="$(localized_text "${YELLOW}存在：运行时规则尚未出现在当前保存文件中，重启后可能丢失。${PLAIN}" "${YELLOW}Exists: The runtime rule does not yet appear in the current save file and may be lost after restarting.${PLAIN}" "${YELLOW}существует: правило времени выполнения еще не отображается в текущем файле сохранения и может быть потеряно после перезапуска.${PLAIN}")"
    elif [[ "$backend" != "none" && "$runtime_count" -eq 0 && "$saved_count" -gt 0 ]]; then
        risk="$(localized_text "${YELLOW}存在：运行时没有脚本规则，但保存文件仍有旧标记，重启后可能恢复旧规则。${PLAIN}" "${YELLOW}Exists: There are no script rules when running, but the saved file still has old tags. The old rules may be restored after restarting.${PLAIN}" "${YELLOW}существует: при запуске нет правил сценария, но сохраненный файл все еще имеет старые теги. Старые правила могут быть восстановлены после перезапуска.${PLAIN}")"
    elif [[ "$backend" != "none" && "$runtime_rules" != "$saved_rules" ]]; then
        risk="$(localized_text "${YELLOW}存在：运行时规则与保存文件不同，建议到 [8] -> [5] -> [5] 重新保存/检查。${PLAIN}" "${YELLOW}Exists: The runtime rules are different from the saved files. It is recommended to go to [8] -> [5] -> [5] to resave/check.${PLAIN}" "${YELLOW}существует: правила времени выполнения отличаются от правил сохраненных файлов. Рекомендуется перейти к [8] -> [5] -> [5] для пересохранения/проверки.${PLAIN}")"
    else
        risk="$(localized_text "${GREEN}未发现明显丢失/旧快照风险${PLAIN}" "${GREEN}No obvious risk of loss/old snapshot found${PLAIN}" "${GREEN}Нет очевидного риска потери/старый снимок не найден${PLAIN}")"
    fi

    echo -e "$(localized_text "${CYAN}🔒 connlimit 持久化摘要${PLAIN}" "${CYAN}🔒 connlimit persistence summary${PLAIN}" "${CYAN}🔒 сводка о постоянстве connlimit${PLAIN}")"
    if [[ "$runtime_count" -gt 0 ]]; then
        echo -e "$(localized_text "脚本规则状态       : [ ${GREEN}存在${PLAIN} ]  运行时: ${CYAN}${runtime_count}${PLAIN} 条" "Script rule status: [ ${GREEN}Exists${PLAIN} ] Runtime: ${CYAN}${runtime_count}${PLAIN}" "Статус правила сценария: [ ${GREEN}существует${PLAIN} ] Время выполнения: ${CYAN}${runtime_count}${PLAIN}")"
    else
        echo -e "$(localized_text "脚本规则状态       : [ ${BLUE}未检测到运行时规则${PLAIN} ]" "Script rule status: [${BLUE}Runtime rule${PLAIN} not detected]" "Статус правила сценария: [${BLUE}Правило времени выполнения${PLAIN} не обнаружено]")"
    fi
    echo -e "$(localized_text "可用持久化后端     : [ $backend_label ]" "Available persistence backends: [ $backend_label ]" "Доступные серверные части персистентности: [ $backend_label ]")"
    echo -e "$(localized_text "运行时/保存文件    : [ $consistency ]  保存文件: ${CYAN}${saved_count}${PLAIN} 条" "Runtime/save file: [ $consistency ] Save file: ${CYAN}${saved_count}${PLAIN}" "Файл времени выполнения/сохранения: [ $consistency ] Файл сохранения: ${CYAN}${saved_count}${PLAIN}")"
    echo -e "$(localized_text "重启风险提示       : [ $risk ]" "Restart risk warning: [ $risk ]" "Предупреждение о риске перезапуска: [ $risk ]")"
}

print_port_connlimit_persistence_unavailable() {
    echo -e "$(localized_text "${YELLOW}⚠️ 未检测到本脚本可可靠调用的 connlimit 持久化保存能力。${PLAIN}" "${YELLOW}⚠️ The connlimit persistence capability that this script can call reliably has not been detected.${PLAIN}" "${YELLOW}⚠️ Возможность сохранения connlimit, которую этот сценарий может надежно вызывать, не обнаружена.${PLAIN}")"
    if is_debian; then
        echo -e "$(localized_text "${YELLOW}Debian/Ubuntu 可安装并启用 iptables-persistent / netfilter-persistent 后再保存。${PLAIN}" "${YELLOW}Debian/Ubuntu can install and enable iptables-persistent / netfilter-persistent and then save.${PLAIN}" "${YELLOW}Debian/Ubuntu может установить и включить iptables-persistent/netfilter-persistent, а затем сохранить.${PLAIN}")"
    elif is_redhat; then
        echo -e "$(localized_text "${YELLOW}RHEL/Rocky/Alma/CentOS Stream 仅在检测到已有 iptables-services（iptables.service 或 /etc/sysconfig/iptables）时自动保存。${PLAIN}" "${YELLOW}RHEL/Rocky/Alma/CentOS Stream is only automatically saved if an existing iptables-services (iptables.service or /etc/sysconfig/iptables) is detected.${PLAIN}" "${YELLOW}Поток RHEL/Rocky/Alma/CentOS автоматически сохраняется только в том случае, если обнаружены существующие службы iptables (iptables.service или /etc/sysconfig/iptables).${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}当前发行版未提供本脚本可验证的 iptables 持久化路径，请使用系统自带机制手动保存。${PLAIN}" "${YELLOW}The current release version of does not provide a iptables persistence path that can be verified by this script. Please use the system's own mechanism to save it manually.${PLAIN}" "${YELLOW}Текущая версия не предоставляет путь сохранения iptables, который можно проверить с помощью этого сценария. Пожалуйста, используйте собственный механизм системы, чтобы сохранить его вручную.${PLAIN}")"
    fi
    echo -e "$(localized_text "${YELLOW}当前 connlimit 规则只在本次运行期生效，重启后可能丢失或恢复旧快照。${PLAIN}" "${YELLOW}The current connlimit rule only takes effect during this running period. Old snapshots may be lost or restored after restarting.${PLAIN}" "${YELLOW}Текущее правило connlimit вступает в силу только в течение этого периода работы. Старые снимки могут быть потеряны или восстановлены после перезапуска.${PLAIN}")"
}

print_legacy_port_connlimit_persistence_status() {
    local v4_runtime v6_runtime v4_saved v6_saved backend
    local v4_file deb_v4_saved deb_v6_saved rhel_v4_saved rhel_v6_saved

    backend=$(port_connlimit_persistence_backend)
    v4_runtime=$(port_connlimit_runtime_rule_count iptables)
    v6_runtime=$(port_connlimit_runtime_rule_count ip6tables)
    v4_saved=$(port_connlimit_saved_rule_count_for_family 4 "$backend")
    v6_saved=$(port_connlimit_saved_rule_count_for_family 6 "$backend")
    deb_v4_saved=$(port_connlimit_persisted_rule_count /etc/iptables/rules.v4)
    deb_v6_saved=$(port_connlimit_persisted_rule_count /etc/iptables/rules.v6)
    rhel_v4_saved=$(port_connlimit_persisted_rule_count /etc/sysconfig/iptables)
    rhel_v6_saved=$(port_connlimit_persisted_rule_count /etc/sysconfig/ip6tables)
    v4_file=$(port_connlimit_saved_file_for_family 4 "$backend" 2>/dev/null || true)

    echo -e "$(localized_text "${CYAN}持久化检查：${PLAIN}" "${CYAN}Persistence check:${PLAIN}" "${CYAN}Проверка устойчивости :${PLAIN}")"
    echo "$(localized_text "  运行时规则：IPv4 ${v4_runtime} 条，IPv6 ${v6_runtime} 条。" "Runtime rules: IPv4 ${v4_runtime}, IPv6 ${v6_runtime}." "Правила выполнения: IPv4 ${v4_runtime}, IPv6 ${v6_runtime}.")"
    echo "$(localized_text "  Debian/Ubuntu 保存文件：/etc/iptables/rules.v4 中 ${deb_v4_saved} 条，/etc/iptables/rules.v6 中 ${deb_v6_saved} 条。" "Debian/Ubuntu save files: ${deb_v4_saved} in /etc/iptables/rules.v4, ${deb_v6_saved} in /etc/iptables/rules.v6." "Файлы сохранения Debian/Ubuntu: ${deb_v4_saved} в /etc/iptables/rules.v4, ${deb_v6_saved} в /etc/iptables/rules.v6.")"
    echo "$(localized_text "  RHEL 系列保存文件：/etc/sysconfig/iptables 中 ${rhel_v4_saved} 条，/etc/sysconfig/ip6tables 中 ${rhel_v6_saved} 条。" "RHEL series save files: ${rhel_v4_saved} in /etc/sysconfig/iptables, ${rhel_v6_saved} in /etc/sysconfig/ip6tables." "Файлы сохранения серии RHEL: ${rhel_v4_saved} в /etc/sysconfig/iptables, ${rhel_v6_saved} в /etc/sysconfig/ip6tables.")"

    if [[ "$backend" == "netfilter-persistent" ]]; then
        echo -e "$(localized_text "${GREEN}  已检测到 netfilter-persistent；添加/删除 connlimit 后会自动尝试保存，也可用本菜单 [5] 手动检查/保存。${PLAIN}" "${GREEN}Netfilter-persistent has been detected; after adding/deleting connlimit, it will automatically try to save. You can also use this menu [5] to manually check/save.${PLAIN}" "${GREEN}Обнаружен постоянный сетевой фильтр ; после добавления/удаления connlimit автоматически попытается сохранить. Вы также можете использовать это меню [5] для проверки/сохранения вручную.${PLAIN}")"
    elif command -v dpkg-query >/dev/null 2>&1 && dpkg-query -W -f='${Status}' iptables-persistent 2>/dev/null | grep -q 'install ok installed'; then
        echo -e "$(localized_text "${YELLOW}  已检测到 iptables-persistent 包，但未检测到 netfilter-persistent 命令；请确认 /usr/sbin 是否在 PATH。${PLAIN}" "${YELLOW}The iptables-persistent package has been detected, but the netfilter-persistent command has not been detected; please confirm whether /usr/sbin is in PATH.${PLAIN}" "${YELLOW}Обнаружен постоянный пакет iptables, но команда netfilter-persistent не обнаружена; пожалуйста, подтвердите, находится ли /usr/sbin в PATH.${PLAIN}")"
    elif [[ "$backend" == "rhel-iptables-services" ]]; then
        echo -e "$(localized_text "${GREEN}  已检测到 RHEL 系列已有 iptables-services 持久化路径；添加/删除 connlimit 后会自动写入 ${v4_file:-/etc/sysconfig/iptables}。${PLAIN}" "${GREEN}Has detected that the RHEL series already has the iptables-services persistence path; ${v4_file:-/etc/sysconfig/iptables} will be automatically written after adding/deleting the connlimit.${PLAIN}" "${GREEN}обнаружил, что серия RHEL уже имеет путь сохранения iptables-services; ${v4_file:-/etc/sysconfig/iptables} будет автоматически записан после добавления/удаления connlimit.${PLAIN}")"
        if ! port_connlimit_rhel_ipv6_persistence_available; then
            echo -e "$(localized_text "${YELLOW}  IPv6 未检测到 ip6tables.service 或 /etc/sysconfig/ip6tables；如有 IPv6 connlimit 规则，可能只能在本次运行期生效。${PLAIN}" "${YELLOW}IPv6 ip6tables.service or /etc/sysconfig/ip6tables is not detected; if there is a IPv6 connlimit rule, it may only take effect during this run.${PLAIN}" "${YELLOW}IPv6 ip6tables.service или /etc/sysconfig/ip6tables не обнаружен; если существует правило connlimit IPv6, оно может вступить в силу только во время этого запуска.${PLAIN}")"
        fi
    else
        print_port_connlimit_persistence_unavailable
    fi

    if [[ "$backend" == "netfilter-persistent" ]] && command -v systemctl >/dev/null 2>&1 && systemctl list-unit-files netfilter-persistent.service --no-legend 2>/dev/null | grep -q .; then
        local enabled active
        enabled=$(systemctl is-enabled netfilter-persistent 2>/dev/null || true)
        active=$(systemctl is-active netfilter-persistent 2>/dev/null || true)
        echo "$(localized_text "  开机恢复服务：netfilter-persistent enabled=${enabled:-unknown}, active=${active:-unknown}。" "Restore service after booting: netfilter-persistent enabled=${enabled:-unknown}, active=${active:-unknown}." "Восстановление службы после загрузки: netfilter-persistent Enabled=${enabled:-unknown}, active=${active:-unknown}.")"
    fi
    if port_connlimit_systemd_unit_exists iptables; then
        local iptables_enabled iptables_active
        iptables_enabled=$(systemctl is-enabled iptables 2>/dev/null || true)
        iptables_active=$(systemctl is-active iptables 2>/dev/null || true)
        echo "$(localized_text "  开机恢复服务：iptables enabled=${iptables_enabled:-unknown}, active=${iptables_active:-unknown}。" "Restore service after booting: iptables enabled=${iptables_enabled:-unknown}, active=${iptables_active:-unknown}." "Восстановление службы после загрузки: iptables включен=${iptables_enabled:-unknown}, активен=${iptables_active:-unknown}.")"
    fi
    if port_connlimit_systemd_unit_exists ip6tables; then
        local ip6tables_enabled ip6tables_active
        ip6tables_enabled=$(systemctl is-enabled ip6tables 2>/dev/null || true)
        ip6tables_active=$(systemctl is-active ip6tables 2>/dev/null || true)
        echo "$(localized_text "  开机恢复服务：ip6tables enabled=${ip6tables_enabled:-unknown}, active=${ip6tables_active:-unknown}。" "Restore service at startup: ip6tables enabled=${ip6tables_enabled:-unknown}, active=${ip6tables_active:-unknown}." "Восстановление службы при запуске: ip6tables Enabled=${ip6tables_enabled:-unknown}, active=${ip6tables_active:-unknown}.")"
    fi

    if (( v4_runtime > 0 && v4_saved == 0 )) || (( v6_runtime > 0 && v6_saved == 0 )); then
        echo -e "$(localized_text "${YELLOW}  提示：检测到运行时 connlimit 规则尚未出现在当前可用的保存文件中，重启后可能丢失。${PLAIN}" "${YELLOW}Tip: It was detected that the runtime connlimit rule does not yet appear in the currently available save file and may be lost after restarting.${PLAIN}" "${YELLOW}Совет. Было обнаружено, что правило connlimit во время выполнения еще не отображается в доступном на данный момент файле сохранения и может быть потеряно после перезапуска.${PLAIN}")"
    elif (( v4_runtime + v6_runtime == 0 && v4_saved + v6_saved > 0 )); then
        echo -e "$(localized_text "${YELLOW}  提示：运行时没有脚本规则，但保存文件里仍有旧标记；如不更新快照，重启后可能恢复旧规则。${PLAIN}" "${YELLOW}Tip: There are no script rules when running, but there are still old marks in the saved file; if the snapshot is not updated, the old rules may be restored after restarting.${PLAIN}" "${YELLOW}Совет: При запуске скрипта правила отсутствуют, но в сохраненном файле все еще остаются старые отметки; если снимок не обновляется, старые правила могут быть восстановлены после перезапуска.${PLAIN}")"
    elif (( v4_runtime + v6_runtime > 0 )); then
        echo -e "$(localized_text "${GREEN}  已在当前可用的保存文件中检测到脚本规则标记，重启恢复还取决于对应恢复服务是否启用。${PLAIN}" "${GREEN}A script rule tag has been detected in a currently available save file. Restarting recovery also depends on whether the corresponding recovery service is enabled.${PLAIN}" "${GREEN}В доступном в данный момент файле сохранения обнаружен тег правила сценария. Перезапуск восстановления также зависит от того, включена ли соответствующая служба восстановления.${PLAIN}")"
    else
        echo -e "$(localized_text "${BLUE}  当前没有检测到脚本添加的运行时 connlimit 规则。${PLAIN}" "${BLUE}Runtime connlimit rules added by the script are not currently detected.${PLAIN}" "${BLUE}Правила connlimit во время выполнения, добавленные сценарием, в настоящее время не обнаружены.${PLAIN}")"
    fi
}

print_nft_port_connlimit_persistence_status() {
    local runtime_count saved_count legacy_runtime service_enabled service_active
    runtime_count=$(port_connlimit_nft_rule_entries | grep -c . || true)
    saved_count=$(port_connlimit_persisted_rule_count "$PORT_CONNLIMIT_NFT_CONFIG")
    legacy_runtime=$(( $(port_connlimit_runtime_rule_count iptables) + $(port_connlimit_runtime_rule_count ip6tables) ))
    service_enabled="unknown"
    service_active="unknown"
    if command -v systemctl >/dev/null 2>&1; then
        service_enabled=$(systemctl is-enabled "$PORT_CONNLIMIT_NFT_SERVICE" 2>/dev/null || true)
        service_active=$(systemctl is-active "$PORT_CONNLIMIT_NFT_SERVICE" 2>/dev/null || true)
    fi

    echo -e "$(localized_text "${CYAN}持久化检查：${PLAIN}" "${CYAN}Persistence check:${PLAIN}" "${CYAN}Проверка сохранения:${PLAIN}")"
    echo "$(localized_text "  后端：原生 nftables；专用表：inet ${PORT_CONNLIMIT_NFT_TABLE}" "  Backend: native nftables; table: inet ${PORT_CONNLIMIT_NFT_TABLE}" "  Бэкенд: нативный nftables; таблица: inet ${PORT_CONNLIMIT_NFT_TABLE}")"
    echo "$(localized_text "  运行时规则：${runtime_count} 条；配置文件：${PORT_CONNLIMIT_NFT_CONFIG} 中 ${saved_count} 条。" "  Runtime rules: ${runtime_count}; configuration file: ${saved_count} in ${PORT_CONNLIMIT_NFT_CONFIG}." "  Правила во время выполнения: ${runtime_count}; в файле ${PORT_CONNLIMIT_NFT_CONFIG}: ${saved_count}.")"
    echo "$(localized_text "  开机恢复：${PORT_CONNLIMIT_NFT_SERVICE} enabled=${service_enabled:-unknown}, active=${service_active:-unknown}。" "  Boot restore: ${PORT_CONNLIMIT_NFT_SERVICE} enabled=${service_enabled:-unknown}, active=${service_active:-unknown}." "  Восстановление при загрузке: ${PORT_CONNLIMIT_NFT_SERVICE} enabled=${service_enabled:-unknown}, active=${service_active:-unknown}.")"
    if (( legacy_runtime > 0 )); then
        echo -e "$(localized_text "${YELLOW}  检测到 ${legacy_runtime} 条遗留 iptables/ip6tables 规则，可能与 nftables 限制叠加。${PLAIN}" "${YELLOW}  Found ${legacy_runtime} legacy iptables/ip6tables rule(s), which may overlap the nftables limits.${PLAIN}" "${YELLOW}  Обнаружено старых правил iptables/ip6tables: ${legacy_runtime}; они могут применяться вместе с ограничениями nftables.${PLAIN}")"
    elif [[ "$runtime_count" -eq "$saved_count" && "$service_enabled" == "enabled" ]]; then
        echo -e "$(localized_text "${GREEN}  运行时规则、配置文件和开机恢复状态一致。${PLAIN}" "${GREEN}  Runtime rules, configuration file, and boot restoration are consistent.${PLAIN}" "${GREEN}  Правила, файл конфигурации и восстановление при загрузке согласованы.${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}  运行时、配置文件或开机恢复状态不一致。${PLAIN}" "${YELLOW}  Runtime, configuration file, or boot restoration state is inconsistent.${PLAIN}" "${YELLOW}  Состояние правил, файла конфигурации или восстановления при загрузке не согласовано.${PLAIN}")"
    fi
}

print_port_connlimit_persistence_status() {
    if port_connlimit_nft_is_managed; then
        print_nft_port_connlimit_persistence_status
    else
        print_legacy_port_connlimit_persistence_status
    fi
}

enable_port_connlimit_persistence_service() {
    local backend="${1:-$(port_connlimit_persistence_backend)}"

    if [[ "$backend" == "netfilter-persistent" ]] && command -v systemctl >/dev/null 2>&1 && systemctl list-unit-files netfilter-persistent.service --no-legend 2>/dev/null | grep -q .; then
        if systemctl enable netfilter-persistent >/dev/null 2>&1; then
            echo -e "$(localized_text "${GREEN}✅ 已确认 netfilter-persistent 开机恢复服务启用。${PLAIN}" "${GREEN}✅ It has been confirmed that the netfilter-persistent boot recovery service is enabled.${PLAIN}" "${GREEN}. Было подтверждено, что служба восстановления загрузки с постоянным фильтром netfilter включена.${PLAIN}")"
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 未能启用 netfilter-persistent 服务；规则文件已保存，但开机恢复状态需要手动确认。${PLAIN}" "${YELLOW}⚠️ Failed to enable the netfilter-persistent service; the rule file has been saved, but the boot recovery status requires manual confirmation.${PLAIN}" "${YELLOW}⚠️ Не удалось включить постоянную службу netfilter; файл правил сохранен, но статус восстановления загрузки требует подтверждения вручную.${PLAIN}")"
        fi
    fi
    if [[ "$backend" == "rhel-iptables-services" ]] && port_connlimit_systemd_unit_exists iptables; then
        if systemctl enable iptables >/dev/null 2>&1; then
            echo -e "$(localized_text "${GREEN}✅ 已确认 iptables 开机恢复服务启用。${PLAIN}" "${GREEN}✅ It is confirmed that iptables boot recovery service is enabled.${PLAIN}" "${GREEN}. Подтверждено, что служба восстановления загрузки iptables включена.${PLAIN}")"
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 未能启用 iptables 服务；IPv4 规则文件已保存，但开机恢复状态需要手动确认。${PLAIN}" "${YELLOW}⚠️ Failed to enable the iptables service; IPv4 rule file has been saved, but the power-on recovery status requires manual confirmation.${PLAIN}" "${YELLOW}⚠️ Не удалось включить службу iptables; Файл правил IPv4 сохранен, но состояние восстановления при включении требует подтверждения вручную.${PLAIN}")"
        fi
    fi
    if [[ "$backend" == "rhel-iptables-services" ]] && port_connlimit_systemd_unit_exists ip6tables; then
        if systemctl enable ip6tables >/dev/null 2>&1; then
            echo -e "$(localized_text "${GREEN}✅ 已确认 ip6tables 开机恢复服务启用。${PLAIN}" "${GREEN}✅ It is confirmed that the ip6tables boot recovery service is enabled.${PLAIN}" "${GREEN}✅ Подтверждено, что служба восстановления загрузки ip6tables включена.${PLAIN}")"
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 未能启用 ip6tables 服务；IPv6 规则文件已保存，但开机恢复状态需要手动确认。${PLAIN}" "${YELLOW}⚠️ Failed to enable the ip6tables service; IPv6 rule file has been saved, but the boot recovery state needs to be manually confirmed.${PLAIN}" "${YELLOW}⚠️ Не удалось включить службу ip6tables; Файл правил IPv6 сохранен, но состояние восстановления загрузки необходимо подтвердить вручную.${PLAIN}")"
        fi
    fi
}

save_rhel_port_connlimit_family() {
    local save_cmd="$1"
    local file="$2"
    local label="$3"
    local tmp_file err_file output

    tmp_file=$(mktemp /tmp/vps-connlimit-rules.XXXXXX) || return 1
    err_file=$(mktemp /tmp/vps-connlimit-save.XXXXXX) || {
        rm -f "$tmp_file"
        return 1
    }
    if "$save_cmd" > "$tmp_file" 2>"$err_file"; then
        output=$(<"$err_file")
        mkdir -p "$(dirname "$file")" || {
            rm -f "$tmp_file"
            rm -f "$err_file"
            echo -e "$(localized_text "${RED}❌ 无法创建 $(dirname "$file")，${label} connlimit 持久化保存失败。${PLAIN}" "${RED}❌ Unable to create $(dirname \"$file\"), ${label} connlimit persistent save failed.${PLAIN}" "${RED}❌ Невозможно создать $(dirname \"$file\"), не удалось сохранить постоянное сохранение connlimit ${label}.${PLAIN}")"
            return 1
        }
        if cp "$tmp_file" "$file"; then
            chmod 600 "$file" 2>/dev/null || true
            rm -f "$tmp_file"
            rm -f "$err_file"
            echo -e "$(localized_text "${GREEN}✅ 已写入 ${file}，${label} connlimit 快照已保存。${PLAIN}" "${GREEN}✅ ${file} has been written, ${label} connlimit snapshot has been saved.${PLAIN}" "${GREEN}✅ ${file} записан, снапшот connlimit ${label} сохранен.${PLAIN}")"
            return 0
        fi
        rm -f "$tmp_file"
        rm -f "$err_file"
        echo -e "$(localized_text "${RED}❌ 写入 ${file} 失败，${label} connlimit 规则仍可能只在运行时有效。${PLAIN}" "${RED}❌ Writing to ${file} failed, ${label} connlimit rules may still only be valid at runtime.${PLAIN}" "${RED}❌ Не удалось выполнить запись в ${file}, правила connlimit ${label} все еще могут быть действительны только во время выполнения.${PLAIN}")"
        return 1
    fi

    output=$(<"$err_file")
    rm -f "$tmp_file"
    rm -f "$err_file"
    echo -e "$(localized_text "${RED}❌ ${save_cmd} 执行失败，${label} connlimit 持久化保存失败：${output}${PLAIN}" "${RED}❌ ${save_cmd} execution failed, ${label} connlimit persistent save failed: ${output}${PLAIN}" "${RED}❌ ${save_cmd} не удалось выполнить, ${label} постоянное сохранение connlimit не удалось: ${output}${PLAIN}")"
    return 1
}

save_rhel_port_connlimit_persistence() {
    local rc=0
    local iptables_save ip6tables_save
    local v6_runtime v6_saved

    iptables_save=$(port_connlimit_command_path iptables-save 2>/dev/null || true)
    if [[ -z "$iptables_save" ]]; then
        echo -e "$(localized_text "${RED}❌ 未检测到 iptables-save，无法写入 RHEL 系列 IPv4 connlimit 持久化文件。${PLAIN}" "${RED}❌ iptables-save not detected, unable to write to RHEL series IPv4 connlimit persistence file.${PLAIN}" "${RED}❌ iptables-сохранение не обнаружено, невозможно записать в файл постоянства connlimit серии RHEL IPv4.${PLAIN}")"
        rc=1
    else
        save_rhel_port_connlimit_family "$iptables_save" "/etc/sysconfig/iptables" "IPv4" || rc=1
    fi

    v6_runtime=$(port_connlimit_runtime_rule_count ip6tables)
    v6_saved=$(port_connlimit_persisted_rule_count /etc/sysconfig/ip6tables)
    if port_connlimit_rhel_ipv6_persistence_available; then
        ip6tables_save=$(port_connlimit_command_path ip6tables-save 2>/dev/null || true)
        save_rhel_port_connlimit_family "$ip6tables_save" "/etc/sysconfig/ip6tables" "IPv6" || rc=1
    elif (( v6_runtime > 0 || v6_saved > 0 )); then
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 RHEL IPv6 持久化路径；当前 IPv6 connlimit 规则或旧快照无法由脚本可靠保存。${PLAIN}" "${YELLOW}⚠️ RHEL IPv6 persistence path not detected; current IPv6 connlimit rules or old snapshots cannot be reliably saved by the script.${PLAIN}" "${YELLOW}⚠️ Путь сохранения RHEL IPv6 не обнаружен; текущие правила connlimit IPv6 или старые снимки не могут быть надежно сохранены сценарием.${PLAIN}")"
        rc=1
    fi

    enable_port_connlimit_persistence_service "rhel-iptables-services"
    print_port_connlimit_persistence_status
    return "$rc"
}

save_legacy_port_connlimit_persistence() {
    local output backend
    local v4_runtime v6_runtime v4_saved v6_saved

    backend=$(port_connlimit_persistence_backend)
    if [[ "$backend" == "none" ]]; then
        print_port_connlimit_persistence_unavailable
        return 1
    fi

    if [[ "$backend" == "rhel-iptables-services" ]]; then
        save_rhel_port_connlimit_persistence
        return $?
    fi

    local netfilter_cmd
    netfilter_cmd=$(port_connlimit_command_path netfilter-persistent)
    if output=$("$netfilter_cmd" save 2>&1); then
        echo -e "$(localized_text "${GREEN}✅ 已执行 netfilter-persistent save，当前 iptables/ip6tables 快照已写入持久化文件。${PLAIN}" "${GREEN}✅ netfilter-persistent save has been executed, and the current iptables/ip6tables snapshot has been written to the persistent file.${PLAIN}" "${GREEN}Сохранение веще netfilter-persistent выполнено, и текущий снимок iptables/ip6tables записан в постоянный файл.${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ netfilter-persistent save 执行失败：${output}${PLAIN}" "${RED}❌ netfilter-persistent save execution failed: ${output}${PLAIN}" "${RED}❌ не удалось выполнить постоянное сохранение netfilter: ${output}${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}本次不会假装已保存；当前 connlimit 规则仍可能只在运行时有效。${PLAIN}" "${YELLOW}Will not pretend to be saved this time; current connlimit rules may still only be valid at runtime.${PLAIN}" "${YELLOW}на этот раз не будет притворяться сохраненным; текущие правила connlimit могут по-прежнему действовать только во время выполнения.${PLAIN}")"
        return 1
    fi

    enable_port_connlimit_persistence_service "$backend"
    print_port_connlimit_persistence_status

    v4_runtime=$(port_connlimit_runtime_rule_count iptables)
    v6_runtime=$(port_connlimit_runtime_rule_count ip6tables)
    v4_saved=$(port_connlimit_saved_rule_count_for_family 4 "$backend")
    v6_saved=$(port_connlimit_saved_rule_count_for_family 6 "$backend")

    if (( v4_runtime > 0 && v4_saved == 0 )) || (( v6_runtime > 0 && v6_saved == 0 )); then
        echo -e "$(localized_text "${RED}❌ 保存后仍未在当前持久化文件中检测到脚本规则标记，请不要认为重启后一定会恢复。${PLAIN}" "${RED}❌ The script rule mark is still not detected in the current persistence file after saving. Please do not think that it will be restored after restarting.${PLAIN}" "${RED}❌ Метка правила сценария по-прежнему не обнаружена в текущем файле персистентности после сохранения. Пожалуйста, не думайте, что он восстановится после перезагрузки.${PLAIN}")"
        return 1
    fi

    return 0
}

save_nft_port_connlimit_persistence() {
    local entries
    entries=$(port_connlimit_nft_rule_entries)
    if write_port_connlimit_nft_config "$entries" 0; then
        echo -e "$(localized_text "${GREEN}nftables 配置已保存到 ${PORT_CONNLIMIT_NFT_CONFIG}，并启用 ${PORT_CONNLIMIT_NFT_SERVICE}。${PLAIN}" "${GREEN}nftables configuration saved to ${PORT_CONNLIMIT_NFT_CONFIG}; ${PORT_CONNLIMIT_NFT_SERVICE} is enabled.${PLAIN}" "${GREEN}Конфигурация nftables сохранена в ${PORT_CONNLIMIT_NFT_CONFIG}; служба ${PORT_CONNLIMIT_NFT_SERVICE} включена.${PLAIN}")"
        return 0
    fi
    return 1
}

save_port_connlimit_persistence() {
    if port_connlimit_nft_is_managed; then
        save_nft_port_connlimit_persistence
    else
        save_legacy_port_connlimit_persistence
    fi
}

auto_save_port_connlimit_persistence_after_change() {
    local action_label="$1"

    echo ""
    echo -e "$(localized_text "${CYAN}正在尝试自动保存 connlimit 持久化快照（${action_label} 后刷新）...${PLAIN}" "${CYAN}Is trying to automatically save the connlimit persistence snapshot (refreshed after ${action_label})...${PLAIN}" "${CYAN}пытается автоматически сохранить снимок состояния connlimit (обновляется после ${action_label})...${PLAIN}")"
    if save_port_connlimit_persistence; then
        echo -e "$(localized_text "${GREEN}✅ connlimit 持久化快照已刷新。${PLAIN}" "${GREEN}✅ connlimit persistence snapshot has been refreshed.${PLAIN}" "${GREEN}Снимок состояния постоянства connlimit ✅ обновлен.${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}⚠️ connlimit 运行时规则已按上方结果处理，但当前无法确认重启后保留。${PLAIN}" "${YELLOW}⚠️ The connlimit runtime rule has been processed according to the above results, but it is currently unable to confirm that it will be retained after restarting.${PLAIN}" "${YELLOW}⚠️ Правило времени выполнения connlimit было обработано в соответствии с приведенными выше результатами, но в настоящее время невозможно подтвердить, что оно будет сохранено после перезапуска.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}请按提示补齐系统持久化能力，或在确认发行版机制后手动保存；不要默认重启后仍存在。${PLAIN}" "${YELLOW}Please follow the prompts to complete the system persistence capability, or save it manually after confirming the release mechanism; do not default to it persisting after restarting.${PLAIN}" "${YELLOW}Следуйте инструкциям, чтобы завершить настройку сохранения системы, или сохраните ее вручную после подтверждения механизма выпуска; не по умолчанию сохраняйте его после перезапуска.${PLAIN}")"
        return 1
    fi
}

func_save_port_connlimit_persistence() {
    local effect scope
    print_port_connlimit_persistence_status
    echo ""
    if port_connlimit_nft_is_managed; then
        effect="$(localized_text "保存 nftables 专用表配置并启用 ${PORT_CONNLIMIT_NFT_SERVICE}" "save the dedicated nftables table configuration and enable ${PORT_CONNLIMIT_NFT_SERVICE}" "сохранить конфигурацию выделенной таблицы nftables и включить ${PORT_CONNLIMIT_NFT_SERVICE}")"
        scope="$(localized_text "不修改 UFW/firewalld，也不保存其他 nftables 表" "do not modify UFW/firewalld or save other nftables tables" "не изменять UFW/firewalld и не сохранять другие таблицы nftables")"
    else
        effect="$(localized_text "按系统可用机制保存 iptables/ip6tables 快照" "save the iptables/ip6tables snapshot using the available system mechanism" "сохранить снимок iptables/ip6tables через доступный системный механизм")"
        scope="$(localized_text "不清空运行时规则，也不修改 UFW/firewalld" "do not clear runtime rules or modify UFW/firewalld" "не очищать текущие правила и не изменять UFW/firewalld")"
    fi
    confirm_risk_action "$(localized_text "保存端口并发连接限制持久化快照" "Save port concurrent connection limit persistent snapshot" "Сохранить постоянный снимок ограничения количества одновременных подключений к порту")" \
        "$effect" \
        "$(localized_text "用于手动检查或失败后重试" "use this for a manual check or retry after failure" "использовать для ручной проверки или повторной попытки после ошибки")" \
        "$scope" || {
        echo -e "$(localized_text "${BLUE}已取消保存端口并发连接限制持久化快照。${PLAIN}" "${BLUE}The port concurrent connection limit persistent snapshot has been canceled.${PLAIN}" "${BLUE}Постоянный снимок ограничения количества одновременных подключений к порту был отменен.${PLAIN}")"
        return 0
    }

    save_port_connlimit_persistence
}

port_connlimit_loopback_only_listener() {
    local port="$1"
    command -v ss >/dev/null 2>&1 || return 1

    ss -Htlpn 2>/dev/null | awk -v port="$port" '
        function is_target(addr) {
            return addr ~ (":" port "$") || addr ~ ("\\]:" port "$")
        }
        is_target($4) {
            if ($4 ~ /^(127\.0\.0\.1|localhost):/ || $4 ~ /^\[::1\]:/) {
                loopback = 1
            } else {
                public = 1
            }
        }
        END {
            exit (loopback && !public ? 0 : 1)
        }
    '
}

print_port_connlimit_scope_notice() {
    local port="$1"

    echo -e "$(localized_text "${YELLOW}说明：本功能优先使用原生 nftables；不支持 ct count 时回退到 iptables/ip6tables connlimit。该限制不等同于 UFW/firewalld 端口放行。${PLAIN}" "${YELLOW}This feature prefers native nftables and falls back to iptables/ip6tables connlimit when ct count is unavailable. It does not allow ports through UFW/firewalld.${PLAIN}" "${YELLOW}Функция предпочитает нативный nftables и переходит на iptables/ip6tables connlimit, если ct count недоступен. Она не открывает порты в UFW/firewalld.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}默认按“每个来源 IP”限制 TCP 并发连接数，不做全局总连接数限制。${PLAIN}" "${YELLOW}By default, the limit applies per source IP, not to the global connection total.${PLAIN}" "${YELLOW}По умолчанию ограничение применяется отдельно к каждому исходному IP-адресу, а не к общему числу соединений.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}添加/删除后会自动尝试刷新持久化快照；系统不支持时会明确提示只在本次运行期生效。${PLAIN}" "${YELLOW}After is added/deleted, it will automatically try to refresh the persistent snapshot; if the system does not support it, it will clearly prompt that it will only take effect during this running period.${PLAIN}" "${YELLOW}После добавления/удаления он автоматически попытается обновить постоянный снимок; если система его не поддерживает, она четко сообщит, что оно вступит в силу только в течение этого периода работы.${PLAIN}")"

    if [[ "$port" == "443" ]]; then
        echo -e "$(localized_text "${RED}⚠️ 443 强提醒：如果当前启用了 443端口复用/端口复用，本限制会作用于整个公网 443。${PLAIN}" "${RED}⚠️ 443 strong reminder: If Port 443 Reuse/port reuse is currently enabled, this restriction will apply to the entire public port 443.${PLAIN}" "${RED}⚠️ 443 Настоятельное напоминание: если в настоящее время включено мультиплексирование одной записи/порта 443, это ограничение будет применяться ко всей публичного порта 443.${PLAIN}")"
        echo -e "$(localized_text "${RED}它不能精准限制某一个 Xray/3x-ui 入站、某一个 SNI、某一个 UUID 或某一个用户。${PLAIN}" "${RED}Cannot accurately restrict the inbound of a certain Xray/3x-ui, a certain SNI, a certain UUID or a certain user.${PLAIN}" "${RED}не может точно ограничить входящее подключение определенного Xray/3x-ui, определенного SNI, определенного UUID или определенного пользователя.${PLAIN}")"
    fi

    if port_connlimit_loopback_only_listener "$port"; then
        echo -e "$(localized_text "${YELLOW}⚠️ 检测到该端口可能只监听 127.0.0.1/::1。本功能建议限制公网监听端口。${PLAIN}" "${YELLOW}⚠️ Detected that this port may only be listening on 127.0.0.1/::1. This feature recommends limiting public listening ports.${PLAIN}" "${YELLOW}⚠️ Обнаружено, что этот порт может прослушивать только 127.0.0.1/::1. Эта функция рекомендует ограничить порты прослушивания публичной сети.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}如果限制本地后端端口，可能只能限制本机代理到后端的连接，不能代表真实公网来源。${PLAIN}" "${YELLOW}If you limit the local backend port, you may only be able to limit the connection from the local proxy to the backend, which cannot represent the real public source.${PLAIN}" "${YELLOW}Если вы ограничите локальный внутренний порт, вы сможете ограничить только подключение от локального прокси к серверной части, которая не может представлять собой реальный источник публичной сети.${PLAIN}")"
    fi
}

port_connlimit_rule_limits_for_port() {
    local cmd="$1"
    local port="$2"
    local comment
    comment=$(port_connlimit_comment "$port")

    "$cmd" -S INPUT 2>/dev/null | awk -v expected_comment="$comment" '
        $1 == "-A" && $2 == "INPUT" {
            matched = 0
            limit = ""
            for (i = 3; i <= NF; i++) {
                if ($i == "--comment" && i < NF) {
                    value = $(i + 1)
                    gsub(/^["\047]|["\047]$/, "", value)
                    if (value == expected_comment) {
                        matched = 1
                    }
                }
                if ($i == "--connlimit-above" && i < NF) {
                    limit = $(i + 1)
                }
            }
            if (matched && limit ~ /^[0-9]+$/) {
                print limit
            }
        }
    '
}

run_port_connlimit_rule_action() {
    local cmd="$1"
    local action="$2"
    local port="$3"
    local limit="$4"
    local mask="$5"
    local family_label="$6"
    local comment output existing_limits existing_count existing_limit keep_count remove_count i
    local changed=0 removed=0 cleanup_failed=0
    comment=$(port_connlimit_comment "$port")

    local args=(
        -p tcp --dport "$port" --syn
        -m connlimit --connlimit-above "$limit" --connlimit-mask "$mask" --connlimit-saddr
        -m comment --comment "$comment"
        -j REJECT --reject-with tcp-reset
    )

    case "$action" in
        add)
            existing_limits=$(port_connlimit_rule_limits_for_port "$cmd" "$port")
            keep_count=$(printf '%s\n' "$existing_limits" | grep -xc "$limit" || true)
            if (( keep_count == 0 )); then
                if output=$("$cmd" -I INPUT "${args[@]}" 2>&1); then
                    changed=1
                else
                    echo -e "$(localized_text "${RED}❌ ${family_label} 添加失败：${output}${PLAIN}" "${RED}❌ ${family_label} Failed to add: ${output}${PLAIN}" "${RED}❌ ${family_label} Не удалось добавить: ${output}${PLAIN}")"
                    return 1
                fi
            fi

            while read -r existing_count existing_limit; do
                [[ -n "$existing_count" && -n "$existing_limit" ]] || continue
                keep_count=0
                [[ "$existing_limit" == "$limit" ]] && keep_count=1
                remove_count=$((existing_count - keep_count))
                local cleanup_args=(
                    -p tcp --dport "$port" --syn
                    -m connlimit --connlimit-above "$existing_limit" --connlimit-mask "$mask" --connlimit-saddr
                    -m comment --comment "$comment"
                    -j REJECT --reject-with tcp-reset
                )
                for ((i = 0; i < remove_count; i++)); do
                    if output=$("$cmd" -D INPUT "${cleanup_args[@]}" 2>&1); then
                        removed=$((removed + 1))
                        changed=1
                    else
                        cleanup_failed=1
                        echo -e "$(localized_text "${RED}❌ ${family_label} 清理端口 ${port} 的旧限制 ${existing_limit} 失败：${output}${PLAIN}" "${RED}❌ ${family_label} Failed to clean up old limit ${existing_limit} on port ${port}: ${output}${PLAIN}" "${RED}❌ ${family_label} Не удалось очистить старое ограничение ${existing_limit} на порту ${port}: ${output}${PLAIN}")"
                        break
                    fi
                done
            done < <(printf '%s\n' "$existing_limits" | sed '/^$/d' | sort -n | uniq -c)

            if (( cleanup_failed != 0 )); then
                echo -e "$(localized_text "${YELLOW}⚠️ ${family_label} 目标规则已保留，但同端口旧规则可能仍会叠加生效。${PLAIN}" "${YELLOW}⚠️ ${family_label} The target rule is retained, but old rules on the same port may still apply cumulatively.${PLAIN}" "${YELLOW}⚠️ ${family_label} Целевое правило сохранено, но старые правила на том же порту могут продолжать действовать совместно.${PLAIN}")"
                return 1
            fi
            if (( changed == 0 )); then
                echo -e "$(localized_text "${BLUE}ℹ️ ${family_label} 已存在唯一目标规则：端口 ${port}，每来源 IP 最大并发 ${limit}。${PLAIN}" "${BLUE}ℹ️ ${family_label} The single target rule already exists: port ${port}, maximum concurrency per source IP ${limit}.${PLAIN}" "${BLUE}ℹ️ ${family_label} Единственное целевое правило уже существует: порт ${port}, максимальное количество одновременных подключений на IP-адрес источника — ${limit}.${PLAIN}")"
            else
                echo -e "$(localized_text "${GREEN}✅ ${family_label} 已应用：端口 ${port}，每来源 IP 最大并发 ${limit}；清理旧/重复规则 ${removed} 条。${PLAIN}" "${GREEN}✅ ${family_label} Applied: port ${port}, maximum concurrency per source IP ${limit}; removed ${removed} old/duplicate rules.${PLAIN}" "${GREEN}✅ ${family_label} Применено: порт ${port}, максимальное количество одновременных подключений на IP-адрес источника — ${limit}; удалено старых/повторяющихся правил: ${removed}.${PLAIN}")"
            fi
            return 0
            ;;
        delete)
            existing_limits=$(port_connlimit_rule_limits_for_port "$cmd" "$port")
            remove_count=$(printf '%s\n' "$existing_limits" | grep -xc "$limit" || true)
            if (( remove_count == 0 )); then
                echo -e "$(localized_text "${YELLOW}⚠️ ${family_label} 未找到匹配规则：端口 ${port}，连接数 ${limit}。${PLAIN}" "${YELLOW}⚠️ ${family_label} No matching rule found: port ${port}, connection number ${limit}.${PLAIN}" "${YELLOW}⚠️ ${family_label} Не найдено соответствующее правило: порт ${port}, номер подключения ${limit}.${PLAIN}")"
                return 1
            fi
            for ((i = 0; i < remove_count; i++)); do
                if output=$("$cmd" -D INPUT "${args[@]}" 2>&1); then
                    removed=$((removed + 1))
                else
                    echo -e "$(localized_text "${RED}❌ ${family_label} 删除失败：${output}${PLAIN}" "${RED}❌ ${family_label} Deletion failed: ${output}${PLAIN}" "${RED}❌ ${family_label} Не удалось удалить: ${output}${PLAIN}")"
                    return 1
                fi
            done
            echo -e "$(localized_text "${GREEN}✅ ${family_label} 已删除：端口 ${port}，连接数 ${limit}，共 ${removed} 条。${PLAIN}" "${GREEN}✅ ${family_label} Deleted: port ${port}, connection limit ${limit}, ${removed} rule(s) in total.${PLAIN}" "${GREEN}✅ ${family_label} Удалено: порт ${port}, ограничение подключений ${limit}, всего правил: ${removed}.${PLAIN}")"
            return 0
            ;;
        *)
            echo -e "$(localized_text "${RED}❌ 未知 connlimit 操作：${action}${PLAIN}" "${RED}❌ unknown connlimit operation: ${action}${PLAIN}" "${RED}❌ неизвестная операция connlimit: ${action}${PLAIN}")"
            return 1
            ;;
    esac
}

read_connlimit_port() {
    local __target="$1"
    local port

    read_trimmed port "$(localized_text "请输入要限制的端口号（1-65535，回车或 0 取消）: " "Please enter the port number to be restricted (1-65535, press Enter or 0 to cancel):" "Введите номер порта, который необходимо ограничить (1-65535, нажмите Enter или 0 для отмены):")"
    if [[ -z "$port" || "$port" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消端口并发连接限制操作。${PLAIN}" "${BLUE}The port concurrent connection restriction operation has been canceled.${PLAIN}" "${BLUE}Операция ограничения одновременных подключений к порту была отменена.${PLAIN}")"
        return 1
    fi
    if ! is_valid_port "$port"; then
        echo -e "$(localized_text "${RED}❌ 端口无效，必须是 1-65535。${PLAIN}" "${RED}❌ Invalid port, must be 1-65535.${PLAIN}" "${RED}❌ Неверный порт, должен быть 1-65535.${PLAIN}")"
        return 1
    fi

    printf -v "$__target" '%s' "$((10#$port))"
}

read_connlimit_limit() {
    local __target="$1"
    local limit

    read_trimmed limit "$(localized_text "请输入每个来源 IP 最大 TCP 并发连接数（正整数，回车或 0 取消）: " "Please enter the maximum number of TCP concurrent connections for each source IP (positive integer, press Enter or 0 to cancel):" "Введите максимальное количество одновременных подключений TCP для каждого IP-адреса источника (положительное целое число, нажмите Enter или 0 для отмены):")"
    if [[ -z "$limit" || "$limit" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消端口并发连接限制操作。${PLAIN}" "${BLUE}The port concurrent connection restriction operation has been canceled.${PLAIN}" "${BLUE}Операция ограничения одновременных подключений к порту была отменена.${PLAIN}")"
        return 1
    fi
    if ! is_valid_connlimit_value "$limit"; then
        echo -e "$(localized_text "${RED}❌ 连接数无效，必须是正整数。${PLAIN}" "${RED}❌ The number of connections is invalid and must be a positive integer.${PLAIN}" "${RED}❌ Недопустимое количество соединений и должно быть положительным целым числом.${PLAIN}")"
        return 1
    fi

    printf -v "$__target" '%s' "$((10#$limit))"
}

func_add_port_connlimit_rule() {
    local port limit apply_ipv6 backend effect rollback marker rc=0 touched=0 include_ipv6=1

    read_connlimit_port port || return 0
    read_connlimit_limit limit || return 0
    read_trimmed apply_ipv6 "$(localized_text "是否同时应用 IPv6？(y/N，默认 N): " "Apply the rule to IPv6 too? (y/N, default N): " "Также применить правило к IPv6? (y/N, по умолчанию N): ")"
    is_yes "$apply_ipv6" || include_ipv6=0

    print_port_connlimit_scope_notice "$port"
    marker=$(port_connlimit_comment "$port")
    echo -e "$(localized_text "${CYAN}规则标记：${marker}${PLAIN}" "${CYAN}Rule marker: ${marker}${PLAIN}" "${CYAN}Метка правила: ${marker}${PLAIN}")"

    if port_connlimit_nft_is_managed || ensure_nft_connlimit_support; then
        backend="nftables"
        effect="$(localized_text "在 nftables 专用表中使用 ct count 按来源 IP 限制并发，并原子更新整张表" "use ct count in a dedicated nftables table to limit concurrency per source IP and update the table atomically" "использовать ct count в выделенной таблице nftables для ограничения по исходному IP-адресу и атомарного обновления таблицы")"
        rollback="$(localized_text "回到本菜单删除同端口和连接数；必要时删除 nftables 表 ${PORT_CONNLIMIT_NFT_TABLE}" "Return here to remove the same port and limit; if necessary, delete nftables table ${PORT_CONNLIMIT_NFT_TABLE}" "Вернитесь в это меню и удалите тот же порт и лимит; при необходимости удалите таблицу nftables ${PORT_CONNLIMIT_NFT_TABLE}")"
    else
        backend="iptables"
        effect="$(localized_text "写入 iptables/ip6tables INPUT connlimit 规则，拒绝超过 ${limit} 条并发的新 TCP 连接" "add iptables/ip6tables INPUT connlimit rules and reject new TCP connections above ${limit}" "добавить правила connlimit в INPUT iptables/ip6tables и отклонять новые TCP-подключения сверх ${limit}")"
        rollback="$(localized_text "回到本菜单删除同端口和连接数；必要时通过云控制台/VNC 清理 iptables 规则" "Return here to remove the same port and limit; if necessary, clear iptables rules through the cloud console/VNC" "Вернитесь в это меню и удалите тот же порт и лимит; при необходимости очистите правила iptables через облачную консоль/VNC")"
        ensure_connlimit_tool iptables "IPv4" || return 1
        if (( include_ipv6 == 1 )); then
            ensure_connlimit_tool ip6tables "IPv6" || return 1
        fi
        try_load_connlimit_module
    fi

    confirm_risk_action "$(localized_text "添加端口 ${port} 并发连接限制" "Add a concurrency limit to port ${port}" "Добавить ограничение подключений для порта ${port}")" \
        "$effect" \
        "$rollback" \
        "$(localized_text "该规则不代表端口已被 UFW/firewalld 放行。" "This rule does not allow the port through UFW/firewalld." "Это правило не открывает порт в UFW/firewalld.")" || {
        echo -e "$(localized_text "${BLUE}已取消添加端口并发连接限制。${PLAIN}" "${BLUE}Port concurrency limit was not added.${PLAIN}" "${BLUE}Добавление ограничения подключений отменено.${PLAIN}")"
        return 0
    }

    if [[ "$backend" == "nftables" ]]; then
        run_nft_port_connlimit_action add "$port" "$limit" "$include_ipv6"
        return $?
    fi

    if run_port_connlimit_rule_action iptables add "$port" "$limit" 32 "IPv4"; then
        touched=1
    else
        rc=1
    fi
    if (( include_ipv6 == 1 )); then
        if run_port_connlimit_rule_action ip6tables add "$port" "$limit" 128 "IPv6"; then
            touched=1
        else
            rc=1
        fi
    fi
    if [[ "$touched" -eq 1 ]]; then
        auto_save_port_connlimit_persistence_after_change "$(localized_text "添加规则" "add" "добавления")" || true
    else
        echo -e "$(localized_text "${YELLOW}规则添加不完整，未刷新持久化快照。${PLAIN}" "${YELLOW}Rules were not added completely; the persistent snapshot was not refreshed.${PLAIN}" "${YELLOW}Правила добавлены не полностью; постоянный снимок не обновлён.${PLAIN}")"
    fi
    return "$rc"
}

func_delete_port_connlimit_rule() {
    local port limit delete_ipv6 backend effect rollback marker rc=0 include_ipv6=1

    read_connlimit_port port || return 0
    read_connlimit_limit limit || return 0
    read_trimmed delete_ipv6 "$(localized_text "是否同时删除 IPv6 规则？(y/N，默认 N): " "Remove the IPv6 rule too? (y/N, default N): " "Также удалить правило IPv6? (y/N, по умолчанию N): ")"
    is_yes "$delete_ipv6" || include_ipv6=0

    print_port_connlimit_scope_notice "$port"
    marker=$(port_connlimit_comment "$port")
    echo -e "$(localized_text "${CYAN}规则标记：${marker}${PLAIN}" "${CYAN}Rule marker: ${marker}${PLAIN}" "${CYAN}Метка правила: ${marker}${PLAIN}")"

    if port_connlimit_nft_is_managed || ensure_nft_connlimit_support; then
        backend="nftables"
        effect="$(localized_text "从 nftables 专用表原子移除匹配限制，并迁移遗留 iptables 规则" "atomically remove the matching limit from the dedicated nftables table and migrate legacy iptables rules" "атомарно удалить лимит из выделенной таблицы nftables и перенести старые правила iptables")"
        rollback="$(localized_text "如误删，可重新添加同端口和连接数限制" "Re-add the same port and connection limit if needed" "При необходимости снова добавьте тот же порт и лимит подключений")"
    else
        backend="iptables"
        effect="$(localized_text "仅删除端口 ${port}、连接数 ${limit} 和对应脚本标记的 connlimit 规则" "remove only connlimit rules for port ${port}, limit ${limit}, and the matching script marker" "удалить только правила connlimit для порта ${port}, лимита ${limit} и соответствующей метки сценария")"
        rollback="$(localized_text "如误删，可重新添加同端口和连接数限制" "Re-add the same port and connection limit if needed" "При необходимости снова добавьте тот же порт и лимит подключений")"
        ensure_connlimit_tool iptables "IPv4" || return 1
        if (( include_ipv6 == 1 )); then
            ensure_connlimit_tool ip6tables "IPv6" || return 1
        fi
    fi

    confirm_risk_action "$(localized_text "删除端口 ${port} 并发连接限制" "Delete port ${port} concurrent connection limit" "Удалить лимит одновременных подключений порта ${port}")" \
        "$effect" \
        "$rollback" \
        "$(localized_text "本操作不清空 UFW/firewalld，也不删除非 VPS-Optimize 规则。" "This does not clear UFW/firewalld or remove rules not owned by VPS-Optimize." "Операция не очищает UFW/firewalld и не удаляет правила, не принадлежащие VPS-Optimize.")" || {
        echo -e "$(localized_text "${BLUE}已取消删除端口并发连接限制。${PLAIN}" "${BLUE}The port concurrent connection limit has been canceled.${PLAIN}" "${BLUE}Ограничение на количество одновременных подключений к порту отменено.${PLAIN}")"
        return 0
    }

    if [[ "$backend" == "nftables" ]]; then
        run_nft_port_connlimit_action delete "$port" "$limit" "$include_ipv6"
        return $?
    fi

    run_port_connlimit_rule_action iptables delete "$port" "$limit" 32 "IPv4" || rc=1
    if (( include_ipv6 == 1 )); then
        run_port_connlimit_rule_action ip6tables delete "$port" "$limit" 128 "IPv6" || rc=1
    fi
    auto_save_port_connlimit_persistence_after_change "$(localized_text "删除规则" "delete rule" "удалить правило")" || true
    return "$rc"
}

func_show_port_connlimit_rules() {
    local found=0

    echo -e "$(localized_text "${CYAN}当前由 VPS-Optimize 添加的端口并发连接限制规则：${PLAIN}" "${CYAN}The current port concurrent connection limit rule added by VPS-Optimize:${PLAIN}" "${CYAN}Текущее правило ограничения одновременных подключений к порту, добавленное VPS-Optimize:${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}标记格式：VPSO_CONN_LIMIT_PORT_<端口>${PLAIN}" "${YELLOW}Tag format: VPSO_CONN_LIMIT_PORT_<port>${PLAIN}" "${YELLOW}Формат тега : VPSO_CONN_LIMIT_PORT_<порт>${PLAIN}")"
    echo ""

    if command -v nft >/dev/null 2>&1 && nft list table inet "$PORT_CONNLIMIT_NFT_TABLE" >/dev/null 2>&1; then
        echo -e "${BOLD}nftables (inet ${PORT_CONNLIMIT_NFT_TABLE}):${PLAIN}"
        if nft -nn list table inet "$PORT_CONNLIMIT_NFT_TABLE" 2>/dev/null | grep -F 'VPSO_CONN_LIMIT_PORT_'; then
            found=1
        else
            echo "$(localized_text "  未发现 nftables 脚本规则。" "  No managed nftables rules found." "  Управляемые правила nftables не найдены.")"
        fi
        echo ""
    fi

    if command -v iptables >/dev/null 2>&1; then
        echo -e "${BOLD}$(localized_text "旧规则 IPv4" "Legacy IPv4" "Старые правила IPv4"):${PLAIN}"
        if iptables -S INPUT 2>/dev/null | grep -F 'VPSO_CONN_LIMIT_PORT_'; then
            found=1
        else
            echo "$(localized_text "  未发现 IPv4 脚本规则。" "IPv4 script rule not found." "Правило сценария IPv4 не найдено.")"
        fi
    else
        echo -e "$(localized_text "${YELLOW}IPv4: 未检测到 iptables。${PLAIN}" "${YELLOW}IPv4: iptables not detected.${PLAIN}" "${YELLOW}IPv4: iptables не обнаружен.${PLAIN}")"
    fi

    echo ""
    if command -v ip6tables >/dev/null 2>&1; then
        echo -e "${BOLD}$(localized_text "旧规则 IPv6" "Legacy IPv6" "Старые правила IPv6"):${PLAIN}"
        if ip6tables -S INPUT 2>/dev/null | grep -F 'VPSO_CONN_LIMIT_PORT_'; then
            found=1
        else
            echo "$(localized_text "  未发现 IPv6 脚本规则。" "IPv6 script rule not found." "Правило сценария IPv6 не найдено.")"
        fi
    else
        echo -e "$(localized_text "${YELLOW}IPv6: 未检测到 ip6tables。${PLAIN}" "${YELLOW}IPv6: ip6tables not detected.${PLAIN}" "${YELLOW}IPv6: ip6tables не обнаружен.${PLAIN}")"
    fi

    echo ""
    if [[ "$found" -eq 0 ]]; then
        echo -e "$(localized_text "${BLUE}当前没有检测到本脚本添加的 connlimit 规则。${PLAIN}" "${BLUE}Currently does not detect the connlimit rule added by this script.${PLAIN}" "${BLUE}в настоящее время не обнаруживает правило connlimit, добавленное этим сценарием.${PLAIN}")"
    fi
    echo -e "$(localized_text "${YELLOW}提示：这些规则是连接数限制，不等同于 UFW/firewalld 的端口放行规则。${PLAIN}" "${YELLOW}Tip: These rules are connection number limits and are not equivalent to the port allow rules of UFW/firewalld.${PLAIN}" "${YELLOW}Совет. Эти правила представляют собой ограничения на количество подключений и не эквивалентны правилам освобождения портов UFW/firewalld.${PLAIN}")"
    echo ""
    print_port_connlimit_persistence_status
}

func_show_port_current_connections() {
    local port rows

    read_connlimit_port port || return 0

    if ! command -v ss >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 ss，正在尝试安装 iproute2/iproute...${PLAIN}" "${YELLOW}⚠️ ss not detected, trying to install iproute2/iproute...${PLAIN}" "${YELLOW}⚠️ ss не обнаружен, пытаюсь установить iproute2/iproute...${PLAIN}")"
        install_pkg iproute2 || install_pkg iproute || true
    fi
    if ! command -v ss >/dev/null 2>&1; then
        echo -e "$(localized_text "${RED}❌ 未检测到 ss，无法查看当前连接情况。${PLAIN}" "${RED}❌ ss is not detected and the current connection status cannot be viewed.${PLAIN}" "${RED}❌ ss не обнаружен и текущий статус подключения просмотреть невозможно.${PLAIN}")"
        return 1
    fi

    print_port_connlimit_scope_notice "$port"
    echo -e "$(localized_text "${CYAN}端口 ${port} 当前 ESTABLISHED TCP 连接按来源 IP 统计：${PLAIN}" "${CYAN}Port ${port} Current ESTABLISHED TCP Connection by Source IP Statistics:${PLAIN}" "${CYAN}Порт ${port} Текущий УСТАНОВЛЕН TCP Соединение по IP-статистике источника:${PLAIN}")"
    rows=$(ss -Htan state established 2>/dev/null | awk -v port="$port" '
        function is_local_port(endpoint) {
            return endpoint ~ (":" port "$") || endpoint ~ ("\\]:" port "$")
        }
        function remote_ip(endpoint) {
            if (endpoint ~ /^\[/) {
                sub(/^\[/, "", endpoint)
                sub(/\]:[0-9]+$/, "", endpoint)
                return endpoint
            }
            sub(/:[0-9]+$/, "", endpoint)
            return endpoint
        }
        is_local_port($4) {
            print remote_ip($5)
        }
    ' | sort | uniq -c | sort -nr)

    if [[ -z "$rows" ]]; then
        echo "$(localized_text "  当前没有 ESTABLISHED 连接。" "There are currently no ESTABLISHED connections." "В настоящее время нет УСТАНОВЛЕННЫХ соединений.")"
    else
        printf '%s\n' "$rows" | awk '{count=$1; $1=""; sub(/^ /, ""); printf "  %-45s %s\n", $0, count}'
    fi
}

show_firewall_menu_help() {
    echo "$(localized_text "防火墙菜单用于放行、删除、查看或关闭系统防火墙规则。删除规则和关闭防火墙都必须输入 yes 确认，大小写均可。" "The firewall menu is used to release, delete, view or close system firewall rules. To delete rules and turn off the firewall, you must enter yes to confirm, in both upper and lower case letters." "Меню брандмауэра используется для освобождения, удаления, просмотра или закрытия правил системного брандмауэра. Чтобы удалить правила и отключить брандмауэр, для подтверждения необходимо ввести «да» как заглавными, так и строчными буквами.")"
    echo "$(localized_text "自动放行会生成最小权限计划，展示协议、监听地址、进程和 Docker 映射；回环监听不会放行，当前 SSH 端口不能排除。" "automatic allow rules will generate a minimum privilege plan, showing the protocol, listening address, process and Docker mapping; loopback listening will not be released, and the current SSH port cannot be excluded." "При автоматическом выпуске будет создан план минимальных привилегий, показывающий протокол, адрес прослушивания, процесс и сопоставление Docker; Loopback-прослушивание не будет активирован, и текущий порт SSH не может быть исключен.")"
    echo "$(localized_text "计划只代表当前公网监听和 Docker 发布端口，不能判断业务是否仍需对外开放；可按编号排除非必要规则，确认后才应用。" "The plan only represents the current public listening and Docker publishing ports, and cannot determine whether the business still needs to be open to the outside world; unnecessary rules can be excluded by number and applied after confirmation." "План представляет только текущий прослушивание публичной сети и порты публикации Docker и не может определить, нужно ли по-прежнему бизнесу быть открытым для внешнего мира; ненужные правила можно исключить по количеству и применить после подтверждения.")"
    echo "$(localized_text "Docker 映射可能绕过普通 UFW/firewalld 端口规则；排除计划项不会关闭容器映射，需要同时修改 Docker 发布地址或使用 Docker 管理。" "Docker port publishing may bypass ordinary UFW/firewalld rules; excluding a plan item does not close a published container port. Change the publish address or use Docker Management." "Публикация портов Docker может обходить правила UFW/firewalld; исключение пункта плана не закрывает опубликованный порт. Измените адрес публикации или используйте управление Docker.")"
    echo "$(localized_text "手动添加默认只放行 TCP，可明确选择 udp 或 both。删除旧规则默认同时检查 TCP/UDP。" "Manually adding only TCP is allowed by default, you can explicitly select udp or both. Deleting old rules also checks TCP/UDP by default." "По умолчанию разрешено добавление только TCP вручную, вы можете явно выбрать udp или оба. При удалении старых правил также по умолчанию проверяется TCP/UDP.")"
    echo "$(localized_text "端口并发连接限制优先使用 nftables ct count；不支持时回退到 iptables/ip6tables connlimit。" "Port concurrency limits prefer nftables ct count and fall back to iptables/ip6tables connlimit when unavailable." "Ограничение подключений предпочитает nftables ct count и при недоступности переходит на iptables/ip6tables connlimit.")"
    echo "$(localized_text "该限制是额外连接数限制规则，不等同于 UFW/firewalld 的端口放行规则；两者可能并存。" "This restriction is an additional connection limit rule and is not equivalent to the UFW/firewalld port access rule; the two may coexist." "Это ограничение является дополнительным правилом ограничения подключений и не эквивалентно правилу освобождения порта UFW/firewalld; они могут сосуществовать.")"
    echo "$(localized_text "添加/删除 connlimit 后会自动尝试刷新持久化快照；[5] 可手动检查或再次保存。系统不支持时会提示当前规则只在本次运行期生效。" "After adding/removing connlimit, it will automatically try to refresh the persistent snapshot; [5] it can be checked manually or saved again. If the system does not support it, it will prompt that the current rule will only take effect during this running period." "После добавления/удаления connlimit он автоматически попытается обновить постоянный снимок; [5] его можно проверить вручную или сохранить снова. Если система его не поддерживает, она предложит, что текущее правило вступит в силу только в течение этого периода работы.")"
    echo "$(localized_text "如果限制公网 443 且当前启用了 443端口复用/端口复用，限制粒度只能是整个公网 443，不能精准到某个入站、SNI、UUID 或用户。" "If public port 443 is restricted and Port 443 Reuse/port reuse is currently enabled, the restriction granularity can only be the entire public port 443, and cannot be precise to a specific inbound connection, SNI, UUID, or user." "Если публичный порт 443 ограничена и в настоящее время включено повторное использование одной записи/порта 443, степень детализации ограничения может охватывать только всю публичный порт 443 и не может быть точной для конкретного входящего подключения, SNI, UUID или пользователя.")"
}

func_port_connlimit_menu() {
    while true; do
