normalize_site_stack_arrays() {
    SITE_DOMAINS=()
    SITE_BACKEND_ADDRS=()
    SITE_BACKEND_PORTS=()

    if [[ -n "${SITE_DOMAINS_CSV:-}" ]]; then
        split_csv_to_array "$SITE_DOMAINS_CSV" SITE_DOMAINS
        split_csv_to_array "${SITE_BACKEND_ADDRS_CSV:-}" SITE_BACKEND_ADDRS
        split_csv_to_array "${SITE_BACKEND_PORTS_CSV:-}" SITE_BACKEND_PORTS
    elif [[ -n "${SITE_DOMAIN:-}" ]]; then
        SITE_DOMAINS=("$SITE_DOMAIN")
        SITE_BACKEND_ADDRS=("${SITE_BACKEND_ADDR:-127.0.0.1}")
        SITE_BACKEND_PORTS=("${SITE_BACKEND_PORT:-3000}")
    fi

    local i default_port
    default_port=3000
    for i in "${!SITE_DOMAINS[@]}"; do
        SITE_DOMAINS[$i]=$(normalize_domain_input "${SITE_DOMAINS[$i]}")
        SITE_BACKEND_ADDRS[$i]="${SITE_BACKEND_ADDRS[$i]:-127.0.0.1}"
        if [[ -z "${SITE_BACKEND_PORTS[$i]:-}" ]]; then
            if [[ "$i" -eq 0 && -n "${SITE_BACKEND_PORT:-}" ]]; then
                SITE_BACKEND_PORTS[$i]="$SITE_BACKEND_PORT"
            else
                SITE_BACKEND_PORTS[$i]="$default_port"
            fi
        fi
        SITE_BACKEND_ADDRS[$i]=$(normalize_backend_addr_input "${SITE_BACKEND_ADDRS[$i]}")
        SITE_BACKEND_PORTS[$i]=$(normalize_port_input "${SITE_BACKEND_PORTS[$i]}")
        default_port=$((default_port + 1))
    done

    SITE_DOMAIN="${SITE_DOMAINS[0]:-}"
    SITE_BACKEND_ADDR="${SITE_BACKEND_ADDRS[0]:-127.0.0.1}"
    SITE_BACKEND_PORT="${SITE_BACKEND_PORTS[0]:-3000}"
}

normalize_tcp_route_arrays() {
    local -a raw_snis=()
    local -a raw_addrs=()
    local -a raw_ports=()
    local -a clean_snis=()
    local -a clean_addrs=()
    local -a clean_ports=()
    local i sni addr port

    if [[ -n "${TCP_ROUTE_SNIS_CSV:-}" ]]; then
        split_csv_to_array "$TCP_ROUTE_SNIS_CSV" raw_snis
        split_csv_to_array "${TCP_ROUTE_ADDRS_CSV:-}" raw_addrs
        split_csv_to_array "${TCP_ROUTE_PORTS_CSV:-}" raw_ports
    fi

    for i in "${!raw_snis[@]}"; do
        sni=$(normalize_domain_input "${raw_snis[$i]}")
        addr=$(normalize_loopback_addr "$(normalize_ip_input "${raw_addrs[$i]:-127.0.0.1}")")
        port=$(normalize_port_input "${raw_ports[$i]:-8443}")
        if is_valid_domain "$sni" && is_loopback_listen_addr "$addr" && is_valid_port "$port"; then
            clean_snis+=("$sni")
            clean_addrs+=("$addr")
            clean_ports+=("$port")
        fi
    done

    TCP_ROUTE_SNIS=("${clean_snis[@]}")
    TCP_ROUTE_ADDRS=("${clean_addrs[@]}")
    TCP_ROUTE_PORTS=("${clean_ports[@]}")
}

xray_sni_routes_path() {
    echo "/etc/vps-optimize/xray-sni-routes.conf"
}

load_xray_sni_route_arrays() {
    local route_file line sni addr port
    route_file=$(xray_sni_routes_path)
    XRAY_SNI_ROUTE_SNIS=()
    XRAY_SNI_ROUTE_ADDRS=()
    XRAY_SNI_ROUTE_PORTS=()

    [[ -f "$route_file" ]] || return 0
    while IFS= read -r line || [[ -n "$line" ]]; do
        line="${line%%#*}"
        [[ -n "$(trim_input "$line")" ]] || continue
        IFS='|' read -r sni addr port _ <<< "$line"
        sni=$(normalize_domain_input "$sni")
        addr=$(normalize_loopback_addr "${addr:-127.0.0.1}")
        port="$(trim_input "${port:-}")"
        if is_valid_domain "$sni" && is_loopback_listen_addr "$addr" && is_valid_port "$port"; then
            XRAY_SNI_ROUTE_SNIS+=("$sni")
            XRAY_SNI_ROUTE_ADDRS+=("$addr")
            XRAY_SNI_ROUTE_PORTS+=("$port")
        fi
    done < "$route_file"
}

save_xray_sni_route_arrays() {
    local route_file i
    route_file=$(xray_sni_routes_path)
    mkdir -p "$(dirname "$route_file")"
    : > "$route_file"
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ -n "${XRAY_SNI_ROUTE_SNIS[$i]:-}" ]] || continue
        printf '%s|%s|%s\n' "${XRAY_SNI_ROUTE_SNIS[$i]}" "${XRAY_SNI_ROUTE_ADDRS[$i]}" "${XRAY_SNI_ROUTE_PORTS[$i]}" >> "$route_file"
    done
    chmod 600 "$route_file" 2>/dev/null || true
}

xray_sni_route_index() {
    local sni="$1"
    local i
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$sni" == "${XRAY_SNI_ROUTE_SNIS[$i]}" ]] && { echo "$i"; return 0; }
    done
    return 1
}

xray_fallback_main_route_index() {
    local i
    if [[ -n "${XRAY_FALLBACK_MAIN_SNI:-}" ]]; then
        for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            [[ "$XRAY_FALLBACK_MAIN_SNI" == "${XRAY_SNI_ROUTE_SNIS[$i]}" ]] && { echo "$i"; return 0; }
        done
    fi
    if [[ -n "${XRAY_FALLBACK_MAIN_ADDR:-}" && -n "${XRAY_FALLBACK_MAIN_PORT:-}" ]]; then
        for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            if [[ "$XRAY_FALLBACK_MAIN_ADDR" == "${XRAY_SNI_ROUTE_ADDRS[$i]}" && "$XRAY_FALLBACK_MAIN_PORT" == "${XRAY_SNI_ROUTE_PORTS[$i]}" ]]; then
                echo "$i"
                return 0
            fi
        done
    fi
    if [[ "$(get_entry_mode)" == "xray-fallback" && -n "${XRAY_LISTEN_ADDR:-}" && -n "${XRAY_LISTEN_PORT:-}" ]]; then
        for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            if [[ "$XRAY_LISTEN_ADDR" == "${XRAY_SNI_ROUTE_ADDRS[$i]}" && "$XRAY_LISTEN_PORT" == "${XRAY_SNI_ROUTE_PORTS[$i]}" ]]; then
                echo "$i"
                return 0
            fi
        done
    fi
    return 1
}

set_xray_fallback_main_route_from_index() {
    local idx="$1"
    [[ "$idx" =~ ^[0-9]+$ ]] || return 1
    (( idx >= 0 && idx < ${#XRAY_SNI_ROUTE_SNIS[@]} )) || return 1
    XRAY_FALLBACK_MAIN_SNI="${XRAY_SNI_ROUTE_SNIS[$idx]}"
    XRAY_FALLBACK_MAIN_ADDR="${XRAY_SNI_ROUTE_ADDRS[$idx]}"
    XRAY_FALLBACK_MAIN_PORT="${XRAY_SNI_ROUTE_PORTS[$idx]}"
}

print_xray_fallback_mode_explanation() {
    echo -e "$(localized_text "${YELLOW}Xray 本身可以有多个入站。但在 xray-fallback 模式下，公网 443 默认由一个 Xray 主入站接管。脚本暂不支持在该模式下继续按多个 SNI 分流到多个本地 Xray 入站。${PLAIN}" "${YELLOW}Xray itself can have multiple inbounds. But in xray-fallback mode, public port 443 is taken over by a Xray main inbound by default. The script currently does not support continuing to routing multiple SNI to multiple local Xray inbound in this mode.${PLAIN}" "${YELLOW}Xray сам по себе может иметь несколько входящих подключений. Но в резервном режиме xray публичный порт 443 по умолчанию перехватывается основным входящим подключением Xray. В настоящее время сценарий не поддерживает продолжение перенаправления нескольких SNI на несколько локальных входящих Xray в этом режиме.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}该模式只负责 Xray 主入站监听公网 443，并 fallback 普通 HTTPS 到所选 Web 反代引擎。${PLAIN}" "${YELLOW}This mode is only responsible for Xray's main inbound listening of public port 443, and fallback normal HTTPS to the selected Web reverse proxy engine.${PLAIN}" "${YELLOW}Этот режим отвечает только за основной входящий прослушивание Xray публичного порта 443 и возврат обычного HTTPS к выбранному механизму веб-прокси.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}如需多个本地 Xray 入站通过 443 按 SNI 分流，请使用 Nginx Stream 模式或 TCP Peek + Splice 模式。${PLAIN}" "${YELLOW}If you need multiple local Xray inbound pass 443 split by SNI, please use Nginx Stream mode or TCP Peek + Splice mode.${PLAIN}" "${YELLOW}Если вам нужно несколько локальных входящих проходов Xray 443, разделенных на SNI, используйте режим Nginx Stream или режим TCP Peek + Splice.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}如果 Web 域名开启 CDN/WAF/源站保护/Cloudflare 回源限制/Web 白名单，403 或拒绝访问通常是 Web/CDN/白名单/SNI 策略阻断，不一定是证书或反代引擎故障。${PLAIN}" "${YELLOW}If the Web domain has CDN/WAF/origin protection/Cloudflare return-to-origin restriction/Web whitelist, 403 or access denied is usually blocked by the Web/CDN/whitelist/SNI policy, and is not necessarily a certificate or reverse proxy engine failure.${PLAIN}" "${YELLOW}Если имя веб-домена имеет CDN/WAF/защиту исходного сайта/ограничения исходного сайта серверной части подключения Cloudflare/белый список веб-сайтов, 403 или отказ в доступе обычно блокируется политикой Интернета/CDN/белого списка/SNI и не обязательно является сбоем сертификата или механизма обратного прокси-сервера.${PLAIN}")"
}

print_xray_fallback_main_route_summary() {
    local idx
    idx=$(xray_fallback_main_route_index 2>/dev/null || true)
    if [[ -n "$idx" ]]; then
        echo -e "$(localized_text "${GREEN}当前 xray-fallback 主入站：${XRAY_SNI_ROUTE_SNIS[$idx]} -> ${XRAY_SNI_ROUTE_ADDRS[$idx]}:${XRAY_SNI_ROUTE_PORTS[$idx]}${PLAIN}" "${GREEN}Current xray-fallback main inbound: ${XRAY_SNI_ROUTE_SNIS[$idx]} -> ${XRAY_SNI_ROUTE_ADDRS[$idx]}:${XRAY_SNI_ROUTE_PORTS[$idx]}${PLAIN}" "${GREEN}текущий xray-резервный основной входящий: ${XRAY_SNI_ROUTE_SNIS[$idx]} -> ${XRAY_SNI_ROUTE_ADDRS[$idx]}:${XRAY_SNI_ROUTE_PORTS[$idx]}${PLAIN}")"
    elif [[ -n "${XRAY_FALLBACK_MAIN_SNI:-}" ]]; then
        echo -e "$(localized_text "${YELLOW}当前 xray-fallback 主入站记录：${XRAY_FALLBACK_MAIN_SNI} -> ${XRAY_FALLBACK_MAIN_ADDR:-?}:${XRAY_FALLBACK_MAIN_PORT:-?}，但未匹配到现有规则。${PLAIN}" "${YELLOW}Current xray-fallback main inbound record: ${XRAY_FALLBACK_MAIN_SNI} -> ${XRAY_FALLBACK_MAIN_ADDR:-?}:${XRAY_FALLBACK_MAIN_PORT:-?}, but no existing rules are matched.${PLAIN}" "${YELLOW}Текущая основная входящая резервная запись xray: ${XRAY_FALLBACK_MAIN_SNI} -> ${XRAY_FALLBACK_MAIN_ADDR:-?}:${XRAY_FALLBACK_MAIN_PORT:-?}, но ни одно существующее правило не соответствует.${PLAIN}")"
    elif [[ "$(get_entry_mode)" == "xray-fallback" ]]; then
        echo -e "$(localized_text "${YELLOW}当前未记录 xray-fallback 主入站；请确认 Xray 主入站已按当前模式监听公网 443。${PLAIN}" "${YELLOW}Is currently not recorded. xray-fallback main inbound; please confirm that Xray main inbound is listening on the public in the current mode 443.${PLAIN}" "${YELLOW}в настоящее время не записан. xray-резервный основной входящий; пожалуйста, подтвердите, что основное входящее подключение Xray прослушивает публичную сеть в текущем режиме 443.${PLAIN}")"
    fi
}

select_xray_fallback_main_route_for_switch() {
    load_sni_stack_env || return 1
    local count choice idx
    count=${#XRAY_SNI_ROUTE_SNIS[@]}

    if [[ "$count" -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}未找到 $(xray_sni_routes_path) 中的 Xray 入站分流规则。${PLAIN}" "${YELLOW}Did not find the Xray inbound routing rule in $(xray_sni_routes_path).${PLAIN}" "${YELLOW}Правило маршрутизации входящего подключения Xray не найдено в $(xray_sni_routes_path).${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}切换到 xray-fallback 时，将由用户已配置的 Xray 主入站接管公网 443；脚本不会修改 3x-ui/Xray 入站内部配置。${PLAIN}" "${YELLOW}When switching to xray-fallback, the Xray main inbound configured by the user will take over the public port 443; the script will not modify the 3x-ui/Xray inbound internal configuration.${PLAIN}" "${YELLOW}Когда  переключается на резервный xray, публичный порт 443 будет занят настраиваемым пользователем основным входящим соединением Xray; сценарий не будет изменять внутреннюю конфигурацию входящего соединения 3x-ui/Xray.${PLAIN}")"
        confirm_risk_action "$(localized_text "继续切换到 xray-fallback" "Continue to switch to xray-fallback" "Продолжить переход на резервный вариант xray.")" \
            "$(localized_text "公网 443 将由 Xray 主入站接管，普通 HTTPS fallback 到所选 Web 反代引擎" "public port 443 will be taken over by Xray main inbound, and ordinary HTTPS fallback to the selected web reverse proxy engine" "Публичная сеть 443 будет занята основным входящим подключением Xray и обычным резервным HTTPS для выбранного механизма веб-прокси.")" \
            "$(localized_text "取消切换，先在 Xray 入站管理中记录一个主入站候选" "To cancel the switch, first record a primary inbound candidate in Xray inbound management" "Чтобы отменить переключение, сначала запишите кандидата на роль основного входящего подключения в системе управления входящими подключениями Xray.")" \
            "$(localized_text "确认你已经在 3x-ui/Xray 中准备好将作为主入站的配置。" "Confirm that you have prepared the configuration in 3x-ui/Xray that will serve as the primary inbound." "Подтвердите, что вы подготовили конфигурацию в 3x-ui/Xray, которая будет служить основным входящим подключением.")" || return 1
        XRAY_FALLBACK_MAIN_SNI=""
        XRAY_FALLBACK_MAIN_ADDR=""
        XRAY_FALLBACK_MAIN_PORT=""
        return 0
    fi

    print_xray_fallback_mode_explanation
    echo -e "------------------------------------------------"
    if [[ "$count" -eq 1 ]]; then
        echo -e "$(localized_text "${CYAN}检测到 1 条 Xray 入站分流规则，可作为 xray-fallback 主入站候选：${PLAIN}" "${CYAN}Detects 1 Xray inbound routing rule, which can be used as the xray-fallback main inbound candidate:${PLAIN}" "${CYAN}Обнаружено одно правило маршрутизации входящего подключения Xray, которое можно использовать в качестве основного входящего кандидата для xray:${PLAIN}")"
        echo -e "1. ${XRAY_SNI_ROUTE_SNIS[0]} -> ${XRAY_SNI_ROUTE_ADDRS[0]}:${XRAY_SNI_ROUTE_PORTS[0]}"
        confirm_risk_action "$(localized_text "使用该规则作为 xray-fallback 主入站候选" "Use this rule as the xray-fallback primary inbound candidate" "Используйте это правило в качестве резервного основного входящего кандидата xray.")" \
            "$(localized_text "该规则会被记录为 xray-fallback 主入站；其他模式下仍按 xray-sni-routes.conf 正常分流" "This rule will be recorded as xray-fallback main inbound; in other modes, it will still be distributed normally according to xray-sni-routes.conf" "Это правило будет записано как основной входящий xray-резервный; в остальных режимах всё равно будет нормально раздаваться согласно xray-sni-routes.conf")" \
            "$(localized_text "取消切换，先确认 3x-ui/Xray 主入站配置" "To cancel the switch, first confirm the 3x-ui/Xray main inbound configuration" "Чтобы отменить переключение, сначала подтвердите основную входящую конфигурацию 3x-ui/Xray.")" \
            "$(localized_text "确认该本地入站就是你希望在 xray-fallback 模式下接管公网 443 的主入站。" "Confirm that this local inbound is the primary inbound that you want to take over public port 443 in xray-fallback mode." "Подтвердите, что это локальное входящее подключение является основным входящим подключением, который вы хотите использовать для публичного порта 443 в резервном режиме xray.")" || return 1
        set_xray_fallback_main_route_from_index 0
        return 0
    fi

    echo -e "$(localized_text "${CYAN}检测到多条 Xray 入站分流规则，请选择其中一条作为 xray-fallback 主入站：${PLAIN}" "${CYAN}Detects multiple Xray inbound routing rules, please select one of them as the xray-fallback main inbound:${PLAIN}" "${CYAN}обнаруживает несколько правил маршрутизация входящего подключения Xray. Выберите одно из них в качестве резервного основного входящего подключения xray:.${PLAIN}")"
    for idx in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        echo -e "${GREEN}$((idx + 1)).${PLAIN} ${XRAY_SNI_ROUTE_SNIS[$idx]} -> ${XRAY_SNI_ROUTE_ADDRS[$idx]}:${XRAY_SNI_ROUTE_PORTS[$idx]}"
    done
    echo -e "$(localized_text "${RED}0. 取消切换${PLAIN}" "${RED}0. Cancel switching${PLAIN}" "${RED}0. Отменить переключение${PLAIN}")"
    read_trimmed choice "$(localized_text "请选择 xray-fallback 主入站候选: " "Please select xray-fallback primary inbound candidate:" "Пожалуйста, выберите xray-резервный основной входящий кандидат:")"
    if [[ -z "$choice" || "$choice" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消切换到 xray-fallback。${PLAIN}" "${BLUE}Canceled the switch to xray-fallback.${PLAIN}" "${BLUE}отменил переход на резервный вариант xray.${PLAIN}")"
        return 1
    fi
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > count )); then
        echo -e "$(localized_text "${RED}❌ 序号无效，已取消切换。${PLAIN}" "${RED}❌ The serial number is invalid and the switching has been cancelled.${PLAIN}" "${RED}❌ Серийный номер недействителен, переключение отменено.${PLAIN}")"
        return 1
    fi
    set_xray_fallback_main_route_from_index "$((choice - 1))" || return 1
    echo -e "$(localized_text "${GREEN}✅ 已选择 xray-fallback 主入站候选：${XRAY_FALLBACK_MAIN_SNI} -> ${XRAY_FALLBACK_MAIN_ADDR}:${XRAY_FALLBACK_MAIN_PORT}${PLAIN}" "${GREEN}✅ xray-fallback main inbound candidate selected: ${XRAY_FALLBACK_MAIN_SNI} -> ${XRAY_FALLBACK_MAIN_ADDR}:${XRAY_FALLBACK_MAIN_PORT}${PLAIN}" "${GREEN}✅ xray — выбран резервный основной входящий кандидат: ${XRAY_FALLBACK_MAIN_SNI} -> ${XRAY_FALLBACK_MAIN_ADDR}:${XRAY_FALLBACK_MAIN_PORT}${PLAIN}")"
}

xray_sni_route_port_conflict() {
    local addr="$1"
    local port="$2"
    local skip_idx="${3:-}"
    local i
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ -n "$skip_idx" && "$i" == "$skip_idx" ]] && continue
        if [[ "$addr" == "${XRAY_SNI_ROUTE_ADDRS[$i]}" && "$port" == "${XRAY_SNI_ROUTE_PORTS[$i]}" ]]; then
            echo "${XRAY_SNI_ROUTE_SNIS[$i]}"
            return 0
        fi
    done
    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        if [[ "$addr" == "${TCP_ROUTE_ADDRS[$i]}" && "$port" == "${TCP_ROUTE_PORTS[$i]}" ]]; then
            echo "$(localized_text "旧 TCP/SNI:${TCP_ROUTE_SNIS[$i]}" "Old TCP/SNI:${TCP_ROUTE_SNIS[$i]}" "Старый TCP/SNI:${TCP_ROUTE_SNIS[$i]}")"
            return 0
        fi
    done
    return 1
}

xray_route_listen_line_by_addr_port() {
    local addr="$1"
    local port="$2"
    local host_regex
    case "$addr" in
        "127.0.0.1") host_regex='(127\.0\.0\.1|0\.0\.0\.0|\*)' ;;
        "::1") host_regex='(\[::1\]|\[::\]|\*)' ;;
        "localhost") host_regex='(127\.0\.0\.1|0\.0\.0\.0|\[::1\]|\[::\]|\*)' ;;
        *) host_regex=$(printf '%s' "$addr" | sed 's/[.[\*^$()+?{}|\\]/\\&/g') ;;
    esac
    ss -lntp 2>/dev/null | grep -E "${host_regex}:${port}[[:space:]]" | head -n1 || true
}

print_xray_route_port_status() {
    local sni="$1"
    local addr="$2"
    local port="$3"
    local line conflict

    echo -e "${CYAN}${sni}${PLAIN} -> ${addr}:${port}"
    if [[ "${CADDY_LISTEN_PORT:-}" == "$port" ]]; then
        echo -e "$(localized_text "${RED}  ❌ 与 Web 反代引擎本地端口 ${CADDY_LISTEN_PORT} 冲突，请换一个本地入站端口。${PLAIN}" "${RED}❌ Conflicts with the local port ${CADDY_LISTEN_PORT} of the Web reverse proxy engine. Please change the local inbound port.${PLAIN}" "${RED}❌ Конфликты с локальным портом ${CADDY_LISTEN_PORT} механизма веб-прокси. Пожалуйста, измените локальный входящий порт.${PLAIN}")"
    fi

    conflict=$(xray_sni_route_port_conflict "$addr" "$port" "$(xray_sni_route_index "$sni" 2>/dev/null || true)" || true)
    [[ -n "$conflict" ]] && echo -e "$(localized_text "${YELLOW}  ⚠️ 与规则 ${conflict} 使用了相同的 ${addr}:${port}，请确认是否故意复用。${PLAIN}" "${YELLOW}⚠️ Uses the same ${addr}:${port} as rule ${conflict}. Please confirm whether it is reused intentionally.${PLAIN}" "${YELLOW}⚠️ Использует тот же ${addr}:${port}, что и правило ${conflict}. Пожалуйста, подтвердите, намеренно ли он используется повторно.${PLAIN}")"

    line=$(xray_route_listen_line_by_addr_port "$addr" "$port")
    if [[ -n "$line" ]]; then
        echo -e "$(localized_text "${GREEN}  ✅ 端口已监听：${line}${PLAIN}" "${GREEN}✅ Port is listening: ${line}${PLAIN}" "${GREEN}✅ Порт прослушивается: ${line}${PLAIN}")"
        if echo "$line" | grep -Eq '(^|[[:space:]])(0\.0\.0\.0|\*|\[::\]):'"${port}"'[[:space:]]'; then
            echo -e "$(localized_text "${YELLOW}  ⚠️ 检测到可能监听在 0.0.0.0/[::]，存在公网暴露风险，建议改为 127.0.0.1。${PLAIN}" "${YELLOW}⚠️ Detected that it may be monitored at 0.0.0.0/[::], which is a risk of Internet exposure. It is recommended to change it to 127.0.0.1.${PLAIN}" "${YELLOW}⚠️ Обнаружено, что его можно отслеживать по адресу 0.0.0.0/[::]. Существует риск публичного доступа. Рекомендуется изменить его на 127.0.0.1.${PLAIN}")"
        fi
    else
        echo -e "$(localized_text "${YELLOW}  ⚠️ 未检测到 ${addr}:${port} 监听，请先去 3x-ui 创建并启用对应入站。${PLAIN}" "${YELLOW}⚠️ The ${addr}:${port} monitor is not detected. Please go to 3x-ui first to create and enable the corresponding inbound connection.${PLAIN}" "${YELLOW}⚠️ Монитор ${addr}:${port} не обнаружен. Сначала перейдите по адресу 3x-ui, чтобы создать и включить соответствующее входящее соединение.${PLAIN}")"
    fi
}

is_sni_stack_managed_domain() {
    local domain="$1"
    local site_domain
    [[ "$domain" == "$PANEL_DOMAIN" ]] && return 0
    for site_domain in "${SITE_DOMAINS[@]}"; do
        [[ "$domain" == "$site_domain" ]] && return 0
    done
    for site_domain in "${TCP_ROUTE_SNIS[@]}"; do
        [[ "$domain" == "$site_domain" ]] && return 0
    done
    for site_domain in "${XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$domain" == "$site_domain" ]] && return 0
    done
    return 1
}

is_sni_stack_web_domain() {
    local domain="$1"
    local site_domain
    [[ "$domain" == "$PANEL_DOMAIN" ]] && return 0
    for site_domain in "${SITE_DOMAINS[@]}"; do
        [[ "$domain" == "$site_domain" ]] && return 0
    done
    return 1
}

nginx_var_suffix_for_domain() {
    local domain="$1"
    domain=$(echo "$domain" | tr '.-' '__' | tr -cd 'a-zA-Z0-9_')
    printf '%s' "$domain"
}

normalize_sni_ip_whitelist_arrays() {
    local domains_input="${SNI_IP_WHITELIST_DOMAINS_CSV:-}"
    local ranges_input="${SNI_IP_WHITELIST_RANGES_PIPE:-}"
    local -a raw_domains=()
    local -a raw_ranges=()
    local -a clean_domains=()
    local -a clean_ranges=()
    local -a range_array=()
    local i domain ranges

    SNI_IP_WHITELIST_DOMAINS=()
    SNI_IP_WHITELIST_RANGES=()

    [[ -n "$domains_input" ]] && split_csv_to_array "$domains_input" raw_domains
    [[ -n "$ranges_input" ]] && split_pipe_to_array "$ranges_input" raw_ranges

    for i in "${!raw_domains[@]}"; do
        domain=$(normalize_domain_input "${raw_domains[$i]}")
        ranges="${raw_ranges[$i]:-}"
        [[ -n "$domain" && -n "$ranges" ]] || continue
        is_valid_domain "$domain" || continue
        is_sni_stack_web_domain "$domain" || continue
        if normalize_ip_whitelist_input "$ranges" range_array; then
            clean_domains+=("$domain")
            clean_ranges+=("$(join_array_by_space "${range_array[@]}")")
        fi
    done

    SNI_IP_WHITELIST_DOMAINS=("${clean_domains[@]}")
    SNI_IP_WHITELIST_RANGES=("${clean_ranges[@]}")
}

sni_ip_whitelist_index() {
    local domain="$1"
    local i
    for i in "${!SNI_IP_WHITELIST_DOMAINS[@]}"; do
        [[ "$domain" == "${SNI_IP_WHITELIST_DOMAINS[$i]}" ]] && { echo "$i"; return 0; }
    done
    return 1
}

sni_ip_whitelist_ranges_for_domain() {
    local domain="$1"
    local idx
    idx=$(sni_ip_whitelist_index "$domain" 2>/dev/null) || return 0
    echo "${SNI_IP_WHITELIST_RANGES[$idx]:-}"
}

set_sni_ip_whitelist_for_domain() {
    local domain="$1"
    local ranges="$2"
    local idx
    idx=$(sni_ip_whitelist_index "$domain" 2>/dev/null) || idx=""
    if [[ -n "$idx" ]]; then
        SNI_IP_WHITELIST_RANGES[$idx]="$ranges"
    else
        SNI_IP_WHITELIST_DOMAINS+=("$domain")
        SNI_IP_WHITELIST_RANGES+=("$ranges")
    fi
}

remove_sni_ip_whitelist_for_domain() {
    local domain="$1"
    local i
    local -a new_domains=()
    local -a new_ranges=()
    for i in "${!SNI_IP_WHITELIST_DOMAINS[@]}"; do
        [[ "$domain" == "${SNI_IP_WHITELIST_DOMAINS[$i]}" ]] && continue
        new_domains+=("${SNI_IP_WHITELIST_DOMAINS[$i]}")
        new_ranges+=("${SNI_IP_WHITELIST_RANGES[$i]}")
    done
    SNI_IP_WHITELIST_DOMAINS=("${new_domains[@]}")
    SNI_IP_WHITELIST_RANGES=("${new_ranges[@]}")
}

rename_sni_ip_whitelist_domain() {
    local old_domain="$1"
    local new_domain="$2"
    local idx
    idx=$(sni_ip_whitelist_index "$old_domain" 2>/dev/null) || return 0
    SNI_IP_WHITELIST_DOMAINS[$idx]="$new_domain"
}

print_sni_ip_whitelist_summary() {
    if [[ ${#SNI_IP_WHITELIST_DOMAINS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "IP 白名单：  未启用" "IP Whitelist: Not enabled" "Белый список IP: не включен")"
        return 0
    fi

    local i
    echo -e "$(localized_text "IP 白名单：" "IP whitelist:" "Белый список IP:")"
    for i in "${!SNI_IP_WHITELIST_DOMAINS[@]}"; do
        echo -e "$(localized_text "  - ${SNI_IP_WHITELIST_DOMAINS[$i]} 仅允许：${SNI_IP_WHITELIST_RANGES[$i]}" "- ${SNI_IP_WHITELIST_DOMAINS[$i]} Only allowed: ${SNI_IP_WHITELIST_RANGES[$i]}" "- ${SNI_IP_WHITELIST_DOMAINS[$i]} Разрешено только: ${SNI_IP_WHITELIST_RANGES[$i]}")"
    done
}

sni_stack_health_check() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🧪 443端口复用链路体检${PLAIN}" "${BOLD}🧪 Port 443 Reuse routing link health check${PLAIN}" "${BOLD}🧪 Проверка маршрутизации повторного использования порта 443${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1

    local current_mode
    current_mode=$(get_entry_mode)
    if [[ "$current_mode" != "nginx-stream" ]]; then
        sni_stack_health_check_enhanced
        return $?
    fi

    local ok=0 warn=0 fail=0
    check_listen() {
        local name="$1"
        local port="$2"
        local expect_addr="$3"
        if ss -lntp 2>/dev/null | grep -q ":${port}[[:space:]]"; then
            local line
            line=$(ss -lntp 2>/dev/null | grep ":${port}[[:space:]]" | head -n1)
            echo -e "$(localized_text "${GREEN}✅ ${name} 端口 ${port} 有监听：${line}${PLAIN}" "${GREEN}✅ ${name} port ${port} is monitored: ${line}${PLAIN}" "${GREEN}✅ ${name} Порт ${port} контролируется: ${line}${PLAIN}")"
            if [[ -n "$expect_addr" ]] && ! echo "$line" | grep -q "$expect_addr"; then
                echo -e "$(localized_text "${YELLOW}⚠️ ${name} 期望监听 ${expect_addr}:${port}，请确认是否被改成公网监听。${PLAIN}" "${YELLOW}⚠️ ${name} is expected to monitor ${expect_addr}:${port}, please confirm whether it has been changed to Internet listening.${PLAIN}" "${YELLOW}⚠️ ${name} планирует отслеживать ${expect_addr}:${port}. Пожалуйста, подтвердите, был ли он изменен на прослушивание публичной сети.${PLAIN}")"
                ((warn++))
            else
                ((ok++))
            fi
        else
            echo -e "$(localized_text "${RED}❌ ${name} 端口 ${port} 未监听。${PLAIN}" "${RED}❌ ${name} Port ${port} is not listening.${PLAIN}" "${RED}❌ ${name} Порт ${port} не прослушивается.${PLAIN}")"
            ((fail++))
        fi
    }
    check_backend() {
        local name="$1"
        local addr="$2"
        local port="$3"
        local probe_rc

        if probe_backend_target "$name" "$addr" "$port"; then
            ((ok++))
            return 0
        fi
        probe_rc=$?
        if [[ "$probe_rc" -eq 2 ]]; then
            ((warn++))
        else
            ((fail++))
        fi
    }

    check_listen "$(localized_text "Nginx 公网入口" "Nginx public entry" "Nginx вход в публичную сеть")" "$NGINX_LISTEN_PORT" ""
    check_listen "$(localized_text "$(web_proxy_engine_label) 本地 TLS" "$(web_proxy_engine_label) local TLS" "$(web_proxy_engine_label) локальный TLS")" "$CADDY_LISTEN_PORT" "$CADDY_LISTEN_ADDR"
    check_listen "Xray / 3x-ui+Reality" "$XRAY_LISTEN_PORT" "$XRAY_LISTEN_ADDR"
    check_listen "$(localized_text "3x-ui 面板" "3x-ui panel" "Панель 3x-ui")" "$PANEL_LISTEN_PORT" "$PANEL_LISTEN_ADDR"
    check_listen "$(localized_text "3x-ui 订阅" "3x-ui Subscribe" "3x-ui Подписаться")" "$SUB_LISTEN_PORT" "$SUB_LISTEN_ADDR"
    if [[ ${#SITE_DOMAINS[@]} -gt 0 ]]; then
        local i
        for i in "${!SITE_DOMAINS[@]}"; do
            check_backend "$(localized_text "网站后端 ${SITE_DOMAINS[$i]}" "Website backend ${SITE_DOMAINS[$i]}" "бэкенд сайта ${SITE_DOMAINS[$i]}")" "${SITE_BACKEND_ADDRS[$i]}" "${SITE_BACKEND_PORTS[$i]}"
        done
    fi
    if [[ ${#TCP_ROUTE_SNIS[@]} -gt 0 ]]; then
        local tcp_i
        for tcp_i in "${!TCP_ROUTE_SNIS[@]}"; do
            check_listen "$(localized_text "TCP/SNI 入站 ${TCP_ROUTE_SNIS[$tcp_i]}" "TCP/SNI Inbound ${TCP_ROUTE_SNIS[$tcp_i]}" "TCP/SNI Входящий ${TCP_ROUTE_SNIS[$tcp_i]}")" "${TCP_ROUTE_PORTS[$tcp_i]}" "${TCP_ROUTE_ADDRS[$tcp_i]}"
        done
    fi
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -gt 0 ]]; then
        local xray_route_i
        for xray_route_i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            check_listen "$(localized_text "Xray 入站 ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}" "Xray Inbound ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}" "Xray Входящий ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}")" "${XRAY_SNI_ROUTE_PORTS[$xray_route_i]}" "${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}"
        done
    fi

    echo -e "------------------------------------------------"
    if check_xui_cert_settings_for_single_443; then
        ((ok++))
    else
        ((warn++))
    fi

    echo -e "------------------------------------------------"
    if check_domain_dns_sanity "$PANEL_DOMAIN" "$(localized_text "面板域名" "Panel domain" "Доменное имя панели")" "warn"; then
        ((ok++))
    else
        ((warn++))
    fi
    if [[ ${#SITE_DOMAINS[@]} -gt 0 ]]; then
        local dns_site
        for dns_site in "${SITE_DOMAINS[@]}"; do
            [[ -z "$dns_site" ]] && continue
            if check_domain_dns_sanity "$dns_site" "$(localized_text "网站/反代域名" "Website/reverse domain" "Веб-сайт/обратное доменное имя")" "warn"; then
                ((ok++))
            else
                ((warn++))
            fi
        done
    fi
    if [[ ${#TCP_ROUTE_SNIS[@]} -gt 0 ]]; then
        local tcp_sni
        for tcp_sni in "${TCP_ROUTE_SNIS[@]}"; do
            [[ -z "$tcp_sni" ]] && continue
            if check_domain_dns_sanity "$tcp_sni" "$(localized_text "TCP/SNI 入站域名" "TCP/SNI inbound domain" "TCP/SNI имя входящего домена")" "warn"; then
                ((ok++))
            else
                echo -e "$(localized_text "${YELLOW}⚠️ 如果客户端使用服务器 IP 连接并手动指定 SNI，可忽略该 DNS 警告。${PLAIN}" "${YELLOW}⚠️ This DNS warning can be ignored if the client connects using the server IP and manually specifies SNI.${PLAIN}" "${YELLOW}⚠️ Это предупреждение DNS можно игнорировать, если клиент подключается с использованием IP-адреса сервера и вручную указывает SNI.${PLAIN}")"
                ((warn++))
            fi
        done
    fi
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -gt 0 ]]; then
        local xray_route_sni
        for xray_route_sni in "${XRAY_SNI_ROUTE_SNIS[@]}"; do
            [[ -z "$xray_route_sni" ]] && continue
            if check_domain_dns_sanity "$xray_route_sni" "$(localized_text "Xray 入站域名" "Xray inbound domain" "Xray входящее доменное имя")" "warn"; then
                ((ok++))
            else
                echo -e "$(localized_text "${YELLOW}⚠️ 如果客户端使用服务器 IP 连接并手动指定 SNI，可忽略该 DNS 警告。${PLAIN}" "${YELLOW}⚠️ This DNS warning can be ignored if the client connects using the server IP and manually specifies SNI.${PLAIN}" "${YELLOW}⚠️ Это предупреждение DNS можно игнорировать, если клиент подключается с использованием IP-адреса сервера и вручную указывает SNI.${PLAIN}")"
                ((warn++))
            fi
        done
    fi

    echo -e "------------------------------------------------"
    nginx -t >/dev/null 2>&1 && echo -e "$(localized_text "${GREEN}✅ nginx -t 通过${PLAIN}" "${GREEN}✅ nginx -t by${PLAIN}" "${GREEN}✅ nginx -t от${PLAIN}")" && ((ok++)) || { echo -e "$(localized_text "${RED}❌ nginx -t 失败${PLAIN}" "${RED}❌ nginx -t failed${PLAIN}" "${RED}❌ nginx -t не удалось${PLAIN}")"; ((fail++)); }
    if [[ "$(current_web_proxy_engine)" == "caddy" ]]; then
        caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1 && echo -e "$(localized_text "${GREEN}✅ Caddy 配置校验通过${PLAIN}" "${GREEN}✅ Caddy configuration validation passed${PLAIN}" "${GREEN}✅ Проверка конфигурации Caddy пройдена${PLAIN}")" && ((ok++)) || { echo -e "$(localized_text "${RED}❌ Caddy 配置校验失败${PLAIN}" "${RED}❌ Caddy configuration validation failed${PLAIN}" "${RED}❌ Caddy Проверка конфигурации не удалась${PLAIN}")"; ((fail++)); }
    fi
    if grep -Eq '^[[:space:]]*server_tokens[[:space:]]+off;' /etc/nginx/nginx.conf 2>/dev/null; then
        echo -e "$(localized_text "${GREEN}✅ Nginx 已关闭版本号显示 server_tokens off${PLAIN}" "${GREEN}✅ Nginx Version number display has been turned off server_tokens off${PLAIN}" "${GREEN}✅ Nginx Отображение номера версии отключено server_tokens off${PLAIN}")"
        ((ok++))
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 未确认 Nginx server_tokens off，错误页可能显示版本号。${PLAIN}" "${YELLOW}⚠️ Not confirmed Nginx server_tokens off, the error page may display the version number.${PLAIN}" "${YELLOW}⚠️ Не подтверждено. Nginx server_tokens отключен, на странице ошибки может отображаться номер версии.${PLAIN}")"
        ((warn++))
    fi
    if [[ -f /etc/nginx/conf.d/00-vps-default-drop.conf ]]; then
        echo -e "$(localized_text "${GREEN}✅ Nginx 80 默认站点已设置为丢弃连接${PLAIN}" "${GREEN}✅ Nginx 80 The default site has been set to drop connections${PLAIN}" "${GREEN}✅ Nginx 80 Сайт по умолчанию настроен на отбрасывание соединений${PLAIN}")"
        ((ok++))
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 未找到 80 默认丢弃配置，错误域名可能命中默认页。${PLAIN}" "${YELLOW}⚠️ Not found 80 default discard configuration, wrong domain may hit the default page.${PLAIN}" "${YELLOW}⚠️ Не найдено 80. Конфигурация отмены по умолчанию, неправильное доменное имя может попасть на страницу по умолчанию.${PLAIN}")"
        ((warn++))
    fi

    if command -v openssl >/dev/null 2>&1; then
        if timeout 10 openssl s_client -connect "127.0.0.1:${NGINX_LISTEN_PORT}" -servername "$PANEL_DOMAIN" </dev/null 2>/dev/null | grep -q "BEGIN CERTIFICATE"; then
            echo -e "$(localized_text "${GREEN}✅ 面板 SNI 可从入口命中 Web 反代引擎证书链${PLAIN}" "${GREEN}✅ Panel SNI can hit the Web reverse proxy engine certificate chain from the entry${PLAIN}" "${GREEN}✅ Панель SNI может попасть в цепочку сертификатов механизма обратного веб-прокси  со входа.${PLAIN}")"
            ((ok++))
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 面板 SNI 测试未拿到证书，请检查入口模式与 Web 反代引擎。${PLAIN}" "${YELLOW}⚠️ Panel SNI test did not get the certificate, please check the entry mode and Web reverse proxy engine.${PLAIN}" "${YELLOW}⚠️ Тест панели SNI не получил сертификат, проверьте режим входа и механизм веб-прокси.${PLAIN}")"
            ((warn++))
        fi
    fi

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "体检结果：${GREEN}通过 ${ok}${PLAIN} / ${YELLOW}警告 ${warn}${PLAIN} / ${RED}失败 ${fail}${PLAIN}" "health check results: ${GREEN}Passed ${ok}${PLAIN} / ${YELLOW}Warning ${warn}${PLAIN} / ${RED}Failed ${fail}${PLAIN}" "Результаты медицинского осмотра: ${GREEN}прошел ${ok}${PLAIN} / ${YELLOW}предупреждение ${warn}${PLAIN} / ${RED}не прошел ${fail}${PLAIN}")"
}

# ---------------------------------------------------------
# Module: vpso_mux_state.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# vpso-mux paths, engine state, route summaries, and runtime status output.

vpso_mux_config_path() {
    echo "/etc/vps-optimize/vpso-mux.yaml"
}

vpso_mux_service_name() {
    echo "vpso-mux.service"
}

vpso_mux_status_json_path() {
    echo "/var/lib/vps-optimize/vpso-mux/status.json"
}

single_443_engine_state_path() {
    echo "/etc/vps-optimize/443-engine.conf"
}

yaml_quote() {
    local value="$1"
    value=$(printf '%s' "$value" | sed "s/'/''/g")
    printf "'%s'" "$value"
}

single_443_current_engine() {
    local state_file raw_engine env_mode normalized
    state_file=$(single_443_engine_state_path)
    if [[ -f "$state_file" ]]; then
        raw_engine=$(
            # shellcheck disable=SC1090
            unset engine
            source "$state_file" 2>/dev/null || true
            printf '%s' "${engine:-}"
        )
        if [[ -n "$raw_engine" ]]; then
            normalized=$(normalize_entry_mode_name "$raw_engine" 2>/dev/null || true)
            if [[ -n "$normalized" ]]; then
                if declare -F rewrite_legacy_entry_mode_assignment >/dev/null 2>&1; then
                    rewrite_legacy_entry_mode_assignment "$state_file" "engine" "$raw_engine" 2>/dev/null || true
                fi
                printf '%s' "$normalized"
            else
                printf 'invalid:%s' "$raw_engine"
            fi
            return 0
        fi
    fi
    env_mode=$(get_entry_mode)
    case "$env_mode" in
        "nginx-stream"|"xray-fallback"|"tcp-peek") printf '%s' "$env_mode" ;;
        *) printf 'nginx-stream' ;;
    esac
}

sni_stack_route_name() {
    local prefix="$1"
    local sni="$2"
    sni=$(echo "$sni" | tr '.-' '__' | tr -cd 'a-zA-Z0-9_')
    printf '%s_%s' "$prefix" "$sni"
}

sni_stack_route_summary_for_state() {
    local web_backend xray_backend summary i domain
    web_backend=$(web_proxy_backend)
    xray_backend=$(format_hostport "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT")
    if strict_sni_gate_enabled; then
        summary="panel:${PANEL_DOMAIN}->${web_backend},reality:${REALITY_SNI}->${xray_backend},default->reject"
    else
        summary="panel:${PANEL_DOMAIN}->${web_backend},reality:${REALITY_SNI}->${xray_backend},default->${xray_backend}"
    fi
    for i in "${!SITE_DOMAINS[@]}"; do
        domain="${SITE_DOMAINS[$i]}"
        [[ -n "$domain" ]] && summary+=",site:${domain}->${web_backend}"
    done
    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        domain="${TCP_ROUTE_SNIS[$i]}"
        [[ -n "$domain" ]] && summary+=",tcp:${domain}->$(format_hostport "${TCP_ROUTE_ADDRS[$i]}" "${TCP_ROUTE_PORTS[$i]}")"
    done
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        domain="${XRAY_SNI_ROUTE_SNIS[$i]}"
        [[ -n "$domain" ]] && summary+=",xray:${domain}->$(format_hostport "${XRAY_SNI_ROUTE_ADDRS[$i]}" "${XRAY_SNI_ROUTE_PORTS[$i]}")"
    done
    printf '%s' "$summary"
}

sni_stack_whitelist_summary_for_state() {
    local summary="" i
    for i in "${!SNI_IP_WHITELIST_DOMAINS[@]}"; do
        [[ -n "${SNI_IP_WHITELIST_DOMAINS[$i]}" && -n "${SNI_IP_WHITELIST_RANGES[$i]}" ]] || continue
        [[ -n "$summary" ]] && summary+="|"
        summary+="${SNI_IP_WHITELIST_DOMAINS[$i]}:${SNI_IP_WHITELIST_RANGES[$i]}"
    done
    printf '%s' "$summary"
}

write_single_443_engine_state() {
    local selected_engine="$1"
    local selected_engine_raw="$1"
    local backup_id="${2:-}"
    local state_file mux_config mux_service web_backend xray_backend routes whitelist_rules web_engine
    selected_engine=$(normalize_entry_mode_name "$selected_engine_raw") || { echo -e "${RED}Invalid engine: ${selected_engine_raw}${PLAIN}"; return 1; }
    state_file=$(single_443_engine_state_path)
    mux_config=$(vpso_mux_config_path)
    mux_service=$(vpso_mux_service_name)
    web_engine=$(current_web_proxy_engine)
    web_backend=$(web_proxy_backend)
    xray_backend=$(format_hostport "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT")
    routes=$(sni_stack_route_summary_for_state)
    whitelist_rules=$(sni_stack_whitelist_summary_for_state)
    [[ -z "$backup_id" ]] && backup_id=$(cat /etc/vps-optimize/sni-stack.last-backup 2>/dev/null || true)

    mkdir -p /etc/vps-optimize
    cat <<EOF > "$state_file"
engine='${selected_engine}'
listen_addr='${NGINX_LISTEN_ADDR}'
listen_port='${NGINX_LISTEN_PORT}'
web_proxy_engine='${web_engine}'
web_proxy_backend='${web_backend}'
caddy_backend='${web_backend}'
xray_backend='${xray_backend}'
default_backend='${xray_backend}'
strict_sni_gate='$(normalize_strict_sni_gate "${STRICT_SNI_GATE:-false}")'
routes='${routes}'
whitelist_rules='${whitelist_rules}'
last_backup_id='${backup_id}'
mux_config_path='${mux_config}'
mux_systemd_service_name='${mux_service}'
EOF
    chmod 600 "$state_file" 2>/dev/null || true
}

show_single_443_engine_status() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🔎 当前 443 入口状态 / 端口复用引擎${PLAIN}" "${BOLD}🔎 Current 443 entry status / Port 443 Reuse engine${PLAIN}" "${BOLD}🔎 Текущий статус записи 443 / система повторного использования порта 443${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    local engine state_file mux_config
    engine=$(single_443_current_engine)
    state_file=$(single_443_engine_state_path)
    mux_config=$(vpso_mux_config_path)
    show_current_entry_status
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "当前 engine：${GREEN}${engine}${PLAIN}" "Current engine: ${GREEN}${engine}${PLAIN}" "Текущий двигатель: ${GREEN}${engine}${PLAIN}.")"
    echo -e "$(localized_text "状态文件：${state_file}" "Status file: ${state_file}" "Файл состояния: ${state_file}")"
    echo -e "$(localized_text "mux 配置：${mux_config}" "mux configuration: ${mux_config}" "конфигурация мультиплексора: ${mux_config}")"
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${GREEN}Nginx Stream 模式是默认稳定模式。${PLAIN}" "${GREEN}Nginx Stream mode is the default stable mode.${PLAIN}" "${GREEN}Режим Nginx Stream является стабильным режимом по умолчанию.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}TCP Peek + Splice 模式适合需要四层 SNI 分流和 splice 转发优化的进阶用户。${PLAIN}" "${YELLOW}TCP Peek + Splice mode Suitable for advanced users who require four-layer SNI offloading and splice forwarding optimization.${PLAIN}" "${YELLOW}Режим TCP Peek + Splice подходит для опытных пользователей, которым требуется четырехуровневая разгрузка SNI и оптимизация пересылки соединений.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}首次建议先监听 8444 测试，不要直接接管 443。${PLAIN}" "${YELLOW}For the first time, recommends listening to 8444 for testing instead of taking over 443 directly.${PLAIN}" "${YELLOW}Впервые рекомендует прослушивать 8444 для тестирования вместо непосредственного использования 443.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}切换前会自动备份，可回滚。${PLAIN}" "${YELLOW}Will automatically back up before switching and can be rolled back.${PLAIN}" "${YELLOW}автоматически создаст резервную копию перед переключением, и ее можно будет откатить.${PLAIN}")"
    echo -e "------------------------------------------------"
    if [[ -f /etc/vps-optimize/sni-stack.env ]]; then
        load_sni_stack_env >/dev/null 2>&1 && print_sni_stack_current_summary
    else
        echo -e "$(localized_text "${YELLOW}未检测到 sni-stack.env，尚未完成 443端口复用初始化。${PLAIN}" "${YELLOW}Did not detect sni-stack.env, and the Port 443 Reuse initialization has not been completed.${PLAIN}" "${YELLOW}не обнаружил sni-stack.env, и инициализация повторного использования порта 443 не завершена.${PLAIN}")"
    fi
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "公网 443 监听：" "public port 443 listening:" "прослушивание публичной сети 443:")"
    ss -lntup 2>/dev/null | grep -E '(:443[[:space:]]|:443$)' || echo "$(localized_text "未监听或当前用户无权限查看进程" "Not listening or the current user does not have permission to view the process" "Не прослушивается или текущий пользователь не имеет разрешения на просмотр процесса")"
}

show_tcp_peek_splice_info() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}TCP Peek + Splice 模式${PLAIN}" "${BOLD}TCP Peek + Splice mode${PLAIN}" "${BOLD}TCP Peek + Splice режим${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${YELLOW}TCP Peek + Splice 模式：基于 MSG_PEEK 读取 TLS ClientHello 中的 SNI，不消费首包，并根据 SNI 将连接分流到 Caddy 或 Xray 本地后端；转发时优先使用 splice 零拷贝，失败时自动回退普通 copy。实际运行的分流器程序为 vpso-mux。${PLAIN}" "${YELLOW}TCP Peek + Splice mode: Read SNI in TLS ClientHello based on MSG_PEEK, do not consume the first packet, and routing the connection to the Caddy or Xray local backend based on SNI; use splice first when forwarding Zero copy, automatic fallback to normal copy when failure occurs. The actual running routing program is vpso-mux.${PLAIN}" "${YELLOW}Режим TCP Peek + Splice: читайте SNI в TLS ClientHello на основе MSG_PEEK, не потребляйте первый пакет и маршрутизируйте соединение с локальным сервером Caddy или Xray на основе SNI; сначала используйте сращивание при пересылке нулевой копии, автоматический возврат к обычной копии в случае сбоя. Действующая программа маршрутизирования — vpso-mux.${PLAIN}")"
    echo -e "$(localized_text "它只在 TCP 层读取 TLS ClientHello 的 SNI，不终止 TLS，不管理证书，不替换 Caddy，也不是 Xray 直占 443。" "It only reads SNI of TLS ClientHello at the TCP layer, does not terminate TLS, does not manage certificates, does not replace Caddy, and is not directly occupied by Xray 443." "Он читает только SNI из TLS ClientHello на уровне TCP, не завершает TLS, не управляет сертификатами, не заменяет Caddy и не занят непосредственно Xray 443.")"
    echo -e "$(localized_text "推荐流程：" "Recommended process:" "Рекомендуемый процесс:")"
    echo -e "$(localized_text "  1. 先生成 TCP Peek + Splice 分流规则：/etc/vps-optimize/vpso-mux.yaml" "1. First generate the TCP Peek + Splice routing rule: /etc/vps-optimize/vpso-mux.yaml" "1. Сначала создайте правило маршрутизации TCP Peek + Splice: /etc/vps-optimize/vpso-mux.yaml.")"
    echo -e "$(localized_text "  2. 校验配置和后端端口" "2. Verify configuration and backend port" "2. Проверьте конфигурацию и внутренний порт.")"
    echo -e "$(localized_text "  3. 使用 TCP Peek + Splice 测试入口监听 8444" "3. Use TCP Peek + Splice to test entry listening 8444" "3. Используйте TCP Peek + Splice для проверки системы контроля входа 8444.")"
    echo -e "$(localized_text "  4. 确认后再事务式切换公网 443" "4. After confirmation, switch to the public transactionally 443" "4. После подтверждения переключитесь в публичную сеть транзакционно 443.")"
    echo -e "$(localized_text "  5. 异常时从菜单回滚到 Nginx Stream 模式" "5. Roll back to Nginx Stream mode from the menu in case of exception" "5. Откатиться в режим Nginx Stream из меню в случае исключения")"
}

print_vpso_mux_systemd_fallback_status() {
    local listen_port="${1:-${NGINX_LISTEN_PORT:-443}}"
    local public_lines preflight_lines
    echo -e "$(localized_text "${YELLOW}status.json 不存在或解析失败，已降级为 systemd / 监听状态检查。${PLAIN}" "${YELLOW}Status.json does not exist or fails to parse, and has been downgraded to systemd/listening status check.${PLAIN}" "${YELLOW}status.json не существует или его не удалось проанализировать, и его ранг был понижен до systemd/проверка статуса прослушивания.${PLAIN}")"
    echo -e "vpso-mux：$(service_status_compact vpso-mux)"
    echo -e "vpso-mux-preflight：$(service_status_compact vpso-mux-preflight)"
    echo -e "$(localized_text "公网 ${listen_port} 监听：" "public ${listen_port} listening:" "прослушивание публичной сети ${listen_port}:")"
    public_lines=$(ss -lntp 2>/dev/null | awk -v p=":${listen_port}" '$4 ~ p"$" {print}' || true)
    echo "$(localized_text "${public_lines:-未监听或当前用户无权限查看进程}" "${public_lines:-未监听或当前用户无权限查看进程}" "${public_lines:-未监听或当前用户无权限查看进程}")"
    echo -e "$(localized_text "8444 预检监听：" "8444 Preflight listening:" "8444 Предполетный контроль:")"
    preflight_lines=$(ss -lntp 2>/dev/null | awk '$4 ~ ":8444$" {print}' || true)
    echo "$(localized_text "${preflight_lines:-未监听或当前用户无权限查看进程}" "${preflight_lines:-未监听或当前用户无权限查看进程}" "${preflight_lines:-未监听或当前用户无权限查看进程}")"
}

print_vpso_mux_status_json() {
    local status_file py_bin
    status_file=$(vpso_mux_status_json_path)
    [[ -s "$status_file" ]] || return 1

    if command -v python3 >/dev/null 2>&1; then
        py_bin="python3"
    elif command -v python >/dev/null 2>&1; then
        py_bin="python"
    else
        return 1
    fi

    "$py_bin" - "$status_file" "$VPSO_LANGUAGE" <<'PY'
import json
import sys

path = sys.argv[1]
language = sys.argv[2] if len(sys.argv) > 2 else "zh"
with open(path, "r", encoding="utf-8") as fh:
    data = json.load(fh)

def value(name, default=0):
    return data.get(name, default)

labels = {
    "zh": {
        "started": "启动时间", "updated": "更新时间", "listen": "监听地址",
        "max": "连接上限", "active": "当前连接数", "total": "连接总数",
        "rejected": "拒绝连接数", "dial_errors": "后端拨号错误",
        "retry_attempts": "后端重试尝试", "retry_success": "后端重试成功",
        "retry_failed": "后端重试失败", "splice": "splice 成功次数",
        "fallback": "copy fallback 次数", "blocked": "白名单拦截次数", "unknown_blocked": "严格 SNI 门禁拦截次数",
        "no_sni": "no_sni 次数", "peek_errors": "peek 错误次数",
        "peek_timeouts": "peek 超时次数", "up": "客户端->后端字节",
        "down": "后端->客户端字节", "routes": "按 route 命中次数 Top 10",
        "errors": "最近错误", "none": "暂无",
    },
    "en": {
        "started": "Started", "updated": "Updated", "listen": "Listen addresses",
        "max": "Connection limit", "active": "Active connections", "total": "Total connections",
        "rejected": "Rejected connections", "dial_errors": "Backend dial errors",
        "retry_attempts": "Backend retry attempts", "retry_success": "Successful backend retries",
        "retry_failed": "Failed backend retries", "splice": "Successful splice operations",
        "fallback": "copy fallback operations", "blocked": "Whitelist blocks", "unknown_blocked": "Strict SNI gate blocks",
        "no_sni": "no_sni connections", "peek_errors": "peek errors",
        "peek_timeouts": "peek timeouts", "up": "Client-to-backend bytes",
        "down": "Backend-to-client bytes", "routes": "Top 10 route hits",
        "errors": "Recent errors", "none": "None",
    },
    "ru": {
        "started": "Время запуска", "updated": "Время обновления", "listen": "Адреса прослушивания",
        "max": "Лимит подключений", "active": "Активные подключения", "total": "Всего подключений",
        "rejected": "Отклонённые подключения", "dial_errors": "Ошибки подключения к бэкенду",
        "retry_attempts": "Попытки повтора подключения", "retry_success": "Успешные повторы подключения",
        "retry_failed": "Неудачные повторы подключения", "splice": "Успешные операции splice",
        "fallback": "Операции copy fallback", "blocked": "Блокировки белым списком", "unknown_blocked": "Блокировки строгим контролем SNI",
        "no_sni": "Подключения no_sni", "peek_errors": "Ошибки peek",
        "peek_timeouts": "Тайм-ауты peek", "up": "Байты от клиента к бэкенду",
        "down": "Байты от бэкенда к клиенту", "routes": "10 самых частых маршрутов",
        "errors": "Последние ошибки", "none": "Нет",
    },
}
text = labels.get(language, labels["zh"])

print(f"status.json：{path}")
print(f"{text['started']}: {value('start_time', 'unknown')}")
print(f"{text['updated']}: {value('updated_at', 'unknown')}")
listen = data.get("listen_addresses") or []
print(f"{text['listen']}: " + (", ".join(listen) if listen else "unknown"))
max_connections = value('max_connections', 'unlimited')
if max_connections == 0:
    max_connections = 'unlimited'
print(f"{text['max']}: {max_connections}")
print(f"{text['active']}: {value('active_connections')}")
print(f"{text['total']}: {value('total_connections')}")
print(f"{text['rejected']}: {value('rejected_connections')}")
print(f"{text['dial_errors']}: {value('backend_dial_errors')}")
print(f"{text['retry_attempts']}: {value('backend_retry_attempts')}")
print(f"{text['retry_success']}: {value('backend_retry_success')}")
print(f"{text['retry_failed']}: {value('backend_retry_failed')}")
print(f"{text['splice']}: {value('splice_success')}")
print(f"{text['fallback']}: {value('copy_fallback')}")
print(f"{text['blocked']}: {value('whitelist_blocked')}")
print(f"{text['unknown_blocked']}: {value('unknown_sni_blocked')}")
print(f"{text['no_sni']}: {value('no_sni')}")
print(f"{text['peek_errors']}: {value('peek_errors')}")
print(f"{text['peek_timeouts']}: {value('peek_timeouts')}")
print(f"{text['up']}: {value('bytes_client_to_backend')}")
print(f"{text['down']}: {value('bytes_backend_to_client')}")

route_hits = data.get("route_hits") or {}
print(f"{text['routes']}:")
if route_hits:
    for name, count in sorted(route_hits.items(), key=lambda item: (-int(item[1]), item[0]))[:10]:
        print(f"  - {name}: {count}")
else:
    print(f"  - {text['none']}")

recent_errors = data.get("recent_errors") or []
print(f"{text['errors']}:")
if recent_errors:
    for item in recent_errors[-10:]:
        at = item.get("time", "unknown")
        msg = item.get("message", "")
        route = item.get("route_name", "")
        sni = item.get("sni", "")
        suffix = ""
        if route:
            suffix += f" route={route}"
        if sni:
            suffix += f" sni={sni}"
        print(f"  - {at} {msg}{suffix}")
else:
    print(f"  - {text['none']}")
PY
}

show_vpso_mux_runtime_status() {
    local status_file
    status_file=$(vpso_mux_status_json_path)
    echo -e "$(localized_text "${BOLD}TCP Peek + Splice 运行统计${PLAIN}" "${BOLD}TCP Peek + Splice Operation statistics${PLAIN}" "${BOLD}TCP Peek + Splice Статистика работы${PLAIN}")"
    if ! print_vpso_mux_status_json; then
        print_vpso_mux_systemd_fallback_status "${NGINX_LISTEN_PORT:-443}"
    fi
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "配置文件：$(vpso_mux_config_path)" "Configuration file: $(vpso_mux_config_path)" "Файл конфигурации: $(vpso_mux_config_path).")"
    echo -e "systemd：/etc/systemd/system/$(vpso_mux_service_name)"
    echo -e "$(localized_text "状态文件：${status_file}" "Status file: ${status_file}" "Файл состояния: ${status_file}")"
}

# ---------------------------------------------------------
# Module: vpso_mux_config.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# vpso-mux YAML rendering and TCP Peek config generation.

append_vpso_mux_route_yaml() {
    local file="$1"
    local name="$2"
    local sni="$3"
    local backend="$4"
    local whitelist="$5"
    {
        echo "  - name: $(yaml_quote "$name")"
        echo "    sni:"
        echo "      - $(yaml_quote "$sni")"
        echo "    backend: $(yaml_quote "$backend")"
        if [[ -n "$whitelist" ]]; then
            echo "    whitelist:"
            local range
            for range in $whitelist; do
                echo "      - $(yaml_quote "$range")"
            done
        fi
    } >> "$file"
}

write_vpso_mux_config_from_sni_stack() {
    local listen_port="${1:-$NGINX_LISTEN_PORT}"
    local output_file="${2:-$(vpso_mux_config_path)}"
    local web_backend xray_backend listen_addr route_name ranges i domain backend
    web_backend=$(web_proxy_backend)
    xray_backend=$(format_hostport "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT")
    mkdir -p "$(dirname "$output_file")"

    {
        echo "listen:"
        echo "  tcp:"
        if [[ "$NGINX_LISTEN_ADDR" == "0.0.0.0" ]]; then
            echo "    - $(yaml_quote "0.0.0.0:${listen_port}")"
        elif [[ "$NGINX_LISTEN_ADDR" == "::" ]]; then
            echo "    - $(yaml_quote "[::]:${listen_port}")"
        else
            listen_addr=$(format_hostport "$NGINX_LISTEN_ADDR" "$listen_port")
            echo "    - $(yaml_quote "$listen_addr")"
        fi
        echo ""
        echo "timeouts:"
        echo "  peek: $(yaml_quote "3s")"
        echo "  dial: $(yaml_quote "5s")"
        echo "  idle: $(yaml_quote "300s")"
        echo "  shutdown: $(yaml_quote "10s")"
        echo ""
        echo "backend_retry:"
        echo "  count: 0"
        echo "  delay: $(yaml_quote "200ms")"
        echo ""
        echo "splice:"
        echo "  enabled: true"
        echo "  pipe_size: 1048576"
        echo "  fallback_to_copy: true"
        echo ""
        echo "limits:"
        echo "  max_connections: 4096"
        echo ""
        echo "default_backend: $(yaml_quote "$xray_backend")"
        echo "reject_unknown_sni: $(normalize_strict_sni_gate "${STRICT_SNI_GATE:-false}")"
        echo ""
        echo "routes:"
    } > "$output_file"

    ranges=$(sni_ip_whitelist_ranges_for_domain "$PANEL_DOMAIN")
    append_vpso_mux_route_yaml "$output_file" "panel" "$PANEL_DOMAIN" "$web_backend" "$ranges"
    if [[ -z "$ranges" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 面板域名 ${PANEL_DOMAIN} 当前未配置 IP 白名单；切换前请确认这是你想要的行为。${PLAIN}" "${YELLOW}⚠️ Panel domain ${PANEL_DOMAIN} currently does not have an IP whitelist configured; please confirm that this is the behavior you want before switching.${PLAIN}" "${YELLOW}⚠️ Для доменного имени панели ${PANEL_DOMAIN} в настоящее время не настроен белый список IP-адресов; перед переключением подтвердите, что это именно то поведение, которое вам нужно.${PLAIN}")"
    fi

    for i in "${!SITE_DOMAINS[@]}"; do
        domain="${SITE_DOMAINS[$i]}"
        [[ -n "$domain" ]] || continue
        route_name=$(sni_stack_route_name "site" "$domain")
        ranges=$(sni_ip_whitelist_ranges_for_domain "$domain")
        append_vpso_mux_route_yaml "$output_file" "$route_name" "$domain" "$web_backend" "$ranges"
    done

    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        domain="${TCP_ROUTE_SNIS[$i]}"
        [[ -n "$domain" ]] || continue
        route_name=$(sni_stack_route_name "tcp" "$domain")
        backend=$(format_hostport "${TCP_ROUTE_ADDRS[$i]}" "${TCP_ROUTE_PORTS[$i]}")
        append_vpso_mux_route_yaml "$output_file" "$route_name" "$domain" "$backend" ""
    done

    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        domain="${XRAY_SNI_ROUTE_SNIS[$i]}"
        [[ -n "$domain" ]] || continue
        route_name=$(sni_stack_route_name "xray" "$domain")
        backend=$(format_hostport "${XRAY_SNI_ROUTE_ADDRS[$i]}" "${XRAY_SNI_ROUTE_PORTS[$i]}")
        append_vpso_mux_route_yaml "$output_file" "$route_name" "$domain" "$backend" ""
    done

    append_vpso_mux_route_yaml "$output_file" "reality" "$REALITY_SNI" "$xray_backend" ""

    cat <<EOF >> "$output_file"

logging:
  level: $(yaml_quote "info")
  format: $(yaml_quote "json")
  max_size_bytes: 5242880
  max_backups: 3
EOF
    chmod 600 "$output_file" 2>/dev/null || true
}

generate_tcp_peek_config() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}重新应用 TCP Peek + Splice 配置${PLAIN}" "${BOLD}Reapply TCP Peek + Splice configure${PLAIN}" "${BOLD}повторно применить TCP Peek + Splice настроить${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    echo -e "$(localized_text "${YELLOW}只生成 TCP Peek + Splice 分流规则，不改服务，不改端口，不接管 443。${PLAIN}" "${YELLOW}Only generates TCP Peek + Splice routing rules, does not change the service, does not change the port, and does not take over 443.${PLAIN}" "${YELLOW}генерирует только правила маршрутизации TCP Peek + Splice, не меняя службу, порт и не перенимая управление 443.${PLAIN}")"
    write_vpso_mux_config_from_sni_stack "$NGINX_LISTEN_PORT" "$(vpso_mux_config_path)" || return 1
    echo -e "$(localized_text "${GREEN}✅ 已生成：$(vpso_mux_config_path)${PLAIN}" "${GREEN}✅ Generated: $(vpso_mux_config_path)${PLAIN}" "${GREEN}✅ Сгенерировано: $(vpso_mux_config_path)${PLAIN}")"
    echo -e "$(localized_text "默认后端：$(format_hostport "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT")" "Default backend: $(format_hostport \"$XRAY_LISTEN_ADDR\" \"$XRAY_LISTEN_PORT\")" "бэкенд по умолчанию: $(format_hostport \"$XRAY_LISTEN_ADDR\" \"$XRAY_LISTEN_PORT\").")"
    echo -e "$(localized_text "Web 反代后端：$(web_proxy_engine_label) $(web_proxy_backend)" "Web reverse proxy backend: $(web_proxy_engine_label) $(web_proxy_backend)" "бэкенд веб-прокси: $(web_proxy_engine_label) $(web_proxy_backend)")"
    echo -e "$(localized_text "${YELLOW}下一步建议先校验配置，再使用 TCP Peek + Splice 测试入口监听 8444。${PLAIN}" "${YELLOW}The next step is to verify the configuration first, and then use TCP Peek + Splice to test entry listening 8444.${PLAIN}" "${YELLOW}Следующий шаг — сначала проверить конфигурацию, а затем использовать TCP Peek + Splice для проверки контроля входа 8444.${PLAIN}")"
}

# ---------------------------------------------------------
# Module: vpso_mux_install.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# vpso-mux build, install, systemd, and failure-context helpers.

go_install_vpso_mux_latest() {
    local module_version tmp_dir
    echo -e "$(localized_text "${CYAN}▶ 正在使用本机 Go 以兼容模式构建 vpso-mux...${PLAIN}" "${CYAN}▶ Building in compatibility mode using native Go vpso-mux...${PLAIN}" "${CYAN}▶ Сборка в режиме совместимости с использованием родного Go vpso-mux...${PLAIN}")"
    if ! go version 2>/dev/null | grep -Eq 'go1\.(2[2-9]|[3-9][0-9])'; then
        echo -e "$(localized_text "${RED}❌ 当前 Go 版本低于 1.22，拒绝在生产机上自动下载临时 Go 工具链。${PLAIN}" "${RED}❌ The current Go version is lower than 1.22, and automatic downloading of the temporary Go tool chain on the production machine is refused.${PLAIN}" "${RED}❌ Текущая версия Go ниже 1.22, и автоматическая загрузка временной цепочки инструментов Go на производственную машину запрещена.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}请先通过系统包管理器安装 Go 1.22+，或在安全环境构建 /usr/local/bin/vpso-mux 后再切换 TCP Peek。${PLAIN}" "${YELLOW}Please install Go 1.22+ through the system package manager first, or build /usr/local/bin/vpso-mux in a safe environment before switching to TCP Peek.${PLAIN}" "${YELLOW}Сначала установите Go 1.22+ через системный менеджер пакетов или соберите /usr/local/bin/vpso-mux в безопасной среде перед переходом на TCP Peek.${PLAIN}")"
        return 1
    fi
    vpso_mux_build_resource_check || return 1
    module_version=$(GOTOOLCHAIN=local go list -m -f '{{.Version}}' github.com/Chunlion/VPS-Optimize@latest 2>/dev/null) || return 1
    tmp_dir=$(mktemp -d /tmp/vpso-mux-build.XXXXXX) || return 1
    cat <<EOF > "${tmp_dir}/go.mod"
module vpso-mux-build

go 1.22

require github.com/Chunlion/VPS-Optimize ${module_version}

replace golang.org/x/sys => golang.org/x/sys v0.30.0
EOF
    (
        local mod_dir patched_dir patch_file
        cd "$tmp_dir" || exit 1
        GOMAXPROCS=1 GOTOOLCHAIN=local go mod download github.com/Chunlion/VPS-Optimize || exit 1
        mod_dir=$(GOTOOLCHAIN=local go list -m -f '{{.Dir}}' github.com/Chunlion/VPS-Optimize) || exit 1
        patched_dir="${tmp_dir}/VPS-Optimize-src"
        cp -a "$mod_dir" "$patched_dir" || exit 1
        chmod -R u+w "$patched_dir" 2>/dev/null || true
        patch_file="${patched_dir}/cmd/vpso-mux/main.go"
        if grep -q 'unix\.Splice(pipeFD\[0\], nil, dstFD, nil, remaining,' "$patch_file" 2>/dev/null; then
            echo -e "$(localized_text "${YELLOW}⚠️ 检测到远程 vpso-mux 旧源码，正在应用 Go 兼容修补...${PLAIN}" "${YELLOW}⚠️ Detected remote vpso-mux old source code, applying Go compatible patch...${PLAIN}" "${YELLOW}⚠️ Обнаружен удаленный старый исходный код vpso-mux, применен патч, совместимый с Go...${PLAIN}")"
            sed -i 's/unix\.Splice(pipeFD\[0\], nil, dstFD, nil, remaining,/unix.Splice(pipeFD[0], nil, dstFD, nil, int(remaining),/' "$patch_file" || exit 1
        fi
        cat <<EOF >> "${tmp_dir}/go.mod"

replace github.com/Chunlion/VPS-Optimize => ./VPS-Optimize-src
EOF
        GOMAXPROCS=1 GOTOOLCHAIN=local go get "github.com/Chunlion/VPS-Optimize/cmd/vpso-mux@${module_version}" || exit 1
        GOMAXPROCS=1 GOTOOLCHAIN=local go build -p 1 -o /usr/local/bin/vpso-mux github.com/Chunlion/VPS-Optimize/cmd/vpso-mux
    )
}

vpso_mux_build_resource_check() {
    local mem_kb swap_kb available_kb tmp_kb
    if [[ -r /proc/meminfo ]]; then
        mem_kb=$(awk '/MemAvailable:/ {print $2; exit}' /proc/meminfo 2>/dev/null || echo 0)
        swap_kb=$(awk '/SwapFree:/ {print $2; exit}' /proc/meminfo 2>/dev/null || echo 0)
        mem_kb=${mem_kb:-0}
        swap_kb=${swap_kb:-0}
        available_kb=$((mem_kb + swap_kb))
        if (( available_kb > 0 && available_kb < 262144 )); then
            echo -e "$(localized_text "${RED}❌ 可用内存+Swap 低于 256MB，拒绝在当前服务器上编译 vpso-mux，避免系统失联。${PLAIN}" "${RED}❌ Available memory + Swap is less than 256MB, refuse to compile vpso-mux on the current server to avoid system loss.${PLAIN}" "${RED}❌ Доступная память + подкачка менее 256 МБ, откажитесь от компиляции vpso-mux на текущем сервере во избежание потери системы.${PLAIN}")"
            return 1
        fi
    fi
    tmp_kb=$(df -Pk /tmp 2>/dev/null | awk 'NR==2 {print $4}' || echo 0)
    tmp_kb=${tmp_kb:-0}
    if (( tmp_kb > 0 && tmp_kb < 524288 )); then
        echo -e "$(localized_text "${RED}❌ /tmp 可用空间低于 512MB，拒绝构建 vpso-mux。${PLAIN}" "${RED}❌ /tmp free space is less than 512MB, rejecting build vpso-mux.${PLAIN}" "${RED}❌ /tmp свободного места меньше 512 МБ, что означает отклонение сборки vpso-mux.${PLAIN}")"
        return 1
    fi
}

require_vpso_mux_binary_for_cutover() {
    if [[ -x /usr/local/bin/vpso-mux ]]; then
        return 0
    fi
    echo -e "$(localized_text "${RED}❌ /usr/local/bin/vpso-mux 不可用，无法继续 TCP Peek 预检或切换。${PLAIN}" "${RED}❌ /usr/local/bin/vpso-mux is unavailable; TCP Peek preflight or switching cannot continue.${PLAIN}" "${RED}❌ /usr/local/bin/vpso-mux недоступен; проверка и переключение TCP Peek невозможны.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}请根据前面的安装或构建错误处理后重试。${PLAIN}" "${YELLOW}Fix the installation or build error above, then retry.${PLAIN}" "${YELLOW}Исправьте указанную выше ошибку установки или сборки и повторите попытку.${PLAIN}")"
    return 1
}

install_vpso_mux_binary() {
    if [[ -x /usr/local/bin/vpso-mux ]]; then
        return 0
    fi

    if ! command -v go >/dev/null 2>&1; then
        echo -e "$(localized_text "${CYAN}▶ 未检测到 Go，正在安装 vpso-mux 构建工具链...${PLAIN}" "${CYAN}▶ Go not detected, installing vpso-mux build toolchain...${PLAIN}" "${CYAN}▶ Go не обнаружен, устанавливается набор инструментов сборки vpso-mux...${PLAIN}")"
        if is_debian; then
            install_pkg golang-go || install_pkg golang || return 1
        elif is_redhat; then
            install_pkg golang || return 1
        else
            echo -e "$(localized_text "${RED}❌ 当前系统暂不支持自动安装 Go，请先安装 Go 1.22+ 后重试。${PLAIN}" "${RED}❌ The current system does not support automatic installation of Go. Please install Go 1.22+ first and try again.${PLAIN}" "${RED}❌ Текущая система не поддерживает автоматическую установку Go. Пожалуйста, сначала установите Go 1.22+ и повторите попытку.${PLAIN}")"
            return 1
        fi
    fi

    command -v go >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ Go 安装后仍不可用，无法构建 vpso-mux。${PLAIN}" "${RED}❌ Go is still unavailable after installation and cannot build vpso-mux.${PLAIN}" "${RED}❌ Go по-прежнему недоступен после установки и не может собрать vpso-mux.${PLAIN}")"; return 1; }

    local source_dir="${SCRIPT_DIR:-$(pwd)}"
    if [[ -d "$source_dir/cmd/vpso-mux" ]]; then
        echo -e "$(localized_text "${CYAN}▶ 正在从当前源码构建 vpso-mux...${PLAIN}" "${CYAN}▶ Building from current source code vpso-mux...${PLAIN}" "${CYAN}▶ Сборка из текущего исходного кода vpso-mux...${PLAIN}")"
        (cd "$source_dir" && go build -o /usr/local/bin/vpso-mux ./cmd/vpso-mux) || return 1
        chmod 755 /usr/local/bin/vpso-mux
        return 0
    fi

    go_install_vpso_mux_latest || return 1
    chmod 755 /usr/local/bin/vpso-mux 2>/dev/null || true
    [[ -x /usr/local/bin/vpso-mux ]] || { echo -e "$(localized_text "${RED}❌ vpso-mux 安装后仍不可执行：/usr/local/bin/vpso-mux${PLAIN}" "${RED}❌ vpso-mux Still unexecutable after installation: /usr/local/bin/vpso-mux${PLAIN}" "${RED}❌ vpso-mux После установки все еще не выполняется: /usr/local/bin/vpso-mux${PLAIN}")"; return 1; }
    return 0
}

write_vpso_mux_systemd_service() {
    local service_file="${1:-/etc/systemd/system/vpso-mux.service}"
    cat <<'EOF' > "$service_file"
[Unit]
Description=VPS-Optimize TCP Peek + Splice vpso-mux router
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecCondition=/bin/grep -Fxq "ENTRY_MODE='tcp-peek'" /etc/vps-optimize/sni-stack.env
ExecStart=/usr/local/bin/vpso-mux -config /etc/vps-optimize/vpso-mux.yaml
Restart=on-failure
RestartSec=3
LimitNOFILE=1048576
AmbientCapabilities=CAP_NET_BIND_SERVICE
NoNewPrivileges=true
ProtectSystem=full
ProtectHome=true
PrivateTmp=true

[Install]
WantedBy=multi-user.target
EOF
    chmod 644 "$service_file"
    if [[ "$service_file" == "/etc/systemd/system/vpso-mux.service" ]]; then
        systemctl daemon-reload >/dev/null 2>&1 || true
    fi
}

run_vpso_mux_config_check() {
    local config_file="${1:-$(vpso_mux_config_path)}"
    if [[ -x /usr/local/bin/vpso-mux ]]; then
        /usr/local/bin/vpso-mux -config "$config_file" -check
        return $?
    fi
    local source_dir="${SCRIPT_DIR:-$(pwd)}"
    if command -v go >/dev/null 2>&1 && [[ -d "$source_dir/cmd/vpso-mux" ]]; then
        (cd "$source_dir" && go run ./cmd/vpso-mux -config "$config_file" -check)
        return $?
    fi
    echo -e "$(localized_text "${RED}❌ 缺少 vpso-mux 二进制或 Go 工具链，无法执行完整配置校验。${PLAIN}" "${RED}❌ Missing the vpso-mux binary or Go toolchain, a full configuration check cannot be performed.${PLAIN}" "${RED}❌ При отсутствии двоичного файла vpso-mux или набора инструментов Go полную проверку конфигурации выполнить невозможно.${PLAIN}")"
    return 1
}

print_vpso_mux_failure_context() {
    local port="${1:-$NGINX_LISTEN_PORT}"
    echo -e "$(localized_text "${YELLOW}▶ vpso-mux 未能稳定监听 ${port}，下面是最近状态和日志：${PLAIN}" "${YELLOW}▶ vpso-mux failed to monitor ${port} stably. The following is the latest status and log:${PLAIN}" "${YELLOW}▶ vpso-mux не удалось стабильно контролировать ${port}. Ниже приводится последний статус и журнал:.${PLAIN}")"
    systemctl status vpso-mux --no-pager -l 2>/dev/null || true
    echo -e "$(localized_text "${YELLOW}▶ 最近 40 行 vpso-mux 日志：${PLAIN}" "${YELLOW}▶ Last 40 lines vpso-mux Log:${PLAIN}" "${YELLOW}▶ Последние 40 строк vpso-mux Журнал:${PLAIN}")"
    journalctl -u vpso-mux -n 40 --no-pager 2>/dev/null || true
    echo -e "$(localized_text "${YELLOW}▶ 当前 ${port} 监听情况：${PLAIN}" "${YELLOW}▶ Current listening status of ${port}:${PLAIN}" "${YELLOW}▶ Текущий статус прослушивания ${port}:${PLAIN}")"
    if command -v ss >/dev/null 2>&1; then
        ss -lntp 2>/dev/null | awk -v p=":${port}" '$4 ~ p"$" {print}' || true
    else
        netstat -lntp 2>/dev/null | awk -v p=":${port}" '$4 ~ p"$" {print}' || true
    fi
}

# ---------------------------------------------------------
# Module: tcp_peek_engine.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# TCP Peek preflight, entry-mode cutover, and runtime actions.

vpso_mux_preflight_config_path() {
    echo "/etc/vps-optimize/vpso-mux.preflight.yaml"
}

write_vpso_mux_preflight_service() {
    cat <<'EOF' > /etc/systemd/system/vpso-mux-preflight.service
[Unit]
Description=VPS-Optimize TCP Peek preflight router on 8444
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=/usr/local/bin/vpso-mux -config /etc/vps-optimize/vpso-mux.preflight.yaml
Restart=on-failure
RestartSec=3
LimitNOFILE=1048576
AmbientCapabilities=CAP_NET_BIND_SERVICE
NoNewPrivileges=true
ProtectSystem=full
ProtectHome=true
PrivateTmp=true

[Install]
WantedBy=multi-user.target
EOF
    chmod 644 /etc/systemd/system/vpso-mux-preflight.service
    systemctl daemon-reload >/dev/null 2>&1 || true
}

port_listener_has_process() {
    local port="$1"
    local proc_pattern="$2"
    ss -lntp 2>/dev/null | grep -E "(:${port}[[:space:]]|:${port}$)" | grep -q "$proc_pattern"
}

tcppeek_preflight_probe_route_matrix() {
    local test_port="$1"
    local connect_host domain i route_addr route_port failures=0
    connect_host=$(probe_host_for_listen_addr "$NGINX_LISTEN_ADDR")

    echo -e "$(localized_text "${CYAN}▶ 检查 TCP Peek 8444 路由矩阵...${PLAIN}" "${CYAN}▶ Check TCP Peek 8444 routing matrix...${PLAIN}" "${CYAN}▶ Проверьте матрицу маршрутизации TCP Peek 8444...${PLAIN}")"
    probe_tls_sni_certificate "$(localized_text "TCP Peek 8444 面板 SNI 预检" "TCP Peek 8444 panel SNI preflight check" "TCP Peek 8444 панель SNI предварительная проверка")" "$connect_host" "$test_port" "$PANEL_DOMAIN" || failures=1

    for domain in "${SITE_DOMAINS[@]}"; do
        [[ -n "$domain" ]] || continue
        probe_tls_sni_certificate "$(localized_text "TCP Peek 8444 Web SNI 预检 ${domain}" "TCP Peek 8444 Web SNI preflight check ${domain}" "TCP Peek 8444 Интернет SNI Предварительная проверка ${domain}")" "$connect_host" "$test_port" "$domain" || failures=1
    done

    tcp_probe_host "$(localized_text "TCP Peek 默认 Xray/REALITY 后端" "TCP Peek Default Xray/REALITY backend" "TCP Peek бэкенд по умолчанию Xray/REALITY")" "$(probe_host_for_listen_addr "$XRAY_LISTEN_ADDR")" "$XRAY_LISTEN_PORT" 3 1 || failures=1

    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        domain="${TCP_ROUTE_SNIS[$i]}"
        route_addr="${TCP_ROUTE_ADDRS[$i]}"
        route_port="${TCP_ROUTE_PORTS[$i]}"
        [[ -n "$domain" && -n "$route_addr" && -n "$route_port" ]] || continue
        tcp_probe_host "$(localized_text "TCP Peek 本地 TCP/SNI 后端 ${domain}" "TCP Peek local TCP/SNI backend ${domain}" "TCP Peek локальный TCP/SNI бэкенд ${domain}")" "$(probe_host_for_listen_addr "$route_addr")" "$route_port" 3 1 || failures=1
    done

    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        domain="${XRAY_SNI_ROUTE_SNIS[$i]}"
        route_addr="${XRAY_SNI_ROUTE_ADDRS[$i]}"
        route_port="${XRAY_SNI_ROUTE_PORTS[$i]}"
        [[ -n "$domain" && -n "$route_addr" && -n "$route_port" ]] || continue
        tcp_probe_host "$(localized_text "TCP Peek Xray SNI 后端 ${domain}" "TCP Peek Xray SNI Backend ${domain}" "TCP Peek Xray SNI бэкенд ${domain}")" "$(probe_host_for_listen_addr "$route_addr")" "$route_port" 3 1 || failures=1
    done

    if [[ "$failures" -ne 0 ]]; then
        echo -e "$(localized_text "${RED}❌ TCP Peek 8444 路由矩阵预检失败，公网 443 未改动。${PLAIN}" "${RED}❌ TCP Peek 8444 Routing matrix preflight check failed, public port 443 has not been changed.${PLAIN}" "${RED}❌ TCP Peek 8444 Предварительная проверка матрицы маршрутизации не удалась, публичный порт 443 не был изменён.${PLAIN}")"
        return 1
    fi
    echo -e "$(localized_text "${GREEN}✅ TCP Peek 8444 路由矩阵预检通过。${PLAIN}" "${GREEN}✅ TCP Peek 8444 Routing matrix preflight check passed.${PLAIN}" "${GREEN}✅ TCP Peek 8444 Предварительная проверка матрицы маршрутизации пройдена.${PLAIN}")"
    return 0
}

run_tcppeek_preflight_service() {
    local keep_running="${1:-0}"
    local test_port="${2:-8444}"
    local config_file tmp_config
    config_file=$(vpso_mux_preflight_config_path)

    require_vpso_mux_binary_for_cutover || return 1
    tmp_config="${config_file}.tmp.$$"
    write_vpso_mux_config_from_sni_stack "$test_port" "$tmp_config" || return 1
    if ! run_vpso_mux_config_check "$tmp_config"; then
        quarantine_path "$tmp_config" "/etc/vps-optimize/quarantine/vpso-mux" >/dev/null 2>&1 || true
        return 1
    fi
    mv "$tmp_config" "$config_file" || return 1
    write_vpso_mux_preflight_service
    systemctl stop vpso-mux-preflight >/dev/null 2>&1 || true
    if ! systemctl start vpso-mux-preflight; then
        echo -e "$(localized_text "${RED}❌ TCP Peek 8444 预检服务启动失败，公网 443 未改动。${PLAIN}" "${RED}❌ TCP Peek 8444 The preflight service failed to start, and the public port 443 has not been changed.${PLAIN}" "${RED}❌ TCP Peek 8444 Не удалось запустить предполетную службу, а публичный порт 443 не был изменён.${PLAIN}")"
        print_tcppeek_preflight_failure_context "$test_port"
        return 1
    fi
    sleep 1
    if ! port_listener_has_process "$test_port" 'vpso-mux'; then
        systemctl stop vpso-mux-preflight >/dev/null 2>&1 || true
        echo -e "$(localized_text "${RED}❌ TCP Peek 8444 预检未监听到 vpso-mux，拒绝切换公网 443。${PLAIN}" "${RED}❌ TCP Peek 8444 The precheck did not detect vpso-mux and refused to switch to the public port 443.${PLAIN}" "${RED}❌ TCP Peek 8444 Предварительная проверка не обнаружила vpso-mux и отказалась переключаться в публичную сеть 443.${PLAIN}")"
        print_tcppeek_preflight_failure_context "$test_port"
        return 1
    fi
    tcppeek_preflight_probe_route_matrix "$test_port" || {
        systemctl stop vpso-mux-preflight >/dev/null 2>&1 || true
        return 1
    }
    if [[ "$keep_running" != "1" ]]; then
        systemctl stop vpso-mux-preflight >/dev/null 2>&1 || true
    fi
    return 0
}

print_tcppeek_preflight_failure_context() {
    local port="${1:-8444}"
    echo -e "$(localized_text "${YELLOW}vpso-mux 预检状态与最近日志：${PLAIN}" "${YELLOW}vpso-mux preflight status and recent logs:${PLAIN}" "${YELLOW}Состояние проверки vpso-mux и последние журналы:${PLAIN}")"
    systemctl status vpso-mux-preflight --no-pager -l 2>/dev/null || true
    journalctl -u vpso-mux-preflight -n 40 --no-pager 2>/dev/null || true
    echo -e "$(localized_text "${YELLOW}${port} 端口监听：${PLAIN}" "${YELLOW}Port ${port} listener:${PLAIN}" "${YELLOW}Прослушивание порта ${port}:${PLAIN}")"
    ss -lntp 2>/dev/null | awk -v p=":${port}" '$4 ~ p"$" {print}' || true
}

tcp_peek_dry_run_config() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}TCP Peek + Splice 分流规则校验${PLAIN}" "${BOLD}TCP Peek + Splice Routing rule verification${PLAIN}" "${BOLD}TCP Peek + Splice Проверка правил маршрутизации${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    local config_file
    config_file=$(vpso_mux_config_path)
    [[ -f "$config_file" ]] || { echo -e "$(localized_text "${YELLOW}未找到 ${config_file}，正在先生成配置。${PLAIN}" "${YELLOW}${config_file} was not found; generating it first.${PLAIN}" "${YELLOW}Файл ${config_file} не найден; сначала создаётся конфигурация.${PLAIN}")"; write_vpso_mux_config_from_sni_stack "$NGINX_LISTEN_PORT" "$config_file" || return 1; }
    echo -e "$(localized_text "${CYAN}▶ 校验 YAML、SNI、backend、whitelist 和重复 SNI...${PLAIN}" "${CYAN}▶ Check YAML, SNI, backend, whitelist and duplicate SNI...${PLAIN}" "${CYAN}▶ Проверьте YAML, SNI, бэкенд, белый список и дубликат SNI....${PLAIN}")"
    run_vpso_mux_config_check "$config_file" || return 1
    echo -e "$(localized_text "${CYAN}▶ 检查本地后端端口...${PLAIN}" "${CYAN}▶ Check local backend port...${PLAIN}" "${CYAN}▶ Проверьте локальный внутренний порт...${PLAIN}")"
    tcp_probe_host "Caddy 127.0.0.1:${CADDY_LISTEN_PORT}" "$(probe_host_for_listen_addr "$CADDY_LISTEN_ADDR")" "$CADDY_LISTEN_PORT" || true
    tcp_probe_host "Xray/REALITY 127.0.0.1:${XRAY_LISTEN_PORT}" "$(probe_host_for_listen_addr "$XRAY_LISTEN_ADDR")" "$XRAY_LISTEN_PORT" || true
    print_sni_ip_whitelist_summary
    echo -e "$(localized_text "${GREEN}✅ 配置校验完成。请先使用 TCP Peek + Splice 测试入口验证，不要直接接管 443。${PLAIN}" "${GREEN}✅ configuration validation completed. Please use TCP Peek + Splice test entry verification first, do not take over 443 directly.${PLAIN}" "${GREEN}✅ Проверка конфигурации завершена. Пожалуйста, сначала используйте тестовую проверку входа TCP Peek + Splice, не переключайте публичный порт 443 напрямую.${PLAIN}")"
}

start_tcp_peek_test_port() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}TCP Peek + Splice 状态 / 测试入口${PLAIN}" "${BOLD}TCP Peek + Splice status / test entry${PLAIN}" "${BOLD}TCP Peek + Splice статус/тестовый вход${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    if ! load_sni_stack_env; then
        NGINX_LISTEN_PORT="${NGINX_LISTEN_PORT:-443}"
        show_vpso_mux_runtime_status
        return 1
    fi
    show_vpso_mux_runtime_status
    echo -e "------------------------------------------------"
    if [[ "$(single_443_current_engine)" == "tcp-peek" ]]; then
        echo -e "$(localized_text "${YELLOW}当前入口已经是 TCP Peek + Splice 模式。为避免误停公网 443，本入口不覆盖运行中的 443 配置。${PLAIN}" "${YELLOW}The current entry of is already in TCP Peek + Splice mode. To avoid accidentally stopping the public port 443, this entry does not cover the running 443 configuration.${PLAIN}" "${YELLOW}Текущая запись уже находится в режиме TCP Peek + Splice. Чтобы избежать случайной остановки публичного порта 443, эта запись не распространяется на работающую конфигурацию 443.${PLAIN}")"
        return 0
    fi
    echo -e "$(localized_text "${YELLOW}vpso-mux 预检服务只监听 8444，当前公网 443 入口不会被停止或替换。${PLAIN}" "${YELLOW}Vpso-mux The preflight service only listens to 8444, and the current public port 443 entry will not be stopped or replaced.${PLAIN}" "${YELLOW}vpso-mux Предполетная служба слушает только 8444, и текущий вход в публичный порт 443 не будет остановлен или заменен.${PLAIN}")"
    confirm_risk_action "$(localized_text "安装/构建 vpso-mux 并启动 8444 预检" "Install/build vpso-mux and start 8444 preflight" "Установите/соберите vpso-mux и запустите предварительная проверка 8444.")" \
        "$(localized_text "可能安装 Go 工具链、构建 /usr/local/bin/vpso-mux，并启动独立 vpso-mux-preflight.service 监听 8444" "Possibly install the Go toolchain, build /usr/local/bin/vpso-mux, and start the standalone vpso-mux-preflight.service listener 8444" "Возможно, установите набор инструментов Go, соберите /usr/local/bin/vpso-mux и запустите автономный прослушиватель vpso-mux-preflight.service 8444.")" \
        "$(localized_text "停止 vpso-mux-preflight.service，或继续使用 Nginx Stream / Xray Fallback，不会改动公网 443" "Stop vpso-mux-preflight.service, or continue to use Nginx Stream / Xray Fallback, which will not change the public port 443" "Остановите vpso-mux-preflight.service или продолжайте использовать Nginx Stream/Xray Fallback, который не изменит публичную сеть 443")" \
        "$(localized_text "低内存或低磁盘机器会被资源预检查拦截；公网 443 在本步骤不会被替换。" "Low memory or low disk machines will be blocked by resource preflight check; public port 443 will not be replaced in this step." "Машины с нехваткой памяти или диска будут заблокированы предварительной проверкой ресурсов; публичный порт 443 не будет заменена на этом этапе.")" || return 1
    install_vpso_mux_binary || return 1
    apply_web_proxy_configs_for_single_443 || return 1
    restart_web_proxy_for_single_443 || return 1
    tcp_probe_host "$(localized_text "$(web_proxy_engine_label) 本地 TLS" "$(web_proxy_engine_label) local TLS" "$(web_proxy_engine_label) локальный TLS")" "$(probe_host_for_listen_addr "$CADDY_LISTEN_ADDR")" "$CADDY_LISTEN_PORT" || return 1
    tcp_probe_host "$(localized_text "Xray/REALITY 本地入站" "Xray/REALITY local inbound" "Xray/REALITY локальное входящее подключение")" "$(probe_host_for_listen_addr "$XRAY_LISTEN_ADDR")" "$XRAY_LISTEN_PORT" 6 1 || return 1
    run_tcppeek_preflight_service 1 "8444" || return 1
    echo -e "$(localized_text "${GREEN}✅ vpso-mux 预检服务已启动在测试端口 8444，公网 443 未改动。${PLAIN}" "${GREEN}✅ vpso-mux preflight service has been started on test port 8444, and public port 443 has not been changed.${PLAIN}" "${GREEN}✅ Служба предварительной проверки vpso-mux запущена на тестовом порту 8444, а публичный порт 443 не был изменён.${PLAIN}")"
    echo -e "$(localized_text "测试命令：" "Test command:" "Тестовая команда:")"
    echo -e "  openssl s_client -connect SERVER_IP:8444 -servername ${PANEL_DOMAIN}"
    [[ ${#SITE_DOMAINS[@]} -gt 0 ]] && echo -e "  openssl s_client -connect SERVER_IP:8444 -servername ${SITE_DOMAINS[0]}"
    echo -e "  openssl s_client -connect SERVER_IP:8444 -servername random.example.com"
    [[ ${#SITE_DOMAINS[@]} -gt 0 ]] && echo -e "  curl -vk --resolve ${SITE_DOMAINS[0]}:8444:SERVER_IP https://${SITE_DOMAINS[0]}:8444/"
}

preflight_tcppeek_before_cutover() {
    echo -e "$(localized_text "${CYAN}▶ 正在执行 TCP Peek 8444 安全预检，公网 443 暂不改动...${PLAIN}" "${CYAN}▶ Executing TCP Peek 8444 security preflight check, public port 443 No changes for now...${PLAIN}" "${CYAN}▶ Выполнение предварительной проверки безопасности TCP Peek 8444, публичный порт 443 На данный момент изменений нет...${PLAIN}")"
    require_vpso_mux_binary_for_cutover || return 1
    warn_if_public_bind "$(web_proxy_engine_label)" "$CADDY_LISTEN_ADDR" "$CADDY_LISTEN_PORT" || return 1
    warn_if_public_bind "Xray REALITY" "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT" || return 1
    apply_web_proxy_configs_for_single_443 || return 1
    restart_web_proxy_for_single_443 || return 1
    tcp_probe_host "$(localized_text "$(web_proxy_engine_label) 本地 TLS" "$(web_proxy_engine_label) local TLS" "$(web_proxy_engine_label) локальный TLS")" "$(probe_host_for_listen_addr "$CADDY_LISTEN_ADDR")" "$CADDY_LISTEN_PORT" || return 1
    tcp_probe_host "$(localized_text "Xray/REALITY 本地入站" "Xray/REALITY local inbound" "Xray/REALITY локальное входящее подключение")" "$(probe_host_for_listen_addr "$XRAY_LISTEN_ADDR")" "$XRAY_LISTEN_PORT" 6 1 || {
        echo -e "$(localized_text "${RED}❌ Xray 本地入站不可达，拒绝切换 TCP Peek。请先在 3x-ui/Xray 中准备本地监听入站。${PLAIN}" "${RED}❌ Xray The local inbound is unreachable and the switch to TCP Peek is refused. Please prepare local listeners inbound in 3x-ui/Xray first.${PLAIN}" "${RED}❌ Xray локальное входящее подключение недоступно, и в переключении на TCP Peek отказано. Пожалуйста, сначала подготовьте локальное входящее подключение в 3x-ui/Xray.${PLAIN}")"
        return 1
    }
    run_tcppeek_preflight_service 0 "8444" || return 1
    echo -e "$(localized_text "${GREEN}✅ TCP Peek 8444 预检通过，才会进入公网 443 切换。${PLAIN}" "${GREEN}✅ TCP Peek 8444 Only after passing the preflight check will it enter the public port 443 switch.${PLAIN}" "${GREEN}✅ TCP Peek 8444 Только после прохождения предварительной проверки он попадет в коммутатор публичной сети 443.${PLAIN}")"
}

preflight_entry_mode_before_cutover() {
    local target_mode="$1"
    target_mode=$(normalize_entry_mode_name "$target_mode") || return 1
    case "$target_mode" in
        "tcp-peek") preflight_tcppeek_before_cutover ;;
        *) return 0 ;;
    esac
}

normalize_entry_mode_name() {
    local mode="$1"
    case "$mode" in
        "nginx_stream"|"nginx-stream") echo "nginx-stream" ;;
        "xray_fallback"|"xray-fallback") echo "xray-fallback" ;;
        "tcp_peek"|"tcp-peek") echo "tcp-peek" ;;
        *) return 1 ;;
    esac
}

entry_mode_engine_name() {
    local mode="$1"
    mode=$(normalize_entry_mode_name "$mode") || return 1
    echo "$mode"
}

print_entry_mode_cutover_paths() {
    local target_mode="$1"
    echo -e "$(localized_text "${BOLD}将涉及的配置路径${PLAIN}" "${BOLD}Will involve the configuration path${PLAIN}" "${BOLD}будет включать путь конфигурации.${PLAIN}")"
    echo -e "Nginx：/etc/nginx/nginx.conf"
    echo -e "Nginx：/etc/nginx/stream.d/vps_sni_${NGINX_LISTEN_PORT}.conf"
    echo -e "Nginx：/etc/nginx/conf.d/00-vps-default-drop.conf"
    echo -e "Caddy：/etc/caddy/Caddyfile"
    echo -e "Caddy：/etc/caddy/conf.d/${PANEL_DOMAIN}.caddy"
    local site_domain
    for site_domain in "${SITE_DOMAINS[@]}"; do
        [[ -n "$site_domain" ]] && echo -e "Caddy：/etc/caddy/conf.d/${site_domain}.caddy"
    done
    echo -e "systemd：/etc/systemd/system/vpso-mux.service"
    echo -e "vpso-mux：$(vpso_mux_config_path)"
    echo -e "$(localized_text "状态：$(single_443_engine_state_path)" "Status: $(single_443_engine_state_path)" "Статус: $(single_443_engine_state_path)")"
    echo -e "$(localized_text "共享参数：/etc/vps-optimize/sni-stack.env" "Shared parameters: /etc/vps-optimize/sni-stack.env" "Общие параметры: /etc/vps-optimize/sni-stack.env")"
    if [[ "$target_mode" == "tcp-peek" ]]; then
        echo -e "$(localized_text "vpso-mux 状态：$(vpso_mux_status_json_path)" "vpso-mux Status: $(vpso_mux_status_json_path)" "Статус vpso-mux: $(vpso_mux_status_json_path)")"
    fi
}

print_preview_file_diff() {
    local actual_path="$1"
    local planned_path="$2"
    local title="$3"

    echo -e "${CYAN}--- ${title}${PLAIN}"
    if ! command -v diff >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}未检测到 diff 命令，无法显示文本差异。${PLAIN}" "${YELLOW}The diff command was not detected and text differences cannot be displayed.${PLAIN}" "${YELLOW}Команда diff не обнаружена, и текстовые различия не могут быть отображены.${PLAIN}")"
        return 0
    fi

    if [[ -f "$actual_path" && -f "$planned_path" ]]; then
        diff -u --label "$(localized_text "${actual_path} (当前)" "${actual_path} (current)" "${actual_path} (текущий)")" --label "$(localized_text "${actual_path} (预计)" "${actual_path} (estimated)" "${actual_path} (оценка)")" "$actual_path" "$planned_path" || true
    elif [[ -f "$actual_path" && ! -f "$planned_path" ]]; then
        diff -u --label "$(localized_text "${actual_path} (当前)" "${actual_path} (current)" "${actual_path} (текущий)")" --label "$(localized_text "${actual_path} (预计停用)" "${actual_path} (expected to be discontinued)" "${actual_path} (скорее всего, будет снят с производства)")" "$actual_path" /dev/null || true
    elif [[ ! -f "$actual_path" && -f "$planned_path" ]]; then
        diff -u --label "$(localized_text "${actual_path} (当前不存在)" "${actual_path} (does not currently exist)" "${actual_path} (в настоящее время не существует)")" --label "$(localized_text "${actual_path} (预计新增)" "${actual_path} (expected to be added)" "${actual_path} (ожидается добавление)")" /dev/null "$planned_path" || true
    else
        echo "$(localized_text "当前和预计都没有该文件。" "This file is neither currently nor expected to be available." "Этот файл в настоящее время недоступен и не ожидается, что он будет доступен.")"
    fi
    echo ""
}

write_entry_preview_caddyfile() {
    local output_file="$1"
    cat <<'EOF' > "$output_file"
{
    auto_https off
}

import conf.d/*
EOF
}

show_entry_mode_cutover_diff() {
    local target_mode="$1"
    local tmp_dir target_root target_caddy_dir target_nginx target_mux target_service target_caddyfile
    target_mode=$(normalize_entry_mode_name "$target_mode") || return 1
    tmp_dir=$(mktemp -d /tmp/vpso-entry-preview.XXXXXX) || return 1
    chmod 700 "$tmp_dir" 2>/dev/null || true
    target_root="${tmp_dir}/target"
    target_caddy_dir="${target_root}/etc/caddy/conf.d"
    mkdir -p "$target_caddy_dir" "${target_root}/etc/nginx/stream.d" "${target_root}/etc/vps-optimize" "${target_root}/etc/systemd/system"

    target_caddyfile="${target_root}/etc/caddy/Caddyfile"
    target_nginx="${target_root}/etc/nginx/stream.d/vps_sni_${NGINX_LISTEN_PORT}.conf"
    target_mux="${target_root}/etc/vps-optimize/vpso-mux.yaml"
    target_service="${target_root}/etc/systemd/system/vpso-mux.service"

    write_entry_preview_caddyfile "$target_caddyfile"
    write_caddy_panel_config "${target_caddy_dir}/${PANEL_DOMAIN}.caddy"
    write_caddy_site_config "$target_caddy_dir"

    if [[ "$target_mode" == "nginx-stream" ]]; then
        write_nginx_sni_stream_config "$target_nginx" "no"
    fi
    if [[ "$target_mode" == "tcp-peek" ]]; then
        write_vpso_mux_config_from_sni_stack "$NGINX_LISTEN_PORT" "$target_mux"
        write_vpso_mux_systemd_service "$target_service"
    else
        [[ -f "$(vpso_mux_config_path)" ]] && cp -a "$(vpso_mux_config_path)" "$target_mux" 2>/dev/null || true
        [[ -f /etc/systemd/system/vpso-mux.service ]] && cp -a /etc/systemd/system/vpso-mux.service "$target_service" 2>/dev/null || true
    fi

    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}443端口复用切换 diff 预览${PLAIN}" "${BOLD}Port 443 Reuse switch diff preview${PLAIN}" "${BOLD}443 Предварительный просмотр дифференциала переключения одной записи${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    print_preview_file_diff "/etc/caddy/Caddyfile" "$target_caddyfile" "Caddyfile"
    print_preview_file_diff "/etc/caddy/conf.d/${PANEL_DOMAIN}.caddy" "${target_caddy_dir}/${PANEL_DOMAIN}.caddy" "$(localized_text "Caddy 面板域名" "Caddy panel domain" "Доменное имя панели Caddy")"
    local site_domain
    for site_domain in "${SITE_DOMAINS[@]}"; do
        [[ -n "$site_domain" ]] || continue
        print_preview_file_diff "/etc/caddy/conf.d/${site_domain}.caddy" "${target_caddy_dir}/${site_domain}.caddy" "$(localized_text "Caddy 网站/反代 ${site_domain}" "Caddy website/reverse proxy ${site_domain}" "Caddy веб-сайт/обратный прокси ${site_domain}")"
    done
    print_preview_file_diff "/etc/nginx/stream.d/vps_sni_${NGINX_LISTEN_PORT}.conf" "$target_nginx" "$(localized_text "Nginx Stream 入口" "Nginx Stream entry" "Nginx Stream вход")"
    print_preview_file_diff "$(vpso_mux_config_path)" "$target_mux" "$(localized_text "vpso-mux 分流配置" "vpso-mux routing configuration" "Конфигурация маршрутизации vpso-mux")"
    print_preview_file_diff "/etc/systemd/system/vpso-mux.service" "$target_service" "vpso-mux systemd"
    echo -e "$(localized_text "${YELLOW}diff 预览只在临时目录生成目标文件，不会写入 /etc。临时目录：${tmp_dir}${PLAIN}" "${YELLOW}Diff preview only generates target files in the temporary directory and will not write to /etc. Temporary directory: ${tmp_dir}${PLAIN}" "${YELLOW}Предварительный просмотр diff создает целевые файлы только во временном каталоге и не записывает их в /etc. Временный каталог: ${tmp_dir}.${PLAIN}")"
}

preview_entry_mode_cutover() {
    local current_mode="$1"
    local target_mode="$2"
    local backup_dir="$3"
    local listener_info current_listener current_display expected_listener expected_display choice

    current_mode=$(normalize_entry_mode_name "$current_mode" 2>/dev/null || echo "$current_mode")
    target_mode=$(normalize_entry_mode_name "$target_mode") || return 1
    listener_info=$(detect_443_listener "$NGINX_LISTEN_PORT")
    current_listener="${listener_info%%|*}"
    current_display=$(entry_listener_display_name "$current_listener")
    expected_listener=$(entry_mode_expected_listener "$target_mode") || return 1
    expected_display=$(entry_listener_display_name "$expected_listener")

    while true; do
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}443端口复用切换变更预览${PLAIN}" "${BOLD}Port 443 Reuse switching change preview${PLAIN}" "${BOLD}443 Предварительный просмотр изменений коммутации на один вход${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "当前 ENTRY_MODE：${current_mode}" "Current ENTRY_MODE: ${current_mode}" "Текущий ENTRY_MODE: ${current_mode}")"
        echo -e "$(localized_text "目标 ENTRY_MODE：${target_mode}" "Target ENTRY_MODE: ${target_mode}" "Цель ENTRY_MODE: ${target_mode}")"
        echo -e "$(localized_text "当前 443 监听者：${current_display} (${listener_info#*|})" "Current 443 listener: ${current_display} (${listener_info#*|})" "Текущий прослушиватель 443: ${current_display} (${listener_info#*|})")"
        echo -e "$(localized_text "切换后预计监听者：${expected_display}" "Expected listener after switching: ${expected_display}" "Ожидаемый слушатель после переключения: ${expected_display}")"
        echo -e "$(localized_text "回滚点位置：${backup_dir}" "Rollback point position: ${backup_dir}" "Позиция точки отката: ${backup_dir}")"
        echo -e "------------------------------------------------"
        print_entry_mode_cutover_paths "$target_mode"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 查看 diff${PLAIN}" "${GREEN}1. View diff${PLAIN}" "${GREEN}1. Посмотреть разницу${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 继续切换${PLAIN}" "${GREEN}2. Continue to switch to${PLAIN}" "${GREEN}2. Продолжайте переходить на.${PLAIN}")"
        echo -e "$(localized_text "${RED}  0. 取消，不修改任何配置${PLAIN}" "${RED}0. Cancel without modifying any configuration${PLAIN}" "${RED}0. Отмена без изменения конфигурации.${PLAIN}")"
        read_trimmed choice "$(localized_text "请选择操作（默认 0 取消）: " "Please select an action (default 0 cancels):" "Пожалуйста, выберите действие (по умолчанию 0 отменяет):")"
        case "$(echo "${choice:-0}" | tr '[:upper:]' '[:lower:]')" in
            1|d|D|diff)
                show_entry_mode_cutover_diff "$target_mode"
                ;;
            2|y|yes)
                return 0
                ;;
            0|n|no|q)
                echo -e "$(localized_text "${BLUE}已取消 443 入口切换，未修改任何配置。${PLAIN}" "${BLUE}Canceled the 443 entry switch without modifying any configuration.${PLAIN}" "${BLUE}отменил входной переключатель 443 без изменения какой-либо конфигурации.${PLAIN}")"
                return 1
                ;;
            *)
                echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"
                ;;
        esac
    done
}

systemd_unit_exists() {
    local unit="$1"
    systemctl list-unit-files "$unit" >/dev/null 2>&1 || systemctl status "$unit" >/dev/null 2>&1
}

xray_entry_service_name() {
    local svc
    for svc in xray.service x-ui.service 3x-ui.service; do
        if systemd_unit_exists "$svc"; then
            echo "${svc%.service}"
            return 0
        fi
    done
    return 1
}

restart_xray_entry_service() {
    local svc
    svc=$(xray_entry_service_name) || { echo -e "$(localized_text "${RED}❌ 未检测到 xray/x-ui/3x-ui systemd 服务。${PLAIN}" "${RED}❌ xray/x-ui/3x-ui systemd service not detected.${PLAIN}" "${RED}❌ xray/x-ui/3x-ui Служба systemd не обнаружена.${PLAIN}")"; return 1; }
    systemctl enable "$svc" >/dev/null 2>&1 || true
    systemctl restart "$svc" || { echo -e "$(localized_text "${RED}❌ ${svc} 重启失败。${PLAIN}" "${RED}❌ ${svc} Restart failed.${PLAIN}" "${RED}❌ ${svc} Не удалось перезапустить.${PLAIN}")"; return 1; }
}

stop_xray_entry_service_if_public_443() {
    local listener svc
    listener=$(detect_443_listener)
    listener_info_has_entry "$listener" "xray" || return 0
    svc=$(xray_entry_service_name) || return 0
    if ! systemctl stop "$svc"; then
        echo -e "$(localized_text "${RED}❌ 停止 ${svc} 失败，公网 443 仍可能被 Xray 占用。${PLAIN}" "${RED}❌ Stop ${svc} failed, public port 443 may still be occupied by Xray.${PLAIN}" "${RED}❌ Не удалось остановить ${svc}, публичный порт 443 всё ещё может быть занят Xray.${PLAIN}")"
        return 1
    fi
    sleep 1
    listener=$(detect_443_listener)
    if listener_info_has_entry "$listener" "xray"; then
        echo -e "$(localized_text "${RED}❌ ${svc} 已执行停止，但 Xray 仍在监听公网 443，拒绝继续切换入口。${PLAIN}" "${RED}❌ ${svc} has been executed and stopped, but Xray is still listening on the public port 443 and refuses to continue switching entries.${PLAIN}" "${RED}❌ ${svc} был выполнен и остановлен, но Xray все еще прослушивает публичный порт 443 и отказывается продолжать переключение входов.${PLAIN}")"
        return 1
    fi
}

stop_vpso_mux_service_if_public_443() {
    local listener
    local had_public_listener=false

    listener=$(detect_443_listener)
    if listener_info_has_entry "$listener" "tcppeek"; then
        had_public_listener=true
    fi

    if ! systemctl cat vpso-mux.service >/dev/null 2>&1 && [[ ! -f /etc/systemd/system/vpso-mux.service ]]; then
        $had_public_listener || return 0
        echo -e "$(localized_text "${RED}❌ 检测到 TCP Peek 占用公网 443，但未找到 vpso-mux.service。${PLAIN}" "${RED}❌ It was detected that TCP Peek occupied public port 443, but vpso-mux.service was not found.${PLAIN}" "${RED}❌ Было обнаружено, что TCP Peek занимает публичный порт 443, но vpso-mux.service не найден.${PLAIN}")"
        print_vpso_mux_failure_context "$NGINX_LISTEN_PORT"
        return 1
    fi

    systemctl stop vpso-mux-preflight >/dev/null 2>&1 || true
    write_vpso_mux_systemd_service || return 1
    systemctl disable --now vpso-mux >/dev/null 2>&1 || true
    if systemctl is-active --quiet vpso-mux; then
        echo -e "$(localized_text "${RED}❌ 停止 vpso-mux 失败，公网 443 仍可能被 TCP Peek 占用。${PLAIN}" "${RED}❌ Failed to stop vpso-mux, public port 443 may still be occupied by TCP Peek.${PLAIN}" "${RED}❌ Не удалось остановить vpso-mux, публичный порт 443 всё ещё может быть занят TCP Peek.${PLAIN}")"
        print_vpso_mux_failure_context "$NGINX_LISTEN_PORT"
        return 1
    fi
    if systemctl is-enabled --quiet vpso-mux; then
        echo -e "$(localized_text "${RED}❌ 禁用 vpso-mux 开机启动失败，重启后可能再次抢占公网 443。${PLAIN}" "${RED}❌ Disable vpso-mux Failed to start at boot, and may seize the public again after restarting 443.${PLAIN}" "${RED}❌ Отключить vpso-mux Не удалось запуститься при загрузке, и может снова захватить публичную сеть после перезапуска 443.${PLAIN}")"
        return 1
    fi
    systemctl reset-failed vpso-mux >/dev/null 2>&1 || true

    if $had_public_listener; then
        sleep 1
    fi
    listener=$(detect_443_listener)
    if listener_info_has_entry "$listener" "tcppeek"; then
        echo -e "$(localized_text "${RED}❌ vpso-mux 已执行停止并禁用，但 TCP Peek 仍在监听公网 443，拒绝继续切换入口。${PLAIN}" "${RED}❌ vpso-mux has been stopped and disabled, but TCP Peek is still listening on the public port 443 and refuses to continue switching entries.${PLAIN}" "${RED}❌ vpso-mux остановлен и отключен, но TCP Peek все еще прослушивает публичный порт 443 и отказывается продолжать переключение входов.${PLAIN}")"
        print_vpso_mux_failure_context "$NGINX_LISTEN_PORT"
        return 1
    fi
    echo -e "$(localized_text "${YELLOW}ℹ️ 已停止并禁用 vpso-mux 开机启动；非 TCP Peek 模式重启后不会抢占公网 443。${PLAIN}" "${YELLOW}ℹ️ Stopped and disabled vpso-mux startup; non-TCP Peek mode will not seize the public after restarting 443.${PLAIN}" "${YELLOW}ℹ️ Остановлен и отключен запуск vpso-mux; Режим, отличный от TCP Peek, не будет захватывать публичную сеть после перезапуска 443.${PLAIN}")"
}

stop_caddy_service_if_public_443() {
    local listener
    listener=$(detect_443_listener)
    listener_info_has_entry "$listener" "caddy" || return 0
    if ! systemctl stop caddy; then
        echo -e "$(localized_text "${RED}❌ 停止 caddy 失败，公网 443 仍可能被 Caddy 占用。${PLAIN}" "${RED}❌ Failed to stop caddy, public port 443 may still be occupied by Caddy.${PLAIN}" "${RED}❌ Не удалось остановить caddy, публичный порт 443 всё ещё может быть занят Caddy.${PLAIN}")"
        return 1
    fi
    sleep 1
    listener=$(detect_443_listener)
    if listener_info_has_entry "$listener" "caddy"; then
        echo -e "$(localized_text "${RED}❌ caddy 已执行停止，但仍在监听公网 443，拒绝继续切换入口。${PLAIN}" "${RED}❌ caddy has been stopped, but is still listening on the public port 443 and refuses to continue switching entries.${PLAIN}" "${RED}❌ caddy остановлен, но продолжает контролировать публичную сеть 443 и отказывается продолжать переключение входов.${PLAIN}")"
        return 1
    fi
}

disable_nginx_stream_public_443() {
    local nginx_conf="/etc/nginx/stream.d/vps_sni_${NGINX_LISTEN_PORT}.conf"
    local listener
    [[ -e "$nginx_conf" ]] && quarantine_path "$nginx_conf" "/etc/vps-optimize/quarantine/nginx-sni" >/dev/null 2>&1 || true
    if command -v nginx >/dev/null 2>&1; then
        if ! nginx -t; then
            print_nginx_stream_failure_context "$NGINX_LISTEN_PORT"
            return 1
        fi
        if ! restart_service_if_available nginx; then
            print_nginx_stream_failure_context "$NGINX_LISTEN_PORT"
            return 1
        fi
        sleep 1
        listener=$(detect_443_listener)
        if listener_info_has_entry "$listener" "nginx"; then
            echo -e "$(localized_text "${RED}❌ Nginx Stream 443 配置已移除，但 nginx 仍在监听公网 443，拒绝继续切换入口。${PLAIN}" "${RED}❌ Nginx Stream 443 configuration has been removed, but nginx is still listening on the public port 443 and refuses to continue switching entries.${PLAIN}" "${RED}Конфигурация ❌ Nginx Stream 443 удалена, но nginx по-прежнему прослушивает публичный порт 443 и отказывается продолжать переключение входов.${PLAIN}")"
            print_nginx_stream_failure_context "$NGINX_LISTEN_PORT"
            return 1
        fi
        if systemctl is-active --quiet nginx; then
            echo -e "$(localized_text "${YELLOW}ℹ️ nginx 服务仍在运行，但已不监听公网 ${NGINX_LISTEN_PORT}；这是允许的，端口复用只要求公网 443 由目标入口独占。${PLAIN}" "${YELLOW}ℹ️ nginx The service is still running, but it is no longer listening on the public ${NGINX_LISTEN_PORT}; this is allowed, and the Port 443 Reuse only requires that public port 443 be exclusively occupied by the target entry.${PLAIN}" "${YELLOW}ℹ️ nginx Служба все еще работает, но больше не прослушивает публичную сеть ${NGINX_LISTEN_PORT}; это разрешено, и для повторного использования порта 443 требуется только, чтобы публичный порт 443 был занята исключительно целевым входом.${PLAIN}")"
        fi
    fi
}

stop_public_443_entry_services_for_target() {
    local target_mode="$1"
    target_mode=$(normalize_entry_mode_name "$target_mode") || return 1
    quarantine_legacy_nginx_https_proxy_configs
    stop_caddy_service_if_public_443 || return 1

    if [[ "$target_mode" != "nginx-stream" ]]; then
        disable_nginx_stream_public_443 || return 1
    fi
    if [[ "$target_mode" != "tcp-peek" ]]; then
        stop_vpso_mux_service_if_public_443 || return 1
    fi
    if [[ "$target_mode" != "xray-fallback" ]]; then
        stop_xray_entry_service_if_public_443 || return 1
    fi
}

guard_current_ssh_not_on_entry_port() {
    local action_name="$(localized_text "${1:-入口模式切换}" "${1:-入口模式切换}" "${1:-入口模式切换}")"
    local ssh_server_port
    if [[ -z "${SSH_CONNECTION:-}" ]]; then
        return 0
    fi
    ssh_server_port=$(printf '%s\n' "$SSH_CONNECTION" | awk '{print $4}')
    if [[ -n "$ssh_server_port" && "$ssh_server_port" == "${NGINX_LISTEN_PORT:-443}" ]]; then
        echo -e "$(localized_text "${RED}❌ 检测到当前 SSH 会话连接在入口端口 ${ssh_server_port}。${PLAIN}" "${RED}❌ Detected the current SSH session connected on ingress port ${ssh_server_port}.${PLAIN}" "${RED}❌ Обнаружен текущий сеанс SSH, подключенный к входному порту ${ssh_server_port}.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}${action_name} 会重启或替换该端口的入口服务，继续执行会直接断开当前 SSH。${PLAIN}" "${YELLOW}${action_name} will restart or replace the entry service of the port. Continued execution will directly disconnect the current SSH.${PLAIN}" "${YELLOW}${action_name} перезапустит или заменит службу входа в порт. Продолжение выполнения приведет к непосредственному отключению текущего SSH.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}请改用云厂商 VNC/Serial Console，或先用非 ${ssh_server_port} 的 SSH 端口登录后再执行。${PLAIN}" "${YELLOW}Please use the cloud vendor VNC/Serial Console instead, or log in using the SSH port other than ${ssh_server_port} before executing.${PLAIN}" "${YELLOW}Вместо этого используйте VNC/Serial Console поставщика облака или войдите в систему, используя порт SSH, отличный от ${ssh_server_port}, перед выполнением.${PLAIN}")"
        return 1
    fi
}

verify_public_443_listener_for_mode() {
    local mode="$1"
    local expected listener i
    local tries="${2:-10}"
    local delay="${3:-0.5}"
    mode=$(normalize_entry_mode_name "$mode") || return 1
    expected=$(entry_mode_expected_listener "$mode") || return 1

    for ((i = 1; i <= tries; i++)); do
        listener=$(detect_443_listener "$NGINX_LISTEN_PORT")
        if listener_info_has_entry "$listener" "$expected"; then
            return 0
        fi
        [[ "$i" -lt "$tries" ]] && sleep "$delay"
    done

    echo -e "$(localized_text "${RED}❌ 公网 443 监听不符合 ${mode}：期望 ${expected}，实际 ${listener#*|}${PLAIN}" "${RED}❌ public port 443 listening does not comply with ${mode}: expected ${expected}, actual ${listener#*|}${PLAIN}" "${RED}❌ прослушивание публичного порта 443 не соответствует ${mode}: ожидается ${expected}, факт ${listener#*|}${PLAIN}")"
    return 1
}

print_nginx_stream_failure_context() {
    local port="${1:-$NGINX_LISTEN_PORT}"
    local conf_file="/etc/nginx/stream.d/vps_sni_${port}.conf"
    echo -e "$(localized_text "${YELLOW}▶ Nginx Stream 未能稳定监听 ${port}，下面是最近状态和配置线索：${PLAIN}" "${YELLOW}▶ Nginx Stream failed to monitor ${port} stably. The following is the latest status and configuration clues:${PLAIN}" "${YELLOW}▶ Nginx Stream не удалось стабильно контролировать ${port}. Ниже приведены последние сведения о состоянии и конфигурации:.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}▶ 期望配置文件：${conf_file}${PLAIN}" "${YELLOW}▶ Expected profile: ${conf_file}${PLAIN}" "${YELLOW}▶ Ожидаемый профиль: ${conf_file}${PLAIN}")"
    if [[ -s "$conf_file" ]]; then
        sed -n '1,180p' "$conf_file" 2>/dev/null || true
    else
        echo -e "$(localized_text "${RED}❌ ${conf_file} 不存在或为空。${PLAIN}" "${RED}❌ ${conf_file} does not exist or is empty.${PLAIN}" "${RED}❌ ${conf_file} не существует или пуст.${PLAIN}")"
    fi
    echo -e "$(localized_text "${YELLOW}▶ nginx.conf 中的 stream/include 线索：${PLAIN}" "${YELLOW}▶ stream/include clue in nginx.conf:${PLAIN}" "${YELLOW}▶ трансляция/включение подсказки в nginx.conf:${PLAIN}")"
    grep -nE '^[[:space:]]*(stream[[:space:]]*\{|include[[:space:]]+/etc/nginx/stream\.d/\*\.conf;|include[[:space:]]+/etc/nginx/modules-enabled/\*\.conf;)' /etc/nginx/nginx.conf 2>/dev/null || true
    echo -e "$(localized_text "${YELLOW}▶ nginx -T 是否加载该 stream 文件：${PLAIN}" "${YELLOW}▶ nginx -T Whether to load the stream file:${PLAIN}" "${YELLOW}▶ nginx -T Загружать ли файл потока:${PLAIN}")"
    if nginx -T 2>&1 | grep -Fq "$conf_file"; then
        echo -e "$(localized_text "${GREEN}✅ nginx -T 已加载 ${conf_file}${PLAIN}" "${GREEN}✅ nginx -T Loaded ${conf_file}${PLAIN}" "${GREEN}✅ nginx -T Загружен ${conf_file}${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ nginx -T 未加载 ${conf_file}${PLAIN}" "${RED}❌ nginx -T not loaded ${conf_file}${PLAIN}" "${RED}❌ nginx -T не загружен ${conf_file}${PLAIN}")"
    fi
    echo -e "$(localized_text "${YELLOW}▶ nginx 服务状态：${PLAIN}" "${YELLOW}▶ nginx Service status:${PLAIN}" "${YELLOW}▶ nginx Статус сервиса:${PLAIN}")"
    systemctl status nginx --no-pager -l 2>/dev/null || true
    echo -e "$(localized_text "${YELLOW}▶ 最近 40 行 nginx 日志：${PLAIN}" "${YELLOW}▶ Last 40 lines nginx Log:${PLAIN}" "${YELLOW}▶ Последние 40 строк nginx Журнал:${PLAIN}")"
    journalctl -u nginx -n 40 --no-pager 2>/dev/null || true
    echo -e "$(localized_text "${YELLOW}▶ 当前 ${port} 监听情况：${PLAIN}" "${YELLOW}▶ Current listening status of ${port}:${PLAIN}" "${YELLOW}▶ Текущий статус прослушивания ${port}:${PLAIN}")"
    if command -v ss >/dev/null 2>&1; then
        ss -lntp 2>/dev/null | awk -v p=":${port}" '$4 ~ p"$" {print}' || true
    else
        netstat -lntp 2>/dev/null | awk -v p=":${port}" '$4 ~ p"$" {print}' || true
    fi
}

assert_nginx_stream_config_loaded() {
    local port="${1:-$NGINX_LISTEN_PORT}"
    local conf_file="/etc/nginx/stream.d/vps_sni_${port}.conf"

    if [[ ! -s "$conf_file" ]]; then
        echo -e "$(localized_text "${RED}❌ Nginx Stream 配置未生成或为空：${conf_file}${PLAIN}" "${RED}❌ Nginx Stream Configuration is not generated or empty: ${conf_file}${PLAIN}" "${RED}❌ Nginx Stream Конфигурация не создана или пуста: ${conf_file}${PLAIN}")"
        print_nginx_stream_failure_context "$port"
        return 1
    fi
    if ! nginx -T 2>&1 | grep -Fq "$conf_file"; then
        echo -e "$(localized_text "${RED}❌ Nginx 主配置没有实际加载 ${conf_file}，拒绝继续。${PLAIN}" "${RED}❌ Nginx The main configuration has not actually loaded ${conf_file}, refusing to continue.${PLAIN}" "${RED}❌ Nginx Основная конфигурация фактически не загрузила ${conf_file}, отказываясь продолжать работу.${PLAIN}")"
        print_nginx_stream_failure_context "$port"
        return 1
    fi
}

check_entry_mode_dependencies() {
    local mode="$1"
    mode=$(normalize_entry_mode_name "$mode") || { echo -e "$(localized_text "${RED}❌ 目标入口模式无效：${mode}${PLAIN}" "${RED}❌ Invalid target entry mode: ${mode}${PLAIN}" "${RED}❌ Неверный режим ввода цели: ${mode}${PLAIN}")"; return 1; }
    assert_web_proxy_whitelist_supported "$mode" "${WEB_PROXY_ENGINE:-caddy}" || return 1

    case "$mode" in
        "nginx-stream")
            command -v nginx >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}未检测到 Nginx，切换时会沿用现有 Nginx stream 安装逻辑。${PLAIN}" "${YELLOW}Does not detect Nginx, and the existing Nginx stream installation logic will be used when switching.${PLAIN}" "${YELLOW}не обнаруживает Nginx, и при переключении будет использоваться существующая логика установки Nginx stream.${PLAIN}")"
            if [[ "$(current_web_proxy_engine)" == "caddy" ]]; then
                command -v caddy >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}未检测到 Caddy，切换时会沿用现有 Caddy 安装逻辑。${PLAIN}" "${YELLOW}Does not detect Caddy, and the existing Caddy installation logic will be used when switching.${PLAIN}" "${YELLOW}не обнаруживает Caddy, и при переключении будет использоваться существующая логика установки Caddy.${PLAIN}")"
            fi
            ;;
        "tcp-peek")
            require_vpso_mux_binary_for_cutover || return 1
            if [[ "$(current_web_proxy_engine)" == "caddy" ]]; then
                command -v caddy >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}未检测到 Caddy，切换时会沿用现有 Caddy 安装逻辑。${PLAIN}" "${YELLOW}Does not detect Caddy, and the existing Caddy installation logic will be used when switching.${PLAIN}" "${YELLOW}не обнаруживает Caddy, и при переключении будет использоваться существующая логика установки Caddy.${PLAIN}")"
            fi
            ;;
        "xray-fallback")
            xray_entry_service_name >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ 未检测到 xray/x-ui/3x-ui systemd 服务，拒绝切换。${PLAIN}" "${RED}❌ xray/x-ui/3x-ui systemd service not detected, switching refused.${PLAIN}" "${RED}❌ xray/x-ui/3x-ui Служба systemd не обнаружена, в переключении отказано.${PLAIN}")"; return 1; }
            if [[ "$(current_web_proxy_engine)" == "caddy" ]]; then
                command -v caddy >/dev/null 2>&1 || echo -e "$(localized_text "${YELLOW}未检测到 Caddy，切换时会沿用现有 Caddy 安装逻辑。${PLAIN}" "${YELLOW}Does not detect Caddy, and the existing Caddy installation logic will be used when switching.${PLAIN}" "${YELLOW}не обнаруживает Caddy, и при переключении будет использоваться существующая логика установки Caddy.${PLAIN}")"
            fi
            ;;
    esac
}

backup_entry_mode_config() {
    local backup_dir="${1:-}" service_path svc listener_info
    create_sni_stack_backup "$backup_dir" >/dev/null
    backup_dir=$(cat /etc/vps-optimize/sni-stack.last-backup 2>/dev/null)
    [[ -n "$backup_dir" && -d "$backup_dir" ]] || { echo -e "$(localized_text "${RED}❌ 入口模式切换备份失败。${PLAIN}" "${RED}❌ Entry mode switching backup failed.${PLAIN}" "${RED}❌ Не удалось переключить режим входа в резервную копию.${PLAIN}")"; return 1; }

    mkdir -p "$backup_dir/systemd" "$backup_dir/xray" "$backup_dir/vps-optimize"
    for svc in nginx.service caddy.service xray.service x-ui.service 3x-ui.service vpso-mux.service; do
        for service_path in "/etc/systemd/system/$svc" "/lib/systemd/system/$svc" "/usr/lib/systemd/system/$svc"; do
            [[ -f "$service_path" ]] && cp -a "$service_path" "$backup_dir/systemd/${service_path//\//_}" 2>/dev/null || true
        done
    done
    [[ -f /etc/xray/config.json ]] && cp -a /etc/xray/config.json "$backup_dir/xray/etc-xray-config.json" 2>/dev/null || true
    [[ -f /usr/local/etc/xray/config.json ]] && cp -a /usr/local/etc/xray/config.json "$backup_dir/xray/usr-local-etc-xray-config.json" 2>/dev/null || true
    [[ -f /etc/vps-optimize/xray-sni-routes.conf ]] && cp -a /etc/vps-optimize/xray-sni-routes.conf "$backup_dir/vps-optimize/xray-sni-routes.conf" 2>/dev/null || true
    listener_info=$(detect_443_listener)
    {
        echo "created_at=$(date -Is 2>/dev/null || date)"
        echo "entry_mode=$(get_entry_mode)"
        echo "listener=${listener_info}"
        echo "ss_443:"
        ss -lntp 2>/dev/null | grep -E '(:443[[:space:]]|:443$)' || echo "none"
    } > "$backup_dir/vps-optimize/443-listener-state.txt"
    echo "$backup_dir"
}

stop_vpso_mux_services_for_restore() {
    echo -e "$(localized_text "${YELLOW}▶ 正在停止 vpso-mux 相关服务，避免覆盖运行中的分流器二进制...${PLAIN}" "${YELLOW}▶ Stopping vpso-mux related services to avoid overwriting the running routing binary...${PLAIN}" "${YELLOW}▶ Остановка служб, связанных с vpso-mux, чтобы избежать перезаписи работающего двоичного файла маршрутизации...${PLAIN}")"
    systemctl stop vpso-mux-preflight >/dev/null 2>&1 || true
    systemctl stop vpso-mux >/dev/null 2>&1 || true
    sleep 1
}

rollback_last_entry_mode() {
    local backup_dir="${1:-}"
    local manual=0
    local old_mode=""
    if [[ -z "$backup_dir" ]]; then
        manual=1
        backup_dir=$(cat /etc/vps-optimize/sni-stack.last-backup 2>/dev/null)
    fi
    if [[ -z "$backup_dir" || ! -d "$backup_dir" ]]; then
        echo -e "$(localized_text "${RED}❌ 未找到可回滚的入口模式备份。${PLAIN}" "${RED}❌ No rollbackable entry mode backup found.${PLAIN}" "${RED}❌ Не найдена резервная копия в режим входа с возможностью отката.${PLAIN}")"
        return 1
    fi
    if [[ -f "$backup_dir/vps-optimize/sni-stack.env" ]]; then
        old_mode=$(
            # shellcheck disable=SC1090
            unset ENTRY_MODE
            source "$backup_dir/vps-optimize/sni-stack.env" 2>/dev/null || true
            printf '%s' "${ENTRY_MODE:-nginx-stream}"
        )
        old_mode=$(normalize_entry_mode_name "$old_mode" 2>/dev/null || echo "nginx-stream")
    fi

    if [[ "$manual" -eq 1 ]]; then
        confirm_risk_action "$(localized_text "回滚上一次 443 入口模式切换" "Roll back the last 443 entry mode switch" "Откатить последний переключатель режима входа 443")" \
            "$(localized_text "Nginx/Caddy/Xray/vpso-mux 入口相关配置和服务状态" "Nginx/Caddy/Xray/vpso-mux entry-related configuration and service status" "Nginx/Caddy/Xray/vpso-mux конфигурация и состояние службы, связанные с точкой входа")" \
            "$(localized_text "再次切换入口模式，或用备份目录手动恢复" "Switch to entry mode again, or restore manually using the backup directory" "Снова переключитесь в режим входа или восстановите вручную, используя каталог резервной копии.")" \
            "$(localized_text "将使用备份目录 ${backup_dir} 覆盖当前入口配置。" "The current entry configuration will be overwritten with the backup directory ${backup_dir}." "Текущая конфигурация входа будет перезаписана резервным каталогом ${backup_dir}.")" || return 1
    fi

    echo -e "$(localized_text "${YELLOW}▶ 正在回滚上一次入口模式切换：${backup_dir}${PLAIN}" "${YELLOW}▶ Rolling back the last entry mode switch: ${backup_dir}${PLAIN}" "${YELLOW}▶ Откат последнего переключателя режима входа: ${backup_dir}${PLAIN}")"
    stop_vpso_mux_services_for_restore
    restore_sni_stack_backup_files "$backup_dir" || { echo -e "$(localized_text "${RED}❌ 回滚文件恢复失败。${PLAIN}" "${RED}❌ Rollback file recovery failed.${PLAIN}" "${RED}❌ Не удалось выполнить откат восстановления файла.${PLAIN}")"; return 1; }
    systemctl daemon-reload >/dev/null 2>&1 || true
    load_sni_stack_env >/dev/null 2>&1 || true
    old_mode=${old_mode:-$(get_entry_mode)}

    if ! stop_public_443_entry_services_for_target "$old_mode"; then
        echo -e "$(localized_text "${RED}❌ 回滚时未能停止冲突的公网 443 入口服务，请查看上面的诊断。${PLAIN}" "${RED}❌ The conflicting public port 443 entry service failed to stop during rollback, please check the diagnosis above.${PLAIN}" "${RED}❌ Не удалось остановить конфликтующую служба входа публичного порта 443 во время отката. Просмотрите диагностику выше.${PLAIN}")"
        return 1
    fi
    if ! apply_entry_mode_by_name "$old_mode" "$backup_dir"; then
        echo -e "$(localized_text "${RED}❌ 回滚到 ${old_mode} 时未能恢复公网 443 监听，请查看上面的诊断。${PLAIN}" "${RED}❌ Failed to restore public port 443 listening when rolling back to ${old_mode}, please check the diagnosis above.${PLAIN}" "${RED}❌ Не удалось восстановить прослушивание публичного порта 443 при откате к ${old_mode}, проверьте диагностику выше.${PLAIN}")"
        return 1
    fi
    set_entry_mode "$old_mode" >/dev/null 2>&1 || true
    write_single_443_engine_state "$(entry_mode_engine_name "$old_mode" 2>/dev/null || echo nginx-stream)" "$backup_dir"
    echo -e "$(localized_text "${GREEN}✅ 已回滚到上一次入口模式：${old_mode}${PLAIN}" "${GREEN}✅ Has rolled back to the last entry mode: ${old_mode}${PLAIN}" "${GREEN}✅ Откатился к последнему режиму входа: ${old_mode}${PLAIN}")"
}

apply_nginx_stream_mode() {
    local backup_dir="${1:-}"
    install_nginx_stream_stack || return 1
    harden_nginx_public_errors
    apply_web_proxy_configs_for_single_443 || return 1
    cleanup_old_nginx_sni_stream_configs
    write_nginx_sni_stream_config || return 1
    assert_nginx_stream_config_loaded "$NGINX_LISTEN_PORT" || return 1
    if [[ "$(current_web_proxy_engine)" == "caddy" ]]; then
        restart_web_proxy_for_single_443 || return 1
    fi
    if ! systemctl enable nginx >/dev/null 2>&1; then
        echo -e "$(localized_text "${RED}❌ nginx 开机启动设置失败，拒绝将本次启动误报为可持久入口。${PLAIN}" "${RED}❌ nginx The startup setting failed and the startup was rejected as a persistent entry.${PLAIN}" "${RED}❌ nginx Не удалось настроить запуск, и запуск был отклонен как постоянная запись.${PLAIN}")"
        return 1
    fi
    if ! systemctl restart nginx; then
        print_nginx_stream_failure_context "$NGINX_LISTEN_PORT"
        return 1
    fi
    if ! verify_public_443_listener_for_mode "nginx-stream"; then
        print_nginx_stream_failure_context "$NGINX_LISTEN_PORT"
        return 1
    fi
    probe_tls_sni_certificate "$(localized_text "Nginx Stream 面板 SNI" "Nginx Stream panel SNI" "Панель Nginx Stream SNI")" "$(probe_host_for_listen_addr "$NGINX_LISTEN_ADDR")" "$NGINX_LISTEN_PORT" "$PANEL_DOMAIN" || return 1
    tcp_probe_host "$(localized_text "$(web_proxy_engine_label) 本地 TLS" "$(web_proxy_engine_label) local TLS" "$(web_proxy_engine_label) локальный TLS")" "$(probe_host_for_listen_addr "$CADDY_LISTEN_ADDR")" "$CADDY_LISTEN_PORT" || return 1
    if xray_entry_service_name >/dev/null 2>&1; then
        restart_xray_entry_service || echo -e "$(localized_text "${YELLOW}⚠️ Xray/3x-ui 服务重启失败；Nginx Stream/Web 入口已恢复，请单独检查 Xray 入站。${PLAIN}" "${YELLOW}⚠️ Xray/3x-ui service failed to restart; Nginx Stream/Web entry has been restored, please check Xray inbound separately.${PLAIN}" "${YELLOW}⚠️ Службу Xray/3x-ui не удалось перезапустить; Вход Nginx Stream/Web восстановлен, проверьте входящий Xray отдельно.${PLAIN}")"
    fi
    if ! tcp_probe_host "$(localized_text "Xray/REALITY 本地入站" "Xray/REALITY local inbound" "Xray/REALITY локальное входящее подключение")" "$(probe_host_for_listen_addr "$XRAY_LISTEN_ADDR")" "$XRAY_LISTEN_PORT" 6 1; then
        echo -e "$(localized_text "${YELLOW}⚠️ Nginx Stream/Web 入口已恢复，但 Xray/REALITY 本地入站未连通。${PLAIN}" "${YELLOW}⚠️ Nginx Stream/Web ingress has been restored, but Xray/REALITY local inbound is not connected.${PLAIN}" "${YELLOW}⚠️ Вход Nginx Stream/Web восстановлен, но локальное входящее подключение Xray/REALITY не подключен.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}请在 3x-ui/Xray 确认本地入站正在监听 ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}，或把脚本里的 Xray 本地端口改成实际值。${PLAIN}" "${YELLOW}Please confirm that the local inbound port is listening ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT} at 3x-ui/Xray, or change the Xray local port in the script to the actual value.${PLAIN}" "${YELLOW}Подтвердите, что локальный входящий порт прослушивает ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT} по адресу 3x-ui/Xray, или измените локальный порт Xray в сценарии на фактическое значение.${PLAIN}")"
    fi
    write_single_443_engine_state "nginx-stream" "$backup_dir"
}

apply_tcppeek_mode() {
    local backup_dir="${1:-}"
    local tmp_config
    require_vpso_mux_binary_for_cutover || return 1
    warn_if_public_bind "$(web_proxy_engine_label)" "$CADDY_LISTEN_ADDR" "$CADDY_LISTEN_PORT" || return 1
    warn_if_public_bind "Xray REALITY" "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT" || return 1
    apply_web_proxy_configs_for_single_443 || return 1
    restart_web_proxy_for_single_443 || return 1
    tmp_config="/etc/vps-optimize/vpso-mux.yaml.tmp.$$"
    write_vpso_mux_config_from_sni_stack "$NGINX_LISTEN_PORT" "$tmp_config" || return 1
    run_vpso_mux_config_check "$tmp_config" || { quarantine_path "$tmp_config" "/etc/vps-optimize/quarantine/vpso-mux" >/dev/null 2>&1 || true; return 1; }
    set_entry_mode "tcp-peek" || return 1
    write_vpso_mux_systemd_service
    mv "$tmp_config" "$(vpso_mux_config_path)" || return 1
    if ! systemctl enable vpso-mux >/dev/null 2>&1; then
        echo -e "$(localized_text "${RED}❌ vpso-mux 开机启动设置失败，拒绝将本次启动误报为可持久入口。${PLAIN}" "${RED}❌ vpso-mux The startup setting failed and the startup was rejected as a persistent entry.${PLAIN}" "${RED}❌ vpso-mux Не удалось настроить запуск, и запуск был отклонен как постоянная запись.${PLAIN}")"
        return 1
    fi
    if ! systemctl restart vpso-mux; then
        print_vpso_mux_failure_context "$NGINX_LISTEN_PORT"
        return 1
    fi
    if ! verify_public_443_listener_for_mode "tcp-peek"; then
        print_vpso_mux_failure_context "$NGINX_LISTEN_PORT"
        return 1
    fi
    probe_tls_sni_certificate "$(localized_text "TCP Peek 面板 SNI" "TCP Peek panel SNI" "Панель TCP Peek SNI")" "$(probe_host_for_listen_addr "$NGINX_LISTEN_ADDR")" "$NGINX_LISTEN_PORT" "$PANEL_DOMAIN" || return 1
    tcp_probe_host "$(localized_text "$(web_proxy_engine_label) 本地 TLS" "$(web_proxy_engine_label) local TLS" "$(web_proxy_engine_label) локальный TLS")" "$(probe_host_for_listen_addr "$CADDY_LISTEN_ADDR")" "$CADDY_LISTEN_PORT" || return 1
    if xray_entry_service_name >/dev/null 2>&1; then
        restart_xray_entry_service || return 1
    fi
    tcp_probe_host "$(localized_text "Xray/REALITY 本地入站" "Xray/REALITY local inbound" "Xray/REALITY локальное входящее подключение")" "$(probe_host_for_listen_addr "$XRAY_LISTEN_ADDR")" "$XRAY_LISTEN_PORT" 6 1 || return 1
    write_single_443_engine_state "tcp-peek" "$backup_dir"
}

apply_xray_fallback_mode() {
    local backup_dir="${1:-}"
    apply_web_proxy_configs_for_single_443 || return 1
    restart_web_proxy_for_single_443 || return 1
    restart_xray_entry_service || return 1
    verify_public_443_listener_for_mode "xray-fallback" || return 1
    tcp_probe_host "$(localized_text "$(web_proxy_engine_label) fallback 后端" "$(web_proxy_engine_label) fallback backend" "Резервный сервер $(web_proxy_engine_label)")" "$(probe_host_for_listen_addr "$CADDY_LISTEN_ADDR")" "$CADDY_LISTEN_PORT" || return 1
    probe_tls_sni_certificate "$(localized_text "Xray Fallback 面板 SNI" "Xray Fallback panel SNI" "Xray Резервная панель SNI")" "$(probe_host_for_listen_addr "$NGINX_LISTEN_ADDR")" "$NGINX_LISTEN_PORT" "$PANEL_DOMAIN" || return 1
    write_single_443_engine_state "xray-fallback" "$backup_dir"
}

apply_entry_mode_by_name() {
    local target_mode="$1"
    local backup_dir="${2:-}"
    target_mode=$(normalize_entry_mode_name "$target_mode") || return 1
    case "$target_mode" in
        "nginx-stream") apply_nginx_stream_mode "$backup_dir" ;;
        "xray-fallback") apply_xray_fallback_mode "$backup_dir" ;;
        "tcp-peek") apply_tcppeek_mode "$backup_dir" ;;
    esac
}

select_initial_entry_mode() {
    local choice
    ENTRY_MODE="nginx-stream"

    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}选择 443 入口模式${PLAIN}" "${BOLD}Select the 443 entry mode${PLAIN}" "${BOLD}Выберите режим входа 443${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${GREEN}  1. Nginx Stream 模式${PLAIN}       ${YELLOW}(默认稳定模式，适合大多数用户)${PLAIN}" "${GREEN}1. Nginx Stream mode (default stable mode, suitable for most users)${PLAIN}" "${GREEN}1. Режим Nginx Stream (стабильный режим по умолчанию, подходит для большинства пользователей)${PLAIN}")"
    echo -e "$(localized_text "${GREEN}  2. Xray Fallback 模式${PLAIN}      ${YELLOW}(需你已在 Xray/3x-ui 准备好公网 443 主入站)${PLAIN}" "${GREEN}2. Xray Fallback mode (you need to prepare the public port 443 main inbound in Xray/3x-ui)${PLAIN}" "${GREEN}2. Xray Резервный режим (необходимо подготовить основное входящее подключение публичного порта 443 в Xray/3x-ui)${PLAIN}")"
    echo -e "$(localized_text "${GREEN}  3. TCP Peek + Splice 模式${PLAIN}  ${YELLOW}(自动安装依赖、8444 预检并切换)${PLAIN}" "${GREEN}3. TCP Peek + Splice mode (installs dependencies, runs the 8444 preflight, then switches)${PLAIN}" "${GREEN}3. TCP Peek + Splice (установка зависимостей, проверка 8444 и переключение)${PLAIN}")"
    echo -e "$(localized_text "${RED}  0. 取消${PLAIN}" "${RED}0. Cancel${PLAIN}" "${RED}0. Отмена${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    read_trimmed choice "$(localized_text "请选择入口模式（默认 1）: " "Please select entry mode (default 1):" "Пожалуйста, выберите режим входа (по умолчанию 1):")"
    case "${choice:-1}" in
        1) ENTRY_MODE="nginx-stream" ;;
        2) ENTRY_MODE="xray-fallback" ;;
        3) ENTRY_MODE="tcp-peek" ;;
        0|q|Q) echo -e "$(localized_text "${BLUE}已取消首次配置。${PLAIN}" "${BLUE}Initial setup canceled.${PLAIN}" "${BLUE}Первоначальная настройка отменена.${PLAIN}")"; return 1 ;;
        *) echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"; return 1 ;;
    esac
    echo -e "$(localized_text "${GREEN}✅ 已选择 443 入口模式：${ENTRY_MODE}${PLAIN}" "${GREEN}✅ 443 entry mode selected: ${ENTRY_MODE}${PLAIN}" "${GREEN}Выбран 443 режима входа: ${ENTRY_MODE}${PLAIN}")"
}

manage_entry_mode_install_or_switch() {
    local choice current_mode
    if [[ ! -f /etc/vps-optimize/sni-stack.env ]]; then
        func_caddy_cf_reality_wizard
        return
    fi

    load_sni_stack_env || return 1
    current_mode=$(get_entry_mode)
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}安装 / 切换 443 入口模式${PLAIN}" "${BOLD}Install / switch the 443 entry mode${PLAIN}" "${BOLD}Установка / смена режима входа 443${PLAIN}")"
    echo -e "$(localized_text "当前：${GREEN}${current_mode}${PLAIN}" "Current: ${GREEN}${current_mode}${PLAIN}" "Текущий: ${GREEN}${current_mode}${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "${GREEN}  1. Nginx Stream${PLAIN}"
    echo -e "${GREEN}  2. Xray Fallback${PLAIN}"
    echo -e "${GREEN}  3. TCP Peek + Splice${PLAIN}"
    echo -e "${RED}  0. $(localized_text "返回" "Back" "Назад")${PLAIN}"
    read_trimmed choice "$(localized_text "选择模式: " "Select a mode: " "Выберите режим: ")"
    case "$choice" in
        1) switch_entry_mode "nginx-stream" ;;
        2) switch_entry_mode "xray-fallback" ;;
        3) switch_entry_mode "tcp-peek" ;;
        0|q|Q) return ;;
        *) echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")"; return 1 ;;
    esac
}

prepare_initial_entry_mode_dependencies() {
    local target_mode="$1"
    target_mode=$(normalize_entry_mode_name "$target_mode") || return 1
    case "$target_mode" in
        "tcp-peek")
            install_vpso_mux_binary || {
                echo -e "$(localized_text "${RED}❌ vpso-mux 安装失败，首次配置已停止。请根据上方错误处理后重试。${PLAIN}" "${RED}❌ Failed to install vpso-mux. Initial setup stopped. Fix the error above and retry.${PLAIN}" "${RED}❌ Не удалось установить vpso-mux. Первоначальная настройка остановлена. Исправьте ошибку выше и повторите попытку.${PLAIN}")"
                return 1
            }
            ;;
        "xray-fallback")
            xray_entry_service_name >/dev/null 2>&1 || {
                echo -e "$(localized_text "${RED}❌ 未检测到 xray/x-ui/3x-ui systemd 服务，无法首次配置为 xray-fallback。${PLAIN}" "${RED}❌ The xray/x-ui/3x-ui systemd service is not detected and cannot be configured as xray-fallback for the first time.${PLAIN}" "${RED}❌ Служба xray/x-ui/3x-ui systemd не обнаружена и не может быть настроена как резервная служба xray в первый раз.${PLAIN}")"
                echo -e "$(localized_text "${YELLOW}请先在 [5 面板、节点与订阅工具] 中安装并配置 Xray/3x-ui 主入站，或改选 Nginx Stream 模式 / TCP Peek + Splice 模式。${PLAIN}" "${YELLOW}Please first install and configure Xray/3x-ui main inbound in [5 Panels, Nodes and Subscription Tools], or change to Nginx Stream mode / TCP Peek + Splice mode.${PLAIN}" "${YELLOW}Сначала установите и настройте основное входящее подключение Xray/3x-ui в [5 панелей, узлов и инструментов подписки] или переключитесь в режим Nginx Stream/TCP Peek + Splice.${PLAIN}")"
                return 1
            }
            print_xray_fallback_mode_explanation
            confirm_risk_action "$(localized_text "首次配置使用 Xray Fallback 模式" "initial setup using Xray Fallback mode" "Первая настройка с использованием резервного режима Xray.")" \
                "$(localized_text "公网 443 将由已有 Xray 主入站接管，普通 HTTPS fallback 到所选 Web 反代引擎" "public port 443 will be taken over by the existing Xray main inbound, and ordinary HTTPS fallback to the selected Web reverse proxy engine" "публичный порт 443 будет занят существующей основным входящим подключением Xray и обычным резервным HTTPS для выбранного механизма обратный прокси веб-сети.")" \
                "$(localized_text "返回首次配置并选择 Nginx Stream 模式或 TCP Peek + Splice 模式" "Return to the first configuration and select Nginx Stream mode or TCP Peek + Splice mode" "Вернитесь к первой конфигурации и выберите режим Nginx Stream или режим TCP Peek + Splice.")" \
                "$(localized_text "确认你已经在 Xray/3x-ui 中准备好公网 443 主入站；脚本不会创建或修改 3x-ui/Xray 入站内部配置。" "Confirm that you have prepared the public port 443 main inbound in Xray/3x-ui; the script will not create or modify the 3x-ui/Xray inbound internal configuration." "Подтвердите, что вы подготовили главный вход 443 публичной сети в Xray/3x-ui; сценарий не будет создавать или изменять входящую внутреннюю конфигурацию 3x-ui/Xray.")" || return 1
            ;;
    esac
}

switch_entry_mode() {
    local target_mode="$1"
    local current_mode backup_dir planned_backup_dir
    load_sni_stack_env || return 1
    target_mode=$(normalize_entry_mode_name "$target_mode") || { echo -e "$(localized_text "${RED}❌ 目标入口模式无效：${target_mode}${PLAIN}" "${RED}❌ Invalid target entry mode: ${target_mode}${PLAIN}" "${RED}❌ Неверный режим ввода цели: ${target_mode}${PLAIN}")"; return 1; }
    current_mode=$(get_entry_mode)

    if [[ "$target_mode" == "$current_mode" ]]; then
        confirm_danger \
            "$(localized_text "重新应用 ${target_mode} 入口模式" "Reapply the ${target_mode} entry mode" "Повторно применить режим входа ${target_mode}")" \
            "$(localized_text "重新生成公网 443 入口配置并重启相关入口服务。" "Regenerate the public Port 443 entry configuration and restart the related entry services." "Заново создать конфигурацию публичного входа 443 и перезапустить связанные службы.")" \
            "$(localized_text "使用入口模式备份回滚，或重新应用原入口模式。" "Roll back with the entry-mode backup or reapply the previous entry mode." "Выполните откат из резервной копии режима входа или повторно примените прежний режим.")" || return 1
        reapply_current_entry_mode
        return $?
    fi

    echo -e "$(localized_text "${CYAN}准备切换 443 入口模式：${current_mode} -> ${target_mode}${PLAIN}" "${CYAN}Is ready to switch 443 Entry mode: ${current_mode} -> ${target_mode}${PLAIN}" "${CYAN}готов переключить режим ввода 443: ${current_mode} -> ${target_mode}${PLAIN}")"
    if [[ "$target_mode" == "tcp-peek" && ! -x /usr/local/bin/vpso-mux ]]; then
        echo -e "$(localized_text "${CYAN}▶ 未检测到 vpso-mux，正在安装构建依赖并生成程序...${PLAIN}" "${CYAN}▶ vpso-mux was not found; installing build dependencies and building it...${PLAIN}" "${CYAN}▶ vpso-mux не найден; устанавливаются зависимости и выполняется сборка...${PLAIN}")"
        install_vpso_mux_binary || {
            echo -e "$(localized_text "${RED}❌ vpso-mux 安装失败，公网 443 未切换。请根据上方错误处理后重试。${PLAIN}" "${RED}❌ Failed to install vpso-mux. Public port 443 was not switched. Fix the error above and retry.${PLAIN}" "${RED}❌ Не удалось установить vpso-mux. Публичный порт 443 не переключён. Исправьте ошибку выше и повторите попытку.${PLAIN}")"
            return 1
        }
    fi
    check_entry_mode_dependencies "$target_mode" || return 1
    if [[ "$target_mode" == "xray-fallback" ]]; then
        select_xray_fallback_main_route_for_switch || return 1
    fi
    planned_backup_dir=$(sni_stack_backup_dir)
    preview_entry_mode_cutover "$current_mode" "$target_mode" "$planned_backup_dir" || return 1
    guard_current_ssh_not_on_entry_port "$(localized_text "切换 443 入口模式" "Switch 443 entry mode" "Переключить 443 режим входа")" || return 1
    backup_dir=$(backup_entry_mode_config "$planned_backup_dir") || return 1
    if ! preflight_entry_mode_before_cutover "$target_mode"; then
        echo -e "$(localized_text "${RED}❌ 入口模式 ${target_mode} 预检失败，公网 443 未切换。${PLAIN}" "${RED}❌ entry mode ${target_mode} preflight check failed, public port 443 was not switched.${PLAIN}" "${RED}❌ Режим входа ${target_mode} Предварительная проверка не удалась, публичный порт 443 не был переключён.${PLAIN}")"
        return 1
    fi

    if ! stop_public_443_entry_services_for_target "$target_mode"; then
        echo -e "$(localized_text "${RED}❌ 停止当前公网 443 入口服务失败，正在回滚。${PLAIN}" "${RED}❌ Stop the current public port 443. The entry service failed and is being rolled back.${PLAIN}" "${RED}❌ Не удалось остановить текущую службу входа в публичный порт 443, и выполняется откат.${PLAIN}")"
        rollback_last_entry_mode "$backup_dir"
        return 1
    fi

    if ! apply_entry_mode_by_name "$target_mode" "$backup_dir"; then
        echo -e "$(localized_text "${RED}❌ 入口模式 ${target_mode} 应用失败，正在自动回滚。${PLAIN}" "${RED}❌ Entry mode ${target_mode} The application failed and is being rolled back automatically.${PLAIN}" "${RED}❌ Режим входа ${target_mode} Ошибка приложения, и выполняется автоматический откат.${PLAIN}")"
        rollback_last_entry_mode "$backup_dir"
        return 1
    fi

    ENTRY_MODE="$target_mode"
    save_sni_stack_env
    write_single_443_engine_state "$(entry_mode_engine_name "$target_mode")" "$backup_dir"
    echo -e "$(localized_text "${GREEN}✅ 443 入口模式已切换为：${target_mode}${PLAIN}" "${GREEN}✅ 443 The entry mode has been switched to: ${target_mode}${PLAIN}" "${GREEN}✅ 443 Режим входа переключен на: ${target_mode}${PLAIN}")"
    show_current_entry_status
}

reapply_current_entry_mode() {
    local current_mode backup_dir planned_backup_dir assume_yes
    assume_yes="${1:-}"
    load_sni_stack_env || return 1
    current_mode=$(get_entry_mode)
    current_mode=$(normalize_entry_mode_name "$current_mode") || { echo -e "$(localized_text "${RED}❌ 当前 ENTRY_MODE 无效：${current_mode}${PLAIN}" "${RED}❌ Current ENTRY_MODE is invalid: ${current_mode}${PLAIN}" "${RED}❌ Текущий ENTRY_MODE недействителен: ${current_mode}${PLAIN}")"; return 1; }
    echo -e "$(localized_text "${CYAN}正在重新应用当前 443 入口模式：${current_mode}${PLAIN}" "${CYAN}Is reapplying the current 443 entry mode: ${current_mode}${PLAIN}" "${CYAN}повторно применяет текущий режим ввода 443: ${current_mode}.${PLAIN}")"
    guard_current_ssh_not_on_entry_port "$(localized_text "重新应用 443 入口模式" "Reapply 443 entry mode" "Повторно применить режим входа 443")" || return 1
    if [[ "$assume_yes" != "--yes" ]]; then
        planned_backup_dir=$(sni_stack_backup_dir)
        preview_entry_mode_cutover "$current_mode" "$current_mode" "$planned_backup_dir" || return 1
    fi
    check_entry_mode_dependencies "$current_mode" || return 1
    planned_backup_dir="${planned_backup_dir:-$(sni_stack_backup_dir)}"
    backup_dir=$(backup_entry_mode_config "$planned_backup_dir") || return 1
    if [[ "$current_mode" == "xray-fallback" ]]; then
        select_xray_fallback_main_route_for_switch || return 1
    fi
    if ! preflight_entry_mode_before_cutover "$current_mode"; then
        echo -e "$(localized_text "${RED}❌ 当前入口模式 ${current_mode} 预检失败，公网 443 未重新应用。${PLAIN}" "${RED}❌ Current entry mode ${current_mode} preflight failed, public port 443 has not been reapplied.${PLAIN}" "${RED}❌ Текущий режим входа. Не удалось выполнить предварительную проверку ${current_mode}, конфигурация публичного порта 443 не была применена повторно.${PLAIN}")"
        return 1
    fi
    if ! stop_public_443_entry_services_for_target "$current_mode"; then
        echo -e "$(localized_text "${RED}❌ 停止当前公网 443 入口服务失败，正在回滚。${PLAIN}" "${RED}❌ Stop the current public port 443. The entry service failed and is being rolled back.${PLAIN}" "${RED}❌ Не удалось остановить текущую службу входа в публичный порт 443, и выполняется откат.${PLAIN}")"
        rollback_last_entry_mode "$backup_dir"
        return 1
    fi
    if ! apply_entry_mode_by_name "$current_mode" "$backup_dir"; then
        echo -e "$(localized_text "${RED}❌ 当前入口模式重新应用失败，正在自动回滚。${PLAIN}" "${RED}❌ The current entry mode failed to be reapplied and is being automatically rolled back.${PLAIN}" "${RED}❌ Не удалось повторно применить текущий режим входа, и выполняется автоматический откат.${PLAIN}")"
        rollback_last_entry_mode "$backup_dir"
        return 1
    fi
    ENTRY_MODE="$current_mode"
    save_sni_stack_env
    write_single_443_engine_state "$(entry_mode_engine_name "$current_mode")" "$backup_dir"
    echo -e "$(localized_text "${GREEN}✅ 当前入口模式已重新应用：${current_mode}${PLAIN}" "${GREEN}✅ The current entry mode has been reapplied: ${current_mode}${PLAIN}" "${GREEN}. Текущий режим входа был применен повторно: ${current_mode}.${PLAIN}")"
    show_current_entry_status
}

view_current_entry_logs() {
    local mode service label
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}📜 当前 443 入口日志${PLAIN}" "${BOLD}📜 Current 443 entry logs${PLAIN}" "${BOLD}📜 Журналы текущего входа 443${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    mode=$(get_entry_mode)
    case "$mode" in
        nginx-stream) service="nginx"; label="Nginx Stream" ;;
        xray-fallback)
            service=$(xray_entry_service_name 2>/dev/null) || {
                echo -e "$(localized_text "${RED}❌ 未检测到 Xray/3x-ui 入口服务。${PLAIN}" "${RED}❌ No Xray/3x-ui entry service was detected.${PLAIN}" "${RED}❌ Служба входа Xray/3x-ui не обнаружена.${PLAIN}")"
                return 1
            }
            label="Xray Fallback"
            ;;
        tcp-peek) service="vpso-mux"; label="TCP Peek + Splice" ;;
        *) echo -e "$(localized_text "${RED}❌ ENTRY_MODE 无效：${mode}${PLAIN}" "${RED}❌ Invalid ENTRY_MODE: ${mode}${PLAIN}" "${RED}❌ Недопустимый ENTRY_MODE: ${mode}${PLAIN}")"; return 1 ;;
    esac
    echo -e "$(localized_text "入口模式：${GREEN}${label}${PLAIN}  服务：${CYAN}${service}${PLAIN}" "Entry mode: ${GREEN}${label}${PLAIN}  Service: ${CYAN}${service}${PLAIN}" "Режим: ${GREEN}${label}${PLAIN}  Служба: ${CYAN}${service}${PLAIN}")"
    echo -e "------------------------------------------------"
    systemctl status "$service" --no-pager -l 2>/dev/null || true
    echo -e "------------------------------------------------"
    journalctl -u "$service" -n 120 --no-pager 2>/dev/null || echo "$(localized_text "未读取到 ${service} 日志。" "No logs were read for ${service}." "Не удалось прочитать журнал ${service}.")"
}

entry_mode_supports_xray_sni_routes() {
    local mode="$1"
    mode=$(normalize_entry_mode_name "$mode" 2>/dev/null) || return 1
    [[ "$mode" == "nginx-stream" || "$mode" == "tcp-peek" ]]
}

# ---------------------------------------------------------
# Module: sni_stack_health.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Port 443 Reuse health checks, HTTP/TLS probes, and subscription hints.

print_443_health_status_code_hints() {
    echo -e "$(localized_text "${BOLD}状态码提示${PLAIN}" "${BOLD}Status code prompt${PLAIN}" "${BOLD}подсказка кода состояния${PLAIN}")"
    echo -e "$(localized_text "  - 403/401：可能是 Web 白名单、CDN/WAF、源站保护、Host/SNI 策略或后端鉴权。" "- 403/401: It may be web whitelist, CDN/WAF, origin protection, Host/SNI policy or backend authentication." "- 403/401: это может быть белый список веб-сайтов, CDN/WAF, защита источника, политика Host/SNI или внутренняя аутентификация.")"
    echo -e "$(localized_text "  - 502：可能是 Caddy 到后端端口不通。" "- 502: It may be that Caddy cannot reach the backend port." "- 502: Возможно, Caddy не может достичь внутреннего порта.")"
    echo -e "$(localized_text "  - 525/526：可能是 CDN 到源站 TLS 或证书校验失败。" "- 525/526: It may be that the CDN to the origin site TLS or the certificate verification failed." "- 525/526: Возможно, CDN к исходному сайту TLS или проверка сертификата не удалась.")"
    echo -e "$(localized_text "  - 超时：可能是 443 监听、防火墙、安全组、入口服务异常。" "- Timeout: It may be 443 abnormality in listening, firewall, security group, or entry service." "- Тайм-аут: это может быть ошибка 443 в прослушивании, брандмауэре, группе безопасности или службе точки входа.")"
}

print_443_health_reality_notes() {
    echo -e "$(localized_text "${BOLD}REALITY 检查提示${PLAIN}" "${BOLD}REALITY Inspection prompt${PLAIN}" "${BOLD}REALITY Запрос на проверку${PLAIN}")"
    echo -e "$(localized_text "  - 不要要求 REALITY serverName/dest 加入 Web 反代引擎。" "- Do not require REALITY serverName/dest to join the web reverse proxy engine." "- Не требуйте REALITY serverName/dest для присоединения к механизму веб-прокси.")"
    echo -e "$(localized_text "  - 不要要求本机证书覆盖 REALITY serverName。" "- Do not require native certificates to override REALITY serverName." "— Не требуйте собственных сертификатов для переопределения имени сервера REALITY.")"
    echo -e "$(localized_text "  - REALITY 应检查外部目标站点是否真实可访问、TLS 特征是否稳定。" "- REALITY should check whether the external target site is truly accessible and whether the TLS characteristics are stable." "- REALITY должен проверить, действительно ли внешний целевой сайт доступен и стабильны ли характеристики TLS.")"
    echo -e "$(localized_text "  - 普通 TLS 节点和 REALITY 节点的 SNI/serverName 检查逻辑必须区分。" "- The SNI/serverName check logic of ordinary TLS nodes and REALITY nodes must be distinguished." "- Необходимо различать логику проверки SNI/serverName обычных узлов TLS и узлов REALITY.")"
}

print_web_domain_http_status() {
    local label="$1"
    local domain="$2"
    local path="${3:-/}"
    local url code

    [[ -n "$domain" ]] || return 0
    path=$(normalize_path_prefix "$path")
    url="https://${domain}${path}"

    if ! command -v curl >/dev/null 2>&1; then
        echo -e "$(localized_text "${label}：${url} -> ${YELLOW}未检测，curl 未安装${PLAIN}" "${label}: ${url} -> ${YELLOW}Is not detected, curl is not installed,${PLAIN} is not installed" "${label}: ${url} -> ${YELLOW}не обнаружен, curl не установлен,${PLAIN} не установлен")"
        return 0
    fi

    code=$(curl -k -L -o /dev/null -sS --connect-timeout 6 --max-time 12 -w '%{http_code}' "$url" 2>/dev/null) || code="timeout"
    [[ -z "$code" || "$code" == "000" ]] && code="timeout"
    echo -e "${label}：${url} -> ${code}"
}

print_domain_cert_file_status() {
    local domain="$1"
    local cert key root_cert root_key

    [[ -n "$domain" ]] || return 0
    cert="/etc/caddy/certs/${domain}.crt"
    key="/etc/caddy/certs/${domain}.key"
    root_cert="/root/cert/${domain}.crt"
    root_key="/root/cert/${domain}.key"

    echo -e "${CYAN}${domain}${PLAIN}"
    [[ -s "$cert" ]] && echo -e "$(localized_text "  ${GREEN}✅ 证书文件存在：${cert}${PLAIN}" "${GREEN}✅ Certificate file exists: ${cert}${PLAIN}" "${GREEN}✅ Файл сертификата существует: ${cert}${PLAIN}")" || echo -e "$(localized_text "  ${YELLOW}⚠️ 证书文件不存在或为空：${cert}${PLAIN}" "${YELLOW}⚠️ The certificate file does not exist or is empty: ${cert}${PLAIN}" "${YELLOW}⚠️ Файл сертификата не существует или пуст: ${cert}${PLAIN}.")"
    [[ -s "$key" ]] && echo -e "$(localized_text "  ${GREEN}✅ 私钥文件存在：${key}${PLAIN}" "${GREEN}✅ Private key file exists: ${key}${PLAIN}" "${GREEN}✅ Существует файл закрытого ключа: ${key}${PLAIN}.")" || echo -e "$(localized_text "  ${YELLOW}⚠️ 私钥文件不存在或为空：${key}${PLAIN}" "${YELLOW}⚠️ The private key file does not exist or is empty: ${key}${PLAIN}" "${YELLOW}⚠️ Файл закрытого ключа не существует или пуст: ${key}${PLAIN}.")"

    if [[ -L "$root_cert" && "$(readlink "$root_cert" 2>/dev/null)" == "$cert" && -e "$root_cert" ]]; then
        echo -e "$(localized_text "  ${GREEN}✅ /root/cert 证书软链接正常：${root_cert} -> ${cert}${PLAIN}" "${GREEN}✅ /root/cert certificate symlink is normal: ${root_cert} -> ${cert}${PLAIN}" "${GREEN}✅ /root/cert символическая ссылка сертификата является нормальной: ${root_cert} -> ${cert}${PLAIN}")"
    else
        echo -e "$(localized_text "  ${YELLOW}⚠️ /root/cert 证书软链接异常或不存在：${root_cert}${PLAIN}" "${YELLOW}⚠️ /root/cert Certificate symlink is abnormal or does not exist: ${root_cert}${PLAIN}" "${YELLOW}⚠️ /root/cert символическая ссылка на сертификат ненормальна или не существует: ${root_cert}${PLAIN}")"
    fi

    if [[ -L "$root_key" && "$(readlink "$root_key" 2>/dev/null)" == "$key" && -e "$root_key" ]]; then
        echo -e "$(localized_text "  ${GREEN}✅ /root/cert 私钥软链接正常：${root_key} -> ${key}${PLAIN}" "${GREEN}✅ /root/cert private key symlink is normal: ${root_key} -> ${key}${PLAIN}" "${GREEN}✅ /root/cert символическая ссылка на закрытый ключ является нормальной: ${root_key} -> ${key}${PLAIN}")"
    else
        echo -e "$(localized_text "  ${YELLOW}⚠️ /root/cert 私钥软链接异常或不存在：${root_key}${PLAIN}" "${YELLOW}⚠️ /root/cert The private key symlink is abnormal or does not exist: ${root_key}${PLAIN}" "${YELLOW}⚠️ /root/cert символическая ссылка на закрытый ключ ненормальна или не существует: ${root_key}${PLAIN}")"
    fi
}

print_xray_route_health_list() {
    local mode="$1"
    local i sni addr port line main_idx status

    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}未配置 Xray 入站分流规则：$(xray_sni_routes_path)${PLAIN}" "${YELLOW}No Xray inbound routing rules are configured: $(xray_sni_routes_path)${PLAIN}" "${YELLOW}Правила маршрутизации входящих подключений Xray не настроены: $(xray_sni_routes_path)${PLAIN}")"
        return 0
    fi

    main_idx=$(xray_fallback_main_route_index 2>/dev/null || true)
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        sni="${XRAY_SNI_ROUTE_SNIS[$i]}"
        addr="${XRAY_SNI_ROUTE_ADDRS[$i]}"
        port="${XRAY_SNI_ROUTE_PORTS[$i]}"
        [[ -n "$sni" ]] || continue

        if [[ "$mode" == "xray-fallback" ]]; then
            if [[ -n "$main_idx" && "$i" == "$main_idx" ]]; then
                status="$(localized_text "xray-fallback 主入站，当前模式生效" "xray-fallback Main inbound, current mode takes effect" "xray-fallback Основной входящий, текущий режим вступает в силу")"
            else
                status="$(localized_text "已保留，当前 xray-fallback 模式下不生效" "Reserved, not effective in current xray-fallback mode" "Зарезервировано, не действует в текущем резервном режиме xray.")"
            fi
        else
            status="$(localized_text "当前模式支持按 SNI 分流" "The current mode supports routinging according to SNI" "Текущий режим поддерживает маршрутизирование согласно SNI.")"
        fi

        echo -e "${CYAN}${sni}${PLAIN} -> ${addr}:${port}（${status}）"
        if [[ "${CADDY_LISTEN_PORT:-}" == "$port" ]]; then
            echo -e "$(localized_text "${RED}  ❌ 与 Web 反代引擎本地端口 ${CADDY_LISTEN_PORT} 冲突。${PLAIN}" "${RED}❌ Conflicts with the web inversion engine local port ${CADDY_LISTEN_PORT}.${PLAIN}" "${RED}❌ Конфликты с локальным портом ${CADDY_LISTEN_PORT} механизма веб-инверсии.${PLAIN}")"
        fi
        line=$(xray_route_listen_line_by_addr_port "$addr" "$port")
        if [[ -n "$line" ]]; then
            echo -e "$(localized_text "${GREEN}  ✅ 端口已监听：${line}${PLAIN}" "${GREEN}✅ Port is listening: ${line}${PLAIN}" "${GREEN}✅ Порт прослушивается: ${line}${PLAIN}")"
            if echo "$line" | grep -Eq '(^|[[:space:]])(0\.0\.0\.0|\*|\[::\]):'"${port}"'[[:space:]]'; then
                echo -e "$(localized_text "${YELLOW}  ⚠️ 检测到可能监听在 0.0.0.0/[::]，存在公网暴露风险，建议改为 127.0.0.1。${PLAIN}" "${YELLOW}⚠️ Detected that it may be monitored at 0.0.0.0/[::], which is a risk of Internet exposure. It is recommended to change it to 127.0.0.1.${PLAIN}" "${YELLOW}⚠️ Обнаружено, что его можно отслеживать по адресу 0.0.0.0/[::]. Существует риск публичного доступа. Рекомендуется изменить его на 127.0.0.1.${PLAIN}")"
            fi
        else
            echo -e "$(localized_text "${YELLOW}  ⚠️ 未检测到 ${addr}:${port} 监听，请先去 3x-ui 创建并启用对应入站。${PLAIN}" "${YELLOW}⚠️ The ${addr}:${port} monitor is not detected. Please go to 3x-ui first to create and enable the corresponding inbound connection.${PLAIN}" "${YELLOW}⚠️ Монитор ${addr}:${port} не обнаружен. Сначала перейдите по адресу 3x-ui, чтобы создать и включить соответствующее входящее соединение.${PLAIN}")"
        fi
    done
}

print_443_health_connlimit_scope_notice() {
    local marker runtime_rules saved_rules rules locations source_count

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}端口并发连接限制${PLAIN}" "${BOLD}Port concurrent connection limit${PLAIN}" "${BOLD}Ограничение количества одновременных подключений к порту${PLAIN}")"

    if ! declare -F port_connlimit_comment >/dev/null || ! declare -F port_connlimit_runtime_rule_fingerprints >/dev/null || ! declare -F port_connlimit_known_saved_rule_fingerprints >/dev/null; then
        echo -e "$(localized_text "${BLUE}未接入 connlimit 检测 helper，跳过端口并发连接限制检查。${PLAIN}" "${BLUE}Is not connected to the connlimit detection helper and skips the port concurrent connection limit check.${PLAIN}" "${BLUE}не подключен к помощнику обнаружения connlimit и пропускает проверку ограничения количества одновременных подключений к порту.${PLAIN}")"
        return 0
    fi

    marker=$(port_connlimit_comment 443)
    runtime_rules=$(port_connlimit_runtime_rule_fingerprints | grep -E "${marker}([^0-9]|$)" || true)
    saved_rules=$(port_connlimit_known_saved_rule_fingerprints | grep -E "${marker}([^0-9]|$)" || true)
    rules=$(printf '%s\n%s\n' "$runtime_rules" "$saved_rules" | grep -E "${marker}([^0-9]|$)" || true)

    if [[ -z "$rules" ]]; then
        echo -e "$(localized_text "${BLUE}未检测到本脚本添加的公网 443 connlimit 规则。${PLAIN}" "${BLUE}Did not detect the public port 443 connlimit rule added by this script.${PLAIN}" "${BLUE}не обнаружил правило connlimit публичного порта 443, добавленное этим сценарием.${PLAIN}")"
        return 0
    fi

    locations=""
    [[ -n "$runtime_rules" ]] && locations="$(localized_text "运行时" "runtime" "время выполнения")"
    [[ -n "$saved_rules" ]] && locations="$(localized_text "${locations:+${locations},}持久化文件" "${locations:+${locations},}persistent files" "${locations:+${locations},}постоянные файлы")"
    source_count=$(printf '%s\n' "$rules" | grep -c . || true)

    echo -e "$(localized_text "${YELLOW}检测到本脚本添加的公网 443 connlimit 规则：${marker}${PLAIN}" "${YELLOW}Detects the public port 443 connlimit rule added by this script: ${marker}${PLAIN}" "${YELLOW}обнаруживает правило connlimit публичного порта 443, добавленное этим скриптом: ${marker}${PLAIN}")"
    echo -e "$(localized_text "检测位置：${locations:-未知}；匹配条数：${source_count}" "Detection position: ${locations:-未知}; matching number: ${source_count}" "Позиция обнаружения: ${locations:-未知}; соответствующий номер: ${source_count}")"
    echo -e "$(localized_text "${RED}影响范围：该限制只能作用于整个公网 443 入口，不能精准到某个 SNI、Xray/3x-ui 入站、UUID 或用户。${PLAIN}" "${RED}Scope of influence: This restriction can only be applied to the entire public port 443 entry, and cannot be precise to a specific SNI, Xray/3x-ui inbound, UUID or user.${PLAIN}" "${RED}Область влияния : это ограничение может применяться только ко всему входу в публичный порт 443 и не может быть точным для конкретного входящего SNI, Xray/3x-ui, UUID или пользователя.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}如果某个节点、订阅或网站被误伤，请到 [8 防火墙规则管理] -> [5 端口并发连接限制] 查看或删除公网 443 的 connlimit 规则。${PLAIN}" "${YELLOW}If a node, subscription or website is accidentally damaged, please go to [8 Firewall Rule Management] -> [5 Port Concurrent Connection Limit] to view or delete the connlimit rule of public port 443.${PLAIN}" "${YELLOW}Если узел, подписка или веб-сайт случайно повреждены, перейдите в раздел [8 Управление правилами брандмауэра] -> [Ограничение одновременных подключений через 5 портов], чтобы просмотреть или удалить правило connlimit публичного порта 443.${PLAIN}")"
}

sni_stack_health_check_enhanced() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🧪 443 链路体检增强${PLAIN}" "${BOLD}🧪 443 Link health check enhancement${PLAIN}" "${BOLD}🧪 443 Улучшение проверки работоспособности ссылки${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    detect_current_entry_status

    local mode web_backend web_label xray_backend panel_backend sub_backend site_backend route_count ranges i domain public_443_lines mux_config mux_service
    mode="$ENTRY_STATUS_MODE"
    web_backend=$(web_proxy_backend)
    web_label=$(web_proxy_engine_label)
    xray_backend=$(format_hostport "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT")
    panel_backend=$(format_hostport "$PANEL_LISTEN_ADDR" "$PANEL_LISTEN_PORT")
    sub_backend=$(format_hostport "$SUB_LISTEN_ADDR" "$SUB_LISTEN_PORT")
    mux_config=$(vpso_mux_config_path)
    mux_service="/etc/systemd/system/$(vpso_mux_service_name)"
    route_count=$((2 + ${#SITE_DOMAINS[@]} + ${#TCP_ROUTE_SNIS[@]} + ${#XRAY_SNI_ROUTE_SNIS[@]}))

    echo -e "$(localized_text "${BOLD}入口状态${PLAIN}" "${BOLD}Entry status${PLAIN}" "${BOLD}Статус входа${PLAIN}")"
    echo -e "$(localized_text "当前 ENTRY_MODE：${GREEN}${mode}${PLAIN}" "Current ENTRY_MODE: ${GREEN}${mode}${PLAIN}" "Текущий ENTRY_MODE: ${GREEN}${mode}${PLAIN}")"
    print_entry_mode_compat_notice
    echo -e "$(localized_text "实际公网 443 监听服务：${ENTRY_STATUS_LISTENER_PROCESS}" "Actual public port 443 listening service: ${ENTRY_STATUS_LISTENER_PROCESS}" "Фактическая служба прослушивания публичного порта 443: ${ENTRY_STATUS_LISTENER_PROCESS}.")"
    public_443_lines=$(ss -lntp 2>/dev/null | grep -E '(:443[[:space:]]|:443$)' || true)
    echo -e "$(localized_text "${public_443_lines:-未监听或当前用户无权限查看进程}" "${public_443_lines:-未监听或当前用户无权限查看进程}" "${public_443_lines:-未监听或当前用户无权限查看进程}")"
    if [[ "$ENTRY_STATUS_CONSISTENT" == "yes" ]]; then
        echo -e "$(localized_text "配置模式与实际监听：${GREEN}一致${PLAIN}" "The configuration mode is consistent with the actual listening: ${GREEN}${PLAIN}" "Режим конфигурации соответствует фактическому прослушиваниеу: ${GREEN}${PLAIN}")"
    else
        echo -e "$(localized_text "配置模式与实际监听：${YELLOW}不一致${PLAIN}" "The configuration mode is inconsistent with the actual listening: ${YELLOW}${PLAIN}" "Режим конфигурации не соответствует реальному прослушиваниеу: ${YELLOW}${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}配置模式与实际监听不一致，建议重新应用当前入口模式。${PLAIN}" "${YELLOW}Configuration mode is inconsistent with actual listening. It is recommended to re-apply the current entry mode.${PLAIN}" "${YELLOW}Режим конфигурации несовместим с реальным прослушиваниеом. Рекомендуется повторно применить текущий режим входа.${PLAIN}")"
    fi
    echo -e "$(localized_text "nginx 状态：${ENTRY_STATUS_NGINX_SERVICE}" "nginx Status: ${ENTRY_STATUS_NGINX_SERVICE}" "Статус nginx: ${ENTRY_STATUS_NGINX_SERVICE}")"
    echo -e "$(localized_text "Xray/3x-ui 状态：${ENTRY_STATUS_XRAY_SERVICE}" "Xray/3x-ui Status: ${ENTRY_STATUS_XRAY_SERVICE}" "Xray/3x-ui Статус: ${ENTRY_STATUS_XRAY_SERVICE}")"
    echo -e "$(localized_text "TCP Peek + Splice 状态：${ENTRY_STATUS_TCPPEEK_SERVICE}" "TCP Peek + Splice Status: ${ENTRY_STATUS_TCPPEEK_SERVICE}" "Статус TCP Peek + Splice: ${ENTRY_STATUS_TCPPEEK_SERVICE}")"
    if [[ "$(current_web_proxy_engine)" == "caddy" ]]; then
        echo -e "$(localized_text "caddy 状态：$(service_status_compact caddy)" "caddy Status: $(service_status_compact caddy)" "Статус caddy: $(service_status_compact caddy)")"
    fi
    if [[ -f "$mux_config" ]]; then
        echo -e "$(localized_text "TCP Peek + Splice 分流规则：${GREEN}存在 ${mux_config}${PLAIN}" "TCP Peek + Splice routing rule: ${GREEN}Exists ${mux_config}${PLAIN}" "TCP Peek + Splice Правило перенаправления: ${GREEN}существует ${mux_config}${PLAIN}")"
    else
        echo -e "$(localized_text "TCP Peek + Splice 分流规则：${YELLOW}未找到 ${mux_config}${PLAIN}" "TCP Peek + Splice routing rule: ${YELLOW}Not found ${mux_config}${PLAIN}" "TCP Peek + Splice Правило перенаправления: ${YELLOW}не найден ${mux_config}${PLAIN}")"
    fi
    if [[ -f "$mux_service" ]]; then
        echo -e "$(localized_text "vpso-mux 分流器 systemd：${GREEN}存在 ${mux_service}${PLAIN}" "vpso-mux routing systemd: ${GREEN}Exists ${mux_service}${PLAIN}" "vpso-mux маршрутизация systemd: ${GREEN}существует ${mux_service}${PLAIN}")"
    else
        echo -e "$(localized_text "vpso-mux 分流器 systemd：${YELLOW}未找到 ${mux_service}${PLAIN}" "vpso-mux routing systemd: ${YELLOW}Not found ${mux_service}${PLAIN}" "маршрутизация vpso-mux systemd: ${YELLOW}не найден ${mux_service}${PLAIN}")"
    fi
    print_443_health_connlimit_scope_notice

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}本地监听${PLAIN}" "${BOLD}Local listeners${PLAIN}" "${BOLD}локальный прослушивание${PLAIN}")"
    echo -e "$(localized_text "Web 反代引擎本地监听端口：${web_backend} (${web_label})" "Web reverse proxy engine local listening port: ${web_backend} (${web_label})" "Локальный порт прослушивания механизма веб-прокси: ${web_backend} (${web_label})")"
    get_listen_line_by_port "$CADDY_LISTEN_PORT" | grep -q "$CADDY_LISTEN_ADDR" && echo -e "$(localized_text "${GREEN}✅ ${web_label} 期望监听 ${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT}${PLAIN}" "${GREEN}✅ ${web_label} expects to monitor ${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT}${PLAIN}" "${GREEN}✅ ${web_label} планирует контролировать ${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT}${PLAIN}")" || echo -e "$(localized_text "${YELLOW}⚠️ ${web_label} 监听地址需确认：$(get_listen_line_by_port "$CADDY_LISTEN_PORT")${PLAIN}" "${YELLOW}⚠️ ${web_label} The listening address needs to be confirmed: $(get_listen_line_by_port \"$CADDY_LISTEN_PORT\")${PLAIN}" "${YELLOW}⚠️ ${web_label} Необходимо подтвердить адрес прослушивания: $(get_listen_line_by_port \"$CADDY_LISTEN_PORT\")${PLAIN}")"
    echo -e "$(localized_text "Xray 本地监听端口：${xray_backend}" "Xray Local listening port: ${xray_backend}" "Xray Локальный порт прослушивания: ${xray_backend}")"
    get_listen_line_by_port "$XRAY_LISTEN_PORT" | grep -q "$XRAY_LISTEN_ADDR" && echo -e "$(localized_text "${GREEN}✅ Xray 期望监听 ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}${PLAIN}" "${GREEN}✅ Xray expects to monitor ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}${PLAIN}" "${GREEN}✅ Xray планирует контролировать ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}${PLAIN}")" || echo -e "$(localized_text "${YELLOW}⚠️ Xray 监听地址需确认：$(get_listen_line_by_port "$XRAY_LISTEN_PORT")${PLAIN}" "${YELLOW}⚠️ Xray The listening address needs to be confirmed: $(get_listen_line_by_port \"$XRAY_LISTEN_PORT\")${PLAIN}" "${YELLOW}⚠️ Xray Необходимо подтвердить адрес прослушивания: $(get_listen_line_by_port \"$XRAY_LISTEN_PORT\")${PLAIN}")"
    if [[ "$ENTRY_STATUS_LISTENER" == "xray" ]]; then
        echo -e "$(localized_text "Xray 公网监听端口：${GREEN}公网 443 当前由 Xray 监听${PLAIN}" "Xray Internet listening port: ${GREEN} public port 443 is currently monitored by Xray ${PLAIN}" "Порт прослушивания публичной сети Xray: публичный порт 443 ${GREEN}в настоящее время контролируется Xray${PLAIN}")"
    else
        echo -e "$(localized_text "Xray 公网监听端口：未检测到 Xray 监听公网 443" "Xray public listening port: not detected Xray listening public port 443" "Порт прослушивания публичной сети Xray: не обнаружен. Xray прослушивает публичный порт 443")"
    fi

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}网站后端连通性${PLAIN}" "${BOLD}Website backend connectivity${PLAIN}" "${BOLD}Подключение к серверной части веб-сайта${PLAIN}")"
    if [[ ${#SITE_DOMAINS[@]} -eq 0 ]]; then
        echo "$(localized_text "未配置自定义网站/反代后端。" "Custom website/reverse proxy backend not configured." "Пользовательский веб-сайт или бэкенд обратного прокси не настроены.")"
    else
        for i in "${!SITE_DOMAINS[@]}"; do
            domain="${SITE_DOMAINS[$i]}"
            [[ -n "$domain" ]] || continue
            probe_backend_target "$(localized_text "网站后端 ${domain}" "Website backend ${domain}" "бэкенд сайта ${domain}")" "${SITE_BACKEND_ADDRS[$i]}" "${SITE_BACKEND_PORTS[$i]}" || true
        done
    fi

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}Xray 入站分流规则${PLAIN}" "${BOLD}Xray Inbound routing rule${PLAIN}" "${BOLD}Правила маршрутизации входящих подключений Xray${PLAIN}")"
    if entry_mode_supports_xray_sni_routes "$mode"; then
        echo -e "$(localized_text "当前入口模式是否支持 Xray 入站分流规则：${GREEN}支持${PLAIN}" "Whether the current ingress mode supports Xray Inbound routing rules: ${GREEN}Supports${PLAIN}" "Поддерживает ли текущий режим входящего подключения Xray Правила маршрутизация входящего подключения: ${GREEN}поддерживает${PLAIN}")"
    else
        echo -e "$(localized_text "当前入口模式是否支持 Xray 入站分流规则：${YELLOW}不支持/当前不生效${PLAIN}" "Whether the current ingress mode supports Xray Inbound routing rules: ${YELLOW}Is not supported/currently not in effect${PLAIN}" "Поддерживает ли текущий режим входящего подключения Xray Правила маршрутизация входящего подключения: ${YELLOW}не поддерживается/в настоящее время не действует${PLAIN}")"
    fi
    if [[ "$mode" == "xray-fallback" ]]; then
        echo -e "$(localized_text "${YELLOW}当前为 Xray Fallback 模式，Xray 入站管理中的多 SNI 分流规则不生效。${PLAIN}" "${YELLOW}Xray Fallback mode is active; multi-SNI rules from Xray inbound management do not apply.${PLAIN}" "${YELLOW}Активен режим Xray Fallback; правила нескольких SNI из управления входящими подключениями Xray не действуют.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}如需多个本地 Xray 入站，请切换到 Nginx Stream 模式或 TCP Peek + Splice 模式。${PLAIN}" "${YELLOW}If you need multiple local Xray inbound, please switch to Nginx Stream mode or TCP Peek + Splice mode.${PLAIN}" "${YELLOW}Если вам нужно несколько локальных входящих Xray, переключитесь в режим Nginx Stream или режим TCP Peek + Splice.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}普通 HTTPS 流量会先进入 Xray，再 fallback 到所选 Web 反代引擎；403/拒绝访问通常优先排查 Web 白名单、CDN/WAF、源站保护、Cloudflare 回源限制或 Host/SNI 策略。${PLAIN}" "${YELLOW}Ordinary HTTPS traffic will first enter Xray and then fallback to the selected Web reverse proxy engine; 403/Access Denied usually prioritizes Web whitelisting, CDN/WAF, origin site protection, Cloudflare back-to-origin restrictions or Host/SNI policy.${PLAIN}" "${YELLOW}Обычный трафик HTTPS сначала поступает в Xray, а затем возвращается к выбранному механизму обратный прокси Web; 403/Доступ запрещен, обычно приоритет отдается белому списку веб-сайтов, CDN/WAF, защите исходного сайта, ограничениям возврата к исходному коду Cloudflare или политике Host/SNI.${PLAIN}")"
        print_xray_fallback_main_route_summary
    fi
    print_xray_route_health_list "$mode"

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}Web 域名白名单状态${PLAIN}" "${BOLD}Web domain whitelist status${PLAIN}" "${BOLD}Состояние белого списка веб-доменов${PLAIN}")"
    print_sni_ip_whitelist_summary
    echo -e "$(localized_text "Xray 节点白名单：不支持/不启用" "Xray node whitelist: not supported/not enabled" "Белый список узлов Xray: не поддерживается/не включен")"

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}证书文件与 /root/cert 软链接${PLAIN}" "${BOLD}Certificate file and /root/cert symlink${PLAIN}" "${BOLD}Файл сертификата и символическая ссылка /root/cert${PLAIN}")"
    print_domain_cert_file_status "$PANEL_DOMAIN"
    for i in "${!SITE_DOMAINS[@]}"; do
        domain="${SITE_DOMAINS[$i]}"
        [[ -n "$domain" ]] || continue
        print_domain_cert_file_status "$domain"
    done

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}Web 域名访问 HTTP 状态码${PLAIN}" "${BOLD}Web domain access HTTP status code${PLAIN}" "${BOLD}Доступ к веб-доменному имени HTTP Код состояния${PLAIN}")"
    print_web_domain_http_status "$(localized_text "面板路径" "Panel path" "Путь панели")" "$PANEL_DOMAIN" "$PANEL_WEB_PATH"
    print_web_domain_http_status "$(localized_text "普通订阅路径" "Common subscription path" "Общий путь подписки")" "$PANEL_DOMAIN" "$SUB_URI_PATH"
    print_web_domain_http_status "$(localized_text "Clash/Mihomo 路径" "Clash/Mihomo path" "Clash/Mihomo путь")" "$PANEL_DOMAIN" "$CLASH_URI_PATH"
    for i in "${!SITE_DOMAINS[@]}"; do
        domain="${SITE_DOMAINS[$i]}"
        [[ -n "$domain" ]] || continue
        print_web_domain_http_status "$(localized_text "网站域名" "website domain" "доменное имя сайта")" "$domain" "/"
    done
    print_443_health_status_code_hints

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${BOLD}路由摘要${PLAIN}" "${BOLD}Route Summary${PLAIN}" "${BOLD}Сводка маршрута${PLAIN}")"
    echo -e "$(localized_text "default_backend 当前指向：${xray_backend}" "default_backend currently points to: ${xray_backend}" "default_backend в настоящее время указывает на: ${xray_backend}")"
    echo -e "$(localized_text "routes 数量：${route_count}" "routes quantity: ${route_count}" "количество маршрутов: ${route_count}")"
    if strict_sni_gate_enabled && strict_sni_gate_mode_supported "$mode"; then
        echo -e "$(localized_text "unknown SNI 策略：严格门禁直接丢弃" "unknown SNI policy: dropped by the strict SNI gate" "Политика неизвестного SNI: отклонение строгим контролем SNI")"
    else
        echo -e "$(localized_text "unknown SNI 策略：default_backend -> ${xray_backend}" "unknown SNI policy: default_backend -> ${xray_backend}" "Политика неизвестного SNI: default_backend -> ${xray_backend}")"
    fi
    ranges=$(sni_ip_whitelist_ranges_for_domain "$PANEL_DOMAIN")
    echo -e "$(localized_text "web panel: ${PANEL_DOMAIN}${PANEL_WEB_PATH} -> ${web_label} ${web_backend} -> 面板后端 ${panel_backend}" "web panel: ${PANEL_DOMAIN}${PANEL_WEB_PATH} -> ${web_label} ${web_backend} -> panel backend ${panel_backend}" "веб-панель: ${PANEL_DOMAIN}${PANEL_WEB_PATH} -> ${web_label} ${web_backend} -> бэкенд панели ${panel_backend}")"
    echo -e "$(localized_text "web subscription: ${PANEL_DOMAIN}${SUB_URI_PATH} -> ${web_label} ${web_backend} -> 订阅后端 ${sub_backend}" "web subscription: ${PANEL_DOMAIN}${SUB_URI_PATH} -> ${web_label} ${web_backend} -> Subscription backend ${sub_backend}" "веб-подписка: ${PANEL_DOMAIN}${SUB_URI_PATH} -> ${web_label} ${web_backend} -> Сервер подписки ${sub_backend}")"
    echo -e "$(localized_text "web clash/mihomo: ${PANEL_DOMAIN}${CLASH_URI_PATH} -> ${web_label} ${web_backend} -> 订阅后端 ${sub_backend}" "web clash/mihomo: ${PANEL_DOMAIN}${CLASH_URI_PATH} -> ${web_label} ${web_backend} -> Subscription backend ${sub_backend}" "веб-clash/mihomo: ${PANEL_DOMAIN}${CLASH_URI_PATH} -> ${web_label} ${web_backend} -> Сервер подписки ${sub_backend}")"
    echo -e "route panel: ${PANEL_DOMAIN} -> ${web_backend} whitelist=$([[ -n "$ranges" ]] && echo yes || echo no)"
    for i in "${!SITE_DOMAINS[@]}"; do
        domain="${SITE_DOMAINS[$i]}"
        [[ -n "$domain" ]] || continue
        ranges=$(sni_ip_whitelist_ranges_for_domain "$domain")
        site_backend=$(format_hostport "${SITE_BACKEND_ADDRS[$i]}" "${SITE_BACKEND_PORTS[$i]}")
        echo -e "$(localized_text "web site: ${domain}/ -> ${web_label} ${web_backend} -> 网站后端 ${site_backend}" "web site: ${domain}/ -> ${web_label} ${web_backend} -> website backend ${site_backend}" "веб-сайт: ${domain}/ -> ${web_label} ${web_backend} -> бэкенд сайта ${site_backend}")"
        echo -e "route site: ${domain} -> ${web_backend} whitelist=$([[ -n "$ranges" ]] && echo yes || echo no)"
    done
    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        domain="${TCP_ROUTE_SNIS[$i]}"
        [[ -n "$domain" ]] || continue
        echo -e "$(localized_text "route tcp: ${domain} -> $(format_hostport "${TCP_ROUTE_ADDRS[$i]}" "${TCP_ROUTE_PORTS[$i]}") whitelist=no（非 Web 域名不启用白名单）" "route tcp: ${domain} -> $(format_hostport \"${TCP_ROUTE_ADDRS[$i]}\" \"${TCP_ROUTE_PORTS[$i]}\") whitelist=no (whitelist is not enabled for non-Web domains)" "маршрут tcp: ${domain} -> $(format_hostport \"${TCP_ROUTE_ADDRS[$i]}\" \"${TCP_ROUTE_PORTS[$i]}\") белый список = нет (белый список не включен для имен доменов, не принадлежащих Интернету)")"
    done
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        domain="${XRAY_SNI_ROUTE_SNIS[$i]}"
        [[ -n "$domain" ]] || continue
        echo -e "route xray: ${domain} -> $(format_hostport "${XRAY_SNI_ROUTE_ADDRS[$i]}" "${XRAY_SNI_ROUTE_PORTS[$i]}") whitelist=no"
    done
    echo -e "route reality: ${REALITY_SNI} -> ${xray_backend} whitelist=no"
    print_443_health_reality_notes

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "最近 20 行 vpso-mux 日志：" "The last 20 lines of vpso-mux logs:" "Последние 20 строк логов vpso-mux:")"
    journalctl -u vpso-mux -n 20 --no-pager 2>/dev/null || echo "$(localized_text "未读取到 vpso-mux 日志。" "The vpso-mux log was not read." "Журнал vpso-mux не был прочитан.")"
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "测试命令：" "Test command:" "Тестовая команда:")"
    echo -e "  openssl s_client -connect SERVER_IP:${NGINX_LISTEN_PORT} -servername ${PANEL_DOMAIN}"
    [[ ${#SITE_DOMAINS[@]} -gt 0 ]] && echo -e "  openssl s_client -connect SERVER_IP:${NGINX_LISTEN_PORT} -servername ${SITE_DOMAINS[0]}"
    echo -e "  openssl s_client -connect SERVER_IP:${NGINX_LISTEN_PORT} -servername random.example.com"
}

check_sni_stack_subscription_hint() {
    local web_label

    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🔎 订阅链接与 Hosts / External Proxy 检查提示${PLAIN}" "${BOLD}🔎 Subscription link and Hosts / External Proxy check prompt${PLAIN}" "${BOLD}🔎 Ссылка на подписку и приглашение для проверки хостов/внешнего прокси${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    web_label=$(web_proxy_engine_label)
    echo -e "$(localized_text "3x-ui v3.4.0 及之后：打开 Hosts / 主机，新增 Host：" "3x-ui v3.4.0 and later: Open Hosts / Host and add a Host:" "3x-ui v3.4.0 и новее: откройте Hosts / Хост и добавьте хост:")"
    echo -e "$(localized_text "  入站：选择对应的 REALITY 或本地 Xray 入站" "Inbound: Select the corresponding REALITY or local Xray for inbound" "Входящий: выберите соответствующий REALITY или локальный Xray для входящего подключения.")"
    echo -e "$(localized_text "  地址：你的节点域名或服务器 IP" "Address: your node domain or server IP" "Адрес: доменное имя вашего узла или IP-адрес сервера.")"
    echo -e "$(localized_text "  端口：${NGINX_LISTEN_PORT}" "Port: ${NGINX_LISTEN_PORT}" "Порт: ${NGINX_LISTEN_PORT}")"
    echo -e "$(localized_text "  Security/SNI/Fingerprint/ALPN：按该入站和客户端实际值保持一致" "Security/SNI/Fingerprint/ALPN: The inbound and client actual values are consistent" "Security/SNI/Fingerprint/ALPN: фактические значения входящего и клиентского трафика совпадают.")"
    echo -e ""
    echo -e "$(localized_text "3x-ui v3.3.1 及之前：在 REALITY 入站里开启 External Proxy，并确保：" "3x-ui v3.3.1 and before: Enable External Proxy in REALITY inbound, and make sure:" "3x-ui v3.3.1 и более ранние версии: включите внешний прокси во входящем REALITY и убедитесь:")"
    echo -e "$(localized_text "  类型：相同" "Type: same" "Тип: тот же")"
    echo -e "$(localized_text "  地址：你的节点域名或服务器 IP" "Address: your node domain or server IP" "Адрес: доменное имя вашего узла или IP-адрес сервера.")"
    echo -e "$(localized_text "  端口：${NGINX_LISTEN_PORT}" "Port: ${NGINX_LISTEN_PORT}" "Порт: ${NGINX_LISTEN_PORT}")"
    echo -e "$(localized_text "${YELLOW}提示：本教程推荐 Cloudflare 灰云 / DNS only。REALITY 节点地址必须直连 VPS，可填灰云节点域名或服务器公网 IP。${PLAIN}" "${YELLOW}Tip: This tutorial recommends Cloudflare Gray Cloud / DNS only. REALITY The node address must be directly connected to the VPS. You can fill in the gray cloud node domain or server public IP.${PLAIN}" "${YELLOW}Совет. В этом руководстве рекомендуется использовать только Cloudflare Grey Cloud / DNS. REALITY Адрес узла должен быть напрямую подключен к VPS. Вы можете указать доменное имя серого облачного узла или IP-адрес сервера в Интернете.${PLAIN}")"
    echo -e ""
    echo -e "$(localized_text "复制节点链接后应该看到：" "After copying the node link you should see:" "После копирования ссылки на узел вы должны увидеть:")"
    echo -e "$(localized_text "  vless://...@节点地址:${NGINX_LISTEN_PORT}?security=reality&sni=${REALITY_SNI}&..." "vless://...@Node address:${NGINX_LISTEN_PORT}?security=reality&sni=${REALITY_SNI}&..." "vless://...@Адрес узла: ${NGINX_LISTEN_PORT}?security=reality&sni=${REALITY_SNI}&...")"
    echo -e ""
    echo -e "$(localized_text "订阅公网入口应为：" "The public entry for subscribing should be:" "Вход в публичную сеть для подписки должен быть:")"
    echo -e "$(localized_text "  普通订阅：      https://${PANEL_DOMAIN}${SUB_URI_PATH}" "Ordinary subscription: https://${PANEL_DOMAIN}${SUB_URI_PATH}" "Обычная подписка: https://${PANEL_DOMAIN}${SUB_URI_PATH}.")"
    echo -e "  Clash/Mihomo：  https://${PANEL_DOMAIN}${CLASH_URI_PATH}"
    echo -e "$(localized_text "${YELLOW}不要把公网订阅地址写成 :${SUB_LISTEN_PORT}；该端口只给当前本地 Web 反代引擎（${web_label}）访问，不应写成公网订阅入口。${PLAIN}" "${YELLOW}Do not write the public subscription address as: ${SUB_LISTEN_PORT}; this port is only accessible to the current local Web reverse proxy engine (${web_label}) and should not be written as the public subscription entry.${PLAIN}" "${YELLOW}Не записывайте адрес подписки в публичной сети как: ${SUB_LISTEN_PORT}; этот порт доступен только текущему локальному механизму защиты от создания веб-страниц (${web_label}) и не должен записываться как вход для подписки в публичной сети.${PLAIN}")"
    echo -e ""
    echo -e "$(localized_text "${YELLOW}如果链接里还是 :${XRAY_LISTEN_PORT}，3x-ui v3.4.0+ 请检查 Hosts / 主机；旧版请检查入站 External Proxy。${PLAIN}" "${YELLOW}If the link is still: ${XRAY_LISTEN_PORT}, 3x-ui v3.4.0+, please check Hosts / Host; for older versions, please check the inbound External Proxy.${PLAIN}" "${YELLOW}Если ссылка все еще: ${XRAY_LISTEN_PORT}, 3x-ui v3.4.0+, проверьте Hosts / Host; для более старых версий проверьте входящий внешний прокси.${PLAIN}")"
}

# ---------------------------------------------------------
# Module: sni_stack_profiles.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Port 443 Reuse profile editing and reapply helpers.

save_and_offer_reapply_sni_stack() {
    local env_file env_backup
    env_file="/etc/vps-optimize/sni-stack.env"
    env_backup=""
    if [[ -f "$env_file" ]]; then
        env_backup="${env_file}.pre_reapply_$(date +%Y%m%d_%H%M%S)"
        cp -p "$env_file" "$env_backup" 2>/dev/null || env_backup=""
    fi
    save_sni_stack_env
    echo -e "$(localized_text "${GREEN}✅ 已保存新的 443端口复用运行参数。${PLAIN}" "${GREEN}✅ New Port 443 Reuse operating parameters have been saved.${PLAIN}" "${GREEN}. Сохранены новые 443 отдельных рабочих параметра.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}提示：保存后需要重新应用，Nginx/Caddy 才会使用新的域名、端口或路径。${PLAIN}" "${YELLOW}Tips: You need to reapply after saving, so that Nginx/Caddy will use the new domain, port or path.${PLAIN}" "${YELLOW}Советы: вам необходимо повторно подать заявку после сохранения, чтобы Nginx/Caddy использовал новое имя домена, порт или путь.${PLAIN}")"
    if confirm_danger \
        "$(localized_text "重新应用 443 配置" "Reapply the port 443 configuration" "Повторно применить конфигурацию порта 443")" \
        "$(localized_text "重新生成入口配置并重启 Nginx/Caddy" "regenerate the entry configuration and restart Nginx/Caddy" "заново создать конфигурацию точки входа и перезапустить Nginx/Caddy")" \
        "$(localized_text "失败时自动恢复本次修改前的参数文件" "restore the parameter file saved before this change if reapplication fails" "при ошибке восстановить файл параметров, сохранённый до этого изменения")"; then
        if ! reapply_sni_stack_from_env --yes; then
            if [[ -n "$env_backup" && -f "$env_backup" ]]; then
                cp -p "$env_backup" "$env_file" 2>/dev/null || true
                echo -e "$(localized_text "${YELLOW}⚠️ 已恢复重新应用前的参数文件：${env_backup}${PLAIN}" "${YELLOW}⚠️ The parameter file before re-application has been restored: ${env_backup}${PLAIN}" "${YELLOW}⚠️ Файл параметров до повторного применения восстановлен: ${env_backup}${PLAIN}")"
            fi
            return 1
        fi
    else
        echo -e "$(localized_text "${YELLOW}稍后可执行 [19] -> [6] 重新应用上次配置。${PLAIN}" "${YELLOW}Can be executed later [19] -> [6] to reapply the last configuration.${PLAIN}" "${YELLOW}можно выполнить позже [19] -> [6] для повторного применения последней конфигурации.${PLAIN}")"
        [[ -n "$env_backup" ]] && echo -e "$(localized_text "${CYAN}参数修改前备份已保留：${env_backup}${PLAIN}" "${CYAN}The backup before parameter modification has been retained: ${env_backup}${PLAIN}" "${CYAN}Резервная копия до изменения параметра была сохранена: ${env_backup}.${PLAIN}")"
    fi
}

restart_xui_panel_services_after_setting_update() {
    local service_name restarted=0
    for service_name in x-ui 3x-ui x-panel; do
        if systemctl list-unit-files "${service_name}.service" --no-legend 2>/dev/null | grep -q . || systemctl status "$service_name" >/dev/null 2>&1; then
            if systemctl restart "$service_name" >/dev/null 2>&1; then
                restarted=1
            else
                echo -e "$(localized_text "${YELLOW}⚠️ ${service_name} 重启失败，请稍后手动重启面板服务。${PLAIN}" "${YELLOW}⚠️ ${service_name} Restart failed, please manually restart the panel service later.${PLAIN}" "${YELLOW}⚠️ ${service_name} Не удалось перезапустить, перезапустите службу панели вручную позже.${PLAIN}")"
            fi
        fi
    done
    [[ "$restarted" -eq 1 ]] && echo -e "$(localized_text "${GREEN}✅ 已重启 3x-ui/x-ui 面板服务，使域名设置生效。${PLAIN}" "${GREEN}✅ The 3x-ui/x-ui panel service has been restarted to make the domain settings take effect.${PLAIN}" "${GREEN}✅ Служба панели 3x-ui/x-ui перезапущена, чтобы настройки доменного имени вступили в силу.${PLAIN}")"
}

update_xui_panel_domain_settings_for_single_443() {
    local old_domain="$1"
    local new_domain="$2"
    local db_path table_name backup_dir backup_file sql
    local checked=0 updated=0 failed=0 timestamp

    if xui_uses_postgresql; then
        echo -e "$(localized_text "${YELLOW}⚠️ 检测到 3x-ui 使用 PostgreSQL，跳过数据库自动同步。请在 3x-ui 中保持订阅监听 IP 为 127.0.0.1、监听域名留空，并将反向代理 URI 设置为 https://${new_domain}${SUB_URI_PATH}；节点 Host 使用实际节点域名和公网 443。${PLAIN}" "${YELLOW}⚠️ 3x-ui uses PostgreSQL, so database synchronization was skipped. In 3x-ui, keep the subscription listen IP at 127.0.0.1, leave the listen domain empty, and set Reverse Proxy URI to https://${new_domain}${SUB_URI_PATH}; use the actual node domain and public port 443 for the node Host.${PLAIN}" "${YELLOW}⚠️ 3x-ui использует PostgreSQL, поэтому синхронизация базы пропущена. В 3x-ui оставьте IP прослушивания подписки 127.0.0.1, домен прослушивания — пустым, задайте URI обратного прокси https://${new_domain}${SUB_URI_PATH}; в Host узла укажите фактический домен узла и публичный порт 443.${PLAIN}")"
        return 0
    fi

    if ! command -v sqlite3 >/dev/null 2>&1; then
        echo -e "$(localized_text "${CYAN}▶ 正在安装 sqlite3，用于同步 3x-ui 面板域名设置...${PLAIN}" "${CYAN}▶ Installing sqlite3 for synchronization of 3x-ui panel domain settings...${PLAIN}" "${CYAN}▶ Установка sqlite3 для синхронизации настроек доменного имени панели 3x-ui...${PLAIN}")"
        install_pkg sqlite3 sqlite >/dev/null 2>&1 || true
    fi
    if ! command -v sqlite3 >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 sqlite3，跳过自动同步 3x-ui 面板域名设置。${PLAIN}" "${YELLOW}⚠️ sqlite3 not detected, skipping automatic synchronization 3x-ui panel domain settings.${PLAIN}" "${YELLOW}⚠️ sqlite3 не обнаружен, автоматическая синхронизация пропускается. Настройки доменного имени панели 3x-ui.${PLAIN}")"
        return 0
    fi

    timestamp=$(date +%Y%m%d_%H%M%S)
    while IFS= read -r db_path; do
        [[ -f "$db_path" ]] || continue
        table_name=$(sqlite3 "$db_path" "select name from sqlite_master where type='table' and name in ('settings','setting') order by case name when 'settings' then 0 else 1 end limit 1;" 2>/dev/null || true)
        [[ "$table_name" == "settings" || "$table_name" == "setting" ]] || continue
        checked=1

        backup_dir="/root/x-ui-backups"
        mkdir -p "$backup_dir"
        backup_file="${backup_dir}/x-ui.db.panel_domain_${timestamp}.bak"
        if ! sqlite3 "$db_path" ".backup '${backup_file}'" >/dev/null 2>&1; then
            echo -e "$(localized_text "${YELLOW}⚠️ 备份 3x-ui 数据库失败，跳过自动同步：${db_path}${PLAIN}" "${YELLOW}⚠️ Backup 3x-ui database failed, automatic synchronization skipped: ${db_path}${PLAIN}" "${YELLOW}⚠️ Ошибка резервного копирования базы данных 3x-ui, автоматическая синхронизация пропущена: ${db_path}${PLAIN}")"
            failed=1
            continue
        fi

        sql="
update ${table_name} set value='' where lower(key)='webdomain';
update ${table_name} set value='' where lower(key)='subdomain';
update ${table_name} set value='https://${new_domain}${SUB_URI_PATH}' where lower(key)='suburi';
update ${table_name} set value='https://${new_domain}${CLASH_URI_PATH}' where lower(key)='subclashuri';
update ${table_name} set value=replace(replace(value,'https://${old_domain}','https://${new_domain}'),'http://${old_domain}','https://${new_domain}') where lower(key)='subjsonuri' and value like '%${old_domain}%';
"
        if sqlite3 "$db_path" "$sql" >/dev/null 2>&1; then
            echo -e "$(localized_text "${GREEN}✅ 已同步 3x-ui 面板/订阅域名设置：${db_path}${PLAIN}" "${GREEN}✅ Synchronized 3x-ui panel/subscription domain settings: ${db_path}${PLAIN}" "${GREEN}✅ Синхронизированные настройки панели 3x-ui/доменного имени подписки: ${db_path}${PLAIN}")"
            echo -e "$(localized_text "${CYAN}数据库备份：${backup_file}${PLAIN}" "${CYAN}Database backup: ${backup_file}${PLAIN}" "${CYAN}Резервное копирование базы данных : ${backup_file}${PLAIN}")"
            updated=1
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 同步 3x-ui 面板域名设置失败：${db_path}${PLAIN}" "${YELLOW}⚠️ Synchronization 3x-ui Panel domain setting failed: ${db_path}${PLAIN}" "${YELLOW}⚠️ Синхронизация 3x-ui Не удалось настроить доменное имя панели: ${db_path}${PLAIN}")"
            failed=1
        fi
    done < <(find_xui_database_candidates)

    [[ "$updated" -eq 1 ]] && restart_xui_panel_services_after_setting_update
    if [[ "$failed" -eq 1 ]]; then
        echo -e "$(localized_text "${RED}❌ 3x-ui 面板域名设置未完整同步，已停止修改 443 面板域名。${PLAIN}" "${RED}❌ 3x-ui The panel domain settings are not completely synchronized, and the modification of the 443 panel domain has been stopped.${PLAIN}" "${RED}❌ 3x-ui Настройки доменного имени панели не полностью синхронизированы, и изменение доменного имени панели 443 остановлено.${PLAIN}")"
        return 1
    fi
    if [[ "$checked" -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未找到 3x-ui 数据库，跳过 3x-ui 面板内部域名同步。${PLAIN}" "${YELLOW}⚠️ 3x-ui database not found, skipping 3x-ui panel internal domain synchronization.${PLAIN}" "${YELLOW}⚠️ База данных 3x-ui не найдена, пропуская внутреннюю синхронизацию доменного имени панели 3x-ui.${PLAIN}")"
    fi
    return 0
}

edit_sni_stack_panel_subscription_profile() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}修改 3x-ui 面板 / 订阅端口与路径${PLAIN}" "${BOLD}Modified 3x-ui panel / subscription port and path${PLAIN}" "${BOLD}модифицированная панель 3x-ui/порт и путь подписки${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    echo -e "$(localized_text "${YELLOW}适用于：你在 3x-ui 里修改了面板端口、订阅端口、普通订阅路径或 Clash/Mihomo 路径。${PLAIN}" "${YELLOW}Applies to: You modified the panel port, subscription port, normal subscription path or Clash/Mihomo path in 3x-ui.${PLAIN}" "${YELLOW}применяется к: Вы изменили порт панели, порт подписки, обычный путь подписки или путь Clash/Mihomo в 3x-ui.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}注意：3x-ui 3.x 新安装选第 4 项 Skip SSL，再选 y 仅绑定 127.0.0.1；2.x 或旧配置仍需清空面板和订阅证书路径。${PLAIN}" "${YELLOW}Note: for a new 3x-ui 3.x installation, choose option 4, Skip SSL, then y to bind only to 127.0.0.1. For 2.x or existing installations, clear the panel and subscription certificate paths.${PLAIN}" "${YELLOW}Примечание: при новой установке 3x-ui 3.x выберите пункт 4 Skip SSL, затем y для привязки только к 127.0.0.1. В 2.x и существующих установках очистите пути сертификатов панели и подписки.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}修改前请先在 3x-ui 面板里保存对应设置，再来这里同步脚本。${PLAIN}" "${YELLOW}Before modifying , please save the corresponding settings in the 3x-ui panel, and then synchronize the script here.${PLAIN}" "${YELLOW}Перед изменением сохраните соответствующие настройки на панели 3x-ui, а затем синхронизируйте скрипт здесь.${PLAIN}")"
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "当前面板后端：${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "Current panel backend: ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "Текущая панель управления: ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}.")"
    echo -e "$(localized_text "当前面板公网路径：${PANEL_WEB_PATH}" "Current panel public path: ${PANEL_WEB_PATH}" "Путь текущей панели в публичной сети: ${PANEL_WEB_PATH}.")"
    echo -e "$(localized_text "当前订阅后端：${SUB_LISTEN_ADDR}:${SUB_LISTEN_PORT}" "Current subscription backend: ${SUB_LISTEN_ADDR}:${SUB_LISTEN_PORT}" "бэкенд текущей подписки: ${SUB_LISTEN_ADDR}:${SUB_LISTEN_PORT}.")"
    echo -e "$(localized_text "当前普通订阅路径：${SUB_URI_PATH}" "Current common subscription path: ${SUB_URI_PATH}" "Текущий общий путь подписки: ${SUB_URI_PATH}.")"
    echo -e "$(localized_text "当前 Clash/Mihomo 路径：${CLASH_URI_PATH}" "Current Clash/Mihomo path: ${CLASH_URI_PATH}" "Текущий путь Clash/Mihomo: ${CLASH_URI_PATH}")"
    echo -e "------------------------------------------------"

    PANEL_LISTEN_ADDR=$(ask_with_default "$(localized_text "3x-ui 面板监听地址" "3x-ui panel listening address" "Адрес прослушивания панели 3x-ui")" "$PANEL_LISTEN_ADDR")
    PANEL_LISTEN_PORT=$(ask_with_default "$(localized_text "3x-ui 面板端口" "3x-ui panel port" "Порт панели 3x-ui")" "$PANEL_LISTEN_PORT")
    PANEL_WEB_PATH=$(normalize_path_prefix "$(ask_with_default "$(localized_text "3x-ui 面板公网路径 / webBasePath" "3x-ui public panel path / webBasePath" "Публичный путь панели 3x-ui / webBasePath")" "$PANEL_WEB_PATH")")
    SUB_LISTEN_ADDR=$(ask_with_default "$(localized_text "3x-ui 订阅服务监听地址" "3x-ui Subscription service listening address" "3x-ui Адрес прослушивания службы подписки")" "$SUB_LISTEN_ADDR")
    SUB_LISTEN_PORT=$(ask_with_default "$(localized_text "3x-ui 订阅服务端口" "3x-ui Subscription service port" "3x-ui Порт службы подписки")" "$SUB_LISTEN_PORT")
    SUB_URI_PATH=$(normalize_path_prefix "$(ask_with_default "$(localized_text "普通订阅路径前缀（不带客户端 Subscription，建议写 /sub/）" "Standard subscription path prefix (without client identifier; recommended: /sub/)" "Префикс обычной подписки (без идентификатора клиента; рекомендуется /sub/)")" "$SUB_URI_PATH")")
    CLASH_URI_PATH=$(normalize_path_prefix "$(ask_with_default "$(localized_text "Clash/Mihomo 订阅路径前缀（不带客户端 Subscription，建议写 /clash/）" "Clash/Mihomo subscription path prefix (without client identifier; recommended: /clash/)" "Префикс подписки Clash/Mihomo (без идентификатора клиента; рекомендуется /clash/)")" "$CLASH_URI_PATH")")

    is_valid_listen_addr "$PANEL_LISTEN_ADDR" || { echo -e "$(localized_text "${RED}❌ 面板监听地址无效：${PANEL_LISTEN_ADDR}${PLAIN}" "${RED}❌ The panel listening address is invalid: ${PANEL_LISTEN_ADDR}${PLAIN}" "${RED}❌ Неверный адрес прослушивания панели: ${PANEL_LISTEN_ADDR}.${PLAIN}")"; return 1; }
    is_valid_listen_addr "$SUB_LISTEN_ADDR" || { echo -e "$(localized_text "${RED}❌ 订阅监听地址无效：${SUB_LISTEN_ADDR}${PLAIN}" "${RED}❌ The subscription listening address is invalid: ${SUB_LISTEN_ADDR}${PLAIN}" "${RED}❌ Неверный адрес прослушивания подписки: ${SUB_LISTEN_ADDR}.${PLAIN}")"; return 1; }
    is_valid_port "$PANEL_LISTEN_PORT" || { echo -e "$(localized_text "${RED}❌ 面板端口无效：${PANEL_LISTEN_PORT}${PLAIN}" "${RED}❌ Invalid panel port: ${PANEL_LISTEN_PORT}${PLAIN}" "${RED}❌ Неверный порт панели: ${PANEL_LISTEN_PORT}.${PLAIN}")"; return 1; }
    is_valid_port "$SUB_LISTEN_PORT" || { echo -e "$(localized_text "${RED}❌ 订阅端口无效：${SUB_LISTEN_PORT}${PLAIN}" "${RED}❌ Invalid subscription port: ${SUB_LISTEN_PORT}${PLAIN}" "${RED}❌ Неверный порт подписки: ${SUB_LISTEN_PORT}.${PLAIN}")"; return 1; }
    is_valid_path_prefix "$PANEL_WEB_PATH" || { echo -e "$(localized_text "${RED}❌ 面板公网路径无效：${PANEL_WEB_PATH}${PLAIN}" "${RED}❌ The public path of the panel is invalid: ${PANEL_WEB_PATH}${PLAIN}" "${RED}❌ Неверный путь панели в публичной сети: ${PANEL_WEB_PATH}.${PLAIN}")"; return 1; }
    is_valid_path_prefix "$SUB_URI_PATH" || { echo -e "$(localized_text "${RED}❌ 普通订阅路径无效：${SUB_URI_PATH}${PLAIN}" "${RED}❌ The normal subscription path is invalid: ${SUB_URI_PATH}${PLAIN}" "${RED}❌ Неверный обычный путь подписки: ${SUB_URI_PATH}.${PLAIN}")"; return 1; }
    is_valid_path_prefix "$CLASH_URI_PATH" || { echo -e "$(localized_text "${RED}❌ Clash/Mihomo 路径无效：${CLASH_URI_PATH}${PLAIN}" "${RED}❌ Clash/Mihomo Invalid path: ${CLASH_URI_PATH}${PLAIN}" "${RED}❌ Clash/Mihomo Неверный путь: ${CLASH_URI_PATH}${PLAIN}")"; return 1; }
    if [[ "$PANEL_WEB_PATH" == "$SUB_URI_PATH" || "$PANEL_WEB_PATH" == "$CLASH_URI_PATH" || "$SUB_URI_PATH" == "$CLASH_URI_PATH" ]]; then
        echo -e "$(localized_text "${RED}❌ 面板路径、普通订阅路径、Clash/Mihomo 路径不能相同。${PLAIN}" "${RED}❌ The panel path, normal subscription path, and Clash/Mihomo path cannot be the same.${PLAIN}" "${RED}❌ Путь к панели, обычный путь подписки и путь Clash/Mihomo не могут совпадать.${PLAIN}")"
        return 1
    fi
    warn_if_public_bind "$(localized_text "3x-ui 面板" "3x-ui panel" "Панель 3x-ui")" "$PANEL_LISTEN_ADDR" "$PANEL_LISTEN_PORT" || return 1
    warn_if_public_bind "$(localized_text "3x-ui 订阅服务" "3x-ui Subscription Service" "Служба подписки 3x-ui")" "$SUB_LISTEN_ADDR" "$SUB_LISTEN_PORT" || return 1

    save_and_offer_reapply_sni_stack
}

edit_sni_stack_reality_profile() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}修改 REALITY 本地监听与伪装 SNI${PLAIN}" "${BOLD}Modified REALITY local listeners and disguise SNI${PLAIN}" "${BOLD}модифицированный REALITY локальный прослушивание и маскировка SNI${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    echo -e "$(localized_text "${YELLOW}适用于：你在 3x-ui+Reality 入站中修改了监听端口、监听地址，或更换了伪装 SNI。${PLAIN}" "${YELLOW}Applies when you changed the listen port, listen address, or camouflage SNI of a 3x-ui+Reality inbound.${PLAIN}" "${YELLOW}Применяется, если вы изменили порт или адрес прослушивания либо маскировочный SNI входящего 3x-ui+Reality.${PLAIN}")"
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "当前 REALITY：${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}" "Current REALITY: ${XRAY_LISTEN_ADDR}: ${XRAY_LISTEN_PORT}" "Текущий REALITY: ${XRAY_LISTEN_ADDR}: ${XRAY_LISTEN_PORT}")"
    echo -e "$(localized_text "当前 REALITY SNI：${REALITY_SNI}" "Current REALITY SNI: ${REALITY_SNI}" "Текущий REALITY SNI: ${REALITY_SNI}")"
    echo -e "------------------------------------------------"

    local reality_sni_input
    XRAY_LISTEN_ADDR=$(ask_with_default "$(localized_text "Xray / 3x-ui+Reality 入站本地监听地址" "Xray / 3x-ui+Reality inbound local listening address" "Локальный адрес прослушивания входящего Xray / 3x-ui+Reality")" "$XRAY_LISTEN_ADDR")
    XRAY_LISTEN_PORT=$(ask_with_default "$(localized_text "Xray / 3x-ui+Reality 入站本地监听端口" "Xray / 3x-ui+Reality inbound local listening port" "Локальный порт прослушивания входящего Xray / 3x-ui+Reality")" "$XRAY_LISTEN_PORT")
    reality_sni_input=$(ask_with_default "$(localized_text "REALITY 伪装 SNI" "REALITY disguise SNI" "Маскировка REALITY SNI")" "$REALITY_SNI")
    REALITY_SNI=$(normalize_domain_input "$reality_sni_input")

    is_valid_listen_addr "$XRAY_LISTEN_ADDR" || { echo -e "$(localized_text "${RED}❌ REALITY 监听地址无效：${XRAY_LISTEN_ADDR}${PLAIN}" "${RED}❌ REALITY The listening address is invalid: ${XRAY_LISTEN_ADDR}${PLAIN}" "${RED}❌ REALITY Неверный адрес прослушивания: ${XRAY_LISTEN_ADDR}${PLAIN}")"; return 1; }
    is_valid_port "$XRAY_LISTEN_PORT" || { echo -e "$(localized_text "${RED}❌ REALITY 端口无效：${XRAY_LISTEN_PORT}${PLAIN}" "${RED}❌ REALITY Invalid port: ${XRAY_LISTEN_PORT}${PLAIN}" "${RED}❌ REALITY Неверный порт: ${XRAY_LISTEN_PORT}${PLAIN}")"; return 1; }
    is_valid_domain "$REALITY_SNI" || { print_domain_validation_error "REALITY SNI" "$reality_sni_input" "$REALITY_SNI"; return 1; }
    [[ "$REALITY_SNI" == "$PANEL_DOMAIN" ]] && { echo -e "$(localized_text "${RED}❌ REALITY SNI 不能写面板域名。${PLAIN}" "${RED}❌ REALITY SNI The panel domain cannot be written.${PLAIN}" "${RED}❌ REALITY SNI Невозможно записать доменное имя панели.${PLAIN}")"; return 1; }
    local existing
    for existing in "${SITE_DOMAINS[@]}" "${TCP_ROUTE_SNIS[@]}" "${XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$REALITY_SNI" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ REALITY SNI 不能和其他 443 分流域名相同：${existing}${PLAIN}" "${RED}❌ REALITY SNI cannot be the same as other 443 routing domains: ${existing}${PLAIN}" "${RED}❌ REALITY SNI не может совпадать с другими именами доменов маршрутизация 443: ${existing}${PLAIN}")"; return 1; }
    done
    warn_if_public_bind "Xray REALITY" "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT" || return 1
    probe_reality_sni "$REALITY_SNI" || return 1

    save_and_offer_reapply_sni_stack
}

edit_sni_stack_entry_profile() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}修改 443 入口 / Web 反代监听${PLAIN}" "${BOLD}Modified 443 entry / Web reverse proxy listening${PLAIN}" "${BOLD}модифицированный вход 443 / прослушивание обратного веб-прокси${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    local web_label
    web_label=$(web_proxy_engine_label)
    echo -e "$(localized_text "${YELLOW}适用于：你要调整公网入口端口、Web 反代本地 TLS 端口，或修正监听地址。普通用户建议保持默认。${PLAIN}" "${YELLOW}Suitable for: you want to adjust the public entry port, Web reverse local TLS port, or modify the listening address. Ordinary users are advised to keep the default setting.${PLAIN}" "${YELLOW}подходит для: вы хотите настроить порт входа в публичную сеть, обратный локальный веб-порт TLS или изменить адрес прослушивания. Обычным пользователям рекомендуется сохранить настройки по умолчанию.${PLAIN}")"
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "当前公网入口：${NGINX_LISTEN_ADDR}:${NGINX_LISTEN_PORT}" "Current public entry: ${NGINX_LISTEN_ADDR}:${NGINX_LISTEN_PORT}" "Текущий вход в публичную сеть: ${NGINX_LISTEN_ADDR}:${NGINX_LISTEN_PORT}.")"
    echo -e "$(localized_text "当前 ${web_label} 本地 TLS：${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT}" "Current ${web_label} Local TLS:${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT}" "Текущий ${web_label} Локальный TLS:${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT}")"
    echo -e "------------------------------------------------"

    NGINX_LISTEN_ADDR=$(ask_with_default "$(localized_text "Nginx 公网监听地址" "Nginx public listening address" "Nginx адрес прослушивания публичной сети")" "$NGINX_LISTEN_ADDR")
    NGINX_LISTEN_PORT=$(ask_with_default "$(localized_text "Nginx 公网监听端口" "Nginx public listening port" "Порт прослушивания публичной сети Nginx")" "$NGINX_LISTEN_PORT")
    CADDY_LISTEN_ADDR=$(ask_with_default "$(localized_text "${web_label}监听地址" "${web_label} listening address" "Адрес прослушивания ${web_label}")" "$CADDY_LISTEN_ADDR")
    CADDY_LISTEN_PORT=$(ask_with_default "$(localized_text "${web_label}监听端口" "${web_label} listening port" "Порт прослушивания ${web_label}")" "$CADDY_LISTEN_PORT")

    is_valid_listen_addr "$NGINX_LISTEN_ADDR" || { echo -e "$(localized_text "${RED}❌ Nginx 监听地址无效：${NGINX_LISTEN_ADDR}${PLAIN}" "${RED}❌ Nginx The listening address is invalid: ${NGINX_LISTEN_ADDR}${PLAIN}" "${RED}❌ Nginx Неверный адрес прослушивания: ${NGINX_LISTEN_ADDR}${PLAIN}")"; return 1; }
    is_valid_listen_addr "$CADDY_LISTEN_ADDR" || { echo -e "$(localized_text "${RED}❌ Web 反代监听地址无效：${CADDY_LISTEN_ADDR}${PLAIN}" "${RED}❌ Web reverse proxy listening address is invalid: ${CADDY_LISTEN_ADDR}${PLAIN}" "${RED}❌ Недопустимый адрес прослушивания веб-прокси: ${CADDY_LISTEN_ADDR}.${PLAIN}")"; return 1; }
    is_valid_port "$NGINX_LISTEN_PORT" || { echo -e "$(localized_text "${RED}❌ Nginx 端口无效：${NGINX_LISTEN_PORT}${PLAIN}" "${RED}❌ Nginx Invalid port: ${NGINX_LISTEN_PORT}${PLAIN}" "${RED}❌ Nginx Неверный порт: ${NGINX_LISTEN_PORT}${PLAIN}")"; return 1; }
    is_valid_port "$CADDY_LISTEN_PORT" || { echo -e "$(localized_text "${RED}❌ Web 反代端口无效：${CADDY_LISTEN_PORT}${PLAIN}" "${RED}❌ Web reverse proxy port is invalid: ${CADDY_LISTEN_PORT}${PLAIN}" "${RED}❌ Неверный порт веб-прокси: ${CADDY_LISTEN_PORT}.${PLAIN}")"; return 1; }
    warn_if_public_bind "$web_label" "$CADDY_LISTEN_ADDR" "$CADDY_LISTEN_PORT" || return 1
    if [[ "$NGINX_LISTEN_PORT" != "443" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️  Nginx 公网入口不是 443。请确认云安全组、防火墙和客户端地址都同步改了。${PLAIN}" "${YELLOW}⚠️ Nginx The public entry is not 443. Please confirm that the cloud security group, firewall and client address have all been changed simultaneously.${PLAIN}" "${YELLOW}⚠️ Nginx Вход в публичную сеть не 443. Подтвердите, что группа безопасности облака, брандмауэр и адрес клиента были изменены одновременно.${PLAIN}")"
    fi

    save_and_offer_reapply_sni_stack
}

edit_sni_stack_panel_domain_profile() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}修改面板域名${PLAIN}" "${BOLD}Modify the panel domain${PLAIN}" "${BOLD}Измените доменное имя панели.${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1

    local cf_env_file="/root/.config/vps-panel/cloudflare.env"
    if [[ ! -f "$cf_env_file" ]]; then
        echo -e "$(localized_text "${RED}❌ 未找到 Cloudflare Token，请先到证书维护菜单更新 Token。${PLAIN}" "${RED}❌ Cloudflare Token was not found. Please go to the certificate maintenance menu to update the token first.${PLAIN}" "${RED}❌ Cloudflare Токен не найден. Пожалуйста, перейдите в меню обслуживания сертификатов, чтобы сначала обновить токен.${PLAIN}")"
        return 1
    fi
    # shellcheck disable=SC1090
    source "$cf_env_file"
    if [[ -z "${CF_Token:-}" ]]; then
        echo -e "$(localized_text "${RED}❌ Cloudflare Token 为空，请先到证书维护菜单更新。${PLAIN}" "${RED}❌ Cloudflare Token is empty, please go to the certificate maintenance menu to update it first.${PLAIN}" "${RED}❌ Cloudflare Токен пуст. Сначала перейдите в меню обслуживания сертификата, чтобы обновить его.${PLAIN}")"
        return 1
    fi

    local old_domain new_domain new_domain_input existing confirm old_conf
    old_domain="$PANEL_DOMAIN"
    echo -e "$(localized_text "当前面板域名：${old_domain}" "Current panel domain: ${old_domain}" "Доменное имя текущей панели: ${old_domain}.")"
    echo -e "$(localized_text "${YELLOW}修改前请先把新域名解析到当前 VPS，并确认 Cloudflare Token 有该 zone 权限。${PLAIN}" "${YELLOW}Before modifying , please resolve the new domain to the current VPS and confirm that Cloudflare Token has the zone permission.${PLAIN}" "${YELLOW}Прежде чем изменять , разрешите новое доменное имя текущему VPS и подтвердите, что токен Cloudflare имеет разрешение зоны.${PLAIN}")"
    new_domain_input=$(ask_with_default "$(localized_text "新的面板域名" "New panel domain" "Новое доменное имя панели")" "$PANEL_DOMAIN")
    new_domain=$(normalize_domain_input "$new_domain_input")
    [[ "$new_domain" == "$old_domain" ]] && { echo -e "$(localized_text "${BLUE}面板域名未变化。${PLAIN}" "${BLUE}The panel domain has not changed.${PLAIN}" "${BLUE}Доменное имя панели не изменилось.${PLAIN}")"; return 0; }
    is_valid_domain "$new_domain" || { print_domain_validation_error "$(localized_text "面板域名" "Panel domain" "Доменное имя панели")" "$new_domain_input" "$new_domain"; return 1; }
    [[ "$new_domain" == "$REALITY_SNI" ]] && { echo -e "$(localized_text "${RED}❌ 面板域名不能和 REALITY SNI 相同。${PLAIN}" "${RED}❌ The panel domain cannot be the same as REALITY SNI.${PLAIN}" "${RED}❌ Доменное имя панели не может совпадать с REALITY SNI.${PLAIN}")"; return 1; }
    for existing in "${SITE_DOMAINS[@]}"; do
        [[ "$new_domain" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 面板域名不能和网站/反代域名相同。${PLAIN}" "${RED}❌ The panel domain cannot be the same as the website/reverse proxy domain.${PLAIN}" "${RED}❌ Доменное имя панели не может совпадать с именем домена веб-сайта/обратного прокси-сервера.${PLAIN}")"; return 1; }
    done
    for existing in "${TCP_ROUTE_SNIS[@]}"; do
        [[ "$new_domain" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 面板域名不能和 TCP/SNI 入站域名相同。${PLAIN}" "${RED}The ❌ panel domain cannot be the same as the TCP/SNI inbound domain.${PLAIN}" "${RED}Доменное имя панели ❌ не может совпадать с именем входящего домена TCP/SNI.${PLAIN}")"; return 1; }
    done
    for existing in "${XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$new_domain" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 面板域名不能和 Xray 入站域名相同。${PLAIN}" "${RED}The ❌ panel domain cannot be the same as the Xray inbound domain.${PLAIN}" "${RED}Доменное имя панели ❌ не может совпадать с именем входящего домена Xray.${PLAIN}")"; return 1; }
    done
    check_domain_dns_sanity "$new_domain" "$(localized_text "新的面板域名" "New panel domain" "Новое доменное имя панели")" "prompt" || return 1
    confirm_risk_action "$(localized_text "替换 443 面板域名为 ${new_domain}" "Replace the 443 panel domain with ${new_domain}" "Замените доменное имя панели 443 на ${new_domain}.")" \
        "$(localized_text "面板域名、证书和 Caddy/Nginx 相关配置" "Panel domain, certificate and Caddy/Nginx related configuration" "Доменное имя панели, сертификат и конфигурация, связанная с Caddy/Nginx.")" \
        "$(localized_text "使用 443端口复用备份恢复旧域名配置" "Use Port 443 Reuse backup to restore the old domain configuration" "Восстановите старую конфигурацию доменного имени с помощью резервной копии повторного использования порта 443.")" \
        "$(localized_text "确认新域名 DNS 已解析到当前 VPS，且 Token 有该 zone 权限。" "Confirm that the new domain DNS has been resolved to the current VPS, and the Token has the zone permissions." "Убедитесь, что новое доменное имя DNS разрешено текущему VPS, а токен имеет разрешения зоны.")" || return 1

    issue_and_install_cert_for_domain "$new_domain" "$CF_Token" || return 1
    update_xui_panel_domain_settings_for_single_443 "$old_domain" "$new_domain" || return 1
    old_conf="/etc/caddy/conf.d/${old_domain}.caddy"
    [[ -f "$old_conf" ]] && quarantine_path "$old_conf" "/etc/caddy/conf.d_quarantine" >/dev/null 2>&1 || true
    PANEL_DOMAIN="$new_domain"
    rename_sni_ip_whitelist_domain "$old_domain" "$new_domain"
    save_and_offer_reapply_sni_stack
}

edit_sni_stack_runtime_profile() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}🧭 修改 443 分流参数${PLAIN}" "${BOLD}🧭 Modify 443 routing parameters${PLAIN}" "${BOLD}🧭 Изменение 443 параметров маршрутизации${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}用途：后续修改面板端口/路径、订阅端口/路径、REALITY SNI、入口端口时使用。${PLAIN}" "${YELLOW}Purpose: Used when subsequently modifying the panel port/path, subscription port/path, REALITY, SNI, and entry port.${PLAIN}" "${YELLOW}Назначение: используется при последующем изменении порта/пути панели, порта/пути подписки, REALITY, SNI и входного порта.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}修改面板域名请走主菜单 [19 443端口复用管理中心] -> [8 管理 Web 域名/反代] -> [9 修改面板域名]。${PLAIN}" "${YELLOW}To modify the panel domain, please go to the main menu [19 Port 443 Reuse Manager] -> [8 Manage Web domain/Reverse Proxy] -> [9 Modify Panel domain].${PLAIN}" "${YELLOW}Чтобы изменить имя домена панели, перейдите в главное меню [19 Управление повторным использованием порта 443] -> [8 Управление именем веб-домена/обратным прокси] -> [9 Изменить имя домена панели].${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}新增网站请走 [19] -> [8]，不用重跑首次配置。${PLAIN}" "${YELLOW}Please go to [19] -> [8] to add a new website. There is no need to rerun the first configuration.${PLAIN}" "${YELLOW}Пожалуйста, перейдите в [19] -> [8], чтобы добавить новый веб-сайт. Нет необходимости повторно запускать первую конфигурацию.${PLAIN}")"
        echo -e "------------------------------------------------"
        if load_sni_stack_env >/dev/null 2>&1; then
            print_sni_stack_current_summary
        else
            echo -e "$(localized_text "${RED}未找到 443 配置，请先运行 [19] -> [2]。${PLAIN}" "${RED}443 configuration not found, please run [19] -> [2] first.${PLAIN}" "${RED}Конфигурация 443 не найдена, сначала запустите [19] -> [2].${PLAIN}")"
            return 1
        fi
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 修改面板/订阅端口与路径${PLAIN}" "${GREEN}1. Modify the panel/subscription port and path${PLAIN}" "${GREEN}1. Измените порт панели/подписки и путь.${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 修改 REALITY 本地监听 / 伪装 SNI${PLAIN}" "${GREEN}2. Modify REALITY local listeners/disguise SNI${PLAIN}" "${GREEN}2. Изменить REALITY локальный прослушивание/маскировку SNI${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  3. 修改 Nginx 公网入口 / Web 反代本地 TLS${PLAIN}" "${GREEN}3. Modify Nginx public entry/Web to replace local TLS${PLAIN}" "${GREEN}3. Измените Nginx вход в публичную сеть/Интернет для замены локального TLS.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}  4. 修改面板域名：请走 [8] -> [9]${PLAIN}" "${YELLOW}4. Modify the panel domain: please go [8] -> [9]${PLAIN}" "${YELLOW}4. Измените доменное имя панели: выберите [8] -> [9].${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  5. 重新应用当前保存的配置${PLAIN}" "${GREEN}5. Reapply the currently saved configuration${PLAIN}" "${GREEN}5. Повторно примените текущую сохраненную конфигурацию.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${BLUE}  ?. 查看帮助${PLAIN}" "${BLUE}?. View help${PLAIN}" "${BLUE}?. Посмотреть справку${PLAIN}")"
        echo -e "$(localized_text "${RED}  0. 返回上一级 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local choice
        read_trimmed choice "$(localized_text "👉 请输入菜单编号或 ?: " "👉 Please enter menu number or ?:" "👉 Пожалуйста, введите номер меню или ?:")"
        case "$choice" in
            1) edit_sni_stack_panel_subscription_profile ;;
            2) edit_sni_stack_reality_profile ;;
            3) edit_sni_stack_entry_profile ;;
            4) echo -e "$(localized_text "${YELLOW}请使用：主菜单 [19 443端口复用管理中心] -> [8 管理 Web 域名/反代] -> [9 修改面板域名]。${PLAIN}" "${YELLOW}Please use: Main menu [19 Port 443 Reuse Manager] -> [8 Manage Web domain/Reverse Proxy] -> [9 Modify Panel domain].${PLAIN}" "${YELLOW}Используйте: Главное меню [19 Управление повторным использованием порта 443] -> [8 Управление именем веб-домена/обратным прокси-сервером] -> [9 Изменить имя домена панели].${PLAIN}")" ;;
            5) reapply_sni_stack_from_env ;;
            "?") show_sni_help; pause_return; continue ;;
            0) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择，请输入菜单编号或 ?。${PLAIN}" "${RED}❌ Invalid selection, please enter the menu number or ?.${PLAIN}" "${RED}❌ Неверный выбор, введите номер меню или ?.${PLAIN}")"; sleep 1 ;;
        esac
        echo ""
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    done
}

reapply_sni_stack_from_env() {
    load_sni_stack_env || return 1
    if [[ "${1:-}" != "--yes" ]]; then
        print_sni_stack_preview || return 1
    fi
    reapply_current_entry_mode --yes
}

# ---------------------------------------------------------
# Module: sni_stack_install.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Port 443 Reuse collection, installation, rendering, certificates, and runtime apply flows.

collect_sni_stack_config() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}443端口复用配置${PLAIN}" "${BOLD}Port 443 Reuse configuration${PLAIN}" "${BOLD}Конфигурация повторного использования порта 443${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${YELLOW}公网 443 将由你选择的入口模式监听；Web 域名、反代引擎、证书和白名单为三种模式共享。${PLAIN}" "${YELLOW}Public port 443 will be monitored by the entry mode you choose; the web domain, reverse proxy engine, certificate and whitelist are shared by the three modes.${PLAIN}" "${YELLOW}Публичный порт  443 будет контролироваться выбранным вами режимом входа; имя веб-домена, механизм обратного прокси-сервера, сертификат и белый список являются общими для всех трех режимов.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}Web 反代引擎、Xray/3x-ui 本地后端默认绑定 127.0.0.1。${PLAIN}" "${YELLOW}Web reverse proxy engine and Xray/3x-ui local backend are bound to 127.0.0.1 by default.${PLAIN}" "${YELLOW}Механизм обратный прокси Web и локальный бэкэнд Xray/3x-ui по умолчанию привязаны к 127.0.0.1.${PLAIN}")"
    echo -e "------------------------------------------------"

    local default_panel_addr="127.0.0.1"
    local default_panel_port="40000"
    local default_panel_path="/panel/"
    local default_sub_addr="127.0.0.1"
    local default_sub_port="2096"
    local default_sub_path="/sub/"
    local default_clash_path="/clash/"
    detect_xui_single_443_defaults
    if [[ -n "${XUI_DETECTED_BIN:-}" || -n "${XUI_DETECTED_DB:-}" ]]; then
        default_panel_addr="${XUI_DETECTED_PANEL_ADDR:-127.0.0.1}"
        default_panel_port="${XUI_DETECTED_WEB_PORT:-40000}"
        default_panel_path="${XUI_DETECTED_WEB_BASE_PATH:-/panel/}"
        default_sub_addr="${XUI_DETECTED_SUB_ADDR:-127.0.0.1}"
        default_sub_port="${XUI_DETECTED_SUB_PORT:-2096}"
        default_sub_path="${XUI_DETECTED_SUB_PATH:-/sub/}"
        default_clash_path="${XUI_DETECTED_SUB_CLASH_PATH:-/clash/}"
    fi
    print_xui_single_443_detected_defaults
    echo -e "------------------------------------------------"

    local panel_domain_input reality_sni_input
    read_trimmed panel_domain_input "$(localized_text "面板域名（必填，例如 panel.example.com）: " "Panel domain (required, for example panel.example.com):" "Доменное имя Panel (обязательно, например Panel.example.com):")"
    PANEL_DOMAIN="$panel_domain_input"
    local web_engine_choice
    WEB_PROXY_ENGINE="caddy"
    echo -e "$(localized_text "${CYAN}请选择 443端口复用 Web 反代引擎：${PLAIN}" "${CYAN}Please select Port 443 Reuse Web reverse proxy engine:${PLAIN}" "${CYAN}Выберите механизм веб-прокси с повторным использованием порта 443:${PLAIN}")"
    echo -e "$(localized_text "${GREEN}  1. Caddy 本地 HTTPS 反代${PLAIN} ${YELLOW}(默认，兼容现有 443端口复用配置)${PLAIN}" "${GREEN}1. Caddy local HTTPS reverse proxy   (default, compatible with existing Port 443 Reuse configuration)${PLAIN}" "${GREEN}1. Caddy локальный HTTPS обратный прокси (по умолчанию, совместимо с существующей конфигурацией повторного использования порта 443)${PLAIN}")"
    echo -e "$(localized_text "${GREEN}  2. Nginx 本地 HTTPS 反代${PLAIN} ${YELLOW}(只监听本地端口，不抢公网 443)${PLAIN}" "${GREEN}2. Nginx local HTTPS reverse proxy (only listens to the local port, does not grab the public port 443)${PLAIN}" "${GREEN}2. Nginx локальный HTTPS обратный прокси-сервер   (прослушивает только локальный порт и не захватывает публичный порт 443)${PLAIN}")"
    read_trimmed web_engine_choice "$(localized_text "请选择 Web 反代引擎（默认 1）: " "Please select a web reverse proxy engine (default 1):" "Пожалуйста, выберите механизм веб-прокси (по умолчанию 1):")"
    case "${web_engine_choice:-1}" in
        1) WEB_PROXY_ENGINE="caddy" ;;
        2) WEB_PROXY_ENGINE="nginx" ;;
        *) echo -e "$(localized_text "${RED}❌ 无效的 Web 反代引擎选择。${PLAIN}" "${RED}❌ Invalid web reverse proxy engine selection.${PLAIN}" "${RED}❌ Неверный выбор механизма веб-прокси.${PLAIN}")"; return 1 ;;
    esac
    SITE_DOMAINS=()
    SITE_BACKEND_ADDRS=()
    SITE_BACKEND_PORTS=()
    TCP_ROUTE_SNIS=()
    TCP_ROUTE_ADDRS=()
    TCP_ROUTE_PORTS=()
    SNI_IP_WHITELIST_DOMAINS=()
    SNI_IP_WHITELIST_RANGES=()
    local site_domains_input
    local -a site_domain_raw_inputs=()
    site_domains_input=$(ask_with_default "$(localized_text "网站/反代域名（可选，多个用英文逗号分隔，例如 site1.example.com,site2.example.com）" "Website/reverse domain (optional, separate multiple with commas, such as site1.example.com,site2.example.com)" "Веб-сайт/обратное доменное имя (необязательно, разделяйте запятыми, например site1.example.com,site2.example.com)")" "")
    split_csv_to_array "$site_domains_input" SITE_DOMAINS
    site_domain_raw_inputs=("${SITE_DOMAINS[@]}")
    echo -e "$(localized_text "${YELLOW}REALITY 伪装 SNI 请填写外部真实 HTTPS 站点域名，不要填写面板域名或节点域名。${PLAIN}" "${YELLOW}REALITY Disguise SNI Please fill in the external real HTTPS site domain, do not fill in the panel domain or node domain.${PLAIN}" "${YELLOW}REALITY Маскировка SNI Пожалуйста, укажите внешнее реальное доменное имя сайта HTTPS, не заполняйте имя домена панели или имя домена узла.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}模板示例：your-reality-sni.example.com（请替换成你自己选择的真实站点）${PLAIN}" "${YELLOW}Template example: your-reality-sni.example.com (please replace it with the real site of your choice)${PLAIN}" "${YELLOW}Пример шаблона : your-reality-sni.example.com (замените его реальным сайтом по вашему выбору)${PLAIN}")"
    read_trimmed reality_sni_input "$(localized_text "REALITY 伪装 SNI（必填）: " "REALITY Disguise SNI (required):" "REALITY Маскировка SNI (обязательно):")"
    REALITY_SNI="$reality_sni_input"
    STRICT_SNI_GATE="false"
    if strict_sni_gate_mode_supported "${ENTRY_MODE:-nginx-stream}"; then
        echo -e "$(localized_text "${YELLOW}若 REALITY target 使用 CDN，验证失败的连接可能把服务器变成转发节点。严格 SNI 门禁会自动放行面板、网站、TCP/Xray 路由和 REALITY SNI，其他 SNI 直接丢弃。${PLAIN}" "${YELLOW}If the REALITY target uses a CDN, failed-authentication connections can turn the server into a relay. The strict SNI gate automatically allows panel, site, TCP/Xray route, and REALITY SNIs, and drops all other SNIs.${PLAIN}" "${YELLOW}Если REALITY target использует CDN, подключения с ошибкой проверки могут превратить сервер в ретранслятор. Строгий контроль автоматически разрешает SNI панели, сайтов, маршрутов TCP/Xray и REALITY, а остальные отклоняет.${PLAIN}")"
        if confirm_default_no "$(localized_text "是否启用严格 SNI 门禁？(y/N): " "Enable the strict SNI gate? (y/N): " "Включить строгий контроль SNI? (y/N): ")"; then
            STRICT_SNI_GATE="true"
        fi
    fi
    NGINX_LISTEN_ADDR=$(ask_with_default "$(localized_text "Nginx 公网监听地址" "Nginx public listening address" "Nginx адрес прослушивания публичной сети")" "0.0.0.0")
    NGINX_LISTEN_PORT=$(ask_with_default "$(localized_text "Nginx 公网监听端口" "Nginx public listening port" "Порт прослушивания публичной сети Nginx")" "443")

    local advanced_mode
    read_trimmed advanced_mode "$(localized_text "是否进入高级模式并允许修改本地服务监听地址？(Y/n，默认 y): " "Do you want to enter advanced mode and allow modification of the local service listening address? (Y/n, default y):" "Хотите войти в расширенный режим и разрешить изменение адреса прослушивания локальной службы? (Да/нет, по умолчанию y):")"
    if is_yes "$advanced_mode"; then
        CADDY_LISTEN_ADDR=$(ask_with_default "$(localized_text "$(web_proxy_engine_label "$WEB_PROXY_ENGINE")监听地址" "$(web_proxy_engine_label \"$WEB_PROXY_ENGINE\") listening address" "Адрес прослушивания $(web_proxy_engine_label \"$WEB_PROXY_ENGINE\")")" "127.0.0.1")
        XRAY_LISTEN_ADDR=$(ask_with_default "$(localized_text "Xray REALITY 本地监听地址" "Xray REALITY local listening address" "Xray REALITY локальный адрес прослушивания")" "127.0.0.1")
        PANEL_LISTEN_ADDR=$(ask_with_default "$(localized_text "3x-ui 面板监听地址" "3x-ui panel listening address" "Адрес прослушивания панели 3x-ui")" "$default_panel_addr")
        SUB_LISTEN_ADDR=$(ask_with_default "$(localized_text "3x-ui 订阅服务监听地址" "3x-ui Subscription service listening address" "3x-ui Адрес прослушивания службы подписки")" "$default_sub_addr")
    else
        CADDY_LISTEN_ADDR="127.0.0.1"
        XRAY_LISTEN_ADDR="127.0.0.1"
        PANEL_LISTEN_ADDR="$default_panel_addr"
        SUB_LISTEN_ADDR="$default_sub_addr"
        echo -e "$(localized_text "${GREEN}普通模式：Web 反代引擎/Xray/3x-ui/订阅/网站后端均使用 127.0.0.1。${PLAIN}" "${GREEN}Normal mode: Web reverse proxy engine/Xray/3x-ui/subscription/website backend all use 127.0.0.1.${PLAIN}" "${GREEN}Обычный режим : механизм веб-прокси/Xray/3x-ui/подписка/бэкэнд веб-сайта используют 127.0.0.1.${PLAIN}")"
    fi

    CADDY_LISTEN_PORT=$(ask_with_default "$(localized_text "$(web_proxy_engine_label "$WEB_PROXY_ENGINE")监听端口" "$(web_proxy_engine_label \"$WEB_PROXY_ENGINE\") listening port" "Порт прослушивания $(web_proxy_engine_label \"$WEB_PROXY_ENGINE\")")" "8443")
    XRAY_LISTEN_PORT=$(ask_with_default "$(localized_text "Xray REALITY 本地监听端口" "Xray REALITY local listening port" "Xray REALITY локальный порт прослушивания")" "1443")
    PANEL_LISTEN_PORT=$(ask_with_default "$(localized_text "3x-ui 面板端口" "3x-ui panel port" "Порт панели 3x-ui")" "$default_panel_port")
    PANEL_WEB_PATH=$(normalize_path_prefix "$(ask_with_default "$(localized_text "3x-ui 面板公网路径 / webBasePath（必须和面板 url 根路径一致）" "3x-ui public panel path / webBasePath (must match the panel URL root path)" "Публичный путь панели 3x-ui / webBasePath (должен совпадать с корневым URL панели)")" "$default_panel_path")")
    SUB_LISTEN_PORT=$(ask_with_default "$(localized_text "3x-ui 订阅服务端口（可自定义）" "3x-ui Subscription service port (customizable)" "3x-ui Порт службы подписки (настраиваемый)")" "$default_sub_port")
    SUB_URI_PATH=$(normalize_path_prefix "$(ask_with_default "$(localized_text "3x-ui 普通订阅路径前缀（不带端口和客户端 Subscription，建议写 /sub/）" "3x-ui standard subscription path prefix (without port or client identifier; recommended: /sub/)" "Префикс обычной подписки 3x-ui (без порта и идентификатора клиента; рекомендуется /sub/)")" "$default_sub_path")")
    CLASH_URI_PATH=$(normalize_path_prefix "$(ask_with_default "$(localized_text "3x-ui Clash/Mihomo 订阅路径前缀（不带客户端 Subscription，建议写 /clash/）" "3x-ui Clash/Mihomo subscription path prefix (without client identifier; recommended: /clash/)" "Префикс подписки Clash/Mihomo в 3x-ui (без идентификатора клиента; рекомендуется /clash/)")" "$default_clash_path")")
    local panel_whitelist_enabled panel_whitelist_input panel_whitelist_ranges current_client_ip
    local -a panel_whitelist_array=()
    read_trimmed panel_whitelist_enabled "$(localized_text "是否为面板域名启用 IP 白名单？(y/N，默认 N): " "Enable an IP allowlist for the panel domain? (y/N, default N): " "Включить список разрешённых IP-адресов для домена панели? (y/N, по умолчанию N): ")"
    if is_yes "$panel_whitelist_enabled"; then
        if ! web_proxy_engine_supports_web_whitelist "${ENTRY_MODE:-nginx-stream}" "$WEB_PROXY_ENGINE"; then
            echo -e "$(localized_text "${RED}❌ xray-fallback 模式不支持 Web 白名单。${PLAIN}" "${RED}❌ xray-fallback mode does not support web whitelisting.${PLAIN}" "${RED}❌ Резервный режим xray не поддерживает белый список веб-сайтов.${PLAIN}")"
            echo -e "$(localized_text "${YELLOW}请改用 Nginx Stream/TCP Peek 入口模式。${PLAIN}" "${YELLOW}For , please use Nginx Stream/TCP Peek entry mode instead.${PLAIN}" "${YELLOW}Для вместо этого используйте режим ввода Nginx Stream/TCP Peek.${PLAIN}")"
            return 1
        fi
        current_client_ip=$(detect_ssh_client_ip)
        [[ -n "$current_client_ip" ]] && echo -e "$(localized_text "${YELLOW}当前 SSH 来源 IP 可能是：${current_client_ip}，请确认已加入白名单。${PLAIN}" "${YELLOW}The current source IP of SSH may be: ${current_client_ip}. Please confirm that it has been added to the whitelist.${PLAIN}" "${YELLOW}Текущий исходный IP-адрес SSH может быть: ${current_client_ip}. Пожалуйста, подтвердите, что он был добавлен в белый список.${PLAIN}")"
        read_trimmed panel_whitelist_input "$(localized_text "请输入允许访问面板域名的 IP/CIDR（多个用空格或英文逗号分隔）: " "Please enter the IP/CIDR of the domain that is allowed to access the panel (separate multiple by spaces or commas):" "Пожалуйста, введите IP/CIDR доменного имени, которому разрешен доступ к панели (разделяйте кратные пробелами или запятыми):")"
        normalize_ip_whitelist_input "$panel_whitelist_input" panel_whitelist_array || return 1
        append_vps_public_ips_to_whitelist panel_whitelist_array
        panel_whitelist_ranges=$(join_array_by_space "${panel_whitelist_array[@]}")
    fi
    if [[ ${#SITE_DOMAINS[@]} -gt 0 ]]; then
        local i default_site_port
        default_site_port=3000
        for i in "${!SITE_DOMAINS[@]}"; do
            if [[ -z "${SITE_DOMAINS[$i]}" ]]; then
                continue
            fi
            if is_yes "$advanced_mode"; then
                SITE_BACKEND_ADDRS[$i]=$(ask_with_default "$(localized_text "网站 ${SITE_DOMAINS[$i]} 的后端地址" "The backend address of the website ${SITE_DOMAINS[$i]}" "Внутренний адрес сайта ${SITE_DOMAINS[$i]}")" "127.0.0.1")
            else
                SITE_BACKEND_ADDRS[$i]="127.0.0.1"
            fi
            SITE_BACKEND_PORTS[$i]=$(ask_with_default "$(localized_text "网站 ${SITE_DOMAINS[$i]} 的后端端口" "Backend port of website ${SITE_DOMAINS[$i]}" "Внутренний порт веб-сайта ${SITE_DOMAINS[$i]}")" "$default_site_port")
            default_site_port=$((default_site_port + 1))
        done
    fi

    echo -e "$(localized_text "${YELLOW}443端口复用需要 3x-ui 面板/订阅后端使用 HTTP，由 $(web_proxy_engine_label "$WEB_PROXY_ENGINE") 统一托管公网证书。${PLAIN}" "${YELLOW}Port 443 Reuse requires the 3x-ui panel/subscription backend to use HTTP, which will centrally manage the public certificate.${PLAIN}" "${YELLOW}Для повторного использования порта 443 требуется, чтобы бэкенд панели/подписки 3x-ui использовала HTTP, который будет централизованно управлять сертификатом публичной сети.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}本向导会让 $(web_proxy_engine_label "$WEB_PROXY_ENGINE") 通过 HTTP 连接 ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT} 和 ${SUB_LISTEN_ADDR}:${SUB_LISTEN_PORT}。${PLAIN}" "${YELLOW}This wizard will allow $(web_proxy_engine_label \"$WEB_PROXY_ENGINE\") to connect ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT} and ${SUB_LISTEN_ADDR}:${SUB_LISTEN_PORT} through HTTP.${PLAIN}" "${YELLOW}Этот мастер позволит $(web_proxy_engine_label \"$WEB_PROXY_ENGINE\") соединить ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT} и ${SUB_LISTEN_ADDR}:${SUB_LISTEN_PORT} через HTTP.${PLAIN}")"
    echo -e "$(localized_text "${CYAN}证书处理分两种情况：${PLAIN}" "${CYAN}Certificate processing is divided into two situations:${PLAIN}" "${CYAN}Обработка сертификата делится на две ситуации:.${PLAIN}")"
    echo -e "$(localized_text "  3x-ui 3.x 新安装：在官方安装器选第 4 项 Skip SSL，再选 y 仅绑定 127.0.0.1；本步骤只做兜底检查。" "  New 3x-ui 3.x installation: choose option 4, Skip SSL, then enter y to bind only to 127.0.0.1. This step is only a fallback check." "  Новая установка 3x-ui 3.x: выберите пункт 4 Skip SSL, затем введите y для привязки только к 127.0.0.1. Этот шаг выполняет только проверку.")"
    echo -e "$(localized_text "  3x-ui 2.x、升级旧配置、或曾经启用过 3x-ui SSL：继续按旧流程清空面板/订阅证书路径。" "3x-ui 2.x, upgrading old configuration, or 3x-ui SSL has been enabled: Continue to clear the panel/subscription certificate path according to the old process." "3x-ui 2.x, обновление старой конфигурации или 3x-ui SSL включен: продолжайте очищать путь сертификата панели/подписки в соответствии со старым процессом.")"
    if confirm_danger \
        "$(localized_text "清空 3x-ui 旧证书路径" "Clear legacy 3x-ui certificate paths" "Очистить старые пути сертификатов 3x-ui")" \
        "$(localized_text "清空 3x-ui 2.x 或旧配置中的面板和订阅证书路径，使本地反代改用 HTTP。" "Clear panel and subscription certificate paths in 3x-ui 2.x or legacy configuration so the local proxy can use HTTP." "Очистить пути сертификатов панели и подписки в 3x-ui 2.x или старой конфигурации, чтобы локальный прокси использовал HTTP.")" \
        "$(localized_text "可在 3x-ui 官方菜单中重新填写原证书路径，或恢复操作前备份。" "Restore the original certificate paths from the official 3x-ui menu or a pre-operation backup." "Верните исходные пути через официальное меню 3x-ui или восстановите резервную копию.")"; then
        if ! clear_xui_cert_settings_for_single_443; then
            confirm_default_no "$(localized_text "是否已经手动清空面板和订阅证书路径？(y/N): " "Have you already cleared the panel and subscription certificate paths manually? (y/N): " "Вы уже вручную очистили пути сертификатов панели и подписки? (y/N): ")" || { echo -e "$(localized_text "${YELLOW}请先在 3x-ui 中清空证书路径，保存并重启面板。${PLAIN}" "${YELLOW}Clear the certificate paths in 3x-ui, save, and restart the panel first.${PLAIN}" "${YELLOW}Сначала очистите пути сертификатов в 3x-ui, сохраните изменения и перезапустите панель.${PLAIN}")"; return 1; }
        fi
    else
        confirm_default_no "$(localized_text "是否已经手动清空面板和订阅证书路径？(y/N): " "Have you already cleared the panel and subscription certificate paths manually? (y/N): " "Вы уже вручную очистили пути сертификатов панели и подписки? (y/N): ")" || { echo -e "$(localized_text "${YELLOW}请先在 3x-ui 中清空证书路径，保存并重启面板。${PLAIN}" "${YELLOW}Clear the certificate paths in 3x-ui, save, and restart the panel first.${PLAIN}" "${YELLOW}Сначала очистите пути сертификатов в 3x-ui, сохраните изменения и перезапустите панель.${PLAIN}")"; return 1; }
    fi

    echo -e "$(localized_text "${CYAN}请输入 Cloudflare API Token（需 Zone.DNS.Edit + Zone.Zone.Read）${PLAIN}" "${CYAN}Please enter Cloudflare API Token (requires Zone.DNS.Edit + Zone.Zone.Read)${PLAIN}" "${CYAN}Введите токен API Cloudflare (требуется Zone.DNS.Edit + Zone.Zone.Read)${PLAIN}")"
    read_secret_trimmed CF_TOKEN "CF Token: "

    PANEL_DOMAIN=$(normalize_domain_input "$panel_domain_input")
    REALITY_SNI=$(normalize_domain_input "$reality_sni_input")
    local site_idx
    for site_idx in "${!SITE_DOMAINS[@]}"; do
        SITE_DOMAINS[$site_idx]=$(normalize_domain_input "${SITE_DOMAINS[$site_idx]}")
        SITE_BACKEND_ADDRS[$site_idx]=$(normalize_backend_addr_input "${SITE_BACKEND_ADDRS[$site_idx]:-127.0.0.1}")
    done

    if ! is_valid_domain "$PANEL_DOMAIN"; then print_domain_validation_error "$(localized_text "面板域名" "Panel domain" "Доменное имя панели")" "$panel_domain_input" "$PANEL_DOMAIN"; return 1; fi
    if ! is_valid_domain "$REALITY_SNI"; then print_domain_validation_error "REALITY SNI" "$reality_sni_input" "$REALITY_SNI"; return 1; fi
    check_domain_dns_sanity "$PANEL_DOMAIN" "$(localized_text "面板域名" "Panel domain" "Доменное имя панели")" "prompt" || return 1
    check_domain_dns_sanity "$REALITY_SNI" "REALITY SNI" "prompt" || return 1
    local site_domain seen_domains
    seen_domains=" ${PANEL_DOMAIN} ${REALITY_SNI} "
    for site_idx in "${!SITE_DOMAINS[@]}"; do
        site_domain="${SITE_DOMAINS[$site_idx]}"
        [[ -z "$site_domain" ]] && continue
        if ! is_valid_domain "$site_domain"; then print_domain_validation_error "$(localized_text "网站/反代域名" "Website/reverse domain" "Веб-сайт/обратное доменное имя")" "${site_domain_raw_inputs[$site_idx]:-$site_domain}" "$site_domain"; return 1; fi
        if [[ "$site_domain" == "$PANEL_DOMAIN" || "$site_domain" == "$REALITY_SNI" || "$seen_domains" == *" ${site_domain} "* ]]; then
            echo -e "$(localized_text "${RED}❌ 面板域名、网站/反代域名、REALITY SNI 不能相同：${site_domain}${PLAIN}" "${RED}❌ Panel domain, website/reverse domain, REALITY SNI cannot be the same: ${site_domain}${PLAIN}" "${RED}❌ Доменное имя панели, веб-сайт/обратное доменное имя, REALITY SNI не могут быть одинаковыми: ${site_domain}${PLAIN}")"
            return 1
        fi
        check_domain_dns_sanity "$site_domain" "$(localized_text "网站/反代域名" "Website/reverse domain" "Веб-сайт/обратное доменное имя")" "prompt" || return 1
        seen_domains+=" ${site_domain} "
    done

    local p a
    for p in "$NGINX_LISTEN_PORT" "$CADDY_LISTEN_PORT" "$XRAY_LISTEN_PORT" "$PANEL_LISTEN_PORT" "$SUB_LISTEN_PORT" "${SITE_BACKEND_PORTS[@]}"; do
        is_valid_port "$p" || { echo -e "$(localized_text "${RED}❌ 端口无效：${p}${PLAIN}" "${RED}❌ Invalid port: ${p}${PLAIN}" "${RED}❌ Неверный порт: ${p}.${PLAIN}")"; return 1; }
    done
    for a in "$NGINX_LISTEN_ADDR" "$CADDY_LISTEN_ADDR" "$XRAY_LISTEN_ADDR" "$PANEL_LISTEN_ADDR" "$SUB_LISTEN_ADDR"; do
        is_valid_listen_addr "$a" || { echo -e "$(localized_text "${RED}❌ 监听地址无效：${a}${PLAIN}" "${RED}❌ The listening address is invalid: ${a}${PLAIN}" "${RED}❌ Неверный адрес прослушивания: ${a}.${PLAIN}")"; return 1; }
    done
    for a in "${SITE_BACKEND_ADDRS[@]}"; do
        is_valid_backend_addr "$a" || { echo -e "$(localized_text "${RED}❌ 后端地址无效：${a}${PLAIN}" "${RED}❌ Invalid backend address: ${a}${PLAIN}" "${RED}❌ Неверный внутренний адрес: ${a}.${PLAIN}")"; return 1; }
    done
    is_valid_path_prefix "$PANEL_WEB_PATH" || { echo -e "$(localized_text "${RED}❌ 面板公网路径无效：${PANEL_WEB_PATH}${PLAIN}" "${RED}❌ The public path of the panel is invalid: ${PANEL_WEB_PATH}${PLAIN}" "${RED}❌ Неверный путь панели в публичной сети: ${PANEL_WEB_PATH}.${PLAIN}")"; return 1; }
    is_valid_path_prefix "$SUB_URI_PATH" || { echo -e "$(localized_text "${RED}❌ 普通订阅路径前缀无效：${SUB_URI_PATH}${PLAIN}" "${RED}❌ The common subscription path prefix is invalid: ${SUB_URI_PATH}${PLAIN}" "${RED}❌ Неверный префикс общего пути подписки: ${SUB_URI_PATH}.${PLAIN}")"; return 1; }
    is_valid_path_prefix "$CLASH_URI_PATH" || { echo -e "$(localized_text "${RED}❌ Clash/Mihomo 订阅路径前缀无效：${CLASH_URI_PATH}${PLAIN}" "${RED}❌ Clash/Mihomo Invalid subscription path prefix: ${CLASH_URI_PATH}${PLAIN}" "${RED}❌ Clash/Mihomo Неверный префикс пути подписки: ${CLASH_URI_PATH}${PLAIN}")"; return 1; }
    if [[ "$PANEL_WEB_PATH" == "$SUB_URI_PATH" || "$PANEL_WEB_PATH" == "$CLASH_URI_PATH" || "$SUB_URI_PATH" == "$CLASH_URI_PATH" ]]; then
        echo -e "$(localized_text "${RED}❌ 面板路径、普通订阅路径、Clash/Mihomo 路径不能相同。${PLAIN}" "${RED}❌ The panel path, normal subscription path, and Clash/Mihomo path cannot be the same.${PLAIN}" "${RED}❌ Путь к панели, обычный путь подписки и путь Clash/Mihomo не могут совпадать.${PLAIN}")"
        return 1
    fi
    SITE_DOMAIN="${SITE_DOMAINS[0]:-}"
    SITE_BACKEND_ADDR="${SITE_BACKEND_ADDRS[0]:-127.0.0.1}"
    SITE_BACKEND_PORT="${SITE_BACKEND_PORTS[0]:-3000}"
    if [[ -n "${panel_whitelist_ranges:-}" ]]; then
        set_sni_ip_whitelist_for_domain "$PANEL_DOMAIN" "$panel_whitelist_ranges"
    fi
    [[ "$NGINX_LISTEN_PORT" != "443" ]] && echo -e "$(localized_text "${YELLOW}⚠️  Nginx 公网端口不是 443，不推荐。${PLAIN}" "${YELLOW}⚠️ The public port of Nginx is not 443 and is not recommended.${PLAIN}" "${YELLOW}⚠️ Порт публичной сети Nginx не 443 и не рекомендуется.${PLAIN}")"

    warn_if_public_bind "$(web_proxy_engine_label "$WEB_PROXY_ENGINE")" "$CADDY_LISTEN_ADDR" "$CADDY_LISTEN_PORT" || return 1
    warn_if_public_bind "Xray REALITY" "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT" || return 1
    warn_if_public_bind "$(localized_text "3x-ui 面板" "3x-ui panel" "Панель 3x-ui")" "$PANEL_LISTEN_ADDR" "$PANEL_LISTEN_PORT" || return 1
    warn_if_public_bind "$(localized_text "3x-ui 订阅服务" "3x-ui Subscription Service" "Служба подписки 3x-ui")" "$SUB_LISTEN_ADDR" "$SUB_LISTEN_PORT" || return 1
    for site_idx in "${!SITE_DOMAINS[@]}"; do
        [[ -n "${SITE_DOMAINS[$site_idx]}" ]] || continue
        confirm_backend_target_or_continue "$(localized_text "网站/反代后端 ${SITE_DOMAINS[$site_idx]}" "Website/reverse proxy backend ${SITE_DOMAINS[$site_idx]}" "Сайт/бэкенд обратного прокси ${SITE_DOMAINS[$site_idx]}")" "${SITE_BACKEND_ADDRS[$site_idx]}" "${SITE_BACKEND_PORTS[$site_idx]}" || return 1
    done

    if [[ -z "$CF_TOKEN" || ${#CF_TOKEN} -lt 20 ]]; then echo -e "$(localized_text "${RED}❌ Cloudflare Token 长度异常。${PLAIN}" "${RED}❌ Cloudflare Token length is abnormal.${PLAIN}" "${RED}❌ Cloudflare Неверная длина токена.${PLAIN}")"; return 1; fi
    echo -e "$(localized_text "${CYAN}▶ 正在在线校验 Cloudflare Token...${PLAIN}" "${CYAN}▶ Verifying online Cloudflare Token...${PLAIN}" "${CYAN}▶ Проверка токена Cloudflare онлайн...${PLAIN}")"
    verify_cf_token_online "$CF_TOKEN"
    local verify_rc=$?
    if [[ "$verify_rc" -eq 0 ]]; then
        echo -e "$(localized_text "${GREEN}✅ Cloudflare Token 校验通过。${PLAIN}" "${GREEN}✅ Cloudflare Token verification passed.${PLAIN}" "${GREEN}✅ Cloudflare Проверка токена пройдена.${PLAIN}")"
    elif [[ "$verify_rc" -eq 2 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未安装 curl，跳过在线校验。${PLAIN}" "${YELLOW}⚠️ curl is not installed, skip online verification.${PLAIN}" "${YELLOW}⚠️ curl не установлен, пропустите онлайн-проверку.${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ Cloudflare Token 校验失败。${PLAIN}" "${RED}❌ Cloudflare Token verification failed.${PLAIN}" "${RED}❌ Cloudflare Проверка токена не удалась.${PLAIN}")"
        return 1
    fi
}

install_caddy_if_needed() {
    command -v caddy >/dev/null 2>&1 && return 0
    echo -e "$(localized_text "${CYAN}▶ 未检测到 Caddy，正在安装...${PLAIN}" "${CYAN}▶ Caddy not detected, installing...${PLAIN}" "${CYAN}▶ Caddy не обнаружен, устанавливается...${PLAIN}")"
    if is_debian; then
        local key_tmp repo_tmp
        install_pkg debian-keyring debian-archive-keyring apt-transport-https curl gpg || return 1
        command -v curl >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ 缺少 curl，无法添加 Caddy 源。${PLAIN}" "${RED}❌ curl is missing and the Caddy source cannot be added.${PLAIN}" "${RED}❌ curl отсутствует, и источник Caddy не может быть добавлен.${PLAIN}")"; return 1; }
        command -v gpg >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ 缺少 gpg，无法校验 Caddy 源。${PLAIN}" "${RED}❌ Missing gpg, unable to verify Caddy source.${PLAIN}" "${RED}❌ Отсутствует gpg, невозможно проверить источник Caddy.${PLAIN}")"; return 1; }
        key_tmp=$(mktemp /tmp/caddy-key.XXXXXX) || return 1
        repo_tmp=$(mktemp /tmp/caddy-repo.XXXXXX) || { rm -f "$key_tmp"; return 1; }
        if ! curl -fsSL --connect-timeout 10 --max-time 60 --retry 2 --retry-delay 1 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' -o "$key_tmp"; then
            rm -f "$key_tmp"
            rm -f "$repo_tmp"
            echo -e "$(localized_text "${RED}❌ Caddy GPG key 下载失败。${PLAIN}" "${RED}❌ Caddy GPG key download failed.${PLAIN}" "${RED}❌ Caddy Загрузка ключа GPG не удалась.${PLAIN}")"
            return 1
        fi
        if ! gpg --batch --yes --dearmor -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg "$key_tmp"; then
            rm -f "$key_tmp"
            rm -f "$repo_tmp"
            echo -e "$(localized_text "${RED}❌ Caddy GPG key 写入失败。${PLAIN}" "${RED}❌ Caddy GPG key writing failed.${PLAIN}" "${RED}❌ Caddy Не удалось записать ключ GPG.${PLAIN}")"
            return 1
        fi
        if ! curl -fsSL --connect-timeout 10 --max-time 60 --retry 2 --retry-delay 1 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' -o "$repo_tmp"; then
            rm -f "$key_tmp"
            rm -f "$repo_tmp"
            echo -e "$(localized_text "${RED}❌ Caddy APT 源配置下载失败。${PLAIN}" "${RED}❌ Caddy APT source configuration download failed.${PLAIN}" "${RED}❌ Caddy Не удалось загрузить исходную конфигурацию APT.${PLAIN}")"
            return 1
        fi
        if ! mv "$repo_tmp" /etc/apt/sources.list.d/caddy-stable.list; then
            rm -f "$key_tmp"
            rm -f "$repo_tmp"
            echo -e "$(localized_text "${RED}❌ Caddy APT 源配置写入失败。${PLAIN}" "${RED}❌ Caddy APT source configuration failed to write.${PLAIN}" "${RED}❌ Caddy Не удалось записать исходную конфигурацию APT.${PLAIN}")"
            return 1
        fi
        rm -f "$key_tmp"
        install_pkg caddy || return 1
    elif is_redhat; then
        install_pkg yum-utils || true
        if command -v yum-config-manager >/dev/null 2>&1; then
            yum-config-manager --add-repo https://openrepo.io/repo/caddy/caddy.repo >/dev/null 2>&1 || return 1
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 yum-config-manager，将尝试直接从系统源安装 Caddy。${PLAIN}" "${YELLOW}⚠️ yum-config-manager not detected, will try to install Caddy directly from system sources.${PLAIN}" "${YELLOW}⚠️ yum-config-manager не обнаружен, попытается установить Caddy непосредственно из системных источников.${PLAIN}")"
        fi
        install_pkg caddy || return 1
    else
        echo -e "$(localized_text "${RED}❌ 暂不支持当前系统自动安装 Caddy。${PLAIN}" "${RED}❌ The current system does not support automatic installation of Caddy.${PLAIN}" "${RED}❌ Текущая система не поддерживает автоматическую установку Caddy.${PLAIN}")"
        return 1
    fi
    command -v caddy >/dev/null 2>&1
}

ensure_caddy_module_layout() {
    mkdir -p /etc/caddy/conf.d || return 1
    if [[ ! -f /etc/caddy/Caddyfile ]]; then
        cat <<'EOF' > /etc/caddy/Caddyfile
import conf.d/*
EOF
        return 0
    fi
    if ! grep -q "import conf.d/\*" /etc/caddy/Caddyfile; then
        cp -p /etc/caddy/Caddyfile "/etc/caddy/Caddyfile.bak_$(date +%s)" 2>/dev/null || true
        printf '\nimport conf.d/*\n' >> /etc/caddy/Caddyfile
    fi
}

install_nginx_stream_stack() {
    echo -e "$(localized_text "${CYAN}▶ 正在检查 Nginx stream 组件...${PLAIN}" "${CYAN}▶ Checking Nginx stream assembly...${PLAIN}" "${CYAN}▶ Проверка сборки Nginx stream...${PLAIN}")"
    local need_install=0
    local nginx_build
    if ! command -v nginx >/dev/null 2>&1; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 Nginx，正在安装基础组件...${PLAIN}" "${YELLOW}⚠️ Nginx not detected, installing basic components...${PLAIN}" "${YELLOW}⚠️ Nginx не обнаружен, установка основных компонентов...${PLAIN}")"
        need_install=1
    else
        nginx_build=$(nginx -V 2>&1 || true)
    fi

    if [[ "$need_install" -eq 0 ]]; then
        if [[ "$nginx_build" == *"--with-stream=dynamic"* ]]; then
            if grep -Rqs 'load_module .*ngx_stream_module\.so' /etc/nginx/nginx.conf /etc/nginx/modules-enabled 2>/dev/null; then
                echo -e "$(localized_text "${GREEN}✅ 已检测到 Nginx stream 动态模块加载配置，跳过安装步骤。${PLAIN}" "${GREEN}✅ The Nginx stream dynamic module loading configuration has been detected, skipping the installation step.${PLAIN}" "${GREEN}✅ Обнаружена конфигурация динамической загрузки модуля Nginx stream, этап установки пропущен.${PLAIN}")"
            else
                echo -e "$(localized_text "${YELLOW}⚠️ Nginx 支持动态 stream 模块，但未确认模块已加载，正在尝试补齐模块...${PLAIN}" "${YELLOW}⚠️ Nginx supports dynamic stream module, but the module has not been confirmed to be loaded. Trying to complete the module...${PLAIN}" "${YELLOW}⚠️ Nginx поддерживает модуль динамического потока, но загрузка модуля не подтверждена. Пытаюсь завершить модуль...${PLAIN}")"
                need_install=1
            fi
        elif [[ "$nginx_build" == *"--with-stream"* || "$nginx_build" == *"--with-stream_ssl_preread_module"* ]]; then
            echo -e "$(localized_text "${GREEN}✅ 已检测到 Nginx stream 静态支持，跳过安装步骤。${PLAIN}" "${GREEN}✅ Static support for Nginx stream has been detected, skipping the installation step.${PLAIN}" "${GREEN}✅ Обнаружена статическая поддержка Nginx stream, пропуская этап установки.${PLAIN}")"
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 未确认 Nginx stream 支持，正在尝试补齐模块...${PLAIN}" "${YELLOW}⚠️ Unconfirmed Nginx stream support, trying to complete the module...${PLAIN}" "${YELLOW}⚠️ Неподтвержденная поддержка Nginx stream, пытаюсь завершить модуль...${PLAIN}")"
            need_install=1
        fi
    fi

    if [[ "$need_install" -eq 1 ]]; then
        if is_debian; then
            install_pkg nginx libnginx-mod-stream
        elif is_redhat; then
            install_pkg nginx
            install_pkg nginx-mod-stream || echo -e "$(localized_text "${YELLOW}⚠️ nginx-mod-stream 安装失败或仓库未提供，将继续检测 Nginx stream 支持。${PLAIN}" "${YELLOW}⚠️ If the installation of nginx-mod-stream fails or the warehouse does not provide it, Nginx stream support will continue to be detected.${PLAIN}" "${YELLOW}⚠️ Если установка nginx-mod-stream не удалась или склад не предоставляет его, поддержка Nginx stream продолжит обнаруживаться.${PLAIN}")"
        fi
    fi
    command -v nginx >/dev/null 2>&1 || { echo -e "$(localized_text "${RED}❌ Nginx 安装失败。${PLAIN}" "${RED}❌ Nginx installation failed.${PLAIN}" "${RED}❌ Установка Nginx не удалась.${PLAIN}")"; return 1; }
    mkdir -p /etc/nginx/stream.d
    if ! grep -Eq '^[[:space:]]*stream[[:space:]]*\{' /etc/nginx/nginx.conf 2>/dev/null; then
        cp -f /etc/nginx/nginx.conf "/etc/nginx/nginx.conf.bak_$(date +%s)" 2>/dev/null || true
        cat <<'EOF' >> /etc/nginx/nginx.conf

stream {
    include /etc/nginx/stream.d/*.conf;
}
EOF
    elif ! grep -q '/etc/nginx/stream.d/\*.conf' /etc/nginx/nginx.conf 2>/dev/null; then
        cp -f /etc/nginx/nginx.conf "/etc/nginx/nginx.conf.bak_$(date +%s)" 2>/dev/null || true
        sed -i '/^[[:space:]]*stream[[:space:]]*{/a\    include /etc/nginx/stream.d/*.conf;' /etc/nginx/nginx.conf
    fi
}

harden_nginx_public_errors() {
    local nginx_conf="/etc/nginx/nginx.conf"
    local drop_conf="/etc/nginx/conf.d/00-vps-default-drop.conf"
    local quarantine_dir="/etc/vps-optimize/nginx-default-sites-disabled_$(date +%s)"
    local moved=0
    local default_file

    command -v nginx >/dev/null 2>&1 || return 0
    mkdir -p /etc/nginx/conf.d /etc/vps-optimize

    if [[ -f "$nginx_conf" ]]; then
        if grep -Eq '^[#[:space:]]*server_tokens[[:space:]]+' "$nginx_conf"; then
            sed -i 's/^[#[:space:]]*server_tokens[[:space:]].*;/    server_tokens off;/' "$nginx_conf"
        elif grep -Eq '^[[:space:]]*http[[:space:]]*\{' "$nginx_conf"; then
            sed -i '/^[[:space:]]*http[[:space:]]*{/a\    server_tokens off;' "$nginx_conf"
        fi
    fi

    for default_file in \
        /etc/nginx/sites-enabled/default \
        /etc/nginx/sites-available/default \
        /etc/nginx/conf.d/default.conf; do
        if [[ -e "$default_file" ]]; then
            mkdir -p "$quarantine_dir"
            mv "$default_file" "$quarantine_dir/" >/dev/null 2>&1 && ((moved++))
        fi
    done

    cat <<'EOF' > "$drop_conf"
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    return 444;
}
EOF

    if [[ "$moved" -gt 0 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 已隔离 ${moved} 个 Nginx 默认站点配置到：${quarantine_dir}${PLAIN}" "${YELLOW}⚠️ Isolated ${moved} Nginx The default site is configured to: ${quarantine_dir}${PLAIN}" "${YELLOW}⚠️ Изолированный ${moved} Nginx Сайт по умолчанию настроен на: ${quarantine_dir}${PLAIN}")"
    fi
    echo -e "$(localized_text "${GREEN}✅ 已关闭 Nginx 版本号显示，并写入 80 端口默认丢弃规则。${PLAIN}" "${GREEN}✅ The Nginx version number display has been turned off, and the default discard rule of port 80 has been written.${PLAIN}" "${GREEN}. Отображение номера версии Nginx отключено и записано правило отбрасывания по умолчанию для порта 80.${PLAIN}")"
}

write_nginx_sni_stream_config() {
    local conf_file="${1:-/etc/nginx/stream.d/vps_sni_${NGINX_LISTEN_PORT}.conf}"
    local validate="${2:-yes}"
    local listen_directives
    local web_backend
    local xray_backend
    local guarded_backend_var="\$vps_sni_backend"
    local default_backend_name="xray_backend"
    local reject_backend_required="false"
    local -a whitelist_block_vars=()
    listen_directives=$(nginx_stream_listen_directives "$NGINX_LISTEN_ADDR" "$NGINX_LISTEN_PORT")
    web_backend=$(web_proxy_backend)
    xray_backend=$(format_hostport "$XRAY_LISTEN_ADDR" "$XRAY_LISTEN_PORT")
    if strict_sni_gate_enabled; then
        default_backend_name="vps_ip_reject_backend"
        reject_backend_required="true"
    fi

    : > "$conf_file"
    if [[ ${#SNI_IP_WHITELIST_DOMAINS[@]} -gt 0 ]]; then
        local i domain ranges suffix allow_var block_var range
        for i in "${!SNI_IP_WHITELIST_DOMAINS[@]}"; do
            domain="${SNI_IP_WHITELIST_DOMAINS[$i]}"
            ranges="${SNI_IP_WHITELIST_RANGES[$i]}"
            [[ -n "$domain" && -n "$ranges" ]] || continue
            is_sni_stack_web_domain "$domain" || continue
            suffix=$(nginx_var_suffix_for_domain "$domain")
            allow_var="vps_ip_allow_${suffix}"
            block_var="vps_ip_block_${suffix}"
            whitelist_block_vars+=("\$${block_var}")
            cat <<EOF >> "$conf_file"
geo \$${allow_var} {
    default 0;
EOF
            for range in $ranges; do
                echo "    ${range} 1;" >> "$conf_file"
            done
            cat <<EOF >> "$conf_file"
}

map "\$ssl_preread_server_name:\$${allow_var}" \$${block_var} {
    default 0;
    "${domain}:0" 1;
}

EOF
        done
    fi

    cat <<EOF >> "$conf_file"
map \$ssl_preread_server_name \$vps_sni_backend {
    ${PANEL_DOMAIN} web_proxy_backend;
EOF
    if [[ ${#SITE_DOMAINS[@]} -gt 0 ]]; then
        local site_domain
        for site_domain in "${SITE_DOMAINS[@]}"; do
            [[ -n "$site_domain" ]] && echo "    ${site_domain} web_proxy_backend;" >> "$conf_file"
        done
    fi
    if [[ ${#TCP_ROUTE_SNIS[@]} -gt 0 ]]; then
        local tcp_i tcp_sni
        for tcp_i in "${!TCP_ROUTE_SNIS[@]}"; do
            tcp_sni="${TCP_ROUTE_SNIS[$tcp_i]}"
            [[ -n "$tcp_sni" ]] && echo "    ${tcp_sni} vps_tcp_route_${tcp_i}_backend;" >> "$conf_file"
        done
    fi
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -gt 0 ]]; then
        local xray_route_i xray_route_sni
        for xray_route_i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            xray_route_sni="${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}"
            [[ -n "$xray_route_sni" ]] && echo "    ${xray_route_sni} vps_xray_route_${xray_route_i}_backend;" >> "$conf_file"
        done
    fi
    cat <<EOF >> "$conf_file"
    ${REALITY_SNI} xray_backend;
    default ${default_backend_name};
}

EOF
    if [[ ${#whitelist_block_vars[@]} -gt 0 ]]; then
        reject_backend_required="true"
        local whitelist_key
        whitelist_key=$(printf '%s' "${whitelist_block_vars[@]}")
        guarded_backend_var="\$vps_sni_guarded_backend"
        cat <<EOF >> "$conf_file"
map "${whitelist_key}" \$vps_sni_ip_blocked {
    default 0;
    ~1 1;
}

map \$vps_sni_ip_blocked \$vps_sni_guarded_backend {
    1 vps_ip_reject_backend;
    default \$vps_sni_backend;
}

EOF
    fi

    cat <<EOF >> "$conf_file"

upstream web_proxy_backend {
    server ${web_backend};
}

upstream xray_backend {
    server ${xray_backend};
}

EOF
    if [[ ${#TCP_ROUTE_SNIS[@]} -gt 0 ]]; then
        local tcp_i tcp_sni tcp_backend
        for tcp_i in "${!TCP_ROUTE_SNIS[@]}"; do
            tcp_sni="${TCP_ROUTE_SNIS[$tcp_i]}"
            [[ -n "$tcp_sni" ]] || continue
            tcp_backend=$(format_hostport "${TCP_ROUTE_ADDRS[$tcp_i]}" "${TCP_ROUTE_PORTS[$tcp_i]}")
            cat <<EOF >> "$conf_file"
upstream vps_tcp_route_${tcp_i}_backend {
    server ${tcp_backend};
}

EOF
        done
    fi
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -gt 0 ]]; then
        local xray_route_i xray_route_sni xray_route_backend
        for xray_route_i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            xray_route_sni="${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}"
            [[ -n "$xray_route_sni" ]] || continue
            xray_route_backend=$(format_hostport "${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}" "${XRAY_SNI_ROUTE_PORTS[$xray_route_i]}")
            cat <<EOF >> "$conf_file"
upstream vps_xray_route_${xray_route_i}_backend {
    server ${xray_route_backend};
}

EOF
        done
    fi
    if [[ "$reject_backend_required" == "true" ]]; then
        cat <<'EOF' >> "$conf_file"
upstream vps_ip_reject_backend {
    server 127.0.0.1:9;
}

EOF
    fi

    cat <<EOF >> "$conf_file"
server {
${listen_directives}
    ssl_preread on;
    proxy_pass ${guarded_backend_var};
    proxy_connect_timeout 10s;
    proxy_timeout 24h;
}
EOF
    if [[ "$validate" == "yes" ]]; then
        nginx -t
    fi
}

ensure_caddy_local_base_config() {
    install_caddy_if_needed || return 1
    mkdir -p /etc/caddy/conf.d /etc/caddy/certs
    cp -f /etc/caddy/Caddyfile "/etc/caddy/Caddyfile.bak_$(date +%s)" 2>/dev/null || true
    cat <<'EOF' > /etc/caddy/Caddyfile
{
    auto_https off
}

import conf.d/*
EOF
}

write_caddy_panel_config() {
    local output_file="${1:-/etc/caddy/conf.d/${PANEL_DOMAIN}.caddy}"
    local panel_backend
    local sub_backend
    local sub_match_paths
    panel_backend=$(format_hostport "$PANEL_LISTEN_ADDR" "$PANEL_LISTEN_PORT")
    sub_backend=$(format_hostport "$SUB_LISTEN_ADDR" "$SUB_LISTEN_PORT")
    SUB_URI_PATH=$(normalize_path_prefix "${SUB_URI_PATH:-/sub/}")
    CLASH_URI_PATH=$(normalize_path_prefix "${CLASH_URI_PATH:-/clash/}")
    sub_match_paths=$(caddy_path_match_tokens "$SUB_URI_PATH" "$CLASH_URI_PATH")
    cat <<EOF > "$output_file"
https://${PANEL_DOMAIN}:${CADDY_LISTEN_PORT} {
    bind ${CADDY_LISTEN_ADDR}
    tls /etc/caddy/certs/${PANEL_DOMAIN}.crt /etc/caddy/certs/${PANEL_DOMAIN}.key
    encode gzip

    @sub path ${sub_match_paths}
    handle @sub {
        reverse_proxy ${sub_backend} {
            header_up Host {http.request.host}
            header_up X-Forwarded-Proto https
            header_up X-Forwarded-Port ${NGINX_LISTEN_PORT}
            header_up X-Real-IP {remote_host}
            header_up Range {http.request.header.Range}
            header_up If-Range {http.request.header.If-Range}
        }
    }

    handle {
        reverse_proxy ${panel_backend} {
            header_up Host {http.request.host}
            header_up X-Forwarded-Proto https
            header_up X-Forwarded-Port ${NGINX_LISTEN_PORT}
            header_up X-Real-IP {remote_host}
            header_up Range {http.request.header.Range}
            header_up If-Range {http.request.header.If-Range}
        }
    }
}
EOF
}

write_caddy_site_config() {
    [[ ${#SITE_DOMAINS[@]} -eq 0 ]] && return 0
    local output_dir="${1:-/etc/caddy/conf.d}"
    local i site_domain site_backend
    for i in "${!SITE_DOMAINS[@]}"; do
        site_domain="${SITE_DOMAINS[$i]}"
        [[ -z "$site_domain" ]] && continue
        site_backend=$(format_hostport "${SITE_BACKEND_ADDRS[$i]}" "${SITE_BACKEND_PORTS[$i]}")
        cat <<EOF > "${output_dir}/${site_domain}.caddy"
https://${site_domain}:${CADDY_LISTEN_PORT} {
    bind ${CADDY_LISTEN_ADDR}
    tls /etc/caddy/certs/${site_domain}.crt /etc/caddy/certs/${site_domain}.key
    encode gzip

    reverse_proxy ${site_backend} {
        header_up Host {http.request.host}
        header_up X-Forwarded-Proto https
        header_up X-Forwarded-Port ${NGINX_LISTEN_PORT}
        header_up X-Real-IP {remote_host}
    }
}
EOF
    done
}

nginx_single_443_web_conf_path() {
    echo "/etc/nginx/conf.d/vps_sni_web_${CADDY_LISTEN_PORT}.conf"
}

nginx_http_listen_directive() {
    local addr="$1"
    local port="$2"
    if [[ "$addr" == *:* && "$addr" != \[*\] ]]; then
        printf '    listen [%s]:%s ssl http2;\n' "$addr" "$port"
    else
        printf '    listen %s:%s ssl http2;\n' "$addr" "$port"
    fi
}

write_nginx_single_443_proxy_headers() {
    cat <<EOF
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Port ${NGINX_LISTEN_PORT};
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$vps_proxy_connection_upgrade;
        proxy_set_header Range \$http_range;
        proxy_set_header If-Range \$http_if_range;
EOF
}

append_nginx_single_443_path_proxy() {
    local output_file="$1"
    local path_prefix="$2"
    local backend="$3"
    local exact_path
    path_prefix=$(normalize_path_prefix "$path_prefix")
    exact_path="${path_prefix%/}"
    cat <<EOF >> "$output_file"

    location = ${exact_path} {
        return 308 ${path_prefix};
    }

    location ^~ ${path_prefix} {
EOF
    write_nginx_single_443_proxy_headers >> "$output_file"
    cat <<EOF >> "$output_file"
        proxy_pass http://${backend};
    }
EOF
}

write_nginx_single_443_web_config() {
    local conf_file="${1:-$(nginx_single_443_web_conf_path)}"
    local panel_backend sub_backend site_backend i site_domain
    panel_backend=$(format_hostport "$PANEL_LISTEN_ADDR" "$PANEL_LISTEN_PORT")
    sub_backend=$(format_hostport "$SUB_LISTEN_ADDR" "$SUB_LISTEN_PORT")
    SUB_URI_PATH=$(normalize_path_prefix "${SUB_URI_PATH:-/sub/}")
    CLASH_URI_PATH=$(normalize_path_prefix "${CLASH_URI_PATH:-/clash/}")
    mkdir -p "$(dirname "$conf_file")" || return 1

    cat <<EOF > "$conf_file"
# Managed by VPS-Optimize Port 443 Reuse. Local HTTPS Web proxy only.
server {
$(nginx_http_listen_directive "$CADDY_LISTEN_ADDR" "$CADDY_LISTEN_PORT")
    server_name ${PANEL_DOMAIN};

    ssl_certificate /etc/caddy/certs/${PANEL_DOMAIN}.crt;
    ssl_certificate_key /etc/caddy/certs/${PANEL_DOMAIN}.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers off;
    gzip on;
EOF
    append_nginx_single_443_path_proxy "$conf_file" "$SUB_URI_PATH" "$sub_backend"
    append_nginx_single_443_path_proxy "$conf_file" "$CLASH_URI_PATH" "$sub_backend"
    cat <<EOF >> "$conf_file"

    location / {
EOF
    write_nginx_single_443_proxy_headers >> "$conf_file"
    cat <<EOF >> "$conf_file"
        proxy_pass http://${panel_backend};
    }
}
EOF

    for i in "${!SITE_DOMAINS[@]}"; do
        site_domain="${SITE_DOMAINS[$i]}"
        [[ -n "$site_domain" ]] || continue
        site_backend=$(format_hostport "${SITE_BACKEND_ADDRS[$i]}" "${SITE_BACKEND_PORTS[$i]}")
        cat <<EOF >> "$conf_file"

server {
$(nginx_http_listen_directive "$CADDY_LISTEN_ADDR" "$CADDY_LISTEN_PORT")
    server_name ${site_domain};

    ssl_certificate /etc/caddy/certs/${site_domain}.crt;
    ssl_certificate_key /etc/caddy/certs/${site_domain}.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers off;
    gzip on;

    location / {
EOF
        write_nginx_single_443_proxy_headers >> "$conf_file"
        cat <<EOF >> "$conf_file"
        proxy_pass http://${site_backend};
    }
}
EOF
    done
}

reload_nginx_after_config_quarantine() {
    command -v nginx >/dev/null 2>&1 || return 0
    nginx -t >/dev/null 2>&1 || return 1
    systemctl reload nginx >/dev/null 2>&1 || systemctl restart nginx >/dev/null 2>&1 || true
}

quarantine_nginx_single_443_web_configs() {
    local keep_file="${1:-}"
    local conf_file moved=0
    for conf_file in /etc/nginx/conf.d/vps_sni_web_*.conf; do
        [[ -e "$conf_file" ]] || continue
        [[ -n "$keep_file" && "$conf_file" == "$keep_file" ]] && continue
        quarantine_path "$conf_file" "/etc/vps-optimize/quarantine/nginx-sni-web" >/dev/null 2>&1 || true
        moved=$((moved + 1))
    done
    if [[ "$moved" -gt 0 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 已隔离 ${moved} 个旧 443 Nginx 本地 Web 反代配置。${PLAIN}" "${YELLOW}⚠️ Isolated ${moved} Gejiu 443 Nginx local web reverse proxy configuration.${PLAIN}" "${YELLOW}⚠️ Карантин ${moved} Gejiu 443 Nginx Конфигурация обратного прокси-сервера локального веб-сайта.${PLAIN}")"
        reload_nginx_after_config_quarantine || echo -e "$(localized_text "${YELLOW}⚠️ Nginx 配置隔离后未能立即重载，后续应用阶段会再次校验。${PLAIN}" "${YELLOW}⚠️ Nginx failed to reload immediately after configuring isolation, and will be verified again in subsequent application stages.${PLAIN}" "${YELLOW}⚠️ Nginx не удалось перезагрузить сразу после настройки изоляции, и он будет проверен снова на последующих этапах применения.${PLAIN}")"
    fi
}

quarantine_caddy_single_443_web_configs() {
    local domain conf_file moved=0
    for domain in "$PANEL_DOMAIN" "${SITE_DOMAINS[@]}"; do
        [[ -n "$domain" ]] || continue
        conf_file="/etc/caddy/conf.d/${domain}.caddy"
        [[ -e "$conf_file" ]] || continue
        quarantine_path "$conf_file" "/etc/vps-optimize/quarantine/caddy-sni-web" >/dev/null 2>&1 || true
        moved=$((moved + 1))
    done
    if [[ "$moved" -gt 0 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 已隔离 ${moved} 个旧 443 Caddy 本地 Web 反代配置。${PLAIN}" "${YELLOW}⚠️ Isolated ${moved} Gejiu 443 Caddy local web reverse proxy configuration.${PLAIN}" "${YELLOW}⚠️ Карантин ${moved} Gejiu 443 Caddy Конфигурация обратного прокси-сервера локального веб-сайта.${PLAIN}")"
        if command -v caddy >/dev/null 2>&1 && [[ -f /etc/caddy/Caddyfile ]]; then
            caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1 && \
                { systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1 || true; }
        fi
    fi
}

apply_nginx_web_configs_for_single_443() {
    local conf_file
    conf_file=$(nginx_single_443_web_conf_path)
    install_nginx_http_if_needed || return 1
    ensure_nginx_http_conf_d || return 1
    harden_nginx_public_errors
    write_nginx_proxy_map_conf || return 1
    quarantine_legacy_nginx_https_proxy_configs
    quarantine_legacy_caddy_443_configs
    quarantine_caddy_single_443_web_configs
    quarantine_nginx_single_443_web_configs "$conf_file"
    write_nginx_single_443_web_config "$conf_file" || return 1
    if ! nginx -t; then
        echo -e "$(localized_text "${RED}❌ Nginx 本地 Web 反代配置校验失败，已隔离新增配置。${PLAIN}" "${RED}❌ Nginx The local Web reverse proxy configuration validation failed, and the new configuration has been isolated.${PLAIN}" "${RED}❌ Nginx Проверка конфигурации локального обратный прокси веб-страниц не удалась, и новая конфигурация была изолирована.${PLAIN}")"
        quarantine_path "$conf_file" "/etc/vps-optimize/quarantine/nginx-sni-web" >/dev/null 2>&1 || true
        return 1
    fi
}

stage_and_validate_caddy_configs_for_single_443() {
    local plan_dir plan_conf_dir validate_log
    install_caddy_if_needed || return 1
    plan_dir=$(mktemp -d /tmp/vpso-caddy-plan.XXXXXX) || return 1
    chmod 700 "$plan_dir" 2>/dev/null || true
    plan_conf_dir="${plan_dir}/conf.d"
    validate_log="${plan_dir}/caddy-validate.log"
    mkdir -p "$plan_conf_dir" || return 1

    cat <<EOF > "${plan_dir}/Caddyfile"
{
    auto_https off
}

import ${plan_conf_dir}/*
EOF
    write_caddy_panel_config "${plan_conf_dir}/${PANEL_DOMAIN}.caddy"
    write_caddy_site_config "$plan_conf_dir"

    echo -e "$(localized_text "${CYAN}▶ 正在预校验 Caddy 计划配置，暂不改动 /etc/caddy...${PLAIN}" "${CYAN}▶ Pre-verifying the planned configuration of Caddy, /etc/caddy... will not be changed for the time being.${PLAIN}" "${CYAN}▶ Предварительная проверка запланированной конфигурации Caddy, /etc/caddy... пока не будет изменена.${PLAIN}")"
    if caddy validate --config "${plan_dir}/Caddyfile" >"$validate_log" 2>&1; then
        echo -e "$(localized_text "${GREEN}✅ Caddy 计划配置校验通过。${PLAIN}" "${GREEN}✅ Caddy plan configuration validation passed.${PLAIN}" "${GREEN}✅ Caddy Проверка конфигурации плана пройдена.${PLAIN}")"
        return 0
    fi

    echo -e "$(localized_text "${RED}❌ Caddy 计划配置校验失败，已停止写入和切换。${PLAIN}" "${RED}❌ Caddy Plan configuration validation failed, writing and switching have stopped.${PLAIN}" "${RED}❌ Caddy Проверка конфигурации плана не удалась, запись и переключение остановлены.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}预检目录：${plan_dir}${PLAIN}" "${YELLOW}Preflight check catalog: ${plan_dir}${PLAIN}" "${YELLOW}Каталог предварительной проверки : ${plan_dir}${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}最近校验输出：${PLAIN}" "${YELLOW}Latest check output:${PLAIN}" "${YELLOW}последний результат проверки:${PLAIN}")"
    tail -n 80 "$validate_log" 2>/dev/null || true
    return 1
}

apply_caddy_configs_for_single_443() {
    quarantine_legacy_nginx_https_proxy_configs
    quarantine_nginx_single_443_web_configs
    stage_and_validate_caddy_configs_for_single_443 || return 1
    ensure_caddy_local_base_config || return 1
    write_caddy_panel_config
    write_caddy_site_config
    caddy_format_configs
    if ! caddy validate --config /etc/caddy/Caddyfile; then
        echo -e "$(localized_text "${RED}❌ Caddy 实际配置校验失败，拒绝继续。${PLAIN}" "${RED}❌ Caddy The actual configuration validation failed and continues is refused.${PLAIN}" "${RED}❌ Caddy Фактическая проверка конфигурации не удалась и в продолжении отказано.${PLAIN}")"
        return 1
    fi
}

apply_web_proxy_configs_for_single_443() {
    WEB_PROXY_ENGINE=$(current_web_proxy_engine)
    assert_web_proxy_whitelist_supported "${ENTRY_MODE:-$(get_entry_mode)}" "$WEB_PROXY_ENGINE" || return 1
    case "$WEB_PROXY_ENGINE" in
        nginx) apply_nginx_web_configs_for_single_443 ;;
        *) apply_caddy_configs_for_single_443 ;;
    esac
}

restart_web_proxy_for_single_443() {
    WEB_PROXY_ENGINE=$(current_web_proxy_engine)
    case "$WEB_PROXY_ENGINE" in
        nginx)
            if ! systemctl enable nginx >/dev/null 2>&1; then
                echo -e "$(localized_text "${RED}❌ nginx Web 反代开机启动设置失败。${PLAIN}" "${RED}❌ nginx Web reverse proxy startup setting failed.${PLAIN}" "${RED}❌ nginx Не удалось настроить запуск веб-прокси.${PLAIN}")"
                return 1
            fi
            systemctl restart nginx || return 1
            ;;
        *)
            if ! systemctl enable caddy >/dev/null 2>&1; then
                echo -e "$(localized_text "${RED}❌ Caddy Web 反代开机启动设置失败。${PLAIN}" "${RED}❌ Caddy Web reverse proxy startup setting failed.${PLAIN}" "${RED}❌ Caddy Не удалось настроить запуск веб-прокси.${PLAIN}")"
                return 1
            fi
            systemctl restart caddy || return 1
            ;;
    esac
}

issue_and_install_cert_for_domain() {
    local domain="$1"
    local cf_token="$2"
    local acme_bin="/root/.acme.sh/acme.sh"
    local acme_email
    acme_email=$(get_acme_account_email)
    if [[ ! -x "$acme_bin" ]]; then
        install_acme_sh "$acme_email" || return 1
    fi
    prepare_acme_account "$acme_bin" "$acme_email" || return 1
    mkdir -p /etc/caddy/certs /root/cert
    echo -e "$(localized_text "${CYAN}▶ 正在为 ${domain} 申请 Cloudflare DNS 证书...${PLAIN}" "${CYAN}▶ Applying for Cloudflare DNS certificate for ${domain}...${PLAIN}" "${CYAN}▶ Подача заявки на сертификат Cloudflare DNS для ${domain}...${PLAIN}")"
    issue_cf_dns_cert_with_retry "$domain" "$cf_token" "$acme_bin" || return 1
    "$acme_bin" --install-cert -d "$domain" --ecc \
        --fullchain-file "/etc/caddy/certs/${domain}.crt" \
        --key-file "/etc/caddy/certs/${domain}.key" \
        --reloadcmd "systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1 || true; systemctl reload nginx >/dev/null 2>&1 || systemctl restart nginx >/dev/null 2>&1 || true" >/dev/null 2>&1 || return 1
    if id caddy >/dev/null 2>&1; then
        chown root:caddy "/etc/caddy/certs/${domain}.crt" "/etc/caddy/certs/${domain}.key" >/dev/null 2>&1
        chmod 640 "/etc/caddy/certs/${domain}.crt" "/etc/caddy/certs/${domain}.key"
    else
        chmod 600 "/etc/caddy/certs/${domain}.crt" "/etc/caddy/certs/${domain}.key"
    fi
    ln -sfn "/etc/caddy/certs/${domain}.crt" "/root/cert/${domain}.crt"
    ln -sfn "/etc/caddy/certs/${domain}.key" "/root/cert/${domain}.key"
}

save_sni_stack_env() {
    mkdir -p /etc/vps-optimize
    local entry_mode web_proxy_engine strict_sni_gate site_domains_csv site_backend_addrs_csv site_backend_ports_csv
    local tcp_route_snis_csv tcp_route_addrs_csv tcp_route_ports_csv
    local sni_ip_whitelist_domains_csv sni_ip_whitelist_ranges_pipe
    entry_mode="${ENTRY_MODE:-$(get_entry_mode)}"
    case "$entry_mode" in
        "nginx_stream") entry_mode="nginx-stream" ;;
        "xray_fallback") entry_mode="xray-fallback" ;;
        "tcp_peek") entry_mode="tcp-peek" ;;
    esac
    case "$entry_mode" in
        "nginx-stream"|"xray-fallback"|"tcp-peek") ;;
        *) entry_mode="nginx-stream" ;;
    esac
    web_proxy_engine=$(normalize_web_proxy_engine "${WEB_PROXY_ENGINE:-caddy}" 2>/dev/null || echo "caddy")
    strict_sni_gate=$(normalize_strict_sni_gate "${STRICT_SNI_GATE:-false}")
    site_domains_csv=$(IFS=','; echo "${SITE_DOMAINS[*]}")
    site_backend_addrs_csv=$(IFS=','; echo "${SITE_BACKEND_ADDRS[*]}")
    site_backend_ports_csv=$(IFS=','; echo "${SITE_BACKEND_PORTS[*]}")
    tcp_route_snis_csv=$(IFS=','; echo "${TCP_ROUTE_SNIS[*]}")
    tcp_route_addrs_csv=$(IFS=','; echo "${TCP_ROUTE_ADDRS[*]}")
    tcp_route_ports_csv=$(IFS=','; echo "${TCP_ROUTE_PORTS[*]}")
    sni_ip_whitelist_domains_csv=$(IFS=','; echo "${SNI_IP_WHITELIST_DOMAINS[*]}")
    sni_ip_whitelist_ranges_pipe=$(IFS='|'; echo "${SNI_IP_WHITELIST_RANGES[*]}")
    cat <<EOF > /etc/vps-optimize/sni-stack.env
ENTRY_MODE='${entry_mode}'
STRICT_SNI_GATE='${strict_sni_gate}'
WEB_PROXY_ENGINE='${web_proxy_engine}'
PANEL_DOMAIN='${PANEL_DOMAIN}'
SITE_DOMAIN='${SITE_DOMAINS[0]:-}'
SITE_DOMAINS_CSV='${site_domains_csv}'
REALITY_SNI='${REALITY_SNI}'
NGINX_LISTEN_ADDR='${NGINX_LISTEN_ADDR}'
NGINX_LISTEN_PORT='${NGINX_LISTEN_PORT}'
CADDY_LISTEN_ADDR='${CADDY_LISTEN_ADDR}'
CADDY_LISTEN_PORT='${CADDY_LISTEN_PORT}'
XRAY_LISTEN_ADDR='${XRAY_LISTEN_ADDR}'
XRAY_LISTEN_PORT='${XRAY_LISTEN_PORT}'
XRAY_FALLBACK_MAIN_SNI='${XRAY_FALLBACK_MAIN_SNI:-}'
XRAY_FALLBACK_MAIN_ADDR='${XRAY_FALLBACK_MAIN_ADDR:-}'
XRAY_FALLBACK_MAIN_PORT='${XRAY_FALLBACK_MAIN_PORT:-}'
PANEL_LISTEN_ADDR='${PANEL_LISTEN_ADDR}'
PANEL_LISTEN_PORT='${PANEL_LISTEN_PORT}'
PANEL_WEB_PATH='${PANEL_WEB_PATH}'
SUB_LISTEN_ADDR='${SUB_LISTEN_ADDR}'
SUB_LISTEN_PORT='${SUB_LISTEN_PORT}'
SUB_URI_PATH='${SUB_URI_PATH}'
CLASH_URI_PATH='${CLASH_URI_PATH}'
SITE_BACKEND_ADDR='${SITE_BACKEND_ADDRS[0]:-127.0.0.1}'
SITE_BACKEND_PORT='${SITE_BACKEND_PORTS[0]:-3000}'
SITE_BACKEND_ADDRS_CSV='${site_backend_addrs_csv}'
SITE_BACKEND_PORTS_CSV='${site_backend_ports_csv}'
TCP_ROUTE_SNIS_CSV='${tcp_route_snis_csv}'
TCP_ROUTE_ADDRS_CSV='${tcp_route_addrs_csv}'
TCP_ROUTE_PORTS_CSV='${tcp_route_ports_csv}'
SNI_IP_WHITELIST_DOMAINS_CSV='${sni_ip_whitelist_domains_csv}'
SNI_IP_WHITELIST_RANGES_PIPE='${sni_ip_whitelist_ranges_pipe}'
EOF
    chmod 600 /etc/vps-optimize/sni-stack.env
}

harden_single_443_firewall() {
    local ssh_port remove_ports port
    local failures=()
    ssh_port=$(ss -lntp 2>/dev/null | awk '/sshd/ {print $4}' | awk -F: '{print $NF}' | grep -E '^[0-9]+$' | head -n1)
    ssh_port=${ssh_port:-22}
    confirm_danger \
        "$(localized_text "收紧 443 入口防火墙" "Tighten the Port 443 firewall" "Ужесточить правила брандмауэра для порта 443")" \
        "$(localized_text "只保留 SSH ${ssh_port:-22}/tcp 与公网入口 ${NGINX_LISTEN_PORT}/tcp，并撤销已知后端端口的公网放行规则。" "Keep only SSH ${ssh_port:-22}/tcp and public entry ${NGINX_LISTEN_PORT}/tcp, and revoke public allow rules for known backend ports." "Оставить только SSH ${ssh_port:-22}/tcp и публичный вход ${NGINX_LISTEN_PORT}/tcp, удалив разрешающие правила для известных внутренних портов.")" \
        "$(localized_text "保持当前 SSH 会话；可通过云厂商控制台重新放行端口或恢复防火墙规则。" "Keep the current SSH session open; use the provider console to restore firewall rules or allow ports again." "Не закрывайте текущий сеанс SSH; правила можно восстановить через консоль провайдера.")" \
        "$(localized_text "若 3x-ui 仍监听 0.0.0.0:${PANEL_LISTEN_PORT}，自动活动端口检测以后可能再次放行该端口。" "If 3x-ui still listens on 0.0.0.0:${PANEL_LISTEN_PORT}, automatic active-port detection may allow it again later." "Если 3x-ui продолжает слушать 0.0.0.0:${PANEL_LISTEN_PORT}, автоматическое обнаружение активных портов позднее может снова разрешить этот порт.")" || return 0
    remove_ports=("$CADDY_LISTEN_PORT" "$XRAY_LISTEN_PORT" "$PANEL_LISTEN_PORT" "$SUB_LISTEN_PORT" "${SITE_BACKEND_PORTS[@]}" "${TCP_ROUTE_PORTS[@]}" "${XRAY_SNI_ROUTE_PORTS[@]}" "40000" "8443" "1443" "2096" "3000")
    if command -v ufw >/dev/null 2>&1; then
        ufw allow "${ssh_port}/tcp" >/dev/null 2>&1 || failures+=("SSH ${ssh_port}/tcp")
        ufw allow "${NGINX_LISTEN_PORT}/tcp" >/dev/null 2>&1 || failures+=("entry ${NGINX_LISTEN_PORT}/tcp")
        for port in "${remove_ports[@]}"; do
            [[ "$port" == "$ssh_port" || "$port" == "$NGINX_LISTEN_PORT" ]] && continue
            ufw delete allow "${port}/tcp" >/dev/null 2>&1 || :
            ufw delete allow "${port}/udp" >/dev/null 2>&1 || :
        done
    elif command -v firewall-cmd >/dev/null 2>&1; then
        systemctl enable --now firewalld >/dev/null 2>&1 || failures+=("firewalld")
        firewall-cmd --permanent --add-port="${ssh_port}/tcp" >/dev/null 2>&1 || failures+=("SSH ${ssh_port}/tcp")
        firewall-cmd --permanent --add-port="${NGINX_LISTEN_PORT}/tcp" >/dev/null 2>&1 || failures+=("entry ${NGINX_LISTEN_PORT}/tcp")
        for port in "${remove_ports[@]}"; do
            [[ "$port" == "$ssh_port" || "$port" == "$NGINX_LISTEN_PORT" ]] && continue
            firewall-cmd --permanent --remove-port="${port}/tcp" >/dev/null 2>&1 || :
            firewall-cmd --permanent --remove-port="${port}/udp" >/dev/null 2>&1 || :
        done
        firewall-cmd --reload >/dev/null 2>&1 || failures+=("firewalld reload")
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 ufw/firewalld，跳过防火墙收紧。${PLAIN}" "${YELLOW}⚠️ ufw/firewalld not detected, skipping firewall tightening.${PLAIN}" "${YELLOW}⚠️ ufw/firewalld не обнаружен, пропускается ужесточение брандмауэра.${PLAIN}")"
        return 0
    fi
    if (( ${#failures[@]} > 0 )); then
        echo -e "$(localized_text "${RED}❌ 防火墙收紧未完整应用：${failures[*]}。请保持当前 SSH 会话并检查防火墙状态。${PLAIN}" "${RED}❌ Firewall tightening was only partially applied: ${failures[*]}. Keep the current SSH session open and inspect the firewall state.${PLAIN}" "${RED}❌ Правила брандмауэра применены не полностью: ${failures[*]}. Не закрывайте текущий сеанс SSH и проверьте состояние брандмауэра.${PLAIN}")"
        return 1
    fi
    echo -e "$(localized_text "${GREEN}✅ 防火墙规则已应用：保留 SSH ${ssh_port}/tcp 与入口 ${NGINX_LISTEN_PORT}/tcp。${PLAIN}" "${GREEN}✅ Firewall rules applied: SSH ${ssh_port}/tcp and entry ${NGINX_LISTEN_PORT}/tcp are allowed.${PLAIN}" "${GREEN}✅ Правила применены: разрешены SSH ${ssh_port}/tcp и вход ${NGINX_LISTEN_PORT}/tcp.${PLAIN}")"
}

print_sni_stack_result() {
    local check_ports=()
    local check_regex=""
    local p entry_mode entry_label entry_listener web_engine web_label
    entry_mode="${ENTRY_MODE:-nginx-stream}"
    entry_mode=$(normalize_entry_mode_name "$entry_mode" 2>/dev/null || echo "nginx-stream")
    web_engine=$(current_web_proxy_engine)
    web_label=$(web_proxy_engine_label "$web_engine")
    case "$entry_mode" in
        "nginx-stream") entry_label="$(localized_text "Nginx Stream 模式" "Nginx Stream mode" "Режим Nginx Stream")"; entry_listener="nginx" ;;
        "xray-fallback") entry_label="$(localized_text "Xray Fallback 模式" "Xray Fallback mode" "Режим Xray Fallback")"; entry_listener="$(localized_text "xray/3x-ui 主入站" "xray/3x-ui main inbound" "Основное входящее подключение xray/3x-ui")" ;;
        "tcp-peek") entry_label="$(localized_text "TCP Peek + Splice 模式" "TCP Peek + Splice mode" "Режим TCP Peek + Splice")"; entry_listener="$(localized_text "vpso-mux 分流器" "vpso-mux traffic router" "Маршрутизатор трафика vpso-mux")" ;;
        *) entry_label="$entry_mode"; entry_listener="$entry_mode" ;;
    esac
    check_ports=("$NGINX_LISTEN_PORT" "$CADDY_LISTEN_PORT" "$XRAY_LISTEN_PORT" "$PANEL_LISTEN_PORT" "$SUB_LISTEN_PORT" "${SITE_BACKEND_PORTS[@]}" "${TCP_ROUTE_PORTS[@]}" "${XRAY_SNI_ROUTE_PORTS[@]}")
    mapfile -t check_ports < <(printf '%s\n' "${check_ports[@]}" | grep -E '^[0-9]+$' | awk '!seen[$0]++')
    for p in "${check_ports[@]}"; do
        if [[ -z "$check_regex" ]]; then
            check_regex=":${p}([[:space:]]|$)"
        else
            check_regex="${check_regex}|:${p}([[:space:]]|$)"
        fi
    done

    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${GREEN}✅ 443端口复用配置完成${PLAIN}" "${GREEN}✅ Port 443 Reuse route configuration completed${PLAIN}" "${GREEN}Конфигурация маршрутизации повторного использования порта 443 завершена${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "当前入口模式：${entry_label} (${entry_mode})" "Current entry mode: ${entry_label} (${entry_mode})" "Текущий режим ввода: ${entry_label} (${entry_mode})")"
    echo -e "$(localized_text "当前 Web 反代引擎：${web_label} (${web_engine})" "Current web reverse proxy engine: ${web_label} (${web_engine})" "Текущий движок веб-прокси: ${web_label} (${web_engine})")"
    echo -e "$(localized_text "${BOLD}一、以后从外面只访问这些地址${PLAIN}" "${BOLD}1. In the future, only these addresses will be accessed from the outside.${PLAIN}" "${BOLD}1. В дальнейшем доступ извне будет осуществляться только по этим адресам.${PLAIN}")"
    echo -e "$(localized_text "  面板入口：      https://${PANEL_DOMAIN}${PANEL_WEB_PATH}" "Panel entry: https://${PANEL_DOMAIN}${PANEL_WEB_PATH}" "Входная панель: https://${PANEL_DOMAIN}${PANEL_WEB_PATH}")"
    echo -e "$(localized_text "  普通订阅入口：  https://${PANEL_DOMAIN}${SUB_URI_PATH}" "Ordinary subscription entry: https://${PANEL_DOMAIN}${SUB_URI_PATH}" "Обычный вход по подписке: https://${PANEL_DOMAIN}${SUB_URI_PATH}.")"
    echo -e "  Clash/Mihomo：  https://${PANEL_DOMAIN}${CLASH_URI_PATH}"
    if [[ ${#SITE_DOMAINS[@]} -gt 0 ]]; then
        local i
        for i in "${!SITE_DOMAINS[@]}"; do
            echo -e "$(localized_text "  网站/反代入口： https://${SITE_DOMAINS[$i]}/" "Website/reverse proxy entry: https://${SITE_DOMAINS[$i]}/" "Вход на сайт/обратный прокси: https://${SITE_DOMAINS[$i]}/")"
        done
    fi
    if [[ ${#TCP_ROUTE_SNIS[@]} -gt 0 ]]; then
        local tcp_i
        for tcp_i in "${!TCP_ROUTE_SNIS[@]}"; do
            echo -e "$(localized_text "  TCP/SNI 入站：  ${TCP_ROUTE_SNIS[$tcp_i]}:${NGINX_LISTEN_PORT} -> ${TCP_ROUTE_ADDRS[$tcp_i]}:${TCP_ROUTE_PORTS[$tcp_i]}" "TCP/SNI Inbound: ${TCP_ROUTE_SNIS[$tcp_i]}:${NGINX_LISTEN_PORT} -> ${TCP_ROUTE_ADDRS[$tcp_i]}:${TCP_ROUTE_PORTS[$tcp_i]}" "TCP/SNI Входящий: ${TCP_ROUTE_SNIS[$tcp_i]}:${NGINX_LISTEN_PORT} -> ${TCP_ROUTE_ADDRS[$tcp_i]}:${TCP_ROUTE_PORTS[$tcp_i]}")"
        done
    fi
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -gt 0 ]]; then
        local xray_route_i
        for xray_route_i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            echo -e "$(localized_text "  Xray 入站：     ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}:${NGINX_LISTEN_PORT} -> ${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}:${XRAY_SNI_ROUTE_PORTS[$xray_route_i]}" "Xray Inbound: ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}:${NGINX_LISTEN_PORT} -> ${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}:${XRAY_SNI_ROUTE_PORTS[$xray_route_i]}" "Xray Входящий: ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]}:${NGINX_LISTEN_PORT} -> ${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}:${XRAY_SNI_ROUTE_PORTS[$xray_route_i]}")"
        done
    fi
    echo -e "$(localized_text "  REALITY 端口：  ${NGINX_LISTEN_PORT}" "REALITY Port: ${NGINX_LISTEN_PORT}" "REALITY Порт: ${NGINX_LISTEN_PORT}")"
    echo -e ""
    echo -e "$(localized_text "${YELLOW}不要从公网访问这些内部端口：${CADDY_LISTEN_PORT}/${XRAY_LISTEN_PORT}/${PANEL_LISTEN_PORT}/${SUB_LISTEN_PORT}/${SITE_BACKEND_PORTS[*]} ${TCP_ROUTE_PORTS[*]} ${XRAY_SNI_ROUTE_PORTS[*]}${PLAIN}" "${YELLOW}Do not access these internal ports from the public: ${CADDY_LISTEN_PORT}/${XRAY_LISTEN_PORT}/${PANEL_LISTEN_PORT}/${SUB_LISTEN_PORT}/${SITE_BACKEND_PORTS[*]} ${TCP_ROUTE_PORTS[*]} ${XRAY_SNI_ROUTE_PORTS[*]}${PLAIN}" "${YELLOW}Не обращайтесь к этим внутренним портам из публичной сети: ${CADDY_LISTEN_PORT}/${XRAY_LISTEN_PORT}/${PANEL_LISTEN_PORT}/${SUB_LISTEN_PORT}/${SITE_BACKEND_PORTS[*]} ${TCP_ROUTE_PORTS[*]} ${XRAY_SNI_ROUTE_PORTS[*]}${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}它们应该只给本机内部服务互相连接，不是浏览器入口。${PLAIN}" "${YELLOW}They should only connect the internal services of this machine to each other, not the browser entry.${PLAIN}" "${YELLOW}Они должны соединять между собой только внутренние службы этой машины, а не вход в браузер.${PLAIN}")"
    echo -e ""
    echo -e "$(localized_text "${BOLD}二、3x-ui 面板设置建议${PLAIN}" "${BOLD}2. 3x-ui panel setting recommendation${PLAIN}" "${BOLD}2. 3x-ui Рекомендации по настройке панели${PLAIN}")"
    echo -e "$(localized_text "  面板监听地址：${PANEL_LISTEN_ADDR}" "Panel listening address: ${PANEL_LISTEN_ADDR}" "Адрес прослушивания панели: ${PANEL_LISTEN_ADDR}")"
    echo -e "$(localized_text "  面板端口：    ${PANEL_LISTEN_PORT}" "Panel port: ${PANEL_LISTEN_PORT}" "Порт панели: ${PANEL_LISTEN_PORT}")"
    echo -e "  webBasePath： ${PANEL_WEB_PATH}"
    echo -e "$(localized_text "  3.x 新安装 SSL：第 4 项 Skip SSL，再选 y 仅绑定 127.0.0.1" "3.x new-install SSL: option 4, Skip SSL, then y to bind only to 127.0.0.1" "SSL при новой установке 3.x: пункт 4 Skip SSL, затем y для привязки только к 127.0.0.1")"
    echo -e "$(localized_text "  2.x/旧配置面板证书路径/私钥路径：清空" "2.x/old configuration panel certificate path/private key path: clear" "2.x/старый путь к сертификату панели конфигурации/путь к секретному ключу: очистить")"
    echo -e "$(localized_text "  Web 反代引擎后端连接：http://${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "Web reverse proxy engine backend connection: http://${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "Серверное соединение механизма веб-прокси: http://${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}")"
    echo -e "  Panel URL / Public URL / External URL：https://${PANEL_DOMAIN}${PANEL_WEB_PATH}"
    echo -e "  Subscription URI Path：${SUB_URI_PATH}"
    echo -e "  Subscription External URL：https://${PANEL_DOMAIN}${SUB_URI_PATH}"
    echo -e "  Clash/Mihomo URI Path：${CLASH_URI_PATH}"
    echo -e "  Clash/Mihomo External URL：https://${PANEL_DOMAIN}${CLASH_URI_PATH}"
    echo -e "$(localized_text "${YELLOW}  不建议使用 webBasePath=/，随机面板路径能降低被批量扫描命中的概率。${PLAIN}" "${YELLOW}It is not recommended to use webBasePath=/. Random panel paths can reduce the probability of being hit by batch scanning.${PLAIN}" "${YELLOW}Не рекомендуется использовать webBasePath=/. Случайное расположение панелей может снизить вероятность попадания в пакетное сканирование.${PLAIN}")"
    echo -e "$(localized_text "  2.x/旧配置订阅证书路径/私钥路径：清空" "2.x/old configuration subscription certificate path/private key path: clear" "2.x/путь сертификата подписки старой конфигурации/путь закрытого ключа: очистить")"
    echo -e ""
    echo -e "$(localized_text "${BOLD}三、Xray / 3x-ui+Reality 入站这样填${PLAIN}" "${BOLD}3. Configure the Xray / 3x-ui+Reality inbound as follows${PLAIN}" "${BOLD}3. Заполните входящее подключение Xray / 3x-ui+Reality так${PLAIN}")"
    echo -e "$(localized_text "  入站监听地址 listen：${XRAY_LISTEN_ADDR}" "Inbound listening address listen: ${XRAY_LISTEN_ADDR}" "Адрес прослушивания входящего подключения: ${XRAY_LISTEN_ADDR}")"
    echo -e "$(localized_text "  入站监听端口 port：  ${XRAY_LISTEN_PORT}" "Inbound listening port port: ${XRAY_LISTEN_PORT}" "Порт входящего прослушивания: ${XRAY_LISTEN_PORT}")"
    echo -e "$(localized_text "  协议 protocol：      VLESS" "Protocol protocol: VLESS" "Протокол протокола: VLESS")"
    echo -e "$(localized_text "  传输 network：       tcp" "Transmission network: tcp" "Сеть передачи: tcp")"
    echo -e "$(localized_text "  安全 security：      reality" "Security security: reality" "Безопасность безопасности: reality")"
    echo -e "  REALITY dest：       ${REALITY_SNI}:443"
    echo -e "  serverNames：        ${REALITY_SNI}"
    echo -e "  SpiderX：            /"
    echo -e "$(localized_text "  客户端连接地址：     你的服务器 IP 或解析到服务器的域名" "Client connection address: Your server IP or domain resolved to the server" "Адрес подключения клиента: IP-адрес вашего сервера или доменное имя, разрешенное серверу.")"
    echo -e "$(localized_text "  客户端连接端口：     ${NGINX_LISTEN_PORT}" "Client connection port: ${NGINX_LISTEN_PORT}" "Порт подключения клиента: ${NGINX_LISTEN_PORT}")"
    echo -e "$(localized_text "  客户端 SNI/serverName：${REALITY_SNI}" "Client SNI/serverName: ${REALITY_SNI}" "Клиент SNI/имя сервера: ${REALITY_SNI}")"
    echo -e "$(localized_text "${YELLOW}  注意：REALITY 的 dest/serverNames 必须是外部真实站点，不要写面板域名。${PLAIN}" "${YELLOW}Note: The dest/serverNames of REALITY must be an external real site, do not write the panel domain.${PLAIN}" "${YELLOW}Примечание. Имена dest/serverName для REALITY должны быть внешним реальным сайтом, не записывайте имя домена панели.${PLAIN}")"
    echo -e ""
    echo -e "$(localized_text "${BOLD}四、常见错误怎么判断${PLAIN}" "${BOLD}4. How to judge common errors${PLAIN}" "${BOLD}4. Как определить типичные ошибки${PLAIN}")"
    echo -e "$(localized_text "  ERR_SSL_PROTOCOL_ERROR：通常是访问了内部端口，外部只访问 https://${PANEL_DOMAIN}${PANEL_WEB_PATH}" "ERR_SSL_PROTOCOL_ERROR: Usually the internal port is accessed, and only https://${PANEL_DOMAIN}${PANEL_WEB_PATH} is accessed externally." "ERR_SSL_PROTOCOL_ERROR: Обычно осуществляется доступ к внутреннему порту, и только к https://${PANEL_DOMAIN}${PANEL_WEB_PATH} осуществляется внешний доступ.")"
    echo -e "$(localized_text "  ERR_TOO_MANY_REDIRECTS：通常是 3.x 误启用 3x-ui SSL、2.x/旧配置证书路径没清空，或外部地址/路径配置不一致" "ERR_TOO_MANY_REDIRECTS: Usually 3.x mistakenly enabled 3x-ui SSL, 2.x/old configuration certificate path is not cleared, or the external address/path configuration is inconsistent" "ERR_TOO_MANY_REDIRECTS: Обычно 3.x ошибочно включен 3x-ui SSL, путь сертификата конфигурации 2.x/старая не очищается или конфигурация внешнего адреса/пути несовместима.")"
    echo -e "$(localized_text "  HTTP 404：先检查访问路径是否等于 3x-ui 的 webBasePath，再检查 Web 反代引擎是否反代到 ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "HTTP 404: First check whether the access path is equal to the webBasePath of 3x-ui, and then check whether the Web reverse proxy engine is reverse proxy to ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "HTTP 404: сначала проверьте, равен ли путь доступа webBasePath 3x-ui, а затем проверьте, соответствует ли обратный прокси-сервер веб-обратного прокси ${PANEL_LISTEN_ADDR}: ${PANEL_LISTEN_PORT}.")"
    echo -e "$(localized_text "  502 Bad Gateway：通常是 3x-ui 没启动、端口不对，或 3x-ui 后端仍是 HTTPS" "502 Bad Gateway: Usually 3x-ui is not started, the port is wrong, or 3x-ui backend is still HTTPS" "502 Bad Gateway: обычно 3x-ui не запускается, порт неправильный или бэкенд 3x-ui все еще остается HTTPS.")"
    echo -e ""
    echo -e "$(localized_text "${BOLD}五、入口与后端配置${PLAIN}" "${BOLD}5. Entry and backend configuration${PLAIN}" "${BOLD}5. Входная и серверная конфигурация${PLAIN}")"
    echo -e "  ${NGINX_LISTEN_ADDR}:${NGINX_LISTEN_PORT} -> ${entry_listener}"
    echo -e "  ${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT} -> ${web_label}"
    echo -e "  ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT} -> xray"
    echo -e "  ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT} -> 3x-ui"
    echo -e "  ${SUB_LISTEN_ADDR}:${SUB_LISTEN_PORT} -> 3x-ui subscription"
    if [[ ${#SITE_DOMAINS[@]} -gt 0 ]]; then
        local i
        for i in "${!SITE_DOMAINS[@]}"; do
            echo -e "$(localized_text "  ${SITE_BACKEND_ADDRS[$i]}:${SITE_BACKEND_PORTS[$i]} -> ${SITE_DOMAINS[$i]} 网站后端" "${SITE_BACKEND_ADDRS[$i]}:${SITE_BACKEND_PORTS[$i]} -> ${SITE_DOMAINS[$i]} website backend" "${SITE_BACKEND_ADDRS[$i]}:${SITE_BACKEND_PORTS[$i]} -> ${SITE_DOMAINS[$i]} бэкенд веб-сайта")"
        done
    fi
    if [[ ${#TCP_ROUTE_SNIS[@]} -gt 0 ]]; then
        local tcp_i
        for tcp_i in "${!TCP_ROUTE_SNIS[@]}"; do
            echo -e "$(localized_text "  ${TCP_ROUTE_ADDRS[$tcp_i]}:${TCP_ROUTE_PORTS[$tcp_i]} -> ${TCP_ROUTE_SNIS[$tcp_i]} TCP/SNI 入站" "${TCP_ROUTE_ADDRS[$tcp_i]}:${TCP_ROUTE_PORTS[$tcp_i]} -> ${TCP_ROUTE_SNIS[$tcp_i]} TCP/SNI inbound" "${TCP_ROUTE_ADDRS[$tcp_i]}:${TCP_ROUTE_PORTS[$tcp_i]} -> ${TCP_ROUTE_SNIS[$tcp_i]} TCP/SNI входящий")"
        done
    fi
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -gt 0 ]]; then
        local xray_route_i
        for xray_route_i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
            echo -e "$(localized_text "  ${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}:${XRAY_SNI_ROUTE_PORTS[$xray_route_i]} -> ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]} Xray 入站" "${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}:${XRAY_SNI_ROUTE_PORTS[$xray_route_i]} -> ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]} Xray inbound" "${XRAY_SNI_ROUTE_ADDRS[$xray_route_i]}:${XRAY_SNI_ROUTE_PORTS[$xray_route_i]} -> ${XRAY_SNI_ROUTE_SNIS[$xray_route_i]} Xray входящий")"
        done
    fi
    echo -e ""
    echo -e "$(localized_text "${BOLD}六、检查命令${PLAIN}" "${BOLD}6. Check command${PLAIN}" "${BOLD}6. Проверьте команду.${PLAIN}")"
    if [[ -n "$check_regex" ]]; then
        echo -e "  ss -lntp | grep -E '${check_regex}'"
    else
        echo -e "  ss -lntp"
    fi
    echo -e "  nginx -t"
    if [[ "$web_engine" == "caddy" ]]; then
        echo -e "  caddy validate --config /etc/caddy/Caddyfile"
        echo -e "  journalctl -u caddy -n 80 --no-pager"
    fi
    echo -e "  curl -I http://${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}/"
    echo -e "$(localized_text "  openssl s_client -connect 服务器IP:${NGINX_LISTEN_PORT} -servername ${PANEL_DOMAIN}" "openssl s_client -connect server IP:${NGINX_LISTEN_PORT} -servername ${PANEL_DOMAIN}" "openssl s_client -IP-адрес сервера подключения: ${NGINX_LISTEN_PORT} -имя_сервера ${PANEL_DOMAIN}")"
    echo -e "$(localized_text "  openssl s_client -connect 服务器IP:${NGINX_LISTEN_PORT} -servername ${REALITY_SNI}" "openssl s_client -connect server IP:${NGINX_LISTEN_PORT} -servername ${REALITY_SNI}" "openssl s_client -IP-адрес сервера подключения: ${NGINX_LISTEN_PORT} -имя_сервера ${REALITY_SNI}")"
    [[ "$web_engine" == "nginx" ]] && echo -e "  journalctl -u nginx -n 80 --no-pager"
    echo -e "  journalctl -u x-ui -u 3x-ui -n 80 --no-pager"
    echo -e ""
    case "$entry_mode" in
        "xray-fallback")
            echo -e "$(localized_text "${RED}绝对不要做：Web 反代引擎直接监听公网 443；3x-ui 面板、订阅服务或额外本地入站暴露公网；3.x 安装时启用 3x-ui SSL 或 2.x/旧配置证书路径未清空就跑 Web fallback；把 REALITY dest/serverNames 写成面板域名。${PLAIN}" "${RED}Do not: Web reverse proxy engine directly listens on the public port 443; 3x-ui panel, subscription service or additional local inbound exposes the public; enable 3x-ui SSL during 3.x installation or run Web fallback without clearing the certificate path of 2.x/old configuration; set REALITY dest/serverNames to the panel domain.${PLAIN}" "${RED}не должен делать: веб-механизм обратный прокси напрямую прослушивает публичный порт 443; Панель 3x-ui, служба подписки или дополнительный локальное входящее подключение предоставляют доступ к публичной сети; включите 3x-ui SSL во время установки 3.x или запустите веб-резервный вариант без очистки пути сертификата конфигурации 2.x/старой; put REALITY dest/serverNames записывается как доменное имя панели.${PLAIN}")"
            ;;
        *)
            echo -e "$(localized_text "${RED}绝对不要做：Web 反代引擎直接监听公网 443；Xray/3x-ui 主入站直接占用公网 443；3x-ui 面板或新增本地入站暴露公网；3.x 安装时启用 3x-ui SSL 或 2.x/旧配置证书路径未清空就跑 443；把 REALITY dest/serverNames 写成面板域名。${PLAIN}" "${RED}Do not: Web reverse proxy engine directly listens on the public port 443; Xray/3x-ui main inbound directly occupies the public port 443; 3x-ui panel or adds local inbound to expose the public; 3.x enable 3x-ui SSL or 2.x/old configuration certificate path is not cleared and 443 will occur; write REALITY dest/serverNames as the panel domain.${PLAIN}" "${RED}не должен делать: веб-механизм обратный прокси напрямую прослушивает публичный порт 443; основное входящее подключение Xray/3x-ui непосредственно занимает публичный порт 443; Панель 3x-ui или добавляет локальное входящее подключение для доступа к публичной сети; Путь к сертификату конфигурации 3.x Enable 3x-ui SSL или 2.x/old не очищается и возникает ошибка 443; напишите REALITY dest/serverNames в качестве имени домена панели.${PLAIN}")"
            ;;
    esac
}

apply_sni_stack_runtime_config() {
    local backup_dir current_mode
    current_mode="${ENTRY_MODE:-$(get_entry_mode)}"
    current_mode=$(normalize_entry_mode_name "$current_mode" 2>/dev/null || echo "nginx-stream")

    create_sni_stack_backup
    backup_dir=$(cat /etc/vps-optimize/sni-stack.last-backup 2>/dev/null)
    guard_current_ssh_not_on_entry_port "$(localized_text "重新应用 443端口复用运行参数" "Reapply Port 443 Reuse Run Parameters" "Повторно применить 443 отдельных рабочих параметра")" || return 1
    check_entry_mode_dependencies "$current_mode" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "入口模式依赖检查失败" "Entry mode dependency check failed" "Проверка зависимости режима входа не удалась")"; return 1; }
    preflight_entry_mode_before_cutover "$current_mode" || { echo -e "$(localized_text "${RED}❌ 入口模式 ${current_mode} 预检失败，公网 443 未重新应用。${PLAIN}" "${RED}❌ entry mode ${current_mode} Preflight failed, public port 443 was not reapplied.${PLAIN}" "${RED}❌ Режим входа ${current_mode} Не удалось выполнить предварительную проверку, конфигурация публичного порта 443 не была применена повторно.${PLAIN}")"; return 1; }
    stop_public_443_entry_services_for_target "$current_mode" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "停止旧公网 443 入口服务失败" "Stop the old public port 443 entry service failed" "Остановить старую публичную сеть 443, служба входа не удалась")"; return 1; }
    apply_entry_mode_by_name "$current_mode" "$backup_dir" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "入口模式 ${current_mode} 应用失败" "Entry mode ${current_mode} application failed" "Режим входа в приложение ${current_mode} не выполнен.")"; return 1; }
    ENTRY_MODE="$current_mode"
    save_sni_stack_env
    write_single_443_engine_state "$(entry_mode_engine_name "$current_mode")" "$backup_dir"
    generate_caddy_cf_manifest
}

# ---------------------------------------------------------
# Module: sni_stack_sites.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Port 443 Reuse web-domain and custom TCP-route CRUD workflows.

list_sni_stack_sites() {
    load_sni_stack_env || return 1
    local web_engine web_label
    web_engine=$(current_web_proxy_engine)
    web_label=$(web_proxy_engine_label "$web_engine")
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}当前 443端口复用网站/反代域名${PLAIN}" "${BOLD}Currently Port 443 Reuse/reverse proxy domain${PLAIN}" "${BOLD}в настоящее время 443 веб-сайта с повторным использованием порта 443 / доменное имя обратного прокси${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "Web 反代引擎：${web_label} (${web_engine}) -> $(web_proxy_backend)" "Web reverse proxy engine: ${web_label} (${web_engine}) -> $(web_proxy_backend)" "механизм веб-прокси: ${web_label} (${web_engine}) -> $(web_proxy_backend)")"
    echo -e "$(localized_text "面板域名：${PANEL_DOMAIN} -> ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "Panel domain: ${PANEL_DOMAIN} -> ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}" "Доменное имя панели: ${PANEL_DOMAIN} -> ${PANEL_LISTEN_ADDR}:${PANEL_LISTEN_PORT}")"
    local panel_ranges
    panel_ranges=$(sni_ip_whitelist_ranges_for_domain "$PANEL_DOMAIN")
    [[ -n "$panel_ranges" ]] && echo -e "$(localized_text "${YELLOW}面板域名 IP 白名单：${panel_ranges}${PLAIN}" "${YELLOW}Panel domain IP whitelist: ${panel_ranges}${PLAIN}" "${YELLOW}Белый список IP-адресов доменного имени панели : ${panel_ranges}${PLAIN}")"
    echo -e "REALITY SNI：${REALITY_SNI} -> ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}"
    [[ ${#TCP_ROUTE_SNIS[@]} -gt 0 ]] && echo -e "$(localized_text "${CYAN}另有 ${#TCP_ROUTE_SNIS[@]} 个旧 TCP/SNI 入站。${PLAIN}" "${CYAN}And ${#TCP_ROUTE_SNIS[@]} are old and TCP/SNI are inbound.${PLAIN}" "${CYAN}и ${#TCP_ROUTE_SNIS[@]} — старые, а TCP/SNI — входящие.${PLAIN}")"
        [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -gt 0 ]] && echo -e "$(localized_text "${CYAN}另有 ${#XRAY_SNI_ROUTE_SNIS[@]} 个 Xray 入站，请在 [19] -> [15] 查看。${PLAIN}" "${CYAN}And ${#XRAY_SNI_ROUTE_SNIS[@]} Xray are inbound, please check at [19] -> [15].${PLAIN}" "${CYAN}и ${#XRAY_SNI_ROUTE_SNIS[@]} Xray входящие, проверьте [19] -> [15].${PLAIN}")"
    echo -e "------------------------------------------------"
    if [[ ${#SITE_DOMAINS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有额外的网站/反代域名。${PLAIN}" "${YELLOW}Currently has no additional website/reverse domains.${PLAIN}" "${YELLOW}в настоящее время не имеет дополнительных веб-сайтов или обратных доменных имен.${PLAIN}")"
        return 0
    fi

    local i num
    for i in "${!SITE_DOMAINS[@]}"; do
        num=$((i + 1))
        echo -e "${GREEN}${num}.${PLAIN} https://${SITE_DOMAINS[$i]}/ -> ${SITE_BACKEND_ADDRS[$i]}:${SITE_BACKEND_PORTS[$i]}"
        local site_ranges
        site_ranges=$(sni_ip_whitelist_ranges_for_domain "${SITE_DOMAINS[$i]}")
        [[ -n "$site_ranges" ]] && echo -e "$(localized_text "   ${YELLOW}IP 白名单：${site_ranges}${PLAIN}" "${YELLOW}IP whitelist: ${site_ranges}${PLAIN}" "Белый список ${YELLOW}IP: ${site_ranges}${PLAIN}")"
    done
}

add_sni_stack_site() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}添加 443 网站/反代域名${PLAIN}" "${BOLD}Added 443 websites/reverse domain${PLAIN}" "${BOLD}добавил 443 веб-сайта/обратное доменное имя${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1

    local cf_env_file="/root/.config/vps-panel/cloudflare.env"
    if [[ ! -f "$cf_env_file" ]]; then
        echo -e "$(localized_text "${RED}❌ 未找到 Cloudflare Token，请先进入维护菜单 [2] 写入 Token。${PLAIN}" "${RED}❌ Cloudflare Token was not found. Please enter the maintenance menu [2] to write the Token first.${PLAIN}" "${RED}❌ Cloudflare Токен не найден. Пожалуйста, войдите в меню обслуживания [2], чтобы сначала записать токен.${PLAIN}")"
        return 1
    fi
    # shellcheck disable=SC1090
    source "$cf_env_file"
    if [[ -z "${CF_Token:-}" ]]; then
        echo -e "$(localized_text "${RED}❌ Cloudflare Token 为空，请先进入维护菜单 [2] 更新。${PLAIN}" "${RED}❌ Cloudflare Token is empty, please enter the maintenance menu [2] to update first.${PLAIN}" "${RED}❌ Cloudflare Токен пуст, войдите в меню обслуживания [2] для обновления.${PLAIN}")"
        return 1
    fi

    echo -e "$(localized_text "这个入口适合后续新增网站，例如 SublinkPro、Dockge、博客、订阅管理工具等。" "This entry Suitable for subsequent new websites, such as SublinkPro, Dockge, blogs, subscription management tools, etc." "Этот вход подходит для последующих новых веб-сайтов, таких как SublinkPro, Dockge, блогов, инструментов управления подписками и т. д.")"
    local web_engine web_label
    web_engine=$(current_web_proxy_engine)
    web_label=$(web_proxy_engine_label "$web_engine")
    echo -e "$(localized_text "${YELLOW}新增域名会走：公网 ${NGINX_LISTEN_PORT} -> 443 入口分流 -> ${web_label} -> 本地后端。${PLAIN}" "${YELLOW}The new domain will go to: public ${NGINX_LISTEN_PORT} -> 443 entry routing -> ${web_label} -> local backend.${PLAIN}" "${YELLOW}Новое доменное имя будет передано в: публичную сеть ${NGINX_LISTEN_PORT} -> маршрутизация входа 443 -> ${web_label} -> локальный сервер.${PLAIN}")"
    echo -e ""

    local site_domain site_domain_input site_addr site_port advanced_mode existing idx confirm
    local enable_ip_whitelist whitelist_input whitelist_ranges current_client_ip
    local -a whitelist_array=()
    read_trimmed site_domain_input "$(localized_text "请输入新网站/反代域名（例如 sub.example.com）: " "Please enter your new website/reverse domain (e.g. sub.example.com):" "Введите имя вашего нового веб-сайта/обратного домена (например, sub.example.com):")"
    site_domain=$(normalize_domain_input "$site_domain_input")
    if [[ -z "$site_domain" || "$site_domain" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消新增网站/反代域名。${PLAIN}" "${BLUE}Canceled the new website/reverse domain.${PLAIN}" "${BLUE}отменил новый веб-сайт/обратное доменное имя.${PLAIN}")"
        return 0
    fi

    if ! is_valid_domain "$site_domain"; then
        print_domain_validation_error "$(localized_text "域名" "domain" "доменное имя")" "$site_domain_input" "$site_domain"
        return 1
    fi
    if [[ "$site_domain" == "$PANEL_DOMAIN" || "$site_domain" == "$REALITY_SNI" ]]; then
        echo -e "$(localized_text "${RED}❌ 新域名不能和面板域名或 REALITY SNI 相同。${PLAIN}" "${RED}❌ The new domain cannot be the same as the panel domain or REALITY SNI.${PLAIN}" "${RED}❌ Новое доменное имя не может совпадать с именем домена панели или REALITY SNI.${PLAIN}")"
        return 1
    fi
    for existing in "${SITE_DOMAINS[@]}"; do
        if [[ "$site_domain" == "$existing" ]]; then
            echo -e "$(localized_text "${RED}❌ 该域名已经在 443 分流列表中。${PLAIN}" "${RED}❌ This domain is already in the 443 routing list.${PLAIN}" "${RED}❌ Это доменное имя уже находится в списке маршрутизация 443.${PLAIN}")"
            return 1
        fi
    done
    for existing in "${TCP_ROUTE_SNIS[@]}"; do
        if [[ "$site_domain" == "$existing" ]]; then
            echo -e "$(localized_text "${RED}❌ 该域名已经作为 TCP/SNI 入站使用。${PLAIN}" "${RED}❌ This domain has been used inbound as TCP/SNI.${PLAIN}" "${RED}❌ Это доменное имя использовалось в качестве TCP/SNI.${PLAIN}")"
            return 1
        fi
    done
    for existing in "${XRAY_SNI_ROUTE_SNIS[@]}"; do
        if [[ "$site_domain" == "$existing" ]]; then
            echo -e "$(localized_text "${RED}❌ 该域名已经作为 Xray 入站使用。${PLAIN}" "${RED}❌ This domain has been used inbound as Xray.${PLAIN}" "${RED}❌ Это доменное имя использовалось в качестве Xray.${PLAIN}")"
            return 1
        fi
    done

    read_trimmed advanced_mode "$(localized_text "后端是否使用自定义地址？(Y/n，默认 y): " "Does the backend use custom addresses? (Y/n, default y):" "Использует ли бэкенд собственные адреса? (Да/нет, по умолчанию y):")"
    if is_yes "$advanced_mode"; then
        site_addr=$(ask_with_default "$(localized_text "后端地址" "Backend address" "Внутренний адрес")" "127.0.0.1")
    else
        site_addr="127.0.0.1"
        echo -e "$(localized_text "${GREEN}后端地址使用 127.0.0.1。${PLAIN}" "${GREEN}Backend address uses 127.0.0.1.${PLAIN}" "${GREEN}Внутренний адрес использует 127.0.0.1.${PLAIN}")"
    fi
    site_addr=$(normalize_backend_addr_input "$site_addr")
    site_port=$(ask_with_default "$(localized_text "后端端口" "backend port" "внутренний порт")" "$((3000 + ${#SITE_DOMAINS[@]}))")

    is_valid_backend_addr "$site_addr" || { echo -e "$(localized_text "${RED}❌ 后端地址无效：${site_addr}${PLAIN}" "${RED}❌ Invalid backend address: ${site_addr}${PLAIN}" "${RED}❌ Неверный внутренний адрес: ${site_addr}.${PLAIN}")"; return 1; }
    is_valid_port "$site_port" || { echo -e "$(localized_text "${RED}❌ 后端端口无效：${site_port}${PLAIN}" "${RED}❌ Invalid backend port: ${site_port}${PLAIN}" "${RED}❌ Неверный внутренний порт: ${site_port}.${PLAIN}")"; return 1; }
    warn_if_public_bind "$(localized_text "网站/反代后端 ${site_domain}" "Website/reverse proxy backend ${site_domain}" "Веб-сайт/бэкенд обратного прокси ${site_domain}")" "$site_addr" "$site_port" || return 1
    confirm_backend_target_or_continue "$(localized_text "网站/反代后端 ${site_domain}" "Website/reverse proxy backend ${site_domain}" "Сайт/бэкенд обратного прокси ${site_domain}")" "$site_addr" "$site_port" || return 1

    if web_proxy_engine_supports_web_whitelist "${ENTRY_MODE:-$(get_entry_mode)}" "$web_engine"; then
        read_trimmed enable_ip_whitelist "$(localized_text "是否为 ${site_domain} 启用 IP 白名单？(y/N，默认 N): " "Enable an IP allowlist for ${site_domain}? (y/N, default N): " "Включить список разрешённых IP-адресов для ${site_domain}? (y/N, по умолчанию N): ")"
    else
        echo -e "$(localized_text "${YELLOW}xray-fallback 无法让本地 Web 反代引擎可靠获取真实客户端源 IP，本次禁止为新域名启用 Web 白名单。${PLAIN}" "${YELLOW}Xray-fallback cannot allow the local web reverse proxy engine to reliably obtain the real client source IP. This time, it is prohibited to enable the web whitelist for new domains.${PLAIN}" "${YELLOW}xray-резервный вариант не может позволить локальному механизму веб-прокси надежно получить реальный исходный IP-адрес клиента. На этот раз запрещено включать белый список веб-сайтов для новых доменных имен.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}如需 Web 白名单，请改用 Nginx Stream/TCP Peek 入口模式。${PLAIN}" "${YELLOW}If you need Web whitelist, please use Nginx Stream/TCP Peek entry mode instead.${PLAIN}" "${YELLOW}Если вам нужен белый список веб-страниц, используйте вместо этого режим входа Nginx Stream/TCP Peek.${PLAIN}")"
        enable_ip_whitelist="n"
    fi
    if is_yes "$enable_ip_whitelist"; then
        current_client_ip=$(detect_ssh_client_ip)
        [[ -n "$current_client_ip" ]] && echo -e "$(localized_text "${YELLOW}当前 SSH 来源 IP 可能是：${current_client_ip}，请确认已加入白名单。${PLAIN}" "${YELLOW}The current source IP of SSH may be: ${current_client_ip}. Please confirm that it has been added to the whitelist.${PLAIN}" "${YELLOW}Текущий исходный IP-адрес SSH может быть: ${current_client_ip}. Пожалуйста, подтвердите, что он был добавлен в белый список.${PLAIN}")"
        read_trimmed whitelist_input "$(localized_text "请输入允许访问 ${site_domain} 的 IP/CIDR（多个用空格或英文逗号分隔）: " "Please enter the IP/CIDR that allows access to ${site_domain} (separate multiple by spaces or commas):" "Введите IP/CIDR, который разрешает доступ к ${site_domain} (разделяйте кратные пробелами или запятыми):")"
        normalize_ip_whitelist_input "$whitelist_input" whitelist_array || return 1
        append_vps_public_ips_to_whitelist whitelist_array
        whitelist_ranges=$(join_array_by_space "${whitelist_array[@]}")
    fi

    echo -e ""
    echo -e "$(localized_text "${CYAN}即将添加：${site_domain} -> ${site_addr}:${site_port}${PLAIN}" "${CYAN}Will be added soon: ${site_domain} -> ${site_addr}:${site_port}${PLAIN}" "${CYAN}скоро будет добавлен: ${site_domain} -> ${site_addr}:${site_port}${PLAIN}")"
    [[ -n "${whitelist_ranges:-}" ]] && echo -e "$(localized_text "${YELLOW}IP 白名单：${whitelist_ranges}${PLAIN}" "${YELLOW}IP whitelist: ${whitelist_ranges}${PLAIN}" "${YELLOW}Белый список IP: ${whitelist_ranges}${PLAIN}")"
    confirm_risk_action "$(localized_text "新增 443 网站/反代域名 ${site_domain}" "Added 443 websites/reverse domain ${site_domain}" "Добавлено 443 веб-сайта/обратное доменное имя ${site_domain}.")" \
        "$(localized_text "证书、Web 反代引擎配置和 443 入口分流配置" "Certificate, Web reverse proxy engine configuration and 443 entry routing configuration" "Сертификат, конфигурация механизма веб-прокси и конфигурация перенаправления входа 443.")" \
        "$(localized_text "使用 443端口复用备份恢复，或从网站管理菜单删除该域名" "Use the Port 443 Reuse backup and restore, or delete the domain from the website management menu" "Используйте резервную копию повторного использования порта 443 для восстановления или удаления домена из меню управления веб-сайтом.")" \
        "$(localized_text "确认域名已解析到当前 VPS，后端端口可从本机访问。" "Confirm that the domain has been resolved to the current VPS and the backend port can be accessed from this machine." "Убедитесь, что доменное имя было преобразовано в текущий VPS и доступ к внутреннему порту возможен с этого компьютера.")" || return 1

    idx=${#SITE_DOMAINS[@]}
    SITE_DOMAINS[$idx]="$site_domain"
    SITE_BACKEND_ADDRS[$idx]="$site_addr"
    SITE_BACKEND_PORTS[$idx]="$site_port"
    [[ -n "${whitelist_ranges:-}" ]] && set_sni_ip_whitelist_for_domain "$site_domain" "$whitelist_ranges"

    issue_and_install_cert_for_domain "$site_domain" "$CF_Token" || return 1
    apply_sni_stack_runtime_config || return 1
    echo -e "$(localized_text "${GREEN}✅ 已添加网站入口：https://${site_domain}/${PLAIN}" "${GREEN}✅ Website entry has been added: https://${site_domain}/${PLAIN}" "${GREEN}✅ Добавлен вход на сайт: https://${site_domain}/${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}提醒：当前 VPS 必须能访问 ${site_addr}:${site_port}，浏览器只访问 https://${site_domain}/。${PLAIN}" "${YELLOW}Reminder: The current VPS must be able to access ${site_addr}:${site_port}, and the browser can only access https://${site_domain}/。${PLAIN}" "${YELLOW}Напоминание : текущий VPS должен иметь доступ к ${site_addr}:${site_port}, а браузер может получить доступ только к https://${site_domain}/。.${PLAIN}")"
    echo -e "$(localized_text "${CYAN}当前 Web 反代后端：${web_label} -> ${site_addr}:${site_port}${PLAIN}" "${CYAN}Current Web reverse proxy backend: ${web_label} -> ${site_addr}:${site_port}${PLAIN}" "${CYAN}Текущий сервер веб-прокси: ${web_label} -> ${site_addr}:${site_port}${PLAIN}")"
}

edit_sni_stack_site_backend() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}修改 443 网站/反代后端${PLAIN}" "${BOLD}Modified 443 website/reverse backend${PLAIN}" "${BOLD}модифицированный веб-сайт 443/обратный сервер${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1

    if [[ ${#SITE_DOMAINS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有可修改的网站/反代域名。${PLAIN}" "${YELLOW}Currently there is no website/reverse domain that can be modified.${PLAIN}" "${YELLOW}В настоящее время не существует веб-сайта/обратного доменного имени, которое можно было бы изменить.${PLAIN}")"
        return 0
    fi

    local i num choice idx domain new_addr new_port confirm
    for i in "${!SITE_DOMAINS[@]}"; do
        num=$((i + 1))
        echo -e "${GREEN}${num}.${PLAIN} ${SITE_DOMAINS[$i]} -> ${SITE_BACKEND_ADDRS[$i]}:${SITE_BACKEND_PORTS[$i]}"
    done
    echo -e "------------------------------------------------"
    read_trimmed choice "$(localized_text "请输入要修改的序号: " "Please enter the serial number to be modified:" "Пожалуйста, введите серийный номер, который необходимо изменить:")"
    if [[ -z "$choice" || "$choice" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消修改。${PLAIN}" "${BLUE}Edit canceled.${PLAIN}" "${BLUE}Изменение отменено.${PLAIN}")"
        return 0
    fi
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#SITE_DOMAINS[@]} )); then
        echo -e "$(localized_text "${RED}❌ 序号无效。${PLAIN}" "${RED}❌ The serial number is invalid.${PLAIN}" "${RED}❌ Серийный номер недействителен.${PLAIN}")"
        return 1
    fi

    idx=$((choice - 1))
    domain="${SITE_DOMAINS[$idx]}"
    new_addr=$(ask_with_default "$(localized_text "后端地址" "Backend address" "Внутренний адрес")" "${SITE_BACKEND_ADDRS[$idx]}")
    new_addr=$(normalize_backend_addr_input "$new_addr")
    new_port=$(ask_with_default "$(localized_text "后端端口" "backend port" "внутренний порт")" "${SITE_BACKEND_PORTS[$idx]}")

    is_valid_backend_addr "$new_addr" || { echo -e "$(localized_text "${RED}❌ 后端地址无效：${new_addr}${PLAIN}" "${RED}❌ Invalid backend address: ${new_addr}${PLAIN}" "${RED}❌ Неверный внутренний адрес: ${new_addr}.${PLAIN}")"; return 1; }
    is_valid_port "$new_port" || { echo -e "$(localized_text "${RED}❌ 后端端口无效：${new_port}${PLAIN}" "${RED}❌ Invalid backend port: ${new_port}${PLAIN}" "${RED}❌ Неверный внутренний порт: ${new_port}.${PLAIN}")"; return 1; }
    warn_if_public_bind "$(localized_text "网站/反代后端 ${domain}" "Website/reverse proxy backend ${domain}" "Веб-сайт/бэкенд обратного прокси ${domain}")" "$new_addr" "$new_port" || return 1
    confirm_backend_target_or_continue "$(localized_text "网站/反代后端 ${domain}" "Website/reverse proxy backend ${domain}" "Сайт/бэкенд обратного прокси ${domain}")" "$new_addr" "$new_port" || return 1

    echo -e ""
    echo -e "$(localized_text "${CYAN}即将修改：${domain} -> ${new_addr}:${new_port}${PLAIN}" "${CYAN}The following will be changed: ${domain} -> ${new_addr}:${new_port}${PLAIN}" "${CYAN}скоро будет изменен: ${domain} -> ${new_addr}:${new_port}${PLAIN}")"
    confirm_risk_action "$(localized_text "修改 443 网站/反代后端" "Modify 443 website/reverse proxy backend" "Изменить веб-сайт 443 / бэкенд обратный прокси")" \
        "$(localized_text "Web 反代引擎后端和 443 入口分流配置" "Web reverse proxy engine backend and 443 entry routing configuration" "бэкенд механизма веб-прокси и конфигурация перенаправления входа 443")" \
        "$(localized_text "使用 443端口复用备份恢复修改前配置" "Use Port 443 Reuse backup to restore the configuration before modification" "Используйте резервную копию повторного использования порта 443 для восстановления конфигурации до изменения.")" \
        "$(localized_text "确认当前 VPS 能访问新的后端地址和端口。" "Confirm that the current VPS can access the new backend address and port." "Убедитесь, что текущий VPS может получить доступ к новому внутреннему адресу и порту.")" || return 1

    SITE_BACKEND_ADDRS[$idx]="$new_addr"
    SITE_BACKEND_PORTS[$idx]="$new_port"
    apply_sni_stack_runtime_config || return 1
    echo -e "$(localized_text "${GREEN}✅ 已更新网站后端：https://${domain}/ -> ${new_addr}:${new_port}${PLAIN}" "${GREEN}✅ Updated website backend: https://${domain}/ -> ${new_addr}:${new_port}${PLAIN}" "${GREEN}✅ Обновлена бэкенд сайта: https://${domain}/ -> ${new_addr}:${new_port}${PLAIN}")"
    echo -e "$(localized_text "${CYAN}当前 Web 反代后端：$(web_proxy_engine_label) -> ${new_addr}:${new_port}${PLAIN}" "${CYAN}Current Web reverse proxy backend: $(web_proxy_engine_label) -> ${new_addr}:${new_port}${PLAIN}" "${CYAN}Текущий сервер веб-прокси: $(web_proxy_engine_label) -> ${new_addr}:${new_port}${PLAIN}")"
}

remove_sni_stack_site() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}删除 443 网站/反代域名${PLAIN}" "${BOLD}Deleted 443 websites/reverse domain${PLAIN}" "${BOLD}удалил 443 веб-сайта/обратное доменное имя${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1

    if [[ ${#SITE_DOMAINS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有可删除的网站/反代域名。${PLAIN}" "${YELLOW}Currently there is no website/reverse domain that can be deleted.${PLAIN}" "${YELLOW}В настоящее время не существует веб-сайта/обратного доменного имени, которое можно было бы удалить.${PLAIN}")"
        return 0
    fi

    local i num choice idx domain confirm delete_cert new_domains new_addrs new_ports
    for i in "${!SITE_DOMAINS[@]}"; do
        num=$((i + 1))
        echo -e "${GREEN}${num}.${PLAIN} ${SITE_DOMAINS[$i]} -> ${SITE_BACKEND_ADDRS[$i]}:${SITE_BACKEND_PORTS[$i]}"
    done
    echo -e "------------------------------------------------"
    read_trimmed choice "$(localized_text "请输入要删除的序号: " "Please enter the serial number to be deleted:" "Пожалуйста, введите серийный номер, который необходимо удалить:")"
    if [[ -z "$choice" || "$choice" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消删除。${PLAIN}" "${BLUE}Removal canceled.${PLAIN}" "${BLUE}Удаление отменено.${PLAIN}")"
        return 0
    fi
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#SITE_DOMAINS[@]} )); then
        echo -e "$(localized_text "${RED}❌ 序号无效。${PLAIN}" "${RED}❌ The serial number is invalid.${PLAIN}" "${RED}❌ Серийный номер недействителен.${PLAIN}")"
        return 1
    fi

    idx=$((choice - 1))
    domain="${SITE_DOMAINS[$idx]}"
    confirm_risk_action "$(localized_text "从 443 分流中移除 ${domain}" "Remove ${domain} from 443 routing" "Снимите ${domain} с маршрутизации 443.")" \
        "$(localized_text "该域名的 Web 反代引擎配置和 443 入口分流规则" "Web reverse proxy engine configuration and 443 entry routing rules for this domain" "Конфигурация механизма веб-прокси и правила перенаправления входа 443 для этого доменного имени.")" \
        "$(localized_text "使用 443端口复用备份恢复，或重新新增该网站/反代域名" "Use Port 443 Reuse backup and restore, or re-add the website/reverse proxy domain" "Используйте резервное копирование и восстановление повторного использования порта 443 или повторно добавьте доменное имя веб-сайта/обратного прокси-сервера.")" \
        "$(localized_text "确认该域名不再承载线上面板、订阅或网站。" "Confirm that the domain no longer hosts the online panel, subscription, or website." "Убедитесь, что в домене больше нет онлайн-панели, подписки или веб-сайта.")" || return 1

    new_domains=()
    new_addrs=()
    new_ports=()
    for i in "${!SITE_DOMAINS[@]}"; do
        [[ "$i" -eq "$idx" ]] && continue
        new_domains+=("${SITE_DOMAINS[$i]}")
        new_addrs+=("${SITE_BACKEND_ADDRS[$i]}")
        new_ports+=("${SITE_BACKEND_PORTS[$i]}")
    done
    SITE_DOMAINS=("${new_domains[@]}")
    SITE_BACKEND_ADDRS=("${new_addrs[@]}")
    SITE_BACKEND_PORTS=("${new_ports[@]}")
    remove_sni_ip_whitelist_for_domain "$domain"
    quarantine_path "/etc/caddy/conf.d/${domain}.caddy" "/etc/vps-optimize/quarantine/caddy-sni" >/dev/null 2>&1 || true

    apply_sni_stack_runtime_config || return 1

    read_trimmed delete_cert "$(localized_text "是否同时隔离 ${domain} 的 Caddy 证书文件？(y/N，默认 N): " "Also quarantine the Caddy certificate files for ${domain}? (y/N, default N): " "Также поместить файлы сертификата Caddy для ${domain} в карантин? (y/N, по умолчанию N): ")"
    if is_yes "$delete_cert"; then
        quarantine_path "/etc/caddy/certs/${domain}.crt" "/etc/vps-optimize/quarantine/caddy-certs" >/dev/null 2>&1 || true
        quarantine_path "/etc/caddy/certs/${domain}.key" "/etc/vps-optimize/quarantine/caddy-certs" >/dev/null 2>&1 || true
        quarantine_path "/root/cert/${domain}.crt" "/etc/vps-optimize/quarantine/caddy-certs" >/dev/null 2>&1 || true
        quarantine_path "/root/cert/${domain}.key" "/etc/vps-optimize/quarantine/caddy-certs" >/dev/null 2>&1 || true
        generate_caddy_cf_manifest
        echo -e "$(localized_text "${GREEN}✅ 已移除 ${domain} 的配置，并隔离本地证书文件。${PLAIN}" "${GREEN}✅ The configuration of ${domain} has been removed and the local certificate file has been isolated.${PLAIN}" "${GREEN}. Конфигурация ${domain} удалена, а локальный файл сертификата изолирован.${PLAIN}")"
    else
        echo -e "$(localized_text "${GREEN}✅ 已删除 ${domain} 的分流配置，证书文件已保留。${PLAIN}" "${GREEN}✅ The offload configuration of ${domain} has been deleted and the certificate file has been retained.${PLAIN}" "${GREEN}. Конфигурация разгрузки ${domain} была удалена, а файл сертификата сохранен.${PLAIN}")"
    fi
}

switch_sni_stack_web_proxy_engine() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}切换 443 Web 反代引擎${PLAIN}" "${BOLD}Switch 443 Web reverse proxy engine${PLAIN}" "${BOLD}переключатель 443 Механизм обратного веб-прокси${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1

    local current_engine current_label choice new_engine new_label entry_mode
    current_engine=$(current_web_proxy_engine)
    current_label=$(web_proxy_engine_label "$current_engine")
    entry_mode="${ENTRY_MODE:-$(get_entry_mode)}"

    echo -e "$(localized_text "当前入口模式：${entry_mode}" "Current entry mode: ${entry_mode}" "Текущий режим ввода: ${entry_mode}.")"
    echo -e "$(localized_text "当前 Web 反代引擎：${current_label} (${current_engine})" "Current web reverse proxy engine: ${current_label} (${current_engine})" "Текущий движок веб-прокси: ${current_label} (${current_engine})")"
    echo -e "$(localized_text "本地 TLS 后端：$(web_proxy_backend)" "Local TLS Backend: $(web_proxy_backend)" "Локальный сервер TLS: $(web_proxy_backend)")"
    echo -e "$(localized_text "读取来源：/etc/vps-optimize/sni-stack.env（脚本保存的 443 共享配置）" "Read source: /etc/vps-optimize/sni-stack.env（脚本保存的 Port 443 Reuse configuration)" "Источник чтения: общая конфигурация /etc/vps-optimize/sni-stack.env（脚本保存的 443)")"
    echo -e "$(localized_text "${YELLOW}切换时会按当前域名、证书、后端和白名单重新渲染所选引擎，并隔离另一套 443 本地 Web 反代配置。${PLAIN}" "${YELLOW}When switching, the selected engine will be re-rendered according to the current domain, certificate, backend and whitelist, and another set of 443 local web reverse proxy configuration will be isolated.${PLAIN}" "${YELLOW}При переключении выбранный движок будет перерисован в соответствии с текущим именем домена, сертификатом, бэкенд и белым списком, а другой набор из 443 локальных конфигураций веб-прокси будет изолирован.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}如果你手工改过 Caddy/Nginx 文件但没有通过本菜单保存，请先在 [8]/[10] 同步脚本保存值后再切换。${PLAIN}" "${YELLOW}If you manually modified the Caddy/Nginx file but did not save it through this menu, please save the value in the [8]/[10] synchronization script before switching.${PLAIN}" "${YELLOW}Если вы вручную изменили файл Caddy/Nginx, но не сохранили его через это меню, сохраните значение в сценарии синхронизации [8]/[10] перед переключением.${PLAIN}")"
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${GREEN}  1. Caddy 本地 HTTPS 反代${PLAIN}" "${GREEN}1. Caddy local HTTPS reverse proxy${PLAIN}" "${GREEN}1. Caddy локальный HTTPS обратный прокси${PLAIN}")"
    echo -e "$(localized_text "${GREEN}  2. Nginx 本地 HTTPS 反代${PLAIN}" "${GREEN}2. Nginx local HTTPS reverse proxy${PLAIN}" "${GREEN}2. Nginx локальный HTTPS обратный прокси${PLAIN}")"
    echo -e "$(localized_text "${RED}  0. 取消${PLAIN}" "${RED}0. Cancel${PLAIN}" "${RED}0. Отмена${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    read_trimmed choice "$(localized_text "请选择 Web 反代引擎（默认保持当前）: " "Please select a web inversion engine (default remains current):" "Пожалуйста, выберите механизм веб-инверсии (по умолчанию остается текущим):")"
    case "$choice" in
        ""|0|q|Q)
            echo -e "$(localized_text "${BLUE}已取消切换 Web 反代引擎。${PLAIN}" "${BLUE}Canceled the switching of the web reverse proxy engine.${PLAIN}" "${BLUE}отменил включение механизма обратный прокси сети.${PLAIN}")"
            return 0
            ;;
        1) new_engine="caddy" ;;
        2) new_engine="nginx" ;;
        *)
            echo -e "$(localized_text "${RED}❌ 无效的 Web 反代引擎选择。${PLAIN}" "${RED}❌ Invalid web reverse proxy engine selection.${PLAIN}" "${RED}❌ Неверный выбор механизма веб-прокси.${PLAIN}")"
            return 1
            ;;
    esac

    new_label=$(web_proxy_engine_label "$new_engine")
    if [[ "$new_engine" == "$current_engine" ]]; then
        echo -e "$(localized_text "${BLUE}Web 反代引擎未变化，仍为 ${current_label}。${PLAIN}" "${BLUE}The Web reverse proxy engine has not changed and is still ${current_label}.${PLAIN}" "${BLUE}Механизм обратный прокси Web не изменился и остается ${current_label}.${PLAIN}")"
        return 0
    fi

    if [[ ${#SNI_IP_WHITELIST_DOMAINS[@]} -gt 0 ]] && ! web_proxy_engine_supports_web_whitelist "$entry_mode" "$new_engine"; then
        echo -e "$(localized_text "${RED}❌ 不能切换到 ${new_label}：当前为 xray-fallback 且已有 Web 白名单，本地 Web 反代引擎无法可靠获取真实客户端源 IP。${PLAIN}" "${RED}❌ cannot switch to ${new_label}: It is currently xray-fallback and has a web whitelist. The local web reverse proxy engine cannot reliably obtain the real client source IP.${PLAIN}" "${RED}❌ не может переключиться на ${new_label}: в настоящее время это резервный вариант xray и имеется белый список веб-сайтов. Механизм обратный прокси локальной сети не может надежно получить реальный исходный IP-адрес клиента.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}请先清除 Web 白名单，或改用 Nginx Stream/TCP Peek 入口模式后再切换。${PLAIN}" "${YELLOW}Please clear the Web whitelist first, or switch to Nginx Stream/TCP Peek entry mode before switching.${PLAIN}" "${YELLOW}Сначала очистите белый список Интернета или переключитесь в режим входа Nginx Stream/TCP Peek перед переключением.${PLAIN}")"
        return 1
    fi
    if ! web_proxy_engine_supports_web_whitelist "$entry_mode" "$new_engine"; then
        echo -e "$(localized_text "${YELLOW}⚠️ 当前入口模式为 xray-fallback，切换 Web 反代引擎后仍禁止新增 Web 白名单。${PLAIN}" "${YELLOW}⚠️ The current entry mode is xray-fallback. After switching the Web reverse proxy engine, new Web whitelists are still prohibited.${PLAIN}" "${YELLOW}⚠️ Текущий режим входа — xray-резервный. После переключения механизма обратный прокси Интернета новые белые списки Интернета по-прежнему запрещены.${PLAIN}")"
    fi

    confirm_risk_action "$(localized_text "切换 443 Web 反代引擎为 ${new_label}" "Switch the 443 Web reverse proxy engine to ${new_label}" "Переключите механизм обратный прокси 443 Web на ${new_label}.")" \
        "$(localized_text "重新生成 ${new_label} 配置，并隔离旧的 443 本地 Web 反代配置；公网 443 入口模式保持 ${entry_mode}" "Regenerate the ${new_label} configuration and isolate the old 443 local Web reverse proxy configuration; the public port 443 entry mode remains ${entry_mode}" "Восстановите конфигурацию ${new_label} и изолируйте старую локальную конфигурацию обратный прокси веб-страницы 443; режим входа в публичную сеть 443 остается ${entry_mode}")" \
        "$(localized_text "使用 443端口复用备份恢复，或切回 ${current_label} 后重新应用" "Use Port 443 Reuse backup and restore, or switch back to ${current_label} and reapply" "Используйте резервное копирование и восстановление повторного использования порта 443 или вернитесь к ${current_label} и повторите заявку.")" \
        "$(localized_text "确认本机 ${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT} 未被其他服务占用，且证书文件仍在 /etc/caddy/certs/。" "Confirm that the local machine ${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT} is not occupied by other services, and the certificate file is still in /etc/caddy/certs/." "Убедитесь, что локальный компьютер ${CADDY_LISTEN_ADDR}:${CADDY_LISTEN_PORT} не занят другими службами и файл сертификата все еще находится в /etc/caddy/certs/.")" || return 1

    WEB_PROXY_ENGINE="$new_engine"
    save_and_offer_reapply_sni_stack
}

list_sni_stack_tcp_routes() {
    load_sni_stack_env || return 1
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}当前 443 TCP/SNI 本地入站分流${PLAIN}" "${BOLD}Current 443 TCP/SNI local inbound offload${PLAIN}" "${BOLD}текущий 443 TCP/SNI локальная входящая разгрузка${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "公网入口：${NGINX_LISTEN_ADDR}:${NGINX_LISTEN_PORT}" "public entry: ${NGINX_LISTEN_ADDR}:${NGINX_LISTEN_PORT}" "Вход в публичную сеть: ${NGINX_LISTEN_ADDR}:${NGINX_LISTEN_PORT}.")"
    echo -e "$(localized_text "REALITY 默认后端：${REALITY_SNI} -> ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}" "REALITY Default backend: ${REALITY_SNI} -> ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}" "REALITY бэкенд по умолчанию: ${REALITY_SNI} -> ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}")"
    echo -e "------------------------------------------------"
    if [[ ${#TCP_ROUTE_SNIS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有额外 TCP/SNI 入站分流。${PLAIN}" "${YELLOW}Currently has no additional TCP/SNI inbound offload.${PLAIN}" "${YELLOW}в настоящее время не имеет дополнительной входящей разгрузки TCP/SNI.${PLAIN}")"
        return 0
    fi

    local i num
    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        num=$((i + 1))
        echo -e "${GREEN}${num}.${PLAIN} ${TCP_ROUTE_SNIS[$i]}:${NGINX_LISTEN_PORT} -> ${TCP_ROUTE_ADDRS[$i]}:${TCP_ROUTE_PORTS[$i]}"
    done
}

add_sni_stack_tcp_route() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}新增 443 TCP/SNI 本地入站分流${PLAIN}" "${BOLD}Added 443 TCP/SNI local inbound offload${PLAIN}" "${BOLD}добавлено 443 TCP/SNI локальная входящая разгрузка${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    echo -e "$(localized_text "${YELLOW}用途：你已在 3x-ui 新增本地入站，本功能只把某个 SNI 通过公网 ${NGINX_LISTEN_PORT} 分流到该本地端口。${PLAIN}" "${YELLOW}Purpose: You have added a local inbound port in 3x-ui. This function only distributes a certain SNI to the local port through the public ${NGINX_LISTEN_PORT}.${PLAIN}" "${YELLOW}Назначение: вы добавили локальное входящее соединение в 3x-ui. Эта функция направляет только определенный SNI на локальный порт через Интернет ${NGINX_LISTEN_PORT}.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}要求：协议必须是 TCP 且客户端握手能带 SNI；UDP/QUIC/Hysteria2/TUIC 或无 SNI 的裸协议不适用。${PLAIN}" "${YELLOW}Requirements: The protocol must be TCP and the client handshake can carry SNI; UDP/QUIC/Hysteria2/TUIC or bare protocols without SNI are not applicable.${PLAIN}" "${YELLOW}Требования : протокол должен быть TCP, а подтверждение связи клиента может передавать SNI; UDP/QUIC/Hysteria2/TUIC или простые протоколы без SNI неприменимы.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}安全边界：后端只允许 127.0.0.1/localhost/::1，不会开放新公网端口。${PLAIN}" "${YELLOW}Security boundary: The backend only allows 127.0.0.1/localhost/::1 and will not open new public ports.${PLAIN}" "${YELLOW}Граница безопасности : бэкенд разрешает только 127.0.0.1/localhost/::1 и не открывает новые порты публичной сети.${PLAIN}")"
    echo -e "------------------------------------------------"

    local route_sni route_sni_input route_addr route_port existing idx
    read_trimmed route_sni_input "$(localized_text "请输入用于分流的新 SNI/域名（例如 relay.example.com）: " "Please enter the new SNI/domain to be used for offloading (e.g. relay.example.com):" "Введите новое SNI/имя домена, которое будет использоваться для разгрузки (например, relay.example.com):")"
    route_sni=$(normalize_domain_input "$route_sni_input")
    if [[ -z "$route_sni" || "$route_sni" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消新增 TCP/SNI 入站。${PLAIN}" "${BLUE}Canceled the addition of TCP/SNI.${PLAIN}" "${BLUE}отменил добавление TCP/SNI.${PLAIN}")"
        return 0
    fi
    is_valid_domain "$route_sni" || { print_domain_validation_error "$(localized_text "SNI/域名" "SNI/domain" "SNI/доменное имя")" "$route_sni_input" "$route_sni"; return 1; }
    if [[ "$route_sni" == "$PANEL_DOMAIN" || "$route_sni" == "$REALITY_SNI" ]]; then
        echo -e "$(localized_text "${RED}❌ TCP/SNI 入站域名不能和面板域名或 REALITY SNI 相同。${PLAIN}" "${RED}❌ The TCP/SNI inbound domain cannot be the same as the panel domain or REALITY SNI.${PLAIN}" "${RED}❌ Имя входящего домена TCP/SNI не может совпадать с именем домена панели или REALITY SNI.${PLAIN}")"
        return 1
    fi
    for existing in "${SITE_DOMAINS[@]}"; do
        [[ "$route_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该域名已作为网站/反代域名使用。${PLAIN}" "${RED}❌ This domain has been used as a website/reverse proxy domain.${PLAIN}" "${RED}❌ Это доменное имя использовалось в качестве доменного имени веб-сайта/обратного прокси-сервера.${PLAIN}")"; return 1; }
    done
    for existing in "${TCP_ROUTE_SNIS[@]}"; do
        [[ "$route_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该 TCP/SNI 入站已经存在。${PLAIN}" "${RED}❌ The TCP/SNI inbound already exists.${PLAIN}" "${RED}❌ входящее подключение TCP/SNI уже существует.${PLAIN}")"; return 1; }
    done
    for existing in "${XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$route_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该域名已作为 Xray 入站使用。${PLAIN}" "${RED}❌ This domain has been used inbound as Xray.${PLAIN}" "${RED}❌ Это доменное имя использовалось в качестве Xray.${PLAIN}")"; return 1; }
    done

    check_domain_dns_sanity "$route_sni" "$(localized_text "TCP/SNI 入站域名" "TCP/SNI inbound domain" "TCP/SNI имя входящего домена")" "warn" || echo -e "$(localized_text "${YELLOW}⚠️ 如果客户端使用服务器 IP 连接并手动指定 SNI，可忽略该 DNS 警告。${PLAIN}" "${YELLOW}⚠️ This DNS warning can be ignored if the client connects using the server IP and manually specifies SNI.${PLAIN}" "${YELLOW}⚠️ Это предупреждение DNS можно игнорировать, если клиент подключается с использованием IP-адреса сервера и вручную указывает SNI.${PLAIN}")"
    route_addr=$(ask_with_default "$(localized_text "3x-ui 新入站本地监听地址（只允许本地）" "3x-ui New inbound local listening address (only local)" "3x-ui Новый входящий локальный адрес прослушивания (только локальный)")" "127.0.0.1")
    route_addr=$(normalize_loopback_addr "$route_addr")
    route_port=$(ask_with_default "$(localized_text "3x-ui 新入站本地监听端口" "3x-ui New inbound local listening port" "3x-ui Новый входящий локальный порт прослушивания")" "8443")
    is_loopback_listen_addr "$route_addr" || { echo -e "$(localized_text "${RED}❌ 为保证安全，TCP/SNI 入站后端只允许 127.0.0.1、localhost 或 ::1。${PLAIN}" "${RED}❌ To ensure security, the TCP/SNI inbound backend only allows 127.0.0.1, localhost or ::1.${PLAIN}" "${RED}❌ В целях обеспечения безопасности входящий сервер TCP/SNI допускает только 127.0.0.1, localhost или ::1.${PLAIN}")"; return 1; }
    is_valid_port "$route_port" || { echo -e "$(localized_text "${RED}❌ 入站端口无效：${route_port}${PLAIN}" "${RED}❌ Invalid inbound port: ${route_port}${PLAIN}" "${RED}❌ Неверный входящий порт: ${route_port}.${PLAIN}")"; return 1; }
    if [[ "$route_port" == "$NGINX_LISTEN_PORT" || "$route_port" == "$CADDY_LISTEN_PORT" || "$route_port" == "$PANEL_LISTEN_PORT" || "$route_port" == "$SUB_LISTEN_PORT" ]]; then
        echo -e "$(localized_text "${RED}❌ 入站端口不能复用公网入口、Web 反代、面板或订阅服务端口。${PLAIN}" "${RED}❌ The inbound port cannot reuse the public entry, Web reverse proxy, panel or subscription service port.${PLAIN}" "${RED}❌ Порт входящего подключения не может повторно использовать интернет-точка входа, обратный веб-прокси, порт панели или службы подписки.${PLAIN}")"
        return 1
    fi

    echo -e ""
    echo -e "$(localized_text "${CYAN}即将添加 TCP/SNI 分流：${route_sni}:${NGINX_LISTEN_PORT} -> ${route_addr}:${route_port}${PLAIN}" "${CYAN}Will be added soon. TCP/SNI routing: ${route_sni}:${NGINX_LISTEN_PORT} -> ${route_addr}:${route_port}${PLAIN}" "${CYAN}будет добавлен в ближайшее время. TCP/SNI маршрутизация: ${route_sni}:${NGINX_LISTEN_PORT} -> ${route_addr}:${route_port}${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}请确认 3x-ui 入站已监听 ${route_addr}:${route_port}，且客户端连接端口使用 ${NGINX_LISTEN_PORT}。${PLAIN}" "${YELLOW}Please confirm that 3x-ui inbound is listening to ${route_addr}:${route_port}, and the client connection port uses ${NGINX_LISTEN_PORT}.${PLAIN}" "${YELLOW}Подтвердите, что 3x-ui прослушивает входящее подключение ${route_addr}:${route_port}, а порт подключения клиента использует ${NGINX_LISTEN_PORT}.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}说明：Web 白名单只保护 Web 域名，不会应用到 TCP/SNI 或 Xray 节点流量。${PLAIN}" "${YELLOW}Note: The Web whitelist only protects Web domains and will not be applied to TCP/SNI or Xray node traffic.${PLAIN}" "${YELLOW}Примечание. Белый список веб-сайтов защищает только имена веб-доменов и не будет применяться к трафику узлов TCP/SNI или Xray.${PLAIN}")"
    confirm_risk_action "$(localized_text "新增 443 TCP/SNI 入站 ${route_sni}" "Added 443 TCP/SNI inbound ${route_sni}" "Добавлен 443 TCP/SNI входящий ${route_sni}.")" \
        "$(localized_text "Nginx stream SNI 分流规则，会把该 SNI 直通到本地 3x-ui 入站" "Nginx stream SNI routing rule will pass the SNI directly to the local 3x-ui inbound connection" "Правило маршрутизации Nginx stream SNI передаст SNI непосредственно локальному входящему соединению 3x-ui.")" \
        "$(localized_text "使用 443端口复用备份恢复，或从 TCP/SNI 入站管理菜单删除该分流" "Restore using a Port 443 Reuse backup, or delete the route from the TCP/SNI inbound connection management menu" "Восстановите резервную копию повторного использования порта 443 или удалите маршрут в меню управления входящими подключениями TCP/SNI.")" \
        "$(localized_text "确认后端只监听本地地址，不要在安全组或防火墙开放 ${route_port}。" "Confirm that the backend only listens to the local address and does not open ${route_port} in the security group or firewall." "Убедитесь, что бэкенд прослушивает только локальный адрес и не открывает ${route_port} в группе безопасности или брандмауэре.")" || return 1

    idx=${#TCP_ROUTE_SNIS[@]}
    TCP_ROUTE_SNIS[$idx]="$route_sni"
    TCP_ROUTE_ADDRS[$idx]="$route_addr"
    TCP_ROUTE_PORTS[$idx]="$route_port"
    save_and_offer_reapply_sni_stack
}

edit_sni_stack_tcp_route() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}修改 443 TCP/SNI 本地入站分流${PLAIN}" "${BOLD}Modification 443 TCP/SNI local inbound offload${PLAIN}" "${BOLD}модификация 443 TCP/SNI локальная входящая разгрузка${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    if [[ ${#TCP_ROUTE_SNIS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有可修改的 TCP/SNI 入站分流。${PLAIN}" "${YELLOW}Currently has no modifiable TCP/SNI inbound offload.${PLAIN}" "${YELLOW}в настоящее время не имеет изменяемой входящей разгрузки TCP/SNI.${PLAIN}")"
        return 0
    fi

    local i num choice idx old_sni new_sni new_sni_input new_addr new_port existing
    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        num=$((i + 1))
        echo -e "${GREEN}${num}.${PLAIN} ${TCP_ROUTE_SNIS[$i]}:${NGINX_LISTEN_PORT} -> ${TCP_ROUTE_ADDRS[$i]}:${TCP_ROUTE_PORTS[$i]}"
    done
    echo -e "------------------------------------------------"
    read_trimmed choice "$(localized_text "请输入要修改的序号: " "Please enter the serial number to be modified:" "Пожалуйста, введите серийный номер, который необходимо изменить:")"
    if [[ -z "$choice" || "$choice" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消修改。${PLAIN}" "${BLUE}Edit canceled.${PLAIN}" "${BLUE}Изменение отменено.${PLAIN}")"
        return 0
    fi
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#TCP_ROUTE_SNIS[@]} )); then
        echo -e "$(localized_text "${RED}❌ 序号无效。${PLAIN}" "${RED}❌ The serial number is invalid.${PLAIN}" "${RED}❌ Серийный номер недействителен.${PLAIN}")"
        return 1
    fi

    idx=$((choice - 1))
    old_sni="${TCP_ROUTE_SNIS[$idx]}"
    new_sni_input=$(ask_with_default "$(localized_text "SNI/域名" "SNI/domain" "SNI/доменное имя")" "$old_sni")
    new_sni=$(normalize_domain_input "$new_sni_input")
    new_addr=$(ask_with_default "$(localized_text "本地监听地址（只允许本地）" "Local listening address (only local allowed)" "Локальный адрес прослушивания (разрешено только локальное)")" "${TCP_ROUTE_ADDRS[$idx]}")
    new_addr=$(normalize_loopback_addr "$new_addr")
    new_port=$(ask_with_default "$(localized_text "本地监听端口" "local listening port" "локальный порт прослушивания")" "${TCP_ROUTE_PORTS[$idx]}")

    is_valid_domain "$new_sni" || { print_domain_validation_error "$(localized_text "SNI/域名" "SNI/domain" "SNI/доменное имя")" "$new_sni_input" "$new_sni"; return 1; }
    if [[ "$new_sni" == "$PANEL_DOMAIN" || "$new_sni" == "$REALITY_SNI" ]]; then
        echo -e "$(localized_text "${RED}❌ TCP/SNI 入站域名不能和面板域名或 REALITY SNI 相同。${PLAIN}" "${RED}❌ The TCP/SNI inbound domain cannot be the same as the panel domain or REALITY SNI.${PLAIN}" "${RED}❌ Имя входящего домена TCP/SNI не может совпадать с именем домена панели или REALITY SNI.${PLAIN}")"
        return 1
    fi
    for existing in "${SITE_DOMAINS[@]}"; do
        [[ "$new_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该域名已作为网站/反代域名使用。${PLAIN}" "${RED}❌ This domain has been used as a website/reverse proxy domain.${PLAIN}" "${RED}❌ Это доменное имя использовалось в качестве доменного имени веб-сайта/обратного прокси-сервера.${PLAIN}")"; return 1; }
    done
    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        [[ "$i" -eq "$idx" ]] && continue
        [[ "$new_sni" == "${TCP_ROUTE_SNIS[$i]}" ]] && { echo -e "$(localized_text "${RED}❌ 该 TCP/SNI 入站已经存在。${PLAIN}" "${RED}❌ The TCP/SNI inbound already exists.${PLAIN}" "${RED}❌ входящее подключение TCP/SNI уже существует.${PLAIN}")"; return 1; }
    done
    for existing in "${XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$new_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该域名已作为 Xray 入站使用。${PLAIN}" "${RED}❌ This domain has been used inbound as Xray.${PLAIN}" "${RED}❌ Это доменное имя использовалось в качестве Xray.${PLAIN}")"; return 1; }
    done
    is_loopback_listen_addr "$new_addr" || { echo -e "$(localized_text "${RED}❌ 为保证安全，TCP/SNI 入站后端只允许 127.0.0.1、localhost 或 ::1。${PLAIN}" "${RED}❌ To ensure security, the TCP/SNI inbound backend only allows 127.0.0.1, localhost or ::1.${PLAIN}" "${RED}❌ В целях обеспечения безопасности входящий сервер TCP/SNI допускает только 127.0.0.1, localhost или ::1.${PLAIN}")"; return 1; }
    is_valid_port "$new_port" || { echo -e "$(localized_text "${RED}❌ 入站端口无效：${new_port}${PLAIN}" "${RED}❌ Invalid inbound port: ${new_port}${PLAIN}" "${RED}❌ Неверный входящий порт: ${new_port}.${PLAIN}")"; return 1; }
    if [[ "$new_port" == "$NGINX_LISTEN_PORT" || "$new_port" == "$CADDY_LISTEN_PORT" || "$new_port" == "$PANEL_LISTEN_PORT" || "$new_port" == "$SUB_LISTEN_PORT" ]]; then
        echo -e "$(localized_text "${RED}❌ 入站端口不能复用公网入口、Caddy、面板或订阅服务端口。${PLAIN}" "${RED}❌ The inbound port cannot reuse the public entry, Caddy, panel or subscription service port.${PLAIN}" "${RED}❌ Входящий порт не может повторно использовать вход в публичную сеть, Caddy, порт панели или сервисный порт подписки.${PLAIN}")"
        return 1
    fi

    echo -e ""
    echo -e "$(localized_text "${CYAN}即将修改：${old_sni}:${NGINX_LISTEN_PORT} -> ${new_sni}:${NGINX_LISTEN_PORT} -> ${new_addr}:${new_port}${PLAIN}" "${CYAN}Is about to be modified: ${old_sni}:${NGINX_LISTEN_PORT} -> ${new_sni}:${NGINX_LISTEN_PORT} -> ${new_addr}:${new_port}${PLAIN}" "${CYAN}скоро будет изменен: ${old_sni}:${NGINX_LISTEN_PORT} -> ${new_sni}:${NGINX_LISTEN_PORT} -> ${new_addr}:${new_port}${PLAIN}")"
    confirm_risk_action "$(localized_text "修改 443 TCP/SNI 入站 ${old_sni}" "Modify 443 TCP/SNI inbound ${old_sni}" "Изменить 443 TCP/SNI входящий ${old_sni}")" \
        "$(localized_text "Nginx stream SNI 分流规则和本地后端端口" "Nginx stream SNI Offload rules and local backend ports" "Nginx stream SNI Правила разгрузки и локальные серверные порты")" \
        "$(localized_text "使用 443端口复用备份恢复修改前配置" "Use Port 443 Reuse backup to restore the configuration before modification" "Используйте резервную копию повторного использования порта 443 для восстановления конфигурации до изменения.")" \
        "$(localized_text "确认 3x-ui 入站已按新地址和端口监听，且未开放该内部端口。" "Confirm that 3x-ui inbound is listening at the new address and port, and the internal port is not open." "Убедитесь, что 3x-ui прослушивает входящее подключение по новому адресу и порту, а внутренний порт не открыт.")" || return 1

    TCP_ROUTE_SNIS[$idx]="$new_sni"
    TCP_ROUTE_ADDRS[$idx]="$new_addr"
    TCP_ROUTE_PORTS[$idx]="$new_port"
    if [[ "$old_sni" != "$new_sni" ]]; then
        rename_sni_ip_whitelist_domain "$old_sni" "$new_sni"
    fi
    save_and_offer_reapply_sni_stack
}

remove_sni_stack_tcp_route() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}删除 443 TCP/SNI 本地入站分流${PLAIN}" "${BOLD}Deleted 443 TCP/SNI local inbound offload${PLAIN}" "${BOLD}удален 443 TCP/SNI локальная входящая разгрузка${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    if [[ ${#TCP_ROUTE_SNIS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有可删除的 TCP/SNI 入站分流。${PLAIN}" "${YELLOW}Currently has no TCP/SNI inbound offloads that can be deleted.${PLAIN}" "${YELLOW}в настоящее время не имеет входящих разгрузок TCP/SNI, которые можно удалить.${PLAIN}")"
        return 0
    fi

    local i num choice idx route_sni
    local -a new_snis=()
    local -a new_addrs=()
    local -a new_ports=()
    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        num=$((i + 1))
        echo -e "${GREEN}${num}.${PLAIN} ${TCP_ROUTE_SNIS[$i]}:${NGINX_LISTEN_PORT} -> ${TCP_ROUTE_ADDRS[$i]}:${TCP_ROUTE_PORTS[$i]}"
    done
    echo -e "------------------------------------------------"
    read_trimmed choice "$(localized_text "请输入要删除的序号: " "Please enter the serial number to be deleted:" "Пожалуйста, введите серийный номер, который необходимо удалить:")"
    if [[ -z "$choice" || "$choice" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消删除。${PLAIN}" "${BLUE}Removal canceled.${PLAIN}" "${BLUE}Удаление отменено.${PLAIN}")"
        return 0
    fi
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#TCP_ROUTE_SNIS[@]} )); then
        echo -e "$(localized_text "${RED}❌ 序号无效。${PLAIN}" "${RED}❌ The serial number is invalid.${PLAIN}" "${RED}❌ Серийный номер недействителен.${PLAIN}")"
        return 1
    fi

    idx=$((choice - 1))
    route_sni="${TCP_ROUTE_SNIS[$idx]}"
    confirm_risk_action "$(localized_text "从 443 分流中移除 TCP/SNI 入站 ${route_sni}" "Remove TCP/SNI from 443 routing inbound ${route_sni}" "Удалить входящее подключение TCP/SNI из маршрутизации 443 ${route_sni}.")" \
        "$(localized_text "该 SNI 的 Nginx stream 直通规则" "The Nginx stream pass-through rule for SNI" "Правило прохождения Nginx stream для SNI")" \
        "$(localized_text "使用 443端口复用备份恢复，或重新新增该 TCP/SNI 入站" "Use Port 443 Reuse backup and restore, or re-add the TCP/SNI inbound connection" "Используйте резервное копирование и восстановление повторного использования порта 443 или повторно добавьте входящий TCP/SNI.")" \
        "$(localized_text "确认没有客户端仍依赖该 SNI 连接。" "Confirm that no clients are still relying on the SNI connection." "Убедитесь, что ни один клиент по-прежнему не использует соединение SNI.")" || return 1

    for i in "${!TCP_ROUTE_SNIS[@]}"; do
        [[ "$i" -eq "$idx" ]] && continue
        new_snis+=("${TCP_ROUTE_SNIS[$i]}")
        new_addrs+=("${TCP_ROUTE_ADDRS[$i]}")
        new_ports+=("${TCP_ROUTE_PORTS[$i]}")
    done
    TCP_ROUTE_SNIS=("${new_snis[@]}")
    TCP_ROUTE_ADDRS=("${new_addrs[@]}")
    TCP_ROUTE_PORTS=("${new_ports[@]}")
    remove_sni_ip_whitelist_for_domain "$route_sni"
    save_and_offer_reapply_sni_stack
}

# ---------------------------------------------------------
# Module: xray_sni_routes.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Xray SNI route records and sync workflows for nginx-stream/tcp-peek modes.

xray_sni_routes_fallback_notice() {
    echo -e "$(localized_text "${YELLOW}当前为 Xray Fallback 模式。${PLAIN}" "${YELLOW}Xray Fallback mode is active.${PLAIN}" "${YELLOW}Активен режим Xray Fallback.${PLAIN}")"
    print_xray_fallback_mode_explanation
}

offer_sync_xray_sni_routes() {
    echo -e "$(localized_text "${YELLOW}规则已保存，但尚未应用到公网 443。${PLAIN}" "${YELLOW}The rule is saved but is not active on public port 443 yet.${PLAIN}" "${YELLOW}Правило сохранено, но ещё не применяется на публичном порту 443.${PLAIN}")"
    if confirm_risk_action \
        "$(localized_text "立即应用 Xray SNI 路由" "Apply Xray SNI routes now" "Применить маршруты Xray SNI сейчас")" \
        "$(localized_text "重新生成当前入口配置；运行中的 Nginx 或 vpso-mux 可能重启" "regenerate the active entry configuration; the running Nginx or vpso-mux service may restart" "будет заново создана конфигурация текущей точки входа; работающий Nginx или vpso-mux может быть перезапущен")" \
        "$(localized_text "原路由文件仍保留；可修正后再次同步或重新应用 443 配置" "the route file remains available; correct it and sync again or reapply the port 443 configuration" "файл маршрутов сохранится; исправьте его и повторите синхронизацию или применение конфигурации порта 443")"; then
        sync_xray_sni_routes_to_entry_mode
    else
        echo -e "$(localized_text "${YELLOW}未应用。稍后可在 Xray 入站管理中选择“同步到当前入口模式”。${PLAIN}" "${YELLOW}Not applied. Use “Sync to current entry mode” in Xray inbound management later.${PLAIN}" "${YELLOW}Изменения не применены. Позже выберите «Синхронизировать с текущим режимом входа» в меню управления входящими подключениями Xray.${PLAIN}")"
    fi
}

confirm_non_xray_route_listener() {
    local listen_line="$1"
    if echo "$listen_line" | grep -Eqi 'xray|x-ui|3x-ui'; then
        return 0
    fi
    echo -e "$(localized_text "${YELLOW}⚠️ 无法确认该端口由 Xray/3x-ui 监听：${listen_line}${PLAIN}" "${YELLOW}⚠️ The listener does not appear to be Xray/3x-ui: ${listen_line}${PLAIN}" "${YELLOW}⚠️ Не удалось подтвердить, что порт прослушивает Xray/3x-ui: ${listen_line}${PLAIN}")"
    confirm_default_no "$(localized_text "仍要保存此路由吗？(y/N): " "Save this route anyway? (y/N): " "Всё равно сохранить этот маршрут? (y/N): ")"
}

list_xray_sni_routes() {
    load_sni_stack_env || return 1
    local mode fallback_idx
    mode=$(get_entry_mode)
    fallback_idx=$(xray_fallback_main_route_index 2>/dev/null || true)
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}Xray 入站分流规则${PLAIN}" "${BOLD}Xray Inbound routing rule${PLAIN}" "${BOLD}Правила маршрутизации входящих подключений Xray${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "配置文件：$(xray_sni_routes_path)" "Configuration file: $(xray_sni_routes_path)" "Файл конфигурации: $(xray_sni_routes_path).")"
    echo -e "$(localized_text "规则格式：SNI|ADDR|PORT" "Rule format: SNI|ADDR|PORT" "Формат правила: SNI|ADDR|PORT.")"
    if [[ "$mode" == "xray-fallback" ]]; then
        echo -e "------------------------------------------------"
        xray_sni_routes_fallback_notice
        print_xray_fallback_main_route_summary
    fi
    echo -e "------------------------------------------------"
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有 Xray 入站分流规则。${PLAIN}" "${YELLOW}Currently does not have the Xray inbound routing rule.${PLAIN}" "${YELLOW}в настоящее время не имеет правила маршрутизация входящего подключения Xray.${PLAIN}")"
        if [[ -n "${XRAY_LISTEN_PORT:-}" ]]; then
            echo -e "$(localized_text "${CYAN}旧默认 Xray/REALITY 后端仍是：${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}${PLAIN}" "${CYAN}Old default Xray/REALITY backend is still: ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}${PLAIN}" "${CYAN}старая версия по умолчанию Xray/REALITY по-прежнему: ${XRAY_LISTEN_ADDR}:${XRAY_LISTEN_PORT}${PLAIN}")"
            echo -e "$(localized_text "${CYAN}如需多个本地 Xray 入站，可按 SNI 添加新的本地端口分流记录。${PLAIN}" "${CYAN}If requires multiple local Xray inbounds, press SNI to add a new local port offload record.${PLAIN}" "${CYAN}Если для требуется несколько локальных входящих вызовов Xray, нажмите SNI, чтобы добавить новую запись о разгрузке локального порта.${PLAIN}")"
        fi
        return 0
    fi

    local i num
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        num=$((i + 1))
        if [[ "$mode" == "xray-fallback" && -n "$fallback_idx" && "$i" == "$fallback_idx" ]]; then
            echo -e "$(localized_text "${GREEN}${num}.${PLAIN} ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]} ${GREEN}[xray-fallback 主入站，当前模式生效]${PLAIN}" "${GREEN}${num}. ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]} [xray-fallback main inbound, current mode takes effect]${PLAIN}" "${GREEN}${num}. ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]} [xray-резервный основной входящий режим, текущий режим вступает в силу]${PLAIN}")"
        elif [[ "$mode" == "xray-fallback" ]]; then
            echo -e "$(localized_text "${GREEN}${num}.${PLAIN} ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]} ${YELLOW}[已保留，当前 xray-fallback 模式下不生效]${PLAIN}" "${GREEN}${num}. ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]} [Reserved, not valid in current xray-fallback mode]${PLAIN}" "${GREEN}${num}. ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]} [Зарезервировано, недействительно в текущем резервном режиме xray]${PLAIN}")"
        else
            echo -e "${GREEN}${num}.${PLAIN} ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]}"
        fi
    done
}

add_xray_sni_route() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}添加 Xray 入站分流规则${PLAIN}" "${BOLD}Adds Xray inbound connection routing rule${PLAIN}" "${BOLD}добавляет правило входящей рассылки Xray${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    echo -e "$(localized_text "${YELLOW}本菜单只记录 SNI -> 本地地址:端口；用于当前支持的端口复用模式渲染分流规则，不会创建、删除或修改 3x-ui/Xray 入站内部配置。${PLAIN}" "${YELLOW}This menu only records SNI -> local address: port; used for the currently supported Port 443 Reuse mode rendering routing rules, and will not create, delete or modify the internal configuration of the 3x-ui/Xray inbound connection.${PLAIN}" "${YELLOW}Это меню записывает только SNI -> локальный адрес: порт; используется для поддерживаемых в настоящее время правил маршрутизации в режиме повторного использования порта 443 и не будет создавать, удалять или изменять внутреннюю конфигурацию входящего соединения 3x-ui/Xray.${PLAIN}")"
    echo -e "------------------------------------------------"

    local route_sni route_sni_input route_addr route_port existing idx
    read_trimmed route_sni_input "$(localized_text "SNI/域名: " "SNI/domain:" "SNI/доменное имя:")"
    route_sni=$(normalize_domain_input "$route_sni_input")
    if [[ -z "$route_sni" || "$route_sni" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消添加。${PLAIN}" "${BLUE}Has been canceled.${PLAIN}" "${BLUE}отменен.${PLAIN}")"
        return 0
    fi
    is_valid_domain "$route_sni" || { print_domain_validation_error "$(localized_text "SNI/域名" "SNI/domain" "SNI/доменное имя")" "$route_sni_input" "$route_sni"; return 1; }
    if [[ "$route_sni" == "$PANEL_DOMAIN" || "$route_sni" == "$REALITY_SNI" ]]; then
        echo -e "$(localized_text "${RED}❌ Xray 入站域名不能和面板域名或 REALITY SNI 相同。${PLAIN}" "${RED}❌ The Xray inbound domain cannot be the same as the panel domain or REALITY SNI.${PLAIN}" "${RED}❌ Имя входящего домена Xray не может совпадать с именем домена панели или REALITY SNI.${PLAIN}")"
        return 1
    fi
    for existing in "${SITE_DOMAINS[@]}"; do
        [[ "$route_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该域名已作为 Web 域名使用，Xray 入站规则必须和 Web 域名分开。${PLAIN}" "${RED}❌ This domain is already used as a web domain. The Xray inbound rule must be separated from the web domain.${PLAIN}" "${RED}❌ Это доменное имя уже используется в качестве имени веб-домена. Правило для входящего подключения Xray должно быть отделено от имени веб-домена.${PLAIN}")"; return 1; }
    done
    for existing in "${TCP_ROUTE_SNIS[@]}"; do
        [[ "$route_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该域名已存在于旧 TCP/SNI 本地入站规则中。${PLAIN}" "${RED}❌ This domain already exists in the old TCP/SNI local inbound rule.${PLAIN}" "${RED}❌ Это доменное имя уже существует в старом локальном входящем правиле TCP/SNI.${PLAIN}")"; return 1; }
    done
    for existing in "${XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$route_sni" == "$existing" ]] && { echo -e "$(localized_text "${RED}❌ 该 Xray 入站分流规则已经存在。${PLAIN}" "${RED}❌ The Xray inbound offload rule already exists.${PLAIN}" "${RED}❌ Правило входящей разгрузки Xray уже существует.${PLAIN}")"; return 1; }
    done

    route_addr=$(ask_with_default "$(localized_text "本地监听地址" "local listening address" "местный адрес прослушивания")" "127.0.0.1")
    route_addr=$(normalize_loopback_addr "$route_addr")
    route_port=$(ask_with_default "$(localized_text "本地监听端口" "local listening port" "локальный порт прослушивания")" "${XRAY_LISTEN_PORT:-1443}")
    is_loopback_listen_addr "$route_addr" || { echo -e "$(localized_text "${RED}❌ 为避免公网暴露，本地监听地址只允许 127.0.0.1、localhost 或 ::1。${PLAIN}" "${RED}❌ To avoid public exposure, the local listening address is only allowed to be 127.0.0.1, localhost or ::1.${PLAIN}" "${RED}❌ Чтобы избежать воздействия публичной сети, локальным адресом прослушивания может быть только 127.0.0.1, localhost или ::1.${PLAIN}")"; return 1; }
    is_valid_port "$route_port" || { echo -e "$(localized_text "${RED}❌ 本地监听端口无效：${route_port}${PLAIN}" "${RED}❌ The local listening port is invalid: ${route_port}${PLAIN}" "${RED}❌ Неверный локальный порт прослушивания: ${route_port}.${PLAIN}")"; return 1; }
    if [[ "$route_port" == "$CADDY_LISTEN_PORT" ]]; then
        echo -e "$(localized_text "${RED}❌ 该端口与 Web 反代引擎本地端口 ${CADDY_LISTEN_PORT} 冲突。${PLAIN}" "${RED}❌ This port conflicts with the Web reverse proxy engine local port ${CADDY_LISTEN_PORT}.${PLAIN}" "${RED}❌ Этот порт конфликтует с локальным портом ${CADDY_LISTEN_PORT} механизма веб-прокси.${PLAIN}")"
        return 1
    fi
    if [[ "$route_port" == "$NGINX_LISTEN_PORT" || "$route_port" == "$PANEL_LISTEN_PORT" || "$route_port" == "$SUB_LISTEN_PORT" ]]; then
        echo -e "$(localized_text "${RED}❌ 入站端口不能复用公网入口、面板或订阅服务端口。${PLAIN}" "${RED}❌ The inbound port cannot reuse the public entry, panel or subscription service port.${PLAIN}" "${RED}❌ Входящий порт не может повторно использовать порт входа в публичную сеть, панель или порт службы подписки.${PLAIN}")"
        return 1
    fi
    existing=$(xray_sni_route_port_conflict "$route_addr" "$route_port" || true)
    if [[ -n "$existing" ]]; then
        echo -e "$(localized_text "${RED}❌ ${route_addr}:${route_port} 已被规则 ${existing} 使用。${PLAIN}" "${RED}❌ ${route_addr}:${route_port} is already used by rule ${existing}.${PLAIN}" "${RED}❌ ${route_addr}:${route_port} уже используется правилом ${existing}.${PLAIN}")"
        return 1
    fi

    local listen_line
    print_xray_route_port_status "$route_sni" "$route_addr" "$route_port"
    listen_line=$(xray_route_listen_line_by_addr_port "$route_addr" "$route_port")
    if [[ -z "$listen_line" ]]; then
        echo -e "$(localized_text "${RED}❌ 端口未监听，请先去 3x-ui 创建并启用对应入站。${PLAIN}" "${RED}Port ❌ is not listening. Please go to 3x-ui to create and enable the corresponding inbound port first.${PLAIN}" "${RED}Порт ❌ не прослушивается. Пожалуйста, перейдите к 3x-ui, чтобы сначала создать и включить соответствующий входящий порт.${PLAIN}")"
        return 1
    fi
    confirm_non_xray_route_listener "$listen_line" || return 0

    idx=${#XRAY_SNI_ROUTE_SNIS[@]}
    XRAY_SNI_ROUTE_SNIS[$idx]="$route_sni"
    XRAY_SNI_ROUTE_ADDRS[$idx]="$route_addr"
    XRAY_SNI_ROUTE_PORTS[$idx]="$route_port"
    save_xray_sni_route_arrays
    echo -e "$(localized_text "${GREEN}✅ 已保存 Xray 入站分流规则：${route_sni} -> ${route_addr}:${route_port}${PLAIN}" "${GREEN}✅ Saved Xray inbound routing rule: ${route_sni} -> ${route_addr}:${route_port}${PLAIN}" "${GREEN}✅ Правило маршрутизации входящего подключения Xray сохранено: ${route_sni} -> ${route_addr}:${route_port}${PLAIN}")"
    offer_sync_xray_sni_routes
}

remove_xray_sni_route() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}删除 Xray 入站分流规则${PLAIN}" "${BOLD}Delete Xray inbound routing rule${PLAIN}" "${BOLD}удалить правило маршрутизация входящего подключения Xray${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    load_sni_stack_env || return 1
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有可删除的 Xray 入站分流规则。${PLAIN}" "${YELLOW}There are currently no Xray inbound routing rules that can be deleted.${PLAIN}" "${YELLOW}В настоящее время нет правил маршрутизация входящего подключения Xray, которые можно удалить.${PLAIN}")"
        return 0
    fi

    local i num choice idx route_sni
    local -a new_snis=() new_addrs=() new_ports=()
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        num=$((i + 1))
        echo -e "${GREEN}${num}.${PLAIN} ${XRAY_SNI_ROUTE_SNIS[$i]} -> ${XRAY_SNI_ROUTE_ADDRS[$i]}:${XRAY_SNI_ROUTE_PORTS[$i]}"
    done
    echo -e "------------------------------------------------"
    read_trimmed choice "$(localized_text "请输入要删除的序号: " "Please enter the serial number to be deleted:" "Пожалуйста, введите серийный номер, который необходимо удалить:")"
    if [[ -z "$choice" || "$choice" == "0" ]]; then
        echo -e "$(localized_text "${BLUE}已取消删除。${PLAIN}" "${BLUE}Has been canceled.${PLAIN}" "${BLUE}отменен.${PLAIN}")"
        return 0
    fi
    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#XRAY_SNI_ROUTE_SNIS[@]} )); then
        echo -e "$(localized_text "${RED}❌ 序号无效。${PLAIN}" "${RED}❌ The serial number is invalid.${PLAIN}" "${RED}❌ Серийный номер недействителен.${PLAIN}")"
        return 1
    fi

    idx=$((choice - 1))
    route_sni="${XRAY_SNI_ROUTE_SNIS[$idx]}"
    confirm_risk_action \
        "$(localized_text "删除 Xray SNI 路由" "Delete Xray SNI route" "Удалить маршрут Xray SNI")" \
        "$(localized_text "从路由文件中删除 ${route_sni}" "remove ${route_sni} from the route file" "удалить ${route_sni} из файла маршрутов")" \
        "$(localized_text "重新添加相同的 SNI、本地地址和端口" "add the same SNI, local address, and port again" "повторно добавить тот же SNI, локальный адрес и порт")" || return 0
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        [[ "$i" -eq "$idx" ]] && continue
        new_snis+=("${XRAY_SNI_ROUTE_SNIS[$i]}")
        new_addrs+=("${XRAY_SNI_ROUTE_ADDRS[$i]}")
        new_ports+=("${XRAY_SNI_ROUTE_PORTS[$i]}")
    done
    XRAY_SNI_ROUTE_SNIS=("${new_snis[@]}")
    XRAY_SNI_ROUTE_ADDRS=("${new_addrs[@]}")
    XRAY_SNI_ROUTE_PORTS=("${new_ports[@]}")
    save_xray_sni_route_arrays
    echo -e "$(localized_text "${GREEN}✅ 已删除 Xray 入站分流规则：${route_sni}${PLAIN}" "${GREEN}✅ Deleted Xray inbound routing rule: ${route_sni}${PLAIN}" "${GREEN}✅ Правило маршрутизации входящего подключения Xray удалено: ${route_sni}.${PLAIN}")"
    offer_sync_xray_sni_routes
}

check_xray_sni_route_ports() {
    load_sni_stack_env || return 1
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}检查 Xray 入站端口状态${PLAIN}" "${BOLD}Check Xray Inbound port status${PLAIN}" "${BOLD}Проверьте Xray Статус входящего порта${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    if [[ ${#XRAY_SNI_ROUTE_SNIS[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前没有 Xray 入站分流规则。${PLAIN}" "${YELLOW}Currently does not have the Xray inbound routing rule.${PLAIN}" "${YELLOW}в настоящее время не имеет правила маршрутизация входящего подключения Xray.${PLAIN}")"
        return 0
    fi

    local i
    for i in "${!XRAY_SNI_ROUTE_SNIS[@]}"; do
        print_xray_route_port_status "${XRAY_SNI_ROUTE_SNIS[$i]}" "${XRAY_SNI_ROUTE_ADDRS[$i]}" "${XRAY_SNI_ROUTE_PORTS[$i]}"
        echo -e "------------------------------------------------"
    done
}

sync_xray_sni_routes_to_entry_mode() {
    load_sni_stack_env || return 1
    local mode
    mode=$(get_entry_mode)
    case "$mode" in
        "nginx-stream")
            echo -e "$(localized_text "${CYAN}正在同步 Xray 入站分流规则到 Nginx Stream 配置...${PLAIN}" "${CYAN}Is synchronizing Xray Inbound connection routing rules to Nginx Stream configuration...${PLAIN}" "${CYAN}синхронизирует правила входящей рассылки Xray с конфигурацией Nginx Stream...${PLAIN}")"
            reapply_sni_stack_from_env --yes
            ;;
        "tcp-peek")
            local tmp_config target_config
            echo -e "$(localized_text "${CYAN}正在同步 Xray 入站分流规则到 TCP Peek + Splice 配置...${PLAIN}" "${CYAN}Is synchronizing Xray Inbound connection routing rules to TCP Peek + Splice configuration...${PLAIN}" "${CYAN}синхронизирует правила входящей рассылки Xray с конфигурацией TCP Peek + Splice...${PLAIN}")"
            target_config=$(vpso_mux_config_path)
            tmp_config="${target_config}.tmp.$$"
            write_vpso_mux_config_from_sni_stack "$NGINX_LISTEN_PORT" "$tmp_config" || return 1
            if ! run_vpso_mux_config_check "$tmp_config"; then
                quarantine_path "$tmp_config" "/etc/vps-optimize/quarantine/vpso-mux" >/dev/null 2>&1 || true
                return 1
            fi
            mv "$tmp_config" "$target_config" || { echo -e "$(localized_text "${RED}❌ TCP Peek + Splice 配置替换失败：${target_config}${PLAIN}" "${RED}❌ TCP Peek + Splice Configuration replacement failed: ${target_config}${PLAIN}" "${RED}❌ TCP Peek + Splice Не удалось заменить конфигурацию: ${target_config}${PLAIN}")"; return 1; }
            if systemctl is-active --quiet vpso-mux 2>/dev/null; then
                systemctl restart vpso-mux || { print_vpso_mux_failure_context "$NGINX_LISTEN_PORT"; echo -e "$(localized_text "${RED}❌ vpso-mux 重启失败，请查看上面的日志。${PLAIN}" "${RED}❌ vpso-mux Restart failed, please check the log above.${PLAIN}" "${RED}❌ vpso-mux Не удалось перезапустить, проверьте журнал выше.${PLAIN}")"; return 1; }
            else
                echo -e "$(localized_text "${YELLOW}vpso-mux 分流器当前未运行，已仅生成并校验配置文件。${PLAIN}" "${YELLOW}The vpso-mux routing is not currently running, only the configuration file has been generated and verified.${PLAIN}" "${YELLOW}маршрутизация vpso-mux в настоящее время не работает, только файл конфигурации создан и проверен.${PLAIN}")"
            fi
            echo -e "$(localized_text "${GREEN}✅ 已同步到 TCP Peek + Splice 配置：${target_config}${PLAIN}" "${GREEN}✅ Synced to TCP Peek + Splice Configuration: ${target_config}${PLAIN}" "${GREEN}✅ Синхронизирован с конфигурацией TCP Peek + Splice: ${target_config}${PLAIN}")"
            ;;
        "xray-fallback")
            xray_sni_routes_fallback_notice
            return 1
            ;;
        *)
            echo -e "$(localized_text "${RED}❌ 当前 ENTRY_MODE 无效或未配置：${mode}${PLAIN}" "${RED}❌ Current ENTRY_MODE is invalid or not configured: ${mode}${PLAIN}" "${RED}❌ Текущий ENTRY_MODE недействителен или не настроен: ${mode}${PLAIN}")"
            return 1
            ;;
    esac
}

manage_xray_inbound_routes() {
    load_sni_stack_env || return 1
    if [[ "$(get_entry_mode)" == "xray-fallback" ]]; then
        while true; do
            clear
            echo -e "${CYAN}================================================${PLAIN}"
            echo -e "$(localized_text "${BOLD}Xray 入站管理${PLAIN}" "${BOLD}Xray Inbound management${PLAIN}" "${BOLD}Управление входящими подключениями Xray${PLAIN}")"
            echo -e "${CYAN}================================================${PLAIN}"
            xray_sni_routes_fallback_notice
            print_xray_fallback_main_route_summary
            echo -e "------------------------------------------------"
            echo -e "$(localized_text "${GREEN}  1. 查看入站分流规则${PLAIN}" "${GREEN}1. View the inbound routing rule${PLAIN}" "${GREEN}1. Просмотреть правила маршрутизации входящих подключений${PLAIN}")"
            echo -e "$(localized_text "${YELLOW}  2. 添加入站分流规则（当前模式不可用）${PLAIN}" "${YELLOW}2. Add inbound routing rules (not available in current mode)${PLAIN}" "${YELLOW}2. Добавьте правила маршрутизация входящего подключения (недоступно в текущем режиме)${PLAIN}")"
            echo -e "$(localized_text "${YELLOW}  3. 删除入站分流规则（当前模式不可用）${PLAIN}" "${YELLOW}3. Delete inbound routing rules (not available in current mode)${PLAIN}" "${YELLOW}3. Удалить правила маршрутизации входящих подключений (недоступно в текущем режиме)${PLAIN}")"
            echo -e "$(localized_text "${YELLOW}  4. 同步规则到当前入口模式（当前模式不可用）${PLAIN}" "${YELLOW}4. Synchronize rules to the current entry mode (the current mode is unavailable)${PLAIN}" "${YELLOW}4. Синхронизировать правила с текущим режимом входа (текущий режим недоступен)${PLAIN}")"
            echo -e "------------------------------------------------"
            echo -e "$(localized_text "${RED}  0. 返回 / q 返回${PLAIN}" "${RED}0. Return / q Return${PLAIN}" "${RED}0. Возврат / q Возврат${PLAIN}")"
            echo -e "${CYAN}================================================${PLAIN}"

            local fallback_choice
            read_trimmed fallback_choice "$(localized_text "请选择操作: " "Please select an action:" "Пожалуйста, выберите действие:")"
            case "$fallback_choice" in
                1) list_xray_sni_routes ;;
                2|3|4)
                    echo -e "$(localized_text "${YELLOW}当前为 xray-fallback 模式，Xray 入站管理默认不可新增、删除或同步规则。${PLAIN}" "${YELLOW}xray-fallback mode is active; Xray inbound rules cannot be added, deleted, or synchronized here.${PLAIN}" "${YELLOW}Активен режим xray-fallback; здесь нельзя добавлять, удалять или синхронизировать правила входящих подключений Xray.${PLAIN}")"
                    echo -e "$(localized_text "${YELLOW}如需多个本地 Xray 入站通过 443 按 SNI 分流，请切换到 nginx-stream 或 tcp-peek。${PLAIN}" "${YELLOW}If multiple local Xray inbound pass 443 split by SNI, please switch to nginx-stream or tcp-peek.${PLAIN}" "${YELLOW}Если несколько локальных входящих каналов Xray 443 разделены на SNI, переключитесь на nginx-stream или tcp-peek.${PLAIN}")"
                    ;;
                0|q|Q) break ;;
                *) echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")" ;;
            esac
            echo ""
            read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        done
        return 0
    fi

    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}Xray 入站管理${PLAIN}" "${BOLD}Xray Inbound management${PLAIN}" "${BOLD}Управление входящими подключениями Xray${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}只管理 SNI -> 本地地址:端口 分流记录，用于当前支持的端口复用模式渲染分流规则；不编辑 3x-ui/Xray 入站内部配置。${PLAIN}" "${YELLOW}Only manages the SNI -> local address:port routing record, which is used for the currently supported Port 443 Reuse mode rendering routing rules; it does not edit the 3x-ui/Xray inbound connection internal configuration.${PLAIN}" "${YELLOW}управляет только SNI -> локальный адрес: записи маршрутизирования порта, которые используются для поддерживаемых в настоящее время правил маршрутизирования рендеринга в однозаходном режиме; он не редактирует входящую внутреннюю конфигурацию 3x-ui/Xray.${PLAIN}")"
        echo -e "$(localized_text "配置文件：$(xray_sni_routes_path)" "Configuration file: $(xray_sni_routes_path)" "Файл конфигурации: $(xray_sni_routes_path).")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 查看入站分流规则${PLAIN}" "${GREEN}1. View the inbound routing rule${PLAIN}" "${GREEN}1. Просмотреть правила маршрутизации входящих подключений${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 添加入站分流规则${PLAIN}" "${GREEN}2. Add inbound routing rule${PLAIN}" "${GREEN}2. Добавить правило маршрутизации входящего подключения${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  3. 删除入站分流规则${PLAIN}" "${GREEN}3. Delete the inbound routing rule${PLAIN}" "${GREEN}3. Удалить правило маршрутизации входящего подключения${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  4. 检查入站端口状态${PLAIN}" "${GREEN}4. Check the inbound port status${PLAIN}" "${GREEN}4. Проверьте состояние входящего порта.${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  5. 同步到当前入口模式${PLAIN}" "${GREEN}5. Synchronize to the current entry mode${PLAIN}" "${GREEN}5. Синхронизироваться с текущим режимом входа${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}  0. 返回 / q 返回${PLAIN}" "${RED}0. Return / q Return${PLAIN}" "${RED}0. Возврат / q Возврат${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local choice
        read_trimmed choice "$(localized_text "请选择操作: " "Please select an action:" "Пожалуйста, выберите действие:")"
        case "$choice" in
            1) list_xray_sni_routes ;;
            2) add_xray_sni_route ;;
            3) remove_xray_sni_route ;;
            4) check_xray_sni_route_ports ;;
            5) sync_xray_sni_routes_to_entry_mode ;;
            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择。${PLAIN}" "${RED}❌ Invalid selection.${PLAIN}" "${RED}❌ Неверный выбор.${PLAIN}")" ;;
        esac
        echo ""
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    done
}

manage_sni_stack_tcp_routes() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}Xray 入站管理${PLAIN}" "${BOLD}Xray Inbound management${PLAIN}" "${BOLD}Управление входящими подключениями Xray${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}用途：记录你已在 3x-ui/Xray 配好的本地入站：SNI -> 本地地址:端口。${PLAIN}" "${YELLOW}Purpose: record the local inbound you have configured in 3x-ui/Xray: SNI -> local address: port.${PLAIN}" "${YELLOW}Назначение: записать локальное входящее подключение, который вы настроили в 3x-ui/Xray: SNI -> локальный адрес: порт.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}这些记录用于当前支持的端口复用模式渲染分流规则；脚本不开放新端口，不改 3x-ui/Xray 入站内部配置。${PLAIN}" "${YELLOW}These records are used for the currently supported Port 443 Reuse mode rendering routing rules; the script does not open new ports and does not change the internal configuration of the 3x-ui/Xray inbound connection.${PLAIN}" "${YELLOW}Эти записи используются для поддерживаемых в настоящее время правил разгрузки рендеринга в режиме с повторным использованием порта 443; сценарий не открывает новые порты и не изменяет внутреннюю конфигурацию входящего подключения 3x-ui/Xray.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 查看当前 TCP/SNI 入站${PLAIN}" "${GREEN}1. View current TCP/SNI inbound${PLAIN}" "${GREEN}1. Просмотр текущего входящего TCP/SNI${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 新增 TCP/SNI 入站${PLAIN}" "${GREEN}2. Add TCP/SNI inbound${PLAIN}" "${GREEN}2. Добавьте входящий TCP/SNI.${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  3. 修改 TCP/SNI 入站${PLAIN}" "${GREEN}3. Modify TCP/SNI inbound${PLAIN}" "${GREEN}3. Изменить TCP/SNI входящий${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  4. 删除 TCP/SNI 入站${PLAIN}" "${GREEN}4. Delete TCP/SNI inbound${PLAIN}" "${GREEN}4. Удалить TCP/SNI входящий${PLAIN}")"
        echo -e "$(localized_text "${BLUE}  5. 查看 Web 白名单适用范围${PLAIN}" "${BLUE}5. View the applicable scope of the Web whitelist${PLAIN}" "${BLUE}5. Просмотрите применимую область белого веб-списка.${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  6. 重新应用并重启 Nginx/Caddy${PLAIN}" "${GREEN}6. Reapply and restart Nginx/Caddy${PLAIN}" "${GREEN}6. Повторно примените и перезапустите Nginx/Caddy.${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  7. 443端口复用链路体检${PLAIN}" "${GREEN}7. Port 443 Reuse link health check${PLAIN}" "${GREEN}7. Проверка состояния повторного использования порта 443${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}  0. 返回上一级 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local choice
        read_trimmed choice "$(localized_text "👉 请选择操作: " "👉 Please select an operation:" "👉 Пожалуйста, выберите операцию:")"
        case "$choice" in
            1) list_sni_stack_tcp_routes ;;
            2) add_sni_stack_tcp_route ;;
            3) edit_sni_stack_tcp_route ;;
            4) remove_sni_stack_tcp_route ;;
            5)
                echo -e "$(localized_text "${YELLOW}Web 白名单只适用于 Web 域名：面板、订阅、普通网站、面板域名和自定义反代域名。${PLAIN}" "${YELLOW}Web whitelist only applies to web domains: panel, subscription, ordinary website, panel domain and custom reverse proxy domain.${PLAIN}" "${YELLOW}Белый список Web применяется только к именам веб-доменов: панель, подписка, обычный веб-сайт, доменное имя панели и собственное доменное имя обратного прокси.${PLAIN}")"
                echo -e "$(localized_text "${YELLOW}TCP/SNI 入站和 Xray 节点流量不会启用 IP 白名单；如需限制来源，请在后端服务或防火墙侧单独设计。${PLAIN}" "${YELLOW}TCP/SNI inbound and Xray node traffic will not enable IP whitelisting; if you need to limit the source, please design it separately on the backend service or firewall side.${PLAIN}" "${YELLOW}входящее подключение TCP/SNI и трафик узла Xray не будут включать белый список IP-адресов; если вам нужно ограничить источник, спроектируйте его отдельно на стороне серверной службы или брандмауэра.${PLAIN}")"
                ;;
            6) reapply_sni_stack_from_env ;;
            7) sni_stack_health_check ;;
            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择！${PLAIN}" "${RED}❌ Invalid selection!${PLAIN}" "${RED}❌ Неверный выбор!${PLAIN}")" ;;
        esac
        echo ""
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    done
}

manage_sni_stack_ip_whitelist() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}🔐 443 域名 IP 白名单${PLAIN}" "${BOLD}🔐 443 domain IP Whitelist${PLAIN}" "${BOLD}🔐 443 Белый список доменных имен IP${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        load_sni_stack_env || return 1
        local whitelist_supported="yes"
        if ! web_proxy_engine_supports_web_whitelist "${ENTRY_MODE:-$(get_entry_mode)}" "${WEB_PROXY_ENGINE:-caddy}"; then
            whitelist_supported="no"
        fi
        echo -e "$(localized_text "${YELLOW}只限制你选择的 Web 域名；支持面板、订阅、网站/反代，Xray 入站、REALITY SNI 与未知 SNI 不受 Web 白名单影响。${PLAIN}" "${YELLOW}Only limits the web domain you choose; supports panel, subscription, website/reverse proxy, Xray inbound, REALITY SNI and unknown SNI are not affected by the web whitelist.${PLAIN}" "${YELLOW}ограничивает только выбранное вами имя веб-домена; поддерживает панель, подписку, веб-сайт/обратный прокси-сервер, входящее соединение Xray, REALITY SNI и неизвестный SNI не зависят от белого списка веб-сайтов.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}Nginx Stream/TCP Peek 入口会在入口层按 SNI + 源 IP 拦截，避免影响同入口其他服务。${PLAIN}" "${YELLOW}The Nginx Stream/TCP Peek entry will be intercepted at the entry layer by SNI + source IP to avoid affecting other services with the same entry.${PLAIN}" "${YELLOW}Вход Nginx Stream/TCP Peek будет перехвачен на входном уровне SNI + IP-адрес источника, чтобы не влиять на другие службы с тем же входом.${PLAIN}")"
        if [[ "$whitelist_supported" != "yes" ]]; then
            echo -e "$(localized_text "${RED}当前为 xray-fallback，本地 Web 反代引擎无法可靠获取真实客户端源 IP，禁止新增或覆盖 Web 白名单。${PLAIN}" "${RED}Is currently xray-fallback. The local Web reverse proxy engine cannot reliably obtain the real client source IP. It is prohibited to add or overwrite the Web whitelist.${PLAIN}" "${RED}в настоящее время является резервным xray. Локальный механизм веб-прокси не может надежно получить реальный исходный IP-адрес клиента. Запрещается добавлять или перезаписывать белый список веб-сайтов.${PLAIN}")"
            echo -e "$(localized_text "${YELLOW}你仍可清除已有白名单；如需继续使用白名单，请切到 Nginx Stream/TCP Peek。${PLAIN}" "${YELLOW}You can still clear the existing whitelist; if you want to continue using the whitelist, please switch to Nginx Stream/TCP Peek.${PLAIN}" "${YELLOW}Вы по-прежнему можете очистить существующий белый список; если вы хотите продолжить использовать белый список, переключитесь на Nginx Stream/TCP Peek.${PLAIN}")"
        fi
        echo -e "------------------------------------------------"

        local -a domains=("$PANEL_DOMAIN")
        local -a labels=("$(localized_text "面板/订阅" "Panel/subscription" "Панель/подписка")")
        local site_domain i num domain current_ranges
        for site_domain in "${SITE_DOMAINS[@]}"; do
            [[ -z "$site_domain" ]] && continue
            domains+=("$site_domain")
            labels+=("$(localized_text "网站/反代" "Website/reverse proxy" "Сайт/обратный прокси")")
        done
        for i in "${!domains[@]}"; do
            num=$((i + 1))
            current_ranges=$(sni_ip_whitelist_ranges_for_domain "${domains[$i]}")
            if [[ -n "$current_ranges" ]]; then
                echo -e "$(localized_text "${GREEN}${num}.${PLAIN} [${labels[$i]}] ${domains[$i]}  ${YELLOW}仅允许：${current_ranges}${PLAIN}" "${GREEN}${num}. [${labels[$i]}] ${domains[$i]} Only allowed: ${current_ranges}${PLAIN}" "${GREEN}${num}. [${labels[$i]}] ${domains[$i]} Разрешено только: ${current_ranges}${PLAIN}")"
            else
                echo -e "$(localized_text "${GREEN}${num}.${PLAIN} [${labels[$i]}] ${domains[$i]}  ${BLUE}未启用${PLAIN}" "${GREEN}${num}. [${labels[$i]}] ${domains[$i]} is not enabled${PLAIN}" "${GREEN}${num}. [${labels[$i]}] ${domains[$i]} не включен${PLAIN}")"
            fi
        done
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}0. 返回上一级 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local choice idx action whitelist_input whitelist_ranges current_client_ip
        local -a whitelist_array=()
        read_trimmed choice "$(localized_text "请输入要管理的域名序号: " "Please enter the domain serial number to be managed:" "Пожалуйста, введите серийный номер доменного имени, которым нужно управлять:")"
        [[ "$choice" == "0" || -z "$choice" ]] && break
        if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#domains[@]} )); then
            echo -e "$(localized_text "${RED}❌ 序号无效。${PLAIN}" "${RED}❌ The serial number is invalid.${PLAIN}" "${RED}❌ Серийный номер недействителен.${PLAIN}")"
            pause_return
            continue
        fi

        idx=$((choice - 1))
        domain="${domains[$idx]}"
        current_ranges=$(sni_ip_whitelist_ranges_for_domain "$domain")
        echo -e "$(localized_text "当前域名：${domain}" "Current domain: ${domain}" "Текущее доменное имя: ${domain}.")"
        echo -e "$(localized_text "当前白名单：${current_ranges:-未启用}" "Current whitelist: ${current_ranges:-未启用}" "Текущий белый список: ${current_ranges:-未启用}.")"
        echo -e "$(localized_text "1. 设置/覆盖白名单" "1. Set/override whitelist" "1. Установить/переопределить белый список")"
        echo -e "$(localized_text "2. 清除白名单" "2. Clear the whitelist" "2. Очистите белый список")"
        echo -e "$(localized_text "0/q. 取消" "0/q. Cancel" "0/кв. Отмена")"
        read_trimmed action "$(localized_text "请选择操作: " "Please select an action:" "Пожалуйста, выберите действие:")"
        case "$action" in
            1)
                if [[ "$whitelist_supported" != "yes" ]]; then
                    echo -e "$(localized_text "${RED}❌ 当前组合禁止设置 Web 白名单。请先切换入口模式或 Web 反代引擎。${PLAIN}" "${RED}❌ The current combination prohibits setting the Web whitelist. Please switch to entry mode or web reverse proxy engine first.${PLAIN}" "${RED}❌ Текущая комбинация запрещает настройку белого списка Интернета. Пожалуйста, сначала переключитесь в режим входа или в механизм веб-прокси.${PLAIN}")"
                    pause_return
                    continue
                fi
                current_client_ip=$(detect_ssh_client_ip)
                [[ -n "$current_client_ip" ]] && echo -e "$(localized_text "${YELLOW}当前 SSH 来源 IP 可能是：${current_client_ip}，请确认已加入白名单。${PLAIN}" "${YELLOW}The current source IP of SSH may be: ${current_client_ip}. Please confirm that it has been added to the whitelist.${PLAIN}" "${YELLOW}Текущий исходный IP-адрес SSH может быть: ${current_client_ip}. Пожалуйста, подтвердите, что он был добавлен в белый список.${PLAIN}")"
                read_trimmed whitelist_input "$(localized_text "请输入允许访问 ${domain} 的 IP/CIDR（多个用空格或英文逗号分隔）: " "Please enter the IP/CIDR that allows access to ${domain} (separate multiple by spaces or commas):" "Введите IP/CIDR, который разрешает доступ к ${domain} (разделяйте кратные пробелами или запятыми):")"
                if ! normalize_ip_whitelist_input "$whitelist_input" whitelist_array; then
                    echo -e "$(localized_text "${RED}❌ 白名单为空或格式错误，已取消。${PLAIN}" "${RED}❌ The whitelist is empty or has an incorrect format and has been cancelled.${PLAIN}" "${RED}❌ Белый список пуст или имеет неверный формат и был отменен.${PLAIN}")"
                    pause_return
                    continue
                fi
                append_vps_public_ips_to_whitelist whitelist_array
                whitelist_ranges=$(join_array_by_space "${whitelist_array[@]}")
                confirm_risk_action "$(localized_text "为 ${domain} 启用 IP 白名单" "Enable IP whitelisting for ${domain}" "Включить белый список IP-адресов для ${domain}")" \
                    "$(localized_text "443 入口层会仅对该 SNI 做源 IP 限制" "443 The entry layer will only restrict the source IP of SNI." "443 Входной уровень будет ограничивать только исходный IP-адрес SNI.")" \
                    "$(localized_text "使用 443端口复用自动备份回滚，或清除该域名白名单后重新应用" "Use the Port 443 Reuse to automatically back up and roll back, or clear the domain whitelist and reapply it." "Используйте автоматическое резервное копирование и откат повторного использования порта 443 или очистите белый список доменных имен и примените его повторно.")" \
                    "$(localized_text "确认你的管理 IP 已包含在白名单中，且该域名不是 Cloudflare 橙云代理访问。" "Confirm that your management IP is included in the whitelist and the domain is not Cloudflare Orange Cloud proxy access." "Убедитесь, что ваш IP-адрес управления включен в белый список, а имя домена не является Cloudflare для доступа к прокси-серверу Orange Cloud.")" || continue
                set_sni_ip_whitelist_for_domain "$domain" "$whitelist_ranges"
                save_and_offer_reapply_sni_stack
                ;;
            2)
                if [[ -z "$current_ranges" ]]; then
                    echo -e "$(localized_text "${BLUE}该域名未启用白名单。${PLAIN}" "${BLUE}This domain is not whitelisted.${PLAIN}" "${BLUE}Это доменное имя не внесено в белый список.${PLAIN}")"
                    pause_return
                    continue
                fi
                confirm_risk_action "$(localized_text "清除 ${domain} 的 IP 白名单" "Clear the IP whitelist of ${domain}" "Очистите белый список IP-адресов ${domain}.")" \
                    "$(localized_text "该域名会恢复为普通 443 分流访问" "The domain will be restored to normal 443 redirection access" "Для доменного имени будет восстановлен обычный доступ к перенаправлению 443.")" \
                    "$(localized_text "重新设置该域名白名单" "Reset the domain whitelist" "Сбросить белый список доменных имен")" \
                    "$(localized_text "确认这是你想要的公网访问策略。" "Confirm that this is the public access policy you want." "Подтвердите, что это именно та политика доступа к публичной сети, которая вам нужна.")" || continue
                remove_sni_ip_whitelist_for_domain "$domain"
                save_and_offer_reapply_sni_stack
                ;;
            0|q|Q|"")
                ;;
            *)
                echo -e "$(localized_text "${RED}❌ 无效操作。${PLAIN}" "${RED}❌ Invalid operation.${PLAIN}" "${RED}❌ Недопустимая операция.${PLAIN}")"
                pause_return
                ;;
        esac
    done
}

# ---------------------------------------------------------
# Module: reality_guard.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# REALITY fallback traffic controls for the shared 443 entry.

normalize_strict_sni_gate() {
    case "${1:-false}" in
        1|true|TRUE|yes|YES|on|ON) printf '%s' "true" ;;
        *) printf '%s' "false" ;;
    esac
}

strict_sni_gate_enabled() {
    [[ "$(normalize_strict_sni_gate "${STRICT_SNI_GATE:-false}")" == "true" ]]
}

registered_443_snis() {
    printf '%s\n' "${PANEL_DOMAIN:-}" "${SITE_DOMAINS[@]:-}" "${TCP_ROUTE_SNIS[@]:-}" "${XRAY_SNI_ROUTE_SNIS[@]:-}" "${REALITY_SNI:-}" |
        awk 'NF && !seen[tolower($0)]++'
}

strict_sni_gate_mode_supported() {
    local mode="${1:-$(get_entry_mode)}"
    [[ "$mode" == "nginx-stream" || "$mode" == "tcp-peek" ]]
}

print_strict_sni_gate_summary() {
    local state mode
    mode=$(get_entry_mode)
    if strict_sni_gate_enabled && strict_sni_gate_mode_supported "$mode"; then
        state="$(localized_text "${GREEN}已启用${PLAIN}" "${GREEN}Enabled${PLAIN}" "${GREEN}Включён${PLAIN}")"
    elif strict_sni_gate_enabled; then
        state="$(localized_text "${YELLOW}已保存，当前模式不生效${PLAIN}" "${YELLOW}Saved, inactive in the current mode${PLAIN}" "${YELLOW}Сохранён, не действует в текущем режиме${PLAIN}")"
    else
        state="$(localized_text "${YELLOW}未启用${PLAIN}" "${YELLOW}Disabled${PLAIN}" "${YELLOW}Выключен${PLAIN}")"
    fi
    echo -e "$(localized_text "严格 SNI 门禁：${state}" "Strict SNI gate: ${state}" "Строгий контроль SNI: ${state}")"
    echo -e "$(localized_text "当前入口模式：${mode}" "Current entry mode: ${mode}" "Текущий режим входа: ${mode}")"
    echo -e "$(localized_text "自动放行的已登记 SNI：" "Automatically allowed registered SNIs:" "Автоматически разрешённые зарегистрированные SNI:")"
    registered_443_snis | sed 's/^/  - /'
}

sync_strict_sni_gate_to_current_entry() {
    local mode
    mode=$(get_entry_mode)
    case "$mode" in
        nginx-stream) reapply_sni_stack_from_env --yes ;;
        tcp-peek) sync_xray_sni_routes_to_entry_mode ;;
        xray-fallback)
            echo -e "$(localized_text "${YELLOW}xray-fallback 由 Xray 直接监听公网 443，没有独立前置门禁；请使用 REALITY 回落限速。${PLAIN}" "${YELLOW}In xray-fallback mode, Xray listens on public port 443 directly, so there is no separate front gate. Use REALITY fallback rate limiting instead.${PLAIN}" "${YELLOW}В режиме xray-fallback Xray напрямую слушает публичный порт 443, поэтому отдельного входного фильтра нет. Используйте ограничение скорости REALITY fallback.${PLAIN}")"
            return 1
            ;;
        *) return 1 ;;
    esac
}

set_strict_sni_gate() {
    local target="$1" mode
    load_sni_stack_env || return 1
    mode=$(get_entry_mode)
    if [[ "$target" == "true" ]] && ! strict_sni_gate_mode_supported "$mode"; then
        echo -e "$(localized_text "${RED}当前模式不支持前置严格 SNI 门禁。${PLAIN}" "${RED}The current mode does not support a front strict SNI gate.${PLAIN}" "${RED}Текущий режим не поддерживает строгий входной контроль SNI.${PLAIN}")"
        return 1
    fi
    if [[ "$target" == "true" ]]; then
        confirm_danger "$(localized_text "启用严格 SNI 门禁" "Enable the strict SNI gate" "Включить строгий контроль SNI")" \
            "$(localized_text "未登记或不带 SNI 的连接会被直接丢弃，并重新应用当前入口" "drop connections with an unregistered or missing SNI and reapply the current entry" "отклонять подключения с незарегистрированным или отсутствующим SNI и повторно применить текущую точку входа")" \
            "$(localized_text "可重新进入本菜单关闭门禁；已登记的 SNI 清单不会删除" "disable the gate from this menu; the registered SNI list is retained" "контроль можно отключить в этом меню; список зарегистрированных SNI сохранится")" || return 0
    else
        confirm_danger "$(localized_text "关闭严格 SNI 门禁" "Disable the strict SNI gate" "Отключить строгий контроль SNI")" \
            "$(localized_text "未知 SNI 将恢复转发到默认 Xray 后端，并重新应用当前入口" "resume forwarding unknown SNI to the default Xray backend and reapply the current entry" "возобновить пересылку неизвестных SNI на стандартный бэкенд Xray и повторно применить текущую точку входа")" \
            "$(localized_text "可重新进入本菜单启用门禁" "enable the gate again from this menu" "контроль можно снова включить в этом меню")" || return 0
    fi
    STRICT_SNI_GATE="$target"
    save_sni_stack_env
    if sync_strict_sni_gate_to_current_entry; then
        echo -e "$(localized_text "${GREEN}✅ 严格 SNI 门禁已保存并同步到当前入口。${PLAIN}" "${GREEN}✅ The strict SNI gate was saved and synchronized to the current entry.${PLAIN}" "${GREEN}✅ Строгий контроль SNI сохранён и применён к текущему входу.${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}设置已保存，但未能同步到当前入口；请修复入口后重新应用。${PLAIN}" "${YELLOW}The setting was saved but could not be synchronized to the current entry. Fix the entry and reapply it.${PLAIN}" "${YELLOW}Настройка сохранена, но не применена к текущему входу. Исправьте вход и повторите применение.${PLAIN}")"
        return 1
    fi
}

reality_guard_python() {
    python3 - "$@" <<'PY'
import copy
import json
import sqlite3
import sys

operation, db_path = sys.argv[1:3]
conn = sqlite3.connect(db_path)
conn.row_factory = sqlite3.Row
columns = {row[1] for row in conn.execute("pragma table_info(inbounds)")}
required = {"id", "port", "remark", "stream_settings"}
if not required.issubset(columns):
    raise SystemExit("unsupported inbounds schema")

def parse(row):
    try:
        stream = json.loads(row["stream_settings"] or "{}")
    except (TypeError, json.JSONDecodeError):
        return None
    if str(stream.get("security", "")).lower() != "reality":
        return None
    reality = stream.get("realitySettings")
    return stream if isinstance(reality, dict) else None

if operation == "list":
    for row in conn.execute("select id, port, remark, stream_settings from inbounds order by id"):
        stream = parse(row)
        if stream is None:
            continue
        reality = stream["realitySettings"]
        names = ",".join(str(item) for item in reality.get("serverNames", []) if item)
        upload = reality.get("limitFallbackUpload") or {}
        download = reality.get("limitFallbackDownload") or {}
        enabled = bool(upload.get("bytesPerSec", 0) or download.get("bytesPerSec", 0))
        remark = str(row["remark"] or "-").replace("\t", " ").replace("\n", " ")
        print(f"{row['id']}\t{row['port']}\t{remark}\t{names or '-'}\t{'enabled' if enabled else 'disabled'}")
    raise SystemExit(0)

inbound_id = int(sys.argv[3])
row = conn.execute("select id, port, remark, stream_settings from inbounds where id=?", (inbound_id,)).fetchone()
if row is None:
    raise SystemExit("inbound not found")
stream = parse(row)
if stream is None:
    raise SystemExit("selected inbound is not REALITY")
original = copy.deepcopy(stream)
reality = stream["realitySettings"]
if operation == "clear":
    reality.pop("limitFallbackUpload", None)
    reality.pop("limitFallbackDownload", None)
elif operation == "apply":
    values = [int(item) for item in sys.argv[4:10]]
    if any(item < 0 for item in values):
        raise SystemExit("rate-limit values must be non-negative")
    reality["limitFallbackUpload"] = dict(zip(("afterBytes", "bytesPerSec", "burstBytesPerSec"), values[:3]))
    reality["limitFallbackDownload"] = dict(zip(("afterBytes", "bytesPerSec", "burstBytesPerSec"), values[3:]))
else:
    raise SystemExit("unsupported operation")

expected = copy.deepcopy(original)
expected_reality = expected["realitySettings"]
if operation == "clear":
    expected_reality.pop("limitFallbackUpload", None)
    expected_reality.pop("limitFallbackDownload", None)
else:
    expected_reality["limitFallbackUpload"] = reality["limitFallbackUpload"]
    expected_reality["limitFallbackDownload"] = reality["limitFallbackDownload"]
if stream != expected:
    raise SystemExit("refusing to modify fields outside fallback limits")

payload = json.dumps(stream, ensure_ascii=False, separators=(",", ":"))
conn.execute("begin immediate")
cursor = conn.execute(
    "update inbounds set stream_settings=? where id=? and stream_settings=?",
    (payload, inbound_id, row["stream_settings"]),
)
if cursor.rowcount != 1:
    conn.rollback()
    raise SystemExit("inbound changed concurrently")
conn.commit()
saved = conn.execute("select stream_settings from inbounds where id=?", (inbound_id,)).fetchone()[0]
if json.loads(saved) != expected:
    raise SystemExit("post-write verification failed")
PY
}

find_reality_guard_database() {
    local db_path
    while IFS= read -r db_path; do
        [[ -f "$db_path" ]] || continue
        if [[ -n "$(reality_guard_python list "$db_path" 2>/dev/null | head -n1)" ]]; then
            printf '%s' "$db_path"
            return 0
        fi
    done < <(find_xui_database_candidates)
    return 1
}

backup_reality_guard_database() {
    local db_path="$1" inbound_id="$2" backup_dir backup_file timestamp
    timestamp=$(date +%Y%m%d_%H%M%S)
    backup_dir="/root/x-ui-backups"
    backup_file="${backup_dir}/$(basename "$db_path").reality_guard_${inbound_id}_${timestamp}.bak"
    mkdir -p "$backup_dir"
    sqlite3 "$db_path" ".backup '${backup_file}'" >/dev/null 2>&1 || return 1
    printf '%s' "$backup_file"
}

restart_reality_guard_panel_service() {
    local service_name
    for service_name in x-ui 3x-ui x-panel; do
        if systemd_unit_exists "${service_name}.service"; then
            systemctl restart "$service_name" >/dev/null 2>&1 && systemctl is-active --quiet "$service_name" && return 0
            return 1
        fi
    done
    return 2
}

show_reality_guard_inbounds() {
    local db_path="$1" id port remark server_names state state_text
    echo -e "$(localized_text "ID  端口  名称  serverNames  回落限速" "ID  Port  Name  serverNames  Fallback limit" "ID  Порт  Имя  serverNames  Ограничение fallback")"
    while IFS=$'\t' read -r id port remark server_names state; do
        [[ -n "$id" ]] || continue
        if [[ "$state" == "enabled" ]]; then
            state_text="$(localized_text "已启用" "enabled" "включено")"
        else
            state_text="$(localized_text "未启用" "disabled" "выключено")"
        fi
        printf '%-3s %-5s %s | %s | %s\n' "$id" "$port" "$remark" "$server_names" "$state_text"
    done < <(reality_guard_python list "$db_path")
}

patch_reality_fallback_limits() {
    local operation="${1:-apply}" db_path inbound_id backup_file result
    local upload_after upload_rate upload_burst download_after download_rate download_burst
    load_sni_stack_env || return 1
    if xui_uses_postgresql; then
        echo -e "$(localized_text "${RED}检测到 PostgreSQL。为避免误改远程数据库，此功能仅支持本机 3x-ui SQLite。${PLAIN}" "${RED}PostgreSQL was detected. To avoid modifying a remote database by mistake, this function supports only local 3x-ui SQLite.${PLAIN}" "${RED}Обнаружен PostgreSQL. Чтобы исключить ошибочное изменение удалённой базы, функция поддерживает только локальный SQLite 3x-ui.${PLAIN}")"
        return 1
    fi
    command -v python3 >/dev/null 2>&1 || install_pkg python3 python3 >/dev/null 2>&1 || true
    command -v sqlite3 >/dev/null 2>&1 || install_pkg sqlite3 sqlite >/dev/null 2>&1 || true
    if ! command -v python3 >/dev/null 2>&1 || ! command -v sqlite3 >/dev/null 2>&1; then
        echo -e "$(localized_text "${RED}需要 python3 和 sqlite3，自动安装失败。${PLAIN}" "${RED}python3 and sqlite3 are required, and automatic installation failed.${PLAIN}" "${RED}Требуются python3 и sqlite3; автоматическая установка не удалась.${PLAIN}")"
        return 1
    fi
    db_path=$(find_reality_guard_database) || { echo -e "$(localized_text "${RED}未找到包含 REALITY 入站的 3x-ui SQLite 数据库。${PLAIN}" "${RED}No 3x-ui SQLite database containing a REALITY inbound was found.${PLAIN}" "${RED}Не найдена база SQLite 3x-ui с входящим REALITY.${PLAIN}")"; return 1; }
    echo -e "$(localized_text "数据库：${db_path}" "Database: ${db_path}" "База данных: ${db_path}")"
    show_reality_guard_inbounds "$db_path"
    read_trimmed inbound_id "$(localized_text "输入要处理的 REALITY 入站 ID（0 取消）: " "Enter the REALITY inbound ID to modify (0 cancels): " "Введите ID входящего REALITY (0 — отмена): ")"
    [[ "$inbound_id" == "0" || -z "$inbound_id" ]] && return 0
    [[ "$inbound_id" =~ ^[0-9]+$ ]] || { echo -e "$(localized_text "${RED}入站 ID 无效。${PLAIN}" "${RED}Invalid inbound ID.${PLAIN}" "${RED}Недопустимый ID входящего подключения.${PLAIN}")"; return 1; }

    if [[ "$operation" == "apply" ]]; then
        upload_after=$((10485760 + (RANDOM % 4194305) - 2097152))
        upload_rate=$((1048576 + (RANDOM % 419431) - 209715))
        upload_burst=$((5242880 + (RANDOM % 2097153) - 1048576))
        download_after=$((10485760 + (RANDOM % 4194305) - 2097152))
        download_rate=$((1048576 + (RANDOM % 419431) - 209715))
        download_burst=$((5242880 + (RANDOM % 2097153) - 1048576))
        echo -e "$(localized_text "将使用本次随机生成的回落限速参数（字节）：" "Randomized fallback limits for this operation (bytes):" "Случайные параметры ограничения fallback для этой операции (байты):")"
        echo "  upload:   afterBytes=${upload_after}, bytesPerSec=${upload_rate}, burstBytesPerSec=${upload_burst}"
        echo "  download: afterBytes=${download_after}, bytesPerSec=${download_rate}, burstBytesPerSec=${download_burst}"
        confirm_danger "$(localized_text "设置 REALITY 回落限速" "Set REALITY fallback rate limits" "Настроить ограничение REALITY fallback")" \
            "$(localized_text "只修改所选入站的两个 limitFallback 字段，并重启面板/Xray" "change only the two limitFallback fields of the selected inbound, then restart the panel/Xray" "изменить только два поля limitFallback выбранного входящего подключения, затем перезапустить панель/Xray")" \
            "$(localized_text "脚本会先备份数据库；可用本菜单清除限速或从备份恢复" "the database is backed up first; clear the limits from this menu or restore the backup" "сначала будет создана резервная копия базы; ограничения можно удалить в этом меню или восстановить базу из копии")" || return 0
    else
        confirm_danger "$(localized_text "清除 REALITY 回落限速" "Clear REALITY fallback rate limits" "Удалить ограничение REALITY fallback")" \
            "$(localized_text "删除所选入站的两个 limitFallback 字段，并重启面板/Xray" "remove the two limitFallback fields from the selected inbound, then restart the panel/Xray" "удалить два поля limitFallback выбранного входящего подключения, затем перезапустить панель/Xray")" \
            "$(localized_text "脚本会先备份数据库；可从备份恢复原参数" "the database is backed up first; restore the original values from the backup" "сначала будет создана резервная копия базы; исходные значения можно восстановить из неё")" || return 0
    fi

    backup_file=$(backup_reality_guard_database "$db_path" "$inbound_id") || { echo -e "$(localized_text "${RED}数据库备份失败，未执行修改。${PLAIN}" "${RED}Database backup failed; no changes were made.${PLAIN}" "${RED}Не удалось создать резервную копию базы; изменения не внесены.${PLAIN}")"; return 1; }
    if [[ "$operation" == "apply" ]]; then
        reality_guard_python apply "$db_path" "$inbound_id" "$upload_after" "$upload_rate" "$upload_burst" "$download_after" "$download_rate" "$download_burst" || result=$?
    else
        reality_guard_python clear "$db_path" "$inbound_id" || result=$?
    fi
    if [[ "${result:-0}" -ne 0 ]]; then
        echo -e "$(localized_text "${RED}入站更新失败，数据库保持原样。备份：${backup_file}${PLAIN}" "${RED}Inbound update failed; the database remains unchanged. Backup: ${backup_file}${PLAIN}" "${RED}Не удалось обновить входящее подключение; база не изменена. Резервная копия: ${backup_file}${PLAIN}")"
        return 1
    fi
    if restart_reality_guard_panel_service; then
        echo -e "$(localized_text "${GREEN}✅ REALITY 回落限速已更新并生效。数据库备份：${backup_file}${PLAIN}" "${GREEN}✅ REALITY fallback rate limiting was updated and activated. Database backup: ${backup_file}${PLAIN}" "${GREEN}✅ Ограничение скорости REALITY fallback обновлено и применено. Резервная копия: ${backup_file}${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}数据库已更新，但未检测到可成功重启的面板服务。请手动重启并检查 Xray；备份：${backup_file}${PLAIN}" "${YELLOW}The database was updated, but no panel service could be restarted successfully. Restart it manually and check Xray. Backup: ${backup_file}${PLAIN}" "${YELLOW}База обновлена, но службу панели не удалось перезапустить. Перезапустите её вручную и проверьте Xray. Резервная копия: ${backup_file}${PLAIN}")"
        return 1
    fi
}

manage_reality_traffic_guard() {
    while true; do
        local postgresql_mode=0
        clear
        load_sni_stack_env || return 1
        xui_uses_postgresql && postgresql_mode=1
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}REALITY 回落流量防护${PLAIN}" "${BOLD}REALITY fallback traffic protection${PLAIN}" "${BOLD}Защита трафика REALITY fallback${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "REALITY 验证失败的连接会转发到 target；使用 CDN 目标时可能被扫描后当作转发节点滥用。" "REALITY forwards failed-authentication connections to the target; a CDN target can make the server abusable as a relay after scanning." "REALITY пересылает подключения с ошибкой проверки на target; при CDN-цели сервер после сканирования может использоваться как ретранслятор.")"
        print_strict_sni_gate_summary
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 启用严格 SNI 门禁${PLAIN}      ${YELLOW}(仅放行自动登记的 SNI)${PLAIN}" "${GREEN}1. Enable strict SNI gate${PLAIN} (allow only automatically registered SNIs)" "${GREEN}1. Включить строгий контроль SNI${PLAIN} (только автоматически зарегистрированные SNI)")"
        echo -e "$(localized_text "${CYAN}  2. 关闭严格 SNI 门禁${PLAIN}      ${YELLOW}(恢复未知 SNI 默认转发)${PLAIN}" "${CYAN}2. Disable strict SNI gate${PLAIN} (restore default forwarding for unknown SNI)" "${CYAN}2. Отключить строгий контроль SNI${PLAIN} (вернуть стандартную пересылку неизвестных SNI)")"
        echo -e "$(localized_text "${CYAN}  3. 重新同步当前 SNI 清单${PLAIN}    ${YELLOW}(按已保存的域名和路由生成)${PLAIN}" "${CYAN}3. Resynchronize the current SNI list${PLAIN} (generated from saved domains and routes)" "${CYAN}3. Повторно синхронизировать список SNI${PLAIN} (из сохранённых доменов и маршрутов)")"
        if [[ "$postgresql_mode" -eq 1 ]]; then
            echo -e "$(localized_text "${YELLOW}  4. 设置 REALITY 回落限速${PLAIN}  ${RED}(不可用：仅支持本机 SQLite)${PLAIN}" "${YELLOW}4. Set REALITY fallback rate limits${PLAIN} ${RED}(unavailable: local SQLite only)${PLAIN}" "${YELLOW}4. Настроить ограничение REALITY fallback${PLAIN} ${RED}(недоступно: только локальный SQLite)${PLAIN}")"
            echo -e "$(localized_text "${YELLOW}  5. 清除 REALITY 回落限速${PLAIN}  ${RED}(不可用：仅支持本机 SQLite)${PLAIN}" "${YELLOW}5. Clear REALITY fallback rate limits${PLAIN} ${RED}(unavailable: local SQLite only)${PLAIN}" "${YELLOW}5. Удалить ограничение REALITY fallback${PLAIN} ${RED}(недоступно: только локальный SQLite)${PLAIN}")"
        else
            echo -e "$(localized_text "${GREEN}  4. 设置 REALITY 回落限速${PLAIN}  ${YELLOW}(仅修改两个 limitFallback 字段)${PLAIN}" "${GREEN}4. Set REALITY fallback rate limits${PLAIN} (changes only the two limitFallback fields)" "${GREEN}4. Настроить ограничение REALITY fallback${PLAIN} (только два поля limitFallback)")"
            echo -e "$(localized_text "${YELLOW}  5. 清除 REALITY 回落限速${PLAIN}  ${YELLOW}(恢复 Xray 默认行为)${PLAIN}" "${YELLOW}5. Clear REALITY fallback rate limits${PLAIN} (restore Xray defaults)" "${YELLOW}5. Удалить ограничение REALITY fallback${PLAIN} (вернуть настройки Xray по умолчанию)")"
        fi
        echo -e "$(localized_text "${RED}  0. 返回 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        local choice
        read_trimmed choice "$(localized_text "请选择操作: " "Select an action: " "Выберите действие: ")"
        case "$choice" in
            1) set_strict_sni_gate true ; pause_return ;;
            2) set_strict_sni_gate false ; pause_return ;;
            3)
                confirm_danger "$(localized_text "重新同步严格 SNI 清单" "Resynchronize the strict SNI list" "Повторно синхронизировать строгий список SNI")" \
                    "$(localized_text "重新生成当前入口配置；运行中的 Nginx 或 vpso-mux 可能重启" "regenerate the current entry configuration; the running Nginx or vpso-mux service may restart" "заново создать текущую конфигурацию точки входа; работающий Nginx или vpso-mux может быть перезапущен")" \
                    "$(localized_text "已保存的域名与路由不会删除；修正后可再次同步" "saved domains and routes are retained; correct them and synchronize again" "сохранённые домены и маршруты останутся; исправьте их и повторите синхронизацию")" && sync_strict_sni_gate_to_current_entry
                pause_return
                ;;
            4)
                if [[ "$postgresql_mode" -eq 1 ]]; then
                    echo -e "$(localized_text "${RED}当前 3x-ui 使用 PostgreSQL，回落限速仅支持本机 SQLite。${PLAIN}" "${RED}3x-ui currently uses PostgreSQL; fallback limits support only local SQLite.${PLAIN}" "${RED}3x-ui использует PostgreSQL; ограничение fallback поддерживает только локальный SQLite.${PLAIN}")"
                else
                    patch_reality_fallback_limits apply
                fi
                pause_return
                ;;
            5)
                if [[ "$postgresql_mode" -eq 1 ]]; then
                    echo -e "$(localized_text "${RED}当前 3x-ui 使用 PostgreSQL，回落限速仅支持本机 SQLite。${PLAIN}" "${RED}3x-ui currently uses PostgreSQL; fallback limits support only local SQLite.${PLAIN}" "${RED}3x-ui использует PostgreSQL; ограничение fallback поддерживает только локальный SQLite.${PLAIN}")"
                else
                    patch_reality_fallback_limits clear
                fi
                pause_return
                ;;
            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}无效选择。${PLAIN}" "${RED}Invalid selection.${PLAIN}" "${RED}Неверный выбор.${PLAIN}")"; sleep 1 ;;
        esac
    done
}

# ---------------------------------------------------------
# Module: sni_stack_menus.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Port 443 Reuse secondary menus for sites, routes, and web whitelist controls.

manage_sni_stack_sites() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}🌐 443 网站/反代域名管理${PLAIN}" "${BOLD}🌐 443 Web domain and reverse-proxy management${PLAIN}" "${BOLD}🌐 443 Управление Web-доменами и обратным прокси${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}管理已配置 443端口复用的网站和反代域名。${PLAIN}" "${YELLOW}Manage Web domains and reverse proxies after Port 443 Reuse is configured.${PLAIN}" "${YELLOW}Управляйте Web-доменами и обратными прокси после настройки повторного использования порта 443.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}新增网站只需填写域名和本机后端端口，无需重跑首次配置。${PLAIN}" "${YELLOW}To add a site, enter its domain and local backend port; do not rerun initial setup.${PLAIN}" "${YELLOW}Для нового сайта укажите домен и локальный порт бэкенда; первоначальная настройка не нужна.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 查看当前网站/反代域名${PLAIN}" "${GREEN}1. View current Web domains/reverse proxies${PLAIN}" "${GREEN}1. Показать текущие Web-домены и обратные прокси${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 新增网站/反代域名${PLAIN}" "${GREEN}2. Add a Web domain/reverse proxy${PLAIN}" "${GREEN}2. Добавить Web-домен и обратный прокси${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  3. 修改网站/反代后端${PLAIN}" "${GREEN}3. Edit a Web/reverse-proxy backend${PLAIN}" "${GREEN}3. Изменить бэкенд Web-сайта или обратного прокси${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  4. 删除网站/反代域名${PLAIN}" "${GREEN}4. Remove a Web domain/reverse proxy${PLAIN}" "${GREEN}4. Удалить Web-домен и обратный прокси${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  5. 管理域名 IP 白名单${PLAIN}       ${YELLOW}(只限制被选择的域名)${PLAIN}" "${GREEN}5. Manage domain IP allowlists (selected domains only)${PLAIN}" "${GREEN}5. Управление IP-белым списком доменов (только выбранные домены)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  6. 重新应用并重启 Nginx/Caddy${PLAIN}" "${GREEN}6. Reapply configuration and restart Nginx/Caddy${PLAIN}" "${GREEN}6. Повторно применить конфигурацию и перезапустить Nginx/Caddy${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  7. 443端口复用链路体检${PLAIN}" "${GREEN}7. Port 443 Reuse diagnostics${PLAIN}" "${GREEN}7. Диагностика повторного использования порта 443${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  8. 切换 Web 反代引擎${PLAIN}       ${YELLOW}(Caddy / Nginx 本地反代)${PLAIN}" "${GREEN}8. Switch the Web reverse-proxy engine (local Caddy/Nginx)${PLAIN}" "${GREEN}8. Сменить Web-движок обратного прокси (локальный Caddy/Nginx)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  9. 修改面板域名${PLAIN}" "${GREEN}9. Change the panel domain${PLAIN}" "${GREEN}9. Изменить домен панели${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${BLUE}  ?. 查看帮助${PLAIN}" "${BLUE}?. View help${PLAIN}" "${BLUE}?. Посмотреть справку${PLAIN}")"
        echo -e "$(localized_text "${RED}  0. 返回上一级 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local choice
        read_trimmed choice "$(localized_text "请输入菜单编号或 ?: " "Select a menu number or ?:" "Выберите номер меню или ?:")"
        case "$choice" in
            1) list_sni_stack_sites ;;
            2) add_sni_stack_site ;;
            3) edit_sni_stack_site_backend ;;
            4) remove_sni_stack_site ;;
            5) manage_sni_stack_ip_whitelist ;;
            6) reapply_sni_stack_from_env ;;
            7) sni_stack_health_check ;;
            8) switch_sni_stack_web_proxy_engine ;;
            9) edit_sni_stack_panel_domain_profile ;;
            "?") show_sni_help; pause_return; continue ;;
            0) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择，请输入菜单编号或 ?。${PLAIN}" "${RED}❌ Invalid selection, please enter the menu number or ?.${PLAIN}" "${RED}❌ Неверный выбор, введите номер меню или ?.${PLAIN}")" ;;
        esac
        echo ""
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    done
}

# ---------------------------------------------------------
# Module: caddy_maintenance.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Cloudflare/Caddy certificate maintenance, Caddy config repair, whitelist, and cleanup tools.

func_caddy_cf_reality_wizard() {
    if [[ -f /etc/vps-optimize/sni-stack.env ]]; then
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}检测到已有 443端口复用配置${PLAIN}" "${BOLD}Detects that there are already Port 443 Reuse configurations${PLAIN}" "${BOLD}обнаружил, что существует 443 конфигурации с повторным использованием порта 443.${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}如果只是新增网站或反代域名，请返回并选择 [8] 管理 Web 域名/反代。${PLAIN}" "${YELLOW}If you are just adding a new website or reverse proxy domain, please go back and select [8] Manage Web domain/Reverse proxy.${PLAIN}" "${YELLOW}Если вы просто добавляете новый веб-сайт или доменное имя обратного прокси, вернитесь назад и выберите [8] Управление именем веб-домена/обратным прокси.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}继续首次配置会重写 443 入口、Web 反代引擎和 Xray 分流相关核心配置。${PLAIN}" "${YELLOW}Continuing initial setup will rewrite the port 443 entry, Web reverse proxy, and Xray routing configuration.${PLAIN}" "${YELLOW}Продолжение первоначальной настройки перезапишет конфигурацию входа 443, веб-прокси и маршрутизации Xray.${PLAIN}")"
        echo -e "------------------------------------------------"
        grep -E '^(PANEL_DOMAIN|PANEL_WEB_PATH|REALITY_SNI|NGINX_LISTEN_ADDR|NGINX_LISTEN_PORT|CADDY_LISTEN_PORT|XRAY_LISTEN_PORT|SUB_URI_PATH|CLASH_URI_PATH)=' /etc/vps-optimize/sni-stack.env 2>/dev/null || true
        echo -e "------------------------------------------------"
        confirm_danger "$(localized_text "重新执行 443 首次配置" "Re-execute 443 initial setup" "Повторно выполнить конфигурацию 443 при первом запуске.")" "$(localized_text "将基于新输入重写 443端口复用核心配置，并重启入口服务/Caddy。" "The Port 443 Reuse core configuration will be rewritten based on the new input and the entry service/Caddy will be restarted." "Конфигурация ядра повторного использования порта 443 будет переписана на основе новых входных данных, а служба входа/Caddy будет перезапущена.")" "$(localized_text "脚本会先创建备份，可从 443 维护菜单或备份目录回滚。" "The script will first create a backup, which can be rolled back from the 443 maintenance menu or the backup directory." "Скрипт сначала создаст резервную копию, откат которой можно выполнить из меню обслуживания 443 или каталога резервных копий.")" || return 1
    fi
    select_initial_entry_mode || return 1
    collect_sni_stack_config || return 1
    probe_reality_sni "$REALITY_SNI" || return 1
    print_sni_stack_preview || return 1
    guard_current_ssh_not_on_entry_port "$(localized_text "首次配置 443端口复用" "Initial Port 443 Reuse setup" "Первоначальная настройка повторного использования порта 443")" || return 1
    local cf_env_dir="/root/.config/vps-panel"
    local cf_env_file="${cf_env_dir}/cloudflare.env"
    local escaped_token
    mkdir -p "$cf_env_dir"
    chmod 700 "$cf_env_dir"
    escaped_token=${CF_TOKEN//\'/\'"\'"\'}
    printf "CF_Token='%s'\n" "$escaped_token" > "$cf_env_file"
    chmod 600 "$cf_env_file"

    local backup_dir
    backup_dir=$(backup_entry_mode_config) || return 1
    prepare_initial_entry_mode_dependencies "$ENTRY_MODE" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "入口模式依赖检查失败" "Entry mode dependency check failed" "Проверка зависимости режима входа не удалась")"; return 1; }
    quarantine_legacy_caddy_443_configs
    quarantine_legacy_nginx_https_proxy_configs
    issue_and_install_cert_for_domain "$PANEL_DOMAIN" "$CF_TOKEN" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "面板域名证书签发/安装失败" "Panel domain certificate issuance/installation failed" "Не удалось выдать/установить сертификат доменного имени панели.")"; return 1; }
    if [[ ${#SITE_DOMAINS[@]} -gt 0 ]]; then
        local site_domain
        for site_domain in "${SITE_DOMAINS[@]}"; do
            [[ -z "$site_domain" ]] && continue
            issue_and_install_cert_for_domain "$site_domain" "$CF_TOKEN" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "站点域名 ${site_domain} 证书签发/安装失败" "Site domain ${site_domain} certificate issuance/installation failed" "Доменное имя сайта ${site_domain} не удалось выдать/установить сертификат")"; return 1; }
        done
    fi
    preflight_entry_mode_before_cutover "$ENTRY_MODE" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "入口模式 ${ENTRY_MODE} 预检失败，公网 443 未切换" "entry mode ${ENTRY_MODE} preflight failed, public port 443 not switched" "Режим входа в предполетный режим ${ENTRY_MODE} не выполнен, публичный порт 443 не переключена")"; return 1; }
    stop_public_443_entry_services_for_target "$ENTRY_MODE" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "停止旧公网 443 入口服务失败" "Stop the old public port 443 entry service failed" "Остановить старую публичную сеть 443, служба входа не удалась")"; return 1; }
    apply_entry_mode_by_name "$ENTRY_MODE" "$backup_dir" || { rollback_sni_stack_after_failure "$backup_dir" "$(localized_text "入口模式 ${ENTRY_MODE} 应用失败" "Entry mode ${ENTRY_MODE} application failed" "Режим входа в приложение ${ENTRY_MODE} не выполнен.")"; return 1; }
    save_sni_stack_env
    harden_single_443_firewall
    generate_caddy_cf_manifest
    print_sni_stack_result
}

func_caddy_cf_health_check() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🩺 CF DNS 一键体检${PLAIN}" "${BOLD}🩺 CF DNS One-click health check${PLAIN}" "${BOLD}🩺 CF DNS проверка состояния в один клик${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"

    local ok_count=0
    local warn_count=0
    local err_count=0
    local cf_env_file="/root/.config/vps-panel/cloudflare.env"

    echo -e "$(localized_text "${YELLOW}▶ [1/5] 检查 Cloudflare Token ...${PLAIN}" "${YELLOW}▶ [1/5] Check Cloudflare Token ...${PLAIN}" "${YELLOW}▶ [1/5] Проверить токен Cloudflare ...${PLAIN}")"
    if [[ -f "$cf_env_file" ]]; then
        # shellcheck disable=SC1090
        source "$cf_env_file"
        if [[ -n "$CF_Token" ]]; then
            if command -v curl >/dev/null 2>&1; then
                local verify_resp
                verify_resp=$(curl -s --max-time 8 -H "Authorization: Bearer ${CF_Token}" -H "Content-Type: application/json" "https://api.cloudflare.com/client/v4/user/tokens/verify" 2>/dev/null)
                if echo "$verify_resp" | grep -q '"success"[[:space:]]*:[[:space:]]*true'; then
                    echo -e "$(localized_text "${GREEN}✅ Cloudflare Token 校验通过${PLAIN}" "${GREEN}✅ Cloudflare Token verification passed${PLAIN}" "${GREEN}✅ Cloudflare Проверка токена пройдена${PLAIN}")"
                    ((ok_count++))
                else
                    echo -e "$(localized_text "${YELLOW}⚠️ Token 文件存在，但在线校验失败（可能权限不足/网络异常）${PLAIN}" "${YELLOW}⚠️ The Token file exists, but the online verification failed (maybe insufficient permissions/network abnormality)${PLAIN}" "${YELLOW}⚠️ Файл токена существует, но онлайн-проверка не удалась (возможно, недостаточные разрешения/неисправность сети)${PLAIN}")"
                    ((warn_count++))
                fi
            else
                echo -e "$(localized_text "${YELLOW}⚠️ 未安装 curl，跳过在线校验。${PLAIN}" "${YELLOW}⚠️ curl is not installed, skip online verification.${PLAIN}" "${YELLOW}⚠️ curl не установлен, пропустите онлайн-проверку.${PLAIN}")"
                ((warn_count++))
            fi
        else
            echo -e "$(localized_text "${RED}❌ Token 文件为空，请在维护菜单 [2] 重新写入。${PLAIN}" "${RED}❌ Token file is empty, please rewrite it in the maintenance menu [2].${PLAIN}" "${RED}❌ Файл токена пуст, перезапишите его в меню обслуживания [2].${PLAIN}")"
            ((err_count++))
        fi
    else
        echo -e "$(localized_text "${RED}❌ 未找到 Token 文件: ${cf_env_file}${PLAIN}" "${RED}❌ Token file not found: ${cf_env_file}${PLAIN}" "${RED}❌ Файл токена не найден: ${cf_env_file}${PLAIN}")"
        ((err_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [2/5] 检查 Caddy 服务状态...${PLAIN}" "${YELLOW}▶ [2/5] Check Caddy service status...${PLAIN}" "${YELLOW}▶ [2/5] Проверьте статус службы Caddy...${PLAIN}")"
    if command -v caddy >/dev/null 2>&1; then
        if systemctl is-active --quiet caddy; then
            echo -e "$(localized_text "${GREEN}✅ Caddy 服务运行中${PLAIN}" "${GREEN}✅ Caddy service is running${PLAIN}" "${GREEN}✅ Служба Caddy запущена${PLAIN}")"
            ((ok_count++))
        else
            echo -e "$(localized_text "${YELLOW}⚠️ Caddy 已安装但未运行${PLAIN}" "${YELLOW}⚠️ Caddy is installed but not running${PLAIN}" "${YELLOW}⚠️ Caddy установлен, но не работает${PLAIN}")"
            ((warn_count++))
        fi
    else
        echo -e "$(localized_text "${RED}❌ 未安装 Caddy${PLAIN}" "${RED}❌ Not installed Caddy${PLAIN}" "${RED}❌ Не установлено Caddy${PLAIN}")"
        ((err_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [3/5] 检查域名配置、证书与软链接...${PLAIN}" "${YELLOW}▶ [3/5] Check domain configuration, certificate and symlink...${PLAIN}" "${YELLOW}▶ [3/5] Проверьте конфигурацию доменного имени, сертификат и программную ссылку...${PLAIN}")"
    local domain_count=0
    if [[ -d /etc/caddy/conf.d ]]; then
        while IFS= read -r conf_file; do
            local domain
            local listen_addr
            local listen_port
            local listen_target
            local backend
            local backend_addr
            local backend_port
            local cert_file
            local key_file
            local cert_end
            local cert_ts
            local now_ts
            local days_left

            domain=$(basename "$conf_file" .caddy)
            cert_file="/etc/caddy/certs/${domain}.crt"
            key_file="/etc/caddy/certs/${domain}.key"

            if ! head -n1 "$conf_file" | grep -q '^https://'; then
                continue
            fi
            ((domain_count++))

            listen_addr=$(caddy_conf_site_bind_addr "$conf_file")
            listen_port=$(caddy_conf_site_listen_port "$conf_file")
            listen_target=$(caddy_conf_site_listen_target "$conf_file")
            backend=$(caddy_conf_first_reverse_proxy_target "$conf_file")
            backend_addr=$(caddy_reverse_proxy_target_host "$backend")
            backend_port=$(caddy_reverse_proxy_target_port "$backend")

            echo -e "$(localized_text "${CYAN}  - 域名: ${domain}${PLAIN}" "${CYAN}- domain: ${domain}${PLAIN}" "${CYAN}— Доменное имя: ${domain}.${PLAIN}")"

            if [[ -f "$cert_file" && -f "$key_file" ]]; then
                cert_end=$(openssl x509 -enddate -noout -in "$cert_file" 2>/dev/null | cut -d= -f2-)
                cert_ts=$(date -d "$cert_end" +%s 2>/dev/null)
                now_ts=$(date +%s)
                days_left=$(( (cert_ts - now_ts) / 86400 ))

                if [[ -n "$cert_end" && "$days_left" -gt 15 ]]; then
                    echo -e "$(localized_text "    ${GREEN}证书状态: 正常 (剩余约 ${days_left} 天)${PLAIN}" "${GREEN}Certificate status: Normal (approximately ${days_left} days remaining)${PLAIN}" "${GREEN}Статус сертификата: Нормальный (осталось примерно ${days_left} дней)${PLAIN}")"
                    ((ok_count++))
                elif [[ -n "$cert_end" ]]; then
                    echo -e "$(localized_text "    ${YELLOW}证书状态: 即将到期 (剩余约 ${days_left} 天)${PLAIN}" "${YELLOW}Certificate status: About to expire (approximately ${days_left} days remaining)${PLAIN}" "Статус сертификата ${YELLOW}: Срок действия истекает (осталось примерно ${days_left} дней)${PLAIN}")"
                    ((warn_count++))
                else
                    echo -e "$(localized_text "    ${RED}证书状态: 无法读取有效期${PLAIN}" "${RED}Certificate status: Unable to read validity period${PLAIN}" "${RED}Статус сертификата: Невозможно прочитать срок действия${PLAIN}")"
                    ((err_count++))
                fi
            else
                echo -e "$(localized_text "    ${RED}证书状态: 缺失 /etc/caddy/certs/${domain}.crt|.key${PLAIN}" "${RED}Certificate status: missing /etc/caddy/certs/${domain}.crt|.key${PLAIN}" "Статус сертификата ${RED}: отсутствует /etc/caddy/certs/${domain}.crt|.key${PLAIN}")"
                ((err_count++))
            fi

            if [[ -L "/root/cert/${domain}.crt" && -e "/root/cert/${domain}.crt" && -L "/root/cert/${domain}.key" && -e "/root/cert/${domain}.key" ]]; then
                echo -e "$(localized_text "    ${GREEN}软链接状态: /root/cert 已正确挂载${PLAIN}" "${GREEN}Symlink status: /root/cert has correctly mounted${PLAIN}" "Состояние программной ссылки ${GREEN}: /root/cert правильно смонтировал${PLAIN}.")"
                ((ok_count++))
            else
                echo -e "$(localized_text "    ${YELLOW}软链接状态: 缺失或失效，建议执行维护菜单 [10] 重建软链接${PLAIN}" "${YELLOW}Symlink status: missing or invalid, it is recommended to execute the maintenance menu [10] to rebuild the symlink${PLAIN}" "Состояние мягкой ссылки ${YELLOW}: отсутствует или недействителен, рекомендуется выполнить меню обслуживания [10] для восстановления мягкой ссылки${PLAIN}")"
                ((warn_count++))
            fi

            [[ -z "$listen_target" ]] && listen_target="$(localized_text "未知" "unknown" "неизвестно")"
            if [[ -n "$listen_port" ]] && caddy_listen_addr_port_is_visible "$listen_addr" "$listen_port"; then
                echo -e "$(localized_text "    ${GREEN}监听状态: Caddy 本地端口 ${listen_target} 可见${PLAIN}" "${GREEN}Listening status: Caddy local port ${listen_target} visible${PLAIN}" "Статус прослушивания ${GREEN}: локальный порт Caddy, ${listen_target} виден${PLAIN}")"
                ((ok_count++))
            else
                echo -e "$(localized_text "    ${YELLOW}监听状态: 未检测到 ${listen_target} 在监听${PLAIN}" "    ${YELLOW}Listener: nothing is listening on ${listen_target}${PLAIN}" "    ${YELLOW}Прослушивание: на ${listen_target} служба не обнаружена${PLAIN}")"
                ((warn_count++))
            fi

            [[ -z "$backend" ]] && backend="$(localized_text "未知" "unknown" "неизвестно")"
            if [[ -z "$backend_addr" || -z "$backend_port" ]]; then
                echo -e "$(localized_text "    ${YELLOW}⚠️ 后端状态：无法从配置读取后端地址${PLAIN}" "${YELLOW}⚠️ Backend status: Unable to read backend address${PLAIN} from configuration" "${YELLOW}⚠️ Статус серверной части: невозможно прочитать адрес внутренней части${PLAIN} из конфигурации.")"
                ((warn_count++))
            elif probe_backend_target "$(localized_text "    后端状态" "    Backend status" "    Состояние бэкенда")" "$backend_addr" "$backend_port"; then
                ((ok_count++))
            else
                ((warn_count++))
            fi
        done < <(find /etc/caddy/conf.d -maxdepth 1 -type f -name "*.caddy" 2>/dev/null | sort)
    fi

    if [[ "$domain_count" -eq 0 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到本功能托管的域名配置（https://域名:端口）。${PLAIN}" "${YELLOW}⚠️ The domain configuration hosted by this function was not detected (https://域名:端口）。${PLAIN}" "${YELLOW}⚠️ Конфигурация доменного имени, размещенная с помощью этой функции, не обнаружена (https://域名:端口）。${PLAIN}")"
        ((warn_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [4/5] 检查清单文件...${PLAIN}" "${YELLOW}▶ [4/5] Checklist file...${PLAIN}" "${YELLOW}▶ [4/5] Файл контрольного списка...${PLAIN}")"
    if [[ -f /root/cert/caddy_cf_manifest.txt ]]; then
        echo -e "$(localized_text "${GREEN}✅ 清单文件存在: /root/cert/caddy_cf_manifest.txt${PLAIN}" "${GREEN}✅ Manifest file exists: /root/cert/caddy_cf_manifest.txt${PLAIN}" "${GREEN}✅ Существует файл манифеста: /root/cert/caddy_cf_manifest.txt.${PLAIN}")"
        ((ok_count++))
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 清单文件不存在，建议执行维护菜单 [11] 重建。${PLAIN}" "${YELLOW}⚠️ The manifest file does not exist, it is recommended to perform maintenance menu [11] to rebuild.${PLAIN}" "${YELLOW}⚠️ Файл манифеста не существует, рекомендуется выполнить меню обслуживания [11] для восстановления.${PLAIN}")"
        ((warn_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [5/5] 总结...${PLAIN}" "${YELLOW}▶ [5/5] Summary...${PLAIN}" "${YELLOW}▶ [5/5] Краткое описание...${PLAIN}")"
    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${CYAN}体检结果: ${GREEN}${ok_count} 正常${PLAIN} / ${YELLOW}${warn_count} 警告${PLAIN} / ${RED}${err_count} 异常${PLAIN}" "${CYAN}Health check results: ${ok_count} Normal / ${warn_count} Warning / ${err_count} Abnormal${PLAIN}" "${CYAN}Результаты медицинского осмотра: ${ok_count} Норма / ${warn_count} Предупреждение / ${err_count} Отклонение от нормы${PLAIN}")"
    if [[ "$err_count" -gt 0 ]]; then
        echo -e "$(localized_text "${RED}建议优先修复异常项，再继续业务切流。${PLAIN}" "${RED}It is recommended to fix the abnormal items first before continuing the business flow cutoff.${PLAIN}" "${RED}Рекомендуется сначала устранить аномальные элементы, прежде чем продолжать отключение бизнес-потока.${PLAIN}")"
    elif [[ "$warn_count" -gt 0 ]]; then
        echo -e "$(localized_text "${YELLOW}当前可继续运行，但建议处理警告项提高稳定性。${PLAIN}" "${YELLOW}Can currently continue to run, but it is recommended to handle the warning items to improve stability.${PLAIN}" "${YELLOW}в настоящее время может продолжать работать, но рекомендуется обработать элементы предупреждений для повышения стабильности.${PLAIN}")"
    else
        echo -e "$(localized_text "${GREEN}检查未发现异常。${PLAIN}" "${GREEN}Check found no abnormality.${PLAIN}" "${GREEN}Проверка не выявила отклонений.${PLAIN}")"
    fi
}

func_caddy_cf_auto_fix() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🧰 CF DNS 一键自动修复${PLAIN}" "${BOLD}🧰 CF DNS One-click automatic repair${PLAIN}" "${BOLD}🧰 CF DNS Автоматическое восстановление в один клик${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"

    local fixed_count=0
    local warn_count=0
    local fail_count=0
    local cf_env_file="/root/.config/vps-panel/cloudflare.env"
    local acme_bin="/root/.acme.sh/acme.sh"

    echo -e "$(localized_text "${YELLOW}▶ [1/7] 修复基础目录与主配置...${PLAIN}" "${YELLOW}▶ [1/7] Repair the basic directory and main configuration...${PLAIN}" "${YELLOW}▶ [1/7] Восстановление базового каталога и основной конфигурации...${PLAIN}")"
    mkdir -p /root/cert /etc/caddy/certs /etc/caddy/conf.d /root/.config/vps-panel
    chmod 700 /root/.config/vps-panel >/dev/null 2>&1

    if [[ ! -f /etc/caddy/Caddyfile ]]; then
        cat <<EOF > /etc/caddy/Caddyfile
# Managed by VPS-Optimize
import conf.d/*
EOF
        ((fixed_count++))
    elif ! grep -q "import conf.d/\*" /etc/caddy/Caddyfile; then
        echo -e "\nimport conf.d/*" >> /etc/caddy/Caddyfile
        ((fixed_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [1.5/7] 隔离旧式站点配置（避免抢占 443）...${PLAIN}" "${YELLOW}▶ [1.5/7] Isolating legacy site configurations (avoiding preemption 443)...${PLAIN}" "${YELLOW}▶ [1.5/7] Изолирование устаревших конфигураций сайта (избежание приоритетного вытеснения 443)...${PLAIN}")"
    quarantine_legacy_caddy_443_configs

    echo -e "$(localized_text "${YELLOW}▶ [2/7] 修复证书权限...${PLAIN}" "${YELLOW}▶ [2/7] Repair certificate permissions...${PLAIN}" "${YELLOW}▶ [2/7] Разрешения на ремонт сертификата...${PLAIN}")"
    if [[ -d /etc/caddy/certs ]]; then
        if id caddy >/dev/null 2>&1; then
            chown root:caddy /etc/caddy/certs/* 2>/dev/null
            chmod 640 /etc/caddy/certs/* 2>/dev/null
        else
            chmod 600 /etc/caddy/certs/* 2>/dev/null
        fi
        ((fixed_count++))
    else
        ((warn_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [3/7] 全量重建 /root/cert 软链接...${PLAIN}" "${YELLOW}▶ [3/7] Full reconstruction /root/cert symlink...${PLAIN}" "${YELLOW}▶ [3/7] Полная реконструкция /root/cert символическая ссылка...${PLAIN}")"
    local relink_count=0
    if [[ -d /etc/caddy/certs ]]; then
        while IFS= read -r cert_path; do
            local domain
            domain=$(basename "$cert_path" .crt)
            if [[ -f "/etc/caddy/certs/${domain}.key" ]]; then
                ln -sfn "/etc/caddy/certs/${domain}.crt" "/root/cert/${domain}.crt"
                ln -sfn "/etc/caddy/certs/${domain}.key" "/root/cert/${domain}.key"
                ((relink_count++))
            fi
        done < <(find /etc/caddy/certs -maxdepth 1 -type f -name "*.crt" 2>/dev/null | sort)
    fi
    echo -e "$(localized_text "${GREEN}✅ 已重建 ${relink_count} 组软链接。${PLAIN}" "${GREEN}✅ The ${relink_count} group symlink has been rebuilt.${PLAIN}" "${GREEN}✅ символическая ссылка группы ${relink_count} была перестроена.${PLAIN}")"
    ((fixed_count++))

    echo -e "$(localized_text "${YELLOW}▶ [4/7] 近效期证书自动续签...${PLAIN}" "${YELLOW}▶ [4/7] Automatic renewal of recent validity certificate...${PLAIN}" "${YELLOW}▶ [4/7] Автоматическое продление последнего сертификата действия...${PLAIN}")"
    local renew_count=0
    local renew_fail=0
    if [[ -x "$acme_bin" && -f "$cf_env_file" ]]; then
        # shellcheck disable=SC1090
        source "$cf_env_file"
        if [[ -n "$CF_Token" ]]; then
            while IFS= read -r conf_file; do
                local domain
                local cert_file
                local cert_end
                local cert_ts
                local now_ts
                local days_left

                domain=$(basename "$conf_file" .caddy)
                cert_file="/etc/caddy/certs/${domain}.crt"

                if ! head -n1 "$conf_file" | grep -q '^https://'; then
                    continue
                fi
                if [[ ! -f "$cert_file" ]]; then
                    continue
                fi

                cert_end=$(openssl x509 -enddate -noout -in "$cert_file" 2>/dev/null | cut -d= -f2-)
                cert_ts=$(date -d "$cert_end" +%s 2>/dev/null)
                now_ts=$(date +%s)
                days_left=$(( (cert_ts - now_ts) / 86400 ))

                if [[ -z "$cert_end" || "$days_left" -le 15 ]]; then
                    if issue_cf_dns_cert_with_retry "$domain" "$CF_Token" "$acme_bin"; then
                        "$acme_bin" --install-cert -d "$domain" --ecc \
                            --fullchain-file "/etc/caddy/certs/${domain}.crt" \
                            --key-file "/etc/caddy/certs/${domain}.key" \
                            --reloadcmd "systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1 || true" >/dev/null 2>&1
                        ((renew_count++))
                    else
                        ((renew_fail++))
                    fi
                fi
            done < <(find /etc/caddy/conf.d -maxdepth 1 -type f -name "*.caddy" 2>/dev/null | sort)

            if [[ "$renew_fail" -gt 0 ]]; then
                ((warn_count+=renew_fail))
            fi
            echo -e "$(localized_text "${GREEN}✅ 自动续签完成，成功 ${renew_count} 个，失败 ${renew_fail} 个。${PLAIN}" "${GREEN}✅ Automatic renewal completed, ${renew_count} successful and ${renew_fail} failed.${PLAIN}" "${GREEN}✅ Автоматическое продление завершено, ${renew_count} успешно, ${renew_fail} не удалось.${PLAIN}")"
            ((fixed_count++))
        else
            echo -e "$(localized_text "${YELLOW}⚠️ Token 为空，跳过自动续签。${PLAIN}" "${YELLOW}⚠️ Token is empty, skip automatic renewal.${PLAIN}" "${YELLOW}⚠️ Токен пуст, пропустите автоматическое продление.${PLAIN}")"
            ((warn_count++))
        fi
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到 acme.sh 或 Token 文件，跳过自动续签。${PLAIN}" "${YELLOW}⚠️ No acme.sh or Token file detected, skipping automatic renewal.${PLAIN}" "${YELLOW}⚠️ acme.sh или файл токена не обнаружены, автоматическое продление отсутствует.${PLAIN}")"
        ((warn_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [5/7] 校验并重载 Caddy...${PLAIN}" "${YELLOW}▶ [5/7] Verify and reload Caddy...${PLAIN}" "${YELLOW}▶ [5/7] Проверьте и перезагрузите Caddy...${PLAIN}")"
    if command -v caddy >/dev/null 2>&1; then
        if caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1; then
            systemctl enable caddy >/dev/null 2>&1
            if systemctl restart caddy >/dev/null 2>&1; then
                echo -e "$(localized_text "${GREEN}✅ Caddy 配置校验通过并重启成功。${PLAIN}" "${GREEN}✅ Caddy configuration validation passed and restarted successfully.${PLAIN}" "${GREEN}✅ Caddy Проверка конфигурации пройдена и успешно перезапущена.${PLAIN}")"
                ((fixed_count++))
            else
                echo -e "$(localized_text "${RED}❌ Caddy 重启失败，请手动检查日志。${PLAIN}" "${RED}❌ Caddy Restart failed, please check the log manually.${PLAIN}" "${RED}❌ Caddy Не удалось перезапустить, проверьте журнал вручную.${PLAIN}")"
                ((fail_count++))
            fi
        else
            echo -e "$(localized_text "${RED}❌ Caddy 配置校验失败，未执行重启。${PLAIN}" "${RED}❌ Caddy configuration validation failed and restart was not performed.${PLAIN}" "${RED}❌ Caddy Проверка конфигурации не удалась, и перезапуск не был выполнен.${PLAIN}")"
            ((fail_count++))
        fi
    else
        echo -e "$(localized_text "${RED}❌ 未安装 Caddy，无法执行重载。${PLAIN}" "${RED}❌ Caddy is not installed and reloading cannot be performed.${PLAIN}" "${RED}❌ Caddy не установлен и перезагрузка невозможна.${PLAIN}")"
        ((fail_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [6/7] 重建清单文件...${PLAIN}" "${YELLOW}▶ [6/7] Rebuild the manifest file...${PLAIN}" "${YELLOW}▶ [6/7] Пересобрать файл манифеста...${PLAIN}")"
    generate_caddy_cf_manifest
    ((fixed_count++))
    echo -e "$(localized_text "${GREEN}✅ 清单已重建: /root/cert/caddy_cf_manifest.txt${PLAIN}" "${GREEN}✅ List has been rebuilt: /root/cert/caddy_cf_manifest.txt${PLAIN}" "${GREEN}✅ Список был перестроен: /root/cert/caddy_cf_manifest.txt${PLAIN}")"

    echo -e "$(localized_text "${YELLOW}▶ [7/7] 补全 acme 自动续签任务...${PLAIN}" "${YELLOW}▶ [7/7] Complete acme automatic renewal task...${PLAIN}" "${YELLOW}▶ [7/7] Выполните задачу автоматического продления acme...${PLAIN}")"
    if [[ -x "$acme_bin" ]]; then
        if "$acme_bin" --install-cronjob >/dev/null 2>&1; then
            echo -e "$(localized_text "${GREEN}✅ acme.sh 自动续签任务已确认。${PLAIN}" "${GREEN}✅ acme.sh The automatic renewal task has been confirmed.${PLAIN}" "${GREEN}✅ acme.sh Задача на автоматическое продление подтверждена.${PLAIN}")"
            ((fixed_count++))
        else
            echo -e "$(localized_text "${YELLOW}⚠️ 无法确认 acme.sh 续签任务，请手动检查 crontab。${PLAIN}" "${YELLOW}⚠️ Unable to confirm acme.sh renewal task, please check crontab manually.${PLAIN}" "${YELLOW}⚠️ Невозможно подтвердить задачу обновления acme.sh, проверьте crontab вручную.${PLAIN}")"
            ((warn_count++))
        fi
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 未安装 acme.sh，跳过续签任务补全。${PLAIN}" "${YELLOW}⚠️ acme.sh is not installed and the renewal task completion is skipped.${PLAIN}" "${YELLOW}⚠️ acme.sh не установлен и выполнение задачи обновления пропускается.${PLAIN}")"
        ((warn_count++))
    fi

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${CYAN}自动修复结果: ${GREEN}${fixed_count} 已修复${PLAIN} / ${YELLOW}${warn_count} 警告${PLAIN} / ${RED}${fail_count} 失败${PLAIN}" "${CYAN}Automatic repair results: ${fixed_count} Fixed / ${warn_count} Warning / ${fail_count} Failed${PLAIN}" "${CYAN}Результаты автоматического ремонта : ${fixed_count} Исправлено / ${warn_count} Предупреждение / ${fail_count} Ошибка${PLAIN}")"
    if [[ "$fail_count" -gt 0 ]]; then
        echo -e "$(localized_text "${RED}存在失败项，建议先执行维护菜单 [13] 体检复查并查看 caddy 日志。${PLAIN}" "${RED}There are failed items in . It is recommended to perform health check review in the maintenance menu [13] and check the caddy log.${PLAIN}" "${RED}В есть неудачные элементы. Рекомендуется выполнить проверка состояния в меню обслуживания [13] и проверить журнал caddy.${PLAIN}")"
    else
        echo -e "$(localized_text "${GREEN}自动修复流程完成，可执行维护菜单 [13] 复检确认。${PLAIN}" "${GREEN}Automatic repair process is completed, and the maintenance menu [13] can be executed for re-inspection and confirmation.${PLAIN}" "${GREEN}Процесс автоматического ремонта завершен, и можно запустить меню обслуживания [13] для повторной проверки и подтверждения.${PLAIN}")"
    fi
}

func_caddy_cf_maintenance_menu() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}🛠️ 443 / Caddy / Cloudflare 维护中心${PLAIN}" "${BOLD}🛠️ 443 / Caddy / Cloudflare Maintenance Center${PLAIN}" "${BOLD}🛠️ 443 / Caddy / Cloudflare Центр технического обслуживания${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}用途：排查 443 链路、重签证书、修复软链接、隔离旧配置和回滚。${PLAIN}" "${YELLOW}Purpose: troubleshooting 443 links, re-signing certificates, repairing symlinks, isolating old configurations and rolling back.${PLAIN}" "${YELLOW}Назначение: устранение неполадок 443 ссылок, переподписка сертификатов, восстановление программных ссылок, изоляция старых конфигураций и откат.${PLAIN}")"
        echo -e "$(localized_text "${YELLOW}建议顺序：先 [1] 体检，再按异常选择证书或 Caddy 修复项。${PLAIN}" "${YELLOW}Recommended order: [1] health check first, then select the certificate or Caddy repair item according to the abnormality.${PLAIN}" "${YELLOW}Рекомендуемый порядок: [1] Сначала проверка состояния, затем выберите сертификат или элемент ремонта Caddy в соответствии с неисправностью.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${BOLD}${BLUE}▶ 443端口复用常用${PLAIN}" "${BOLD}▶ Port 443 Reuse commonly used${PLAIN}" "${BOLD}▶ 443 Обычно используется повторного использования порта 443${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  1. 443 链路与安全体检${PLAIN}       ${YELLOW}(Nginx/Caddy/REALITY/面板/版本隐藏)${PLAIN}" "${GREEN}1. 443 Link and security health check (Nginx/Caddy/REALITY/panel/version hidden)${PLAIN}" "${GREEN}1. 443 проверка состояния канала и безопасности (Nginx/Caddy/REALITY/панель/версия скрыта)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 管理 443 网站/反代域名${PLAIN}    ${YELLOW}(新增/删除/查看，最常用)${PLAIN}" "${GREEN}2. Management 443 website/reverse domain (add/delete/view, most commonly used)${PLAIN}" "${GREEN}2. Веб-сайт Management 443/обратное доменное имя (добавление/удаление/просмотр, наиболее часто используемый)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  3. 修改 443 分流参数${PLAIN}         ${YELLOW}(面板/订阅/REALITY/入口端口与路径)${PLAIN}" "${GREEN}3. Modify 443 routing parameters   (Panel/Subscription/REALITY/Entry Port and Path)${PLAIN}" "${GREEN}3. Измените 443 параметра маршрутизации   (Панель/Подписка/REALITY/Входной порт и путь)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  4. 重新应用上次 443 配置${PLAIN}     ${YELLOW}(读取 sni-stack.env 重建配置)${PLAIN}" "${GREEN}4. Reapply the last 443 configuration (read sni-stack.env and rebuild the configuration)${PLAIN}" "${GREEN}4. Повторно примените последнюю конфигурацию 443 (прочитайте sni-stack.env и перестройте конфигурацию)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  5. 订阅链接 / External Proxy 提示${PLAIN} ${YELLOW}(检查节点链接是否输出公网 443)${PLAIN}" "${GREEN}5. Subscription link / External Proxy prompt (check whether the node link outputs public port 443)${PLAIN}" "${GREEN}5. Ссылка на подписку/запрос внешнего прокси (проверьте, выводит ли ссылка узла публичный порт 443)${PLAIN}")"
        echo -e "$(localized_text "${RED}  6. 回滚 443端口复用配置${PLAIN}       ${YELLOW}(从最近备份恢复)${PLAIN}" "${RED}6. Rollback Port 443 Reuse configuration   (restore from recent backup)${PLAIN}" "${RED}6. Откат 443 Конфигурация с повторным использованием порта 443 (восстановление из последней резервной копии)${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${BOLD}${BLUE}▶ 证书与 Cloudflare${PLAIN}" "${BOLD}▶ Certificate and Cloudflare${PLAIN}" "${BOLD}▶ Сертификат и Cloudflare${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  7. 查看已管理域名 / 证书路径${PLAIN}" "${GREEN}7. View the managed domain/certificate path${PLAIN}" "${GREEN}7. Просмотрите имя управляемого домена/путь сертификата.${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  8. 更新 Cloudflare API Token${PLAIN}" "${GREEN}8. Update Cloudflare API Token${PLAIN}" "${GREEN}8. Обновите Cloudflare API-токен${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  9. 重新签发某个域名证书${PLAIN}" "${GREEN}9. Reissue a domain certificate${PLAIN}" "${GREEN}9. Перевыпустите сертификат доменного имени.${PLAIN}")"
        echo -e "$(localized_text "${GREEN} 10. 重建 /root/cert 证书软链接${PLAIN}" "${GREEN}10. Rebuild /root/cert certificate symlink${PLAIN}" "${GREEN}10. Перестройте программную ссылку сертификата /root/cert.${PLAIN}")"
        echo -e "$(localized_text "${GREEN} 11. 重建证书清单文件${PLAIN}" "${GREEN}11. Rebuild the certificate list file${PLAIN}" "${GREEN}11. Перестройте файл списка сертификатов.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${BOLD}${BLUE}▶ Caddy 修复与清理${PLAIN}" "${BOLD}▶ Caddy Repair and Cleanup${PLAIN}" "${BOLD}▶ Caddy Ремонт и очистка${PLAIN}")"
        echo -e "$(localized_text "${GREEN} 12. 校验并重载 Caddy${PLAIN}" "${GREEN}12. Verify and reload Caddy${PLAIN}" "${GREEN}12. Проверьте и перезагрузите Caddy.${PLAIN}")"
        echo -e "$(localized_text "${GREEN} 13. Caddy/证书一键体检${PLAIN}       ${YELLOW}(Token/证书/监听/后端)${PLAIN}" "${GREEN}13. Caddy/certificate one-click health check (Token/certificate/listening/backend)${PLAIN}" "${GREEN}13. Caddy/сертификат, проверка состояния в один клик (токен/сертификат/прослушивание/бэкенд)${PLAIN}")"
        echo -e "$(localized_text "${GREEN} 14. 一键自动修复常见问题${PLAIN}" "${GREEN}14. One-click automatic repair of common problems${PLAIN}" "${GREEN}14. Автоматическое устранение распространенных проблем в один клик${PLAIN}")"
        echo -e "$(localized_text "${GREEN} 15. 隔离旧 Caddy 配置${PLAIN}        ${YELLOW}(避免抢占 443)${PLAIN}" "${GREEN}15. Isolate the old Caddy and configure (avoid preemption 443)${PLAIN}" "${GREEN}15. Изолируйте старый Caddy и настройте (избегайте вытеснения 443)${PLAIN}")"
        echo -e "$(localized_text "${RED} 16. 隔离某个域名的 Caddy 配置与证书${PLAIN}" "${RED}16. Isolate a domain Caddy configuration and certificate${PLAIN}" "${RED}16. Изолируйте конфигурацию доменного имени Caddy и сертификат.${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}  0. 返回上一级 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"

        local m_choice
        read_trimmed m_choice "$(localized_text "👉 请选择操作: " "👉 Please select an operation:" "👉 Пожалуйста, выберите операцию:")"

        case "$m_choice" in
            1) m_choice=11 ;;
            2) m_choice=15 ;;
            3) m_choice=16 ;;
            4) m_choice=12 ;;
            5) m_choice=13 ;;
            6) m_choice=14 ;;
            7) m_choice=1 ;;
            8) m_choice=2 ;;
            9) m_choice=3 ;;
            10) m_choice=4 ;;
            11) m_choice=7 ;;
            12) m_choice=6 ;;
            13) m_choice=8 ;;
            14) m_choice=9 ;;
            15) m_choice=10 ;;
            16) m_choice=5 ;;
        esac

        case $m_choice in
            16)
                edit_sni_stack_runtime_profile
                ;;

            1)
                generate_caddy_cf_manifest
                echo -e "$(localized_text "${CYAN}👇 当前清单内容：${PLAIN}" "${CYAN}👇 Current list content:${PLAIN}" "${CYAN}👇 Текущее содержимое списка:${PLAIN}")"
                cat /root/cert/caddy_cf_manifest.txt 2>/dev/null
                ;;

            2)
                local new_token escaped_token
                mkdir -p /root/.config/vps-panel
                chmod 700 /root/.config/vps-panel
                echo -e "$(localized_text "${CYAN}👇 请输入新的 Cloudflare API Token${PLAIN}" "${CYAN}👇 Please enter the new Cloudflare API Token${PLAIN}" "${CYAN}👇 Введите новый токен API Cloudflare.${PLAIN}")"
                read_secret_trimmed new_token "CF Token: "
                if [[ -z "$new_token" || ${#new_token} -lt 20 ]]; then
                    echo -e "$(localized_text "${RED}❌ Token 长度异常，更新取消。${PLAIN}" "${RED}❌ Token length is abnormal and the update is cancelled.${PLAIN}" "${RED}❌ Неверная длина токена, обновление отменено.${PLAIN}")"
                else
                    echo -e "$(localized_text "${CYAN}▶ 正在在线校验 Cloudflare Token...${PLAIN}" "${CYAN}▶ Verifying online Cloudflare Token...${PLAIN}" "${CYAN}▶ Проверка токена Cloudflare онлайн...${PLAIN}")"
                    verify_cf_token_online "$new_token"
                    local verify_rc=$?
                    if [[ "$verify_rc" -eq 1 ]]; then
                        echo -e "$(localized_text "${RED}❌ Token 在线校验失败，未写入。${PLAIN}" "${RED}❌ Token failed online verification and was not written.${PLAIN}" "${RED}❌ Токен не прошел онлайн-проверку и не был записан.${PLAIN}")"
                        echo -e "$(localized_text "${YELLOW}需要权限：Zone.DNS.Edit + Zone.Zone.Read${PLAIN}" "${YELLOW}Requires permissions: Zone.DNS.Edit + Zone.Zone.Read${PLAIN}" "${YELLOW}требуются разрешения: Zone.DNS.Edit + Zone.Zone.Read.${PLAIN}")"
                        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                        continue
                    elif [[ "$verify_rc" -eq 2 ]]; then
                        echo -e "$(localized_text "${YELLOW}⚠️ 未安装 curl，跳过在线校验，继续写入。${PLAIN}" "${YELLOW}⚠️ curl is not installed, skip online verification and continue writing.${PLAIN}" "${YELLOW}⚠️ curl не установлен, пропустите онлайн-проверку и продолжайте писать.${PLAIN}")"
                    else
                        echo -e "$(localized_text "${GREEN}✅ Token 校验通过。${PLAIN}" "${GREEN}✅ Token verification passed.${PLAIN}" "${GREEN}✅ Проверка токена пройдена.${PLAIN}")"
                    fi

                    escaped_token=${new_token//\'/\'"\'"\'}
                    printf "CF_Token='%s'\n" "$escaped_token" > /root/.config/vps-panel/cloudflare.env
                    chmod 600 /root/.config/vps-panel/cloudflare.env
                    echo -e "$(localized_text "${GREEN}✅ Cloudflare Token 已更新。${PLAIN}" "${GREEN}✅ Cloudflare Token has been updated.${PLAIN}" "${GREEN}✅ Cloudflare Токен обновлен.${PLAIN}")"
                fi
                ;;

            3)
                local domain domain_input
                local acme_bin="/root/.acme.sh/acme.sh"
                local cf_env_file="/root/.config/vps-panel/cloudflare.env"

                read_trimmed domain_input "$(localized_text "👉 请输入要重签的域名: " "👉 Please enter the domain you want to re-sign:" "👉 Пожалуйста, введите доменное имя, которое вы хотите переподписать:")"
                domain=$(normalize_domain_input "$domain_input")
                if ! is_valid_domain "$domain"; then
                    print_domain_validation_error "$(localized_text "域名" "domain" "доменное имя")" "$domain_input" "$domain"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi

                if [[ ! -x "$acme_bin" ]]; then
                    echo -e "$(localized_text "${RED}❌ 未检测到 acme.sh，请先运行主菜单 [19] -> [2] 安装 443 入口。${PLAIN}" "${RED}❌ acme.sh was not found. Run main menu [19] -> [2] to install the 443 entry first.${PLAIN}" "${RED}❌ acme.sh не найден. Сначала установите вход 443 через главное меню [19] -> [2].${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi
                if [[ ! -f "$cf_env_file" ]]; then
                    echo -e "$(localized_text "${RED}❌ 未检测到 Cloudflare Token，请先执行本菜单 [2]。${PLAIN}" "${RED}❌ Cloudflare Token is not detected, please execute this menu [2] first.${PLAIN}" "${RED}❌ Cloudflare Токен не обнаружен, сначала откройте это меню [2].${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi

                # shellcheck disable=SC1090
                source "$cf_env_file"
                confirm_risk_action "$(localized_text "重签并安装 ${domain} 的证书" "Re-sign and install the certificate of ${domain}" "Переподпишите и установите сертификат ${domain}.")" \
                    "$(localized_text "acme.sh 证书缓存、/etc/caddy/certs 和 /root/cert 软链接" "acme.sh certificate cache, /etc/caddy/certs and /root/cert symlinks" "Кэш сертификатов acme.sh, символическая ссылка /etc/caddy/certs и /root/cert")" \
                    "$(localized_text "使用现有 Caddy/证书备份恢复，或重新运行证书维护菜单签发" "Use the existing Caddy/certificate backup to restore, or re-run the certificate maintenance menu to issue" "Используйте существующую резервную копию Caddy/сертификата для восстановления или повторно запустите меню обслуживания сертификата для выдачи.")" \
                    "$(localized_text "确认域名 DNS 已解析，Cloudflare Token 权限正确。" "Confirm that the domain DNS has been resolved and the Cloudflare Token permissions are correct." "Убедитесь, что доменное имя DNS разрешено и разрешения токена Cloudflare верны.")" || {
                    echo -e "$(localized_text "${BLUE}已取消证书重签。${PLAIN}" "${BLUE}Certificate re-signing has been canceled.${PLAIN}" "${BLUE}Переподписка сертификата отменена.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                }
                echo -e "$(localized_text "${CYAN}▶ 正在重签证书: ${domain}${PLAIN}" "${CYAN}▶ Re-issuing certificate: ${domain}${PLAIN}" "${CYAN}▶ Перевыпуск сертификата: ${domain}${PLAIN}")"

                if ! issue_cf_dns_cert_with_retry "$domain" "$CF_Token" "$acme_bin"; then
                    echo -e "$(localized_text "${RED}❌ 证书签发失败：${domain}${PLAIN}" "${RED}❌ Certificate issuance failed: ${domain}${PLAIN}" "${RED}❌ Не удалось выдать сертификат: ${domain}.${PLAIN}")"
                    echo -e "$(localized_text "${YELLOW}   提示：建议先执行本菜单 [14] 自动修复再重试。${PLAIN}" "${YELLOW}Tip: It is recommended to perform automatic repair in this menu [14] and then try again.${PLAIN}" "${YELLOW}Совет: рекомендуется выполнить автоматическое восстановление в этом меню [14], а затем повторить попытку.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi

                mkdir -p /etc/caddy/certs /root/cert
                if ! "$acme_bin" --install-cert -d "$domain" --ecc \
                    --fullchain-file "/etc/caddy/certs/${domain}.crt" \
                    --key-file "/etc/caddy/certs/${domain}.key" \
                    --reloadcmd "systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1 || true" >/dev/null 2>&1; then
                    echo -e "$(localized_text "${RED}❌ 证书安装失败：${domain}${PLAIN}" "${RED}❌ Certificate installation failed: ${domain}${PLAIN}" "${RED}❌ Не удалось установить сертификат: ${domain}.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi

                if id caddy >/dev/null 2>&1; then
                    chown root:caddy "/etc/caddy/certs/${domain}.crt" "/etc/caddy/certs/${domain}.key" >/dev/null 2>&1
                    chmod 640 "/etc/caddy/certs/${domain}.crt" "/etc/caddy/certs/${domain}.key"
                else
                    chmod 600 "/etc/caddy/certs/${domain}.crt" "/etc/caddy/certs/${domain}.key"
                fi

                ln -sfn "/etc/caddy/certs/${domain}.crt" "/root/cert/${domain}.crt"
                ln -sfn "/etc/caddy/certs/${domain}.key" "/root/cert/${domain}.key"
                generate_caddy_cf_manifest
                echo -e "$(localized_text "${GREEN}✅ 重签完成并已更新 /root/cert 软链接。${PLAIN}" "${GREEN}✅ The re-signing is completed and the /root/cert symlink has been updated.${PLAIN}" "${GREEN}✅ Переподписка завершена, символическая ссылка /root/cert обновлена.${PLAIN}")"
                ;;

            4)
                local link_mode domain domain_input
                mkdir -p /root/cert
                read_trimmed link_mode "$(localized_text "❓ 重建全部链接还是单域名？(all/one): " "❓ Rebuild all links or a single domain? (all/one):" "❓Перестроить все ссылки или одно доменное имя? (все/один):")"

                if [[ "$link_mode" == "all" ]]; then
                    local relink_count=0
                    if [[ -d /etc/caddy/certs ]]; then
                        while IFS= read -r cert_path; do
                            domain=$(basename "$cert_path" .crt)
                            if [[ -f "/etc/caddy/certs/${domain}.key" ]]; then
                                ln -sfn "/etc/caddy/certs/${domain}.crt" "/root/cert/${domain}.crt"
                                ln -sfn "/etc/caddy/certs/${domain}.key" "/root/cert/${domain}.key"
                                ((relink_count++))
                            fi
                        done < <(find /etc/caddy/certs -maxdepth 1 -type f -name "*.crt" 2>/dev/null | sort)
                    fi
                    generate_caddy_cf_manifest
                    echo -e "$(localized_text "${GREEN}✅ 已重建 ${relink_count} 个域名的证书软链接。${PLAIN}" "${GREEN}✅ The certificate symlinks of ${relink_count} domains have been rebuilt.${PLAIN}" "${GREEN}✅ символическая ссылка сертификатов доменных имен ${relink_count} были перестроены.${PLAIN}")"
                else
                    read_trimmed domain_input "$(localized_text "👉 请输入域名: " "👉 Please enter domain:" "👉 Пожалуйста, введите доменное имя:")"
                    domain=$(normalize_domain_input "$domain_input")
                    if ! is_valid_domain "$domain"; then
                        print_domain_validation_error "$(localized_text "域名" "domain" "доменное имя")" "$domain_input" "$domain"
                        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                        continue
                    fi
                    if [[ -f "/etc/caddy/certs/${domain}.crt" && -f "/etc/caddy/certs/${domain}.key" ]]; then
                        ln -sfn "/etc/caddy/certs/${domain}.crt" "/root/cert/${domain}.crt"
                        ln -sfn "/etc/caddy/certs/${domain}.key" "/root/cert/${domain}.key"
                        generate_caddy_cf_manifest
                        echo -e "$(localized_text "${GREEN}✅ 软链接已重建：/root/cert/${domain}.crt 与 /root/cert/${domain}.key${PLAIN}" "${GREEN}✅ symlink has been rebuilt: /root/cert/${domain}.crt and /root/cert/${domain}.key${PLAIN}" "${GREEN}✅ символическая ссылка была перестроена: /root/cert/${domain}.crt и /root/cert/${domain}.key.${PLAIN}")"
                    else
                        echo -e "$(localized_text "${RED}❌ 未找到该域名证书文件。${PLAIN}" "${RED}❌ The domain certificate file was not found.${PLAIN}" "${RED}❌ Файл сертификата доменного имени не найден.${PLAIN}")"
                    fi
                fi
                ;;

            5)
                local domain domain_input purge_acme
                read_trimmed domain_input "$(localized_text "👉 请输入要隔离的域名: " "👉 Please enter the domain to be isolated:" "👉 Пожалуйста, введите доменное имя, которое необходимо изолировать:")"
                domain=$(normalize_domain_input "$domain_input")
                if ! is_valid_domain "$domain"; then
                    print_domain_validation_error "$(localized_text "域名" "domain" "доменное имя")" "$domain_input" "$domain"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi

                if ! confirm_risk_action "$(localized_text "隔离 ${domain} 的配置与证书" "Isolate the configuration and certificate of ${domain}" "Изолируйте конфигурацию и сертификат ${domain}.")" \
                    "$(localized_text "Caddy 配置、证书文件和可选 acme.sh 历史记录" "Caddy configuration, certificate files, and optional acme.sh history" "Конфигурация Caddy, файлы сертификатов и дополнительная история acme.sh.")" \
                    "$(localized_text "从隔离目录手动移回，或重新签发证书并恢复 Caddy 配置" "Manually move back from the quarantine directory, or reissue the certificate and restore the Caddy configuration" "Вручную вернитесь из каталога карантина или перевыпустите сертификат и восстановите конфигурацию Caddy.")" \
                    "$(localized_text "确认该域名不再承载线上服务，或已经准备好重新签发。" "Confirm that the domain no longer hosts online services or is ready for re-issuance." "Подтвердите, что доменное имя больше не размещает онлайн-сервисы или готово к перевыпуску.")"; then
                    echo -e "$(localized_text "${BLUE}已取消隔离。${PLAIN}" "${BLUE}Has been cancelled.${PLAIN}" "${BLUE}отменен.${PLAIN}")"
                    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                    continue
                fi

                local domain_quarantine_dir="/etc/vps-optimize/quarantine/caddy-domain-${domain}-$(date +%s)"
                mkdir -p "$domain_quarantine_dir"
                quarantine_path "/etc/caddy/conf.d/${domain}.caddy" "$domain_quarantine_dir" >/dev/null 2>&1 || true
                quarantine_path "/etc/caddy/certs/${domain}.crt" "$domain_quarantine_dir" >/dev/null 2>&1 || true
                quarantine_path "/etc/caddy/certs/${domain}.key" "$domain_quarantine_dir" >/dev/null 2>&1 || true
                quarantine_path "/root/cert/${domain}.crt" "$domain_quarantine_dir" >/dev/null 2>&1 || true
                quarantine_path "/root/cert/${domain}.key" "$domain_quarantine_dir" >/dev/null 2>&1 || true

                read_trimmed purge_acme "$(localized_text "❓ 是否同时删除 acme.sh 历史记录？(y/N，默认 N，建议保留): " "❓ Also remove the acme.sh history? (y/N, default N; keeping it is recommended): " "❓ Также удалить историю acme.sh? (y/N, по умолчанию N; рекомендуется сохранить): ")"
                if is_yes "$purge_acme"; then
                    /root/.acme.sh/acme.sh --remove -d "$domain" --ecc >/dev/null 2>&1 || true
                    quarantine_path "/root/.acme.sh/${domain}_ecc" "/root/.acme.sh/_quarantine" >/dev/null 2>&1 || true
                    quarantine_path "/root/.acme.sh/${domain}" "/root/.acme.sh/_quarantine" >/dev/null 2>&1 || true
                fi

                if caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1; then
                    systemctl restart caddy >/dev/null 2>&1
                fi
                generate_caddy_cf_manifest
                echo -e "$(localized_text "${GREEN}✅ ${domain} 的 Caddy 配置与证书已隔离到：${domain_quarantine_dir}${PLAIN}" "${GREEN}✅ Caddy configuration and certificate of ${domain} have been isolated to: ${domain_quarantine_dir}${PLAIN}" "${GREEN}✅ Конфигурация Caddy и сертификат ${domain} изолированы от: ${domain_quarantine_dir}.${PLAIN}")"
                ;;

            6)
                caddy_format_configs
                if caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1; then
                    systemctl restart caddy >/dev/null 2>&1
                    echo -e "$(localized_text "${GREEN}✅ Caddy 配置已格式化，校验通过并重启生效。${PLAIN}" "${GREEN}✅ Caddy configuration has been formatted, passed verification and will take effect after restarting.${PLAIN}" "${GREEN}✅ Конфигурация Caddy отформатирована, прошла проверку и вступит в силу после перезагрузки.${PLAIN}")"
                else
                    echo -e "$(localized_text "${RED}❌ Caddy 配置校验失败，请检查 /etc/caddy/conf.d/*.caddy${PLAIN}" "${RED}❌ Caddy configuration validation failed, please check /etc/caddy/conf.d/*.caddy${PLAIN}" "${RED}❌ Caddy Проверка конфигурации не удалась, проверьте /etc/caddy/conf.d/*.caddy${PLAIN}")"
                fi
                ;;

            7)
                generate_caddy_cf_manifest
                echo -e "$(localized_text "${GREEN}✅ 清单已重建：/root/cert/caddy_cf_manifest.txt${PLAIN}" "${GREEN}✅ List has been rebuilt: /root/cert/caddy_cf_manifest.txt${PLAIN}" "${GREEN}✅ Список был перестроен: /root/cert/caddy_cf_manifest.txt${PLAIN}")"
                ;;

            8)
                func_caddy_cf_health_check
                ;;

            9)
                func_caddy_cf_auto_fix
                ;;

            10)
                quarantine_legacy_caddy_443_configs
                if caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1; then
                    systemctl restart caddy >/dev/null 2>&1
                    echo -e "$(localized_text "${GREEN}✅ 隔离完成，Caddy 已重载。${PLAIN}" "${GREEN}✅ Isolation completed, Caddy has been reloaded.${PLAIN}" "${GREEN}. Изоляция завершена, Caddy перезагружен.${PLAIN}")"
                else
                    echo -e "$(localized_text "${RED}❌ 当前 Caddy 配置校验失败，请先修复语法错误。${PLAIN}" "${RED}❌ The current Caddy configuration validation failed, please fix the syntax error first.${PLAIN}" "${RED}❌ Текущая проверка конфигурации Caddy не удалась, сначала исправьте синтаксическую ошибку.${PLAIN}")"
                fi
                ;;

            11)
                sni_stack_health_check
                ;;

            12)
                reapply_sni_stack_from_env
                ;;

            13)
                check_sni_stack_subscription_hint
                ;;

            14)
                rollback_sni_stack_config
                ;;

            15)
                manage_sni_stack_sites
                ;;

            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择！${PLAIN}" "${RED}❌ Invalid selection!${PLAIN}" "${RED}❌ Неверный выбор!${PLAIN}")" ;;
        esac

        echo ""
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
    done
}

# ---------------------------------------------------------
# 新增功能：查看 Caddy 已申请证书路径
# ---------------------------------------------------------
func_view_caddy_cert() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🔑 Caddy 已申请证书路径查询${PLAIN}" "${BOLD}🔑 Caddy Applied certificate path query${PLAIN}" "${BOLD}🔑 Caddy Запрос пути примененного сертификата${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    
    if [[ ! -f "/etc/caddy/Caddyfile" ]]; then
        echo -e "$(localized_text "${RED}❌ 未检测到 /etc/caddy/Caddyfile，请先配置反代！${PLAIN}" "${RED}❌ /etc/caddy/Caddyfile is not detected, please configure reverse proxy first!${PLAIN}" "${RED}❌ /etc/caddy/Caddyfile не обнаружен, сначала настройте обратный прокси-сервер!${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
        return
    fi
    
    # 提取 Caddyfile 与 conf.d 中的域名 (排除注释，简单匹配)
    local domains
    domains=$(cat /etc/caddy/Caddyfile /etc/caddy/conf.d/*.caddy 2>/dev/null | grep -vE '^[[:space:]]*#' | grep '{' | awk '{print $1}' | tr -d '{')
    
    if [[ -z "$domains" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ Caddyfile 中没有配置明确的域名。${PLAIN}" "${YELLOW}⚠️ There is no clear domain configured in Caddyfile.${PLAIN}" "${YELLOW}⚠️ В файле Caddy нет четкого доменного имени.${PLAIN}")"
    else
        # Caddy 默认的证书存储根路径
        local cert_root="/var/lib/caddy/.local/share/caddy/certificates"
        [[ ! -d "$cert_root" ]] && cert_root="/root/.local/share/caddy/certificates"
        
        for domain in $domains; do
            # 过滤掉本地回环等无意义的块
            if [[ "$domain" == ":80" || "$domain" == "localhost" ]]; then continue; fi
            
            echo -e "$(localized_text "${BLUE}🌐 域名: ${BOLD}${domain}${PLAIN}" "${BLUE}🌐 domain: ${domain}${PLAIN}" "${BLUE}🌐 Доменное имя: ${domain}${PLAIN}")"
            
            local found=false
            if [[ -d "$cert_root" ]]; then
                # 递归查找对应的 .crt 和 .key 文件
                local cert_file
                local key_file
                cert_file=$(find "$cert_root" -name "${domain}.crt" -print -quit 2>/dev/null)
                key_file=$(find "$cert_root" -name "${domain}.key" -print -quit 2>/dev/null)
                
                if [[ -n "$cert_file" && -n "$key_file" ]]; then
                    echo -e "$(localized_text "   ${GREEN}📄 公钥 (CRT):${PLAIN} ${cert_file}" "${GREEN}📄 Public key (CRT):${PLAIN} ${cert_file}" "${GREEN}📄 Открытый ключ (CRT):${PLAIN} ${cert_file}")"
                    echo -e "$(localized_text "   ${YELLOW}🔑 密钥 (KEY):${PLAIN} ${key_file}" "${YELLOW}🔑 Key (KEY):${PLAIN} ${key_file}" "${YELLOW}🔑 Ключ (KEY):${PLAIN} ${key_file}")"
                    found=true
                fi
            fi
            
            if ! $found; then
                echo -e "$(localized_text "   ${RED}❌ 未找到证书，可能尚未签发成功或路径异常。${PLAIN}" "${RED}❌ The certificate was not found. It may not have been successfully issued or the path may be abnormal.${PLAIN}" "${RED}❌ Сертификат не найден. Возможно, он не был успешно выдан или путь может быть ненормальным.${PLAIN}")"
            fi
            echo -e "------------------------------------------------"
        done
    fi
    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
}

# ---------------------------------------------------------
# 新增功能：清空 Caddy 配置文件 (适配模块化安全架构)
# ---------------------------------------------------------
func_caddy_clear_config() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🧹 清空 Caddy 配置文件 (模块化版本)${PLAIN}" "${BOLD}🧹 Clear Caddy configuration file (modular version)${PLAIN}" "${BOLD}🧹 Очистить файл конфигурации Caddy (модульная версия)${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    
    # 检查主文件与模块化目录是否存在
    if [[ -f /etc/caddy/Caddyfile ]] || [[ -d /etc/caddy/conf.d ]]; then
        echo -e "$(localized_text "${YELLOW}将清空 /etc/caddy/conf.d/*.caddy，并重置 /etc/caddy/Caddyfile 为模块化初始状态。${PLAIN}" "${YELLOW}Will clear /etc/caddy/conf.d/*.caddy and reset /etc/caddy/Caddyfile to the modular initial state.${PLAIN}" "${YELLOW}очистит /etc/caddy/conf.d/*.caddy и сбросит /etc/caddy/Caddyfile в модульное исходное состояние.${PLAIN}")"
        if confirm_danger "$(localized_text "清空 Caddy 反代配置" "Clear Caddy reverse proxy configuration" "Очистить конфигурацию обратного прокси-сервера Caddy.")" "$(localized_text "所有独立 Caddy 反代配置会失效，相关网站/面板可能暂时打不开。" "All independent Caddy reverse proxy configurations will become invalid, and related websites/panels may not be opened temporarily." "Все независимые конфигурации обратный прокси Caddy станут недействительными, а соответствующие веб-сайты/панели могут быть временно недоступны.")" "$(localized_text "脚本会备份 Caddyfile 和 conf.d 目录，可按备份路径手动恢复。" "The script will back up the Caddyfile and conf.d directories, which can be restored manually according to the backup path." "Скрипт создаст резервную копию каталогов Caddyfile и conf.d, которые можно восстановить вручную в соответствии с путем резервной копии.")"; then
            
            # 1. 备份现有的模块化配置目录
            if [[ -d /etc/caddy/conf.d ]]; then
                local backup_dir="/etc/caddy/conf.d_bak_$(date +%s)"
                cp -r /etc/caddy/conf.d "$backup_dir" 2>/dev/null
                echo -e "$(localized_text "${BLUE}已备份原配置目录为 $backup_dir${PLAIN}" "${BLUE}Has backed up the original configuration directory to $backup_dir${PLAIN}" "${BLUE}создал резервную копию исходного каталога конфигурации в $backup_dir.${PLAIN}")"
                
                # 精准隔离所有 .caddy 配置文件，避免不可逆删除。
                while IFS= read -r caddy_conf; do
                    mv "$caddy_conf" "$backup_dir/" 2>/dev/null || true
                done < <(find /etc/caddy/conf.d -maxdepth 1 -type f -name '*.caddy' 2>/dev/null | sort)
            fi
            
            # 2. 守护主文件架构，重置为极简模式并注入模块化指令
            cp /etc/caddy/Caddyfile "/etc/caddy/Caddyfile.bak_$(date +%s)" 2>/dev/null
            echo "# Caddyfile Cleared and Reset to Modular Architecture" > /etc/caddy/Caddyfile
            echo "import conf.d/*" >> /etc/caddy/Caddyfile
            
            # 3. 重启生效
            systemctl restart caddy >/dev/null 2>&1
            echo -e "$(localized_text "${GREEN}✅ 所有反代配置已清空并成功重载！系统已恢复纯净的模块化初始状态。${PLAIN}" "${GREEN}✅ All reverse proxy configurations have been cleared and reloaded successfully! The system has been restored to its pristine, modular initial state.${PLAIN}" "${GREEN}✅ Все конфигурации обратный прокси очищены и успешно перезагружены! Система была восстановлена ​​в первозданном, модульном исходном состоянии.${PLAIN}")"
        else
            echo -e "$(localized_text "${BLUE}已取消清空操作。${PLAIN}" "${BLUE}The clearing operation has been canceled.${PLAIN}" "${BLUE}Операция очистки была отменена.${PLAIN}")"
        fi
    else
        echo -e "$(localized_text "${RED}❌ 未检测到 Caddy 配置文件或模块化目录！${PLAIN}" "${RED}❌ No Caddy configuration file or modular directory detected!${PLAIN}" "${RED}❌ Файл конфигурации или модульный каталог Caddy не обнаружен!${PLAIN}")"
    fi
    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
}

strip_caddy_ip_whitelist_block() {
    local conf_file="$1"
    local tmp_file
    tmp_file=$(mktemp /tmp/caddy-ipwl.XXXXXX) || return 1
    awk '
        /# vps-optimize-ip-whitelist-start/ {skip=1; next}
        /# vps-optimize-ip-whitelist-end/ {skip=0; next}
        !skip {print}
    ' "$conf_file" > "$tmp_file" || { rm -f "$tmp_file"; return 1; }
    mv "$tmp_file" "$conf_file"
}

insert_caddy_ip_whitelist_block() {
    local conf_file="$1"
    local ranges="$2"
    local tmp_file block
    strip_caddy_ip_whitelist_block "$conf_file" || return 1
    tmp_file=$(mktemp /tmp/caddy-ipwl.XXXXXX) || return 1
    block=$(caddy_ip_whitelist_block "$ranges")
    awk -v block="$block" '
        inserted == 0 && /^[[:space:]]*[^#[:space:]].*\{[[:space:]]*$/ {
            print
            printf "%s", block
            inserted=1
            next
        }
        {print}
        END { if (inserted == 0) exit 1 }
    ' "$conf_file" > "$tmp_file" || { rm -f "$tmp_file"; return 1; }
    mv "$tmp_file" "$conf_file"
}

func_caddy_manage_ip_whitelist() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🔐 Caddy 域名 IP 白名单${PLAIN}" "${BOLD}🔐 Caddy domain IP whitelist${PLAIN}" "${BOLD}🔐 Caddy доменное имя Белый список IP-адресов${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${YELLOW}适用于未启用 443端口复用、由 Caddy 直接对外服务的域名。${PLAIN}" "${YELLOW}Suitable for domains that do not enable the Port 443 Reuse and are directly served externally by Caddy.${PLAIN}" "${YELLOW}подходит для доменных имен, которые не поддерживают повторное использование порта 443 и обслуживаются напрямую извне Caddy.${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}如果该域名已接入 443端口复用，请用主菜单 [19 443端口复用管理中心] -> [8 管理 Web 域名/反代] -> [5 管理域名 IP 白名单]，不要在 Caddy 层限制。${PLAIN}" "${YELLOW}If the domain has been connected to Port 443 Reuse, please use the main menu [19 Port 443 Reuse Manager] -> [8 Manage Web domain/reverse proxy] -> [5 Manage domain IP whitelist], do not limit it at the Caddy layer.${PLAIN}" "${YELLOW}Если доменное имя подключено к повторному использованию порта 443, используйте главное меню [19 Управление повторным использованием порта 443] -> [8 Управление именем веб-домена/обратным прокси-сервером] -> [5 Управление белым списком IP-адресов доменного имени], не ограничивайте его на уровне Caddy.${PLAIN}")"
    echo -e "------------------------------------------------"

    if ! command -v caddy >/dev/null 2>&1 || [[ ! -f /etc/caddy/Caddyfile ]]; then
        echo -e "$(localized_text "${RED}❌ 未检测到 Caddy 或 /etc/caddy/Caddyfile，请先配置 Caddy 反代。${PLAIN}" "${RED}❌ Caddy or /etc/caddy/Caddyfile is not detected, please configure Caddy reverse proxy first.${PLAIN}" "${RED}❌ Caddy или /etc/caddy/Caddyfile не обнаружен, сначала настройте обратный прокси-сервер Caddy.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi

    local domain domain_input conf_file first_site_line action backup_file
    read_trimmed domain_input "$(localized_text "请输入要管理的域名 (如 panel.example.com): " "Please enter the domain you want to manage (eg panel.example.com):" "Пожалуйста, введите доменное имя, которым вы хотите управлять (например, Panel.example.com):")"
    domain=$(normalize_domain_input "$domain_input")
    if ! is_valid_domain "$domain"; then
        print_domain_validation_error "$(localized_text "域名" "domain" "доменное имя")" "$domain_input" "$domain"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi

    conf_file="/etc/caddy/conf.d/${domain}.caddy"
    if [[ ! -f "$conf_file" ]]; then
        echo -e "$(localized_text "${RED}❌ 未找到 ${conf_file}。该入口只管理脚本创建的模块化 Caddy 域名配置。${PLAIN}" "${RED}❌ ${conf_file} not found. This entry only manages the modular Caddy domain configuration created by the script.${PLAIN}" "${RED}❌ ${conf_file} не найден. Эта запись управляет только модульной конфигурацией доменного имени Caddy, созданной сценарием.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi

    first_site_line=$(grep -m1 -E '^[[:space:]]*[^#[:space:]].*\{' "$conf_file" 2>/dev/null | sed 's/^[[:space:]]*//')
    if [[ "$first_site_line" != "$domain "* && "$first_site_line" != "$domain{"* && "$first_site_line" != "https://${domain}"* ]]; then
        echo -e "$(localized_text "${RED}❌ ${conf_file} 的首个站点块不是 ${domain}，为避免误改已取消。${PLAIN}" "${RED}❌ The first site block of ${conf_file} is not ${domain}, and has been canceled to avoid mistaken modification.${PLAIN}" "${RED}❌ Первый блок сайта ${conf_file} — это не ${domain}, и он был отменен во избежание ошибочной модификации.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi
    if [[ "$first_site_line" =~ ^https://[^[:space:]]+:[0-9]+[[:space:]]*\{ ]]; then
        echo -e "$(localized_text "${RED}❌ 这个配置看起来属于 443端口复用本地 Caddy TLS 站点。请改用主菜单 [19 443端口复用管理中心] -> [8 管理 Web 域名/反代] -> [5 管理域名 IP 白名单]。${PLAIN}" "${RED}❌ This configuration appears to belong to the Port 443 Reuse local Caddy TLS site. Please use the main menu instead [19 Port 443 Reuse Manager] -> [8 Manage Web domain/Reverse Proxy] -> [5 Manage domain IP Whitelist].${PLAIN}" "${RED}❌ Похоже, эта конфигурация принадлежит локальному сайту Caddy TLS с повторным использованием порта 443. Вместо этого используйте главное меню [19 Управление повторным использованием порта 443] -> [8 Управление именем веб-домена/обратным прокси-сервером] -> [5 Управление белым списком IP-адресов доменных имен].${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi

    echo -e "$(localized_text "当前配置文件：${conf_file}" "Current configuration file: ${conf_file}" "Текущий файл конфигурации: ${conf_file}.")"
    if grep -q '# vps-optimize-ip-whitelist-start' "$conf_file" 2>/dev/null; then
        echo -e "$(localized_text "${YELLOW}当前状态：已启用脚本管理的 IP 白名单。${PLAIN}" "${YELLOW}Current status: IP whitelist for script management is enabled.${PLAIN}" "${YELLOW}Текущее состояние: белый список IP-адресов для управления сценариями включен.${PLAIN}")"
    else
        echo -e "$(localized_text "${BLUE}当前状态：未启用脚本管理的 IP 白名单。${PLAIN}" "${BLUE}Current status: IP whitelist for script management is not enabled.${PLAIN}" "${BLUE}Текущий статус: Белый список IP-адресов для управления сценариями не включен.${PLAIN}")"
    fi
    echo -e "$(localized_text "1. 设置/覆盖白名单" "1. Set/override whitelist" "1. Установить/переопределить белый список")"
    echo -e "$(localized_text "2. 清除白名单" "2. Clear the whitelist" "2. Очистите белый список")"
    echo -e "$(localized_text "0/q. 取消" "0/q. Cancel" "0/кв. Отмена")"
    read_trimmed action "$(localized_text "请选择操作: " "Please select an action:" "Пожалуйста, выберите действие:")"

    backup_file="${conf_file}.bak_$(date +%s)"
    case "$action" in
        1)
            local ip_whitelist_input ip_whitelist_ranges current_client_ip
            local -a ip_whitelist_array=()
            current_client_ip=$(detect_ssh_client_ip)
            [[ -n "$current_client_ip" ]] && echo -e "$(localized_text "${YELLOW}当前 SSH 来源 IP 可能是：${current_client_ip}，请确认已加入白名单。${PLAIN}" "${YELLOW}The current source IP of SSH may be: ${current_client_ip}. Please confirm that it has been added to the whitelist.${PLAIN}" "${YELLOW}Текущий исходный IP-адрес SSH может быть: ${current_client_ip}. Пожалуйста, подтвердите, что он был добавлен в белый список.${PLAIN}")"
            read_trimmed ip_whitelist_input "$(localized_text "请输入允许访问 ${domain} 的 IP/CIDR（多个用空格或英文逗号分隔）: " "Please enter the IP/CIDR that allows access to ${domain} (separate multiple by spaces or commas):" "Введите IP/CIDR, который разрешает доступ к ${domain} (разделяйте кратные пробелами или запятыми):")"
            if ! normalize_ip_whitelist_input "$ip_whitelist_input" ip_whitelist_array; then
                echo -e "$(localized_text "${RED}❌ 白名单为空或格式错误，已取消操作。${PLAIN}" "${RED}❌ The whitelist is empty or has an incorrect format, and the operation has been cancelled.${PLAIN}" "${RED}❌ Белый список пуст или имеет неверный формат, и операция отменена.${PLAIN}")"
                read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                return
            fi
            append_vps_public_ips_to_whitelist ip_whitelist_array
            ip_whitelist_ranges=$(join_array_by_space "${ip_whitelist_array[@]}")
            cp -p "$conf_file" "$backup_file" || { echo -e "$(localized_text "${RED}❌ 备份失败，已取消。${PLAIN}" "${RED}❌ Backup failed and has been cancelled.${PLAIN}" "${RED}❌ Резервное копирование не выполнено и было отменено.${PLAIN}")"; read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"; return; }
            if insert_caddy_ip_whitelist_block "$conf_file" "$ip_whitelist_ranges" && caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1; then
                if systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1; then
                    echo -e "$(localized_text "${GREEN}✅ 已为 ${domain} 启用 IP 白名单：${ip_whitelist_ranges}${PLAIN}" "${GREEN}✅ IP whitelist enabled for ${domain}: ${ip_whitelist_ranges}${PLAIN}" "${GREEN}✅ Белый список IP-адресов включен для ${domain}: ${ip_whitelist_ranges}${PLAIN}")"
                    echo -e "$(localized_text "${CYAN}配置备份已保留：${backup_file}${PLAIN}" "${CYAN}Configuration backup has been retained: ${backup_file}${PLAIN}" "${CYAN}Резервная копия конфигурации сохранена: ${backup_file}.${PLAIN}")"
                else
                    echo -e "$(localized_text "${RED}❌ Caddy 重载失败，正在回滚...${PLAIN}" "${RED}❌ Caddy Reload failed, rolling back...${PLAIN}" "${RED}❌ Caddy Ошибка перезагрузки, откат...${PLAIN}")"
                    mv "$backup_file" "$conf_file"
                    systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1 || true
                fi
            else
                echo -e "$(localized_text "${RED}❌ 写入后 Caddy 校验失败，正在回滚...${PLAIN}" "${RED}❌ After writing Caddy verification failed, rolling back...${PLAIN}" "${RED}❌ После записи Caddy проверка не удалась, откат...${PLAIN}")"
                mv "$backup_file" "$conf_file"
            fi
            ;;
        2)
            if ! grep -q '# vps-optimize-ip-whitelist-start' "$conf_file" 2>/dev/null; then
                echo -e "$(localized_text "${BLUE}该域名没有脚本管理的白名单块，无需清除。${PLAIN}" "${BLUE}This domain does not have a script-managed whitelist block and does not need to be cleared.${PLAIN}" "${BLUE}Это доменное имя не имеет блока белого списка, управляемого сценарием, и его не нужно очищать.${PLAIN}")"
                read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
                return
            fi
            cp -p "$conf_file" "$backup_file" || { echo -e "$(localized_text "${RED}❌ 备份失败，已取消。${PLAIN}" "${RED}❌ Backup failed and has been cancelled.${PLAIN}" "${RED}❌ Резервное копирование не выполнено и было отменено.${PLAIN}")"; read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"; return; }
            if strip_caddy_ip_whitelist_block "$conf_file" && caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1; then
                systemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy >/dev/null 2>&1 || true
                echo -e "$(localized_text "${GREEN}✅ 已清除 ${domain} 的 IP 白名单。${PLAIN}" "${GREEN}✅ The IP whitelist of ${domain} has been cleared.${PLAIN}" "${GREEN}✅ Белый список IP-адресов ${domain} очищен.${PLAIN}")"
                echo -e "$(localized_text "${CYAN}配置备份已保留：${backup_file}${PLAIN}" "${CYAN}Configuration backup has been retained: ${backup_file}${PLAIN}" "${CYAN}Резервная копия конфигурации сохранена: ${backup_file}.${PLAIN}")"
            else
                echo -e "$(localized_text "${RED}❌ 清除后 Caddy 校验失败，正在回滚...${PLAIN}" "${RED}❌ After clearing Caddy Verification failed, rolling back...${PLAIN}" "${RED}❌ После очистки Caddy проверка не удалась, откат...${PLAIN}")"
                mv "$backup_file" "$conf_file"
            fi
            ;;
        0|q|Q|"")
            echo -e "$(localized_text "${BLUE}已取消。${PLAIN}" "${BLUE}Has been cancelled.${PLAIN}" "${BLUE}отменен.${PLAIN}")"
            ;;
        *)
            echo -e "$(localized_text "${RED}❌ 无效操作。${PLAIN}" "${RED}❌ Invalid operation.${PLAIN}" "${RED}❌ Недопустимая операция.${PLAIN}")"
            ;;
    esac

    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
}
# ---------------------------------------------------------
# 清理域名证书、配置与端口占用
# ---------------------------------------------------------
sync_sni_stack_state_after_caddy_domain_delete() {
    local domain="$1"
    local env_file="/etc/vps-optimize/sni-stack.env"
    local i removed=0
    local -a new_domains=()
    local -a new_addrs=()
    local -a new_ports=()

    [[ -f "$env_file" ]] || return 0
    load_sni_stack_env >/dev/null 2>&1 || return 0

    if [[ "$domain" == "${PANEL_DOMAIN:-}" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ ${domain} 是当前 443端口复用面板域名，保存状态仍会引用它；重新应用前必须重新签发证书或更换面板域名。${PLAIN}" "${YELLOW}⚠️ ${domain} is the current Port 443 Reuse panel domain, and the saved state will still refer to it; the certificate must be re-issued or the panel domain must be changed before re-applying.${PLAIN}" "${YELLOW}⚠️ ${domain} — это текущее доменное имя панели с единым вводом 443, и сохраненное состояние по-прежнему будет ссылаться на него; сертификат необходимо перевыпустить или изменить доменное имя панели перед повторной подачей заявки.${PLAIN}")"
        return 0
    fi

    for i in "${!SITE_DOMAINS[@]}"; do
        if [[ "$domain" == "${SITE_DOMAINS[$i]}" ]]; then
            removed=1
            continue
        fi
        new_domains+=("${SITE_DOMAINS[$i]}")
        new_addrs+=("${SITE_BACKEND_ADDRS[$i]}")
        new_ports+=("${SITE_BACKEND_PORTS[$i]}")
    done

    [[ "$removed" -eq 1 ]] || return 0
    SITE_DOMAINS=("${new_domains[@]}")
    SITE_BACKEND_ADDRS=("${new_addrs[@]}")
    SITE_BACKEND_PORTS=("${new_ports[@]}")
    remove_sni_ip_whitelist_for_domain "$domain"
    save_sni_stack_env
    echo -e "$(localized_text "${GREEN}✅ 已同步移除 443端口复用保存状态中的 Web 域名：${domain}${PLAIN}" "${GREEN}✅ The web domain in the saved status of Port 443 Reuse has been removed simultaneously: ${domain}${PLAIN}" "${GREEN}. Имя веб-домена в сохраненном состоянии повторного использования порта 443 было одновременно удалено: ${domain}.${PLAIN}")"
}

func_caddy_delete_cert() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}清理域名证书与配置${PLAIN}" "${BOLD}Clean up domain certificate and configuration${PLAIN}" "${BOLD}Очистка сертификата и конфигурации доменного имени${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${YELLOW}将隔离指定域名的证书和配置，并清理 acme.sh 残留。${PLAIN}" "${YELLOW}Will isolate the certificate and configuration of the specified domain and clean up the residue of acme.sh.${PLAIN}" "${YELLOW}изолирует сертификат и конфигурацию указанного доменного имени и очистит остатки acme.sh.${PLAIN}")"
    echo -e "------------------------------------------------"
    
    local domain domain_input
    read_trimmed domain_input "$(localized_text "👉 请输入要清理的域名（例如 panel.site.com）: " "👉 Please enter the domain to be cleaned (for example panel.site.com):" "👉 Введите имя домена, который необходимо очистить (например, Panel.site.com):")"
    domain=$(normalize_domain_input "$domain_input")
    if [[ -z "$domain" ]]; then
        echo -e "$(localized_text "${RED}❌ 域名不能为空！${PLAIN}" "${RED}❌ The domain cannot be empty!${PLAIN}" "${RED}❌ Доменное имя не может быть пустым!${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
        return
    fi
    if ! is_valid_domain "$domain"; then
        print_domain_validation_error "$(localized_text "域名" "domain" "доменное имя")" "$domain_input" "$domain"
        echo -e "$(localized_text "${RED}❌ 已取消清理。${PLAIN}" "${RED}❌ Cleanup canceled.${PLAIN}" "${RED}❌ Очистка отменена.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
        return
    fi

    echo -e "$(localized_text "\n${CYAN}▶ 正在清理域名证书与配置...${PLAIN}" "\n${CYAN}▶ Cleaning up domain certificate and configuration...${PLAIN}" "\n${CYAN}▶ Очистка сертификата и конфигурации доменного имени...${PLAIN}")"
    echo -e "$(localized_text "${YELLOW}此操作会移走该域名的证书与配置，相关网站会暂时不可用。${PLAIN}" "${YELLOW}This operation will remove the certificate and configuration of the domain, and the related website will be temporarily unavailable.${PLAIN}" "${YELLOW}Эта операция приведет к удалению сертификата и конфигурации доменного имени, а соответствующий веб-сайт будет временно недоступен.${PLAIN}")"
    echo -e "$(localized_text "请确认操作...${PLAIN}" "Please confirm the operation...${PLAIN}" "Пожалуйста, подтвердите операцию...${PLAIN}")"
    if confirm_danger "$(localized_text "清理 ${domain} 的证书与配置" "Clean up the certificate and configuration of ${domain}" "Очистите сертификат и конфигурацию ${domain}.")" "$(localized_text "会停止 Caddy，隔离该域名的 Caddy/Nginx 配置、共享证书文件和 acme.sh 残留，再启动/重载相关服务。" "Caddy will be stopped, the Caddy/Nginx configuration, shared certificate file and acme.sh residue of the domain will be isolated, and then related services will be started/reloaded." "Caddy будет остановлен, конфигурация Caddy/Nginx, файл общего сертификата и остаток acme.sh доменного имени будут изолированы, а затем соответствующие службы будут запущены/перезагружены.")" "$(localized_text "请先确认已有系统快照或反代配置备份；清理后的证书需要重新签发。" "Please first confirm that you have a system snapshot or reverse configuration backup; the cleaned certificate needs to be re-issued." "Сначала подтвердите, что у вас есть снимок системы или резервная копия обратной конфигурации; очищенный сертификат необходимо перевыпустить.")"; then
        # 1. 停止 Caddy，强制释放 80/443 端口
        systemctl stop caddy >/dev/null 2>&1
        echo -e "$(localized_text "${GREEN}✅ [1/4] 已强制停止 Caddy 服务，释放网络端口。${PLAIN}" "${GREEN}✅ [1/4] The Caddy service has been forcibly stopped and the network port has been released.${PLAIN}" "${GREEN}✅ [1/4] Служба Caddy была принудительно остановлена, а сетевой порт освобожден.${PLAIN}")"
        
        # 2. 深度清理 Caddy 底层证书缓存
        local caddy_paths=("/var/lib/caddy/.local/share/caddy/certificates" "/root/.local/share/caddy/certificates")
        local caddy_found=false
        for cp in "${caddy_paths[@]}"; do
            if [[ -d "$cp" ]]; then
                local target=$(find "$cp" -type d -name "${domain}" -print -quit 2>/dev/null)
                if [[ -n "$target" ]]; then
                    quarantine_path "$target" "/root/vps-optimize-quarantine/caddy-certs" >/dev/null 2>&1 || true
                    caddy_found=true
                fi
            fi
        done
        if $caddy_found; then
            echo -e "$(localized_text "${GREEN}✅ [2/4] Caddy 引擎中关于 ${domain} 的密钥与证书已抹除。${PLAIN}" "${GREEN}✅ [2/4] The key and certificate related to ${domain} in the Caddy engine have been erased.${PLAIN}" "${GREEN}✅ [2/4] Ключ и сертификат, относящиеся к ${domain} в движке Caddy, были стерты.${PLAIN}")"
        else
            echo -e "$(localized_text "${BLUE}ℹ️ [2/4] 未在 Caddy 引擎中发现该域名的证书。${PLAIN}" "${BLUE}ℹ️ [2/4] The certificate for this domain was not found in the Caddy engine.${PLAIN}" "${BLUE}ℹ️ [2/4] Сертификат для этого доменного имени не найден в движке Caddy.${PLAIN}")"
        fi
        
        # 3. 清理 acme.sh 残留
        if [[ -d "/root/.acme.sh" ]]; then
            local acme_target=$(find "/root/.acme.sh" -type d -name "*${domain}*" -print -quit 2>/dev/null)
            if [[ -n "$acme_target" ]]; then
                quarantine_path "$acme_target" "/root/.acme.sh/_quarantine" >/dev/null 2>&1 || true
                echo -e "$(localized_text "${GREEN}✅ [3/4] 面板底层 (~/.acme.sh) 关于 ${domain} 的残留已抹除。${PLAIN}" "${GREEN}✅ [3/4] The remnants of ${domain} on the bottom layer of the panel (~/.acme.sh) have been erased.${PLAIN}" "${GREEN}✅ [3/4] Остатки ${domain} на нижнем слое панели (~/.acme.sh) стерты.${PLAIN}")"
            else
                echo -e "$(localized_text "${BLUE}ℹ️ [3/4] 未在 acme.sh 引擎中发现残留。${PLAIN}" "${BLUE}ℹ️ [3/4] No residue found in acme.sh engine.${PLAIN}" "${BLUE}ℹ️ [3/4] В двигателе acme.sh остатков не обнаружено.${PLAIN}")"
            fi
        else
            echo -e "$(localized_text "${BLUE}ℹ️ [3/4] 系统未安装独立 acme.sh 环境，已跳过。${PLAIN}" "${BLUE}ℹ️ [3/4] The independent acme.sh environment is not installed on the system and has been skipped.${PLAIN}" "${BLUE}ℹ️ [3/4] Независимая среда acme.sh не установлена в системе и пропущена.${PLAIN}")"
        fi
        
        # 4. 外科手术：模块化安全删除 Caddy/Nginx 域名配置
        local domain_conf="/etc/caddy/conf.d/${domain}.caddy"
        if [[ -f "$domain_conf" ]]; then
            echo -e "$(localized_text "${YELLOW}⏳ [4/5] 检测到 Caddy 专属配置文件，正在隔离...${PLAIN}" "${YELLOW}⏳ [4/5] Detected Caddy exclusive configuration file, isolating...${PLAIN}" "${YELLOW}⏳ [4/5] Обнаружен эксклюзивный файл конфигурации Caddy, изолирующий...${PLAIN}")"
            quarantine_path "$domain_conf" "/etc/vps-optimize/quarantine/caddy-conf" >/dev/null 2>&1 || true
            echo -e "$(localized_text "${GREEN}✅ [4/5] Caddy 专属配置文件 ($domain_conf) 已隔离！${PLAIN}" "${GREEN}✅ [4/5] Caddy exclusive profile ($domain_conf) has been quarantined!${PLAIN}" "${GREEN}✅ [4/5] Эксклюзивный профиль Caddy ($domain_conf) помещен на карантин!${PLAIN}")"
        else
            echo -e "$(localized_text "${GREEN}✅ [4/5] 未发现该域名的 Caddy 专属配置文件。${PLAIN}" "${GREEN}✅ [4/5] No Caddy exclusive configuration file was found for this domain.${PLAIN}" "${GREEN}✅ [4/5] Для этого доменного имени не найден эксклюзивный файл конфигурации Caddy.${PLAIN}")"
        fi
        local nginx_domain_conf
        nginx_domain_conf=$(nginx_proxy_conf_path "$domain" 2>/dev/null || echo "/etc/nginx/conf.d/vps_proxy_${domain}.conf")
        if [[ -f "$nginx_domain_conf" ]]; then
            quarantine_path "$nginx_domain_conf" "/etc/vps-optimize/quarantine/nginx-proxy" >/dev/null 2>&1 || true
            echo -e "$(localized_text "${GREEN}✅ 已隔离 Nginx 反代配置：${nginx_domain_conf}${PLAIN}" "${GREEN}✅ Isolated Nginx Reverse configuration: ${nginx_domain_conf}${PLAIN}" "${GREEN}✅ Изолированный Nginx Обратная конфигурация: ${nginx_domain_conf}${PLAIN}")"
        fi

        # 5. 隔离共享证书安装路径，Nginx 反代也复用这些证书。
        local shared_cert_file
        echo -e "$(localized_text "${YELLOW}⏳ [5/5] 正在隔离共享证书安装路径...${PLAIN}" "${YELLOW}⏳ [5/5] Isolating the shared certificate installation path...${PLAIN}" "${YELLOW}⏳ [5/5] Изолирование пути установки общего сертификата...${PLAIN}")"
        for shared_cert_file in "/etc/caddy/certs/${domain}.crt" "/etc/caddy/certs/${domain}.key" "/root/cert/${domain}.crt" "/root/cert/${domain}.key"; do
            if [[ -e "$shared_cert_file" || -L "$shared_cert_file" ]]; then
                quarantine_path "$shared_cert_file" "/etc/vps-optimize/quarantine/shared-certs" >/dev/null 2>&1 || true
                echo -e "$(localized_text "${GREEN}✅ 已隔离共享证书路径：${shared_cert_file}${PLAIN}" "${GREEN}✅ Isolated shared certificate path: ${shared_cert_file}${PLAIN}" "${GREEN}✅ Путь к изолированному общему сертификату: ${shared_cert_file}${PLAIN}")"
            fi
        done

        # 重启 Caddy 以加载干净的配置
        systemctl start caddy >/dev/null 2>&1
        if command -v nginx >/dev/null 2>&1; then
            nginx -t >/dev/null 2>&1 && { systemctl reload nginx >/dev/null 2>&1 || systemctl restart nginx >/dev/null 2>&1 || true; }
        fi
        sync_sni_stack_state_after_caddy_domain_delete "$domain" || true
        generate_caddy_cf_manifest 2>/dev/null || true

        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}✅ 清理完成；相关配置和证书已移入隔离目录。${PLAIN}" "${GREEN}✅ Cleanup completed; related configurations and certificates have been moved to the isolation directory.${PLAIN}" "${GREEN}✅ Очистка завершена; связанные конфигурации и сертификаты были перемещены в каталог изоляции.${PLAIN}")"
    else
        echo -e "$(localized_text "${BLUE}操作已取消。${PLAIN}" "${BLUE}Operation has been cancelled.${PLAIN}" "${BLUE}Операция отменена.${PLAIN}")"
    fi
    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
}

# ---------------------------------------------------------
# 新增功能：独立追加 Caddy 跳过不安全证书反代块 (模块化版)
# ---------------------------------------------------------
func_caddy_add_insecure() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🛡️ 独立配置：追加 Caddy 跳过证书验证反代${PLAIN}" "${BOLD}🛡️ Independent configuration: append Caddy to skip certificate verification and replace with${PLAIN}" "${BOLD}🛡️ Независимая конфигурация: добавьте Caddy, чтобы пропустить проверку сертификата, и замените на.${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    if [[ ! -f /etc/caddy/Caddyfile ]]; then
        echo -e "$(localized_text "${RED}❌ 未检测到 Caddy 配置文件，请先运行 [13] 安装 Caddy！${PLAIN}" "${RED}❌ The Caddy configuration file is not detected, please run [13] to install Caddy first!${PLAIN}" "${RED}❌ Файл конфигурации Caddy не обнаружен, пожалуйста, запустите [13], чтобы сначала установить Caddy!${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
        return
    fi
    
    local domain domain_input
    local backend_addr port
    local enable_ip_whitelist ip_whitelist_input ip_whitelist_ranges current_client_ip
    local -a ip_whitelist_array=()
    read_trimmed domain_input "$(localized_text "👉 请输入解析后的域名 (如 panel.site.com): " "👉 Please enter the resolved domain (such as panel.site.com):" "👉 Введите разрешенное доменное имя (например, Panel.site.com):")"
    read_trimmed port "$(localized_text "👉 请输入面板 HTTPS 本地映射端口 (如 40000): " "👉 Please enter the panel HTTPS local mapping port (such as 40000):" "👉 Введите локальный порт сопоставления панели HTTPS (например, 40000):")"
    backend_addr=$(ask_with_default "$(localized_text "后端地址" "Backend address" "Внутренний адрес")" "127.0.0.1")
    backend_addr=$(normalize_backend_addr_input "$backend_addr")
    if ! is_valid_backend_addr "$backend_addr"; then
        echo -e "$(localized_text "${RED}❌ 后端地址无效：${backend_addr}${PLAIN}" "${RED}❌ Invalid backend address: ${backend_addr}${PLAIN}" "${RED}❌ Неверный внутренний адрес: ${backend_addr}.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi
    domain=$(normalize_domain_input "$domain_input")
    
    if ! is_valid_domain "$domain"; then
        print_domain_validation_error "$(localized_text "域名" "domain" "доменное имя")" "$domain_input" "$domain"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi
    if ! is_valid_port "$port"; then
        echo -e "$(localized_text "${RED}❌ 端口格式错误：${port}，端口必须是 1-65535。已取消操作。${PLAIN}" "${RED}❌ Port format error: ${port}, the port must be 1-65535. Operation canceled.${PLAIN}" "${RED}❌ Ошибка формата порта: ${port}, порт должен быть 1-65535. Операция отменена.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
        return
    fi

    read_trimmed enable_ip_whitelist "$(localized_text "❓ 是否只允许指定 IP/CIDR 访问该域名？(y/N，默认 N): " "❓ Restrict this domain to specified IP/CIDR ranges? (y/N, default N): " "❓ Ограничить доступ к домену указанными IP/CIDR? (y/N, по умолчанию N): ")"
    if is_yes "$enable_ip_whitelist"; then
        current_client_ip=$(detect_ssh_client_ip)
        [[ -n "$current_client_ip" ]] && echo -e "$(localized_text "${YELLOW}当前 SSH 来源 IP 可能是：${current_client_ip}，请确认已加入白名单。${PLAIN}" "${YELLOW}The current source IP of SSH may be: ${current_client_ip}. Please confirm that it has been added to the whitelist.${PLAIN}" "${YELLOW}Текущий исходный IP-адрес SSH может быть: ${current_client_ip}. Пожалуйста, подтвердите, что он был добавлен в белый список.${PLAIN}")"
        read_trimmed ip_whitelist_input "$(localized_text "请输入允许访问 ${domain} 的 IP/CIDR（多个用空格或英文逗号分隔）: " "Please enter the IP/CIDR that allows access to ${domain} (separate multiple by spaces or commas):" "Введите IP/CIDR, который разрешает доступ к ${domain} (разделяйте кратные пробелами или запятыми):")"
        if ! normalize_ip_whitelist_input "$ip_whitelist_input" ip_whitelist_array; then
            echo -e "$(localized_text "${RED}❌ 白名单为空或格式错误，已取消操作。${PLAIN}" "${RED}❌ The whitelist is empty or has an incorrect format, and the operation has been cancelled.${PLAIN}" "${RED}❌ Белый список пуст или имеет неверный формат, и операция отменена.${PLAIN}")"
            read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
            return
        fi
        append_vps_public_ips_to_whitelist ip_whitelist_array
        ip_whitelist_ranges=$(join_array_by_space "${ip_whitelist_array[@]}")
    else
        ip_whitelist_ranges=""
    fi
    
    # 确保主文件包含模块化目录
    grep -q "import conf.d/\*" /etc/caddy/Caddyfile || echo -e "\nimport conf.d/*" >> /etc/caddy/Caddyfile
    
    mkdir -p /etc/caddy/conf.d
    local conf_file="/etc/caddy/conf.d/${domain}.caddy"
    local backup_file=""
    if [[ -f "$conf_file" ]]; then
        backup_file="${conf_file}.bak_$(date +%s)"
        if ! cp -p "$conf_file" "$backup_file"; then
            echo -e "$(localized_text "${RED}❌ 现有配置备份失败，已取消操作。${PLAIN}" "${RED}❌ The existing configuration backup failed and the operation has been cancelled.${PLAIN}" "${RED}❌ Не удалось выполнить резервное копирование существующей конфигурации, и операция была отменена.${PLAIN}")"
            read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
            return
        fi
    fi
    
    write_caddy_reverse_proxy_conf "$domain" "$backend_addr" "$port" "y" "$conf_file" "$ip_whitelist_ranges"
    if caddy validate --config /etc/caddy/Caddyfile >/dev/null 2>&1; then
        systemctl reload caddy >/dev/null 2>&1
        echo -e "$(localized_text "${GREEN}✅ 独立跳过验证配置已成功建立并生效！${PLAIN}" "${GREEN}✅ The independent skip verification configuration has been successfully established and takes effect!${PLAIN}" "${GREEN}✅ Конфигурация независимой проверки пропуска успешно установлена и вступила в силу!${PLAIN}")"
        [[ -n "$ip_whitelist_ranges" ]] && echo -e "$(localized_text "${GREEN}✅ 已为 ${domain} 启用 IP 白名单：${ip_whitelist_ranges}${PLAIN}" "${GREEN}✅ IP whitelist enabled for ${domain}: ${ip_whitelist_ranges}${PLAIN}" "${GREEN}✅ Белый список IP-адресов включен для ${domain}: ${ip_whitelist_ranges}${PLAIN}")"
    else
        echo -e "$(localized_text "${RED}❌ 新配置语法错误，正在回滚...${PLAIN}" "${RED}❌ New configuration syntax error, rolling back...${PLAIN}" "${RED}❌ Синтаксическая ошибка новой конфигурации, откат...${PLAIN}")"
        quarantine_path "$conf_file" "/etc/vps-optimize/quarantine/caddy-conf" >/dev/null 2>&1 || true
        [[ -n "$backup_file" && -f "$backup_file" ]] && mv "$backup_file" "$conf_file"
    fi

    read -n 1 -s -r -p "$(localized_text "按任意键继续..." "Press any key to continue..." "Нажмите любую клавишу, чтобы продолжить...")"
}
# ---------------------------------------------------------
# 4. SSH 安全加固 (终极完美版：防截断、防覆盖、防 Socket 冲突)
# ---------------------------------------------------------

# ---------------------------------------------------------
# Module: ssh_security.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# SSH hardening, SSH key workflows, authentication modes, and Fail2ban management.

ssh_service_restart() {
    systemctl restart sshd 2>/dev/null || systemctl restart ssh 2>/dev/null
}

ssh_prepare_runtime_dir() {
    if [[ ! -d /run/sshd ]]; then
        mkdir -p /run/sshd 2>/dev/null || return 1
    fi
    chmod 755 /run/sshd 2>/dev/null || true
}

ssh_socket_unit_exists() {
    local unit="$1"
    local active_state enabled_state
    active_state=$(systemctl is-active "$unit" 2>/dev/null || true)
    enabled_state=$(systemctl is-enabled "$unit" 2>/dev/null || true)
    [[ "$active_state" == "active" ]] && return 0
    [[ "$enabled_state" == "enabled" || "$enabled_state" == "enabled-runtime" ]]
}

ssh_socket_units_for_host() {
    local unit
    for unit in ssh.socket sshd.socket; do
        if ssh_socket_unit_exists "$unit"; then
            echo "$unit"
        fi
    done
}

ssh_write_socket_port_dropins() {
    local port="$1"
    local unit dir found=false
    while IFS= read -r unit; do
        [[ -z "$unit" ]] && continue
        found=true
        dir="/etc/systemd/system/${unit}.d"
        mkdir -p "$dir" || return 1
        cat > "${dir}/10-vps-optimize-port.conf" <<EOF
[Socket]
ListenStream=
ListenStream=${port}
EOF
    done < <(ssh_socket_units_for_host)
    $found
}

ssh_restart_socket_units() {
    local unit found=false ok=true
    systemctl daemon-reload >/dev/null 2>&1 || true
    while IFS= read -r unit; do
        [[ -z "$unit" ]] && continue
        found=true
        systemctl restart "$unit" >/dev/null 2>&1 || ok=false
    done < <(ssh_socket_units_for_host)
    $found && $ok
}

ssh_restart_runtime() {
    local restarted=false
    if ssh_restart_socket_units; then
        restarted=true
    fi
    if ssh_service_restart; then
        restarted=true
    fi
    $restarted
}

ssh_write_sshd_port_dropin() {
    local port="$1"
    mkdir -p /etc/ssh/sshd_config.d 2>/dev/null || return 1
    cat > /etc/ssh/sshd_config.d/00-vps-optimize-port.conf <<EOF
# VPS-Optimize SSH port mirror
Port ${port}
EOF
}

ssh_write_auth_dropin() {
    local mode="$1"
    local interactive_key="$2"
    case "$mode" in
        key_only|key_preferred|password) ;;
        *) return 1 ;;
    esac
    mkdir -p /etc/ssh/sshd_config.d 2>/dev/null || return 1
    {
        echo "# VPS-Optimize SSH auth mode mirror"
        echo "PubkeyAuthentication yes"
        case "$mode" in
            key_only)
                echo "PasswordAuthentication no"
                echo "${interactive_key} no"
                ;;
            key_preferred|password)
                echo "PasswordAuthentication yes"
                echo "${interactive_key} yes"
                ;;
        esac
    } > /etc/ssh/sshd_config.d/00-vps-optimize-auth.conf
}

ssh_restore_auth_dropin() {
    local dropin="$1"
    local backup="$2"
    if [[ -n "$backup" && -f "$backup" ]]; then
        cp -p "$backup" "$dropin" 2>/dev/null || true
    else
        mkdir -p "$(dirname "$dropin")" 2>/dev/null || return 0
        cat > "$dropin" <<EOF
# VPS-Optimize SSH auth mode mirror disabled after rollback
EOF
    fi
}

ssh_reconcile_cloud_auth_dropins() {
    local mode="$1"
    local state_file="$2"
    local timestamp="$3"
    local dir="/etc/ssh/sshd_config.d"
    local conf tmp backup current_auth_dropin

    : > "$state_file" || return 1
    [[ -d "$dir" ]] || return 0
    current_auth_dropin="/etc/ssh/sshd_config.d/00-vps-optimize-auth.conf"

    for conf in "$dir"/*.conf; do
        [[ -f "$conf" ]] || continue
        [[ "$conf" == "$current_auth_dropin" ]] && continue
        tmp=$(mktemp /tmp/vps-sshd-dropin.XXXXXX) || return 1
        if ! awk -v mode="$mode" '
            function desired_for(key, lkey) {
                lkey = tolower(key)
                if (lkey == "pubkeyauthentication") return "yes"
                if (lkey == "passwordauthentication") return mode == "key_only" ? "no" : "yes"
                if (lkey == "kbdinteractiveauthentication") return mode == "key_only" ? "no" : "yes"
                if (lkey == "challengeresponseauthentication") return mode == "key_only" ? "no" : "yes"
                return ""
            }
            /^[[:space:]]*#/ || /^[[:space:]]*$/ { print; next }
            /^[[:space:]]*Match[[:space:]]+/ { in_match = 1; print; next }
            in_match { print; next }
            {
                desired = desired_for($1)
                if (desired != "") {
                    if (tolower($2) == desired) {
                        print
                    } else {
                        print $1 " " desired " # VPS-Optimize reconciled cloud image setting"
                    }
                    next
                }
                print
            }
        ' "$conf" > "$tmp"; then
            rm -f "$tmp"
            return 1
        fi
        if ! cmp -s "$conf" "$tmp"; then
            backup="${conf}.bak_auth_${timestamp}"
            if ! cp -p "$conf" "$backup"; then
                rm -f "$tmp"
                return 1
            fi
            if ! cp "$tmp" "$conf"; then
                cp -p "$backup" "$conf" 2>/dev/null || true
                rm -f "$tmp"
                return 1
            fi
            printf '%s\t%s\n' "$conf" "$backup" >> "$state_file"
        fi
        rm -f "$tmp"
    done
}

ssh_restore_cloud_auth_dropins() {
    local state_file="$1"
    local conf backup
    [[ -f "$state_file" ]] || return 0
    while IFS=$'\t' read -r conf backup; do
        [[ -n "$conf" && -n "$backup" && -f "$backup" ]] || continue
        cp -p "$backup" "$conf" 2>/dev/null || true
    done < "$state_file"
}

ssh_assert_auth_mode_effective() {
    local mode="$1"
    local expected effective
    expected="yes"
    [[ "$mode" == "key_only" ]] && expected="no"
    effective=$(ssh_effective_setting PasswordAuthentication)
    [[ -z "$effective" ]] && return 0
    if [[ "$effective" != "$expected" ]]; then
        echo -e "$(localized_text "${RED}❌ SSH 最终生效值仍为 PasswordAuthentication ${effective}，可能有更早的云镜像子配置覆盖。${PLAIN}" "${RED}❌ SSH The final effective value is still PasswordAuthentication ${effective}, which may be covered by earlier cloud image sub-configurations.${PLAIN}" "${RED}❌ SSH Окончательным действующим значением по-прежнему является PasswordAuthentication ${effective}, которое может быть включено в более ранние подконфигурации облачного образа.${PLAIN}")"
        return 1
    fi
}

ssh_rollback_port_change() {
    local backup_file="$1"
    local current_port="$2"
    local socket_managed="${3:-false}"
    cp -p "$backup_file" /etc/ssh/sshd_config 2>/dev/null || true
    ssh_write_sshd_port_dropin "$current_port" >/dev/null 2>&1 || true
    if $socket_managed; then
        ssh_write_socket_port_dropins "$current_port" >/dev/null 2>&1 || true
        ssh_restart_socket_units >/dev/null 2>&1 || true
    fi
    ssh_service_restart >/dev/null 2>&1 || true
}

ssh_effective_setting() {
    local key="$1"
    local sshd_bin value
    sshd_bin=$(command -v sshd 2>/dev/null || true)
    if [[ -n "$sshd_bin" ]]; then
        ssh_prepare_runtime_dir >/dev/null 2>&1 || true
        value=$("$sshd_bin" -T 2>/dev/null | awk -v k="$(echo "$key" | tr '[:upper:]' '[:lower:]')" '$1 == k {print $2; exit}')
        [[ -n "$value" ]] || return 1
        printf '%s' "$value"
        return 0
    fi
    return 1
}

ssh_public_key_is_valid() {
    local key="$1"
    [[ "$key" =~ ^(ssh-rsa|ssh-ed25519|ecdsa-sha2-nistp(256|384|521)|sk-ssh-ed25519@openssh.com|sk-ecdsa-sha2-nistp256@openssh.com)[[:space:]][A-Za-z0-9+/=]+([[:space:]].*)?$ ]]
}

ssh_user_home() {
    local user="$1"
    getent passwd "$user" 2>/dev/null | awk -F: '{print $6; exit}'
}

ssh_authorized_keys_path() {
    local user="$1"
    local home_dir
    home_dir=$(ssh_user_home "$user")
    [[ -n "$home_dir" ]] || return 1
    printf '%s/.ssh/authorized_keys' "$home_dir"
}

ssh_authorized_key_count() {
    local user="$1"
    local key_file
    key_file=$(ssh_authorized_keys_path "$user" 2>/dev/null) || { echo 0; return 0; }
    [[ -r "$key_file" ]] || { echo 0; return 0; }
    grep -E '^(ssh-rsa|ssh-ed25519|ecdsa-sha2-|sk-)' "$key_file" 2>/dev/null | wc -l | awk '{print $1}'
}

ssh_choose_user() {
    local default_user user
    default_user="${SUDO_USER:-root}"
    [[ "$default_user" == "root" || -n "$(getent passwd "$default_user" 2>/dev/null)" ]] || default_user="root"
    user=$(ask_with_default "$(localized_text "目标 Linux 用户" "Target Linux user" "Целевой пользователь Linux")" "$default_user")
    if ! getent passwd "$user" >/dev/null 2>&1; then
        echo -e "$(localized_text "${RED}❌ 用户 ${user} 不存在。${PLAIN}" "${RED}❌ User ${user} does not exist.${PLAIN}" "${RED}❌ Пользователь ${user} не существует.${PLAIN}")" >&2
        return 1
    fi
    printf '%s' "$user"
}

ssh_add_public_key_for_user() {
    local user="$1"
    local ssh_key key_file ssh_dir home_dir
    home_dir=$(ssh_user_home "$user")
    [[ -n "$home_dir" ]] || return 1
    key_file="${home_dir}/.ssh/authorized_keys"
    ssh_dir="${home_dir}/.ssh"
    echo -e "$(localized_text "👇 ${CYAN}请粘贴 ${user} 的 SSH 公钥，粘贴后按回车：${PLAIN}" "👇 ${CYAN}Please paste the SSH public key of ${user} and press Enter after pasting:${PLAIN}" "👇 ${CYAN}Вставьте открытый ключ SSH ${user} и нажмите Enter после вставки:${PLAIN}")"
    read -r ssh_key
    if [[ -z "$ssh_key" ]]; then
        echo -e "$(localized_text "${RED}❌ 输入为空，已取消。${PLAIN}" "${RED}❌ The input is empty and canceled.${PLAIN}" "${RED}❌ Ввод пуст и отменен.${PLAIN}")"
        return 1
    fi
    if ! ssh_public_key_is_valid "$ssh_key"; then
        echo -e "$(localized_text "${RED}❌ 公钥格式无效。支持 ssh-rsa、ssh-ed25519、ecdsa、FIDO2 sk-*。${PLAIN}" "${RED}❌ The public key format is invalid. Support ssh-rsa, ssh-ed25519, ecdsa, FIDO2 sk-*.${PLAIN}" "${RED}❌ Неверный формат открытого ключа. Поддержка ssh-rsa, ssh-ed25519, ecdsa, FIDO2 sk-*.${PLAIN}")"
        return 1
    fi
    mkdir -p "$ssh_dir" || return 1
    touch "$key_file" || return 1
    chmod 700 "$ssh_dir"
    chmod 600 "$key_file"
    if [[ "$user" != "root" ]]; then
        chown -R "$user:$user" "$ssh_dir" 2>/dev/null || true
    fi
    if grep -q -F -x "$ssh_key" "$key_file"; then
        echo -e "$(localized_text "${YELLOW}⚠️ 该公钥已存在，无需重复添加。${PLAIN}" "${YELLOW}⚠️ This public key already exists and there is no need to add it again.${PLAIN}" "${YELLOW}⚠️ Этот открытый ключ уже существует, и нет необходимости добавлять его снова.${PLAIN}")"
        return 0
    fi
    printf '%s\n' "$ssh_key" >> "$key_file"
    echo -e "$(localized_text "${GREEN}✅ 已为 ${user} 添加 SSH 公钥。${PLAIN}" "${GREEN}✅ The SSH public key has been added for ${user}.${PLAIN}" "${GREEN}. Для ${user} добавлен открытый ключ SSH.${PLAIN}")"
}

ssh_apply_auth_mode() {
    local mode="$1"
    local label backup_file tmp_file sshd_bin interactive_key auth_dropin auth_dropin_backup auth_reconcile_state timestamp reconciled_count
    sshd_bin=$(command -v sshd 2>/dev/null || true)
    [[ -n "$sshd_bin" && -f /etc/ssh/sshd_config ]] || {
        echo -e "$(localized_text "${RED}❌ 未找到 sshd 或 /etc/ssh/sshd_config，已取消。${PLAIN}" "${RED}❌ sshd or /etc/ssh/sshd_config not found, canceled.${PLAIN}" "${RED}❌ sshd или /etc/ssh/sshd_config не найден, отменен.${PLAIN}")"
        return 1
    }
    if ! ssh_prepare_runtime_dir; then
        echo -e "$(localized_text "${RED}❌ 无法创建 /run/sshd，sshd 无法完成语法检查。请确认当前为 root 权限。${PLAIN}" "${RED}❌ Unable to create /run/sshd, sshd Unable to complete syntax check. Please confirm that you currently have root privileges.${PLAIN}" "${RED}❌ Невозможно создать /run/sshd, sshd Невозможно завершить проверку синтаксиса. Пожалуйста, подтвердите, что у вас есть root-права.${PLAIN}")"
        return 1
    fi
    case "$mode" in
        key_only) label="$(localized_text "仅密钥登录（禁用密码）" "Key login only (password disabled)" "Вход только с помощью ключа (пароль отключен)")" ;;
        key_preferred|password) label="$(localized_text "密钥 + 密码登录（保留/恢复密码）" "Key + Password Login (Keep/Recover Password)" "Ключ + пароль для входа (Сохранить/Восстановить пароль)")" ;;
        *) return 1 ;;
    esac
    confirm_risk_action "$(localized_text "切换 SSH 登录模式：${label}" "Switch SSH login mode: ${label}" "Переключить режим входа в SSH: ${label}")" \
        "$(localized_text "/etc/ssh/sshd_config 与 /etc/ssh/sshd_config.d 登录认证配置" "/etc/ssh/sshd_config and /etc/ssh/sshd_config.d login authentication configuration" "Конфигурация аутентификации входа в систему /etc/ssh/sshd_config и /etc/ssh/sshd_config.d")" \
        "$(localized_text "使用本菜单的“密钥 + 密码登录”恢复密码登录，或从自动备份恢复 /etc/ssh/sshd_config 与对应子配置备份" "Use \"Key + Password Login\" in this menu to restore password login, or restore /etc/ssh/sshd_config and corresponding sub-configuration backup from automatic backup" "Используйте «Ключ + пароль для входа» в этом меню, чтобы восстановить вход с паролем или восстановить /etc/ssh/sshd_config и соответствующую резервную копию подконфигурации из автоматической резервной копии.")" \
        "$(localized_text "会同步处理 50-cloud-init.conf 等云镜像子配置；切到仅密钥登录前，必须先确认新 SSH 窗口能用私钥登录。" "Cloud image sub-configurations such as 50-cloud-init.conf will be processed synchronously; before switching to key-only login, you must first confirm that the new SSH window can be logged in with the private key." "Подконфигурации облачного образа, такие как 50-cloud-init.conf, будут обрабатываться синхронно; перед переключением на вход только по ключу вы должны сначала подтвердить, что в новое окно SSH можно войти с помощью закрытого ключа.")" || return 1

    timestamp=$(date +%s)
    interactive_key="KbdInteractiveAuthentication"
    if ! "$sshd_bin" -T 2>/dev/null | grep -qi '^kbdinteractiveauthentication '; then
        interactive_key="ChallengeResponseAuthentication"
    fi
    auth_dropin="/etc/ssh/sshd_config.d/00-vps-optimize-auth.conf"
    auth_dropin_backup=""
    auth_reconcile_state=$(mktemp /tmp/vps-sshd-reconcile.XXXXXX) || return 1
    backup_file="/etc/ssh/sshd_config.bak_auth_${timestamp}"
    cp -p /etc/ssh/sshd_config "$backup_file" || {
        echo -e "$(localized_text "${RED}❌ SSH 配置备份失败，已取消。${PLAIN}" "${RED}❌ SSH Configuration backup failed and has been cancelled.${PLAIN}" "${RED}❌ SSH Резервное копирование конфигурации не выполнено и было отменено.${PLAIN}")"
        rm -f "$auth_reconcile_state"
        return 1
    }
    if [[ -f "$auth_dropin" ]]; then
        auth_dropin_backup="${auth_dropin}.bak_auth_${timestamp}"
        cp -p "$auth_dropin" "$auth_dropin_backup" || {
            echo -e "$(localized_text "${RED}❌ SSH drop-in 配置备份失败，已取消。${PLAIN}" "${RED}❌ SSH drop-in configuration backup failed and has been cancelled.${PLAIN}" "${RED}❌ SSH Резервное копирование конфигурации Drop-In не удалось и было отменено.${PLAIN}")"
            rm -f "$auth_reconcile_state"
            return 1
        }
    fi
    tmp_file=$(mktemp /tmp/vps-sshd.XXXXXX) || { rm -f "$auth_reconcile_state"; return 1; }
    awk '
        /^# VPS-Optimize SSH auth mode begin$/ {skip=1; next}
        /^# VPS-Optimize SSH auth mode end$/ {skip=0; next}
        skip != 1 {print}
    ' /etc/ssh/sshd_config > "$tmp_file" || {
        rm -f "$tmp_file"
        rm -f "$auth_reconcile_state"
        return 1
    }
    {
        echo "# VPS-Optimize SSH auth mode begin"
        echo "PubkeyAuthentication yes"
        case "$mode" in
            key_only)
                echo "PasswordAuthentication no"
                echo "${interactive_key} no"
                ;;
            key_preferred|password)
                echo "PasswordAuthentication yes"
                echo "${interactive_key} yes"
                ;;
        esac
        echo "# VPS-Optimize SSH auth mode end"
        cat "$tmp_file"
    } > /etc/ssh/sshd_config
    rm -f "$tmp_file"

    if ! ssh_write_auth_dropin "$mode" "$interactive_key"; then
        echo -e "$(localized_text "${RED}❌ 写入 SSH drop-in 登录配置失败，正在回滚。${PLAIN}" "${RED}❌ Write SSH drop-in The login configuration failed and is being rolled back.${PLAIN}" "${RED}❌ Запись SSH. Не удалось настроить вход в систему, и выполняется откат.${PLAIN}")"
        cp -p "$backup_file" /etc/ssh/sshd_config
        ssh_restore_auth_dropin "$auth_dropin" "$auth_dropin_backup"
        rm -f "$auth_reconcile_state"
        return 1
    fi

    if ! ssh_reconcile_cloud_auth_dropins "$mode" "$auth_reconcile_state" "$timestamp"; then
        echo -e "$(localized_text "${RED}❌ 处理云镜像 SSH 子配置失败，正在回滚。${PLAIN}" "${RED}❌ Processing cloud image SSH sub-configuration failed and is being rolled back.${PLAIN}" "${RED}❌ Не удалось обработать облачный образ подконфигурации SSH, и выполняется откат.${PLAIN}")"
        cp -p "$backup_file" /etc/ssh/sshd_config
        ssh_restore_auth_dropin "$auth_dropin" "$auth_dropin_backup"
        ssh_restore_cloud_auth_dropins "$auth_reconcile_state"
        rm -f "$auth_reconcile_state"
        return 1
    fi

    if ! "$sshd_bin" -t; then
        echo -e "$(localized_text "${RED}❌ SSH 配置语法检查失败，正在回滚。${PLAIN}" "${RED}❌ SSH The configuration syntax check failed and is being rolled back.${PLAIN}" "${RED}❌ SSH Проверка синтаксиса конфигурации не удалась, и выполняется откат.${PLAIN}")"
        cp -p "$backup_file" /etc/ssh/sshd_config
        ssh_restore_auth_dropin "$auth_dropin" "$auth_dropin_backup"
        ssh_restore_cloud_auth_dropins "$auth_reconcile_state"
        rm -f "$auth_reconcile_state"
        return 1
    fi
    if ! ssh_assert_auth_mode_effective "$mode"; then
        echo -e "$(localized_text "${RED}❌ SSH 登录模式未真正生效，正在回滚。${PLAIN}" "${RED}❌ SSH The login mode has not really taken effect and is being rolled back.${PLAIN}" "${RED}❌ SSH Режим входа в систему на самом деле не вступил в силу и выполняется откат.${PLAIN}")"
        cp -p "$backup_file" /etc/ssh/sshd_config
        ssh_restore_auth_dropin "$auth_dropin" "$auth_dropin_backup"
        ssh_restore_cloud_auth_dropins "$auth_reconcile_state"
        rm -f "$auth_reconcile_state"
        return 1
    fi
    if ! ssh_restart_runtime; then
        echo -e "$(localized_text "${RED}❌ SSH 服务重启失败，正在回滚。${PLAIN}" "${RED}❌ SSH The service failed to restart and is being rolled back.${PLAIN}" "${RED}❌ SSH Службу не удалось перезапустить, и выполняется откат.${PLAIN}")"
        cp -p "$backup_file" /etc/ssh/sshd_config
        ssh_restore_auth_dropin "$auth_dropin" "$auth_dropin_backup"
        ssh_restore_cloud_auth_dropins "$auth_reconcile_state"
        ssh_restart_runtime >/dev/null 2>&1 || true
        rm -f "$auth_reconcile_state"
        return 1
    fi
    echo -e "$(localized_text "${GREEN}✅ SSH 登录模式已切换为：${label}${PLAIN}" "${GREEN}✅ SSH login mode has been switched to: ${label}${PLAIN}" "${GREEN}✅ SSH Режим входа в систему переключен на: ${label}${PLAIN}")"
    echo -e "$(localized_text "${CYAN}配置备份已保留：${backup_file}${PLAIN}" "${CYAN}Configuration backup has been retained: ${backup_file}${PLAIN}" "${CYAN}Резервная копия конфигурации сохранена: ${backup_file}.${PLAIN}")"
    reconciled_count=$(wc -l < "$auth_reconcile_state" 2>/dev/null | awk '{print $1}')
    if [[ "$reconciled_count" =~ ^[0-9]+$ && "$reconciled_count" -gt 0 ]]; then
        echo -e "$(localized_text "${CYAN}已同步 ${reconciled_count} 个云镜像 SSH 子配置，例如 50-cloud-init.conf。${PLAIN}" "${CYAN}Has synchronized ${reconciled_count} cloud image SSH sub-configuration, such as 50-cloud-init.conf.${PLAIN}" "${CYAN}синхронизировал подконфигурацию облачного образа ${reconciled_count} SSH, например 50-cloud-init.conf.${PLAIN}")"
    fi
    rm -f "$auth_reconcile_state"
}

func_ssh_login_mode_menu() {
    local unknown_label
    unknown_label="$(localized_text "未知" "Unknown" "Неизвестно")"
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        print_breadcrumb "$(localized_text "SSH 安全中心 > 用户密钥登录模式" "SSH Security Center > User Key Login Mode" "SSH Центр безопасности > Режим входа в систему с помощью ключа пользователя")"
        echo -e "$(localized_text "${BOLD}🔐 用户密钥登录模式${PLAIN}" "${BOLD}🔐 User key login mode${PLAIN}" "${BOLD}🔐 Режим входа в систему с помощью ключа пользователя${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "PubkeyAuthentication       : ${CYAN}$(ssh_effective_setting PubkeyAuthentication || echo "$unknown_label")${PLAIN}"
        echo -e "PasswordAuthentication     : ${CYAN}$(ssh_effective_setting PasswordAuthentication || echo "$unknown_label")${PLAIN}"
        echo -e "KbdInteractiveAuthentication: ${CYAN}$(ssh_effective_setting KbdInteractiveAuthentication || echo "$unknown_label")${PLAIN}"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}  1. 添加/更新用户 SSH 公钥（不改登录方式）${PLAIN}" "${GREEN}1. Add/update user SSH public key (do not change login method)${PLAIN}" "${GREEN}1. Добавьте/обновите открытый ключ пользователя SSH (не меняйте метод входа в систему)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 密钥 + 密码登录（保留/恢复密码）${PLAIN}" "${GREEN}2. Key + password login (retain/recover password)${PLAIN}" "${GREEN}2. Ключ + пароль для входа (сохранить/восстановить пароль)${PLAIN}")"
        echo -e "$(localized_text "${RED}  3. 仅密钥登录，禁用密码登录${PLAIN}" "${RED}3. Only key login, password login is disabled${PLAIN}" "${RED}3. Вход только по ключу, вход по паролю отключен${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}  0. 返回上一级 / q 返回${PLAIN}" "${RED}0. Back / q Back${PLAIN}" "${RED}0. Назад / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        local choice user key_count
        read_trimmed choice "$(localized_text "👉 请选择操作: " "👉 Please select an operation:" "👉 Пожалуйста, выберите операцию:")"
        case "$choice" in
            1)
                user=$(ssh_choose_user) || { pause_return; continue; }
                ssh_add_public_key_for_user "$user"
                pause_return
                ;;
            2) ssh_apply_auth_mode key_preferred; pause_return ;;
            3)
                user=$(ssh_choose_user) || { pause_return; continue; }
                key_count=$(ssh_authorized_key_count "$user")
                if [[ "$key_count" -eq 0 ]]; then
                    echo -e "$(localized_text "${RED}❌ 用户 ${user} 还没有 authorized_keys，不能切到仅密钥登录。${PLAIN}" "${RED}❌ User ${user} has no authorized_keys and cannot switch to key-only login.${PLAIN}" "${RED}❌ У пользователя ${user} нет authorized_keys, поэтому вход только по ключу включить нельзя.${PLAIN}")"
                    echo -e "$(localized_text "${YELLOW}请先用本菜单 [1] 添加公钥，并用新 SSH 窗口测试成功。${PLAIN}" "${YELLOW}Please use this menu [1] to add the public key first, and test successfully with the new SSH window.${PLAIN}" "${YELLOW}Используйте это меню [1], чтобы сначала добавить открытый ключ и успешно протестировать его в новом окне SSH.${PLAIN}")"
                    pause_return
                    continue
                fi
                echo -e "$(localized_text "${YELLOW}检测到 ${user} 已有 ${key_count} 条公钥。切换后密码登录会被禁用。${PLAIN}" "${YELLOW}${user} has ${key_count} public key(s). Password login will be disabled.${PLAIN}" "${YELLOW}У пользователя ${user} есть открытые ключи: ${key_count}. Вход по паролю будет отключён.${PLAIN}")"
                ssh_apply_auth_mode key_only
                pause_return
                ;;
            0|q|Q) break ;;
            *) echo -e "$(localized_text "${RED}❌ 无效选择！${PLAIN}" "${RED}❌ Invalid selection!${PLAIN}" "${RED}❌ Неверный выбор!${PLAIN}")"; sleep 1 ;;
        esac
    done
}

func_ssh_security_menu() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        print_breadcrumb "$(localized_text "SSH 安全中心" "SSH Security Center" "SSH Центр безопасности")"
        echo -e "$(localized_text "${BOLD}🛡️ SSH 安全中心${PLAIN}" "${BOLD}🛡️ SSH Security Center${PLAIN}" "${BOLD}🛡️ SSH Центр безопасности${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${GREEN}  1. 修改 SSH 端口${PLAIN}             ${YELLOW}(防失联校验和回滚)${PLAIN}" "${GREEN}1. Modify SSH port (lockout checks and rollback)${PLAIN}" "${GREEN}1. Измените порт SSH (проверки защиты от потери доступа и откат)${PLAIN}")"
        echo -e "$(localized_text "${GREEN}  2. 用户密钥登录模式${PLAIN}         ${YELLOW}(添加公钥 / 切换密钥或密码登录)${PLAIN}" "${GREEN}2. User key login mode (add public key / switch key or password login)${PLAIN}" "${GREEN}2. Режим входа в систему с помощью ключа пользователя (добавление открытого ключа/переключение ключа или вход с паролем)${PLAIN}")"
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${RED}  0. 返回主菜单 / q 返回${PLAIN}" "${RED}0. Main menu / q Back${PLAIN}" "${RED}0. Главное меню / q Назад${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        local choice
        read_trimmed choice "$(localized_text "👉 请选择操作: " "👉 Please select an operation:" "👉 Пожалуйста, выберите операцию:")"
