    docker_daemon_apply_jq "$(localized_text "Docker IPv6 已开启。" "Docker IPv6 enabled." "Docker IPv6 включен.")" --arg cidr "$cidr" '. + {"ipv6":true,"fixed-cidr-v6":$cidr}'
