        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "${GREEN}  1. $(localized_text "安装 / 更新 Docker" "Install / update Docker" "Установить / обновить Docker")${PLAIN}"
        echo -e "${GREEN}  2. $(localized_text "查看 Docker 全局状态" "View Docker overview" "Обзор Docker")${PLAIN}"
