    echo -e "$(localized_text "${YELLOW}CPU 核心 :${PLAIN} $(nproc) 核心" "${YELLOW}CPU core:${PLAIN} $(nproc) core" "Ядро ${YELLOW}ЦП: Ядро${PLAIN} $(nproc)")"
    echo -e "------------------------------------------------"
