# ---------------------------------------------------------
# Module: server_maintenance.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Port process release and server reboot workflows.

func_port_kill() {
    while true; do
        clear
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${BOLD}🔍 网络端口占用排查与进程释放${PLAIN}" "${BOLD}🔍 Network port occupancy check and process release${PLAIN}" "${BOLD}🔍 Проверка занятости сетевого порта и освобождение процесса${PLAIN}")"
        echo -e "${CYAN}================================================${PLAIN}"
        echo -e "$(localized_text "${YELLOW}当前系统中正在监听的活动端口列表：${PLAIN}" "${YELLOW}List of active ports currently being listened to in the system:${PLAIN}" "${YELLOW}Список активных портов, которые в данный момент прослушиваются в системе:${PLAIN}")"
        echo -e "------------------------------------------------"
        printf "%-10s %-15s %-20s\n" "$(localized_text "协议" "agreement" "соглашение")" "$(localized_text "端口" "port" "порт")" "$(localized_text "关联进程 (PID)" "Associated Process (PID)" "Связанный процесс (PID)")"
        
        ss -tulnp | grep -E 'LISTEN|UNCONN' | while read -r line; do
            local proto=$(echo "$line" | awk '{print $1}')
            local port=$(echo "$line" | awk '{print $5}' | awk -F: '{print $NF}')
            local pid=$(echo "$line" | sed -n 's/.*pid=\([0-9]*\).*/\1/p')
            local proc=$(echo "$line" | sed -n 's/.*users:(("\([^"]*\)".*/\1/p')
            
            local proc_info=""
            if [[ -z "$proc" || -z "$pid" ]]; then
                proc_info="$(localized_text "系统底层 / 无权限读取" "System bottom layer / no permission to read" "Нижний уровень системы / нет разрешения на чтение")"
            else
                proc_info="$proc (PID: $pid)"
            fi
            printf "%-10s %-15s %-20s\n" "$proto" "$port" "$proc_info"
        done | sort -n -k2 | uniq
        
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${GREEN}👉 指南：找到您想释放的冲突端口，输入它即可强杀对应进程。${PLAIN}" "${GREEN}👉 Guide: Find the conflicting port you want to release, enter it to kill the corresponding process.${PLAIN}" "${GREEN}👉 Руководство: Найдите конфликтующий порт, который вы хотите освободить, введите его, чтобы завершить соответствующий процесс.${PLAIN}")"
        echo -e "$(localized_text "${RED}⚠️ 高危：请勿随意终止 sshd (通常为 22) 的端口，否则会断网失联！${PLAIN}" "${RED}⚠️ High risk: Do not terminate the port of sshd (usually 22) at will, otherwise the network will be disconnected!${PLAIN}" "${RED}⚠️ Высокий риск: не отключайте порт sshd (обычно 22) по своему желанию, иначе сеть будет отключена!${PLAIN}")"
        echo -e "------------------------------------------------"
        
        local p_choice
        read_trimmed p_choice "$(localized_text "❓ 请输入要强杀释放的端口号 (输入 0 返回主菜单): " "❓ Please enter the port number to be released (enter 0 to return to the main menu):" "❓ Введите номер порта, который нужно освободить (введите 0, чтобы вернуться в главное меню):")"
        
        if [[ "$p_choice" == "0" ]]; then break; fi
        
        if is_valid_port "$p_choice"; then
            local ssh_match
            ssh_match=$(ss -tulnp 2>/dev/null | awk -v port="$p_choice" '$5 ~ ":" port "$" && $0 ~ /(sshd|ssh)/ {print}')
            if [[ -n "$ssh_match" || "$p_choice" == "22" ]]; then
                echo -e "$(localized_text "${RED}❌ 检测到你选择的是 SSH 相关端口或默认 SSH 端口，为避免失联，已拒绝强杀。${PLAIN}" "${RED}❌ Detected that you have selected the SSH related port or the default SSH port. To avoid losing connection, the forced kill has been refused.${PLAIN}" "${RED}❌ Обнаружено, что вы выбрали порт, связанный с SSH, или порт по умолчанию SSH. Во избежание потери соединения в принудительном удалении было отказано.${PLAIN}")"
                sleep 2
                continue
            fi
            confirm_danger "$(localized_text "强杀占用端口 ${p_choice} 的进程" "Forcefully kill the process occupying port ${p_choice}" "Принудительно завершить процесс, занимающий порт ${p_choice}.")" "$(localized_text "会对 TCP/UDP ${p_choice} 占用进程发送 SIGKILL，相关服务会立即中断。" "SIGKILL will be sent to the TCP/UDP ${p_choice} occupied process, and the related services will be interrupted immediately." "SIGKILL будет отправлен занятому процессу TCP/UDP ${p_choice}, и соответствующие службы будут немедленно прерваны.")" "$(localized_text "如果杀错服务，需要手动重启对应 systemd 服务或容器。" "If you kill the wrong service, you need to manually restart the corresponding systemd service or container." "Если вы уничтожили не ту службу, вам необходимо вручную перезапустить соответствующую службу или контейнер systemd.")" || {
                echo -e "$(localized_text "${BLUE}已取消强杀操作。${PLAIN}" "${BLUE}The forced kill operation has been canceled.${PLAIN}" "${BLUE}Операция принудительного уничтожения отменена.${PLAIN}")"
                sleep 1
                continue
            }
            echo -e "$(localized_text "${CYAN}▶ 正在调用底层系统命令强杀端口 $p_choice ...${PLAIN}" "${CYAN}▶ Calling the underlying system command to kill the port $p_choice...${PLAIN}" "${CYAN}▶ Вызов базовой системной команды для закрытия порта $p_choice...${PLAIN}")"
            
            # [依赖前置检查]: 确保存在 fuser 工具
            if ! command -v fuser >/dev/null 2>&1; then
                install_pkg psmisc
            fi
            
            # [极简实现]: 一行代码杀掉占用该 TCP/UDP 端口的所有进程
            if fuser -k -9 -n tcp "$p_choice" >/dev/null 2>&1 || fuser -k -9 -n udp "$p_choice" >/dev/null 2>&1; then
                echo -e "$(localized_text "${GREEN}✅ 目标进程已被系统底层强制回收 (SIGKILL)。端口已释放！${PLAIN}" "${GREEN}✅ The target process has been forcibly recycled (SIGKILL) by the bottom layer of the system. The port has been released!${PLAIN}" "${GREEN}✅ Целевой процесс был принудительно перезапущен (SIGKILL) нижним уровнем системы. Порт выпущен!${PLAIN}")"
            else
                echo -e "$(localized_text "${BLUE}ℹ️ 未发现任何可被终止的进程占用该端口，或权限不足。${PLAIN}" "${BLUE}ℹ️ No process that can be terminated is found occupying this port, or the permissions are insufficient.${PLAIN}" "${BLUE}ℹ️ Не обнаружено процессов, которые можно завершить, занимающих этот порт, или разрешения недостаточны.${PLAIN}")"
            fi
            sleep 2
        else
            echo -e "$(localized_text "${RED}❌ 输入无效！请输入纯数字端口号。${PLAIN}" "${RED}❌ Invalid input! Please enter a purely numeric port number.${PLAIN}" "${RED}❌ Неверный ввод! Пожалуйста, введите чисто цифровой номер порта.${PLAIN}")"
            sleep 1
        fi
    done
}

func_reboot_server() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🔁 重启服务器${PLAIN}" "${BOLD}🔁 Restart the server${PLAIN}" "${BOLD}🔁 Перезагрузите сервер${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"
    confirm_danger "$(localized_text "立即重启服务器" "Restart the server now" "Перезагрузите сервер сейчас")" "$(localized_text "当前 SSH 会话会断开，所有运行中的服务会短暂中断。" "The current SSH session will be disconnected and all running services will be briefly interrupted." "Текущий сеанс SSH будет отключен, и все работающие службы будут ненадолго прерваны.")" "$(localized_text "请确认云厂商控制台可用，并确保关键配置已经保存。" "Please confirm that the cloud provider console is available and ensure that key configurations have been saved." "Убедитесь, что консоль облачного провайдера доступна, и убедитесь, что ключевые конфигурации сохранены.")" || {
        echo -e "$(localized_text "${BLUE}已取消重启操作。${PLAIN}" "${BLUE}The restart operation has been canceled.${PLAIN}" "${BLUE}Операция перезапуска отменена.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
        return
    }
    reboot
}
# ---------------------------------------------------------
# 19. 脚本热更新
# ---------------------------------------------------------

# ---------------------------------------------------------
# Module: updater.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Script update cache, version comparison, notice, and hot-update workflows.

fetch_latest_script_version() {
    local line version
    if command -v curl >/dev/null 2>&1; then
        line=$(curl -fsSL --connect-timeout 4 --max-time 10 "$UPDATE_URL" 2>/dev/null | grep -m1 '^SCRIPT_VERSION=' || true)
    elif command -v wget >/dev/null 2>&1; then
        line=$(wget -q --timeout=10 --tries=1 -O - "$UPDATE_URL" 2>/dev/null | grep -m1 '^SCRIPT_VERSION=' || true)
    else
        return 1
    fi
    [[ -n "$line" ]] || return 1
    version="${line#SCRIPT_VERSION=}"
    version="${version%\"}"
    version="${version#\"}"
    [[ -n "$version" ]] || return 1
    printf '%s\n' "$version"
}

fetch_latest_script_sha256() {
    local checksum
    if command -v curl >/dev/null 2>&1; then
        checksum=$(curl -fsSL --connect-timeout 4 --max-time 10 "$UPDATE_SHA256_URL" 2>/dev/null | awk 'NR == 1 {print $1}' || true)
    elif command -v wget >/dev/null 2>&1; then
        checksum=$(wget -q --timeout=10 --tries=1 -O - "$UPDATE_SHA256_URL" 2>/dev/null | awk 'NR == 1 {print $1}' || true)
    else
        return 1
    fi
    checksum=$(printf '%s' "$checksum" | tr 'A-F' 'a-f')
    [[ "$checksum" =~ ^[0-9a-f]{64}$ ]] || return 1
    printf '%s\n' "$checksum"
}

current_script_sha256() {
    local current_file
    current_file="${VPSO_CURRENT_SCRIPT_PATH:-$(readlink -f "$0" 2>/dev/null || true)}"
    if [[ ! -f "$current_file" ]] || ! is_vps_optimize_generated_script "$current_file"; then
        current_file="${VPSO_SHORTCUT_PATH:-/usr/local/bin/cy}"
    fi
    [[ -f "$current_file" ]] || return 1
    command -v sha256sum >/dev/null 2>&1 || return 1
    sha256sum "$current_file" 2>/dev/null | awk 'NR == 1 {print $1}'
}

version_is_newer() {
    local latest="${1#v}"
    local current="${2#v}"
    local l1=0 l2=0 l3=0 c1=0 c2=0 c3=0
    IFS='.' read -r l1 l2 l3 <<< "$latest"
    IFS='.' read -r c1 c2 c3 <<< "$current"
    l1=${l1:-0}; l2=${l2:-0}; l3=${l3:-0}
    c1=${c1:-0}; c2=${c2:-0}; c3=${c3:-0}
    [[ "$l1$l2$l3$c1$c2$c3" =~ ^[0-9]+$ ]] || return 1
    (( 10#$l1 > 10#$c1 )) && return 0
    (( 10#$l1 < 10#$c1 )) && return 1
    (( 10#$l2 > 10#$c2 )) && return 0
    (( 10#$l2 < 10#$c2 )) && return 1
    (( 10#$l3 > 10#$c3 ))
}

script_update_cache_is_fresh() {
    local now mtime
    [[ -f "$SCRIPT_UPDATE_CACHE" ]] || return 1
    now=$(date +%s 2>/dev/null || echo 0)
    mtime=$(stat -c %Y "$SCRIPT_UPDATE_CACHE" 2>/dev/null || echo 0)
    [[ "$now" =~ ^[0-9]+$ && "$mtime" =~ ^[0-9]+$ ]] || return 1
    (( now > mtime && now - mtime < 43200 ))
}

read_script_update_cache_field() {
    local key="$1"
    grep -m1 "^${key}=" "$SCRIPT_UPDATE_CACHE" 2>/dev/null | cut -d= -f2-
}

write_script_update_cache() {
    local status="$1"
    local latest="$2"
    local latest_sha256="$3"
    local message="$4"
    local cache_dir
    cache_dir=$(dirname "$SCRIPT_UPDATE_CACHE")
    mkdir -p "$cache_dir" 2>/dev/null || return 0
    {
        echo "status=${status}"
        echo "latest=${latest}"
        echo "latest_sha256=${latest_sha256}"
        echo "message=${message}"
        echo "checked_at=$(date -Is 2>/dev/null || date)"
    } > "$SCRIPT_UPDATE_CACHE" 2>/dev/null || true
}

check_script_update_status() {
    local mode="${1:-auto}"
    local status latest latest_sha256 current_sha256 message
    current_sha256=$(current_script_sha256 2>/dev/null || true)
    if [[ "$mode" != "force" ]] && script_update_cache_is_fresh; then
        status=$(read_script_update_cache_field status)
        latest=$(read_script_update_cache_field latest)
        latest_sha256=$(read_script_update_cache_field latest_sha256)
        if [[ "$latest_sha256" =~ ^[0-9a-f]{64}$ && -n "$latest" && "$latest" != "unknown" ]]; then
            if version_is_newer "$latest" "$SCRIPT_VERSION"; then
                status="available"
            elif [[ -n "$current_sha256" && -n "$latest_sha256" && "$current_sha256" != "$latest_sha256" ]]; then
                status="available"
            else
                status="current"
            fi
            printf '%s|%s\n' "${status:-unknown}" "${latest:-unknown}"
            return 0
        fi
    fi

    if latest=$(fetch_latest_script_version) && latest_sha256=$(fetch_latest_script_sha256); then
        if version_is_newer "$latest" "$SCRIPT_VERSION"; then
            status="available"
            message="$(localized_text "发现新版本 ${latest}" "Found new version ${latest}" "Нашёл новую версию ${latest}")"
        elif [[ -n "$current_sha256" && "$current_sha256" != "$latest_sha256" ]]; then
            status="available"
            message="$(localized_text "检测到同版本内容更新" "Content updates of the same version detected" "Обнаружены обновления контента той же версии")"
        else
            status="current"
            message="$(localized_text "当前脚本内容已是最新" "The current script content is up to date" "Текущее содержимое сценария актуально.")"
        fi
        write_script_update_cache "$status" "$latest" "$latest_sha256" "$message"
        printf '%s|%s\n' "$status" "$latest"
        return 0
    fi

    write_script_update_cache "error" "unknown" "unknown" "$(localized_text "无法检查更新" "Unable to check for updates" "Невозможно проверить наличие обновлений")"
    printf 'error|unknown\n'
}

print_auto_update_notice() {
    local result status latest
    result=$(check_script_update_status "auto" 2>/dev/null || true)
    status="${result%%|*}"
    latest="${result#*|}"
    case "$status" in
        available)
            if [[ "$VPSO_LANGUAGE" == "ru" && "$latest" == "$SCRIPT_VERSION" ]]; then
                echo -e " ${BOLD}${YELLOW}Обновление:${PLAIN} содержимое версии ${CYAN}${latest}${PLAIN} изменилось; введите ${YELLOW}u${PLAIN}, чтобы обновить скрипт."
            elif [[ "$VPSO_LANGUAGE" == "ru" ]]; then
                echo -e " ${BOLD}${YELLOW}Обновление:${PLAIN} доступна версия ${CYAN}${latest}${PLAIN}; введите ${YELLOW}u${PLAIN}, чтобы обновить скрипт."
            elif [[ "$VPSO_LANGUAGE" == "en" && "$latest" == "$SCRIPT_VERSION" ]]; then
                echo -e " ${BOLD}${YELLOW}Update:${PLAIN} Content changed for ${CYAN}${latest}${PLAIN}; enter ${YELLOW}u${PLAIN} to update."
            elif [[ "$VPSO_LANGUAGE" == "en" ]]; then
                echo -e " ${BOLD}${YELLOW}Update:${PLAIN} ${CYAN}${latest}${PLAIN} is available; enter ${YELLOW}u${PLAIN} to update."
            elif [[ "$latest" == "$SCRIPT_VERSION" ]]; then
                echo -e "$(localized_text " ${BOLD}${YELLOW}更新提示:${PLAIN} 检测到 ${CYAN}${latest}${PLAIN} 的内容更新，输入 ${YELLOW}u${PLAIN} 可更新当前脚本。" "${BOLD}${YELLOW}Update prompt:${PLAIN} detects the content update of ${CYAN}${latest}${PLAIN}. Enter ${YELLOW}U${PLAIN} to update the current script." "Запрос на обновление ${BOLD}${YELLOW}:${PLAIN} обнаруживает обновление содержимого ${CYAN}${latest}${PLAIN}. Введите ${YELLOW}u${PLAIN}, чтобы обновить текущий скрипт.")"
            else
                echo -e "$(localized_text " ${BOLD}${YELLOW}更新提示:${PLAIN} 检测到 ${CYAN}${latest}${PLAIN}，输入 ${YELLOW}u${PLAIN} 可更新当前脚本。" "${BOLD}${YELLOW}Update prompt:${PLAIN} detects ${CYAN}${latest}${PLAIN}. Enter ${YELLOW}U${PLAIN} to update the current script." "${BOLD}${YELLOW}Приглашение к обновлению:${PLAIN} обнаруживает ${CYAN}${latest}${PLAIN}. Введите ${YELLOW}u${PLAIN}, чтобы обновить текущий скрипт.")"
            fi
            ;;
        current)
            localized_echo \
                " ${BLUE}更新状态:${PLAIN} 当前 ${SCRIPT_VERSION}，脚本内容已是最新。" \
                " ${BLUE}Update status:${PLAIN} ${SCRIPT_VERSION} is current." \
                " ${BLUE}Статус обновления:${PLAIN} установлена актуальная версия ${SCRIPT_VERSION}."
            ;;
    esac
}

func_update_script() {
    clear
    local tmp_file
    tmp_file=$(mktemp /tmp/cy_update.XXXXXX.sh) || {
        echo -e "$(localized_text "${RED}❌ 临时文件创建失败，更新已取消。${PLAIN}" "${RED}❌ Temporary file creation failed, update canceled.${PLAIN}" "${RED}❌ Не удалось создать временный файл, обновление отменено.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
        return 1
    }
    echo -e "$(localized_text "${CYAN}👉 正在从 GitHub 源地址拉取最新版本...${PLAIN}" "${CYAN}👉 Pulling the latest version from the GitHub source address...${PLAIN}" "${CYAN}👉 Получение последней версии с исходного адреса GitHub...${PLAIN}")"
    if download_verified_update_script "$tmp_file" \
        && grep -q "func_sni_stack_quick_menu" "$tmp_file" 2>/dev/null \
        && grep -q "main_menu" "$tmp_file" 2>/dev/null \
        && ! grep -Eq '^[[:space:]]*(source|\.)[[:space:]]+.*src/' "$tmp_file" 2>/dev/null \
        && copy_shortcut_candidate "$tmp_file" /usr/local/bin/cy "$(localized_text "已验证更新脚本" "Verified update script" "Проверенный скрипт обновления")"; then
        rm -f "$tmp_file" "$SCRIPT_UPDATE_CACHE"
        echo -e "$(localized_text "${GREEN}✅ 更新已安装，正在重新打开面板...${PLAIN}" "${GREEN}✅ Update installed. Reopening the panel...${PLAIN}" "${GREEN}✅ Обновление установлено. Панель запускается заново...${PLAIN}")"
        sleep 1
        release_vpso_session_lock
        exec bash /usr/local/bin/cy
    else
        rm -f "$tmp_file"
        echo -e "$(localized_text "${RED}❌ 更新失败：下载、脚本标识、语法或 sha256 校验未全部通过。${PLAIN}" "${RED}❌ Update failed: The download, script identifier, syntax, or sha256 check did not all pass.${PLAIN}" "${RED}❌ Обновление не выполнено: проверка загрузки, идентификатора сценария, синтаксиса или sha256 не прошла успешно.${PLAIN}")"
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
    fi
}

# ---------------------------------------------------------
# 20. 一键运维预检
# ---------------------------------------------------------

# ---------------------------------------------------------
# Module: preflight.sh
# ---------------------------------------------------------
# shellcheck shell=bash
# Deployment preflight checks and issue diagnostic bundle generation.

preflight_install_missing_commands() {
    local missing=("$@")
    local pkgs=()
    local cmd

    for cmd in "${missing[@]}"; do
        case "$cmd" in
            curl) pkgs+=("curl") ;;
            wget) pkgs+=("wget") ;;
            sudo) pkgs+=("sudo") ;;
            ss)
                if is_debian; then
                    pkgs+=("iproute2")
                elif is_redhat; then
                    pkgs+=("iproute")
                fi
                ;;
        esac
    done

    if [[ ${#pkgs[@]} -eq 0 ]]; then
        return 0
    fi

    echo -e "$(localized_text "${CYAN}▶ 正在安装缺失基础命令: ${missing[*]}${PLAIN}" "${CYAN}▶ Installing missing basic command: ${missing[*]}${PLAIN}" "${CYAN}▶ Установка отсутствующей базовой команды: ${missing[*]}${PLAIN}")"
    install_pkg "${pkgs[@]}"
}

preflight_missing_minimal_compat_items() {
    local missing=()
    local cmd svc
    local commands=(sudo curl wget ss ip getent tar gzip openssl jq awk sed grep pgrep journalctl timedatectl git nano lsof)
    local services=()

    for cmd in "${commands[@]}"; do
        command -v "$cmd" >/dev/null 2>&1 || missing+=("cmd:$cmd")
    done

    if is_debian; then
        services=(cron dbus chrony)
    elif is_redhat; then
        services=(crond dbus chronyd)
    fi

    for svc in "${services[@]}"; do
        systemctl list-unit-files "${svc}.service" --no-legend 2>/dev/null | awk 'NF {found=1} END {exit found ? 0 : 1}' || missing+=("svc:$svc")
    done

    if [[ ${#missing[@]} -gt 0 ]]; then
        printf '%s\n' "${missing[@]}"
    fi
}

preflight_enable_ntp() {
    local ntp_sync
    echo -e "$(localized_text "${CYAN}▶ 正在尝试开启系统 NTP 时间同步...${PLAIN}" "${CYAN}▶ Trying to enable system NTP time synchronization...${PLAIN}" "${CYAN}▶ Попытка включить системную синхронизацию времени NTP...${PLAIN}")"

    if is_debian; then
        install_pkg chrony
    elif is_redhat; then
        install_pkg chrony
    fi

    timedatectl set-ntp true >/dev/null 2>&1 || true
    systemctl enable --now chrony >/dev/null 2>&1 || true
    systemctl enable --now chronyd >/dev/null 2>&1 || true

    if command -v chronyc >/dev/null 2>&1; then
        chronyc -a 'burst 4/4' >/dev/null 2>&1 || true
        chronyc -a makestep >/dev/null 2>&1 || true
    else
        systemctl enable --now systemd-timesyncd >/dev/null 2>&1 || true
    fi

    sleep 2
    ntp_sync=$(timedatectl show -p NTPSynchronized --value 2>/dev/null)
    if [[ "$ntp_sync" == "yes" ]]; then
        echo -e "$(localized_text "${GREEN}✅ NTP 时间同步已恢复。${PLAIN}" "${GREEN}✅ NTP time synchronization has been restored.${PLAIN}" "${GREEN}✅ Синхронизация времени NTP восстановлена.${PLAIN}")"
    else
        echo -e "$(localized_text "${YELLOW}⚠️ NTP 仍未同步，下面是诊断信息：${PLAIN}" "${YELLOW}⚠️ NTP is still not synchronized, the following is the diagnostic information:${PLAIN}" "${YELLOW}⚠️ NTP по-прежнему не синхронизирован, следующая диагностическая информация:${PLAIN}")"
        timedatectl status 2>/dev/null || true
        chronyc tracking 2>/dev/null || true
        chronyc sources -v 2>/dev/null || true
        journalctl -u chrony -u chronyd -u systemd-timesyncd -n 20 --no-pager 2>/dev/null || true
    fi
}

func_preflight_check() {
    clear
    echo -e "${CYAN}================================================${PLAIN}"
    echo -e "$(localized_text "${BOLD}🧪 一键运维预检 (网络/系统/资源/包管理/精简系统兼容)${PLAIN}" "${BOLD}🧪 One-click operation and maintenance preflight check (network/system/resources/package management/simplified system compatibility)${PLAIN}" "${BOLD}🧪 Предварительная проверка работы и обслуживания в один клик (сеть/система/ресурсы/управление пакетами/упрощенная совместимость системы)${PLAIN}")"
    echo -e "${CYAN}================================================${PLAIN}"

    local ok_count=0
    local warn_count=0
    local err_count=0

    echo -e "$(localized_text "${YELLOW}▶ [1/9] 检查系统运行状态...${PLAIN}" "${YELLOW}▶ [1/9] Check the system running status...${PLAIN}" "${YELLOW}▶ [1/9] Проверка рабочего состояния системы...${PLAIN}")"
    local sys_state
    sys_state=$(systemctl is-system-running 2>/dev/null)
    sys_state=${sys_state:-unknown}
    if [[ "$sys_state" == "running" ]]; then
        echo -e "$(localized_text "${GREEN}✅ systemd 状态正常: $sys_state${PLAIN}" "${GREEN}✅ systemd Normal status: $sys_state${PLAIN}" "${GREEN}✅ systemd Нормальный статус: $sys_state${PLAIN}")"
        ((ok_count++))
    elif [[ "$sys_state" == "degraded" ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ systemd 状态降级: $sys_state${PLAIN}" "${YELLOW}⚠️ systemd status downgrade: $sys_state${PLAIN}" "${YELLOW}⚠️ Понижение статуса systemd: $sys_state${PLAIN}")"
        systemctl --failed --no-legend --no-pager 2>/dev/null | awk 'NF {print "   - " $1 " (" $2 ")"}' | head -n 8
        ((warn_count++))
    else
        echo -e "$(localized_text "${RED}❌ systemd 状态异常: $sys_state${PLAIN}" "${RED}❌ systemd Abnormal status: $sys_state${PLAIN}" "${RED}❌ systemd Ненормальное состояние: $sys_state${PLAIN}")"
        ((err_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [2/9] 检查公网连通性...${PLAIN}" "${YELLOW}▶ [2/9] Check public connectivity...${PLAIN}" "${YELLOW}▶ [2/9] Проверка подключения к публичной сети...${PLAIN}")"
    local ipv4
    ipv4=$(curl -s4 --max-time 3 icanhazip.com 2>/dev/null)
    if [[ -n "$ipv4" ]]; then
        echo -e "$(localized_text "${GREEN}✅ IPv4 连通正常: ${ipv4}${PLAIN}" "${GREEN}✅ IPv4 Connected normally: ${ipv4}${PLAIN}" "${GREEN}✅ IPv4 Подключено нормально: ${ipv4}${PLAIN}")"
        ((ok_count++))
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 未检测到公网 IPv4，可能为纯 IPv6 或网络受限${PLAIN}" "${YELLOW}⚠️ The public IPv4 is not detected, it may be pure IPv6 or network restricted${PLAIN}" "${YELLOW}⚠️ публичную сеть IPv4 не обнаружена, это может быть чистая IPv6 или ограниченная сеть.${PLAIN}")"
        ((warn_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [3/9] 检查 DNS 解析能力...${PLAIN}" "${YELLOW}▶ [3/9] Check the resolution ability of DNS...${PLAIN}" "${YELLOW}▶ [3/9] Проверьте разрешающую способность DNS...${PLAIN}")"
    if getent ahosts raw.githubusercontent.com >/dev/null 2>&1; then
        echo -e "$(localized_text "${GREEN}✅ DNS 解析正常 (raw.githubusercontent.com)${PLAIN}" "${GREEN}✅ DNS parses normally (raw.githubusercontent.com)${PLAIN}" "${GREEN}✅ DNS нормально анализирует (raw.githubusercontent.com)${PLAIN}")"
        ((ok_count++))
    else
        echo -e "$(localized_text "${RED}❌ DNS 解析失败，后续远程脚本可能无法下载${PLAIN}" "${RED}❌ DNS parsing failed, subsequent remote scripts may not be able to download${PLAIN}" "${RED}❌ Не удалось выполнить синтаксический анализ DNS, последующие удаленные сценарии не смогут загрузить.${PLAIN}")"
        ((err_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [4/9] 检查时间同步状态...${PLAIN}" "${YELLOW}▶ [4/9] Check time synchronization status...${PLAIN}" "${YELLOW}▶ [4/9] Проверка состояния синхронизации времени...${PLAIN}")"
    local ntp_sync
    local can_fix_ntp=false
    ntp_sync=$(timedatectl show -p NTPSynchronized --value 2>/dev/null)
    if [[ "$ntp_sync" == "yes" ]]; then
        echo -e "$(localized_text "${GREEN}✅ NTP 时间同步正常${PLAIN}" "${GREEN}✅ NTP time synchronization is normal${PLAIN}" "${GREEN}✅ Синхронизация времени NTP в норме${PLAIN}")"
        ((ok_count++))
    else
        echo -e "$(localized_text "${YELLOW}⚠️ NTP 未同步，可能影响证书签发与仓库校验${PLAIN}" "${YELLOW}⚠️ NTP is not synchronized, which may affect certificate issuance and warehouse verification${PLAIN}" "${YELLOW}⚠️ NTP не синхронизирован, что может повлиять на выдачу сертификата и проверку склада${PLAIN}")"
        can_fix_ntp=true
        ((warn_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [5/9] 检查磁盘空间...${PLAIN}" "${YELLOW}▶ [5/9] Check disk space...${PLAIN}" "${YELLOW}▶ [5/9] Проверка места на диске...${PLAIN}")"
    local root_use
    root_use=$(df -P / | awk 'NR==2 {gsub("%", "", $5); print $5}')
    if [[ -n "$root_use" && "$root_use" -lt 80 ]]; then
        echo -e "$(localized_text "${GREEN}✅ 根分区使用率健康: ${root_use}%${PLAIN}" "${GREEN}✅ Root partition usage is healthy: ${root_use}%${PLAIN}" "${GREEN}✅ Корневой раздел используется нормально: ${root_use}%${PLAIN}")"
        ((ok_count++))
    elif [[ -n "$root_use" && "$root_use" -lt 90 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 根分区使用率偏高: ${root_use}%${PLAIN}" "${YELLOW}⚠️ The root partition usage is high: ${root_use}%${PLAIN}" "${YELLOW}⚠️ Высокое использование корневого раздела: ${root_use}%${PLAIN}")"
        ((warn_count++))
    else
        echo -e "$(localized_text "${RED}❌ 根分区使用率危险: ${root_use:-未知}%${PLAIN}" "${RED}❌ Dangerous root partition usage: ${root_use:-未知}%${PLAIN}" "${RED}❌ Опасное использование корневого раздела: ${root_use:-未知}%${PLAIN}")"
        ((err_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [6/9] 检查可用内存...${PLAIN}" "${YELLOW}▶ [6/9] Check available memory...${PLAIN}" "${YELLOW}▶ [6/9] Проверка доступной памяти...${PLAIN}")"
    local mem_avail
    mem_avail=$(free -m | awk '/^Mem:/ {print $7}')
    [[ -z "$mem_avail" ]] && mem_avail=$(free -m | awk '/^Mem:/ {print $4}')
    if [[ -n "$mem_avail" && "$mem_avail" -ge 300 ]]; then
        echo -e "$(localized_text "${GREEN}✅ 可用内存充足: ${mem_avail}MB${PLAIN}" "${GREEN}✅ Sufficient available memory: ${mem_avail}MB${PLAIN}" "${GREEN}✅ Достаточно доступной памяти: ${mem_avail}MB${PLAIN}")"
        ((ok_count++))
    elif [[ -n "$mem_avail" && "$mem_avail" -ge 150 ]]; then
        echo -e "$(localized_text "${YELLOW}⚠️ 可用内存偏低: ${mem_avail}MB${PLAIN}" "${YELLOW}⚠️ Available memory is low: ${mem_avail}MB${PLAIN}" "${YELLOW}⚠️ Недостаточно доступной памяти: ${mem_avail}MB${PLAIN}")"
        ((warn_count++))
    else
        echo -e "$(localized_text "${RED}❌ 可用内存过低: ${mem_avail:-未知}MB${PLAIN}" "${RED}❌ Available memory is too low: ${mem_avail:-未知}MB${PLAIN}" "${RED}❌ Недостаточно доступной памяти: ${mem_avail:-未知}MB${PLAIN}")"
        ((err_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [7/9] 检查包管理器占用...${PLAIN}" "${YELLOW}▶ [7/9] Check package manager usage...${PLAIN}" "${YELLOW}▶ [7/9] Проверка использования менеджера пакетов...${PLAIN}")"
    local pkg_busy=false
    if is_debian; then
        pgrep -x apt >/dev/null 2>&1 && pkg_busy=true
        pgrep -x apt-get >/dev/null 2>&1 && pkg_busy=true
        pgrep -x dpkg >/dev/null 2>&1 && pkg_busy=true
    elif is_redhat; then
        pgrep -x yum >/dev/null 2>&1 && pkg_busy=true
        pgrep -x dnf >/dev/null 2>&1 && pkg_busy=true
        pgrep -x rpm >/dev/null 2>&1 && pkg_busy=true
    fi

    if $pkg_busy; then
        echo -e "$(localized_text "${YELLOW}⚠️ 检测到包管理器正在运行，建议稍后再安装软件${PLAIN}" "${YELLOW}⚠️ Detected that the package manager is running. It is recommended to install the software later.${PLAIN}" "${YELLOW}⚠️ Обнаружено, что менеджер пакетов запущен. Программное обеспечение рекомендуется установить позже.${PLAIN}")"
        ((warn_count++))
    else
        echo -e "$(localized_text "${GREEN}✅ 包管理器空闲，可安全执行安装任务${PLAIN}" "${GREEN}✅ The package manager is idle and can safely perform installation tasks${PLAIN}" "${GREEN}✅ Менеджер пакетов простаивает и может безопасно выполнять задачи установки${PLAIN}")"
        ((ok_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [8/9] 检查关键命令可用性...${PLAIN}" "${YELLOW}▶ [8/9] Check key command availability...${PLAIN}" "${YELLOW}▶ [8/9] Проверка доступности клавишных команд...${PLAIN}")"
    local cmd_miss=()
    command -v curl >/dev/null 2>&1 || cmd_miss+=("curl")
    command -v wget >/dev/null 2>&1 || cmd_miss+=("wget")
    command -v sudo >/dev/null 2>&1 || cmd_miss+=("sudo")
    command -v ss >/dev/null 2>&1 || cmd_miss+=("ss")
    if [[ ${#cmd_miss[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${GREEN}✅ 关键命令齐全${PLAIN}" "${GREEN}✅ Complete key commands${PLAIN}" "${GREEN}✅ Полные ключевые команды${PLAIN}")"
        ((ok_count++))
    else
        echo -e "$(localized_text "${RED}❌ 缺少关键命令: ${cmd_miss[*]}${PLAIN}" "${RED}❌ Missing key command: ${cmd_miss[*]}${PLAIN}" "${RED}❌ Отсутствует ключевая команда: ${cmd_miss[*]}.${PLAIN}")"
        ((err_count++))
    fi

    echo -e "$(localized_text "${YELLOW}▶ [9/9] 检查精简系统兼容组件...${PLAIN}" "${YELLOW}▶ [9/9] Check the streamlined system compatible components...${PLAIN}" "${YELLOW}▶ [9/9] Проверьте компоненты, совместимые с оптимизированной системой...${PLAIN}")"
    local minimal_miss=()
    mapfile -t minimal_miss < <(preflight_missing_minimal_compat_items)
    if [[ ${#minimal_miss[@]} -eq 0 ]]; then
        echo -e "$(localized_text "${GREEN}✅ 精简系统兼容组件齐全${PLAIN}" "${GREEN}✅ Streamlined system with complete compatible components${PLAIN}" "${GREEN}✅ Оптимизированная система с полностью совместимыми компонентами${PLAIN}")"
        ((ok_count++))
    else
        echo -e "$(localized_text "${YELLOW}⚠️ 检测到精简系统缺少组件/服务:${PLAIN}" "${YELLOW}⚠️ Detected that the streamlined system is missing components/services:${PLAIN}" "${YELLOW}⚠️ Обнаружено, что в оптимизированной системе отсутствуют компоненты/службы:.${PLAIN}")"
        printf '  - %s\n' "${minimal_miss[@]}"
        ((warn_count++))
    fi

    echo -e "------------------------------------------------"
    echo -e "$(localized_text "${CYAN}📌 预检汇总: ${GREEN}${ok_count} 正常${PLAIN} / ${YELLOW}${warn_count} 警告${PLAIN} / ${RED}${err_count} 异常${PLAIN}" "${CYAN}📌 preflight check summary: ${ok_count} Normal / ${warn_count} Warning / ${err_count} Abnormal${PLAIN}" "${CYAN}📌 Сводка предварительной проверки: ${ok_count} Нормально / ${warn_count} Предупреждение / ${err_count} Ненормально${PLAIN}")"
    if [[ "$err_count" -gt 0 ]]; then
        echo -e "$(localized_text "${RED}⚠️ 建议先修复异常项，再进行环境部署和系统改造。${PLAIN}" "${RED}⚠️ It is recommended to fix the abnormal items first, and then proceed with environment deployment and system modification.${PLAIN}" "${RED}⚠️ Рекомендуется сначала исправить аномальные элементы, а затем приступить к развертыванию среды и модификации системы.${PLAIN}")"
    elif [[ "$warn_count" -gt 0 ]]; then
        echo -e "$(localized_text "${YELLOW}💡 当前可继续操作，但建议先处理警告项以提升稳定性。${PLAIN}" "${YELLOW}💡 You can currently continue to operate, but it is recommended to deal with the warning items first to improve stability.${PLAIN}" "${YELLOW}💡 В настоящее время вы можете продолжать работу, но рекомендуется сначала разобраться с предупреждающими элементами для повышения стабильности.${PLAIN}")"
    else
        echo -e "$(localized_text "${GREEN}🎉 当前环境健康，可直接进行后续部署。${PLAIN}" "${GREEN}🎉 The current environment is healthy and subsequent deployment can be carried out directly.${PLAIN}" "${GREEN}🎉 Текущая среда работоспособна, и последующее развертывание можно выполнить напрямую.${PLAIN}")"
    fi

    if ! $pkg_busy && { $can_fix_ntp || [[ ${#cmd_miss[@]} -gt 0 ]] || [[ ${#minimal_miss[@]} -gt 0 ]]; }; then
        local rerun_confirm
        echo -e "------------------------------------------------"
        echo -e "$(localized_text "${CYAN}🛠️ 可自动处理的简单问题:${PLAIN}" "${CYAN}🛠️ Simple questions that can be automatically handled:${PLAIN}" "${CYAN}🛠️ Простые вопросы, которые можно обрабатывать автоматически:${PLAIN}")"
        $can_fix_ntp && echo -e "$(localized_text "  - 开启 NTP 时间同步" "- Enable NTP time synchronization" "- Включить синхронизацию времени NTP")"
        [[ ${#cmd_miss[@]} -gt 0 ]] && echo -e "$(localized_text "  - 安装缺失基础命令: ${cmd_miss[*]}" "- Installation missing basic command: ${cmd_miss[*]}" "- При установке отсутствует базовая команда: ${cmd_miss[*]}.")"
        [[ ${#minimal_miss[@]} -gt 0 ]] && echo -e "$(localized_text "  - 补齐精简系统兼容组件" "- Completed streamlined system compatible components" "- Завершены оптимизированные компоненты, совместимые с системой.")"
        if confirm_danger "$(localized_text "自动修复预检问题" "Automatically fix preflight issues" "Автоматически исправить проблемы предварительной проверки")" \
            "$(localized_text "可能安装基础软件包并启用 NTP 时间同步" "may install base packages and enable NTP time synchronization" "может установить базовые пакеты и включить синхронизацию времени NTP")" \
            "$(localized_text "软件包变更需按系统包管理器回退；NTP 可在系统服务中关闭" "revert package changes with the system package manager; disable NTP through the system service" "изменения пакетов отменяются через системный менеджер пакетов; NTP можно отключить в системной службе")"; then
            [[ ${#minimal_miss[@]} -gt 0 ]] && ensure_minimal_system_compat
            $can_fix_ntp && preflight_enable_ntp
            [[ ${#cmd_miss[@]} -gt 0 ]] && preflight_install_missing_commands "${cmd_miss[@]}"
            echo -e "$(localized_text "${GREEN}✅ 简单修复已执行。${PLAIN}" "${GREEN}✅ Simple fix has been performed.${PLAIN}" "${GREEN}Выполнено простое исправление.${PLAIN}")"
            read_trimmed rerun_confirm "$(localized_text "是否立即重新体检？(Y/n): " "Do you want to re-examine immediately? (Y/n):" "Хотите немедленно пройти повторное обследование? (Да/Нет):")"
            if is_yes "$rerun_confirm"; then
                func_preflight_check
                return $?
            fi
        fi
    elif $pkg_busy; then
        echo -e "$(localized_text "${YELLOW}ℹ️ 包管理器正在运行，本次跳过自动安装类修复。${PLAIN}" "${YELLOW}ℹ️ The package manager is running, and the automatic installation repair will be skipped this time.${PLAIN}" "${YELLOW}ℹ️ Менеджер пакетов запущен, и автоматическое восстановление установки на этот раз будет пропущено.${PLAIN}")"
    fi

    if [[ "${VPSO_BEGINNER_FLOW:-0}" != "1" ]]; then
        read -n 1 -s -r -p "$(localized_text "按任意键返回..." "Press any key to return..." "Нажмите любую клавишу, чтобы вернуться...")"
    fi
    if [[ "$err_count" -gt 0 ]]; then
        return 1
    fi
    return 0
}

