normalize_main_choice() {
    local choice
    choice="$(trim_input "$1")"
    choice=$(printf '%s' "$choice" | LC_ALL=C tr '[:upper:]' '[:lower:]')

    case "$choice" in
        proxy) echo "4" ;;
        panel) echo "5" ;;
        ssh) echo "6" ;;
        firewall) echo "8" ;;
        bbr) echo "10" ;;
        docker) echo "11" ;;
        speed) echo "12" ;;
        health) echo "15" ;;
        backup) echo "16" ;;
        u|update|upd) echo "17" ;;
        443) echo "19" ;;
        lang) echo "20" ;;
        *) echo "$choice" ;;
    esac
}

